    fn gcUnkEqPart(self: *Emitter, vt: ValType) anyerror!void {
        switch (vt) {
            .i32 => try self.emit(opOf(.i32, "eq")),
            .i64 => try self.emit(opOf(.i64, "eq")),
            .f64 => try self.emit(.{ .call = self.floatEqSym() }),
            else => try self.emit(.{ .call = "__unk_eq" }),
