    fn gcArrUnique(self: *Emitter, cls: Repr.Elem) anyerror![]const u8 {
        const name = try std.fmt.allocPrint(self.arena(), "__arr_unique_{s}", .{gcClsSuffix(cls)});
        if (!try self.gcHelperOnce(name)) return name;
        const ti = self.gcTyIndex(.{ .arr = cls });
        const at = ValType.def(ti);
        const ev = gcElemVt(cls);
        const P = wat.Builder.param;
        var c: Capture = .{};
        self.open(&c);
        try self.emit(lget("xs"));
        try self.emit(.array_len);
        try self.emit(lset("n"));
        try self.emit(lget("n"));
        try self.emit(.{ .array_new_default = ti });
        try self.emit(lset("out"));
        // for i in 0..n: x = xs[i]; seen = any out[j] == x for j < k
        var outer: Capture = .{};
        self.open(&outer);
        try self.emit(lget("i"));
        try self.emit(lget("n"));
        try self.emit(opOf(.i32, "ge_u"));
        try self.emit(.{ .br_if = "brk" });
        try self.emit(lget("xs"));
        try self.emit(lget("i"));
        try self.emit(.{ .array_get = .{ .ty = ti } });
        try self.emit(lset("x"));
        try self.emit(zero);
        try self.emit(lset("j"));
        // The inner search, as a block of its own: `$found` when seen.
        var inner: Capture = .{};
        self.open(&inner);
        try self.emit(lget("j"));
        try self.emit(lget("k"));
        try self.emit(opOf(.i32, "ge_u"));
        try self.emit(.{ .br_if = "miss" });
        try self.emit(lget("out"));
        try self.emit(lget("j"));
        try self.emit(.{ .array_get = .{ .ty = ti } });
        try self.emit(lget("x"));
        switch (cls) {
            .i32 => try self.emit(opOf(.i32, "eq")),
            .f64 => {
                try self.emit(lset("y"));
                try self.emit(.{ .convert = "i64.reinterpret_f64" });
                try self.emit(lget("y"));
                try self.emit(.{ .convert = "i64.reinterpret_f64" });
                try self.emit(opOf(.i64, "eq"));
            },
            .any => {
                try self.emit(.{ .ref_cast = prelude.gc_str_ref });
                try self.emit(lset("y"));
                try self.emit(.{ .ref_cast = prelude.gc_str_ref });
                try self.emit(lget("y"));
                try self.emit(self.builder().helper(.str_eq));
            },
        }
        try self.emit(.{ .br_if = "found" });
        try self.emit(lget("j"));
        try self.emit(one);
        try self.emit(opOf(.i32, "add"));
        try self.emit(lset("j"));
        try self.emit(.{ .br = "scan" });
        const inner_seq = self.seal(&inner, .terminated);
        var miss: Capture = .{};
        self.open(&miss);
        try self.emit(.{ .block = .{ .kind = .loop, .label = "scan", .body = inner_seq } });
        const miss_body = self.seal(&miss, .none);
        // block $found { block $miss { loop $scan … } ; out[k] = x; k += 1 }
        var found: Capture = .{};
        self.open(&found);
        try self.emit(.{ .block = .{ .kind = .block, .label = "miss", .body = miss_body } });
        try self.emit(lget("out"));
        try self.emit(lget("k"));
        try self.emit(lget("x"));
        try self.emit(.{ .array_set = ti });
        try self.emit(lget("k"));
        try self.emit(one);
        try self.emit(opOf(.i32, "add"));
        try self.emit(lset("k"));
        const found_body = self.seal(&found, .none);
        try self.emit(.{ .block = .{ .kind = .block, .label = "found", .body = found_body } });
        try self.emit(lget("i"));
        try self.emit(one);
        try self.emit(opOf(.i32, "add"));
        try self.emit(lset("i"));
        try self.emit(.{ .br = "cont" });
        const outer_seq = self.seal(&outer, .terminated);
        try self.gcLoop(outer_seq);
        try self.emit(lget("out"));
        try self.emit(zero);
        try self.emit(lget("k"));
        try self.emit(.{ .call = try self.gcArrOp("slice", cls) });
        const yt: ValType = switch (cls) {
            .i32 => .i32,
            .f64 => .f64,
            .any => prelude.gc_str_ref,
        };
        try self.gcFinishFn(name, &.{P("xs", at)}, at, &.{
            .{ .name = "n", .ty = .i32 }, .{ .name = "i", .ty = .i32 }, .{ .name = "j", .ty = .i32 }, .{ .name = "k", .ty = .i32 },
            .{ .name = "x", .ty = ev },   .{ .name = "y", .ty = yt },   .{ .name = "out", .ty = at },
        }, &c);
        return name;
    }

    /// `__arr_flatten_<class>(xs)`: the elements of every inner array of
    /// `xs` (an `anyref` array of arrays of `class`), in order.
    fn gcArrFlatten(self: *Emitter, cls: Repr.Elem) anyerror![]const u8 {
        const name = try std.fmt.allocPrint(self.arena(), "__arr_flatten_{s}", .{gcClsSuffix(cls)});
        if (!try self.gcHelperOnce(name)) return name;
        const oi = self.gcTyIndex(.{ .arr = .any });
        const ti = self.gcTyIndex(.{ .arr = cls });
        const at = ValType.def(ti);
        const P = wat.Builder.param;
        var c: Capture = .{};
        self.open(&c);
        try self.emit(lget("xs"));
        try self.emit(.array_len);
        try self.emit(lset("n"));
        for (0..2) |pass| {
            // Pass 0 counts the elements; pass 1 copies them.
            try self.emit(zero);
            try self.emit(lset("i"));
            var body: Capture = .{};
            self.open(&body);
            try self.emit(lget("i"));
            try self.emit(lget("n"));
            try self.emit(opOf(.i32, "ge_u"));
            try self.emit(.{ .br_if = "brk" });
            try self.emit(lget("xs"));
            try self.emit(lget("i"));
            try self.emit(.{ .array_get = .{ .ty = oi } });
            try self.emit(.{ .ref_cast = at });
            try self.emit(lset("a"));
            if (pass == 0) {
                try self.emit(lget("t"));
                try self.emit(lget("a"));
                try self.emit(.array_len);
                try self.emit(opOf(.i32, "add"));
                try self.emit(lset("t"));
            } else {
                try self.emit(lget("r"));
                try self.emit(lget("o"));
                try self.emit(lget("a"));
                try self.emit(zero);
                try self.emit(lget("a"));
                try self.emit(.array_len);
                try self.emit(.{ .array_copy = .{ .dst = ti, .src = ti } });
                try self.emit(lget("o"));
                try self.emit(lget("a"));
                try self.emit(.array_len);
                try self.emit(opOf(.i32, "add"));
                try self.emit(lset("o"));
            }
            try self.emit(lget("i"));
            try self.emit(one);
            try self.emit(opOf(.i32, "add"));
            try self.emit(lset("i"));
            try self.emit(.{ .br = "cont" });
            const loop_seq = self.seal(&body, .terminated);
            try self.gcLoop(loop_seq);
            if (pass == 0) {
                try self.emit(lget("t"));
                try self.emit(.{ .array_new_default = ti });
                try self.emit(lset("r"));
            }
        }
        try self.emit(lget("r"));
        try self.gcFinishFn(name, &.{P("xs", ValType.def(oi))}, at, &.{
            .{ .name = "n", .ty = .i32 }, .{ .name = "i", .ty = .i32 }, .{ .name = "t", .ty = .i32 }, .{ .name = "o", .ty = .i32 },
            .{ .name = "a", .ty = at },   .{ .name = "r", .ty = at },
        }, &c);
        return name;
    }

    /// `__arr_chunked_<class>(xs, m)` / `__arr_sliding_<class>(xs, m)`: an
    /// `anyref` array of slices of `xs` — consecutive ones of `m`, the last
    /// shorter (`ceil(n / m)` of them), or one of `m` per start offset
    /// (`n - m + 1`); none for `m <= 0` (std-wasm's `chunkCount` /
    /// `slidingCount`, each slice `xs.slice(from, from + m)`).
    fn gcArrWindows(self: *Emitter, chunked: bool, cls: Repr.Elem) anyerror![]const u8 {
        const name = try std.fmt.allocPrint(self.arena(), "__arr_{s}_{s}", .{ if (chunked) "chunked" else "sliding", gcClsSuffix(cls) });
        if (!try self.gcHelperOnce(name)) return name;
        const oi = self.gcTyIndex(.{ .arr = .any });
        const ti = self.gcTyIndex(.{ .arr = cls });
        const at = ValType.def(ti);
        const P = wat.Builder.param;
        const slice = try self.gcArrOp("slice", cls);
        var c: Capture = .{};
        self.open(&c);
        try self.emit(lget("xs"));
        try self.emit(.array_len);
        try self.emit(lset("n"));
        // cnt = 0 when m <= 0
        var some: Capture = .{};
        self.open(&some);
        if (chunked) {
            try self.emit(lget("n"));
            try self.emit(lget("m"));
            try self.emit(opOf(.i32, "div_u"));
            try self.emit(lget("n"));
            try self.emit(lget("m"));
            try self.emit(opOf(.i32, "rem_u"));
            try self.emit(zero);
            try self.emit(opOf(.i32, "ne"));
            try self.emit(opOf(.i32, "add"));
            try self.emit(lset("cnt"));
        } else {
            try self.emit(lget("n"));
            try self.emit(lget("m"));
            try self.emit(opOf(.i32, "sub"));
            try self.emit(one);
            try self.emit(opOf(.i32, "add"));
            try self.emit(lset("cnt"));
            var neg: Capture = .{};
            self.open(&neg);
            try self.emit(zero);
            try self.emit(lset("cnt"));
            const neg_seq = self.seal(&neg, .none);
            try self.emit(lget("cnt"));
            try self.emit(zero);
            try self.emit(opOf(.i32, "lt_s"));
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = neg_seq } } });
        }
        const some_seq = self.seal(&some, .none);
        try self.emit(lget("m"));
        try self.emit(zero);
        try self.emit(opOf(.i32, "gt_s"));
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = some_seq } } });
        try self.emit(lget("cnt"));
        try self.emit(.{ .array_new_default = oi });
        try self.emit(lset("r"));
        var body: Capture = .{};
        self.open(&body);
        try self.emit(lget("k"));
        try self.emit(lget("cnt"));
        try self.emit(opOf(.i32, "ge_u"));
        try self.emit(.{ .br_if = "brk" });
        try self.emit(lget("k"));
        if (chunked) {
            try self.emit(lget("m"));
            try self.emit(opOf(.i32, "mul"));
        }
        try self.emit(lset("from"));
        try self.emit(lget("r"));
        try self.emit(lget("k"));
        try self.emit(lget("xs"));
        try self.emit(lget("from"));
        try self.emit(lget("from"));
        try self.emit(lget("m"));
        try self.emit(opOf(.i32, "add"));
        try self.emit(.{ .call = slice });
        try self.emit(.{ .array_set = oi });
        try self.emit(lget("k"));
        try self.emit(one);
        try self.emit(opOf(.i32, "add"));
        try self.emit(lset("k"));
        try self.emit(.{ .br = "cont" });
        const loop_seq = self.seal(&body, .terminated);
        try self.gcLoop(loop_seq);
        try self.emit(lget("r"));
        try self.gcFinishFn(name, &.{ P("xs", at), P("m", .i32) }, ValType.def(oi), &.{
            .{ .name = "n", .ty = .i32 },            .{ .name = "cnt", .ty = .i32 }, .{ .name = "k", .ty = .i32 }, .{ .name = "from", .ty = .i32 },
            .{ .name = "r", .ty = ValType.def(oi) },
        }, &c);
        return name;
    }

    // ── the std-wasm boundary (front 164 s2 P2, until s3) ───────────────

    fn gcLoadW(off: u32) Instr {
        return .{ .load = .{ .offset = off } };
    }

    /// `__gc_to_lin_strs(a)` / `__lin_to_gc_strs(p)`: a `string[]` between
    /// the GC array of strings and std-wasm's `[n][s0][s1]…`, every string
    /// copied.
    fn gcMarshalStrs(self: *Emitter, to_linear: bool) anyerror![]const u8 {
        const name: []const u8 = if (to_linear) "__gc_to_lin_strs" else "__lin_to_gc_strs";
        if (!try self.gcHelperOnce(name)) return name;
        const ti = self.gcTyIndex(.{ .arr = .any });
        const at = ValType.def(ti);
        const sti = prelude.gc_str_ref;
        var c: Capture = .{};
        self.open(&c);
        var body: Capture = .{};
        self.open(&body);
        try self.emit(.{ .local_get = "i" });
        try self.emit(.{ .local_get = "n" });
        try self.emit(opOf(.i32, "ge_u"));
        try self.emit(.{ .br_if = "brk" });
        if (to_linear) {
            try self.emit(.{ .local_get = "p" });
            try self.emit(.{ .local_get = "i" });
            try self.emit(try self.constInt(4));
            try self.emit(opOf(.i32, "mul"));
            try self.emit(opOf(.i32, "add"));
            try self.emit(.{ .local_get = "a" });
            try self.emit(.{ .local_get = "i" });
            try self.emit(.{ .array_get = .{ .ty = ti } });
            try self.emit(.{ .ref_cast = sti });
            try self.emit(self.builder().helper(.gc_to_lin_str));
            try self.emit(.{ .store = .{ .offset = 4 } });
        } else {
            try self.emit(.{ .local_get = "r" });
            try self.emit(.{ .local_get = "i" });
            try self.emit(.{ .local_get = "p" });
            try self.emit(.{ .local_get = "i" });
            try self.emit(try self.constInt(4));
            try self.emit(opOf(.i32, "mul"));
            try self.emit(opOf(.i32, "add"));
            try self.emit(gcLoadW(4));
            try self.emit(self.builder().helper(.lin_to_gc_str));
            try self.emit(.{ .array_set = ti });
        }
        try self.emit(.{ .local_get = "i" });
        try self.emit(one);
        try self.emit(opOf(.i32, "add"));
        try self.emit(.{ .local_set = "i" });
        try self.emit(.{ .br = "cont" });
        const loop_seq = self.seal(&body, .terminated);
        if (to_linear) {
            try self.emit(.{ .local_get = "a" });
            try self.emit(.array_len);
            try self.emit(.{ .local_set = "n" });
            try self.emit(.{ .local_get = "n" });
            try self.emit(try self.constInt(4));
            try self.emit(opOf(.i32, "mul"));
            try self.emit(try self.constInt(4));
            try self.emit(opOf(.i32, "add"));
            self.gc_alloc_direct = true;
            try self.emit(self.builder().helper(.alloc));
            try self.emit(.{ .local_set = "p" });
            try self.emit(.{ .local_get = "p" });
            try self.emit(.{ .local_get = "n" });
            try self.emit(.{ .store = .{} });
        } else {
            try self.emit(.{ .local_get = "p" });
            try self.emit(gcLoadW(0));
            try self.emit(.{ .local_set = "n" });
            try self.emit(.{ .local_get = "n" });
            try self.emit(.{ .array_new_default = ti });
            try self.emit(.{ .local_set = "r" });
        }
        try self.gcLoop(loop_seq);
        try self.emit(.{ .local_get = if (to_linear) "p" else "r" });
        const fbody = self.seal(&c, .{ .value = if (to_linear) ValType.i32 else at });
        const locals: []const wat.Local = if (to_linear)
            &.{ .{ .name = "n", .ty = .i32 }, .{ .name = "p", .ty = .i32 }, .{ .name = "i", .ty = .i32 } }
        else
            &.{ .{ .name = "n", .ty = .i32 }, .{ .name = "i", .ty = .i32 }, .{ .name = "r", .ty = at } };
        try self.gc_marshal_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = name,
            .params = if (to_linear) &.{wat.Builder.param("a", at)} else &.{wat.Builder.param("p", .i32)},
            .result = if (to_linear) ValType.i32 else at,
            .locals = try self.gcLocals(locals),
            .body = fbody,
        }) });
        return name;
    }

    /// `__gc_to_lin_opt_i32(o)` / `__lin_to_gc_opt_i32(p)`: a `?i32` between its
    /// box in an `anyref` (or null) and std-wasm's 4-byte box (or `0`).
    fn gcMarshalOptI32(self: *Emitter, to_linear: bool) anyerror![]const u8 {
        const name: []const u8 = if (to_linear) "__gc_to_lin_opt_i32" else "__lin_to_gc_opt_i32";
        if (!try self.gcHelperOnce(name)) return name;
        const bx = self.gcTyIndex(.{ .box = .i32 });
        var c: Capture = .{};
        self.open(&c);
        if (to_linear) {
            var absent: Capture = .{};
            self.open(&absent);
            try self.emit(zero);
            const absent_seq = self.seal(&absent, .{ .value = .i32 });
            var present: Capture = .{};
            self.open(&present);
            try self.emit(.{ .local_get = "o" });
            try self.emit(.{ .ref_cast = ValType.def(bx) });
            try self.emit(.{ .struct_get = .{ .ty = bx, .field = 0 } });
            try self.emit(self.builder().helper(.box_i32));
            const present_seq = self.seal(&present, .{ .value = .i32 });
            try self.emit(.{ .local_get = "o" });
            try self.emit(.ref_is_null);
            try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = absent_seq }, .@"else" = .{ .seq = present_seq } } });
        } else {
            var absent: Capture = .{};
            self.open(&absent);
            try self.emit(.{ .ref_null = .anyref });
            const absent_seq = self.seal(&absent, .{ .value = .anyref });
            var present: Capture = .{};
            self.open(&present);
            try self.emit(.{ .local_get = "p" });
            try self.emit(gcLoadW(0));
            try self.emit(.{ .struct_new = bx });
            const present_seq = self.seal(&present, .{ .value = .anyref });
            try self.emit(.{ .local_get = "p" });
            try self.emit(opOf(.i32, "eqz"));
            try self.emit(.{ .@"if" = .{ .result = .anyref, .then = .{ .seq = absent_seq }, .@"else" = .{ .seq = present_seq } } });
        }
        const fbody = self.seal(&c, .{ .value = if (to_linear) ValType.i32 else ValType.anyref });
        try self.gc_marshal_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = name,
            .params = if (to_linear) &.{wat.Builder.param("o", .anyref)} else &.{wat.Builder.param("p", .i32)},
            .result = if (to_linear) ValType.i32 else ValType.anyref,
            .body = fbody,
        }) });
        return name;
    }

    // ── GC printers (front 164 s2 P2) ───────────────────────────────────
    //
    // A value's text in a GC module is written by a function generated for its
    // shape (`$__print_shaped_raw`'s language: `i b f l u s T E…`, `[X`, `(XY…)`,
    // `?X` / `!X`) or for a record's or a variant's declaration. The function's
    // parameter is the value itself — a number, a string, an array, a struct —
    // and an element of an `anyref` slot is cast (a scalar, unboxed) before the
    // function of its shape is called.

    /// The length of the shape at the start of `sh` (`shapeSpan`, with the
    /// all-unit enum's names).
    fn gcShapeSpan(sh: []const u8) usize {
        if (sh.len == 0) return 0;
        switch (sh[0]) {
            '[', '?', '!' => return 1 + gcShapeSpan(sh[1..]),
            'R' => {
                const ok = gcShapeSpan(sh[1..]);
                return 1 + ok + gcShapeSpan(sh[1 + ok ..]);
            },
            '(' => {
                var i: usize = 1;
                while (i < sh.len and sh[i] != ')') {
                    const n = gcShapeSpan(sh[i..]);
                    if (n == 0) return i;
                    i += n;
                }
                return if (i < sh.len) i + 1 else i;
            },
            'E' => {
                var i: usize = 2;
                var j: usize = 0;
                while (j < sh[1]) : (j += 1) i += 1 + sh[i];
                return i;
            },
            else => return 1,
        }
    }

    /// The class of the elements of an array whose element shape is `x`.
    fn gcShapeClass(x: []const u8) Repr.Elem {
        return switch (x[0]) {
            'i', 'b', 'E' => .i32,
            'f' => .f64,
            else => .any,
        };
    }

    /// Whether a value of shape `x` is a scalar the `anyref` slots hold in a box.
    fn gcShapeIsScalar(x: []const u8) bool {
        return switch (x[0]) {
            'i', 'b', 'E', 'f', 'l', 'u' => true,
            else => false,
        };
    }

    /// The value type a value of shape `sh` has.
    fn gcShapeVt(self: *Emitter, sh: []const u8) ValType {
        switch (sh[0]) {
            'R' => return self.gcTy(.result),
            'i', 'b', 'E' => return .i32,
            'f' => return .f64,
            'l', 'u' => return .i64,
            's' => {
                self.gc_str_used = true;
                return prelude.gc_str_ref;
            },
            'T', 'U' => return .anyref,
            '[' => return self.gcTy(.{ .arr = gcShapeClass(sh[1..]) }),
            '(' => return self.gcTy(.{ .arr = .any }),
            '?' => return if (gcShapeIsScalar(sh[1..])) .anyref else self.gcShapeVt(sh[1..]),
            '!' => return .anyref,
            else => {
                self.gcGap("a print shape with no GC form");
                return .anyref;
            },
        }
    }

    /// Turns the `anyref` on the stack into a value of shape `sh`: a scalar
    /// unboxed, a reference cast to its type, `T` left as it is.
    fn gcFromAny(self: *Emitter, sh: []const u8) !void {
        switch (sh[0]) {
            'i', 'b', 'E' => {
                const k = self.gcTyIndex(.{ .box = .i32 });
                try self.emit(.{ .ref_cast = ValType.def(k) });
                try self.emit(.{ .struct_get = .{ .ty = k, .field = 0 } });
            },
            'f' => {
                const k = self.gcTyIndex(.{ .box = .f64 });
                try self.emit(.{ .ref_cast = ValType.def(k) });
                try self.emit(.{ .struct_get = .{ .ty = k, .field = 0 } });
            },
            'l', 'u' => {
                const k = self.gcTyIndex(.{ .box = .i64 });
                try self.emit(.{ .ref_cast = ValType.def(k) });
                try self.emit(.{ .struct_get = .{ .ty = k, .field = 0 } });
            },
            else => {
                const vt = self.gcShapeVt(sh);
                if (vt != .anyref) try self.emit(.{ .ref_cast = vt });
            },
        }
    }

    /// Writes the text `text` (a GC string literal through `$__print_str_raw`).
    fn gcPutStr(self: *Emitter, text: []const u8) !void {
        try self.emitStrLit(text);
        try self.emit(self.builder().helper(.print_str_raw));
    }

    /// The symbol of the function printing a value of the shape at the start
    /// of `sh0`, written on first use.
    fn gcPrinter(self: *Emitter, sh0: []const u8) anyerror![]const u8 {
        const sh = sh0[0..gcShapeSpan(sh0)];
        if (sh.len == 0) return self.gcFail("an empty print shape");
        const gop = try self.gc_printers.getOrPut(self.alloc, sh);
        const sym = try std.fmt.allocPrint(self.arena(), "__pr{d}", .{gop.index});
        if (gop.found_existing) return sym;
        const key = try self.arena().dupe(u8, sh);
        gop.key_ptr.* = key;
        try self.gcGenShapePrinter(sym, key);
        return sym;
    }

    /// `block $brk (loop $cont <body>)` — `body` ends with a branch to `$cont`.
    fn gcLoop(self: *Emitter, body: Seq) !void {
        var outer: Capture = .{};
        self.open(&outer);
        try self.emit(.{ .block = .{ .kind = .loop, .label = "cont", .body = body } });
        const outer_seq = self.seal(&outer, .none);
        try self.emit(.{ .block = .{ .kind = .block, .label = "brk", .body = outer_seq } });
    }

    fn gcGenShapePrinter(self: *Emitter, sym: []const u8, sh: []const u8) anyerror!void {
        const ar = self.arena();
        const vt = self.gcShapeVt(sh);
        var c: Capture = .{};
        self.open(&c);
        var locals: std.ArrayListUnmanaged(wat.Local) = .empty;
        const get_v: Instr = .{ .local_get = "v" };
        const b = self.builder();
        switch (sh[0]) {
            'i' => {
                try self.emit(get_v);
                try self.emit(b.helper(.print_i32_raw));
            },
            'b' => {
                try self.emit(get_v);
                try self.emit(b.helper(.print_bool_raw));
            },
            'f' => {
                try self.emit(get_v);
                try self.emit(b.helper(.print_f64_raw));
            },
            'l' => {
                try self.emit(get_v);
                try self.emit(b.helper(.print_i64_raw));
            },
            'u' => {
                try self.emit(get_v);
                try self.emit(b.helper(.print_u64_raw));
            },
            's' => {
                try self.emit(get_v);
                try self.emit(b.helper(.print_quoted_raw));
            },
            'T' => {
                self.gc_tagged_used = true;
                try self.emit(get_v);
                try self.emit(.{ .call = "__print_tagged_raw" });
            },
            // A union's (or `unknown`'s) slot: printed by what it holds, a
            // string quoted.
            'U' => {
                try self.emit(get_v);
                try self.emit(.{ .call = try self.gcUnkPrint(true) });
            },
            'E' => {
                // An all-unit enum: the ordinal picks one of the names.
                var i: usize = 2;
                var k: u32 = 0;
                while (k < sh[1]) : (k += 1) {
                    const n = sh[i];
                    const name = sh[i + 1 .. i + 1 + n];
                    i += 1 + n;
                    var hit: Capture = .{};
                    self.open(&hit);
                    try self.gcPutStr(name);
                    try self.emit(.@"return");
                    const hit_seq = self.seal(&hit, .terminated);
                    try self.emit(get_v);
                    try self.emit(try self.constInt(k));
                    try self.emit(opOf(.i32, "eq"));
                    try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } });
                }
            },
            '[' => {
                const x = sh[1..];
                const cls = gcShapeClass(x);
                const at = self.gcTyIndex(.{ .arr = cls });
                const px = try self.gcPrinter(x);
                try locals.append(ar, .{ .name = "n", .ty = .i32 });
                try locals.append(ar, .{ .name = "i", .ty = .i32 });
                try self.gcPutStr("[");
                try self.emit(get_v);
                try self.emit(.array_len);
                try self.emit(.{ .local_set = "n" });
                var body: Capture = .{};
                self.open(&body);
                try self.emit(.{ .local_get = "i" });
                try self.emit(.{ .local_get = "n" });
                try self.emit(opOf(.i32, "ge_u"));
                try self.emit(.{ .br_if = "brk" });
                var sep: Capture = .{};
                self.open(&sep);
                try self.gcPutStr(", ");
                const sep_seq = self.seal(&sep, .none);
                try self.emit(.{ .local_get = "i" });
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = sep_seq } } });
                try self.emit(get_v);
                try self.emit(.{ .local_get = "i" });
                try self.emit(.{ .array_get = .{ .ty = at } });
                if (cls == .any) try self.gcFromAny(x);
                try self.emit(.{ .call = px });
                try self.emit(.{ .local_get = "i" });
                try self.emit(one);
                try self.emit(opOf(.i32, "add"));
                try self.emit(.{ .local_set = "i" });
                try self.emit(.{ .br = "cont" });
                const loop_seq = self.seal(&body, .terminated);
                try self.gcLoop(loop_seq);
                try self.gcPutStr("]");
            },
            '(' => {
                const at = self.gcTyIndex(.{ .arr = .any });
                try self.gcPutStr("#(");
                var i: usize = 1;
                var k: u32 = 0;
                while (i < sh.len and sh[i] != ')') : (k += 1) {
                    const n = gcShapeSpan(sh[i..]);
                    if (n == 0) return self.gcFail("a malformed tuple shape");
                    const x = sh[i .. i + n];
                    const px = try self.gcPrinter(x);
                    if (k > 0) try self.gcPutStr(", ");
                    try self.emit(get_v);
                    try self.emit(try self.constInt(k));
                    try self.emit(.{ .array_get = .{ .ty = at } });
                    try self.gcFromAny(x);
                    try self.emit(.{ .call = px });
                    i += n;
                }
                try self.gcPutStr(")");
            },
            'R' => {
                // `Ok(x)` / `Error(y)`: the tag picks the payload's shape.
                const okx = sh[1 .. 1 + gcShapeSpan(sh[1..])];
                const errx = sh[1 + okx.len ..][0..gcShapeSpan(sh[1 + okx.len ..])];
                const pok = try self.gcPrinter(okx);
                const perr = try self.gcPrinter(errx);
                const rti = self.gcTyIndex(.result);
                var is_err: Capture = .{};
                self.open(&is_err);
                try self.gcPutStr("Error(");
                try self.emit(get_v);
                try self.emit(.{ .struct_get = .{ .ty = rti, .field = 1 } });
                try self.gcFromAny(errx);
                try self.emit(.{ .call = perr });
                try self.gcPutStr(")");
                const err_seq = self.seal(&is_err, .none);
                var is_ok: Capture = .{};
                self.open(&is_ok);
                try self.gcPutStr("Ok(");
                try self.emit(get_v);
                try self.emit(.{ .struct_get = .{ .ty = rti, .field = 1 } });
                try self.gcFromAny(okx);
                try self.emit(.{ .call = pok });
                try self.gcPutStr(")");
                const ok_seq = self.seal(&is_ok, .none);
                try self.emit(get_v);
                try self.emit(.{ .struct_get = .{ .ty = rti, .field = 0 } });
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = err_seq }, .@"else" = .{ .seq = ok_seq } } });
            },
            '?', '!' => {
                const x = sh[1..];
                const px = try self.gcPrinter(x);
                var absent: Capture = .{};
                self.open(&absent);
                try self.gcPutStr("null");
                try self.emit(.@"return");
                const absent_seq = self.seal(&absent, .terminated);
                try self.emit(get_v);
                try self.emit(.ref_is_null);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = absent_seq } } });
                try self.emit(get_v);
                if (sh[0] == '!' or gcShapeIsScalar(x)) try self.gcFromAny(x);
                try self.emit(.{ .call = px });
            },
            else => return self.gcFail("a print shape with no GC form"),
        }
        const body = self.seal(&c, .none);
        const lines = try ar.alloc([]const wat.Local, locals.items.len);
        for (locals.items, 0..) |l, i| lines[i] = try ar.dupe(wat.Local, &.{l});
        try self.gc_pr_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = sym,
            .params = &.{wat.Builder.param("v", vt)},
            .locals = lines,
            .body = body,
        }) });
    }

    /// The symbol of the printer of record `rec`'s values (`Name(f: v, …)`),
    /// or of variant `variant` of enum `en` (`Enum.Variant(f: v, …)`).
    fn gcDeclPrinter(self: *Emitter, rec: []const u8, variant: ?[]const u8) anyerror![]const u8 {
        const key = if (variant) |v| try std.fmt.allocPrint(self.arena(), "@V {s} {s}", .{ rec, v }) else try std.fmt.allocPrint(self.arena(), "@R {s}", .{rec});
        const gop = try self.gc_printers.getOrPut(self.alloc, key);
        const sym = try std.fmt.allocPrint(self.arena(), "__pr{d}", .{gop.index});
        if (gop.found_existing) return sym;
        gop.key_ptr.* = key;
        const ar = self.arena();
        // The type of the value, the fields to print and the name shown.
        var fnames: []const []const u8 = &.{};
        var trefs: []const ast.TypeRef = &.{};
        var shown: []const u8 = undefined;
        var ty: GcTy = undefined;
        if (variant) |vn| {
            const variants = self.enums.get(rec) orelse return self.gcFail("a variant of no enum");
            const found: ast.EnumVariant = for (variants) |ev| {
                if (std.mem.eql(u8, ev.name, vn)) break ev;
            } else return self.gcFail("a variant of no enum");
            const names = try ar.alloc([]const u8, found.fields.len);
            const tr = try ar.alloc(ast.TypeRef, found.fields.len);
            for (found.fields, 0..) |f, i| {
                names[i] = f.name;
                tr[i] = f.typeRef;
            }
            fnames = names;
            trefs = tr;
            shown = try std.fmt.allocPrint(ar, "{s}.{s}", .{ self.printed_names.get(rec) orelse displayTypeName(rec), vn });
            ty = .{ .variant = .{ .en = rec, .name = vn } };
        } else {
            fnames = self.records.get(rec) orelse return self.gcFail("a record of no declaration");
            trefs = self.record_field_typerefs.get(rec) orelse &.{};
            shown = self.printed_names.get(rec) orelse displayTypeName(rec);
            ty = .{ .record = rec };
        }
        const tidx = self.gcTyIndex(ty);
        var c: Capture = .{};
        self.open(&c);
        const get_v: Instr = .{ .local_get = "v" };
        // `display(self) -> string` answers its own text (decision 8 §7).
        if (variant == null) {
            const dsym = try std.fmt.allocPrint(ar, "{s}_display", .{rec});
            // A generic record's `display` is its one body, which linear
            // memory reaches only through a call that binds its type
            // parameters (`refuseUnboundTemplateCalls`): not printed here.
            if (self.record_generics.contains(rec) and self.fn_sigs.contains(dsym)) return self.gcFail("a generic record's display");
            if (self.fn_sigs.get(dsym)) |sig| if (sig.params.len == 1 and sig.result != null and sig.result.?.isStr()) {
                try self.emit(get_v);
                try self.emit(.{ .call = dsym });
                try self.emit(self.builder().helper(.print_str_raw));
                try self.emit(.@"return");
            };
        }
        try self.gcPutStr(shown);
        if (fnames.len > 0) try self.gcPutStr("(");
        for (fnames, 0..) |fname, i| {
            if (i >= trefs.len) return self.gcFail("a field with no type");
            const label = try std.fmt.allocPrint(ar, "{s}{s}: ", .{ if (i > 0) ", " else "", fname });
            try self.gcPutStr(label);
            const gen: ?[]const ast.GenericParam = if (variant == null) self.record_generics.get(rec) else self.enum_generics.get(rec);
            const fsh = if (gen != null and mentionsGeneric(trefs[i], gen.?)) try self.gcErasedShape(gen.?, trefs[i]) else if (isUnknownTypeRef(trefs[i])) try ar.dupe(u8, "U") else if (variant == null) blk: {
                const wide: ?u8 = switch (trefs[i]) {
                    .named => |n| i64CellCode(n),
                    else => null,
                };
                if (wide) |w| break :blk try ar.dupe(u8, &.{w});
                break :blk try self.fieldShape(trefs[i]);
            } else try self.fieldShape(trefs[i]);
            const px = try self.gcPrinter(fsh);
            try self.emit(get_v);
            try self.emit(.{ .struct_get = .{ .ty = tidx, .field = @intCast(i) } });
            try self.emit(.{ .call = px });
        }
        if (fnames.len > 0) try self.gcPutStr(")");
        const body = self.seal(&c, .none);
        try self.gc_pr_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = sym,
            .params = &.{wat.Builder.param("v", ValType.def(tidx))},
            .body = body,
        }) });
        return sym;
    }

    /// `__print_ebox(v: anyref) -> i32`: when `v` is an all-unit enum's box
    /// (`GcTy.ebox`), its variant's name written and `1`; else `0`.
    /// `__print_arrs(v: anyref) -> i32`: when `v` is a tuple, an array of
    /// words, of floats or of `unknown`s, written as its shape's printer
    /// writes it and `1`; else `0`. A tuple is tested first: it is an
    /// `arr_any` too (decision 568).
    fn gcArrsPrinter(self: *Emitter) anyerror!void {
        var c: Capture = .{};
        self.open(&c);
        for (self.gc_types.items) |t| if (t == .tuple) {
            const vt = self.gcTy(.tuple);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_test = vt });
            try self.gcWhenReturn(&.{ .{ .local_get = "v" }, .{ .ref_cast = vt }, .{ .call = try self.gcTuplePrinter() }, one });
            break;
        };
        var i: usize = 0;
        while (i < self.gc_types.items.len) : (i += 1) {
            const t = self.gc_types.items[i];
            if (t != .arr) continue;
            const k: u16 = @intCast(i + 1);
            const vt = ValType.def(k);
            const px = try self.gcPrinter(switch (t.arr) {
                .i32 => "[i",
                .f64 => "[f",
                .any => "[U",
            });
            var hit: Capture = .{};
            self.open(&hit);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_cast = vt });
            try self.emit(.{ .call = px });
            try self.emit(one);
            try self.emit(.@"return");
            const hit_seq = self.seal(&hit, .terminated);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_test = vt });
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } });
        }
        try self.emit(zero);
        const body = self.seal(&c, .{ .value = .i32 });
        try self.gc_pr_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = "__print_arrs",
            .params = &.{wat.Builder.param("v", .anyref)},
            .result = .i32,
            .body = body,
        }) });
    }

    /// `__print_tuple(v)`: a tuple held by an `unknown` — `#(e1, e2)`, each
    /// element printed by what its box holds (`U`), a string quoted.
    fn gcTuplePrinter(self: *Emitter) anyerror![]const u8 {
        const name = "__print_tuple";
        if (!try self.gcHelperOnce(name)) return name;
        const vt = self.gcTy(.tuple);
        const at = self.gcTyIndex(.tuple);
        const px = try self.gcUnkPrint(true);
        var c: Capture = .{};
        self.open(&c);
        try self.gcPutStr("#(");
        try self.emit(.{ .local_get = "v" });
        try self.emit(.array_len);
        try self.emit(.{ .local_set = "n" });
        var body: Capture = .{};
        self.open(&body);
        try self.emit(.{ .local_get = "i" });
        try self.emit(.{ .local_get = "n" });
        try self.emit(opOf(.i32, "ge_u"));
        try self.emit(.{ .br_if = "brk" });
        var sep: Capture = .{};
        self.open(&sep);
        try self.gcPutStr(", ");
        const sep_seq = self.seal(&sep, .none);
        try self.emit(.{ .local_get = "i" });
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = sep_seq } } });
        try self.emit(.{ .local_get = "v" });
        try self.emit(.{ .local_get = "i" });
        try self.emit(.{ .array_get = .{ .ty = at } });
        try self.emit(.{ .call = px });
        try self.emit(.{ .local_get = "i" });
        try self.emit(one);
        try self.emit(opOf(.i32, "add"));
        try self.emit(.{ .local_set = "i" });
        try self.emit(.{ .br = "cont" });
        const loop_seq = self.seal(&body, .terminated);
        try self.gcLoop(loop_seq);
        try self.gcPutStr(")");
        try self.gcHelperFunc(name, &.{wat.Builder.param("v", vt)}, null, &.{ .{ .name = "n", .ty = .i32 }, .{ .name = "i", .ty = .i32 } }, self.seal(&c, .none));
        return name;
    }

    fn gcEboxPrinter(self: *Emitter) anyerror!void {
        var c: Capture = .{};
        self.open(&c);
        var i: usize = 0;
        while (i < self.gc_types.items.len) : (i += 1) {
            const t = self.gc_types.items[i];
            if (t != .ebox) continue;
            const k: u16 = @intCast(i + 1);
            const vt = ValType.def(k);
            const px = try self.gcPrinter(try self.unitEnumShape(t.ebox));
            var hit: Capture = .{};
            self.open(&hit);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_cast = vt });
            try self.emit(.{ .struct_get = .{ .ty = k, .field = 0 } });
            try self.emit(.{ .call = px });
            try self.emit(one);
            try self.emit(.@"return");
            const hit_seq = self.seal(&hit, .terminated);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_test = vt });
            try self.emit(.{ .local_get = "v" });
            try self.emit(.ref_is_null);
            try self.emit(opOf(.i32, "eqz"));
            try self.emit(opOf(.i32, "and"));
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } });
        }
        try self.emit(zero);
        const body = self.seal(&c, .{ .value = .i32 });
        try self.gc_pr_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = "__print_ebox",
            .params = &.{wat.Builder.param("v", .anyref)},
            .result = .i32,
            .body = body,
        }) });
    }

    /// The all-unit enum `e`'s type names, when its written type is one.
    fn unitEnumOfTypeRef(self: *Emitter, e: ast.Expr) ?[]const u8 {
        const t = self.typeRefOf(e) orelse return null;
        if (t != .named) return null;
        if (!self.enums.contains(t.named) or !self.isAllUnitEnum(t.named)) return null;
        return t.named;
    }

    /// `__print_tagged_raw(v: anyref)`: the text of a value of any declared
    /// type, by the first record or variant type that `v` is a value of.
    fn gcTaggedPrinter(self: *Emitter) anyerror!void {
        var c: Capture = .{};
        self.open(&c);
        var i: usize = 0;
        // A printer may declare more types: the list grows while it is walked.
        while (i < self.gc_types.items.len) : (i += 1) {
            const t = self.gc_types.items[i];
            const sym = switch (t) {
                .record => |n| try self.gcDeclPrinter(n, null),
                .variant => |v| try self.gcDeclPrinter(v.en, v.name),
                else => continue,
            };
            const vt = ValType.def(@intCast(i + 1));
            var hit: Capture = .{};
            self.open(&hit);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_cast = vt });
            try self.emit(.{ .call = sym });
            try self.emit(.@"return");
            const hit_seq = self.seal(&hit, .terminated);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .ref_test = vt });
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } });
        }
        try self.emit(.@"unreachable");
        const body = self.seal(&c, .terminated);
        try self.gc_pr_funcs.append(self.alloc, .{ .func = try self.builder().func(.{
            .name = "__print_tagged_raw",
            .params = &.{wat.Builder.param("v", .anyref)},
            .body = body,
        }) });
    }

    /// A fresh local of `r` for the GC lowering's own temporaries.
    fn gcTemp(self: *Emitter, r: Repr) ![]const u8 {
        const name = try std.fmt.allocPrint(self.reg_arena.allocator(), "__gc{d}", .{self.gc_seq});
        self.gc_seq += 1;
        try self.declareLocal(name, r);
        return name;
    }

    /// The `wat_ast.Stack` a lowered `Tail` stands for. `.value` carries the
    /// type the context coerced the expression to.
    fn stackOf(self: *Emitter, tail: Tail, ty: Repr) wat.Stack {
        return switch (tail) {
            .value => .{ .value = self.vtOf(ty) },
            .none => .none,
            .terminated => .terminated,
        };
    }

    fn resetFnState(self: *Emitter, result_type: ?Repr) void {
        self.locals.clearRetainingCapacity();
        self.eq_local_types.clearRetainingCapacity();
        self.bound_names.clearRetainingCapacity();
        self.field_closures.clearRetainingCapacity();
        self.ctor_lambdas.clearRetainingCapacity();
        self.shadow_log.clearRetainingCapacity();
        self.local_types.clearRetainingCapacity();
        self.str_locals.clearRetainingCapacity();
        self.arr_locals.clearRetainingCapacity();
        self.print_shape_locals.clearRetainingCapacity();
        self.arr_elem_locals.clearRetainingCapacity();
        self.arr_elem_recs.clearRetainingCapacity();
        self.result_shape_locals.clearRetainingCapacity();
        self.result_subjects.clearRetainingCapacity();
        self.aliases.clearRetainingCapacity();
        self.pattern_locals.clearRetainingCapacity();
        self.local_typerefs.clearRetainingCapacity();
        self.opt_locals.clearRetainingCapacity();
        self.narrowed_opts.clearRetainingCapacity();
        self.cur_ret_typeref = null;
        self.raw_return = false;
        self.bool_locals.clearRetainingCapacity();
        self.closure_locals.clearRetainingCapacity();
        self.env_slots.clearRetainingCapacity();
        self.pending_locals.clearRetainingCapacity();
        self.cur_result = result_type orelse .i32;
        self.fn_has_result = result_type != null;
        self.fn_returns_result = false;
        self.case_depth = 0;
        self.try_seq = 0;
        self.assert_seq = 0;
        self.mem_seq = 0;
        self.res_seq = 0;
        self.loop_seq = 0;
        self.yield_target = null;
        self.gen_end = null;
        self.gen_item = null;
        self.gen_locals.clearRetainingCapacity();
        self.gen_items.clearRetainingCapacity();
        self.loop_depth = 0;
        self.defer_stack.clearRetainingCapacity();
        self.defer_loop_floor = 0;
        self.loop_stack.clearRetainingCapacity();
        self.defer_fn_body = null;
        self.tail_self = null;
        self.tail_self_used = false;
    }

    /// Register a local for the current function. Idempotent, and the *only*
    /// way a `(local …)` reaches the output: the declaration goes into the
    /// function node, which is the one place WAT accepts it.
    /// The local a `val` / `var` (or a loop's, a HOF's binder) named `name`
    /// binds: `name` itself, or a fresh `<name>__sh<n>` when a parameter or a
    /// binding of an enclosing, still open statement list holds it, or when it is a
    /// module-level name (the global stays the global where a `defer` reads it) — a
    /// sibling block's binding has ended and its local is reused, as before. One function is one wasm local
    /// namespace, so an inner block's `val x = 2` wrote the outer `$x`, and
    /// `x` after the block read `2` at exit 0 where node answers the outer
    /// value (decision 152: a block is a new scope).
    fn bindTarget(self: *Emitter, name: []const u8) ![]const u8 {
        const ra = self.reg_arena.allocator();
        if (!self.bound_names.contains(name) and !self.isParamLocal(name) and !self.globals.contains(name)) {
            try self.bound_names.put(ra, name, {});
            try self.shadow_log.append(ra, .{ .name = name, .prev = null, .aliased = false });
            return name;
        }
        const alias = try std.fmt.allocPrint(ra, "{s}__sh{d}", .{ name, self.shadow_seq });
        self.shadow_seq += 1;
        return alias;
    }

    /// `bindTarget` for a binder of wasm type `ty`: a name the function
    /// already declared with another type (`xs.map({ x -> x * 3.0 })` then
    /// `[1, 2].map({ x -> x + 1 })`) is a local of its own — one wasm local
    /// has one type, and the second walk stored an `i32` into the `f64`.
    fn bindTargetAs(self: *Emitter, name: []const u8, ty: Repr) ![]const u8 {
        const t = try self.bindTarget(name);
        const have = self.locals.get(t) orelse return t;
        if (self.sameVal(have, ty)) return t;
        const ra = self.reg_arena.allocator();
        const alias = try std.fmt.allocPrint(ra, "{s}__sh{d}", .{ name, self.shadow_seq });
        self.shadow_seq += 1;
        return alias;
    }

    /// After the binding's value is lowered — `val x = x + 1` reads the outer
    /// `x` — the name means the alias until its statement list ends.
    fn installShadow(self: *Emitter, name: []const u8, target: []const u8) void {
        if (std.mem.eql(u8, name, target)) return;
        self.shadow_log.append(self.reg_arena.allocator(), .{ .name = name, .prev = self.aliases.get(name), .aliased = true }) catch return;
        self.aliases.put(name, target) catch {};
    }

    /// A parameter is in `locals` without a `pending_locals` declaration.
    fn isParamLocal(self: *Emitter, name: []const u8) bool {
        if (!self.locals.contains(name)) return false;
        for (self.pending_locals.items) |l| if (std.mem.eql(u8, l.name, name)) return false;
        return true;
    }

    /// An arm's pattern binders alias names only for the arm: the aliases are
    /// put back as they were before it — a block's re-binding around the
    /// `case` stays (clearing them all lost it).
    fn restoreAliases(self: *Emitter, saved: std.StringHashMap([]const u8)) void {
        self.aliases.deinit();
        self.aliases = saved;
    }

    fn scopeMark(self: *Emitter) usize {
        return self.shadow_log.items.len;
    }

    /// The end of a statement list: every name it re-bound means what it
    /// meant before the list again.
    fn scopeRestore(self: *Emitter, mark: usize) void {
        while (self.shadow_log.items.len > mark) {
            const sh = self.shadow_log.pop().?;
            if (!sh.aliased) {
                _ = self.bound_names.remove(sh.name);
            } else if (sh.prev) |p| self.aliases.put(sh.name, p) catch {} else _ = self.aliases.remove(sh.name);
        }
    }

    fn declareLocal(self: *Emitter, name: []const u8, ty: Repr) !void {
        if (self.locals.contains(name)) return;
        try self.locals.put(name, ty);
        try self.pending_locals.append(self.alloc, .{ .name = name, .ty = ty });
    }

    /// The `(local …)` lines of the function being emitted: one declaration per
    /// line, in registration order.
    fn localLines(self: *Emitter) ![]const []const wat.Local {
        const ar = self.arena();
        const lines = try ar.alloc([]const wat.Local, self.pending_locals.items.len);
        for (self.pending_locals.items, 0..) |l, i| {
            const slot = try ar.alloc(wat.Local, 1);
            slot[0] = .{ .name = l.name, .ty = self.vtOf(l.ty) };
            lines[i] = slot;
        }
        return lines;
    }

    /// `$__mem{k}` — the scratch pointer an aggregate construction or a
    /// destructuring binding holds its base in.
    fn memName(self: *Emitter, k: u32) ![]const u8 {
        return std.fmt.allocPrint(self.arena(), "__mem{d}", .{k});
    }

    /// `$_res{k}` — the scratch pointer a Result/Option op holds its receiver in.
    fn resName(self: *Emitter, k: u32) ![]const u8 {
        return std.fmt.allocPrint(self.arena(), "_res{d}", .{k});
    }

    /// `$_try{k}` — the scratch pointer a `try`/`try…catch` holds its Result in.
    fn tryName(self: *Emitter, k: u32) ![]const u8 {
        return std.fmt.allocPrint(self.arena(), "_try{d}", .{k});
    }

    /// Push `{cur_result}.const 0` — the neutral value used whenever a context
    /// demands a value the lowered expression did not produce.
    fn pushZero(self: *Emitter) !void {
        try self.emit(self.zeroOf(self.cur_result));
    }

    /// `i32.const <n>` for a computed number: a data-segment offset, a variant
    /// tag, a byte count.
    fn constInt(self: *Emitter, value: anytype) !Instr {
        return .{ .@"const" = .{
            .ty = .i32,
            .text = try std.fmt.allocPrint(self.arena(), "{d}", .{value}),
        } };
    }

    /// The bytes a string literal stands for. The lexer keeps a literal's
    /// escape sequences verbatim (`q\"t`); a data segment holds the value
    /// (`q"t`), so `@print` writes the same bytes as commonJS and erlang.
    /// `\n \r \t \0 \\ \"` map to their byte, `\$` to `$`, `\u{hex}` to UTF-8.
    fn literalBytes(self: *Emitter, lexeme: []const u8) ![]const u8 {
        if (std.mem.indexOfScalar(u8, lexeme, '\\') == null) return lexeme;
        var out: std.ArrayListUnmanaged(u8) = .empty;
        var i: usize = 0;
        while (i < lexeme.len) : (i += 1) {
            const ch = lexeme[i];
            if (ch != '\\' or i + 1 >= lexeme.len) {
                try out.append(self.arena(), ch);
                continue;
            }
            i += 1;
            switch (lexeme[i]) {
                'n' => try out.append(self.arena(), '\n'),
                'r' => try out.append(self.arena(), '\r'),
                't' => try out.append(self.arena(), '\t'),
                '0' => try out.append(self.arena(), 0),
                'u' => if (i + 1 < lexeme.len and lexeme[i + 1] == '{') {
                    const close = std.mem.indexOfScalarPos(u8, lexeme, i + 2, '}') orelse {
                        try out.appendSlice(self.arena(), "\\u");
                        continue;
                    };
                    const cp = std.fmt.parseInt(u21, lexeme[i + 2 .. close], 16) catch {
                        try out.appendSlice(self.arena(), "\\u");
                        continue;
                    };
                    var buf: [4]u8 = undefined;
                    const n = std.unicode.utf8Encode(cp, &buf) catch {
                        try out.appendSlice(self.arena(), "\\u");
                        continue;
                    };
                    try out.appendSlice(self.arena(), buf[0..n]);
                    i = close;
                } else try out.appendSlice(self.arena(), "\\u"),
                else => |esc| try out.append(self.arena(), esc),
            }
        }
        return out.items;
    }

    fn internString(self: *Emitter, s: []const u8) !DataSeg {
        // A GC module has no address for a value (`emitStrLit`).
        if (self.mode == .gc) return self.gcFail("internString");
        for (self.data_segments.items) |seg| {
            if (seg.len == s.len and std.mem.eql(u8, seg.content, s)) return seg;
        }
        // Strings are length-prefixed: the value is a pointer to a 4-byte i32
        // length word, immediately followed by the raw bytes (at `offset + 4`).
        // This lets `.len`/`.slice` and concat operate on runtime strings without
        // carrying the length in a separate register.
        const seg = DataSeg{
            .offset = self.next_data_offset,
            .len = @intCast(s.len),
            .content = s,
        };
        self.next_data_offset += 4 + @as(u32, @intCast(s.len));
        if (self.next_data_offset % 4 != 0)
            self.next_data_offset += 4 - (self.next_data_offset % 4);
        try self.data_segments.append(self.alloc, seg);
        return seg;
    }

    // ── fn ───────────────────────────────────────────────────────────────────

    /// Synthetic name for a parameter the source did not name (a destructuring
    /// param such as `fn greet({ name, .. }: Person)`). Emitting `(param $ i32)`
    /// is a WAT parse error ("empty identifier").
    fn paramSymbol(self: *Emitter, p: ast.Param, idx: usize) ![]const u8 {
        if (p.name.len > 0) return p.name;
        return std.fmt.allocPrint(self.reg_arena.allocator(), "__p{d}", .{idx});
    }

    /// Bind a destructuring parameter's field names to locals at function
    /// entry: the parameter holds a pointer to a run of 4-byte slots, so each
    /// bound name is an `i32.load` at the field's declared offset.
    fn bindParamDestructure(self: *Emitter, p: ast.Param, symbol: []const u8, loc: ast.Loc) !void {
        const d = p.destruct orelse return;
        const rty = self.resolveRecordName(typeRefName(p.typeRef));
        switch (d) {
            .names => |n| for (n.fields, 0..) |fld, i| {
                try self.declareLocal(fld.bind_name, .i32);
                const off: u32 = if (rty) |r|
                    (self.fieldOffsetIn(r, fld.field_name) orelse @as(u32, @intCast(i * 4)))
                else
                    @as(u32, @intCast(i * 4));
                if (rty) |r| {
                    if (self.fieldTypeIn(r, fld.field_name)) |ft| {
                        if (self.resolveRecordName(ft)) |sub| try self.local_types.put(fld.bind_name, sub);
                        if (std.mem.eql(u8, ft, "string")) try self.str_locals.put(fld.bind_name, {});
                    }
                }
                try self.emit(.{ .local_get = symbol });
                try self.emitLoadOffset(off);
                try self.emit(.{ .local_set = fld.bind_name });
            },
            .tuple_ => |names| for (names, 0..) |name, i| {
                try self.declareLocal(name, .i32);
                try self.emit(.{ .local_get = symbol });
                try self.emitLoadOffset(@intCast(i * 4));
                try self.emit(.{ .local_set = name });
            },
            .list, .ctor => return self.refuse(loc, "the wasm backend has no lowering for a list or a constructor pattern in the parameter `{s}`", .{p.name}),
        }
    }

    /// Declare the pre-counted `$_try{n}` / `$__mem{n}` scratch pointers.
    fn declareScratch(self: *Emitter, prefix: []const u8, n: u32) !void {
        const ra = self.reg_arena.allocator();
        for (0..n) |i| {
            const name = try std.fmt.allocPrint(ra, "{s}{d}", .{ prefix, i });
            try self.declareLocal(name, .i32);
        }
    }

    /// Lower a function body into a detached sequence, tagged with what it
    /// leaves on the operand stack. Locals registered while lowering land in
    /// `pending_locals`, which the caller hands to the function node.
    ///
    /// The tag is what makes a void function with a leftover value — and a
    /// value-returning one with no `(result …)` — impossible to build: the
    /// stack here is checked against the signature by `wat_ast.Builder.func`.
    fn renderBody(self: *Emitter, body: []const ast.Stmt, prologue: ?ast.FnDecl) !Seq {
        var c: Capture = .{};
        self.open(&c);
        if (prologue) |f| {
            for (f.params, 0..) |p, i| {
                if (p.destruct == null) continue;
                // A parameter carries no location of its own: the body's first
                // statement stands for the signature.
                const loc: ast.Loc = if (body.len > 0) body[0].expr.getLoc() else f.returnTypeLoc;
                try self.bindParamDestructure(p, try self.paramSymbol(p, i), loc);
            }
        }
        const tail_type: ?Repr = if (self.fn_has_result and body.len > 0)
            (if (self.mode == .gc and self.adoptsTask(body[ast.lastRealIndex(body)].expr)) self.cur_result else self.wasmTypeOf(body[ast.lastRealIndex(body)].expr))
        else
            null;
        self.defer_fn_body = body;
        const tail = try self.emitBody(body, self.fn_has_result);
        if (self.fn_has_result and tail == .none) try self.pushZero();
        // An implicit tail value has to meet the declared `(result …)` too.
        if (self.fn_has_result and tail == .value) {
            // A tail that cannot return (`@panic`) leaves the stack polymorphic.
            const last_e: ?ast.Expr = if (body.len > 0) body[ast.lastRealIndex(body)].expr else null;
            const leaves = if (last_e) |le| le == .jump and (le.jump.kind == .@"return" or le.jump.kind == .throw_) else false;
            const no_return = self.mode == .gc and last_e != null and (isNoReturnCall(last_e.?) or leaves);
            // Front 164 s2 P4 — a function declaring no answer whose last
            // statement makes a task (`pub fn main() { run(); }`): the word
            // linear memory answered was the task's address, which nothing
            // reads; here the task is dropped for the `0`.
            const dropped_task = self.mode == .gc and tail_type != null and tail_type.? == .ref and tail_type.?.ref == .task and !self.cur_result.isRef() and prologue != null and prologue.?.returnType == null;
            if (dropped_task) {
                try self.emit(.drop);
                try self.emit(self.zeroOf(self.cur_result));
            } else if (tail_type) |t| if (!no_return) try self.emitConvert(t, self.cur_result);
        }
        // `emitBody` normalises: with a result the tail is a value (or the
        // body terminated), without one it is nothing (or terminated).
        const stack: wat.Stack = if (tail == .terminated)
            .terminated
        else if (self.fn_has_result)
            .{ .value = self.vtOf(self.cur_result) }
        else
            .none;
        return self.seal(&c, stack);
    }

    fn renderAccumulatingBody(self: *Emitter, body: []const ast.Stmt) !Seq {
        var c: Capture = .{};
        self.open(&c);
        const tgt = "__yield_fn";
        if (self.mode == .gc) {
            // A generator fn answers the array of what it yields: of its
            // declared result's class.
            if (!self.cur_result.isArrRef()) return self.gcFail("a generator fn of no array result");
            self.gen_repr = self.cur_result;
            try self.declareLocal(tgt, self.gen_repr);
            try self.emit(zero);
            try self.emit(.{ .array_new_default = self.gcTyIndex(.{ .arr = self.gen_repr.ref.arr }) });
            try self.emit(.{ .local_set = tgt });
        } else {
            try self.declareLocal(tgt, .i32);
            try self.emit(zero);
            try self.emit(self.builder().helper(.arr_new));
            try self.emit(.{ .local_set = tgt });
        }
        self.yield_target = tgt;
        defer self.yield_target = null;
        const tail = try self.emitBody(body, false);
        if (tail != .terminated) {
            try self.emitC(.{ .local_get = tgt }, "everything the body yielded");
            try self.emitConvert(if (self.mode == .gc) self.gen_repr else .i32, self.cur_result);
        }
        return self.seal(&c, if (tail == .terminated) .terminated else .{ .value = self.vtOf(self.cur_result) });
    }

    /// A `declare fn` decision 238's vocabulary binds: the form, and for
    /// `fn:` the name the private fn is emitted under (a linked module's
    /// function may be mangled, `<module>/<name>`).
    const HostBound = struct {
        binding: hostBinding.Binding,
        target: []const u8 = "",
        /// Decision 518 — the binding's `needs:`.
        needs: ast.WasmNeeds = .initEmpty(),
    };

    /// Decision 238 — every `#[@External.Wasm("…")]` of the program and its
    /// linked modules is read before anything is registered: `op:` against
    /// the opcode table and the signature, `fn:` against the declaring
    /// module's own functions (a private bodied `fn` with the same
    /// parameter and return types), `wasi:` against the adapter list. A
    /// binding outside the vocabulary is refused at its annotation, in a
    /// linked module at the consumer's import (`foreign_origin`). A
    /// `declare fn` with no wasm binding is left to `external_missing`.
    fn checkHostBindings(
        self: *Emitter,
        decls: []const ast.DeclKind,
        owner: []const usize,
        linked: []const Linked,
        own_program: ast.Program,
        module_name: []const u8,
    ) !void {
        defer self.foreign_origin = null;
        for (decls, owner) |d, from| {
            const f = switch (d) {
                .@"fn" => |f| f,
                else => continue,
            };
            if (!f.isDeclare or f.body.len > 0) continue;
            // Decision 334: every wasm binding is read and checked, whichever
            // host it serves — a misspelt `.Browser` binding is refused on a
            // `wasi` build too —, and the one serving this build's host is
            // the one recorded.
            const build_host = ast.ExternalLookup.of(self.external_lookup).host orelse .wasi;
            for (f.implementations) |ext| {
                if (ext.target != .wasm) continue;
                const host = ext.host;
                var bound = try self.checkHostBinding(f, from, ext, ext.loc, linked, own_program, module_name);
                bound.needs = ext.needs();
                if (host == null or host.? == build_host) {
                    try self.host_bindings.put(self.alloc, f.name, bound);
                    if (f.genericParams.len > 0) try self.host_generic_decls.put(self.alloc, f.name, f);
                    self.needs.setUnion(bound.needs);
                }
            }
        }
    }

    /// One `#[@External.Wasm(…)]` of `f`, read and checked (decisions 238 and 440:
    /// its four forms); `from` indexes `linked` for a linked module's `fn`.
    fn checkHostBinding(
        self: *Emitter,
        f: ast.FnDecl,
        from: usize,
        ext: ast.Implementation,
        ann_loc: ?ast.Loc,
        linked: []const Linked,
        own_program: ast.Program,
        module_name: []const u8,
    ) !HostBound {
        const ar = self.arena();
        self.foreign_origin = if (from < linked.len) linked[from].via else null;
        const parsed = try hostBinding.parse(ar, ext.text, try hostBinding.signatureOf(ar, f));
        const binding = switch (parsed) {
            .refused => |r| return self.refuse(ann_loc, "{s} (on `{s}`)", .{ r.message, f.name }),
            .ok => |b| b,
        };
        var bound: HostBound = .{ .binding = binding };
        if (binding == .std_) {
            // Decision 440 (3): the declaration's types are the function's,
            // exactly (the checker refuses a mismatch on every target).
            var spelled: std.ArrayListUnmanaged([]const u8) = .empty;
            for (f.params) |p| {
                if (std.mem.eql(u8, p.name, "self")) continue;
                try spelled.append(ar, stdSpelling(p.typeRef));
            }
            const r: ?[]const u8 = if (f.returnType) |rt| stdSpelling(rt) else null;
            if (binding.std_.wasm) |ex| if (!stdWasm.matches(ex, spelled.items, r)) {
                var buf: [128]u8 = undefined;
                return self.refuse(ann_loc, "`.Wasm({s})` on `{s}`: std-wasm's `{s}` is `{s}`, and the declared parameters and return must be exactly those types", .{ try ast.wasmCellDisplay(ar, ext.text), f.name, binding.std_.name, stdWasm.signatureText(ex, &buf) });
            };
            // Front 164 s3 — a leaf with no std-wasm export beside it: a GC
            // module's alone, its GC signature the declaration's.
            if (binding.std_.wasm == null) try self.checkLeafSignature(f, binding.std_, ext, ann_loc);
        }
        if (binding == .fn_) {
            const name = binding.fn_;
            const prog = if (from < linked.len) linked[from].program else own_program;
            const mod_name = if (from < linked.len) linked[from].name else module_name;
            switch (try hostFnBinding.resolve(ar, f, name, prog, if (from < linked.len) mod_name else "", "Wasm")) {
                .refused => |message| return self.refuse(ann_loc, "{s}", .{message}),
                .ok => {},
            }
            bound.target = if (from < linked.len)
                (self.link_mangled.get(try linkKey(ar, mod_name, name)) orelse name)
            else
                name;
        }
        return bound;
    }

    /// The element type of `T[]` / `Array<T>`.
    fn arrayElemRef(t: ast.TypeRef) ?ast.TypeRef {
        return switch (t) {
            .array => |el| el.*,
            .generic => |g| if (std.mem.eql(u8, g.name, "Array") and g.args.len == 1) g.args[0] else null,
            else => null,
        };
    }

    /// Decision 393 — a task adapter carries its `T` in the task's word, so a
    /// float or an `i64` `T` reaching one is refused where the call is
    /// written: `delay`'s value by `lowerCoerced`, the tasks handed to `race`,
    /// `race_of` and `spawn_all` here.
    fn refuseWideTaskValues(self: *Emitter, cc: anytype) !void {
        for (cc.args) |a| {
            const arg = a.value.*;
            if (arg == .collection and arg.collection.kind == .arrayLit) for (arg.collection.kind.arrayLit.elems) |el| {
                const tail: ast.Expr = if (el == .function and el.function.kind.syntax == .lambda and el.function.kind.body.len > 0)
                    el.function.kind.body[ast.lastRealIndex(el.function.kind.body)].expr
                else
                    el;
                if (!self.isTaskExpr(tail)) continue;
                const ty = self.awaitedType(tail);
                if (!ty.isWord())
                    return self.refuse(el.getLoc(), "`{s}` carries a task's value in one word on wasm: a task answering an `{s}` has no lowering here (decision 393)", .{ cc.callee, ty.name() });
            };
            const t = self.typeRefOf(arg) orelse continue;
            const el = arrayElemRef(t) orelse continue;
            const v = taskValueTypeRef(el) orelse (if (el == .function) taskValueTypeRef(el.function.returnType.*) else null) orelse continue;
            const ty = watType(v);
            if (!ty.isWord())
                return self.refuse(arg.getLoc(), "`{s}` carries a task's value in one word on wasm: a task answering an `{s}` has no lowering here (decision 393)", .{ cc.callee, ty.name() });
        }
    }

    /// Front 164 s2 P4 — `spawn_all`'s GC form settles with an `arr_any` of
    /// its tasks' answers: a call whose answers are scalars (an array of
    /// words or floats, `arr_i32` / `arr_f64` here), or whose answers nothing
    /// types, keeps its module in linear memory.
    fn gcSpawnAllAnswers(self: *Emitter, cc: anytype) !void {
        if (cc.args.len != 1) return self.gcFail("a spawn_all of no task list");
        const t = self.typeRefOf(cc.args[0].value.*) orelse return self.gcFail("a spawn_all over thunks of no known type");
        const el = arrayElemRef(t) orelse return self.gcFail("a spawn_all over thunks of no known type");
        if (el != .function) return self.gcFail("a spawn_all over thunks of no known type");
        const v = taskValueTypeRef(el.function.returnType.*) orelse return self.gcFail("a spawn_all over thunks of no known type");
        if (gcElemClassOf(self.reprOf(v)) != .any) return self.gcFail("a spawn_all of scalar answers");
    }

    /// A call of the std-wasm function `name` (`text.trim`), which the module
    /// then links (decision 440, `std_wasm_link.zig`).
    fn stdCall(self: *Emitter, name: []const u8) !Instr {
        // A GC module marshals what crosses into std-wasm (`emitStdCall`).
        if (self.mode == .gc) return self.gcFail(name);
        return self.stdCallLinked(name);
    }

    fn stdCallLinked(self: *Emitter, name: []const u8) !Instr {
        try self.std_exports.put(self.alloc, name, {});
        return .{ .call = try stdWasmLink.entryName(self.arena(), name) };
    }

    /// A call of the std-wasm function `name`, its arguments on the stack. In
    /// a GC module (front 164 s2, decision 544) the values cross into
    /// std-wasm's linear memory marshalled: each string argument copied into
    /// the marshal arena (`$__gc_to_lin_str`), a string answer copied out into
    /// a GC string (`$__lin_to_gc_str`), and the arena — everything std-wasm
    /// allocated too — put back after the call. std-wasm never calls back, so
    /// nothing it allocated outlives the call.
    fn emitStdCall(self: *Emitter, name: []const u8) !void {
        // Front 164 s3: a GC module calls a `.wat` leaf with its own values —
        // no marshal, nothing in linear memory.
        if (self.mode == .gc) if (stdLeaves.find(name)) |_| {
            try self.noteLeaf(name);
            return self.emit(.{ .call = try stdLeaves.symbol(self.arena(), name) });
        };
        const call = try self.stdCallLinked(name);
        if (self.mode == .linear) return self.emit(call);
        const ex = gcStdSig(name) orelse return self.gcFail(name);
        const slots = try self.arena().alloc([]const u8, ex.params.len);
        var i = ex.params.len;
        while (i > 0) {
            i -= 1;
            slots[i] = try self.gcTemp(try stdRepr(ex.params[i]));
            try self.emit(.{ .local_set = slots[i] });
        }
        const top = try self.gcTemp(.i32);
        try self.emit(.{ .global_get = heap_ptr });
        try self.emit(.{ .local_set = top });
        for (ex.params, slots) |t, slot| {
            try self.emit(.{ .local_get = slot });
            switch (t) {
                .string, .bytes => try self.emit(self.builder().helper(.gc_to_lin_str)),
                .string_array => try self.emit(.{ .call = try self.gcMarshalStrs(true) }),
                .opt_string, .opt_bytes => {
                    // Absent is the word `0`; a string is copied out.
                    var absent: Capture = .{};
                    self.open(&absent);
                    try self.emit(zero);
                    const absent_seq = self.seal(&absent, .{ .value = .i32 });
                    var present: Capture = .{};
                    self.open(&present);
                    try self.emit(.{ .local_get = slot });
                    try self.emit(self.builder().helper(.gc_to_lin_str));
                    const present_seq = self.seal(&present, .{ .value = .i32 });
                    try self.emit(.ref_is_null);
                    try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = absent_seq }, .@"else" = .{ .seq = present_seq } } });
                },
                .opt_i32 => try self.emit(.{ .call = try self.gcMarshalOptI32(true) }),
                .i32, .i64, .f64, .void => {},
            }
        }
        try self.emit(call);
        switch (ex.result) {
            .string, .bytes => try self.emit(self.builder().helper(.lin_to_gc_str)),
            .string_array => try self.emit(.{ .call = try self.gcMarshalStrs(false) }),
            .opt_string, .opt_bytes => {
                const tmp = try self.gcTemp(.i32);
                try self.emit(.{ .local_tee = tmp });
                try self.emit(opOf(.i32, "eqz"));
                var absent: Capture = .{};
                self.open(&absent);
                try self.emit(.{ .ref_null = prelude.gc_str_ref });
                const absent_seq = self.seal(&absent, .{ .value = prelude.gc_str_ref });
                var present: Capture = .{};
                self.open(&present);
                try self.emit(.{ .local_get = tmp });
                try self.emit(self.builder().helper(.lin_to_gc_str));
                const present_seq = self.seal(&present, .{ .value = prelude.gc_str_ref });
                try self.emit(.{ .@"if" = .{ .result = prelude.gc_str_ref, .then = .{ .seq = absent_seq }, .@"else" = .{ .seq = present_seq } } });
            },
            .opt_i32 => try self.emit(.{ .call = try self.gcMarshalOptI32(false) }),
            .i32, .i64, .f64, .void => {},
        }
        try self.emit(.{ .local_get = top });
        try self.emit(.{ .global_set = heap_ptr });
    }

    /// Front 164 s3 (decision 549) — the index of the codegen's GC type a
    /// `.wat` leaf names (`str`, `arr_any`, …), declaring it in the module's
    /// group on first use; null for a name the codegen gives no fixed type
    /// (a record's, a variant's: the program's own).
    fn leafTypeIndex(ctx: *anyopaque, name: []const u8) ?u16 {
        const self: *Emitter = @ptrCast(@alignCast(ctx));
        if (std.mem.eql(u8, name, prelude.gc_str_def.name)) {
            self.gc_str_used = true;
            return prelude.gc_str_index;
        }
        const fixed = [_]struct { []const u8, GcTy }{
            .{ "arr_i32", .{ .arr = .i32 } },
            .{ "arr_f64", .{ .arr = .f64 } },
            .{ "arr_any", .{ .arr = .any } },
            .{ "box_i32", .{ .box = .i32 } },
            .{ "box_i64", .{ .box = .i64 } },
            .{ "box_f64", .{ .box = .f64 } },
            .{ "result", .result },
        };
        for (fixed) |x| if (std.mem.eql(u8, x[0], name)) return self.gcTyIndex(x[1]);
        return null;
    }

    /// A leaf the module calls: held once (the leaves it calls are added, in
    /// order, by `leafFuncs`), and the helper groups of the prelude's functions
    /// and globals it and those leaves name required now (decision 585 (i),
    /// (j)), before the module's items are laid out.
    fn noteLeaf(self: *Emitter, name: []const u8) anyerror!void {
        if (self.std_leaves.contains(name)) return;
        try self.std_leaves.put(self.alloc, name, stdLeaves.find(name).?);
        var seen: std.StringHashMapUnmanaged(void) = .empty;
        try self.requireLeafPrelude(name, &seen);
    }

    fn requireLeafPrelude(self: *Emitter, name: []const u8, seen: *std.StringHashMapUnmanaged(void)) anyerror!void {
        if ((try seen.fetchPut(self.arena(), name, {})) != null) return;
        var calls: std.ArrayListUnmanaged([]const u8) = .empty;
        stdLeaves.refs(self.arena(), stdLeaves.find(name).?, &calls) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.Unreadable => return,
        };
        for (calls.items) |n| {
            if (stdLeaves.preludeGroup(n)) |g| self.b.helpers.require(g) else try self.requireLeafPrelude(n, seen);
        }
    }

    /// The leaf `leaf` read into this module (front 164 s3), and the names of
    /// the leaves it calls appended to `calls`. A leaf that does not read is
    /// refused with its located message (`path:line:col`).
    fn readLeaf(self: *Emitter, leaf: stdLeaves.Leaf, calls: *std.ArrayListUnmanaged([]const u8)) !wat.Func {
        var diag: watReader.Diag = .{};
        return stdLeaves.read(self.arena(), leaf, .{ .ctx = self, .index = leafTypeIndex }, calls, &diag) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.Unreadable => return self.refuse(null, "std-wasm's leaf `{s}` does not read: {s}", .{ leaf.name, try diag.text(self.arena()) }),
        };
    }

    /// Every leaf the module calls, read, with the leaves those call — each
    /// once, in the order first called.
    fn leafFuncs(self: *Emitter) ![]const wat.Func {
        const ar = self.arena();
        var out: std.ArrayListUnmanaged(wat.Func) = .empty;
        var i: usize = 0;
        while (i < self.std_leaves.count()) : (i += 1) {
            var calls: std.ArrayListUnmanaged([]const u8) = .empty;
            try out.append(ar, try self.readLeaf(self.std_leaves.values()[i], &calls));
            for (calls.items) |n| if (stdLeaves.preludeGroup(n) == null and !self.std_leaves.contains(n))
                try self.std_leaves.put(self.alloc, n, stdLeaves.find(n).?);
        }
        return out.items;
    }

    /// Front 164 s3 — a `std:` cell naming a leaf with no std-wasm export
    /// beside it: a WasmGC module's alone, and the declaration's types, as the
    /// module holds them, are the leaf's parameters and result.
    fn checkLeafSignature(self: *Emitter, f: ast.FnDecl, b: hostBinding.Std, ext: ast.Implementation, ann_loc: ?ast.Loc) !void {
        const ar = self.arena();
        const shown = try ast.wasmCellDisplay(ar, ext.text);
        if (self.mode == .linear)
            return self.refuse(ann_loc, "`.Wasm({s})` on `{s}`: `{s}` is a `.wat` leaf of std-wasm, which a module in linear memory cannot call", .{ shown, f.name, b.name });
        var calls: std.ArrayListUnmanaged([]const u8) = .empty;
        const leaf = try self.readLeaf(b.leaf.?, &calls);
        var ok = true;
        var k: usize = 0;
        for (f.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            if (k >= leaf.params.len or self.vtOf(self.reprOf(p.typeRef)) != leaf.params[k].ty) ok = false;
            k += 1;
        }
        if (k != leaf.params.len) ok = false;
        const declared: ?ValType = if (f.returnType) |rt| (if (std.mem.eql(u8, stdSpelling(rt), "void")) null else self.vtOf(self.reprOf(rt))) else null;
        if (declared != leaf.result) ok = false;
        if (!ok) return self.refuse(ann_loc, "`.Wasm({s})` on `{s}`: the leaf `{s}` takes and answers other types than the declaration's", .{ shown, f.name, b.name });
    }

    /// What crosses the std-wasm boundary in a GC module (the `stdWasm.Type`s
    /// that have a marshal).
    const GcStd = enum { string, bytes, i32, i64, f64, void, string_array, opt_string, opt_bytes, opt_i32 };

    fn gcStdTy(t: stdWasm.Type) ?GcStd {
        return switch (t) {
            .string => .string,
            .bytes => .bytes,
            .i32, .bool => .i32,
            .i64 => .i64,
            .f64 => .f64,
            .void => .void,
            .string_array => .string_array,
            .opt_string => .opt_string,
            .opt_bytes => .opt_bytes,
            .opt_i32 => .opt_i32,
            else => null,
        };
    }

    /// What crosses into the std-wasm function `name` and back, typed: a
    /// `std:` export's own signature, or — for a function of std-wasm's
    /// program face, whose words are the codegen's (`std_wasm.program`) —
    /// what its words are here. Null for a function whose words have no GC
    /// marshal yet (an array's, a `bigint`'s).
    fn gcStdSig(name: []const u8) ?struct { params: []const GcStd, result: GcStd } {
        const Sig = struct { []const u8, []const GcStd, GcStd };
        const sigs = [_]Sig{
            .{ "text.slice", &.{ .string, .i32, .i32 }, .string },
            // `Bytes` is a string's layout.
            .{ "bytes.slice", &.{ .bytes, .i32, .i32 }, .bytes },
            .{ "bytes.isUtf8", &.{.bytes}, .i32 },
        };
        for (sigs) |sig| if (std.mem.eql(u8, sig[0], name)) return .{ .params = sig[1], .result = sig[2] };
        if (stdWasm.find(name)) |e| {
            const static = struct {
                var buf: [8]GcStd = undefined;
            };
            if (e.params.len > static.buf.len) return null;
            for (e.params, 0..) |t, k| static.buf[k] = gcStdTy(t) orelse return null;
            return .{ .params = static.buf[0..e.params.len], .result = gcStdTy(e.result) orelse return null };
        }
        return null;
    }

    /// The value a std-wasm parameter or answer of type `t` is in a GC
    /// module; a shape the marshal has no form for yet falls back.
    fn stdRepr(t: GcStd) !Repr {
        return switch (t) {
            .string, .opt_string => Repr.string,
            .bytes, .opt_bytes => .{ .ref = .bytes },
            .i32 => .i32,
            .i64 => .i64,
            .f64 => .f64,
            .string_array => .{ .ref = .{ .arr = .any } },
            .opt_i32 => .{ .ref = .unknown },
            .void => error.GcFallback,
        };
    }

    /// A written type as a `std:` binding's check spells it (decision 440
    /// (3), `std_wasm.matches`): a plain name, `string[]`, `?string`, `?i32`
    /// and `@Result<i64 | f64 | T, string>` as `std_wasm.Type` spells them,
    /// anything else `another type`.
    fn stdSpelling(t: ast.TypeRef) []const u8 {
        return switch (t) {
            .named => |n| n,
            .array => |e| if (std.mem.eql(u8, stdSpelling(e.*), "string")) "string[]" else "another type",
            .optional => |e| blk: {
                const inner = stdSpelling(e.*);
                if (std.mem.eql(u8, inner, "string")) break :blk "?string";
                if (std.mem.eql(u8, inner, "Bytes")) break :blk "?Bytes";
                if (std.mem.eql(u8, inner, "i32")) break :blk "?i32";
                break :blk "another type";
            },
            .generic => |g| blk: {
                if (!g.is_builtin or !std.mem.endsWith(u8, g.name, "Result") or g.args.len != 2) break :blk "another type";
                if (!std.mem.eql(u8, stdSpelling(g.args[1]), "string")) break :blk "another type";
                const ok = stdSpelling(g.args[0]);
                if (std.mem.eql(u8, ok, "i64")) break :blk "@Result<i64, string>";
                if (std.mem.eql(u8, ok, "f64")) break :blk "@Result<f64, string>";
                if (std.mem.eql(u8, ok, "T")) break :blk "@Result<T, string>";
                break :blk "another type";
            },
            else => "another type",
        };
    }

    /// The function a bound `declare fn` lowers to — its declared name and
    /// signature (`registerFn` registered both), the parameters passed in
    /// order: `op:` applies the instruction to them, `fn:` calls the private
    /// fn, `wasi:` calls the adapter's prelude helper.
    fn emitHostBinding(self: *Emitter, f: ast.FnDecl, hb: HostBound) !void {
        // Decision 518 (2): a binding the first pass found nothing reaching,
        // whose needs the program does not otherwise ask for, is not emitted.
        if (self.skip_wrappers) |skip| if (skip.contains(f.name)) return;
        if (hb.needs.count() > 0) try self.wrapper_needs.put(self.alloc, f.name, hb.needs);
        const ar = self.arena();
        const sig = self.fn_sigs.get(f.name).?;
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        var lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        var i: usize = 0;
        for (f.params, 0..) |p, k| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            const sym = try self.paramSymbol(p, k);
            try params.append(ar, wat.Builder.param(sym, self.vtOf(sig.params[i])));
            try lines.append(ar, .{ .indent = 4, .instr = .{ .local_get = sym } });
            i += 1;
        }
        // A GC module marshals a `std:` call (`emitStdCall`): the wrapper
        // writes it, with the locals it needs.
        const gc_std = self.mode == .gc and hb.binding == .std_;
        if (gc_std) {
            self.resetFnState(null);
            var cap: Capture = .{};
            self.open(&cap);
            try self.emitStdCall(hb.binding.std_.name);
            const seq = self.seal(&cap, .none);
            try lines.appendSlice(ar, seq.lines);
        }
        const call: wat.Instr = switch (hb.binding) {
            .op => |op| hostBinding.instrOf(op),
            .fn_ => .{ .call = hb.target },
            .std_ => |e| if (gc_std) .{ .comment = if (e.leaf != null) "a .wat leaf's call" else "marshalled std-wasm call" } else try self.stdCall(e.name),
            .wasi => |ad| blk: {
                if (std.mem.eql(u8, ad.name, "random_f64")) break :blk self.builder().helper(.wasi_random_f64);
                if (std.mem.eql(u8, ad.name, "delay")) break :blk self.builder().helper(.task_delay);
                if (std.mem.eql(u8, ad.name, "race")) break :blk self.builder().helper(.task_race);
                if (std.mem.eql(u8, ad.name, "race_of")) {
                    self.uses_table = true;
                    if (self.mode == .gc) break :blk self.gcTaskHelper(.task_race_of, .task_race, "__task_race_of");
                    break :blk self.builder().helper(.task_race_of);
                }
                if (std.mem.eql(u8, ad.name, "spawn_all")) {
                    self.uses_table = true;
                    if (self.mode == .gc) break :blk self.gcTaskHelper(.task_spawn_all, .task, "__task_spawn_all");
                    break :blk self.builder().helper(.task_spawn_all);
                }
                if (std.mem.eql(u8, ad.name, "gate_new")) break :blk self.builder().helper(.task_gate_new);
                if (std.mem.eql(u8, ad.name, "gate_open")) break :blk self.builder().helper(.task_gate_open);
                if (std.mem.eql(u8, ad.name, "gate_await")) break :blk self.builder().helper(.task_gate_await);
                if (std.mem.eql(u8, ad.name, "attempt")) {
                    self.uses_table = true;
                    break :blk self.builder().helper(.wasi_attempt);
                }
                unreachable; // every listed adapter has its helper (`host_binding.zig` `adapters`)
            },
        };
        if (!gc_std) try lines.append(ar, .{ .indent = 4, .instr = call });
        const result: ?ValType = if (sig.result) |r| self.vtOf(r) else null;
        // A written `-> void` registers an `i32` result like every function
        // declaring one (`fnHasResult`); a function answering nothing (std's
        // `random.seed`) leaves the stack empty, so the wrapper answers the
        // 0 the caller drops.
        const yields = switch (hb.binding) {
            .wasi => |ad| ad.result != null or ad.task != null,
            .std_ => |e| if (e.wasm) |ex| ex.result != .void else blk: {
                var calls: std.ArrayListUnmanaged([]const u8) = .empty;
                break :blk (try self.readLeaf(e.leaf.?, &calls)).result != null;
            },
            else => true,
        };
        if (result != null and !yields) try lines.append(ar, .{ .indent = 4, .instr = self.zeroOf(sig.result.?) });
        try self.itemCommentF("{s} — .Wasm({s})", .{ f.name, try ast.wasmCellDisplay(ar, f.externalFor(self.external_lookup).?.text) });
        try self.item(.{ .func = try self.builder().func(.{
            .name = f.name,
            .exports = if (f.isPub) try ar.dupe([]const u8, &.{f.name}) else &.{},
            .params = params.items,
            .result = result,
            .locals = if (gc_std) try self.localLines() else &.{},
            .body = .{ .stack = if (result) |r| .{ .value = r } else .none, .lines = lines.items },
        }) });
    }

    /// Front 164 s2 P4 — the call of a combinator's GC form, which builds its
    /// tasks' array as a GC array: the group without the linear `arr_new`
    /// its linear form calls.
    fn gcTaskHelper(self: *Emitter, g: wat.HelperGroup, dep: wat.HelperGroup, symbol: []const u8) Instr {
        self.b.helpers.groups.insert(g);
        self.b.helpers.require(dep);
        return .{ .call = symbol };
    }

    fn emitFn(self: *Emitter, f: ast.FnDecl) !void {
        // A bodyless `declare fn` (host-backed FFI, `#[@External.…]`) has no
        // wasm implementation. Emitting `(func $f (result f64))` with an empty
        // body is invalid, so skip it entirely — a call of it is refused
        // (`lowerPlainCall`).
        if (self.host_bindings.get(f.name)) |hb| return self.emitHostBinding(f, hb);
        if (isBodyless(f)) {
            try self.itemCommentF("declare fn {s} — no wasm implementation (host-backed)", .{f.name});
            return;
        }
        const has_result = fnHasResult(f);
        // Decision 392 — `-> @Task<T>`: the body is a state machine whose
        // answer is the task's `T` (`emitStateMachine`).
        const is_task = if (f.returnType) |rt| isTaskTypeRef(rt) else false;
        self.fn_tparams = f.genericParams;
        self.resetFnState(if (is_task) self.reprOfOpt(taskValueTypeRef(f.returnType.?)) else if (has_result) self.reprOfOpt(f.returnType) else null);
        defer self.fn_tparams = &.{};
        const outer_template = self.cur_template;
        self.cur_template = if (!self.in_spec and f.genericParams.len > 0) f.name else null;
        defer self.cur_template = outer_template;
        self.fn_returns_result = (f.effect != null and f.effect.? == .result) or
            (if (f.returnType) |rt| resultShapeOfTypeRef(rt) != null else false);

        // An effect fn is async/generator — except `-> @Result` (the
        // checked-Result value), which is a plain function. A `@Task<T>` is
        // a state machine over the scheduler (decision 392); an `@Iterator` /
        // `@Stream` runs eagerly. `-> @Component` is a plain function too
        // (decision 88: it gates `use`).
        if (f.effect != null and f.effect.? != .result and f.effect.? != .component) {
            try self.itemComment(switch (f.effect.?) {
                .task => "@Task — a state machine (decision 392)",
                .iterator => if (self.mode == .gc) "@Iterator — a generator state machine (decision 105)" else "@Iterator — eager lowering",
                else => if (self.mode == .gc) "@Stream — a generator state machine (decision 105)" else "@Stream — eager lowering",
            });
        }
        // Params, and the locals the body needs, are registered *before* the
        // body is rendered so identifier lowering can tell a local from a global.
        for (f.params, 0..) |p, i| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            const sym = try self.paramSymbol(p, i);
            const t = self.reprOf(p.typeRef);
            try self.locals.put(sym, t);
            const tn = typeRefName(p.typeRef);
            if (self.resolveRecordName(tn)) |rty|
                try self.local_types.put(sym, rty);
            try self.noteParamShape(sym, p.typeRef);
            try self.local_typerefs.put(sym, p.typeRef);
        }
        self.cur_ret_typeref = f.returnType;
        self.raw_return = scopeCarry.isWrapper(f.name);
        try self.declareScratch("_try", countTrys(f.body));
        try self.declareScratch("__mem", self.countMems(f.body));
        try self.emitLocalDecls(f.body);
        if (is_task) try self.beginMachine(f.body);
        defer self.machine = null;

        // An `@Iterator` / `@Stream` body runs eagerly: every `yield` is
        // appended to one array, which is what the fn returns.
        const accumulates = if (f.effect) |e|
            (e == .iterator or e == .stream) and has_result and bodyYieldsDeep(f.body)
        else
            false;
        // Decision 105 (144 B-128) — in a GC module an `@Iterator<T>` body
        // is a generator machine instead (§ generators).
        const is_gen = accumulates and self.mode == .gc and f.returnType != null and isIteratorTypeRef(f.returnType.?);
        if (is_gen) try self.beginGenMachine(f.body, self.genItemOfTypeRef(f.returnType.?.generic.args[0]), f.label);
        // A state machine's `return f(…)` answers a task: it is never a loop.
        if (!accumulates and !is_task) try self.noteSelfTailCalls(f);
        const rendered = if (is_gen) try self.renderGenBody(f.body) else if (accumulates) try self.renderAccumulatingBody(f.body) else try self.renderBody(f.body, f);
        const body = if (self.tail_self_used) try self.wrapTailLoop(rendered) else rendered;

        const ar = self.arena();
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        for (f.params, 0..) |p, i| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            try params.append(ar, wat.Builder.param(try self.paramSymbol(p, i), self.vtOf(self.reprOf(p.typeRef))));
        }
        const func = try self.builder().func(.{
            .name = f.name,
            .exports = if (f.isPub) try ar.dupe([]const u8, &.{f.name}) else &.{},
            .params = params.items,
            .result = if (is_gen) .i32 else if (has_result or is_task) self.vtOf(self.cur_result) else null,
            .locals = try self.localLines(),
            .body = body,
        });
        if (is_task) return self.emitStateMachine(func);
        if (is_gen) return self.emitGenMachine(func, null);
        try self.item(.{ .func = func });
    }

    /// Emit each `implement`/`extend` method as a linear-memory function
    /// `$<target>_<method>`. Unlike `emitFn`, the receiver `self` is kept as a
    /// real `i32` param (records/structs are heap pointers) so an activated
    /// `recv.m(args)` dispatch can pass it. Codegen is untyped and method
    /// bodies carry no return type, so params/result default to `i32`; a method
    /// whose body yields no value is emitted without a result.
    fn emitExtensionMethods(self: *Emitter, target: []const u8, methods: []const ast.ImplementMethod) !void {
        for (methods) |m| {
            const has_result = methodHasResult(m.body);
            self.resetFnState(if (has_result) .i32 else null);
            // `self.field` inside an extension method walks the target record's
            // declared field layout.
            self.self_type = if (self.records.contains(target)) target else null;
            defer self.self_type = null;
            const qualifier = m.qualifier orelse target;
            for (m.params, 0..) |p, i| {
                const sym = try self.paramSymbol(p, i);
                try self.locals.put(sym, .i32);
                if (std.mem.eql(u8, p.name, "self")) {
                    if (self.self_type) |st| try self.local_types.put("self", st);
                } else {
                    const tn = typeRefName(p.typeRef);
                    if (self.resolveRecordName(tn)) |rty|
                        try self.local_types.put(sym, rty);
                    try self.noteParamShape(sym, p.typeRef);
                }
            }
            try self.declareScratch("_try", countTrys(m.body));
            try self.declareScratch("__mem", self.countMems(m.body));
            try self.emitLocalDecls(m.body);

            const body = try self.renderBody(m.body, null);

            const ar = self.arena();
            var params: std.ArrayListUnmanaged(wat.Param) = .empty;
            for (m.params, 0..) |p, i| {
                try params.append(ar, wat.Builder.param(try self.paramSymbol(p, i), .i32));
            }
            try self.item(.{ .func = try self.builder().func(.{
                .name = try std.fmt.allocPrint(ar, "{s}_{s}", .{ qualifier, m.name }),
                .params = params.items,
                .result = if (has_result) .i32 else null,
                .locals = try self.localLines(),
                .body = body,
            }) });
        }
    }

    /// Record / struct member methods emitted as `$<owner>_<method>` linear-
    /// memory fns. `self` becomes an i32 record-pointer param, so `self.field`
    /// in the body reads the slot at the declared offset. Skipped: bodyless
    /// declarations (`declare fn`) and `#[@External.<targert>(...)]` host-backed methods.
    fn emitInterfaceMethods(self: *Emitter, owner: []const u8, methods: []const ast.BehaviorMethod) !void {
        for (methods) |m| {
            if (m.is_declare or m.body == null or m.isExternal()) continue;
            try self.emitMemberFn(owner, m);
        }
    }

    fn emitStructMethods(self: *Emitter, s: ast.StructDecl) !void {
        for (s.members) |mem| switch (mem) {
            .method => |m| {
                if (m.is_declare or m.body == null or m.isExternal()) continue;
                try self.emitMemberFn(s.name, m);
            },
            else => {},
        };
    }

    fn emitMemberFn(self: *Emitter, owner: []const u8, m: ast.BehaviorMethod) !void {
        const body = m.body orelse return;
        self.fn_tparams = m.genericParams;
        defer self.fn_tparams = &.{};
        const outer_template = self.cur_template;
        self.cur_template = if (!self.in_spec and (m.genericParams.len > 0 or self.owner_tparams.len > 0))
            try std.fmt.allocPrint(self.reg_arena.allocator(), "{s}_{s}", .{ owner, m.name })
        else
            null;
        defer self.cur_template = outer_template;
        const has_result = m.returnType != null or methodHasResult(body);
        // Decision 392 — a method answering `@Task<T>` is a state machine
        // too, its body answering the `T`.
        const is_task = if (m.returnType) |rt| isTaskTypeRef(rt) else false;
        const result_ty: Repr = if (m.returnType) |rt| self.memberRepr(taskValueTypeRef(rt) orelse rt) else .i32;
        self.resetFnState(if (has_result) result_ty else null);
        // What `return v` coerces to — a `-> ?i32` method boxes its scalar,
        // as a fn does (`emitFn`). Unset here, `Registry.at` returned the bare
        // index and its reader loaded through it as a box (`16777216` for `1`).
        self.cur_ret_typeref = m.returnType;
        self.fn_returns_result = if (m.returnType) |rt| resultShapeOfTypeRef(rt) != null else false;
        self.self_type = if (self.records.contains(owner)) owner else null;
        defer self.self_type = null;
        // Methods declared inside a record/struct body that reference `self`
        // without listing it as a param need an implicit `(param $self i32)`,
        // otherwise the bare `self.field` would emit a `global.get $self`
        // that wasmtime --validate rejects.
        var has_self_param = false;
        for (m.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) {
                has_self_param = true;
                break;
            }
        }
        const needs_self = !has_self_param and bodyReferencesSelf(body);
        if (needs_self) {
            try self.locals.put("self", if (self.mode == .gc and self.self_type != null) Repr{ .ref = .{ .record = self.self_type.? } } else .i32);
            if (self.self_type) |st| try self.local_types.put("self", st);
        }
        for (m.params, 0..) |p, i| {
            const sym = try self.paramSymbol(p, i);
            try self.locals.put(sym, self.memberRepr(p.typeRef));
            if (std.mem.eql(u8, p.name, "self")) {
                if (self.self_type) |st| try self.local_types.put("self", st);
                // A primitive default's copy (`lowerPrimDefault`) writes
                // `self: string`: the receiver's shape.
                if ((p.typeRef == .named and primKindOfName(p.typeRef.named) != null) or (p.typeRef == .array and self.self_type == null)) {
                    try self.noteParamShape("self", p.typeRef);
                    try self.local_typerefs.put("self", p.typeRef);
                }
                // A method copy of a generic type (`Dict<string, f64>.bump`)
                // writes `self: Self<string, f64>`: the receiver's type
                // arguments, which a call on `self` inside the copy
                // specialises by (`self.at(key)` is `Dict_at__K_string__V_f64`,
                // its `?V` a `?f64`), under the owner's name.
                if (self.in_spec and self.field_subs.len > 0 and p.typeRef == .generic) if (self.self_type) |st| {
                    var g = p.typeRef.generic;
                    g.name = st;
                    try self.local_typerefs.put("self", .{ .generic = g });
                };
            } else {
                const tn = typeRefName(p.typeRef);
                if (self.resolveRecordName(tn)) |rty|
                    try self.local_types.put(sym, rty);
                try self.noteParamShape(sym, p.typeRef);
                // In a copy the written type is concrete (`ys: i32[]` for
                // `Self<T>`): `primKindAt` reads it for a method on the param.
                // A GC module reads a generic body's parameter by its written
                // type too (`entries: Array<#(K, V)>`'s elements are tuples).
                if (self.in_spec or self.mode == .gc) try self.local_typerefs.put(sym, p.typeRef);
            }
        }
        try self.declareScratch("_try", countTrys(body));
        try self.declareScratch("__mem", self.countMems(body));
        try self.emitLocalDecls(body);
        if (is_task) try self.beginMachine(body);
        defer self.machine = null;

        // A method declared `-> @Iterator<T>` / `-> @Stream<T>` runs eagerly
        // like a fn does (`emitFn`): every `yield` is appended to one array,
        // which is what it returns. Rendered as a plain body, each `yield` was
        // dropped and the method answered `0` — or whatever its last
        // statement left.
        // Decision 105 (144 B-128) — in a GC module a method answering
        // `@Iterator<T>` is a generator machine (§ generators).
        const is_gen = has_result and methodYieldsEagerly(m) and bodyYieldsDeep(body) and self.mode == .gc and isIteratorTypeRef(m.returnType.?);
        if (is_gen) try self.beginGenMachine(body, self.genItemOfTypeRef(m.returnType.?.generic.args[0]), null);
        const seq = if (is_gen)
            try self.renderGenBody(body)
        else if (has_result and methodYieldsEagerly(m) and bodyYieldsDeep(body))
            try self.renderAccumulatingBody(body)
        else
            try self.renderBody(body, null);

        const ar = self.arena();
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        if (needs_self) try params.append(ar, wat.Builder.param("self", self.vtOf(self.locals.get("self") orelse .i32)));
        for (m.params, 0..) |p, i| {
            try params.append(ar, wat.Builder.param(try self.paramSymbol(p, i), self.vtOf(self.memberRepr(p.typeRef))));
        }
        const func = try self.builder().func(.{
            .name = try std.fmt.allocPrint(ar, "{s}_{s}", .{ owner, m.name }),
            .params = params.items,
            .result = if (is_gen) .i32 else if (has_result) self.vtOf(result_ty) else null,
            .locals = try self.localLines(),
            .body = seq,
        });
        if (is_task) return self.emitStateMachine(func);
        if (is_gen) return self.emitGenMachine(func, null);
        try self.item(.{ .func = func });
    }

    /// A method whose declared return is an `@Iterator<T>` / `@Stream<T>` —
    /// what `FnDecl.effect` says for a fn (a method carries no effect field).
    fn methodYieldsEagerly(m: ast.BehaviorMethod) bool {
        const rt = m.returnType orelse return false;
        return switch (rt) {
            .generic => |g| g.is_builtin and (std.mem.eql(u8, g.name, "Iterator") or std.mem.eql(u8, g.name, "Stream")),
            else => false,
        };
    }

    /// True when any `self` identifier appears anywhere in `body` (used to
    /// decide whether a self-less member fn needs an implicit `$self` param).
    fn bodyReferencesSelf(body: []const ast.Stmt) bool {
        for (body) |s| if (exprReferencesSelf(s.expr)) return true;
        return false;
    }

    fn exprReferencesSelf(e: ast.Expr) bool {
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| std.mem.eql(u8, n, "self"),
                .identAccess => |ia| exprReferencesSelf(ia.receiver.*),
                .dotIdent => false,
            },
            .binaryOp => |bin| exprReferencesSelf(bin.lhs.*) or exprReferencesSelf(bin.rhs.*),
            .unaryOp => |un| exprReferencesSelf(un.expr.*),
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (cc.receiver) |r| if (exprReferencesSelf(r.*)) break :blk true;
                    for (cc.args) |a| if (exprReferencesSelf(a.value.*)) break :blk true;
                    for (cc.trailing) |t| if (bodyReferencesSelf(t.body)) break :blk true;
                    break :blk false;
                },
                .pipeline => |pl| exprReferencesSelf(pl.lhs.*) or exprReferencesSelf(pl.rhs.*),
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| blk: {
                    if (exprReferencesSelf(i.cond.*)) break :blk true;
                    if (bodyReferencesSelf(i.then_)) break :blk true;
                    if (i.else_) |els| if (bodyReferencesSelf(els)) break :blk true;
                    break :blk false;
                },
                .tryCatch => |tc| exprReferencesSelf(tc.expr.*) or exprReferencesSelf(tc.handler.*),
            },
            .binding => |b| switch (b.kind) {
                .localBind => |lb| exprReferencesSelf(lb.value.*),
                .localBindDestruct => |lb| exprReferencesSelf(lb.value.*),
                .assign => |a| blk: {
                    if (exprReferencesSelf(a.value.*)) break :blk true;
                    switch (a.target) {
                        .fieldAccess => |fa| if (exprReferencesSelf(fa.receiver.*)) break :blk true,
                        .name => |n| if (std.mem.eql(u8, n, "self")) break :blk true,
                    }
                    break :blk false;
                },
            },
            .jump => |j| switch (j.kind) {
                .@"return", .throw_, .try_ => |v| if (v) |i| exprReferencesSelf(i.*) else false,
                inline .@"break", .yield => |jl| if (jl.value) |i| exprReferencesSelf(i.*) else false,
                .await_ => |a| exprReferencesSelf(a.*),
                else => false,
            },
            .loop => |lp| exprReferencesSelf(lp.iter.*) or bodyReferencesSelf(lp.body),
            // `case (self) { … }` in an enum's method — the subject and every
            // arm. Missed, the method got no `$self` and read `0` for it.
            .collection => |col| switch (col.kind) {
                .case => |cs| blk: {
                    for (cs.subjects) |sub| if (exprReferencesSelf(sub)) break :blk true;
                    for (cs.arms) |arm| {
                        if (exprReferencesSelf(arm.body)) break :blk true;
                        if (arm.guard) |g| if (exprReferencesSelf(g)) break :blk true;
                    }
                    break :blk false;
                },
                .grouped => |inner| exprReferencesSelf(inner.*),
                else => false,
            },
            .function => |f| bodyReferencesSelf(f.kind.body),
            else => false,
        };
    }

    /// True when a method body's final statement produces a value (so the WAT
    /// function needs a `(result i32)`). Void-tailed bodies (a bare `@print`,
    /// a valueless `return`, or an empty body) yield nothing.
    fn bodyYieldsValue(body: []const ast.Stmt) bool {
        if (body.len == 0) return false;
        const last = body[ast.lastRealIndex(body)].expr;
        return switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| r != null,
                .yield => |y| y.value != null,
                .await_ => true,
                else => false,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| !(cc.is_builtin and
                    (std.mem.eql(u8, cc.callee, "print") or
                        std.mem.eql(u8, cc.callee, "println") or
                        std.mem.eql(u8, cc.callee, "todo") or
                        std.mem.eql(u8, cc.callee, "panic"))),
                .pipeline => true,
            },
            .binding => false,
            .comptime_ => |ct| ct.kind != .assert,
            // Same statement-form test as `exprTail`/`lowerIfExpr`: a trailing
            // `if` with two void arms leaves the function empty-handed, so it
            // must not be given a `(result …)`.
            .branch => |b| switch (b.kind) {
                .if_ => |i| !ifIsStatementForm(i),
                .tryCatch => true,
            },
            else => true,
        };
    }

    /// Whether a function needs a `(result …)`. A declared return type settles
    /// it; otherwise the body decides. The comptime specialisation pass clears
    /// `returnType` on the functions it injects (`transform.zig` `.returnType =
    /// null`) even though their bodies still `return` a value, so relying on
    /// the annotation alone emits a void function whose `return <v>` leaves a
    /// value on the stack — and the call site then underflows.
    fn fnHasResult(f: ast.FnDecl) bool {
        if (f.returnType != null) return true;
        return methodHasResult(f.body);
    }

    /// Same question for a body with no signature to consult: a value-producing
    /// tail, or any `return <expr>` anywhere inside.
    fn methodHasResult(body: []const ast.Stmt) bool {
        return bodyYieldsValue(body) or bodyHasValueReturn(body);
    }

    fn bodyHasValueReturn(body: []const ast.Stmt) bool {
        for (body) |s| if (exprHasValueReturn(s.expr)) return true;
        return false;
    }

    fn exprHasValueReturn(e: ast.Expr) bool {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| r != null,
                else => false,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| bodyHasValueReturn(i.then_) or
                    (if (i.else_) |els| bodyHasValueReturn(els) else false),
                else => false,
            },
            .loop => |lp| bodyHasValueReturn(lp.body),
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    for (cc.trailing) |t| if (bodyHasValueReturn(t.body)) break :blk true;
                    break :blk false;
                },
                else => false,
            },
            .binding => |b| switch (b.kind) {
                .localBind => |lb| exprHasValueReturn(lb.value.*),
                else => false,
            },
            else => false,
        };
    }

    /// Count `try`/`try…catch` nodes so a scratch pointer local can be declared
    /// for each (WAT locals must be declared up-front, before the body).
    fn countTrys(body: []const ast.Stmt) u32 {
        var n: u32 = 0;
        for (body) |stmt| n += countTrysExpr(stmt.expr);
        return n;
    }

    fn countTrysExpr(e: ast.Expr) u32 {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                .try_ => |t| 1 + (if (t) |i| countTrysExpr(i.*) else 0),
                .@"return", .throw_ => |v| if (v) |i| countTrysExpr(i.*) else 0,
                inline .@"break", .yield => |jl| if (jl.value) |i| countTrysExpr(i.*) else 0,
                .await_ => |a| countTrysExpr(a.*),
                else => 0,
            },
            .branch => |b| switch (b.kind) {
                .tryCatch => |tc| 1 + countTrysExpr(tc.expr.*) + countTrysExpr(tc.handler.*),
                .if_ => |i| blk: {
                    var n = countTrysExpr(i.cond.*) + countTrys(i.then_);
                    if (i.else_) |els| n += countTrys(els);
                    break :blk n;
                },
            },
            .binding => |b| switch (b.kind) {
                .localBind => |lb| countTrysExpr(lb.value.*),
                .localBindDestruct => |lb| countTrysExpr(lb.value.*),
                .assign => |a| countTrysExpr(a.value.*),
            },
            else => 0,
        };
    }

    /// What a `.call` lowers to. Construction calls need a `$__mem` scratch
    /// pointer; plain calls and builtins do not. Used identically by
    /// `countMems` (to size the scratch pool) and `lowerExpr` (to consume it),
    /// so the count and usage stay in lock-step.
    const CallKind = enum { builtin, record_ctor, enum_ctor, plain };

    fn callKind(self: *Emitter, cc: anytype) CallKind {
        if (cc.is_builtin) return .builtin;
        // A variant reached through its enum (`__Token__Layout.Size(…)`, what a
        // section path desugars to) is that enum's, even when a record of the
        // same name is in scope (`type Size(px: i32)`): it used to build the
        // record, and `.Layout.Size.Large` answered the section's first arm.
        if (receiverName(cc)) |rcv| if (self.enums.get(rcv)) |vs| {
            for (vs) |v| if (std.mem.eql(u8, v.name, cc.callee)) return .enum_ctor;
        };
        if (self.records.contains(cc.callee)) return .record_ctor;
        if (receiverName(cc)) |rcv| {
            if (self.enums.contains(rcv)) return .enum_ctor;
        } else if (cc.callee.len > 0 and std.ascii.isUpper(cc.callee[0])) {
            // `Variant(...)` with no receiver: an enum payload constructor when
            // the (capitalised) name uniquely names a payload-bearing variant.
            if (self.findVariant(cc.callee)) |fv| {
                if (fv.variant.fields.len > 0) return .enum_ctor;
            }
        }
        return .plain;
    }

    /// The receiver of a qualified call, when it is a plain identifier
    /// (`Color.Rgb(…)` → `"Color"`). The call `receiver` is an expression
    /// pointer, so anything more complex yields null.
    fn receiverName(cc: anytype) ?[]const u8 {
        const recv = cc.receiver orelse return null;
        return switch (recv.*) {
            .identifier => |rid| switch (rid.kind) {
                .ident => |n| n,
                else => null,
            },
            else => null,
        };
    }

    const CtorBox = union(enum) { none, all, args: []const ast.TypeRef };

    const FoundVariant = struct { variants: []const ast.EnumVariant, tag: u32, variant: ast.EnumVariant };

    /// Decision 8 §5.1 P8: a pattern's variant name reaches the backend with
    /// the path it was **written** with — `Shape.Circle`, `.Circle` — while the
    /// constructor stores the bare `Circle`. The last `.`-separated segment is
    /// the variant; what precedes it, when it is not empty, is the enum.
    fn bareVariantName(name: []const u8) []const u8 {
        const i = std.mem.lastIndexOfScalar(u8, name, '.') orelse return name;
        return name[i + 1 ..];
    }

    /// The enum a written path names, or `""` for a bare name and for the
    /// dot shorthand `.Circle` (whose enum comes from the matched value).
    fn variantPathEnum(name: []const u8) []const u8 {
        const i = std.mem.lastIndexOfScalar(u8, name, '.') orelse return "";
        return name[0..i];
    }

    /// True when `name` was written as a path (`Shape.Circle`, `.None`). Such a
    /// name is a variant, never a binding, however it resolves (§5.1 P8).
    fn isVariantPath(name: []const u8) bool {
        return std.mem.indexOfScalar(u8, name, '.') != null;
    }

    /// Search for a variant the pattern named. A written path (`Shape.Circle`)
    /// is looked up in the enum it names first; a bare or dot-shorthand name
    /// searches every enum, first match wins.
    fn findVariant(self: *Emitter, name: []const u8) ?FoundVariant {
        const bare = bareVariantName(name);
        const ename = variantPathEnum(name);
        // A bare or dot-shorthand arm (`Red`, `.After`) over a subject whose
        // enum is known is that enum's variant (§5.1 P8). Searched through one
        // flat table, the first enum declaring the name answered: `case c {
        // Red -> … }` over a `Cool` tested `Warm.Red`'s tag, and a section
        // leaf `Layout.Break.After` was taken for `Token.After(inner)`.
        if (ename.len == 0) if (self.case_enum_hint) |hint| if (self.enums.get(hint)) |variants| {
            for (variants, 0..) |v, i| {
                if (std.mem.eql(u8, v.name, bare))
                    return .{ .variants = variants, .tag = @intCast(i), .variant = v };
            }
        };
        if (ename.len > 0) {
            if (self.enums.get(ename)) |variants| {
                for (variants, 0..) |v, i| {
                    if (std.mem.eql(u8, v.name, bare))
                        return .{ .variants = variants, .tag = @intCast(i), .variant = v };
                }
            }
        }
        var it = self.enums.iterator();
        while (it.next()) |entry| {
            for (entry.value_ptr.*, 0..) |v, i| {
                if (std.mem.eql(u8, v.name, bare))
                    return .{ .variants = entry.value_ptr.*, .tag = @intCast(i), .variant = v };
            }
        }
        return null;
    }

    /// Count the `$__mem` scratch pointers a function body needs: one per
    /// aggregate construction (tuple/array/record/enum-payload) and one per
    /// destructuring binding.
    fn countMems(self: *Emitter, body: []const ast.Stmt) u32 {
        var n: u32 = 0;
        for (body) |stmt| {
            switch (stmt.expr) {
                .binding => |b| switch (b.kind) {
                    .localBind => |lb| n += self.countMemsExpr(lb.value.*),
                    .assign => |a| {
                        n += self.countMemsExpr(a.value.*);
                        switch (a.target) {
                            .fieldAccess => |fa| {
                                n += self.countMemsExpr(fa.receiver.*);
                                // `recv.field += rhs` stashes the receiver in
                                // a scratch local for the load-add-store cycle.
                                if (a.op == .plusAssign) n += 1;
                            },
                            else => {},
                        }
                    },
                    .localBindDestruct => |lb| n += 1 + self.countMemsExpr(lb.value.*),
                },
                else => n += self.countMemsExpr(stmt.expr),
            }
        }
        return n;
    }

    fn countMemsExpr(self: *Emitter, e: ast.Expr) u32 {
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .identAccess => |ia| blk: {
                    var n = self.countMemsExpr(ia.receiver.*);
                    // `?.field` lowers to a `local.tee` guard which needs a
                    // scratch i32 to hold the receiver pointer while testing
                    // for null. Over-counting is safe (unused locals are fine).
                    if (ia.optional) n += 1;
                    break :blk n;
                },
                else => 0,
            },
            .binaryOp => |bin| self.countMemsExpr(bin.lhs.*) + self.countMemsExpr(bin.rhs.*),
            .unaryOp => |un| self.countMemsExpr(un.expr.*),
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    var n: u32 = switch (self.callKind(cc)) {
                        .record_ctor, .enum_ctor => 1,
                        else => 0,
                    };
                    // A method call's receiver is an expression too: `[1,2].at(0)`
                    // materialises the array into a scratch local before the
                    // call, and skipping it here left that `local.set $__memN`
                    // against a name no `(local …)` declared.
                    if (cc.receiver) |recv| n += self.countMemsExpr(recv.*);
                    for (cc.args) |arg| n += self.countMemsExpr(arg.value.*);
                    for (cc.trailing) |t| n += self.countMems(t.body);
                    break :blk n;
                },
                .pipeline => |pl| self.countMemsExpr(pl.lhs.*) + self.countMemsExpr(pl.rhs.*),
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| blk: {
                    var n = self.countMemsExpr(i.cond.*) + self.countMems(i.then_);
                    if (i.else_) |els| n += self.countMems(els);
                    break :blk n;
                },
                .tryCatch => |tc| self.countMemsExpr(tc.expr.*) + self.countMemsExpr(tc.handler.*),
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.countMemsExpr(inner.*),
                .case => |c| blk: {
                    var n: u32 = 0;
                    for (c.subjects) |s| n += self.countMemsExpr(s);
                    for (c.arms) |arm| n += self.countMemsExpr(arm.body);
                    break :blk n;
                },
                .tupleLit => |tl| blk: {
                    var n: u32 = 1;
                    for (tl.elems) |el| n += self.countMemsExpr(el);
                    break :blk n;
                },
                .arrayLit => |al| blk: {
                    var n: u32 = 1;
                    for (al.elems) |el| n += self.countMemsExpr(el);
                    break :blk n;
                },
                .range => |r| blk: {
                    var n = self.countMemsExpr(r.start.*);
                    if (r.end) |end| n += self.countMemsExpr(end.*);
                    break :blk n;
                },
                .behaviorLit => |il| blk: {
                    var n: u32 = 1;
                    for (il.fields) |f| n += self.countMemsExpr(f.value.*);
                    break :blk n;
                },
            },
            .jump => |j| switch (j.kind) {
                .@"return", .throw_, .try_ => |v| if (v) |i| self.countMemsExpr(i.*) else 0,
                inline .@"break", .yield => |jl| if (jl.value) |i| self.countMemsExpr(i.*) else 0,
                .await_ => |a| self.countMemsExpr(a.*),
                else => 0,
            },
            .loop => |lp| self.countMemsExpr(lp.iter.*) + self.countMems(lp.body),
            else => 0,
        };
    }

    /// Walk a body and *register* every local it binds (no output — see
    /// `declareLocal`). Recurses through every nested statement list — if/else
    /// branches, loop bodies, `case` arm blocks — because a `val`
    /// bound inside one of those is still a function-level WAT local, and
    /// missing it used to produce a `local.set` against an undeclared name.
    fn emitLocalDecls(self: *Emitter, body: []const ast.Stmt) anyerror!void {
        for (body) |stmt| {
            switch (stmt.expr) {
                .binding => |b| switch (b.kind) {
                    .localBind => |lb| {
                        // A re-binding of a name already declared here is a
                        // local of its own (`bindTarget`), registered when it
                        // is lowered: registering its shape under the shared
                        // name here marked the OUTER `x` a string too.
                        // A `val` over a module-level name is one too: the
                        // module's name stays the global's until the binding
                        // (and for a `defer` written before it, after).
                        if (self.locals.contains(lb.name) or self.globals.contains(lb.name)) {
                            try self.declareNestedLocals(lb.value.*);
                            continue;
                        }
                        // An `unknown` / union slot holds the box's pointer,
                        // whatever the value's own shape.
                        if (lb.typeAnnotation) |ta| if (isUnknownTypeRef(ta)) {
                            try self.local_typerefs.put(lb.name, ta);
                            try self.declareLocal(lb.name, if (self.mode == .gc) .{ .ref = .unknown } else .i32);
                            try self.declareNestedLocals(lb.value.*);
                            continue;
                        };
                        const t = self.bindingLocalType(lb.typeAnnotation, lb.value.*);
                        // A cell optional (`?f64`, `?i64`) is known before the
                        // body is lowered, so a binder over it is declared
                        // the cell's width.
                        if (lb.typeAnnotation) |ta| if (self.optInfoOfTypeRef(ta)) |oi| if (oi.cell != .none) try self.opt_locals.put(lb.name, oi);
                        if (lb.typeAnnotation == null) if (self.optInfoOf(lb.value.*)) |oi| if (oi.cell != .none) try self.opt_locals.put(lb.name, oi);
                        if (self.recordTypeOfExpr(lb.value.*)) |rty| {
                            try self.local_types.put(lb.name, rty);
                        } else if (self.mode == .gc) if (lb.typeAnnotation) |ta| {
                            // A downcast (`val f: Frame = cur` over an
                            // `unknown` a test proved): the annotation names it.
                            if (ta == .named) if (self.resolveRecordName(ta.named)) |rty| try self.local_types.put(lb.name, rty);
                        };
                        const gc_task = self.mode == .gc and t == .ref and t.ref == .task;
                        if (gc_task and lb.value.* == .function and lb.value.function.kind.syntax == .asyncBlock) {
                            if (try self.gcBlockRepr(lb.value.*)) |r| try self.gc_block_locals.put(self.alloc, lb.name, r) else _ = self.gc_block_locals.remove(lb.name);
                        }
                        if (!gc_task and self.isStringExpr(lb.value.*)) try self.str_locals.put(lb.name, {});
                        if (!gc_task and self.isBoolExpr(lb.value.*)) try self.bool_locals.put(lb.name, {});
                        try self.noteArrayLocal(lb.name, lb.value.*);
                        if (self.resultShapeOf(lb.value.*)) |shape| try self.result_shape_locals.put(lb.name, shape);
                        try self.declareLocal(lb.name, t);
                        try self.declareNestedLocals(lb.value.*);
                    },
                    .localBindDestruct => |lb| {
                        switch (lb.pattern) {
                            .names => |n| {
                                const recv_rty = self.recordTypeOfExpr(lb.value.*);
                                for (n.fields) |fld| {
                                    var cell: Cell = .none;
                                    if (recv_rty) |rty| {
                                        if (self.fieldTypeIn(rty, fld.field_name)) |ft| {
                                            if (self.resolveRecordName(ft)) |sub|
                                                try self.local_types.put(fld.bind_name, sub);
                                            cell = self.fieldCellIn(rty, fld.field_name);
                                        }
                                    }
                                    try self.declareLocal(fld.bind_name, cell.ty());
                                }
                            },
                            .tuple_ => |bindings| {
                                for (bindings, 0..) |name, i| {
                                    try self.declareLocal(name, (try self.tupleElemCell(lb.value.*, i)).ty());
                                    try self.noteTupleElemShape(name, lb.value.*, i);
                                }
                            },
                            else => {},
                        }
                        try self.declareNestedLocals(lb.value.*);
                    },
                    .assign => |a| try self.declareNestedLocals(a.value.*),
                },
                else => try self.declareNestedLocals(stmt.expr),
            }
        }
    }

    /// Register locals bound inside an expression's nested statement lists.
    fn declareNestedLocals(self: *Emitter, e: ast.Expr) anyerror!void {
        switch (e) {
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    // `if (opt) { v -> … }` binds the narrowed value to `v`:
                    // a `?f64`'s / `?i64`'s is what its cell holds.
                    if (i.binding) |name| {
                        const cell: Cell = if (self.optInfoOf(i.cond.*)) |o| o.cell else .none;
                        try self.declareLocal(name, cell.ty());
                    }
                    try self.emitLocalDecls(i.then_);
                    if (i.else_) |els| try self.emitLocalDecls(els);
                },
                .tryCatch => |tc| {
                    try self.declareNestedLocals(tc.expr.*);
                    try self.declareNestedLocals(tc.handler.*);
                },
            },
            .call => |c| switch (c.kind) {
                .call => |cc| {
                    for (cc.args) |a| try self.declareNestedLocals(a.value.*);
                    for (cc.trailing) |t| try self.emitLocalDecls(t.body);
                },
                .pipeline => |pl| {
                    try self.declareNestedLocals(pl.lhs.*);
                    try self.declareNestedLocals(pl.rhs.*);
                },
            },
            .loop => |lp| {
                // A walk over a float array binds its element as the `f64`
                // its slot's cell holds (`lowerCollectionLoop`); a range or an
                // index is an i32.
                const is_range = lp.iter.* == .collection and lp.iter.collection.kind == .range;
                for (lp.params, 0..) |p, i| {
                    const float_elem = i == 0 and !is_range and self.isArrayExpr(lp.iter.*) and self.elemKindOf(lp.iter.*) == .f64;
                    try self.declareLocal(p, if (float_elem) .f64 else .i32);
                }
                try self.emitLocalDecls(lp.body);
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| try self.declareNestedLocals(inner.*),
                .case => |cse| for (cse.arms) |arm| {
                    try self.declarePatternLocals(arm.pattern);
                    try self.declareNestedLocals(arm.body);
                },
                else => {},
            },
            .binaryOp => |bin| {
                try self.declareNestedLocals(bin.lhs.*);
                try self.declareNestedLocals(bin.rhs.*);
            },
            .unaryOp => |un| try self.declareNestedLocals(un.expr.*),
            .jump => |j| switch (j.kind) {
                .@"return", .throw_, .try_ => |v| if (v) |i| try self.declareNestedLocals(i.*),
                inline .@"break", .yield => |jl| if (jl.value) |i| try self.declareNestedLocals(i.*),
                .await_ => |a| try self.declareNestedLocals(a.*),
                else => {},
            },
            .useHook => |uh| try self.declareNestedLocals(uh.kind.inner.*),
            else => {},
        }
    }

    /// Locals a case pattern binds (variant payload fields, `ident` binders,
    /// list-pattern element and rest names).
    fn declarePatternLocals(self: *Emitter, p: ast.Pattern) anyerror!void {
        switch (p) {
            .ident => |n| if (self.findVariant(n) == null) try self.declareLocal(n, .i32),
            .variant => |v| switch (v.payload) {
                .binding => |b| try self.declareLocal(b, .i32),
                .fields => |fs| for (fs, 0..) |f, i| {
                    const ty = if (self.findVariant(v.name)) |fv|
                        (if (i < fv.variant.fields.len) self.reprOf(fv.variant.fields[i].typeRef) else Repr.i32)
                    else
                        Repr.i32;
                    // A name already declared (a parameter) keeps its slot and
                    // the arm binds an alias instead — see `bindName`.
                    if (!self.locals.contains(f)) {
                        try self.declareLocal(f, ty);
                        try self.pattern_locals.put(f, {});
                    }
                },
                .literals => |pats| for (pats) |sub| try self.declarePatternLocals(sub),
            },
            .list => |l| {
                for (l.elems) |el| try self.declareListElemLocals(el);
                if (l.spread) |rest| if (rest.len > 0) try self.declareLocal(rest, .i32);
            },
            .@"or", .multi => |pats| for (pats) |sub| try self.declarePatternLocals(sub),
            else => {},
        }
    }

    fn declareListElemLocals(self: *Emitter, el: ast.ListPatternElem) anyerror!void {
        switch (el) {
            .bind => |n| try self.declareLocal(n, .i32),
            else => {},
        }
    }

    /// The wasm type to declare a local with. Must be the *same* classifier the
    /// lowering uses, or the value pushed and the slot it is stored into
    /// disagree: `val taxa = valor * 0.15` lowered to an `f32.mul` but declared
    /// `(local $taxa i32)`.
    fn inferExprType(self: *Emitter, e: ast.Expr) Repr {
        return self.wasmTypeOf(e);
    }

    /// The wasm type of a `val`/`var`'s local: what a written type says, when
    /// it says one — a `?T` is the `i32` of its box or pointer, a number the
    /// width it names (`val a: i64 = 4294967295` is an `i64`, `val o: ?f64 =
    /// 1.1` the address of a cell) — and the value's own type otherwise.
    fn bindingLocalType(self: *Emitter, ann: ?ast.TypeRef, value: ast.Expr) Repr {
        // Front 164 s2 P4 — a task (an `async { }` block, a call answering
        // one) is a `$task`, whatever its value's shape.
        if (self.mode == .gc and ann == null and self.isTaskExpr(value)) return .{ .ref = .task };
        if (self.mode == .gc) if (ann) |ta| {
            const r = self.reprOf(ta);
            if (r != .i32) return r;
        };
        if (ann) |ta| switch (ta) {
            .optional => return .i32,
            .named => |n| if (isScalarName(n)) return watType(ta),
            else => {},
        };
        return self.inferExprType(value);
    }

    fn emitGlobalVal(self: *Emitter, v: ast.ValDecl) !void {
        const t = self.globalValType(v);
        if (self.boxesInto(v.typeAnnotation, v.value.*)) {
            try self.item(.{ .global = .{ .name = v.name, .ty = .i32, .mutable = true, .init = "0" } });
            try self.deferred_globals.append(self.alloc, v);
            try self.deferred_renames.append(self.alloc, self.global_renames);
            return;
        }
        // A `var` (front 17 step 2) is a mutable global on every path: the two
        // constant paths below declared an immutable one, which `global.set`
        // does not validate against.
        if (self.folded_globals.get(v.name)) |text| {
            if (isNumericLiteral(text)) {
                try self.item(.{ .global = .{ .name = v.name, .ty = self.vtOf(t), .mutable = v.mutable, .init = try numeralText(self.arena(), text) } });
                return;
            }
            if (quotedString(text)) |str| {
                if (self.mode == .gc) {
                    // The string is built at instantiation, with the other
                    // globals `$__init_globals` fills in.
                    const lit = try self.arena().create(ast.Expr);
                    lit.* = .{ .literal = .{ .loc = v.value.getLoc(), .kind = .{ .stringLit = str } } };
                    var folded = v;
                    folded.value = lit;
                    folded.typeAnnotation = null;
                    try self.item(.{ .global = .{ .name = v.name, .ty = self.vtOf(Repr.string), .mutable = true, .init = "0" } });
                    try self.deferred_globals.append(self.alloc, folded);
                    try self.deferred_renames.append(self.alloc, self.global_renames);
                    return;
                }
                const seg = try self.internString(str);
                try self.item(.{ .global = .{
                    .name = v.name,
                    .ty = .i32,
                    .init = try std.fmt.allocPrint(self.arena(), "{d}", .{seg.offset}),
                } });
                return;
            }
        }
        switch (v.value.*) {
            .literal => |lit| switch (lit.kind) {
                // The comptime folder rewrites a folded `val` into a `numberLit`
                // node carrying the *rendered* value, which is not always a
                // number: `val COMMANDS = comptime ["calc", …]` arrived here as
                // the text `["calc", "noop", "help"]` and was emitted as
                // `(f32.const ["calc", …])` — a parse error that killed the
                // whole module. Only take the constant path for real numerals.
                .numberLit => |n| if (isNumericLiteral(n)) {
                    try self.item(.{ .global = .{
                        .name = v.name,
                        .exports = if (v.isPub) try self.arena().dupe([]const u8, &.{v.name}) else &.{},
                        .ty = self.vtOf(t),
                        .mutable = v.mutable,
                        .init = try numeralText(self.arena(), n),
                    } });
                    return;
                },
                // A GC string literal is built at instantiation: the
                // global is filled in by `$__init_globals` below.
                .stringLit => |s| if (self.mode == .linear) {
                    const seg = try self.internString(try self.literalBytes(s));
                    try self.item(.{ .global = .{
                        .name = v.name,
                        .ty = .i32,
                        .mutable = true,
                        .init = try std.fmt.allocPrint(self.arena(), "{d}", .{seg.offset}),
                    } });
                    return;
                },
                else => {},
            },
            else => {},
        }
        // Not a constant expression: declare it zeroed and mutable, and fill it
        // in from `$__init_globals` (see `emitGlobalInit`).
        try self.item(.{ .global = .{
            .name = v.name,
            .ty = self.vtOf(t),
            .mutable = true,
            .init = "0",
        } });
        try self.deferred_globals.append(self.alloc, v);
        try self.deferred_renames.append(self.alloc, self.global_renames);
    }

    /// Emit `$__init_globals`, the body of the module's `(start …)`: every
    /// top-level `val` whose initialiser is not a wasm constant expression is
    /// evaluated here, in source order, before `main` runs.
    fn emitGlobalInit(self: *Emitter) !void {
        if (self.deferred_globals.items.len == 0) return;
        self.resetFnState(null);

        var total_mems: u32 = 0;
        var total_trys: u32 = 0;
        for (self.deferred_globals.items) |v| {
            total_mems += self.countMemsExpr(v.value.*);
            total_trys += countTrysExpr(v.value.*);
        }
        try self.declareScratch("_try", total_trys);
        try self.declareScratch("__mem", total_mems);

        var c: Capture = .{};
        self.open(&c);
        for (self.deferred_globals.items, self.deferred_renames.items) |v, renames| {
            self.global_renames = renames;
            defer self.global_renames = null;
            if (self.deferred_stmts.contains(v.name)) {
                _ = try self.emitStmt(.{ .expr = v.value.* }, false);
                continue;
            }
            if (self.boxesInto(v.typeAnnotation, v.value.*))
                try self.lowerBoxedInto(v.typeAnnotation, v.value.*)
            else
                try self.lowerCoerced(v.value.*, self.globalValType(v));
            try self.emit(.{ .global_set = v.name });
        }
        const body = self.seal(&c, .none);

        try self.item(.{ .func = try self.builder().func(.{
            .name = "__init_globals",
            .locals = try self.localLines(),
            .body = body,
        }) });
    }

    /// Syntactically an array literal (through parentheses).
    fn isArrayLit(e: ast.Expr) bool {
        return switch (e) {
            .collection => |col| switch (col.kind) {
                .arrayLit => true,
                .grouped => |inner| isArrayLit(inner.*),
                else => false,
            },
            else => false,
        };
    }

    /// The contents of a folded `"…"` value, when the text is one (no escapes
    /// inside).
    fn quotedString(text: []const u8) ?[]const u8 {
        if (text.len < 2 or text[0] != '"' or text[text.len - 1] != '"') return null;
        const inner = text[1 .. text.len - 1];
        if (std.mem.indexOfAny(u8, inner, "\\\"") != null) return null;
        return inner;
    }

    /// Whether a `numberLit`'s text really is a wasm numeral. Guards against the
    /// comptime folder's rendered non-numeric values (arrays, records, strings).
    fn isNumericLiteral(n: []const u8) bool {
        if (n.len == 0) return false;
        if (radixOf(n)) |r| return radixValue(n, r) != null;
        var i: usize = 0;
        if (n[0] == '-' or n[0] == '+') i = 1;
        if (i >= n.len) return false;
        var seen_digit = false;
        while (i < n.len) : (i += 1) switch (n[i]) {
            '0'...'9' => seen_digit = true,
            '.', 'e', 'E', '+', '-', '_' => {},
            else => return false,
        };
        return seen_digit;
    }

    /// The wat value type of a top-level `val`. Without an annotation the
    /// literal's own spelling decides, so `val PI = 3.14` is an `f64` global
    /// rather than an `(global $PI i32 (i32.const 3.14))` parse error.
    fn globalValType(self: *Emitter, v: ast.ValDecl) Repr {
        if (v.typeAnnotation) |ta| return self.reprOf(ta);
        // A folded float is an f64 — the value the comptime pass computed.
        if (self.folded_globals.get(v.name)) |text| {
            if (isNumericLiteral(text)) return numLitType(text);
            if (self.mode == .gc and quotedString(text) != null) return Repr.string;
        }
        if (self.mode == .gc and self.isStringExpr(v.value.*)) return Repr.string;
        return switch (v.value.*) {
            .literal => |lit| switch (lit.kind) {
                .numberLit => |n| if (isNumericLiteral(n)) numLitType(n) else .i32,
                else => .i32,
            },
            // Anything the init function computes is a pointer or an i32 unless
            // the expression is plainly a float.
            else => self.wasmTypeOf(v.value.*),
        };
    }

    /// `$__display_of(v) -> i32`: the string a record's own `display(self)
    /// -> string` answers for `v`, or `0` when `v`'s type declares none — the
    /// hook `$__print_tagged_raw` calls first. Null when no record qualifies:
    /// the prelude's `display_of` group (`0`) is then the module's answer. One compare per record type that
    /// has both a descriptor (some value of it was built) and a `display`
    /// method: `v` is a pointer past the data floor and the header four bytes
    /// behind it is that type's descriptor. A dispatch written after lowering,
    /// not a table index interned into the descriptor, because table indices
    /// are handed out as lambdas are lifted and would shift under it.
    fn displayDispatch(self: *Emitter) !?wat.Func {
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        var it = self.records.keyIterator();
        while (it.next()) |k| try names.append(self.arena(), k.*);
        std.mem.sort([]const u8, names.items, {}, struct {
            fn lt(_: void, a: []const u8, b: []const u8) bool {
                return std.mem.lessThan(u8, a, b);
            }
        }.lt);
        var c: Capture = .{};
        self.open(&c);
        var any = false;
        for (names.items) |rec| {
            const desc = self.type_descs.get(rec) orelse continue;
            const sym = try std.fmt.allocPrint(self.arena(), "{s}_display", .{rec});
            const sig = self.fn_sigs.get(sym) orelse continue;
            if (sig.params.len != 1 or sig.result == null) continue;
            any = true;
            var hit: Capture = .{};
            self.open(&hit);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .call = sym });
            try self.emit(.@"return");
            const hit_seq = self.seal(&hit, .terminated);
            var guard: Capture = .{};
            self.open(&guard);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .@"const" = .{ .ty = .i32, .text = "4" } });
            try self.emit(opOf(.i32, "sub"));
            try self.emit(.{ .load = .{} });
            try self.emit(try self.constInt(desc));
            try self.emit(opOf(.i32, "eq"));
            try self.emitC(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } }, rec);
            const guard_seq = self.seal(&guard, .none);
            try self.emit(.{ .local_get = "v" });
            try self.emit(.{ .@"const" = .{ .ty = .i32, .text = "256" } });
            try self.emit(opOf(.i32, "ge_u"));
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = guard_seq } } });
        }
        try self.emit(.{ .@"const" = .{ .ty = .i32, .text = "0" } });
        const body = self.seal(&c, .{ .value = .i32 });
        // No type declares `display`: the prelude's form (`0`) is the answer.
        if (!any) return null;
        return try self.builder().func(.{
            .name = "__display_of",
            .params = &.{wat.Builder.param("v", .i32)},
            .result = .i32,
            .body = body,
        });
    }

    /// The types that may answer `method` with `argc` arguments: every record
    /// and enum of the (linked) module declaring `<Type>_<method>` taking the
    /// receiver and `argc` more, sorted so two runs emit the same module.
    fn behaviorImplementers(self: *Emitter, method: []const u8, argc: usize) ![]const []const u8 {
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        var rit = self.records.keyIterator();
        while (rit.next()) |k| try names.append(self.arena(), k.*);
        var eit = self.enums.keyIterator();
        while (eit.next()) |k| try names.append(self.arena(), k.*);
        std.mem.sort([]const u8, names.items, {}, struct {
            fn lt(_: void, a: []const u8, b: []const u8) bool {
                return std.mem.lessThan(u8, a, b);
            }
        }.lt);
        var out: std.ArrayListUnmanaged([]const u8) = .empty;
        for (names.items) |t| {
            const sym = try std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ t, method });
            const sig = self.fn_sigs.get(sym) orelse continue;
            if (sig.params.len != argc + 1) continue;
            try out.append(self.arena(), t);
        }
        return out.items;
    }

    /// Whether inference placed `recv.method(…)` at `loc` on a behavior-typed
    /// value (`.by_value`) and some type of the module declares the method,
    /// so `lowerBehaviorDispatch` answers it. A primitive's method of the same
    /// name (`slice` on a `Slice<V>` value) is not the call's.
    fn answeredByValue(self: *Emitter, cc: anytype, loc: ast.Loc) bool {
        if (cc.receiver == null or cc.is_builtin) return false;
        const il = self.instance_lowerings.get(loc) orelse return false;
        if (il != .by_value) return false;
        const impls = self.behaviorImplementers(cc.callee, cc.args.len) catch return false;
        return impls.len > 0;
    }

    /// What a call answered by value (`answeredByValue`) answers: the return
    /// its implementers declare, when every one declares the same. The
    /// dispatcher calls `<Type>_<method>`, so the value is in that method's
    /// representation — `Registry.at`'s `?i32` a box. Read as nothing, the
    /// box's address was the payload (`m.at(k) ?? -1` on an `Index<string,
    /// i32>` answered `388`).
    fn byValueRetTypeRef(self: *Emitter, cc: anytype, loc: ast.Loc) ?ast.TypeRef {
        if (!self.answeredByValue(cc, loc)) return null;
        const impls = self.behaviorImplementers(cc.callee, cc.args.len) catch return null;
        var out: ?ast.TypeRef = null;
        for (impls) |t| {
            const sym = std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ t, cc.callee }) catch return null;
            const tr = self.fn_ret_typerefs.get(sym) orelse return null;
            if (out) |o| {
                if (!sameTypeRef(o, tr)) return null;
            } else out = tr;
        }
        return out;
    }

    /// Structural equality of two written types; a form compared nowhere
    /// (a function type, a typeparam) is never the same.
    fn sameTypeRef(a: ast.TypeRef, b: ast.TypeRef) bool {
        if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
        return switch (a) {
            .named => |n| std.mem.eql(u8, n, b.named),
            .array => |e| sameTypeRef(e.*, b.array.*),
            .optional => |e| sameTypeRef(e.*, b.optional.*),
            .tuple_ => |es| es.len == b.tuple_.len and for (es, b.tuple_) |x, y| {
                if (!sameTypeRef(x, y)) break false;
            } else true,
            .generic => |g| std.mem.eql(u8, g.name, b.generic.name) and g.args.len == b.generic.args.len and for (g.args, b.generic.args) |x, y| {
                if (!sameTypeRef(x, y)) break false;
            } else true,
            else => false,
        };
    }

    /// `recv.method(…)` where `recv` is typed by a `behavior`: no declaration
    /// is known at the call, so the VALUE answers — its header names its type,
    /// and `$__bdispatch_<method>_<n>` calls that type's `<Type>_<method>`.
    /// It trapped (`unresolved call`) where commonJS, erlang and beam
    /// dispatched. False when no type of the module declares the method.
    fn lowerBehaviorDispatch(self: *Emitter, cc: anytype) anyerror!bool {
        const impls = try self.behaviorImplementers(cc.callee, cc.args.len);
        if (impls.len == 0) return false;
        const first = try std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ impls[0], cc.callee });
        const sig = self.fn_sigs.get(first).?;
        // The dispatcher tells implementers apart by the descriptor in the
        // value's header and calls each through one signature. A variant of
        // an all-unit enum is its bare ordinal (no header), and an
        // implementer whose method takes or answers something else cannot
        // be called from the dispatcher: a value of either would reach the
        // dispatcher's end at run time, so the call is refused here.
        for (impls) |t| {
            const gsym = try std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ t, cc.callee });
            if (self.generic_methods.contains(gsym)) try self.noteTemplateCall(gsym, self.call_loc);
            if (self.enums.get(t)) |variants| if (!enumHasPayload(variants))
                return self.refuse(self.call_loc, "the wasm backend cannot dispatch `.{s}` by value: `{s}` is an all-unit enum, whose values carry no header naming their type", .{ cc.callee, t });
            const isym = try std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ t, cc.callee });
            if (!self.sameSig(self.fn_sigs.get(isym).?, sig))
                return self.refuse(self.call_loc, "the wasm backend cannot dispatch `.{s}` by value: `{s}` and `{s}` declare it with different wasm signatures", .{ cc.callee, impls[0], t });
        }
        const sym = try std.fmt.allocPrint(self.reg_arena.allocator(), "__bdispatch_{s}_{d}", .{ cc.callee, cc.args.len });
        if (!self.behavior_dispatch.contains(sym)) try self.behavior_dispatch.put(self.reg_arena.allocator(), sym, .{
            .method = try self.reg_arena.allocator().dupe(u8, cc.callee),
            .argc = cc.args.len,
            .sig = sig,
        });
        try self.lowerCoerced(cc.receiver.?.*, .i32);
        try self.lowerCallArgs(cc.args, sig, 1);
        try self.emit(.{ .call = sym });
        return true;
    }

    /// `$__bdispatch_<method>_<n>(self, a0, …)`: one header compare per
    /// descriptor of each implementer (a record's, or each variant's of a
    /// payload enum) that some value of the module was built with, calling
    /// that type's method. The chain ends in `unreachable`, which no value
    /// reaches: `lowerBehaviorDispatch` refused the call when an implementer
    /// has no header (an all-unit enum) or another signature. Written after
    /// lowering, as `$__display_of` is, because a descriptor exists only once
    /// a value of its type was built.
    fn behaviorDispatchFunc(self: *Emitter, bd: BehaviorDispatch) !wat.Func {
        const impls = try self.behaviorImplementers(bd.method, bd.argc);
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        try params.append(self.arena(), wat.Builder.param("self", .i32));
        var arg_names: std.ArrayListUnmanaged([]const u8) = .empty;
        for (0..bd.argc) |i| {
            const n = try std.fmt.allocPrint(self.arena(), "a{d}", .{i});
            try arg_names.append(self.arena(), n);
            try params.append(self.arena(), wat.Builder.param(n, self.vtOf(bd.sig.params[i + 1])));
        }
        var c: Capture = .{};
        self.open(&c);
        for (impls) |t| {
            const sym = try std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ t, bd.method });
            const sig = self.fn_sigs.get(sym).?;
            // An implementer whose method does not take and answer what the
            // dispatcher does cannot be called from it.
            if (!self.sameSig(sig, bd.sig)) continue;
            var descs: std.ArrayListUnmanaged(u32) = .empty;
            if (self.records.contains(t)) {
                if (self.type_descs.get(t)) |d| try descs.append(self.arena(), d);
            } else if (self.enums.get(t)) |variants| {
                for (variants) |v| {
                    const key = try std.fmt.allocPrint(self.arena(), "{s}.{s}", .{ t, v.name });
                    if (self.type_descs.get(key)) |d| try descs.append(self.arena(), d);
                }
            }
            for (descs.items) |d| {
                var hit: Capture = .{};
                self.open(&hit);
                try self.emit(.{ .local_get = "self" });
                for (arg_names.items) |n| try self.emit(.{ .local_get = n });
                try self.emit(.{ .call = sym });
                try self.emit(.@"return");
                const hit_seq = self.seal(&hit, .terminated);
                var guard: Capture = .{};
                self.open(&guard);
                try self.emit(.{ .local_get = "self" });
                try self.emit(try self.constInt(tag_header_bytes));
                try self.emit(opOf(.i32, "sub"));
                try self.emit(.{ .load = .{} });
                try self.emit(try self.constInt(d));
                try self.emit(opOf(.i32, "eq"));
                try self.emitC(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } }, t);
                const guard_seq = self.seal(&guard, .none);
                try self.emit(.{ .local_get = "self" });
                try self.emit(try self.constInt(heap_floor));
                try self.emit(opOf(.i32, "ge_u"));
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = guard_seq } } });
            }
        }
        try self.emitC(.@"unreachable", "no implementer of this behavior method built the value");
        const body = self.seal(&c, .terminated);
        return try self.builder().func(.{
            .name = try std.fmt.allocPrint(self.arena(), "__bdispatch_{s}_{d}", .{ bd.method, bd.argc }),
            .params = params.items,
            .result = if (bd.sig.result) |r| self.vtOf(r) else null,
            .body = body,
        });
    }

    /// Whether a method call at `loc` is answered by its receiver's own type
    /// at run time: inference placed it on a behavior-typed value, named a
    /// type this module declares no record or enum of (the behavior itself),
    /// or placed it nowhere.
    /// Whether `recv.m(…)` is a method inference dispatches by the value
    /// (a behavior-typed receiver) while a function `m` of the module or its
    /// imports is known too: the method wins.
    fn behaviorMethodShadowsFn(self: *Emitter, cc: anytype, loc: ast.Loc) bool {
        if (cc.receiver == null or cc.is_builtin or !self.fn_sigs.contains(cc.callee)) return false;
        const il = self.instance_lowerings.get(loc) orelse return false;
        return il == .by_value;
    }

    fn dispatchesByValue(self: *Emitter, loc: ast.Loc) bool {
        const il = self.instance_lowerings.get(loc) orelse return true;
        return switch (il) {
            .by_value => true,
            .type_, .unplaced_type => |tn| !self.records.contains(tn) and !self.enums.contains(tn),
            else => false,
        };
    }

    fn sameSig(self: *Emitter, a: FnSig, b: FnSig) bool {
        if (a.params.len != b.params.len) return false;
        for (a.params, b.params) |x, y| if (!self.sameVal(x, y)) return false;
        if (a.result == null or b.result == null) return a.result == null and b.result == null;
        return self.sameVal(a.result.?, b.result.?);
    }

    fn emitEntrypointWrapper(self: *Emitter, main_returns_value: bool) !void {
        var c: Capture = .{};
        self.open(&c);
        // The one folded instruction the backend emits, kept for byte-identity
        // with the historical wrapper.
        try self.cur.?.append(self.arena(), .{ .instr = .{ .call = "main" }, .folded = true });
        // The wrapper itself returns nothing, so a value-returning `main` would
        // leave its result on the stack — invalid wasm. Discard it.
        if (main_returns_value) try self.emit(.drop);
        // Decision 392 — the tasks `main` started run on: the ready ones,
        // and on `wasi` the host's answers as they come (the `browser`
        // host's loader drives the rest from the event loop).
        if (self.b.helpers.has(.task)) try self.emitC(self.builder().helper(.task_finish), "the tasks main started");
        const run = self.seal(&c, .none);
        if (!self.exceptions) {
            try self.item(.{ .func = try self.builder().func(.{
                .name = "_botopink_main",
                .exports = &.{ "_botopink_main", "_start" },
                .body = run,
            }) });
            return;
        }
        // Decision 518 — an abort nothing caught leaves `main` as
        // `$__bp_panic`: written as `@panic` writes it (its `print` word), then
        // the trap an abort is.
        const ar = self.arena();
        const try_line: wat.Line = .{ .instr = .{ .block = .{
            .kind = .try_table,
            .catches = try ar.dupe(wat.Block.Catch, &.{.{ .tag = prelude.panic_tag.name, .label = "__uncaught" }}),
            .body = run,
        } } };
        const caught = try self.builder().seq(&.{ try_line, .{ .instr = .@"return" } }, .terminated);
        const fail = self.builder().helper(.panic_fail);
        // Front 164 s2 P4 — in a GC module the payload is an `$exn`.
        const gc = self.mode == .gc;
        const exn: u16 = if (gc) self.gcTyIndex(.exn) else 0;
        const c_vt: ValType = if (gc) .anyref else .i32;
        const msg_read: []const wat.Line = if (gc) &.{
            .{ .instr = .{ .ref_cast = ValType.def(exn) }, .indent = 6 },
            .{ .instr = .{ .struct_get = .{ .ty = exn, .field = 0 } }, .indent = 6, .comment = "the message" },
        } else &.{
            .{ .instr = .{ .load = .{} }, .indent = 6, .comment = "the message" },
        };
        var print_lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        try print_lines.append(ar, .{ .instr = .{ .local_get = "__c" }, .indent = 6 });
        try print_lines.appendSlice(ar, msg_read);
        try print_lines.append(ar, .{ .instr = fail, .indent = 6 });
        const print_arm = try self.builder().seq(print_lines.items, .none);
        var body_lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        try body_lines.appendSlice(ar, &.{
            .{ .instr = .{ .block = .{ .kind = .block, .label = "__uncaught", .result = c_vt, .body = caught } } },
            .{ .instr = .{ .local_set = "__c" }, .comment = "an abort nothing caught (decision 518)" },
            .{ .instr = .{ .local_get = "__c" } },
        });
        if (gc) {
            try body_lines.append(ar, .{ .instr = .{ .ref_cast = ValType.def(exn) } });
            try body_lines.append(ar, .{ .instr = .{ .struct_get = .{ .ty = exn, .field = 1 } }, .comment = "print" });
        } else try body_lines.append(ar, .{ .instr = .{ .load = .{ .offset = 4 } }, .comment = "print" });
        try body_lines.appendSlice(ar, &.{
            .{ .instr = .{ .@"if" = .{ .then = .{ .seq = print_arm } } } },
            .{ .instr = .@"unreachable" },
        });
        const body = try self.builder().seq(body_lines.items, .terminated);
        try self.item(.{ .func = try self.builder().func(.{
            .name = "_botopink_main",
            .exports = &.{ "_botopink_main", "_start" },
            .locals = try self.builder().localLines(&.{.{ .name = "__c", .ty = c_vt }}),
            .body = body,
        }) });
    }

    // ── body ─────────────────────────────────────────────────────────────────

    /// Lower a statement list. `keep_value` says whether the last statement's
    /// value must survive on the operand stack (a function with a `(result …)`,
    /// or an `(if (result …))` branch). The returned `Tail` reports what the
    /// stack actually looks like afterwards, so nested contexts can normalise.
    fn emitBody(self: *Emitter, body: []const ast.Stmt, keep_value: bool) anyerror!Tail {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        if (body.len == 0) {
            if (keep_value) {
                try self.pushZero();
                return .value;
            }
            return .none;
        }
        const mark = self.defer_stack.items.len;
        // The function's own body has `cur_result`; another block answering a
        // value, the type of its last expression (the type a region names).
        const value_ty: ?Repr = if (!keep_value) null else if (self.defer_fn_body != null and
            self.defer_fn_body.?.ptr == body.ptr and self.defer_fn_body.?.len == body.len) self.cur_result else if (hasDefer(body) and !body[body.len - 1].deferred)
            self.wasmTypeOf(body[ast.lastRealIndex(body)].expr)
        else
            null;
        const tail = try self.emitStmtsFrom(body, 0, keep_value, value_ty, true, null);
        try self.closeDefers(mark, tail);
        return tail;
    }

    /// `body[start..]`: every statement but the last for effect, the last as
    /// `emitBody` says. A `defer` is not lowered here: it joins `defer_stack`
    /// and the rest of the list runs under it (`emitDeferRegion` when a panic
    /// can reach it).
    fn emitStmtsFrom(self: *Emitter, body: []const ast.Stmt, start: usize, keep_value: bool, value_ty: ?Repr, regions: bool, hook: ?LastHook) anyerror!Tail {
        var tail: Tail = .none;
        var i = start;
        // A `//` comment written after the tail is no statement of the value.
        const lastAt = if (body.len > start) ast.lastRealIndex(body) else 0;
        while (i < body.len) : (i += 1) {
            const stmt = body[i];
            const is_last = i == lastAt;
            // The comments after the tail emit nothing and leave its `Tail`.
            if (i > lastAt) continue;
            if (stmt.deferred) {
                var plain = stmt;
                plain.deferred = false;
                try self.pushDefer(plain);
                if (regions and self.exceptions and (!keep_value or value_ty != null))
                    return self.emitDeferRegion(body, i + 1, keep_value, value_ty, hook);
                tail = .none;
                continue;
            }
            if (is_last and keep_value and hook != null) {
                tail = try hook.?.run(hook.?.ctx, self, stmt);
            } else tail = try self.emitStmt(stmt, is_last and keep_value);
        }
        // A body whose last statement is a `defer` answers the neutral value.
        if (keep_value and body.len > 0 and body[body.len - 1].deferred) {
            if (value_ty) |t| try self.emit(self.zeroOf(t)) else try self.pushZero();
            tail = .value;
        }
        return tail;
    }

    /// Whether a statement list holds a `defer` of its own.
    fn hasDefer(body: []const ast.Stmt) bool {
        for (body) |s| if (s.deferred) return true;
        return false;
    }

    /// A `defer` joins `defer_stack` with the aliases its names have here.
    fn pushDefer(self: *Emitter, stmt: ast.Stmt) anyerror!void {
        var idents: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectIdents(stmt.expr, &idents);
        const ra = self.reg_arena.allocator();
        var names: std.ArrayListUnmanaged(DeferName) = .empty;
        for (idents.items) |n| {
            var seen = false;
            for (names.items) |have| if (std.mem.eql(u8, have.name, n)) {
                seen = true;
            };
            if (!seen) try names.append(ra, .{ .name = n, .alias = self.aliases.get(n) });
        }
        try self.defer_stack.append(self.alloc, .{ .stmt = stmt, .names = names.items });
    }

    /// The statement of `defer_stack[idx]`, written here. The entries from
    /// `idx` up are out of sight while it is lowered (a `throw` in it leaves
    /// past the ones below only). It is stack-neutral, so a value waiting
    /// beneath it survives.
    fn writeDefer(self: *Emitter, idx: usize) anyerror!void {
        const entry = self.defer_stack.items[idx];
        var hidden: std.ArrayListUnmanaged(DeferEntry) = .empty;
        defer hidden.deinit(self.alloc);
        try hidden.appendSlice(self.alloc, self.defer_stack.items[idx..]);
        self.defer_stack.shrinkRetainingCapacity(idx);
        defer self.defer_stack.appendSliceAssumeCapacity(hidden.items);
        // The names mean what they meant at the `defer`.
        var current: std.ArrayListUnmanaged(DeferName) = .empty;
        defer current.deinit(self.alloc);
        for (entry.names) |dn| {
            try current.append(self.alloc, .{ .name = dn.name, .alias = self.aliases.get(dn.name) });
            if (dn.alias) |a| try self.aliases.put(dn.name, a) else _ = self.aliases.remove(dn.name);
        }
        defer for (current.items) |dn| {
            if (dn.alias) |a| self.aliases.put(dn.name, a) catch {} else _ = self.aliases.remove(dn.name);
        };
        _ = try self.emitStmtNormalised(entry.stmt, false);
    }

    /// A way out of the function or the loop: every pending defer above
    /// `floor`, innermost first. They stay pending for the paths that do not
    /// leave.
    fn runDefers(self: *Emitter, floor: usize) anyerror!void {
        var k = self.defer_stack.items.len;
        while (k > floor) {
            k -= 1;
            // Inside the entry's own panic region: it is marked run, so a
            // panic in it does not reach the region's handler to run it again.
            if (self.defer_stack.items[k].ran_flag) |flag| {
                try self.emit(try self.constInt(1));
                try self.emit(.{ .local_set = flag });
            }
            try self.writeDefer(k);
        }
    }

    /// The end of a block: the defers it pushed (above `mark`) run, last
    /// first, unless the block already left.
    fn closeDefers(self: *Emitter, mark: usize, tail: Tail) anyerror!void {
        while (self.defer_stack.items.len > mark) {
            if (tail != .terminated) try self.writeDefer(self.defer_stack.items.len - 1);
            _ = self.defer_stack.pop();
        }
    }

    /// The rest of a block under a `defer` a panic can reach (decision 518):
    ///
    ///     (block $done (result T)
    ///       (block $h (result i32)
    ///         (try_table (result T) (catch $__bp_panic $h) <the rest>)
    ///         <deferred>  (br $done))
    ///       (local.set $exc)  <deferred>  (local.get $exc)  (throw $__bp_panic))
    ///
    /// The deferred code is written outside the region on both paths, so a
    /// panic in it is not caught twice. The `defer` is the top entry.
    fn emitDeferRegion(self: *Emitter, body: []const ast.Stmt, start: usize, keep_value: bool, value_ty: ?Repr, hook: ?LastHook) anyerror!Tail {
        const ar = self.arena();
        const idx = self.defer_stack.items.len - 1;
        self.defer_seq += 1;
        const handler = try std.fmt.allocPrint(ar, "__defer_h{d}", .{self.defer_seq});
        const done = try std.fmt.allocPrint(ar, "__defer_done{d}", .{self.defer_seq});
        const exc = try std.fmt.allocPrint(ar, "__defer_exc{d}", .{self.defer_seq});
        // The tag's payload: an `$exn` as an `anyref` in a GC module.
        const exc_r: Repr = if (self.mode == .gc) .{ .ref = .unknown } else .i32;
        try self.declareLocal(exc, exc_r);
        const ran = try std.fmt.allocPrint(ar, "__defer_ran{d}", .{self.defer_seq});
        try self.declareLocal(ran, .i32);
        self.defer_stack.items[idx].ran_flag = ran;
        const result: ?wat.ValType = if (keep_value) self.vtOf(value_ty.?) else null;

        var rest_c: Capture = .{};
        self.open(&rest_c);
        var rest_tail = try self.emitStmtsFrom(body, start, keep_value, value_ty, true, hook);
        // A last statement that is no value (`val`, a loop) answers the neutral one.
        if (keep_value and rest_tail == .none) {
            try self.emit(self.zeroOf(value_ty.?));
            rest_tail = .value;
        }
        const rest_seq = self.seal(&rest_c, self.stackOf(rest_tail, if (value_ty) |t| t else .i32));

        var normal_c: Capture = .{};
        self.open(&normal_c);
        try self.emit(try self.constInt(0));
        try self.emit(.{ .local_set = ran });
        try self.emit(.{ .block = .{
            .kind = .try_table,
            .result = result,
            .catches = try ar.dupe(wat.Block.Catch, &.{.{ .tag = prelude.panic_tag.name, .label = handler }}),
            .body = rest_seq,
        } });
        try self.writeDefer(idx);
        try self.emit(.{ .br = done });
        const normal_seq = self.seal(&normal_c, .terminated);

        var caught_c: Capture = .{};
        self.open(&caught_c);
        try self.emit(.{ .block = .{ .kind = .block, .label = handler, .result = self.vtOf(exc_r), .body = normal_seq } });
        try self.emit(.{ .local_set = exc });
        // An exit path inside the region may have run the deferred code (and
        // panicked in it): it runs once.
        var again_c: Capture = .{};
        self.open(&again_c);
        try self.writeDefer(idx);
        const again_seq = self.seal(&again_c, .none);
        try self.emit(.{ .local_get = ran });
        try self.emit(opOf(.i32, "eqz"));
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = again_seq } } });
        try self.emit(.{ .local_get = exc });
        try self.emit(.{ .throw = prelude.panic_tag.name });
        const caught_seq = self.seal(&caught_c, .terminated);

        try self.emit(.{ .block = .{ .kind = .block, .label = done, .result = result, .body = caught_seq } });
        _ = self.defer_stack.pop();
        return if (keep_value) .value else .none;
    }

    fn emitStmt(self: *Emitter, stmt: ast.Stmt, keep_value: bool) anyerror!Tail {
        // Decision 539 — a `defer` is lowered by the statement lists that
        // keep `defer_stack` (`emitStmtsFrom`); this one is another list.
        if (stmt.deferred) return self.refuse(stmt.expr.getLoc(), "a `defer` in this position is not lowered by the wasm backend yet", .{});
        // Decision 392 — a statement of a state machine runs under its
        // resume guard. The one whose value a body answers is not guarded:
        // re-entering never reaches it before the resume index.
        if (self.machine != null and !keep_value) return self.emitGuardedStmt(stmt);
        return self.emitStmtNormalised(stmt, keep_value);
    }

    fn emitStmtNormalised(self: *Emitter, stmt: ast.Stmt, keep_value: bool) anyerror!Tail {
        const outer_loc = self.stmt_loc;
        self.stmt_loc = stmt.expr.getLoc();
        defer self.stmt_loc = outer_loc;
        const tail = try self.emitStmtRaw(stmt);
        // Normalise to what the context asked for: a value where one is
        // required, nothing where one is not. `.terminated` needs neither.
        if (keep_value and tail == .none) {
            try self.pushZero();
            return .value;
        }
        if (!keep_value and tail == .value) {
            try self.emit(.drop);
            return .none;
        }
        return tail;
    }

    fn emitStmtRaw(self: *Emitter, stmt: ast.Stmt) anyerror!Tail {
        switch (stmt.expr) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r0| {
                    // A bare `return` in a generator fn ends the generator
                    // with what it yielded so far, from any arm (164 s2c).
                    if (r0 == null and self.yield_target != null and self.gen_end == null) {
                        try self.emitGenEnd();
                        return .terminated;
                    }
                    const r = try self.adoptTask(r0);
                    if (r) |val| if (try self.lowerSelfTailCall(val.*)) return .terminated;
                    if (r) |val| {
                        // Coerce to the *declared* result: `fn area(…) -> f64`
                        // whose body multiplies f32 literals produced an f32
                        // and the `(result f64)` rejected the whole module.
                        if (val.* == .function) self.expected_fn = self.cur_ret_typeref;
                        if (self.cur_ret_typeref) |rt| if (rt == .generic and self.record_generics.contains(rt.generic.name)) {
                            self.expected_ctor = rt;
                        };
                        defer self.expected_ctor = null;
                        if (self.cur_ret_typeref) |rt| if (isUnionArrayTypeRef(rt) and isArrayLit(val.*)) {
                            self.expected_union_array = true;
                        };
                        defer self.expected_union_array = false;
                        defer self.expected_fn = null;
                        if (self.fn_has_result and self.raw_return and self.mode == .linear) {
                            // A carry wrapper (decision 504): the scope's word,
                            // or — a float or an `i64` — its cell's address,
                            // loaded as the declared type.
                            try self.lowerCoerced(val.*, .i32);
                            const cell = if (self.cur_ret_typeref) |rt| cellOfTypeRef(rt) else .none;
                            if (cell != .none) {
                                try self.emitFromCell(cell);
                                try self.emitConvert(cell.ty(), self.cur_result);
                            }
                        } else if (self.fn_has_result and self.boxesInto(self.cur_ret_typeref, val.*))
                            try self.lowerBoxedInto(self.cur_ret_typeref, val.*)
                        else if (self.fn_has_result)
                            try self.lowerCoerced(val.*, self.cur_result)
                        else {
                            // A `return <expr>` inside a void function must not
                            // carry a value out of it.
                            try self.lowerValue(val.*);
                            try self.emit(.drop);
                        }
                    } else if (self.fn_has_result) {
                        // A bare `return;` in a function that still has a
                        // `(result …)` — a `@Task<void>` carries a word —
                        // leaves with the neutral value, or the module fails
                        // validation ("expected i32 but nothing on stack").
                        try self.pushZero();
                    }
                    // Decision 539 — the value is computed; the defers run
                    // before the function is left.
                    try self.runDefers(0);
                    try self.emit(.@"return");
                    return .terminated;
                },
                .throw_ => |val| {
                    try self.lowerThrow(val);
                    return .terminated;
                },
                .try_ => |val| {
                    if (val) |v| {
                        try self.lowerTryPropagate(v.*);
                        return .value;
                    }
                    return .none;
                },
                .await_ => |av| {
                    try self.lowerAwait(av.*);
                    return if (self.isTaskExpr(av.*)) .value else self.exprTail(av.*);
                },
                .@"break" => |br| {
                    if (br.value) |v| {
                        // Decision 105: `break <v>` in a generator scope
                        // pushes `v` and ends the scope from any loop depth.
                        if (self.yield_target != null) {
                            try self.emitGenBreak(v.*);
                            return .terminated;
                        }
                        try self.lowerValue(v.*);
                        return .value;
                    }
                    if (self.loop_depth > 0) {
                        try self.emitLoopJump(br.label, true);
                        return .terminated;
                    }
                    // Decision 103: a bare `break` at a generator body's own
                    // level ends it — nothing after it is emitted.
                    if (self.yield_target != null) {
                        try self.emitGenEnd();
                        return .terminated;
                    }
                    return .none;
                },
                .yield => |y| {
                    if (y.value) |v| {
                        if (self.yield_target != null) {
                            try self.emitYield(v.*);
                            return .none;
                        }
                        try self.lowerValue(v.*);
                        return .value;
                    }
                    return .none;
                },
                .@"continue" => |cj| {
                    if (self.loop_depth > 0) {
                        try self.emitLoopJump(cj.label, false);
                        return .terminated;
                    }
                    return .none;
                },
            },
            .binding => |b| switch (b.kind) {
                .localBind => |lb0| {
                    // A second binding of a name — a block's `val x` over an
                    // outer `x` (decision 152 keeps that legal: a new scope)
                    // — is a fresh local, aliased until the block ends.
                    var lb = lb0;
                    lb.name = try self.bindTargetAs(lb0.name, self.bindingLocalType(lb0.typeAnnotation, lb0.value.*));
                    defer self.installShadow(lb0.name, lb.name);
                    // `val v = if (c) 2 else "two"` / `val v = case s { … }`
                    // whose arms disagree is the union of its arms (decision
                    // 150, decision 8 §3.2), as the checker typed it: a union
                    // slot, each arm boxed.
                    const unknown_ann: ?ast.TypeRef = lb.typeAnnotation orelse
                        (if (self.unionValueOf(lb.value.*)) |uv| uv.type_ else null);
                    if (unknown_ann) |ta| if (isUnknownTypeRef(ta)) {
                        const unk: Repr = if (self.mode == .gc) .{ .ref = .unknown } else .i32;
                        try self.declareLocal(lb.name, unk);
                        try self.local_typerefs.put(lb.name, ta);
                        if (self.boxesInto(ta, lb.value.*))
                            try self.lowerAsUnknown(lb.value.*)
                        else
                            try self.lowerCoerced(lb.value.*, unk);
                        try self.emit(.{ .local_set = lb.name });
                        return .none;
                    };
                    try self.declareLocal(lb.name, self.bindingLocalType(lb.typeAnnotation, lb.value.*));
                    // A function NAMED as the value (`val g = greet`) types the
                    // local by its declaration, as a written `fn(…) -> T` does:
                    // `g()` then answers `greet`'s declared return. Without it the
                    // call of a string-returning function printed the string's
                    // address at exit 0.
                    // An enum constructor's value is typed by its enum, so the
                    // name prints by the variant's descriptor.
                    const enum_tr: ?ast.TypeRef = if (self.enumValueOf(lb.value.*)) |en| .{ .named = en } else null;
                    const gc_block: ?ast.TypeRef = if (self.mode == .gc and lb.value.* == .function and lb.value.function.kind.syntax == .asyncBlock) try self.asyncBlockTaskType(lb.value.*, false) else null;
                    const bound_tr: ?ast.TypeRef = lb.typeAnnotation orelse (try self.failingAsyncTypeRef(lb.value.*)) orelse gc_block orelse self.typeRefOf(lb.value.*) orelse (try self.fnRefTypeRef(lb.value.*)) orelse enum_tr orelse try self.lambdaTaskTypeRef(lb.value.*);
                    if (bound_tr) |tr| try self.local_typerefs.put(lb.name, tr);
                    // Decision 210 — the composite a `val` holds, for `==`
                    // over the name (`val t = #(P(x: 1), 2)`).
                    _ = self.eq_local_types.remove(lb.name);
                    if (lb.typeAnnotation == null) if (try self.eqTypeOf(lb.value.*)) |et| if (self.eqComposite(et)) {
                        try self.eq_local_types.put(self.arena(), lb.name, et);
                    };
                    // A written `?T` says the local is optional; how the value
                    // carries its absence (boxed or not) is the VALUE's, so it
                    // is asked too: `val c: ?Color = cs[1]` holds a box around
                    // an all-unit enum's ordinal, and read as the bare ordinal
                    // it compared unequal to `Color.Green` and printed the
                    // box's address.
                    const ann_optional = if (lb.typeAnnotation) |ta| ta == .optional else true;
                    if (ann_optional) if (self.optInfoOf(lb.value.*)) |oi| try self.opt_locals.put(lb.name, oi);
                    // A `?f64` written as such is a cell whatever the value is.
                    if (lb.typeAnnotation) |ta| if (self.optInfoOfTypeRef(ta)) |oi| if (oi.cell != .none) try self.opt_locals.put(lb.name, oi);
                    if (self.isStringExpr(lb.value.*)) try self.str_locals.put(lb.name, {});
                    if (self.isBoolExpr(lb.value.*)) try self.bool_locals.put(lb.name, {});
                    // The written type says it too, where the value cannot: a
                    // generic call (`val s: string = first<string>(…)`) answers
                    // a `T`, whose word printed as an address (`276`).
                    if (lb.typeAnnotation) |ta| if (ta == .named) {
                        if (std.mem.eql(u8, ta.named, "string")) try self.str_locals.put(lb.name, {});
                        if (std.mem.eql(u8, ta.named, "bool")) try self.bool_locals.put(lb.name, {});
                    };
                    try self.noteArrayLocal(lb.name, lb.value.*);
                    // A written array type says what an empty literal cannot:
                    // `var names: string[] = []` holds strings, and read off
                    // `[]` its shape was `[i` — `names.push("a")` printed
                    // `[256]`, the string's address, at exit 0.
                    if (lb.typeAnnotation) |ta| try self.noteAnnotatedArray(lb.name, ta);
                    if (self.resultShapeOf(lb.value.*)) |shape| try self.result_shape_locals.put(lb.name, shape);
                    if (self.recordTypeOfExpr(lb.value.*)) |rty| try self.local_types.put(lb.name, rty);
                    // Coerce to the type the local was *actually* declared with:
                    // `emitLocalDecls` runs before the body, so its guess can
                    // differ from what lowering ends up pushing.
                    const lambda_idx: u32 = @intCast(self.lambdas.items.len);
                    self.ctor_lambdas.clearRetainingCapacity();
                    if (lb.typeAnnotation) |ta| if (ta == .generic and self.record_generics.contains(ta.generic.name)) {
                        self.expected_ctor = ta;
                    };
                    defer self.expected_ctor = null;
                    if (lb.typeAnnotation) |ta| if (isUnionArrayTypeRef(ta) and isArrayLit(lb.value.*)) {
                        self.expected_union_array = true;
                    };
                    defer self.expected_union_array = false;
                    if (lb.value.* == .function) self.expected_fn = lb.typeAnnotation;
                    defer self.expected_fn = null;
                    // `val f: fn(a: string, b: string) -> bool = same` over a
                    // generic `same`: the copy the written type binds, as an
                    // argument against such a parameter is (`specializeByFnType`).
                    if (lb.typeAnnotation) |ta| if (plainIdentName(lb.value.*)) |vn| if (!self.locals.contains(vn)) {
                        if (try self.specializeByFnType(self.import_aliases.get(vn) orelse vn, ta)) |sym| {
                            try self.lowerFnRef(sym, null);
                            try self.emit(.{ .local_set = lb.name });
                            _ = self.closure_locals.remove(lb.name);
                            return .none;
                        }
                    };
                    if (self.boxesInto(lb.typeAnnotation, lb.value.*))
                        try self.lowerBoxedInto(lb.typeAnnotation, lb.value.*)
                    else
                        try self.lowerCoerced(lb.value.*, self.locals.get(lb.name) orelse .i32);
                    try self.emit(.{ .local_set = lb.name });
                    // Decision 105 — a local holding an `iter` loop's handle:
                    // its consumers here sync the loop's captures.
                    try self.noteGenLocal(lb.name, lb.value.*, lambda_idx);
                    if (lb.value.* == .function and self.lambdas.items.len > lambda_idx)
                        try self.closure_locals.put(lb.name, lambda_idx)
                    else if (self.fieldClosureOfExpr(lb.value.*)) |li|
                        // `val lf = lam.value` over a constructor-stored lambda.
                        try self.closure_locals.put(lb.name, li)
                    else
                        _ = self.closure_locals.remove(lb.name);
                    // A constructor that stored lambdas: each one by its field —
                    // only when the value IS the constructor call.
                    if (lb.value.* == .call and lb.value.call.kind == .call and lb.value.call.kind.call.receiver == null and self.records.contains(lb.value.call.kind.call.callee)) for (self.ctor_lambdas.items) |cl| {
                        const key = try std.fmt.allocPrint(self.reg_arena.allocator(), "{s}.{s}", .{ lb.name, cl.field });
                        try self.field_closures.put(self.reg_arena.allocator(), key, cl.idx);
                    };
                    self.ctor_lambdas.clearRetainingCapacity();
                },
                .assign => |a| switch (a.target) {
                    // A `var` two linked modules declare is written in the
                    // module the statement is in (`resolveName`).
                    .name => |name0| switch (a.op) {
                        .assign => {
                            const name = self.resolveName(name0);
                            // A scalar flowing into a declared `?T` goes in a
                            // box, exactly as it does at the binding that
                            // declared the slot. Without this, `var h: ?i32 =
                            // null; h = 5;` stored the bare `5` and the reader
                            // took it for a box *address*: `@print(h)` answered
                            // whatever lives at offset 5 — `16777216` — with
                            // exit 0 and no diagnostic.
                            const tr: ?ast.TypeRef = blk: {
                                const n = self.resolveName(name);
                                if (self.local_typerefs.get(n)) |t| break :blk t;
                                if (self.locals.contains(n)) break :blk null;
                                break :blk self.global_typerefs.get(n);
                            };
                            if (self.boxesInto(tr, a.value.*))
                                try self.lowerBoxedInto(tr, a.value.*)
                            else
                                // The slot's declared type wins over the value's.
                                try self.lowerCoerced(a.value.*, self.locals.get(name) orelse
                                    self.global_types.get(name) orelse .i32);
                            try self.emit(if (self.locals.contains(name))
                                .{ .local_set = name }
                            else
                                .{ .global_set = name });
                            try self.writeBackCapture(name);
                        },
                        .plusAssign => {
                            const name = self.resolveName(name0);
                            try self.emit(if (self.locals.contains(name))
                                .{ .local_get = name }
                            else
                                .{ .global_get = name });
                            const t = self.locals.get(name) orelse
                                self.global_types.get(name) orelse .i32;
                            // Decision 332 — `x += y` over `bigint`s is a fresh block.
                            if (self.isBigintAt(b.loc)) {
                                try self.lowerValue(a.value.*);
                                try self.emit(zero);
                                try self.emitStdCall("bigint.add");
                            } else {
                                try self.lowerCoerced(a.value.*, t);
                                try self.emitArith(t, "add", b.loc);
                            }
                            try self.emit(if (self.locals.contains(name))
                                .{ .local_set = name }
                            else
                                .{ .global_set = name });
                            try self.writeBackCapture(name);
                        },
                    },
                    .fieldAccess => |fa| if (self.mode == .gc) {
                        try self.gcFieldAssign(fa, a.op, a.value.*, b.loc);
                    } else {
                        // `recv.field [+]= value` → store at the record's
                        // declared field offset. `+=` reads the current slot,
                        // adds, then writes back. Falls back to a comment when
                        // the receiver's record type can't be recovered.
                        const rty_opt = self.recordTypeOfExpr(fa.receiver.*);
                        const off_opt = if (rty_opt) |rty| self.fieldOffsetIn(rty, fa.field) else null;
                        if (off_opt) |off| switch (a.op) {
                            // A float field's slot holds its `f64` cell: the
                            // new value is a new cell (`lowerSlotWord`), never
                            // a write into the old one, which another value
                            // may share.
                            .assign => {
                                const cell = self.fieldCellIn(rty_opt.?, fa.field);
                                try self.lowerValue(fa.receiver.*);
                                if (cell != .none) try self.lowerCellWord(a.value.*, cell) else try self.lowerValue(a.value.*);
                                try self.emitCf(.{ .store = .{ .offset = off } }, ".{s} =", .{fa.field});
                            },
                            .plusAssign => {
                                const cell = self.fieldCellIn(rty_opt.?, fa.field);
                                const mem = try self.memName(self.nextMem());
                                try self.lowerValue(fa.receiver.*);
                                try self.emit(.{ .local_set = mem });
                                try self.emit(.{ .local_get = mem });
                                try self.emit(.{ .local_get = mem });
                                try self.emit(.{ .load = .{ .offset = off } });
                                if (self.isBigintAt(b.loc)) {
                                    // Decision 332 — the field holds the block's address.
                                    try self.lowerValue(a.value.*);
                                    try self.emit(zero);
                                    try self.emitStdCall("bigint.add");
                                } else if (cell != .none) {
                                    try self.emitFromCell(cell);
                                    try self.lowerCoerced(a.value.*, cell.ty());
                                    try self.emitArith(cell.ty(), "add", b.loc);
                                    try self.emit(self.builder().helper(if (cell == .f64) .box_f64 else .box_i64));
                                } else {
                                    try self.lowerCoerced(a.value.*, .i32);
                                    try self.emitArith(.i32, "add", b.loc);
                                }
                                try self.emitCf(.{ .store = .{ .offset = off } }, ".{s} +=", .{fa.field});
                            },
                        } else return self.refuse(stmt.expr.getLoc(), "the wasm backend cannot place `.{s} =`: the receiver's type is not known here", .{fa.field});
                    },
                },
                .localBindDestruct => |lb| if (self.mode == .gc) {
                    try self.gcDestruct(lb);
                } else {
                    // The value is a pointer to a contiguous run of 4-byte slots
                    // (tuple or record). Load each slot at its offset; named
                    // patterns walk the record's declared field order so
                    // out-of-order destructuring (`{ b, a } = R(7, 11)`) reads
                    // the right slot.
                    const mem = try self.memName(self.nextMem());
                    try self.lowerValue(lb.value.*);
                    try self.emit(.{ .local_set = mem });
                    switch (lb.pattern) {
                        .names => |n| {
                            const recv_rty = self.recordTypeOfExpr(lb.value.*);
                            for (n.fields, 0..) |fld, i| {
                                try self.emit(.{ .local_get = mem });
                                const off: u32 = if (recv_rty) |rty|
                                    (self.fieldOffsetIn(rty, fld.field_name) orelse @as(u32, @intCast(i * 4)))
                                else
                                    @as(u32, @intCast(i * 4));
                                try self.emitLoadOffset(off);
                                // A float or `i64` field holds its cell.
                                if (recv_rty) |rty| try self.emitFromCell(self.fieldCellIn(rty, fld.field_name));
                                // The binder is the field's type, as `.ctor`'s
                                // below: a string field concatenates as text.
                                if (recv_rty) |rty| if (self.fieldTypeIn(rty, fld.field_name)) |ft| {
                                    if (std.mem.eql(u8, ft, "string")) try self.str_locals.put(fld.bind_name, {});
                                    if (std.mem.eql(u8, ft, "bool")) try self.bool_locals.put(fld.bind_name, {});
                                    if (self.resolveRecordName(ft)) |sub| try self.local_types.put(fld.bind_name, sub);
                                };
                                // An optional field's binder is that `?T`: its box, read as one.
                                if (recv_rty) |rty| if (self.fieldTypeRefIn(rty, fld.field_name)) |ftr| if (eagerTypeRef(ftr) == .optional) {
                                    if (self.optInfoOfTypeRef(ftr)) |oi| try self.opt_locals.put(fld.bind_name, oi);
                                };
                                try self.emit(.{ .local_set = fld.bind_name });
                            }
                        },
                        .tuple_ => |bindings| {
                            for (bindings, 0..) |name, i| {
                                try self.noteTupleElemShape(name, lb.value.*, i);
                                try self.emit(.{ .local_get = mem });
                                try self.emitLoadOffset(@intCast(i * 4));
                                const cell = try self.tupleElemCell(lb.value.*, i);
                                if (cell != .none) {
                                    try self.emitFromCell(cell);
                                    if (if (self.locals.get(name)) |have| !self.sameVal(have, cell.ty()) else true)
                                        return self.refuse(stmt.expr.getLoc(), "the wasm backend binds `{s}` to values of two widths in one function", .{name});
                                }
                                try self.emit(.{ .local_set = name });
                            }
                        },
                        // `val Circle(r) = s;` — decision 67's R5: the checker
                        // accepts it only where it cannot fail, so there is no
                        // test, only the reads. A record reads each binding off
                        // the declared field at its position; a variant takes
                        // the `case` arm's binder (`bindPattern`), payload
                        // slots from offset 4.
                        .ctor => |pat| {
                            if (self.ctorRecordFields(pat)) |r| {
                                for (r.binds, 0..) |bind, i| {
                                    if (bind.len == 0) continue;
                                    const cell = self.fieldCellIn(r.record, r.fields[i]);
                                    try self.declareLocal(bind, cell.ty());
                                    if (self.fieldTypeIn(r.record, r.fields[i])) |ft| {
                                        if (std.mem.eql(u8, ft, "string")) try self.str_locals.put(bind, {});
                                        if (std.mem.eql(u8, ft, "bool")) try self.bool_locals.put(bind, {});
                                        if (self.resolveRecordName(ft)) |sub| try self.local_types.put(bind, sub);
                                    }
                                    try self.emit(.{ .local_get = mem });
                                    try self.emitLoadOffset(@intCast(i * 4));
                                    // A float or `i64` field holds its cell.
                                    try self.emitFromCell(cell);
                                    try self.emit(.{ .local_set = bind });
                                }
                            } else if (try self.ctorAsFieldsPattern(pat)) |fp| {
                                try self.bindPattern(fp, mem);
                            } else if (pat == .variant and (self.variantRef(pat.variant.name) != null or self.recordPatternType(pat.variant) != null)) {
                                // A nested constructor (`val Pair(Circle(r), n) = p;`,
                                // 144 B-22 step 13): the `case` arm's walk binds each
                                // name off its field's slot, one level at a time.
                                try self.bindPattern(pat, mem);
                            } else return self.refuse(stmt.expr.getLoc(), "the wasm backend has no lowering for this constructor pattern in a binding", .{});
                        },
                        // A spread-only list is the one list the checker lets
                        // through: `[..rest]` is the whole value.
                        .list => |pat| if (pat == .list and pat.list.elems.len == 0) {
                            if (pat.list.spread) |sp| if (sp.len > 0) {
                                try self.declareLocal(sp, .i32);
                                try self.noteArrayLocal(sp, lb.value.*);
                                try self.emit(.{ .local_get = mem });
                                try self.emit(.{ .local_set = sp });
                            };
                        } else return self.refuse(stmt.expr.getLoc(), "the wasm backend has no lowering for a list pattern with elements in a binding", .{}),
                    }
                },
            },
            else => {
                try self.lowerExpr(stmt.expr);
                return self.exprTail(stmt.expr);
            },
        }
        return .none;
    }

    /// What `lowerExpr(e)` leaves on the operand stack. This is the single
    /// classifier the statement loop, the argument loop and the branch
    /// normaliser all consult; every arm of `lowerExpr` must agree with it,
    /// which is what keeps the emitted module free of stack leftovers and
    /// underflows.
    fn exprTail(self: *Emitter, e: ast.Expr) Tail {
        return switch (e) {
            .literal => |lit| switch (lit.kind) {
                .comment => .none,
                else => .value,
            },
            .useHook => |uh| self.exprTail(uh.kind.inner.*),
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (cc.is_builtin) {
                        if (isVoidBuiltinCall(cc)) break :blk .none;
                        break :blk .value;
                    }
                    // A call the value answers (`lowerBehaviorDispatch`)
                    // pushes what its dispatcher answers — nothing for a
                    // method declared with no return (`c.close()` on a
                    // `Closeable`), which gave the enclosing `fn` a
                    // `(result i32)` it never filled.
                    if (cc.receiver != null and self.instance_lowerings.get(c.loc) != null and self.dispatchesByValue(c.loc)) {
                        const impls = self.behaviorImplementers(cc.callee, cc.args.len) catch break :blk .value;
                        if (impls.len > 0) {
                            const first = std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ impls[0], cc.callee }) catch break :blk .value;
                            if (self.fn_sigs.get(first)) |sig| break :blk if (sig.result != null) Tail.value else Tail.none;
                        }
                    }
                    if (self.primKindAt(cc, c.loc)) |k| {
                        const res = self.primRes(k, cc) orelse break :blk .value;
                        break :blk if (res == .none) Tail.none else Tail.value;
                    }
                    if (self.recordMethodSym(cc, c.loc)) |sym| {
                        if (self.fn_sigs.get(sym)) |sig| break :blk if (sig.result != null) Tail.value else Tail.none;
                    }
                    if (self.calleeSymbol(cc, c.loc)) |sym| {
                        if (self.fn_sigs.get(sym)) |sig| {
                            break :blk if (sig.result != null) Tail.value else Tail.none;
                        }
                    }
                    // Constructors, string/array ops and the unresolved-call
                    // stub all leave exactly one value.
                    break :blk .value;
                },
                .pipeline => .value,
            },
            .jump => |j| switch (j.kind) {
                .@"return", .throw_ => .terminated,
                .@"continue" => if (self.loop_depth > 0) Tail.terminated else Tail.none,
                .try_ => |v| if (v != null) Tail.value else Tail.none,
                .@"break" => |jl| if (jl.value != null)
                    (if (self.yield_target != null) Tail.terminated else Tail.value)
                else if (self.loop_depth > 0) Tail.terminated else Tail.none,
                .yield => |jl| if (jl.value != null and self.yield_target == null) Tail.value else Tail.none,
                .await_ => |a| if (self.isTaskExpr(a.*)) Tail.value else self.exprTail(a.*),
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.exprTail(inner.*),
                else => .value,
            },
            .comptime_ => |ct| switch (ct.kind) {
                .assert, .assertPattern => .none,
                else => .value,
            },
            // Mirror `lowerIfExpr`: an `if` whose branches all end in a void
            // call is emitted in statement form and pushes nothing. Reporting
            // `.value` here made the statement loop `drop` an empty stack and
            // gave the enclosing `fn` a `(result i32)` it never fills.
            .branch => |b| switch (b.kind) {
                .if_ => |i| if (ifIsStatementForm(i)) Tail.none else Tail.value,
                .tryCatch => .value,
            },
            else => .value,
        };
    }

    /// The one predicate `lowerIfExpr`, `exprTail` and `fnHasResult` share:
    /// both arms void ⇒ no `(result …)` on the `(if …)`, no value pushed.
    fn ifIsStatementForm(i: anytype) bool {
        if (!branchIsVoid(i.then_)) return false;
        const els = i.else_ orelse return false;
        return branchIsVoid(els);
    }

    fn bodyTail(self: *Emitter, body: []const ast.Stmt) Tail {
        if (body.len == 0) return .none;
        return self.exprTail(body[ast.lastRealIndex(body)].expr);
    }

    /// Lower `e` guaranteeing exactly one value on the stack. Used wherever an
    /// operand is required (call arguments, stores, bindings): a void-tailed
    /// expression gets a zero, a terminating one gets nothing (the stack is
    /// polymorphic after `return`/`unreachable`).
    fn lowerValue(self: *Emitter, e: ast.Expr) anyerror!void {
        const t = self.exprTail(e);
        try self.lowerExpr(e);
        if (t == .none) try self.pushZero();
    }

    /// Builtin calls that emit *no* operand-stack push (void on the wasm
    /// side). Matches the void arms of `lowerBuiltin` 1:1. New builtins
    /// added here must update this list or be wired through a producing
    /// arm in `lowerBuiltin`.
    /// `@panic(…)` / `@todo()` as an expression (declared `-> noreturn`).
    fn isNoReturnCall(e: ast.Expr) bool {
        return switch (e) {
            .call => |c| switch (c.kind) {
                .call => |cc| cc.is_builtin and (std.mem.eql(u8, cc.callee, "panic") or std.mem.eql(u8, cc.callee, "todo")),
                else => false,
            },
            else => false,
        };
    }

    fn isVoidBuiltinCall(cc: anytype) bool {
        if (!cc.is_builtin) return false;
        const eq = std.mem.eql;
        return eq(u8, cc.callee, "print") or
            eq(u8, cc.callee, "println") or
            eq(u8, cc.callee, "panic") or
            eq(u8, cc.callee, "todo");
    }

    // ── expressions ──────────────────────────────────────────────────────────

    fn lowerExpr(self: *Emitter, e: ast.Expr) anyerror!void {
        switch (e) {
            // `use` is a transparent prefix: lower the wrapped hook call. The
            // enclosing `val` stores the result into its local slot.
            .useHook => |uh| try self.lowerExpr(uh.kind.inner.*),
            .literal => |lit| switch (lit.kind) {
                .numberLit => |n| {
                    // Decision 332 — a `bigint` literal is its block, interned
                    // as a data segment (`lowerBigintLiteral`).
                    if (lexerMod.isBigintText(n)) return self.lowerBigintLiteral(n);
                    // The comptime folder parks *rendered* values (arrays,
                    // records, …) in a `numberLit` node, so the text is not
                    // always a numeral. `f32.const ["calc", …]` is a parse
                    // error that rejects the module — intern such a value as a
                    // string constant instead, which at least loads.
                    if (!isNumericLiteral(n)) {
                        const seg = try self.internString(n);
                        try self.emitC(try self.constInt(seg.offset), "folded non-numeric literal");
                    } else {
                        try self.emit(try numLitConst(self.arena(), n));
                    }
                },
                .null_ => try self.emit(zero),
                .stringLit => |s| try self.emitStrLit(try self.literalBytes(s)),
                // Decisions 519, 520 — a `Bytes` build constant is a data
                // segment laid out as a string's (its `u32` length, the bytes).
                .bytesLit => |bytes| {
                    if (self.mode == .gc) return self.emitStrLit(bytes);
                    const seg = try self.internString(bytes);
                    try self.emit(try self.constInt(seg.offset));
                },
                // Desugared to a `+` chain by the transform pass; never reaches codegen.
                .stringTemplate => unreachable,
                .comment => {},
            },
            .identifier => |id| switch (id.kind) {
                .ident => |n0| {
                    const n = self.resolveName(n0);
                    // `true`/`false` are bound as identifiers (bool builtins),
                    // not literals. wasm has no boolean type — they lower to
                    // the same `i32` 0/1 a comparison yields. Without this they
                    // would emit `global.get $true`, referencing a global that
                    // is never defined.
                    if (std.mem.eql(u8, n, "true")) {
                        try self.emit(one);
                    } else if (std.mem.eql(u8, n, "false")) {
                        try self.emit(zero);
                    } else if (self.locals.contains(n)) {
                        try self.emit(.{ .local_get = n });
                        // Narrowed by a `!= null` test: the name is its payload
                        // inside the branch, and a boxed payload lives one
                        // indirection away.
                        if (self.narrowed_opts.get(n)) |o| {
                            if (o.boxed) try self.emitUnboxPayload(o, "narrowed optional payload");
                        }
                    } else if (self.globals.contains(n)) {
                        try self.emit(.{ .global_get = self.globalName(n) });
                    } else if (self.fn_sigs.contains(n)) {
                        try self.lowerFnRef(self.import_aliases.get(n) orelse n, id.loc);
                    } else if (self.findVariant(n)) |fv| {
                        // a bare unit variant (`Lt`)
                        try self.emitUnitVariant(fv.variants, fv.tag, "", n);
                    } else {
                        // Neither a local nor a module global: a `global.get`
                        // here would make the whole module unloadable
                        // ("unknown global"), and a `0` in its place printed
                        // a wrong value at exit 0.
                        return self.refuse(id.loc, "`{s}` is not bound here: the wasm backend found no local, global, function or variant of that name", .{n});
                    }
                },
                .dotIdent => |name| {
                    // `.Variant` — type inferred from context. Emit the variant
                    // tag if the name uniquely identifies a unit variant.
                    if (self.findVariant(name)) |fv| {
                        // The enum that declares it names the variant's
                        // descriptor: with none, a unit variant of an enum
                        // with payloads carried descriptor `0`, and
                        // `R(q: .Here)` into a `?Place` field printed
                        // `R(q: )`.
                        const ename: []const u8 = if (!enumHasPayload(fv.variants)) "" else blk: {
                            var it = self.enums.iterator();
                            while (it.next()) |entry| if (entry.value_ptr.*.ptr == fv.variants.ptr) break :blk entry.key_ptr.*;
                            break :blk "";
                        };
                        try self.emitUnitVariant(fv.variants, fv.tag, ename, name);
                    } else {
                        return self.refuse(id.loc, "`.{s}` names no variant of an enum this program declares", .{name});
                    }
                },
                .identAccess => |ia| try self.lowerIdentAccess(ia, id.loc),
            },
            .binaryOp => |bin| try self.lowerBinOp(bin.op, bin.lhs.*, bin.rhs.*, bin.loc),
            .unaryOp => |un| switch (un.op) {
                .neg => try self.lowerNeg(un.expr.*, un.loc),
                .not => {
                    try self.lowerExpr(un.expr.*);
                    try self.emit(opOf(.i32, "eqz"));
                },
            },
            .call => |c| {
                const outer_call = self.call_loc;
                self.call_loc = c.loc;
                defer self.call_loc = outer_call;
                switch (c.kind) {
                    .call => |cc| {
                        // Decision 504 — a value read back from the render
                        // scope is typed by the call that carries it
                        // (`wat/scope_carry.zig`); one left as the lowering
                        // wrote it carried no type this backend can hold —
                        // unresolved, or a float / `i64` no slot here holds
                        // as a word. Only a carry wrapper calls std's own.
                        if (cc.receiver == null and !self.raw_return and isScopeReadFn(cc.callee))
                            return self.refuse(c.loc, "the wasm backend cannot read this value back from a component's render scope: its type is not known here, or it is not one word (a float, an `i64`)", .{});
                        // Static extension dispatch (F6) — resolve to the mangled
                        // linear-memory function `$<target>_<method>` before the
                        // ordinary call-kind handling.
                        if (try self.lowerGenSyncedCall(e, cc)) return;
                        if (try self.lowerDispatchCall(cc, c.loc)) return;
                        // Decision 105 (144 B-128) — a method over a generator
                        // handle (§ generators).
                        if (self.mode == .gc) {
                            if (try self.lowerGenMethod(e)) return;
                            if (cc.receiver) |recv| if (self.isGenExpr(recv.*)) return self.gcFail("a method over a generator this backend does not step");
                        }
                        if (self.instance_lowerings.get(c.loc)) |il| if (il == .sequence_next) {
                            try self.lowerSequenceNext(cc);
                            return;
                        };
                        if (try self.lowerChainedCall(cc, c.loc)) return;
                        if (try self.lowerOptionalTypedMethod(c)) return;
                        if (self.primKindAt(cc, c.loc)) |k| {
                            try self.lowerPrimMethod(k, cc);
                            return;
                        }
                        // A host-backed method (`hostMethods`): wasm has no host,
                        // so the call is refused where it is written, as a
                        // module-level host function's is (`lowerPlainCall`).
                        if (hostMethods.missingAt(self.cross, &self.instance_lowerings, c.loc, cc.callee, .wasm)) |me| {
                            self.missing_external = me;
                            return error.MissingExternalTarget;
                        }
                        if (try self.lowerRecordMethod(cc, c.loc)) return;
                        if (self.primAssocHelper(cc)) |h| {
                            try self.lowerCoerced(callArg(cc, 0).?, .i32);
                            try self.emitStdCall(h);
                            return;
                        }
                        if (self.bigintAssoc(cc)) |which| return self.lowerBigintAssoc(which, cc);
                        if (self.isBytesFromUtf8(cc)) return self.lowerCoerced(callArg(cc, 0).?, if (self.mode == .gc) Repr.string else .i32);
                        if (self.assocSym(cc)) |sym_tmp| {
                            const generic = try self.arena().dupe(u8, sym_tmp);
                            const spec = (try self.specializeFor(generic, cc.args)) orelse
                                (if (self.generic_methods.contains(generic)) try self.specializeMethod(generic, cc) else null);
                            const sym = spec orelse generic;
                            try self.lowerCallArgs(cc.args, self.fn_sigs.get(sym).?, 0);
                            if (spec == null and self.generic_fns.contains(sym)) try self.noteTemplateCall(sym, c.loc);
                            try self.emit(.{ .call = sym });
                            if (spec == null and self.iface_assoc.contains(sym) and !self.assoc_emitted.contains(sym))
                                try self.assoc_needed.append(self.alloc, sym);
                            return;
                        }
                        // String slice method (`s.slice(a, b)`) — handled before the
                        // ctor/plain classification (codegen is untyped). A `slice`
                        // on a `Slice<V>` value is the value's (`lowerPlainCall`).
                        if (isStrSlice(cc) and !self.answeredByValue(cc, c.loc)) {
                            try self.lowerStrSlice(cc);
                            return;
                        }
                        switch (self.callKind(cc)) {
                            .builtin => try self.lowerBuiltin(cc, c.loc),
                            .record_ctor => try self.lowerRecordCtor(cc, self.records.get(cc.callee).?),
                            .enum_ctor => {
                                if (receiverName(cc)) |rcv| {
                                    const variants = self.enums.get(rcv).?;
                                    for (variants, 0..) |v, i| {
                                        if (std.mem.eql(u8, v.name, cc.callee)) {
                                            try self.lowerEnumCtor(cc, @intCast(i), v);
                                            return;
                                        }
                                    }
                                    return self.refuse(c.loc, "`{s}.{s}` names no variant of `{s}`", .{ rcv, cc.callee, rcv });
                                } else if (self.findVariant(cc.callee)) |fv| {
                                    try self.lowerEnumCtor(cc, fv.tag, fv.variant);
                                }
                            },
                            .plain => try self.lowerPlainCall(cc, c.loc),
                        }
                    },
                    .pipeline => |pl| {
                        switch (pl.rhs.*) {
                            .identifier => |pid| switch (pid.kind) {
                                .ident => |name| {
                                    if (self.fn_sigs.get(name)) |sig| {
                                        try self.lowerValue(pl.lhs.*);
                                        try self.emit(.{ .call = self.import_aliases.get(name) orelse name });
                                        if (sig.result == null) try self.pushZero();
                                    } else {
                                        return self.refuse(c.loc, "`{s}` is not a function the wasm backend can pipe into", .{name});
                                    }
                                },
                                else => return self.refuse(c.loc, "the wasm backend pipes only into a named function", .{}),
                            },
                            else => try self.lowerValue(pl.rhs.*),
                        }
                    },
                }
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| try self.lowerIfExpr(i),
                .tryCatch => |tc| try self.lowerTryCatch(tc),
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| try self.lowerExpr(inner.*),
                .case => |c| try self.lowerCase(c),
                .tupleLit => |tl| try self.lowerTupleLit(tl),
                .arrayLit => |al| try self.lowerArrayLit(al, e.getLoc()),
                .behaviorLit => |il| try self.lowerBehaviorLit(il),
                .range => return self.refuse(e.getLoc(), "the wasm backend has no lowering for a range outside an index or a pattern", .{}),
            },
            .jump => |j| switch (j.kind) {
                .@"return" => |r0| {
                    if (r0 == null and self.yield_target != null and self.gen_end == null) {
                        try self.emitGenEnd();
                        return;
                    }
                    const r = try self.adoptTask(r0);
                    if (r) |val| if (try self.lowerSelfTailCall(val.*)) return;
                    if (r) |val| try self.lowerExpr(val.*) else if (self.fn_has_result) try self.pushZero();
                    try self.runDefers(0);
                    try self.emit(.@"return");
                },
                .throw_ => |val| try self.lowerThrow(val),
                .try_ => |val| {
                    if (val) |v| try self.lowerTryPropagate(v.*);
                },
                .await_ => |av| try self.lowerAwait(av.*),
                .@"break" => |br| {
                    if (br.value) |v| {
                        if (self.yield_target != null) {
                            // Decision 105 — see the statement-position arm above.
                            try self.emitGenBreak(v.*);
                        } else try self.lowerExpr(v.*);
                    } else if (self.loop_depth > 0) {
                        try self.emitLoopJump(br.label, true);
                    } else if (self.yield_target != null) {
                        // Decision 103 — see the statement-position arm above.
                        try self.emitGenEnd();
                    }
                },
                .yield => |y| {
                    if (y.value) |v| {
                        if (self.yield_target != null) try self.emitYield(v.*) else try self.lowerExpr(v.*);
                    }
                },
                .@"continue" => |cj| if (self.loop_depth > 0) {
                    try self.emitLoopJump(cj.label, false);
                } else return self.refuse(e.getLoc(), "`continue` outside a loop", .{}),
            },
            .comptime_ => |ct| switch (ct.kind) {
                .assert => |a| try self.lowerAssert(a, ct.loc),
                .assertPattern => |ap| try self.lowerAssertPattern(ap, ct.loc),
                else => return self.refuse(ct.loc, "the wasm backend has no lowering for the comptime construct `{s}`", .{@tagName(ct.kind)}),
            },
            .function => |f| if (f.kind.syntax == .asyncBlock)
                try self.lowerAsyncBlock(f.kind.body)
            else {
                // A typed function expression (`fn(x: i32) -> i32 { … }`)
                // is written against its own function type (decision 408).
                if (self.mode == .gc and self.expected_fn == null and f.kind.syntax == .fnExpr and f.kind.paramTypes.len == f.kind.params.len) if (f.kind.returnType) |rt| {
                    const ra = self.reg_arena.allocator();
                    const ret = try ra.create(ast.TypeRef);
                    ret.* = rt;
                    self.expected_fn = .{ .function = .{ .params = try ra.dupe(ast.TypeRef, f.kind.paramTypes), .returnType = ret } };
                };
                try self.lowerLambdaValue(f.kind.params, f.kind.body, e.getLoc());
            },
            .loop => |lp| try self.lowerLoop(lp),
            else => return self.refuse(e.getLoc(), "the wasm backend has no lowering for a `{s}` expression", .{@tagName(e)}),
        }
    }

    // A `@Result` lives in linear memory as a pointer: the tag is the `i32` at
    // `[ptr]` (0 = Ok, non-zero = Error) and the payload is the `i32` at `[ptr+4]`.
    // `try`/`catch` branch on that tag with `if`/`else` — never host exceptions.

    /// `try expr catch handler` → load the tag; Ok yields `[ptr+4]`, Error runs
    /// the handler. Leaves the resulting value on the stack.
    /// `assert cond[, msg]` — always fatal (decision 4 of the 1.0.2-beta
    /// semantics decisions), a panic (decision 527 (2)) whose message is
    /// `assertion failed: <condition>[: <msg>] at <file:line:col>`, as on
    /// every target: raised as `$__bp_panic` when the program reaches
    /// `attempt` (decision 518), else written to stderr before the trap.
    fn lowerAssert(self: *Emitter, a: anytype, loc: ast.Loc) anyerror!void {
        try self.lowerCoerced(a.condition.*, .i32);
        try self.emit(opOf(.i32, "eqz"));
        var then_c: Capture = .{};
        self.open(&then_c);
        const file = if (self.src_path.len > 0) self.src_path else try std.fmt.allocPrint(self.arena(), "{s}.bp", .{if (self.module_name.len > 0) self.module_name else "main"});
        const head = try ast.assertHead(self.arena(), a.text);
        const at = try ast.assertWhere(self.arena(), file, loc);
        if (a.message) |m| {
            try self.emitStrLit(try std.fmt.allocPrint(self.arena(), "{s}: ", .{head}));
            try self.lowerCoerced(m.*, Repr.string);
            try self.emit(self.builder().helper(.str_concat));
            try self.emitStrLit(try std.fmt.allocPrint(self.arena(), " at {s}", .{at}));
            try self.emit(self.builder().helper(.str_concat));
        } else {
            try self.emitStrLit(try std.fmt.allocPrint(self.arena(), "{s} at {s}", .{ head, at }));
        }
        if (self.exceptions) {
            try self.emit(one);
            try self.emit(self.builder().helper(.panic_raise));
        } else {
            try self.emit(self.builder().helper(.panic_fail));
        }
        try self.emit(.@"unreachable");
        const then_seq = self.seal(&then_c, .terminated);
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq } } });
    }

    /// `val assert P = e [catch h];` (decision 8 § 9). The subject is staged in
    /// a local, the pattern's own test decides, and the pattern's names are
    /// bound in the function's locals — where the statements after it read
    /// them. A mismatch runs the handler: the `@panic(…)` the parser desugars
    /// the handler-less form to traps, a written `catch <value>` replaces the
    /// staged subject so the bindings come from it.
    ///
    /// The local a pattern is matched against, given what its subject is: a
    /// tuple's shape (what a tuple pattern reads its elements by), an array's
    /// shape and element kind (what a list pattern reads).
    fn noteSubjectShape(self: *Emitter, local: []const u8, subject: ast.Expr) !void {
        if (try self.printShapeOf(subject)) |sh| if (sh[0] == '(' or sh[0] == '[') try self.print_shape_locals.put(local, sh);
        if (self.isArrayExpr(subject)) {
            try self.arr_locals.put(local, {});
            try self.arr_elem_locals.put(local, self.elemKindOf(subject));
        }
    }

    /// True when `emitPatternTest` produces a real test for `p`. A variant
    /// pattern naming neither an enum variant nor a `@Result` arm — a record
    /// constructor, say — falls back to a constant `0`, which as a `val
    /// assert` test would mean "never matches" and make every such assert
    /// fatal. There the assert is lowered as a plain binding instead, which is
    /// what the construct did before it was lowered at all.
    fn patternTestIsReal(self: *Emitter, p: ast.Pattern) bool {
        return switch (p) {
            .variant => |v| self.variantRef(v.name) != null or self.recordPatternType(v) != null,
            .@"or" => |pats| blk: {
                for (pats) |sub| {
                    if (!self.patternTestIsReal(sub)) break :blk false;
                }
                break :blk true;
            },
            else => true,
        };
    }

    fn lowerAssertPattern(self: *Emitter, ap: anytype, loc: ast.Loc) anyerror!void {
        const slot = try std.fmt.allocPrint(self.arena(), "__assert_{d}", .{self.assert_seq});
        self.assert_seq += 1;
        try self.declareLocal(slot, .i32);
        try self.lowerCoerced(ap.expr.*, .i32);
        try self.emit(.{ .local_set = slot });
        if (self.isStringExpr(ap.expr.*)) try self.str_locals.put(slot, {});
        if (self.resultShapeOf(ap.expr.*)) |shape| try self.result_subjects.put(slot, shape);
        try self.noteSubjectShape(slot, ap.expr.*);

        if (!self.patternIsIrrefutable(ap.pattern) and self.patternTestIsReal(ap.pattern)) {
            try self.emitPatternTest(ap.pattern, slot, loc);
            try self.emit(opOf(.i32, "eqz"));
            var then_c: Capture = .{};
            self.open(&then_c);
            const handler_tail = self.exprTail(ap.handler.*);
            try self.lowerExpr(ap.handler.*);
            if (handler_tail == .value) try self.emit(.{ .local_set = slot });
            const then_seq = self.seal(&then_c, if (handler_tail == .terminated) .terminated else .none);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq } } });
        }
        try self.bindPattern(ap.pattern, slot);
    }

    /// `throw e`. Inside a fn that returns a `@Result` the transform rewrites
    /// the common forms into `return __bp_error(e)`; one it left behind (inside
    /// a `case` arm, say) still returns the Error rather than trapping. Anywhere
    /// else there is nothing to unwind to, so it traps.
    fn lowerThrow(self: *Emitter, val: ?*ast.Expr) anyerror!void {
        if (self.fn_returns_result and self.fn_has_result) {
            const slot = try self.declRes();
            try self.allocResultPair(slot);
            try self.emit(.{ .local_get = slot });
            try self.emit(one);
            try self.emitC(.{ .store = .{} }, "Result tag (Error)");
            try self.emit(.{ .local_get = slot });
            if (val) |v| try self.lowerCoerced(v.*, .i32) else try self.emit(zero);
            try self.emitC(.{ .store = .{ .offset = 4 } }, "payload");
            try self.emit(.{ .local_get = slot });
            try self.runDefers(0);
            try self.emit(.@"return");
            return;
        }
        if (val) |v| {
            try self.lowerValue(v.*);
            try self.emit(.drop);
        }
        try self.emit(.@"unreachable");
    }

    fn lowerTryCatch(self: *Emitter, tc: anytype) anyerror!void {
        if (self.mode == .gc) return self.gcTryCatch(tc);
        const slot = try self.tryName(self.try_seq);
        self.try_seq += 1;
        try self.declareLocal(slot, .i32);
        try self.lowerValue(tc.expr.*);
        try self.emit(.{ .local_set = slot });
        try self.emit(.{ .local_get = slot });
        try self.emitC(.{ .load = .{} }, result_tag);

        // An `f64` / `i64` payload is its cell's address.
        const cell = self.resultOkCell(tc.expr.*);
        const ty = if (cell != .none) self.vtOf(cell.ty()) else self.vtOf(self.cur_result);
        var then_c: Capture = .{};
        self.open(&then_c);
        if (cell != .none) try self.lowerCoerced(tc.handler.*, cell.ty()) else try self.lowerExpr(tc.handler.*);
        const then_seq = self.seal(&then_c, .{ .value = ty });

        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emit(.{ .local_get = slot });
        try self.emitC(.{ .load = .{ .offset = 4 } }, ok_payload);
        try self.emitFromCell(cell);
        const else_seq = self.seal(&else_c, .{ .value = ty });

        try self.emit(.{ .@"if" = .{
            .result = ty,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
    }

    /// `try expr` (no catch) → unwrap the Ok payload, or `return` the Result
    /// pointer unchanged to propagate the Error variant up. Leaves the unwrapped
    /// Ok payload on the stack.
    fn lowerTryPropagate(self: *Emitter, inner: ast.Expr) anyerror!void {
        if (self.mode == .gc) return self.gcTryPropagate(inner);
        const slot = try self.tryName(self.try_seq);
        self.try_seq += 1;
        try self.declareLocal(slot, .i32);
        try self.lowerValue(inner);
        try self.emit(.{ .local_set = slot });
        try self.emit(.{ .local_get = slot });
        try self.emitC(.{ .load = .{} }, result_tag);

        var then_c: Capture = .{};
        self.open(&then_c);
        if (self.yield_target) |tgt| {
            // Decision 122 — in a sequence whose item is a `@Result`, a
            // failing `try` emits the Error as the last item and ends (the
            // scope's `break <v>`).
            try self.emit(.{ .local_get = tgt });
            try self.emit(.{ .local_get = slot });
            try self.emit(self.builder().helper(.arr_push));
            try self.emit(.{ .local_set = tgt });
            if (self.gen_end) |label| {
                try self.emit(.{ .br = label });
            } else {
                try self.emitC(.{ .local_get = tgt }, "everything the body yielded");
                try self.emitConvert(.i32, self.cur_result);
                try self.runDefers(0);
                try self.emit(.@"return");
            }
        } else {
            try self.emit(.{ .local_get = slot });
            try self.runDefers(0);
            try self.emitC(.@"return", "propagate Error");
        }
        const then_seq = self.seal(&then_c, .terminated);

        try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq } } });
        try self.emit(.{ .local_get = slot });
        try self.emitC(.{ .load = .{ .offset = 4 } }, ok_payload);
        try self.emitFromCell(self.resultOkCell(inner));
    }

    /// Front 164 s2 P2 — `recv.field = value` and `recv.field += value` in a
    /// GC module: `struct.set` of the field of the receiver's record type.
    fn gcFieldAssign(self: *Emitter, fa: anytype, op: anytype, value: ast.Expr, loc: ast.Loc) anyerror!void {
        const rty = self.recordTypeOfExpr(fa.receiver.*) orelse return self.gcFail("a field written on a receiver of no known record");
        const off = self.fieldOffsetIn(rty, fa.field) orelse return self.gcFail("a field the record does not declare");
        const ft = self.fieldTypeRefIn(rty, fa.field) orelse return self.gcFail("a field with no type");
        const rrepr: Repr = .{ .ref = .{ .record = rty } };
        const ref: wat.FieldRef = .{ .ty = self.gcTyIndex(.{ .record = rty }), .field = off / 4 };
        // A field of a generic record that mentions its type parameters: the
        // value goes in as a constructor's argument does (erased, boxed).
        if (self.gcGenericFieldDecl(rty, fa.field)) |efr| {
            if (op != .assign) return self.gcFail("a compound write of a generic record's type parameter field");
            try self.lowerCoerced(fa.receiver.*, rrepr);
            try self.gcGenericArg(ft, self.record_generics.get(rty).?, efr, value);
            try self.emit(.{ .struct_set = ref });
            return;
        }
        const fr = self.reprOf(ft);
        switch (op) {
            .assign => {
                try self.lowerCoerced(fa.receiver.*, rrepr);
                if (self.boxesInto(ft, value)) try self.lowerBoxedInto(ft, value) else try self.lowerCoerced(value, fr);
                try self.emit(.{ .struct_set = ref });
            },
            .plusAssign => {
                if (self.isBigintAt(loc)) return self.gcFail("a bigint field");
                const mem = try self.gcTemp(rrepr);
                try self.lowerCoerced(fa.receiver.*, rrepr);
                try self.emit(.{ .local_set = mem });
                try self.emit(.{ .local_get = mem });
                try self.emit(.{ .local_get = mem });
                try self.emit(.{ .struct_get = ref });
                try self.lowerCoerced(value, fr);
                try self.emitArith(fr, "add", loc);
                try self.emit(.{ .struct_set = ref });
            },
        }
    }

    /// Front 164 s2 P2 — an argument a GC module prints by a generated
    /// printer: a record by its declaration. False for what the other paths
    /// print (`lowerPrintArg`).
    fn gcPrintArg(self: *Emitter, arg: ast.Expr, last: bool) anyerror!bool {
        const r = self.wasmTypeOf(arg);
        if (self.optInfoOf(arg)) |oi| return self.gcPrintOpt(arg, oi, last);
        if (r == .ref) switch (r.ref) {
            .record => |rty| {
                const sym = try self.gcDeclPrinter(rty, null);
                if (self.optInfoOf(arg) != null) {
                    // A record that may be absent prints `null`.
                    const tmp = try self.gcTemp(r);
                    try self.lowerCoerced(arg, r);
                    try self.emit(.{ .local_tee = tmp });
                    try self.emit(.ref_is_null);
                    var then_c: Capture = .{};
                    self.open(&then_c);
                    try self.gcPutStr("null");
                    const then_seq = self.seal(&then_c, .none);
                    var else_c: Capture = .{};
                    self.open(&else_c);
                    try self.emit(.{ .local_get = tmp });
                    try self.emit(.{ .call = sym });
                    const else_seq = self.seal(&else_c, .none);
                    try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                } else {
                    try self.lowerCoerced(arg, r);
                    try self.emit(.{ .call = sym });
                }
                if (last) try self.emit(self.builder().helper(.print_nl));
                return true;
            },
            .enum_ => {
                if (self.optInfoOf(arg) != null) return self.gcFail("an optional enum");
                self.gc_tagged_used = true;
                try self.lowerCoerced(arg, r);
                try self.emit(.{ .call = "__print_tagged_raw" });
                if (last) try self.emit(self.builder().helper(.print_nl));
                return true;
            },
            else => {},
        };
        // An array, a tuple or an all-unit enum: the printer of its shape.
        if (try self.printShapeOf(arg)) |shape| switch (shape[0]) {
            '[', '(', 'E', 'R' => {
                const sym = try self.gcPrinter(shape);
                try self.lowerValue(arg);
                try self.emit(.{ .call = sym });
                if (last) try self.emit(self.builder().helper(.print_nl));
                return true;
            },
            else => {},
        };
        return false;
    }

    /// One `@print` argument. `last` decides whether the trailing newline is
    /// emitted here (the `_raw` helpers write the value only). The printer is
    /// picked from the argument's recovered shape — everything used to go
    /// through `$__print_i32`, so a string printed as its *address* and a bool
    /// as `0`/`1`.
    fn lowerPrintArg(self: *Emitter, arg: ast.Expr, last: bool) anyerror!void {
        // A bare `null` carries no type to pick a printer by, and its word `0`
        // went through the integer printer: it prints the word `null`.
        if (isNullLit(arg)) {
            if (self.mode == .gc) try self.gcPutStr("null") else try self.emit(self.builder().helper(.print_null));
            if (last) try self.emit(self.builder().helper(.print_nl));
            return;
        }
        // Decision 332 — a `bigint` prints its digits (std-wasm's `bigint.toString`); a
        // `?bigint` has no reader here yet.
        if (self.isOptBigintExpr(arg)) {
            // The block's address, or `0` for absence.
            const tmp = try self.declRes();
            try self.lowerValue(arg);
            try self.emit(.{ .local_tee = tmp });
            try self.emit(opOf(.i32, "eqz"));
            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emit(self.builder().helper(.print_null));
            const then_seq = self.seal(&then_c, .none);
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emit(.{ .local_get = tmp });
            try self.emitStdCall("bigint.toString");
            try self.emit(self.builder().helper(.print_str_raw));
            const else_seq = self.seal(&else_c, .none);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
            if (last) try self.emit(self.builder().helper(.print_nl));
            return;
        }
        if (self.isBigintExpr(arg)) {
            try self.lowerValue(arg);
            try self.emitStdCall("bigint.toString");
            try self.emit(self.builder().helper(if (last) .print_str else .print_str_raw));
            return;
        }
        if (self.mode == .gc) if (try self.gcPrintArg(arg, last)) return;
        // A value of a generic `type` that declares `display` prints through
        // `$__display_of`, which calls the ONE generic body of that method:
        // a call no specialisation reached (`refuseUnboundTemplateCalls`).
        if (self.recordTypeOfExpr(arg)) |rec| {
            const dsym = try std.fmt.allocPrint(self.arena(), "{s}_display", .{rec});
            if (self.generic_methods.contains(dsym)) try self.noteTemplateCall(dsym, arg.getLoc());
        }
        // §7 F2/F3 are not this front's — a value has to know which named type
        // it is at run time, which is `13-module-identity`. Until then a record
        // or a variant reaching `@print` has **no text**, and the numeric
        // printer answered its heap address: `328`, `336`, `344` with exit 0 and
        // no diagnostic. That is the one thing this backend must not do.
        // §7 F2/F3 — a value that carries its own declaration prints as the
        // source writes it, read from the VALUE's header and not from this
        // site. A variant of an ALL-UNIT enum is the ordinal itself, with no
        // allocation and so no header, and still has no printed form: it is
        // refused rather than reading four bytes behind an integer.
        // A field or a name declared as an enum with a payload variant
        // (`a.place`, `val p: Place`): every value of it — a unit variant too
        // — is a tagged cell carrying its variant's descriptor. Neither
        // `namedShapeOf` nor `isTaggedValue` reads a declared type, and the
        // numeric printer answered the cell's address.
        // A `?Place` of such an enum (a local, `r.q`): the cell or `0`, which
        // `$__print_opt_tagged` prints `null`; through the integer printer it
        // answered the cell's address.
        if (self.optPayloadEnumOf(arg) != null) {
            try self.lowerCoerced(arg, .i32);
            try self.emit(self.builder().helper(if (last) .print_opt_tagged else .print_opt_tagged_raw));
            return;
        }
        if (self.payloadEnumOfName(arg) != null) {
            try self.lowerCoerced(arg, .i32);
            try self.emit(self.builder().helper(if (last) .print_tagged else .print_tagged_raw));
            return;
        }
        if (self.namedShapeOf(arg)) |ns| {
            // A record that may be ABSENT — `es.at(0)`, or a name bound to one.
            // The tagged printer reads a header four bytes behind the value, so
            // a `0` would read out of bounds; `$__print_opt_tagged` answers
            // `undefined` for it and the header for anything else.
            if (self.optInfoOf(arg)) |oi| if (oi.rec != null) {
                try self.lowerCoerced(arg, .i32);
                try self.emit(self.builder().helper(if (last) .print_opt_tagged else .print_opt_tagged_raw));
                return;
            };
            if (self.isTaggedValue(arg)) {
                try self.lowerCoerced(arg, .i32);
                try self.emit(self.builder().helper(if (last) .print_tagged else .print_tagged_raw));
                return;
            }
            // A CONTAINER of such values is printed by its shape, whose `T`
            // arm reads each element's own header.
            if (try self.printShapeOf(arg)) |_| {} else {
                return self.refuse(arg.getLoc(), "the wasm backend has no printed form for this {s}: a variant of an all-unit enum is its ordinal, with no header naming its type", .{@tagName(ns)});
            }
        }
        // An `unknown` / union value prints by what its box says it holds.
        if (self.isUnknownExpr(arg)) {
            if (self.mode == .gc) {
                try self.lowerCoerced(arg, .{ .ref = .unknown });
                try self.emit(.{ .call = try self.gcUnkPrint(false) });
                if (last) try self.emit(self.builder().helper(.print_nl));
                return;
            }
            try self.lowerCoerced(arg, .i32);
            try self.emit(self.builder().helper(if (last) .print_unknown else .print_unknown_raw));
            return;
        }
        if (self.optInfoOf(arg)) |oi| {
            // A `?Color` of an all-unit enum: a box around the ordinal, which
            // prints `null` or the variant's name. Through `$__print_opt_i32`
            // it printed the ordinal.
            if (oi.boxed and !oi.bool_ and oi.cell == .none) if (try self.optUnitEnumShape(arg, oi)) |shape| {
                const tmp = try self.declRes();
                try self.lowerValue(arg);
                try self.emit(.{ .local_tee = tmp });
                try self.emit(opOf(.i32, "eqz"));
                var then_c: Capture = .{};
                self.open(&then_c);
                try self.emit(self.builder().helper(.print_null));
                const then_seq = self.seal(&then_c, .none);
                var else_c: Capture = .{};
                self.open(&else_c);
                try self.emit(.{ .local_get = tmp });
                try self.emitC(.{ .load = .{} }, "optional payload");
                const seg = try self.internString(shape);
                try self.emit(try self.constInt(seg.offset + 4));
                try self.emit(try self.constInt(1));
                try self.emit(self.builder().helper(.print_shaped_raw));
                try self.emit(.drop);
                const else_seq = self.seal(&else_c, .none);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                if (last) try self.emit(self.builder().helper(.print_nl));
                return;
            };
            // A `?T[]` of a scalar `T` — `m.at(1)` on a `Matrix` whose `at`
            // answers `?i32[]`: the value is the array's own pointer and `0`
            // its absence, so it prints `null` or the array. Through the
            // integer printer it answered the row's address (`384`).
            if (!oi.boxed and !oi.str) if (oi.inner) |inner| if (arrayScalarCode(inner)) |code| {
                const tmp = try self.declRes();
                try self.lowerValue(arg);
                try self.emit(.{ .local_tee = tmp });
                try self.emit(opOf(.i32, "eqz"));
                var then_c: Capture = .{};
                self.open(&then_c);
                try self.emit(self.builder().helper(.print_null));
                if (last) try self.emit(self.builder().helper(.print_nl));
                const then_seq = self.seal(&then_c, .none);
                var else_c: Capture = .{};
                self.open(&else_c);
                try self.emit(.{ .local_get = tmp });
                try self.emit(self.builder().helper(if (code == 'f')
                    (if (last) .print_arr_f64 else .print_arr_f64_raw)
                else if (last) .print_arr_i32 else .print_arr_i32_raw));
                const else_seq = self.seal(&else_c, .none);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                return;
            };
            if (!oi.boxed and !oi.str) if (oi.shape) |shape| {
                const tmp = try self.declRes();
                try self.lowerValue(arg);
                try self.emit(.{ .local_tee = tmp });
                try self.emit(opOf(.i32, "eqz"));
                var then_c: Capture = .{};
                self.open(&then_c);
                try self.emit(self.builder().helper(.print_null));
                const then_seq = self.seal(&then_c, .none);
                var else_c: Capture = .{};
                self.open(&else_c);
                try self.emit(.{ .local_get = tmp });
                const seg = try self.internString(shape);
                try self.emit(try self.constInt(seg.offset + 4));
                try self.emit(try self.constInt(1));
                try self.emit(self.builder().helper(.print_shaped_raw));
                try self.emit(.drop);
                const else_seq = self.seal(&else_c, .none);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                if (last) try self.emit(self.builder().helper(.print_nl));
                return;
            };
            try self.lowerValue(arg);
            const b = self.builder();
            try self.emit(if (oi.boxed)
                b.helper(if (oi.bool_)
                    (if (last) .print_opt_bool else .print_opt_bool_raw)
                else if (oi.cell == .f64)
                    (if (last) .print_opt_f64 else .print_opt_f64_raw)
                else if (oi.cell == .i64 and optIsU64(oi))
                    (if (last) .print_opt_u64 else .print_opt_u64_raw)
                else if (oi.cell == .i64)
                    (if (last) .print_opt_i64 else .print_opt_i64_raw)
                else if (last) .print_opt_i32 else .print_opt_i32_raw)
            else if (oi.str)
                b.helper(if (last) .print_opt_str else .print_opt_str_raw)
            else
                b.helper(if (last) .print_i32 else .print_i32_raw));
            return;
        }
        if (self.isStringExpr(arg)) {
            try self.lowerValue(arg);
            try self.emit(self.builder().helper(if (last) .print_str else .print_str_raw));
            return;
        }
        if (self.isBoolExpr(arg)) {
            try self.lowerCoerced(arg, .i32);
            try self.emit(self.builder().helper(if (last) .print_bool else .print_bool_raw));
            return;
        }
        // An array of strings, a tuple, an array of tuples: the shape-driven
        // printer (semantics decision 1a). A flat integer or float array keeps its own.
        if (try self.printShapeOf(arg)) |shape| if (!std.mem.eql(u8, shape, "[i") and !std.mem.eql(u8, shape, "[f")) {
            try self.lowerCoerced(arg, .i32);
            const seg = try self.internString(shape);
            try self.emit(try self.constInt(seg.offset + 4));
            try self.emit(try self.constInt(1));
            try self.emit(self.builder().helper(.print_shaped_raw));
            try self.emit(.drop);
            if (last) try self.emit(self.builder().helper(.print_nl));
            return;
        };
        if (self.isArrayExpr(arg)) switch (self.elemKindOf(arg)) {
            .i32 => {
                try self.lowerCoerced(arg, .i32);
                try self.emit(self.builder().helper(if (last) .print_arr_i32 else .print_arr_i32_raw));
                return;
            },
            .f64 => {
                try self.lowerCoerced(arg, .i32);
                try self.emit(self.builder().helper(if (last) .print_arr_f64 else .print_arr_f64_raw));
                return;
            },
            .str => {},
        };
        const t = self.wasmTypeOf(arg);
        if (t.isFloat()) {
            try self.lowerCoerced(arg, .f64);
            try self.emit(self.builder().helper(if (last) .print_f64 else .print_f64_raw));
            return;
        }
        if (t.isI64()) {
            try self.lowerValue(arg);
            if (self.isU64Expr(arg)) {
                try self.emit(self.builder().helper(if (last) .print_u64 else .print_u64_raw));
                return;
            }
            try self.emit(self.builder().helper(if (last) .print_i64 else .print_i64_raw));
            return;
        }
        // A tuple whose elements have no print shape here (a `?T` over a type
        // parameter, an all-unit enum) is a pointer: through the integer
        // printer it answered its address (`300`) at exit 0.
        if (self.typeRefOf(arg)) |tr| if (tr.tupleElems() != null)
            return self.refuse(arg.getLoc(), "the wasm backend has no printed form for this tuple: one of its elements has no print shape here", .{});
        try self.lowerCoerced(arg, .i32);
        try self.emit(self.builder().helper(if (last) .print_i32 else .print_i32_raw));
    }

    fn lowerBuiltin(self: *Emitter, cc: anytype, loc: ast.Loc) anyerror!void {
        if (std.mem.eql(u8, cc.callee, "todo") or std.mem.eql(u8, cc.callee, "panic")) {
            const is_panic = std.mem.eql(u8, cc.callee, "panic");
            // Decision 518 — a program that reaches `attempt` raises the abort
            // as `$__bp_panic`, its message the text the program wrote (else
            // the other targets' `panic` / `not implemented`); `print` keeps
            // what an uncaught one writes (a `@panic` with a message).
            if (self.exceptions) {
                const has_text = cc.args.len == 1 and self.isStringExpr(cc.args[0].value.*);
                if (has_text)
                    try self.lowerCoerced(cc.args[0].value.*, if (self.mode == .gc) Repr.string else .i32)
                else if (self.mode == .gc)
                    try self.emitStrLit(if (is_panic) "panic" else "not implemented")
                else
                    try self.emit(try self.constInt((try self.internString(if (is_panic) "panic" else "not implemented")).offset));
                try self.emit(if (is_panic and has_text) one else zero);
                try self.emit(self.builder().helper(.panic_raise));
                try self.emit(.@"unreachable");
                return;
            }
            // `@panic(msg)` / `@todo(msg)` write `panic: msg` to stderr before
            // it traps (B-41, decision 535).
            if (cc.args.len == 1 and self.isStringExpr(cc.args[0].value.*)) {
                try self.lowerCoerced(cc.args[0].value.*, Repr.string);
                try self.emit(self.builder().helper(.panic_fail));
            }
            try self.emit(.@"unreachable");
            return;
        }
        if (std.mem.eql(u8, cc.callee, ast.is_builtin_name) and cc.isType != null) {
            try self.lowerIsCall(cc);
            return;
        }
        // Decision 758 — a run-time type token (a static blob's address) and
        // `x is t` over one (`$__is_type_token`). A linear module's: a GC one
        // falls back.
        if (std.mem.eql(u8, cc.callee, "__bp_type_token") and cc.args.len == 1) {
            if (self.mode == .gc) return self.gcFail("a run-time type token");
            const a = cc.args[0].value.*;
            const n: []const u8 = if (a == .identifier and a.identifier.kind == .ident) a.identifier.kind.ident else return error.InvalidArgs;
            const addr = try self.typeTokenAddr(n) orelse
                return self.refuseUnlessTemplate(self.call_loc, "`{s}` as a run-time type token: the wasm backend has no run-time test for this type (no value of it carries a descriptor)", .{n});
            try self.emit(try self.constInt(addr));
            return;
        }
        if (std.mem.eql(u8, cc.callee, "__bp_is_type") and cc.args.len == 2) {
            if (self.mode == .gc) return self.gcFail("an is test over a run-time type token");
            try self.lowerAsUnknown(cc.args[0].value.*);
            try self.lowerCoerced(cc.args[1].value.*, .i32);
            try self.emit(self.builder().helper(.is_type_token));
            return;
        }
        if (std.mem.eql(u8, cc.callee, "print") or std.mem.eql(u8, cc.callee, "println")) {
            // `@println` is `@print`: both end the line on every target.
            // Marks the print helper group even for `@print()` with no
            // arguments, matching the historical `uses_print` flag.
            // `print()` with no value is an empty line, as on every target.
            if (cc.args.len == 0) return self.emit(self.builder().helper(.print_nl));
            // `@print(a, b, c)` is one line with the parts space-separated, the
            // shape node and erlang print. Only the first argument used to be
            // emitted at all.
            for (cc.args, 0..) |a, i| {
                if (i > 0) try self.emit(self.builder().helper(.print_sp));
                try self.lowerPrintArg(a.value.*, i + 1 == cc.args.len);
            }
            return;
        }
        if (std.mem.eql(u8, cc.callee, ast.index_builtin_name)) {
            try self.lowerIndex(cc);
            return;
        }
        if (std.mem.startsWith(u8, cc.callee, "__bp_")) {
            try self.lowerResultOptionOp(cc.callee, cc.args, loc);
            return;
        }
        // Decorator / template builtins (`@emit`, `@compilerError`,
        // `Binding.ref`) only exist inside comptime bodies, which never reach
        // this backend: the comptime pass runs them on `erl`. There is nothing
        // in a program module to call, so a program that writes one is
        // refused there.
        if (std.mem.eql(u8, cc.callee, "emit") or
            std.mem.eql(u8, cc.callee, "compilerError") or
            std.mem.eql(u8, cc.callee, "ref"))
        {
            return self.refuse(loc, "`@{s}` is a comptime-only builtin: it runs in a decorator or template body, never in a program the wasm backend emits", .{cc.callee});
        }
        return self.refuse(loc, "the wasm backend has no lowering for the builtin `@{s}`", .{cc.callee});
    }

    /// Decision 30's index expression, which the parser lands as the reserved
    /// builtin call `ast.index_builtin_name` over `(receiver, index)`. One node
    /// serves four readings, told apart by the receiver and by whether the
    /// index is a range (`decision-8:447` — `..` is iteration **and** slicing):
    ///
    /// | Written | Lowering |
    /// |---|---|
    /// | `xs[i]` | `$__arr_at` — the element itself, `0` out of range |
    /// | `xs[a..b]` | std-wasm's `array.slice` — a fresh array, bounds clamped |
    /// | `s[i]` | std-wasm's `text.slice(s, i, i+1)` — the code point at `i` |
    /// | `s[a..b]` | std-wasm's `text.slice` |
    ///
    /// **`xs[i]` answers `T`, not `?T`** — the reading every other language
    /// gives it, and the one `$__arr_at` already implements for the `.at()`
    /// method on a string array. Which of the two decision 30 means is
    /// `01-checker`'s to settle (`ast.zig:1734`); if it settles on `?T` this is
    /// one helper swap (`.arr_at` → `.arr_at_box`) and the fixtures move with it.
    ///
    /// A receiver that is neither an array nor a string — a `Dict`, above all —
    /// has no lowering here: `d["k"]` is `Dict.at` through a std record, and
    /// this backend inlines std rather than linking it. It is refused rather
    /// than answering a number nothing put there.
    /// The `(receiver, index)` of an index call, and whether the index is a
    /// range — `null` for every other call. The one question the type
    /// predicates (`isStringExpr`, `isArrayExpr`, `elemKindOf`) ask about it.
    const IndexArgs = struct { recv: ast.Expr, idx: ast.Expr, is_slice: bool };

    fn indexArgs(self: *Emitter, cc: anytype) ?IndexArgs {
        _ = self;
        if (!cc.is_builtin or !std.mem.eql(u8, cc.callee, ast.index_builtin_name)) return null;
        if (cc.args.len != 2) return null;
        const idx = cc.args[1].value.*;
        const is_slice = switch (idx) {
            .collection => |col| col.kind == .range,
            else => false,
        };
        return .{ .recv = cc.args[0].value.*, .idx = idx, .is_slice = is_slice };
    }

    /// The print shape of `xs[i]` — one `[` stripped off the receiver's shape —
    /// when that element is itself a blob (`[[i` → `[i`, `[(is)` → `(is)`).
    /// Null for a slice, for a scalar element and for a receiver whose shape is
    /// unknown. This is what tells `rows[1]` from `xs[1]`: without it a nested
    /// index had no lowering and trapped (`index on an unknown receiver`).
    ///
    /// It must not call `isArrayExpr` on the index node itself: `isArrayExpr`
    /// asks *this* question, and `printShapeOf` ends by asking `isArrayExpr`.
    /// Only the receiver — structurally smaller — is walked.
    fn indexElemShape(self: *Emitter, cc: anytype) anyerror!?[]const u8 {
        const ix = self.indexArgs(cc) orelse return null;
        if (ix.is_slice) return null;
        const outer = try self.printShapeOf(ix.recv) orelse return null;
        if (outer.len < 2 or outer[0] != '[') return null;
        const inner = outer[1..];
        return if (inner[0] == '[' or inner[0] == '(') inner else null;
    }

    fn lowerIndex(self: *Emitter, cc: anytype) anyerror!void {
        const b = self.builder();
        const recv = cc.args[0].value.*;
        const idx = cc.args[1].value.*;
        const is_str = self.isStringExpr(recv);
        const is_arr = self.isArrayExpr(recv);

        // `xs[a..b]` — the same node, with a range where the index goes.
        const range = switch (idx) {
            .collection => |col| switch (col.kind) {
                .range => |r| r,
                else => null,
            },
            else => null,
        };
        if (range) |r| {
            if (!is_str and !is_arr) {
                return self.refuseUnlessTemplate(self.call_loc, "the wasm backend cannot slice this receiver: nothing types it as a string or an array here", .{});
            }
            if (self.mode == .gc and is_arr) {
                const ar = self.wasmTypeOf(recv);
                if (!ar.isArrRef()) return self.gcFail("a slice of a value of no known array type");
                try self.lowerCoerced(recv, ar);
                try self.lowerCoerced(r.start.*, .i32);
                if (r.end) |e| try self.lowerCoerced(e.*, .i32) else try self.emit(try self.constInt(std.math.maxInt(i32)));
                return self.emit(.{ .call = try self.gcArrOp("slice", ar.ref.arr) });
            }
            try self.lowerCoerced(recv, .i32);
            try self.lowerCoerced(r.start.*, .i32);
            if (r.end) |e| {
                try self.lowerCoerced(e.*, .i32);
            } else {
                // std-wasm's `text.slice` and `array.slice` clamp, so "to the end"
                // is the largest i32
                try self.emit(try self.constInt(std.math.maxInt(i32)));
            }
            // Decision 240: a string's bounds are codepoints.
            try self.emitStdCall(if (is_str) "text.slice" else "array.slice");
            return;
        }

        if (is_str) {
            // `s[i]` is the one-codepoint string at codepoint `i` (decision
            // 240), the `char` §7 prints.
            const at = try self.declRes();
            try self.lowerCoerced(idx, .i32);
            try self.emit(.{ .local_set = at });
            try self.lowerCoerced(recv, .i32);
            try self.emit(.{ .local_get = at });
            try self.emit(.{ .local_get = at });
            try self.emit(one);
            try self.emit(opOf(.i32, "add"));
            try self.emitStdCall("text.slice");
            return;
        }
        if (is_arr) {
            if (self.mode == .gc) return self.gcIndex(recv, idx);
            try self.lowerCoerced(recv, .i32);
            try self.lowerCoerced(idx, .i32);
            try self.emit(b.helper(.arr_at));
            // A float array's slot holds the address of the element's `f64`
            // cell (`$__box_f64`): the value is one load away.
            if (self.elemKindOf(recv) == .f64) try self.emitFromFloatSlot();
            return;
        }
        return self.refuseUnlessTemplate(self.call_loc, "the wasm backend cannot index this receiver: nothing types it as a string or an array here", .{});
    }

    /// Reserve and declare the next `$_res{n}` scratch pointer local. Declared
    /// inline (like the `$__case` locals) since the count isn't known up front.
    /// Bump the heap by the two `i32` slots a `@Result` occupies, leaving the
    /// base pointer in the scratch local `slot`.
    fn allocResultPair(self: *Emitter, slot: []const u8) !void {
        try self.emit(try self.constInt(8));
        try self.emit(self.builder().helper(.alloc));
        try self.emit(.{ .local_set = slot });
    }

    fn declRes(self: *Emitter) ![]const u8 {
        const name = try self.resName(self.res_seq);
        self.res_seq += 1;
        try self.declareLocal(name, .i32);
        return name;
    }

    /// The closure a `@Result`'s `map` / `flatMap` applies: the lambda
    /// written at the call, or — for a function named as a value
    /// (`r.flatMap(half)`, a local holding one) — the lambda `{ v -> f(v) }`
    /// calling it.
    fn resultClosureArg(self: *Emitter, arg: ?*ast.Expr) ?*ast.Expr {
        if (lambdaArg(arg)) |le| return le;
        const a = arg orelse return null;
        const name = plainIdentName(a.*) orelse return null;
        const ar = self.arena();
        const loc = a.getLoc();
        const params = ar.alloc([]const u8, 1) catch return null;
        params[0] = "__bp_fv";
        const ref = ar.create(ast.Expr) catch return null;
        ref.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = "__bp_fv" } } };
        const args = ar.alloc(ast.CallArg, 1) catch return null;
        args[0] = .{ .label = null, .value = ref };
        const body = ar.alloc(ast.Stmt, 1) catch return null;
        body[0] = .{ .expr = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
            .receiver = null,
            .callee = name,
            .is_builtin = false,
            .args = args,
            .trailing = &.{},
        } } } } };
        const out = ar.create(ast.Expr) catch return null;
        out.* = .{ .function = .{ .loc = loc, .kind = .{ .syntax = .lambda, .params = params, .body = body } } };
        return out;
    }

    /// True when `arg` is a literal lambda (`{ x -> ... }`), the only fn form a
    /// higher-order Result/Option op can inline on WASM (there is no first-class
    /// closure value in this backend — `.function` otherwise lowers to `0`).
    fn lambdaArg(arg: ?*ast.Expr) ?*ast.Expr {
        const a = arg orelse return null;
        if (a.* != .function) return null;
        if (a.function.kind.syntax != .lambda) return null;
        return a;
    }

    /// Bind a single-param lambda's parameter to a value held in `src` (a local
    /// name), declaring the parameter local on first use. A zero-param lambda
    /// ignores the value.
    fn bindLambdaParam(self: *Emitter, lam: anytype, src: []const u8) !void {
        if (lam.params.len == 0) return;
        const p = lam.params[0];
        try self.declareLocal(p, .i32);
        try self.emit(.{ .local_get = src });
        try self.emit(.{ .local_set = p });
    }

    /// Inline a lambda body, leaving its tail value on the stack. An explicit
    /// `return` tail is unwrapped to its value (a bare `return` opcode would
    /// exit the *enclosing* function, not the inlined closure).
    fn inlineLambdaBody(self: *Emitter, body: []const ast.Stmt) anyerror!void {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        if (body.len == 0) {
            try self.emit(zero);
            return;
        }
        if (hasDefer(body) and !body[body.len - 1].deferred) {
            // A `defer` of the lambda: its value is computed inside the panic
            // region, the defers run after it.
            const ty = self.wasmTypeOf(body[ast.lastRealIndex(body)].expr);
            const mark = self.defer_stack.items.len;
            var site: InlineLast = .{};
            const tail = try self.emitStmtsFrom(body, 0, true, ty, true, .{ .ctx = &site, .run = InlineLast.run });
            try self.closeDefers(mark, tail);
            return;
        }
        for (body[0..ast.lastRealIndex(body)]) |s| _ = try self.emitStmt(s, false);
        _ = try self.inlineLastStmt(body[ast.lastRealIndex(body)]);
    }

    const InlineLast = struct {
        fn run(_: *anyopaque, em: *Emitter, stmt: ast.Stmt) anyerror!Tail {
            return em.inlineLastStmt(stmt);
        }
    };

    /// The last statement of an inlined lambda: its value on the stack.
    fn inlineLastStmt(self: *Emitter, last: ast.Stmt) anyerror!Tail {
        switch (last.expr) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| {
                    if (r) |v| try self.lowerValue(v.*) else try self.emit(zero);
                    return .value;
                },
                else => {},
            },
            else => {},
        }
        return self.emitStmt(last, true);
    }

    /// `r.map(f)` / `r.flatMap(f)` over a GC `@Result` (front 164 s2 P2b):
    /// an Error goes through as it is; an Ok binds the closure's parameter to
    /// its payload, unboxed by the receiver's Ok type, and the closure's body,
    /// inlined, answers the payload of a new Ok (`map`) or the `@Result`
    /// itself (`flatMap`).
    fn gcResultMap(self: *Emitter, recv: ast.Expr, lam: anytype, is_map: bool) anyerror!void {
        const rr: Repr = .{ .ref = .result };
        const rvt = self.vtOf(rr);
        const rti = self.gcTyIndex(.result);
        const sh = self.resultShapeOf(recv) orelse return self.gcFail("a map over a @Result of no known shape");
        const ok_tr = sh.ok orelse return self.gcFail("a map over a @Result of no known Ok type");
        const okr = self.reprOf(ok_tr);
        const slot = try self.gcTemp(rr);
        try self.lowerCoerced(recv, rr);
        try self.emit(.{ .local_set = slot });

        var err_c: Capture = .{};
        self.open(&err_c);
        try self.emit(.{ .local_get = slot });
        const err_seq = self.seal(&err_c, .{ .value = rvt });

        var ok_c: Capture = .{};
        self.open(&ok_c);
        {
            const scope_mark = self.scopeMark();
            defer self.scopeRestore(scope_mark);
            if (lam.params.len > 0) {
                const p = lam.params[0];
                try self.declareLocal(p, okr);
                try self.local_typerefs.put(p, ok_tr);
                if (okr.isStr()) try self.str_locals.put(p, {});
                if (okr == .bool) try self.bool_locals.put(p, {});
                try self.emit(.{ .local_get = slot });
                try self.emit(.{ .struct_get = .{ .ty = rti, .field = 1 } });
                try self.gcUnbox(okr);
                try self.emit(.{ .local_set = p });
            }
            const body = lam.body;
            if (body.len == 0) return self.gcFail("a map closure with no body");
            for (body[0..ast.lastRealIndex(body)]) |st| _ = try self.emitStmt(st, false);
            const last = body[ast.lastRealIndex(body)].expr;
            const tail: ast.Expr = switch (last) {
                .jump => |j| switch (j.kind) {
                    .@"return" => |r| if (r) |v| v.* else return self.gcFail("a map closure answering nothing"),
                    else => return self.gcFail("a map closure ending in a jump"),
                },
                else => last,
            };
            if (is_map) {
                const outr = self.wasmTypeOf(tail);
                try self.emit(zero);
                try self.lowerCoerced(tail, outr);
                try self.gcBox(outr);
                try self.emit(.{ .struct_new = rti });
            } else try self.lowerCoerced(tail, rr);
        }
        const ok_seq = self.seal(&ok_c, .{ .value = rvt });

        try self.emit(.{ .local_get = slot });
        try self.emit(.{ .struct_get = .{ .ty = rti, .field = 0 } });
        try self.emit(.{ .@"if" = .{ .result = rvt, .then = .{ .seq = err_seq }, .@"else" = .{ .seq = ok_seq } } });
    }

    /// Lower a `__bp_<domain>_<op>(receiver, arg?)` Result/Option method op.
    /// A `@Result` is a pointer to two `i32` slots — `[ptr]` is the tag (0 = Ok,
    /// non-zero = Error), `[ptr+4]` the payload — matching `try`/`catch`. A
    /// `@Option` is the bare value, with `0` standing for absence. `map`/`flatMap`
    /// inline the closure body (there are no first-class funs here); the other
    /// ops are pure tag tests / payload loads.
    fn lowerResultOptionOp(self: *Emitter, callee: []const u8, args: anytype, loc: ast.Loc) anyerror!void {
        const recv = args[0].value;
        const arg1: ?*ast.Expr = if (args.len > 1) args[1].value else null;

        // §1F F4F-T2 — `#[@future]` post-transform markers. wat's #[@future]
        // lowering is eager (Frente A §C2 is what wires `botopink test --target
        // wasm`); strip the resolved marker back to the inner value. The
        // rejected marker is a trap (wat has no `throw` op; future runtime is
        // gated on Frente A §D-D4).
        if (std.mem.eql(u8, callee, "__bp_future_resolved")) {
            try self.lowerExpr(recv.*);
            return;
        }
        if (std.mem.eql(u8, callee, "__bp_future_rejected")) {
            try self.emitC(.@"unreachable", "@future rejection (wat runtime: Frente A §D-D4)");
            return;
        }
        if (std.mem.eql(u8, callee, "__bp_ok") or std.mem.eql(u8, callee, "__bp_error")) {
            // Result constructor (`return v` / `throw e` in a `-> @Result<…>`
            // fn): allocate a fresh `{ tag, payload }` pair (tag 0 = Ok, 1 = Error).
            const tag: u8 = if (std.mem.eql(u8, callee, "__bp_ok")) 0 else 1;
            // A float or an `i64` does not fit the payload's word: it is held
            // in its cell (`resultPayloadCell`), typed by the fn's declared
            // `@Result`, else by the value.
            const declared: ?ast.TypeRef = if (self.cur_ret_typeref) |rt|
                (if (resultShapeOfTypeRef(rt)) |sh| (if (tag == 0) sh.ok else sh.err) else null)
            else
                null;
            if (self.mode == .gc) {
                const pr: Repr = if (declared) |t| self.reprOf(t) else self.wasmTypeOf(recv.*);
                try self.emit(try self.constInt(tag));
                try self.lowerCoerced(recv.*, pr);
                try self.gcBox(pr);
                try self.emit(.{ .struct_new = self.gcTyIndex(.result) });
                return;
            }
            const cell = if (declared) |t| resultPayloadCell(t) else Cell.of(self.wasmTypeOf(recv.*));
            const slot = try self.declRes();
            try self.allocResultPair(slot);
            try self.emit(.{ .local_get = slot });
            try self.emit(try self.constInt(tag));
            try self.emitCf(.{ .store = .{} }, "Result tag ({s})", .{if (tag == 0) "Ok" else "Error"});
            try self.emit(.{ .local_get = slot });
            if (cell != .none) try self.lowerCellWord(recv.*, cell) else try self.lowerExpr(recv.*);
            try self.emitC(.{ .store = .{ .offset = 4 } }, "payload");
            try self.emit(.{ .local_get = slot });
            return;
        }

        if (std.mem.eql(u8, callee, "__bp_result_map") or std.mem.eql(u8, callee, "__bp_result_flatMap")) {
            const is_map = std.mem.eql(u8, callee, "__bp_result_map");
            const le = self.resultClosureArg(arg1) orelse return self.refuse(loc, "`Result.{s}` on the wasm backend takes a closure written at the call or a function named as a value", .{if (is_map) "map" else "flatMap"});
            const lam = le.function.kind;
            if (self.mode == .gc) return self.gcResultMap(recv.*, lam, is_map);
            const slot = try self.declRes();
            try self.lowerExpr(recv.*);
            try self.emit(.{ .local_set = slot });
            try self.emit(.{ .local_get = slot });
            try self.emitC(.{ .load = .{} }, result_tag);

            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emitC(.{ .local_get = slot }, "Error — propagate unchanged");
            const then_seq = self.seal(&then_c, .{ .value = .i32 });

            var else_c: Capture = .{};
            self.open(&else_c);
            // Ok: bind the closure param to the payload, then apply it. An
            // `f64` / `i64` payload is its cell's address, read into a local
            // of the cell's type.
            const in_cell = self.resultOkCell(recv.*);
            try self.emit(.{ .local_get = slot });
            try self.emitC(.{ .load = .{ .offset = 4 } }, ok_payload);
            if (in_cell == .none) {
                try self.emit(.{ .local_set = slot });
                try self.bindLambdaParam(lam, slot);
            } else if (lam.params.len > 0) {
                try self.emitFromCell(in_cell);
                try self.declareLocal(lam.params[0], in_cell.ty());
                try self.emit(.{ .local_set = lam.params[0] });
            } else try self.emit(.drop);
            // The parameter is the payload's type, so a primitive method on
            // it (`{ n -> n.toString() }`) finds its family where inference
            // recorded none.
            if (lam.params.len > 0) if (self.resultShapeOf(recv.*)) |sh| if (sh.ok) |ok_tr|
                try self.local_typerefs.put(lam.params[0], ok_tr);
            if (is_map) {
                // Rewrap the mapped value as a fresh `{ tag: 0, payload }` Result.
                const out = try self.declRes();
                try self.allocResultPair(out);
                try self.emit(.{ .local_get = out });
                try self.emit(zero);
                try self.emitC(.{ .store = .{} }, "Ok tag");
                try self.emit(.{ .local_get = out });
                const out_cell = Cell.of(self.lambdaTailType(lam.body));
                try self.inlineLambdaBody(lam.body);
                if (out_cell != .none) try self.emit(self.builder().helper(if (out_cell == .f64) .box_f64 else .box_i64));
                try self.emitC(.{ .store = .{ .offset = 4 } }, "mapped payload");
                try self.emit(.{ .local_get = out });
            } else {
                // flatMap: the closure already yields a `@Result` pointer.
                try self.inlineLambdaBody(lam.body);
            }
            const else_seq = self.seal(&else_c, .{ .value = .i32 });

            try self.emit(.{ .@"if" = .{
                .result = .i32,
                .then = .{ .seq = then_seq },
                .@"else" = .{ .seq = else_seq },
            } });
            return;
        }

        if (std.mem.eql(u8, callee, "__bp_result_unwrapOr")) {
            if (self.mode == .gc) return self.gcResultUnwrapOr(recv.*, arg1);
            // An `f64` / `i64` payload is its cell's address; the default is
            // the value itself.
            const cell = self.resultOkCell(recv.*);
            const ty = self.vtOf(cell.ty());
            const slot = try self.declRes();
            try self.lowerExpr(recv.*);
            try self.emit(.{ .local_set = slot });
            try self.emit(.{ .local_get = slot });
            try self.emitC(.{ .load = .{} }, result_tag);

            var then_c: Capture = .{};
            self.open(&then_c);
            if (arg1) |d| {
                if (cell != .none) try self.lowerCoerced(d.*, cell.ty()) else try self.lowerExpr(d.*);
            } else try self.emit(constOf(cell.ty(), "0"));
            const then_seq = self.seal(&then_c, .{ .value = ty });

            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emit(.{ .local_get = slot });
            try self.emitC(.{ .load = .{ .offset = 4 } }, ok_payload);
            try self.emitFromCell(cell);
            const else_seq = self.seal(&else_c, .{ .value = ty });

            try self.emit(.{ .@"if" = .{
                .result = ty,
                .then = .{ .seq = then_seq },
                .@"else" = .{ .seq = else_seq },
            } });
            return;
        }

        if (self.mode == .gc and (std.mem.eql(u8, callee, "__bp_result_isOk") or std.mem.eql(u8, callee, "__bp_result_isError"))) {
            try self.lowerCoerced(recv.*, .{ .ref = .result });
            try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.result), .field = 0 } });
            if (std.mem.eql(u8, callee, "__bp_result_isOk")) try self.emit(opOf(.i32, "eqz")) else {
                try self.emit(zero);
                try self.emit(opOf(.i32, "ne"));
            }
            return;
        }
        if (std.mem.eql(u8, callee, "__bp_result_isOk")) {
            try self.lowerExpr(recv.*);
            try self.emitC(.{ .load = .{} }, "Result tag");
            try self.emitC(opOf(.i32, "eqz"), "isOk = (tag == 0)");
            return;
        }

        if (std.mem.eql(u8, callee, "__bp_result_isError")) {
            try self.lowerExpr(recv.*);
            try self.emitC(.{ .load = .{} }, "Result tag");
            try self.emit(zero);
            try self.emitC(opOf(.i32, "ne"), "isError = (tag != 0)");
            return;
        }

        if (std.mem.eql(u8, callee, "__bp_option_map") or std.mem.eql(u8, callee, "__bp_option_flatMap")) {
            const is_map = std.mem.eql(u8, callee, "__bp_option_map");
            const le = lambdaArg(arg1) orelse return self.refuse(loc, "`Option.{s}` on the wasm backend takes a closure written at the call; a function value is not lowered", .{if (is_map) "map" else "flatMap"});
            const lam = le.function.kind;
            const boxed = self.optionIsBoxed(recv.*, null);
            if (self.optInfoOf(recv.*)) |oi| if (oi.cell != .none) {
                return self.refuse(loc, "`Option.{s}` over a `?{s}` has no lowering on the wasm backend", .{ if (is_map) "map" else "flatMap", oi.cell.ty().name() });
            };
            if (is_map and Cell.of(self.lambdaTailType(lam.body)) != .none) {
                return self.refuse(loc, "`Option.map` to an `{s}` has no lowering on the wasm backend", .{self.lambdaTailType(lam.body).name()});
            }
            const slot = try self.declRes();
            try self.lowerExpr(recv.*);
            try self.emit(.{ .local_set = slot });
            try self.emitC(.{ .local_get = slot }, option_shape);

            var then_c: Capture = .{};
            self.open(&then_c);
            // Some: apply the closure to the payload.
            if (lam.params.len > 0) {
                try self.declareLocal(lam.params[0], .i32);
                try self.emit(.{ .local_get = slot });
                if (boxed) try self.emitC(.{ .load = .{} }, "optional payload");
                try self.emit(.{ .local_set = lam.params[0] });
            }
            const tail_boxes = is_map and !self.lambdaTailIsPointer(lam.body);
            try self.inlineLambdaBody(lam.body);
            // `map`'s result is an optional again: a scalar goes back in a box.
            if (tail_boxes) try self.emit(self.builder().helper(.box_i32));
            const then_seq = self.seal(&then_c, .{ .value = .i32 });

            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emitC(zero, "None — propagate absence");
            const else_seq = self.seal(&else_c, .{ .value = .i32 });

            try self.emit(.{ .@"if" = .{
                .result = .i32,
                .then = .{ .seq = then_seq },
                .@"else" = .{ .seq = else_seq },
            } });
            return;
        }

        if (std.mem.eql(u8, callee, "__bp_option_unwrapOr")) {
            if (self.mode == .gc) return self.gcOptionUnwrapOr(recv.*, arg1);
            const slot = try self.declRes();
            // A `?f64` / `?i64` answers what its cell holds, the default
            // that type.
            const cell: Cell = if (self.optInfoOf(recv.*)) |oi| oi.cell else .none;
            const res_ty: ValType = self.vtOf(cell.ty());
            try self.lowerExpr(recv.*);
            try self.emit(.{ .local_set = slot });
            try self.emitC(.{ .local_get = slot }, option_shape);

            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emitC(.{ .local_get = slot }, "Some — present value");
            if (cell != .none)
                try self.emitC(.{ .load = .{ .ty = res_ty } }, "optional payload")
            else if (self.optionIsBoxed(recv.*, arg1)) try self.emitC(.{ .load = .{} }, "optional payload");
            const then_seq = self.seal(&then_c, .{ .value = res_ty });

            var else_c: Capture = .{};
            self.open(&else_c);
            if (cell != .none) {
                if (arg1) |d| try self.lowerCoerced(d.*, cell.ty()) else try self.emit(constOf(cell.ty(), "0"));
            } else if (arg1) |d| try self.lowerExpr(d.*) else try self.emit(zero);
            const else_seq = self.seal(&else_c, .{ .value = res_ty });

            try self.emit(.{ .@"if" = .{
                .result = res_ty,
                .then = .{ .seq = then_seq },
                .@"else" = .{ .seq = else_seq },
            } });
            return;
        }

        return self.refuse(loc, "the wasm backend has no lowering for `{s}`", .{callee});
    }

    /// True when `e` evaluates to the 0/1 boolean carrier: the `true`/`false`
    /// identifiers, a comparison, `!x`, `&&`/`||`, or a call to a fn declared
    /// `-> bool`.
    fn isBoolExpr(self: *Emitter, e: ast.Expr) bool {
        if (self.genMethodOf(e)) |m| if (m == .some or m == .every) return true;
        if (asyncBlockValue(e)) |a| return self.isBoolExpr(a);
        // `o ?? d` reads as `o.unwrapOr(d)`; `x!` answers its payload.
        if (nullishParts(e)) |nu| return self.isBoolExpr(nu.dflt);
        if (optOperatorParts(e)) |op| if (op.bang) return if (self.optInfoOf(op.cond.*)) |oi| oi.bool_ else false;
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| std.mem.eql(u8, n, "true") or std.mem.eql(u8, n, "false") or
                    self.bool_locals.contains(self.resolveName(n)) or self.bool_globals.contains(self.resolveName(n)),
                // `r.flag` of a field declared `bool`, `t.1` of a `bool`
                // element: the word is `1`/`0`, and only the declared type
                // says it prints `true`/`false` — `@print(r.flag)` wrote `1`
                // at exit 0. An optional read (`r?.flag`) is a `?bool`.
                .identAccess => |ia| !ia.optional and if (self.typeRefOf(e)) |t| isBoolTypeRef(t) else if (self.tupleElemShapeOf(e) catch null) |el| std.mem.eql(u8, el, "b") else false,
                else => false,
            },
            .unaryOp => |un| un.op == .not,
            .binaryOp => |bin| switch (bin.op) {
                .eq, .ne, .lt, .gt, .lte, .gte => true,
                .@"and", .@"or" => self.isBoolExpr(bin.lhs.*) or self.isBoolExpr(bin.rhs.*),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.isBoolExpr(inner.*),
                else => false,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (isUnwrapOr(cc)) break :blk self.isBoolExpr(cc.args[1].value.*);
                    if (cc.is_builtin) break :blk std.mem.eql(u8, cc.callee, "__bp_result_isOk") or
                        std.mem.eql(u8, cc.callee, "__bp_result_isError") or
                        (std.mem.eql(u8, cc.callee, ast.is_builtin_name) and cc.isType != null) or
                        std.mem.eql(u8, cc.callee, "__bp_is_type");
                    if (self.primKindAt(cc, c.loc)) |k| break :blk self.primRes(k, cc) == .bool_;
                    if (self.genericResultArg(cc)) |a| break :blk self.isBoolExpr(a);
                    // `f(a, b)` over a value declared `fn(…) -> bool`.
                    if (self.valueCallTypeRef(cc)) |t| if (isBoolTypeRef(t)) break :blk true;
                    if (self.resolvedCallSym(cc, c.loc)) |sym| break :blk self.bool_fns.contains(sym);
                    break :blk false;
                },
                else => false,
            },
            .useHook => |uh| self.isBoolExpr(uh.kind.inner.*),
            else => false,
        };
    }

    /// What the `case` subject staged in `subj_local` is, read off its
    /// expression: the facts the patterns and the arm binders ask of it.
    fn noteCaseSubject(self: *Emitter, c: anytype, subj_local: []const u8) anyerror!void {
        if (self.isU64Expr(c.subjects[0])) try self.u64_subjects.put(self.alloc, subj_local, {}) else _ = self.u64_subjects.remove(subj_local);
        // Re-decided per `case`: `__case_<depth>` names repeat across functions.
        if (self.isUnknownExpr(c.subjects[0])) try self.unknown_subjects.put(self.alloc, subj_local, {}) else _ = self.unknown_subjects.remove(subj_local);
        if (c.subjects.len == 1) {
            if (self.typeRefOf(c.subjects[0])) |tr| try self.local_typerefs.put(subj_local, tr) else _ = self.local_typerefs.remove(subj_local);
        }
        const subj_is_str = self.isStringExpr(c.subjects[0]);
        if (subj_is_str) try self.str_locals.put(subj_local, {});
        if (self.resultShapeOf(c.subjects[0])) |shape| try self.result_subjects.put(subj_local, shape);
        // A record subject: what a catch-all arm's binder reads its fields by
        // (`_ { o -> o.label }`), a generic record's included.
        if (c.subjects.len == 1) if (self.recordTypeOfExpr(c.subjects[0])) |rty| try self.local_types.put(subj_local, rty);
        if (self.enumOfSubject(c.subjects[0])) |en| try self.subject_enums.put(self.alloc, subj_local, en) else _ = self.subject_enums.remove(subj_local);
        try self.noteSubjectShape(subj_local, c.subjects[0]);
        _ = self.subject_generic.remove(subj_local);
        if (c.subjects.len == 1) if (self.typeRefOf(c.subjects[0])) |tr| if (tr == .generic and self.enum_generics.contains(tr.generic.name))
            try self.subject_generic.put(self.alloc, subj_local, tr);
    }

    /// Decision 150 — the checker's record of a `case` / `if` whose value is
    /// the union of its arms (`InstanceLowering.union_value`, at its loc).
    fn unionValueOf(self: *Emitter, e: ast.Expr) ?envMod.UnionValue {
        const loc = switch (e) {
            .collection => |col| if (col.kind == .case) col.loc else return null,
            .branch => |br| if (br.kind == .if_) br.loc else return null,
            else => return null,
        };
        const il = self.instance_lowerings.get(loc) orelse return null;
        return if (il == .union_value) il.union_value else null;
    }

    /// The type each of `n` arms of the `case` / `if` `e` is boxed by: the
    /// checker's arm types when it typed `e` a union, else `whole` — the one
    /// type `e` itself is boxed as — for every arm; null when neither is known.
    fn unionArmTypes(self: *Emitter, e: ast.Expr, n: usize, whole: ?ast.TypeRef) anyerror!?[]const ?ast.TypeRef {
        if (self.unionValueOf(e)) |uv| if (uv.arms.len == n) return uv.arms;
        const w = whole orelse return null;
        if (isUnknownTypeRef(w)) return null;
        const arms = try self.arena().alloc(?ast.TypeRef, n);
        @memset(arms, w);
        return arms;
    }

    /// The type the current boxed `case`'s arm `idx` goes into its `unknown` by.
    fn caseArmBoxType(self: *Emitter, idx: usize) ?ast.TypeRef {
        const arms = self.case_arm_types orelse return null;
        return if (idx < arms.len) arms[idx] else null;
    }

    fn lowerCase(self: *Emitter, c: anytype) anyerror!void {
        const prev_case_box = self.case_box;
        self.case_box = self.pending_case_box;
        self.pending_case_box = false;
        defer self.case_box = prev_case_box;
        const prev_arm_types = self.case_arm_types;
        self.case_arm_types = if (self.case_box) self.pending_case_arms else null;
        self.pending_case_arms = null;
        defer self.case_arm_types = prev_arm_types;
        if (c.subjects.len == 0 or c.arms.len == 0) {
            try self.emit(zero);
            return;
        }
        // In a state machine every `case` keeps its subject in a local of its
        // own, which the frame saves and re-entry reads back (decision 392).
        const subj_local = if (self.machine != null) blk: {
            const n = try std.fmt.allocPrint(self.arena(), "__case_{d}_{d}", .{ self.case_depth, self.loop_seq });
            self.loop_seq += 1;
            break :blk n;
        } else try std.fmt.allocPrint(self.arena(), "__case_{d}", .{self.case_depth});
        self.case_depth += 1;
        // A single subject keeps the wasm type it has (`i64`, `u64`, `u32`,
        // `f64`, …): the patterns compare it as that type, never narrowed.
        const subj_ty: Repr = self.wasmTypeOf(c.subjects[0]);
        try self.declareLocal(subj_local, subj_ty);
        const start_lo = if (self.machine) |m| m.next else 0;
        var start: Capture = .{};
        self.open(&start);
        // A multi-subject `case` lowers each subject once, into its own
        // local below; the first one's is copied into `subj_local` there.
        if (c.subjects.len == 1) {
            try self.lowerCoerced(c.subjects[0], subj_ty);
            try self.emit(.{ .local_set = subj_local });
        }
        try self.noteCaseSubject(c, subj_local);
        const prev_result = self.cur_result;
        defer self.cur_result = prev_result;
        // The arms of a `case` boxed into an `unknown` answer a word.
        if (self.case_box) self.cur_result = if (self.mode == .gc) .{ .ref = .unknown } else .i32;
        // In a GC module a `case` whose every arm answers a string answers a
        // string (front 164 s2): its arms are coerced to it, not to the word
        // the enclosing function answers.
        if (self.mode == .gc and !self.case_box) {
            const all_str = for (c.arms) |arm| {
                if (!self.armIsString(arm.body)) break false;
            } else true;
            if (all_str) self.cur_result = Repr.string;
        }
        // `case a, n { 0, "x" -> … }`: every subject in its own local,
        // `<subject local>_<i>`, which the `.multi` pattern's i-th pattern is
        // tested against and binds from. Only the first was lowered, and the
        // `.multi` pattern tested nothing — the first arm answered every call.
        if (c.subjects.len > 1) for (c.subjects, 0..) |subj, i| {
            const sub = try multiSubjectLocal(self.arena(), subj_local, i);
            // Each subject keeps its own wasm type, as a single subject does.
            const sub_ty = self.wasmTypeOf(subj);
            try self.declareLocal(sub, sub_ty);
            try self.lowerCoerced(subj, sub_ty);
            try self.emit(.{ .local_set = sub });
            if (self.isU64Expr(subj)) try self.u64_subjects.put(self.alloc, sub, {}) else _ = self.u64_subjects.remove(sub);
            if (self.isUnknownExpr(subj)) try self.unknown_subjects.put(self.alloc, sub, {});
            if (self.isStringExpr(subj)) try self.str_locals.put(sub, {});
            if (self.resultShapeOf(subj)) |shape| try self.result_subjects.put(sub, shape);
            if (self.recordTypeOfExpr(subj)) |rty| try self.local_types.put(sub, rty);
            if (self.enumOfSubject(subj)) |en| try self.subject_enums.put(self.alloc, sub, en) else _ = self.subject_enums.remove(sub);
            if (i == 0) {
                try self.emit(.{ .local_get = sub });
                try self.emit(.{ .local_set = subj_local });
            }
        };
        try self.guardStart(&start, start_lo);

        try self.emitCaseArms(c.arms, subj_local, 0);
    }

    fn emitCaseArms(self: *Emitter, arms: anytype, subj: []const u8, idx: usize) anyerror!void {
        if (idx >= arms.len) {
            try self.emit(self.zeroOf(self.cur_result));
            return;
        }
        const arm = arms[idx];
        // §5.2 — an arm naming a primitive type over an `unknown` subject
        // tests the value's box (by value: `3.0` takes an `i32` arm), and its
        // binder is the unboxed payload. As a plain identifier it was a
        // binding that matched everything: `number 364`, a heap address.
        if (self.unknown_subjects.contains(subj) and arm.pattern == .ident) if (primTestOf(.{ .named = arm.pattern.ident })) |pt| {
            try self.emit(.{ .local_get = subj });
            try self.emitPrimTest(pt);
            const ty = self.vtOf(self.cur_result);
            var then_c: Capture = .{};
            self.open(&then_c);
            self.arm_unbox = pt;
            if (arm.guard) |g| {
                try self.emitGuardChain(arms, subj, idx, g);
            } else {
                self.arm_box_as = self.caseArmBoxType(idx);
                try self.lowerArmBody(arm.body, subj);
            }
            self.arm_unbox = null;
            const then_seq = self.seal(&then_c, .{ .value = ty });
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emitCaseArms(arms, subj, idx + 1);
            const else_seq = self.seal(&else_c, .{ .value = ty });
            try self.emit(.{ .@"if" = .{
                .result = ty,
                .then = .{ .seq = then_seq },
                .@"else" = .{ .seq = else_seq },
            } });
            return;
        };
        const irrefutable = blk: {
            const prev_hint = self.case_enum_hint;
            self.case_enum_hint = self.subject_enums.get(subj);
            defer self.case_enum_hint = prev_hint;
            break :blk self.patternIsIrrefutable(arm.pattern);
        };
        if (irrefutable) {
            var arm_aliases = try self.aliases.clone();
            // A refusal (the GC pass's) before the clone is put back frees it.
            var restored = false;
            errdefer if (!restored) arm_aliases.deinit();
            try self.bindPattern(arm.pattern, subj);
            // A guard makes even `_` refutable: a failing guard falls through
            // to the next arm (§5.3), so there is still a chain to emit.
            if (arm.guard) |g| {
                try self.emitGuardChain(arms, subj, idx, g);
            } else {
                self.arm_box_as = self.caseArmBoxType(idx);
                try self.lowerArmBody(arm.body, subj);
            }
            self.restoreAliases(arm_aliases);
            restored = true;
            return;
        }
        try self.emitPatternTest(arm.pattern, subj, arm.patternLoc);
        try self.emitArmChain(arms, subj, idx, arm.body);
    }

    /// `(if <guard> (then <arm body>) (else <rest of the chain>))`, the
    /// pattern's names already bound. Decision 8 §5.3: the guard is read after
    /// the binding, and a failing one falls through. Dropping it — which is
    /// what this backend did until now — made every guarded arm match
    /// unconditionally (`case_guard_bound_identifier_numeric_guard` answered
    /// `"positive"` for every `n`).
    fn emitGuardChain(self: *Emitter, arms: anytype, subj: []const u8, idx: usize, guard: ast.Expr) anyerror!void {
        const ty = self.vtOf(self.cur_result);
        try self.lowerCoerced(guard, .i32);

        var ok_c: Capture = .{};
        self.open(&ok_c);
        // §5.3 / §4.1 — `when (v is string)` narrows `v` in the arm body as
        // `if (v is string)` does in its block.
        const unknown_narrowed = try self.narrowUnknown(guard);
        self.arm_box_as = self.caseArmBoxType(idx);
        try self.lowerArmBody(arms[idx].body, subj);
        self.dropUnknownNarrowing(unknown_narrowed);
        const ok_seq = self.seal(&ok_c, .{ .value = ty });

        var no_c: Capture = .{};
        self.open(&no_c);
        try self.emitCaseArms(arms, subj, idx + 1);
        const no_seq = self.seal(&no_c, .{ .value = ty });

        try self.emit(.{ .@"if" = .{
            .result = ty,
            .then = .{ .seq = ok_seq },
            .@"else" = .{ .seq = no_seq },
        } });
    }

    /// Decision 8 §5.1 P1/P3: an arm written `Pattern { … }` — and the
    /// pre-decision-8 `-> { … }` block arm — arrives as a **lambda**: a leading
    /// `name ->` binds the whole matched value and the last expression is the
    /// arm's value. It is not a function value, so it is inlined here. Lowering
    /// it as a value lifted the body into the function table and left the arm
    /// answering a closure-cell address (`case_or_patterns_with_block_arm_body`
    /// recorded that as `$__lambda0` plus a 4-byte cell).
    const ArmLambda = struct { params: []const []const u8, body: []const ast.Stmt };

    fn armLambda(body: ast.Expr) ?ArmLambda {
        if (body != .function) return null;
        const k = body.function.kind;
        if (k.syntax != .lambda or k.params.len > 1) return null;
        return .{ .params = k.params, .body = k.body };
    }

    /// The arm's value, coerced to the case's result type. A block arm's
    /// `defer`s run after its value (decision 539), a panic in the arm
    /// included (`emitDeferRegion` over the arm's statements).
    fn lowerArmBody(self: *Emitter, body: ast.Expr, subj: []const u8) anyerror!void {
        const mark = self.defer_stack.items.len;
        try self.lowerArmBodyStmts(body, subj);
        try self.closeDefers(mark, .value);
    }

    fn lowerArmBodyStmts(self: *Emitter, body: ast.Expr, subj: []const u8) anyerror!void {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        const unbox = self.arm_unbox;
        self.arm_unbox = null;
        // Read once: a `case` nested in the body binds its own arms.
        const record = self.arm_record;
        self.arm_record = null;
        // The arms of a `case` boxed into an `unknown` (`lowerAsUnknown`):
        // this arm's value goes in on its own; a `case` nested in the body
        // is its own (`lowerCase` reads the flag again).
        const box = self.case_box;
        self.case_box = false;
        defer self.case_box = box;
        const box_as = self.arm_box_as;
        self.arm_box_as = null;
        const lam = armLambda(body) orelse {
            if (box and body != .jump) {
                self.box_as = box_as;
                try self.lowerAsUnknown(body);
            } else try self.lowerCoerced(body, self.cur_result);
            return;
        };
        // P1: the single parameter binds the whole matched value — for a
        // primitive-type arm over an `unknown` subject, the payload its test
        // proved.
        if (unbox) |pt| if (lam.params.len == 1) {
            const p = lam.params[0];
            try self.declareLocal(p, self.unkPayloadRepr(pt));
            try self.emit(.{ .local_get = subj });
            try self.emitUnkPayload(pt);
            try self.emit(.{ .local_set = p });
            if (pt == .string) try self.str_locals.put(p, {});
            if (pt == .bool_) try self.bool_locals.put(p, {});
        };
        if (unbox == null and lam.params.len == 1) {
            const p = lam.params[0];
            try self.declareLocal(p, self.locals.get(subj) orelse .i32);
            if (self.str_locals.contains(subj)) try self.str_locals.put(p, {});
            if (record orelse self.local_types.get(subj)) |t| try self.local_types.put(p, t);
            try self.emit(.{ .local_get = subj });
            try self.emit(.{ .local_set = p });
        }
        if (lam.body.len == 0) {
            try self.emit(self.zeroOf(self.cur_result));
            return;
        }
        if (hasDefer(lam.body)) {
            // A `defer` of the arm: the panic region encloses the value too.
            var site: ArmLast = .{ .box = box, .box_as = box_as };
            _ = try self.emitStmtsFrom(lam.body, 0, true, self.cur_result, true, .{ .ctx = &site, .run = ArmLast.run });
            return;
        }
        _ = try self.emitStmtsFrom(lam.body[0..ast.lastRealIndex(lam.body)], 0, false, null, false, null);
        _ = try self.armLastStmt(lam.body[ast.lastRealIndex(lam.body)], box, box_as);
    }

    const ArmLast = struct {
        box: bool,
        box_as: ?ast.TypeRef,
        fn run(ctx: *anyopaque, em: *Emitter, stmt: ast.Stmt) anyerror!Tail {
            const self: *ArmLast = @ptrCast(@alignCast(ctx));
            return em.armLastStmt(stmt, self.box, self.box_as);
        }
    };

    /// The arm's last statement: its value, converted to the case's result.
    fn armLastStmt(self: *Emitter, last: ast.Stmt, box: bool, box_as: ?ast.TypeRef) anyerror!Tail {
        // P3: the last expression is the value; an explicit `break v` carries
        // it instead — the shape the pre-decision-8 block arm is written with.
        switch (last.expr) {
            .jump => |j| switch (j.kind) {
                .@"break" => |br| if (br.value) |v| {
                    if (self.yield_target == null) {
                        if (box) {
                            self.box_as = box_as;
                            try self.lowerAsUnknown(v.*);
                        } else try self.lowerCoerced(v.*, self.cur_result);
                        return .value;
                    }
                },
                else => {},
            },
            .binding => {
                // `val x = …` in tail position is not a value
                _ = try self.emitStmt(last, false);
                try self.emit(self.zeroOf(self.cur_result));
                return .value;
            },
            else => {},
        }
        if (box) switch (last.expr) {
            .jump, .binding => {},
            else => {
                self.box_as = box_as;
                try self.lowerAsUnknown(last.expr);
                return .value;
            },
        };
        const from = self.wasmTypeOf(last.expr);
        // A statement that answers nothing (`yield`, a void call) left the
        // zero of the case's result, which needs no conversion.
        const answers_nothing = self.mode == .gc and self.exprTail(last.expr) == .none;
        const tail = try self.emitStmt(last, true);
        if (tail == .value and !answers_nothing) try self.emitConvert(from, self.cur_result);
        return tail;
    }

    // ── case patterns ────────────────────────────────────────────────────────
    //
    // A pattern is a test (`emitPatternTest`, leaves an i32) plus the bindings
    // its arm sees (`bindPattern`, run at the top of the arm). What a variant
    // test reads depends on how the subject is laid out:
    //   * a variant of a user enum whose variants are all units is its tag, an
    //     i32 (`Color.Red` = 0);
    //   * a variant of an enum with any payload is a pointer to `[tag, …fields]`
    //     — unit variants of such an enum are allocated too, so every value of
    //     the enum has the same shape;
    //   * `Ok(v)` / `Err(e)` on a `@Result` read the `[tag, payload]` pair
    //     (tag 0 = Ok).
    // A bare name that is a variant of some enum is a tag test, not a binding.

    const VariantRef = union(enum) {
        user: FoundVariant,
        result_ok,
        result_err,
    };

    fn variantRef(self: *Emitter, name: []const u8) ?VariantRef {
        if (!isResultPath(name)) if (self.findVariant(name)) |fv| return .{ .user = fv };
        const bare = bareVariantName(name);
        if (std.mem.eql(u8, bare, "Ok")) return .result_ok;
        if (std.mem.eql(u8, bare, "Err") or std.mem.eql(u8, bare, "Error")) return .result_err;
        return null;
    }

    fn enumHasPayload(variants: []const ast.EnumVariant) bool {
        for (variants) |v| if (v.fields.len > 0) return true;
        return false;
    }

    fn patternIsIrrefutable(self: *Emitter, p: ast.Pattern) bool {
        return switch (p) {
            .wildcard => true,
            // a written path is a variant, never a binding (§5.1 P8); a name
            // that is a `type` this module declares is decision 8 §3.3's arm,
            // tested by the value's own header, not a binding either
            .ident => |n| !isLitPatternName(n) and !isVariantPath(n) and self.findVariant(n) == null and !self.namesATestableType(n),
            .multi => |pats| for (pats) |sub| {
                if (!self.patternIsIrrefutable(sub)) break false;
            } else true,
            // `[..]` / `[..rest]` matches every array; any other list pattern
            // is tested (`emitListPatternTest`). Every one of them used to be
            // irrefutable here, so `[x]` took a `[]` arm before it.
            .list => |l| l.elems.len == 0 and l.spread != null,
            else => false,
        };
    }

    fn emitPatternTest(self: *Emitter, p: ast.Pattern, subj: []const u8, loc: ast.Loc) anyerror!void {
        const prev_hint = self.case_enum_hint;
        self.case_enum_hint = self.subject_enums.get(subj);
        defer self.case_enum_hint = prev_hint;
        switch (p) {
            .wildcard => try self.emit(one),
            .list => |l| try self.emitListPatternTest(l, subj, loc),
            // Every pattern against its own subject (`lowerCase`), all of them
            // holding. A primitive type over an `unknown` / union subject
            // tests the value's box, as a whole-subject arm does.
            .multi => |pats| {
                try self.emit(one);
                for (pats, 0..) |sub, i| {
                    const local = try multiSubjectLocal(self.arena(), subj, i);
                    if (sub == .ident and self.unknown_subjects.contains(local)) if (primTestOf(.{ .named = sub.ident })) |pt| {
                        try self.emit(.{ .local_get = local });
                        try self.emitPrimTest(pt);
                        try self.emit(opOf(.i32, "and"));
                        continue;
                    };
                    try self.emitPatternTest(sub, local, loc);
                    try self.emit(opOf(.i32, "and"));
                }
            },
            // `true` / `false` in a pattern are the bool literals, never a
            // binder: inside a tuple pattern (`#(a, b, true)`) the element was
            // bound to a local named `true` and every arm matched.
            .ident => |n| if (isBoolLitName(n)) {
                try self.emit(.{ .local_get = subj });
                try self.emit(if (n[0] == 't') one else zero);
                try self.emit(opOf(.i32, "eq"));
            } else if (std.mem.eql(u8, n, "null")) {
                // `Box(label: null, n: k)`: an optional field is absent when
                // its word is `0`. Bound as a local named `null`, the arm
                // took every value.
                try self.emit(.{ .local_get = subj });
                if (self.mode == .gc) try self.emit(.ref_is_null) else try self.emit(opOf(.i32, "eqz"));
            } else {
                // A written path is a variant, never a binding (§5.1 P8), so
                // `.Ok` and `Shape.Circle` test a tag; a path no enum here
                // declares is an arm that can never match, not a catch-all.
                if (isVariantPath(n)) {
                    if (self.variantRef(n)) |ref|
                        try self.emitTagTest(ref, subj)
                    else
                        return self.refuse(loc, "`{s}` names no variant of an enum this program declares", .{n});
                } else if (self.findVariant(n)) |fv| {
                    // One spelling can be BOTH a `type` this module places and
                    // a variant some enum declares (`type Block(…)` beside
                    // `Token.Layout { Block, … }`). §5.3b: the SUBJECT's type
                    // says which one the arm means, and this emitter has no
                    // subject type, so the arm tests both, each by a test that
                    // is false for the other's values: the record's header,
                    // `or` the variant's own identity. Tested by the tag alone,
                    // a `case` over `Block | Vec` never matched a `Block`
                    // record, and a payload enum's tag load read a record's
                    // first field as a tag.
                    if (self.records.contains(n) and try self.emitNamedTypeTest(n, subj)) {
                        try self.emitVariantIdentityTest(fv, subj, loc);
                        try self.emit(opOf(.i32, "or"));
                    } else try self.emitTagTest(.{ .user = fv }, subj);
                } else if (try self.emitNamedTypeTest(n, subj)) {
                    // Decision 8 §3.3 — an arm naming a `type` is chosen by the
                    // VALUE's own declaration, which half 3 put in its header.
                    // Emitted as the catch-all `1` below, the first arm of a
                    // `case` over `Person | Vec` answered for every subject.
                } else try self.emit(one);
            },
            .numberLit => |n| {
                if (lexerMod.isBigintText(n)) {
                    // Decision 332 — the subject is a block: equal by value.
                    try self.emit(.{ .local_get = subj });
                    try self.lowerBigintLiteral(n);
                    try self.emitStdCall("bigint.compare");
                    try self.emit(opOf(.i32, "eqz"));
                    return;
                }
                try self.emit(.{ .local_get = subj });
                const t = numLitType(n);
                // A subject of another wasm type (`i64`, `u64`, `f64`) is
                // compared as that type: `5l` is `i64.eq`, never narrowed.
                const st = self.locals.get(subj) orelse .i32;
                if (!st.isWord()) {
                    try self.emit(constOf(st, try numeralText(self.arena(), n)));
                    try self.emit(opOf(st, "eq"));
                    return;
                }
                // the subject local is i32; a float literal is compared as one
                if (t.isFloat()) {
                    try self.emit(constOf(.f64, n));
                    try self.emit(.{ .convert = "i32.trunc_f64_s" });
                } else try self.emit(try numLitConst(self.arena(), n));
                try self.emit(opOf(.i32, "eq"));
            },
            .stringLit => |lit| {
                const bytes = try self.literalBytes(lit);
                try self.emit(.{ .local_get = subj });
                try self.emitStrLit(bytes);
                try self.emit(self.builder().helper(.str_eq));
            },
            .@"or" => |pats| {
                try self.emit(zero);
                for (pats) |sub| {
                    try self.emitPatternTest(sub, subj, loc);
                    try self.emit(opOf(.i32, "or"));
                }
            },
            .variant => |v| {
                if (v.shape == .tuple) return self.emitTuplePatternTest(v, subj, loc);
                if (v.shape == .range) {
                    // `A...B` (decision 53): both ends included. The bounds are
                    // `payload.literals[0..2]`, low then high; the subject local
                    // is an i32, so a float bound is compared as one. Before
                    // this arm the shape fell into the variant path below, found
                    // no variant named `""` and answered `0` for every value.
                    const bounds = v.payload.literals;
                    // A `u64` subject orders unsigned: a value past `i64`'s top
                    // is above every bound, not below zero.
                    const uns = self.u64_subjects.contains(subj);
                    try self.emitRangeBound(bounds[0], subj, if (uns) "ge_u" else "ge_s", loc);
                    try self.emitRangeBound(bounds[1], subj, if (uns) "le_u" else "le_s", loc);
                    try self.emit(opOf(.i32, "and"));
                    return;
                }
                // A RECORD's constructor pattern (`val assert Person(n, a) =
                // p catch …`): the value's header names the record, and a
                // nested pattern tests the field it stands at. Read as a
                // variant, no enum declared the name and the pattern tested
                // nothing and bound nothing (`unbound identifier n`).
                if (self.recordPatternType(v)) |rty| {
                    if (!try self.emitNamedTypeTest(rty, subj)) return self.refuse(loc, "the wasm backend has no descriptor for `{s}`, so its constructor pattern cannot be tested", .{rty});
                    if (v.payload == .literals) for (v.payload.literals, 0..) |sub, i| {
                        const fname = self.recordPatternField(rty, v, i) orelse
                            return self.refuse(loc, "the constructor pattern names a field `{s}` does not declare", .{rty});
                        const field = try std.fmt.allocPrint(self.arena(), "__case_{d}", .{self.case_depth});
                        self.case_depth += 1;
                        var then_c: Capture = .{};
                        self.open(&then_c);
                        const acc = try self.recordFieldAccess(subj, rty, fname);
                        try self.declareLocal(field, self.wasmTypeOf(acc));
                        try self.lowerValue(acc);
                        try self.emit(.{ .local_set = field });
                        try self.noteFieldBinder(field, rty, fname);
                        try self.emitPatternTest(sub, field, loc);
                        const then_seq = self.seal(&then_c, .{ .value = .i32 });
                        var else_c: Capture = .{};
                        self.open(&else_c);
                        try self.emit(zero);
                        const else_seq = self.seal(&else_c, .{ .value = .i32 });
                        try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                    };
                    return;
                }
                const ref = self.variantRef(v.name) orelse
                    return self.refuse(loc, "`{s}` names no variant of an enum this program declares", .{v.name});
                try self.emitTagTest(ref, subj);
                // The payload's nested patterns, read only once the tag held
                // (a unit variant's cell has no payload slots) and `and`ed
                // into the tag test. Each test was left on the stack beside
                // the tag's, unread: the arm answered whatever the last
                // one said, and a `_` or a plain name tested a slot of a
                // value the tag had already refused.
                const lits: []const ast.Pattern = if (v.payload == .literals) v.payload.literals else &.{};
                var tested = false;
                for (lits) |sub| {
                    if (!self.patternOnlyBinds(sub)) tested = true;
                }
                if (tested) {
                    var then_c: Capture = .{};
                    self.open(&then_c);
                    try self.emit(one);
                    for (lits, 0..) |sub, i| {
                        if (self.patternOnlyBinds(sub)) continue;
                        const slot = payloadSlot(ref, v, i) orelse
                            return self.refuse(loc, "a label of the `{s}` pattern names no field its variant declares", .{v.name});
                        const field = try self.payloadFieldLocal(ref, subj, slot);
                        try self.emitPatternTest(sub, field, loc);
                        try self.emit(opOf(.i32, "and"));
                    }
                    const then_seq = self.seal(&then_c, .{ .value = .i32 });
                    var else_c: Capture = .{};
                    self.open(&else_c);
                    try self.emit(zero);
                    const else_seq = self.seal(&else_c, .{ .value = .i32 });
                    try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                }
            },
        }
    }

    /// The element patterns of a tuple pattern (`#(0, s)`, `#(a, ..)`).
    fn tupleElems(v: anytype) []const ast.Pattern {
        return switch (v.payload) {
            .literals => |l| l,
            else => &.{},
        };
    }

    /// Whether a pattern only binds (or ignores) — it tests nothing.
    fn patternOnlyBinds(self: *Emitter, p: ast.Pattern) bool {
        return switch (p) {
            .wildcard => true,
            .ident => |n| !isLitPatternName(n) and !isVariantPath(n) and self.findVariant(n) == null and !self.records.contains(n),
            else => false,
        };
    }

    fn isBoolLitName(n: []const u8) bool {
        return std.mem.eql(u8, n, "true") or std.mem.eql(u8, n, "false");
    }

    /// `true`, `false` and `null` ride on `Pattern.ident`
    /// (`parser/patterns.zig` `parseSimplePattern`): literals a pattern
    /// tests, never names it binds.
    fn isLitPatternName(n: []const u8) bool {
        return isBoolLitName(n) or std.mem.eql(u8, n, "null");
    }

    /// Element `i` of the tuple `subj` holds — its shape code (`s`, `i`, `(…)`),
    /// read off the subject's tuple shape. A tuple pattern needs it: the slot
    /// is a word whatever it holds, and a string bound as an integer printed
    /// its address.
    fn tuplePatternElemShape(self: *Emitter, subj: []const u8, i: usize, loc: ast.Loc) anyerror![]const u8 {
        const sh = self.print_shape_locals.get(subj) orelse
            return self.refuse(loc, "the wasm backend does not know the element types of this tuple pattern's subject", .{});
        return tupleShapeElem(sh, @intCast(i)) orelse
            self.refuse(loc, "the tuple pattern has more elements than its subject's type", .{});
    }

    /// Decision 8 §5.1 P6/P7 — `#(0, s)`: each element that tests something
    /// is read from its slot (`i * 4`, no header) and tested in a chain, as a
    /// variant's payload literals are; a binder, `_` and the elements `..`
    /// skips test nothing. A float element is a cell (`emitToFloatSlot`), which the `i32`
    /// tests here cannot compare — refused, never compared as bits.
    fn emitTuplePatternTest(self: *Emitter, v: anytype, subj: []const u8, loc: ast.Loc) anyerror!void {
        try self.emit(one);
        for (tupleElems(v), 0..) |sub, i| {
            if (self.patternOnlyBinds(sub)) continue;
            const code = try self.tuplePatternElemShape(subj, i, loc);
            if (code[0] == 'f') return self.refuse(loc, "the wasm backend cannot test a float tuple element against a pattern", .{});
            if (shapeCell(code) == .i64) return self.refuse(loc, "the wasm backend cannot test a 64-bit integer tuple element against a pattern", .{});
            const field = try std.fmt.allocPrint(self.arena(), "__case_{d}", .{self.case_depth});
            self.case_depth += 1;
            try self.declareLocal(field, if (self.mode == .gc) (gcShapeRepr(code) orelse return self.gcFail("a tuple element of no known repr")) else .i32);
            try self.noteTupleElemLocal(field, code);
            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emit(.{ .local_get = subj });
            if (self.mode == .gc) {
                try self.emit(try self.constInt(i));
                try self.emit(.{ .array_get = .{ .ty = self.gcTyIndex(.{ .arr = .any }) } });
                try self.gcFromAny(code);
            } else try self.emit(.{ .load = .{ .offset = @intCast(i * 4) } });
            try self.emit(.{ .local_set = field });
            try self.emitPatternTest(sub, field, loc);
            const then_seq = self.seal(&then_c, .{ .value = .i32 });
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emit(zero);
            const else_seq = self.seal(&else_c, .{ .value = .i32 });
            try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
        }
    }

    /// What a local holding one tuple element is, by the element's shape code.
    fn noteTupleElemLocal(self: *Emitter, n: []const u8, code: []const u8) !void {
        const scalar: ?[]const u8 = switch (code[0]) {
            'i' => "i32",
            's' => "string",
            'b' => "bool",
            'f' => "f64",
            'l' => "i64",
            'u' => "u64",
            'n' => "bigint",
            else => null,
        };
        if (scalar) |t| try self.local_typerefs.put(n, .{ .named = t });
        switch (code[0]) {
            's' => try self.str_locals.put(n, {}),
            'b' => try self.bool_locals.put(n, {}),
            '(' => try self.print_shape_locals.put(n, code),
            '[' => {
                try self.print_shape_locals.put(n, code);
                try self.arr_locals.put(n, {});
                try self.arr_elem_locals.put(n, if (code.len > 1 and code[1] == 's') .str else if (code.len > 1 and code[1] == 'f') .f64 else .i32);
            },
            else => {},
        }
    }

    /// `[]`, `[x]`, `[4, ..]`, `[first, ..rest]`: the length — exactly the
    /// elements written, or at least them with a spread — then each number
    /// literal against its slot, in a chain. It matched every array (the
    /// pattern answered `1`), so `[x]` took `[]`'s arm at exit 0.
    fn emitListPatternTest(self: *Emitter, l: anytype, subj: []const u8, loc: ast.Loc) anyerror!void {
        if (!self.arr_locals.contains(subj)) return self.refuse(loc, "the wasm backend tests a list pattern against an array subject only", .{});
        try self.emit(.{ .local_get = subj });
        try self.emitC(.{ .load = .{} }, "element count");
        try self.emit(try self.constInt(@as(i32, @intCast(l.elems.len))));
        try self.emit(opOf(.i32, if (l.spread == null) "eq" else "ge_u"));
        for (l.elems, 0..) |el, i| {
            const n = switch (el) {
                .numberLit => |n| n,
                else => continue,
            };
            if (self.arr_elem_locals.get(subj) == .f64 or numLitType(n).isFloat())
                return self.refuse(loc, "the wasm backend cannot test a float list element against a pattern", .{});
            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emit(.{ .local_get = subj });
            try self.emit(.{ .load = .{ .offset = @intCast((i + 1) * 4) } });
            try self.emit(try numLitConst(self.arena(), n));
            try self.emit(opOf(.i32, "eq"));
            const then_seq = self.seal(&then_c, .{ .value = .i32 });
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emit(zero);
            const else_seq = self.seal(&else_c, .{ .value = .i32 });
            try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
        }
    }

    /// Bind a list pattern's names: each `bind` from its slot, a named spread
    /// to the rest of the array (std-wasm's `array.slice`).
    fn bindListPattern(self: *Emitter, l: anytype, subj: []const u8) anyerror!void {
        const ek = self.arr_elem_locals.get(subj) orelse .i32;
        const sh = self.print_shape_locals.get(subj);
        for (l.elems, 0..) |el, i| {
            const name = switch (el) {
                .bind => |b| b,
                else => continue,
            };
            const float = ek == .f64;
            const n = try self.bindName(name, if (float) .f64 else .i32);
            try self.emit(.{ .local_get = subj });
            try self.emit(.{ .load = .{ .offset = @intCast((i + 1) * 4) } });
            if (float) try self.emitFromFloatSlot();
            try self.emitConvert(if (float) .f64 else .i32, self.locals.get(n) orelse .i32);
            try self.emit(.{ .local_set = n });
            if (sh) |shape| if (shape.len > 1) try self.noteTupleElemLocal(n, shape[1..]);
            if (ek == .str) try self.str_locals.put(n, {});
            if (ek != .f64) try self.tuple_binders.put(self.reg_arena.allocator(), n, {});
        }
        const rest = l.spread orelse return;
        if (rest.len == 0) return;
        const n = try self.bindName(rest, .i32);
        try self.emit(.{ .local_get = subj });
        try self.emit(try self.constInt(@as(i32, @intCast(l.elems.len))));
        try self.emit(try self.constInt(std.math.maxInt(i32)));
        try self.emitStdCall("array.slice");
        try self.emit(.{ .local_set = n });
        try self.arr_locals.put(n, {});
        try self.arr_elem_locals.put(n, ek);
        if (sh) |shape| try self.print_shape_locals.put(n, shape);
    }

    /// Bind the names a tuple pattern introduces, each from its slot.
    fn bindTuplePattern(self: *Emitter, v: anytype, subj: []const u8) anyerror!void {
        for (tupleElems(v), 0..) |sub, i| {
            if (sub == .wildcard) continue;
            const code = try self.tuplePatternElemShape(subj, i, .{ .line = 0, .col = 0 });
            const cell = shapeCell(code);
            const float = cell != .none;
            if (sub == .ident and self.patternOnlyBinds(sub)) {
                if (self.mode == .gc) {
                    const er = gcShapeRepr(code) orelse return self.gcFail("a tuple element of no known repr");
                    const n = try self.bindName(sub.ident, er);
                    try self.emit(.{ .local_get = subj });
                    try self.emit(try self.constInt(i));
                    try self.emit(.{ .array_get = .{ .ty = self.gcTyIndex(.{ .arr = .any }) } });
                    try self.gcFromAny(code);
                    try self.emitConvert(er, self.locals.get(n) orelse er);
                    try self.emit(.{ .local_set = n });
                    try self.noteTupleElemLocal(n, code);
                    try self.tuple_binders.put(self.reg_arena.allocator(), n, {});
                    continue;
                }
                const n = try self.bindName(sub.ident, cell.ty());
                try self.emit(.{ .local_get = subj });
                try self.emit(.{ .load = .{ .offset = @intCast(i * 4) } });
                try self.emitFromCell(cell);
                try self.emitConvert(cell.ty(), self.locals.get(n) orelse .i32);
                try self.emit(.{ .local_set = n });
                try self.noteTupleElemLocal(n, code);
                try self.tuple_binders.put(self.reg_arena.allocator(), n, {});
                continue;
            }
            if (float or sub == .numberLit or sub == .stringLit) continue;
            const field = try std.fmt.allocPrint(self.arena(), "__case_{d}", .{self.case_depth});
            self.case_depth += 1;
            try self.declareLocal(field, .i32);
            try self.noteTupleElemLocal(field, code);
            try self.emit(.{ .local_get = subj });
            try self.emit(.{ .load = .{ .offset = @intCast(i * 4) } });
            try self.emit(.{ .local_set = field });
            try self.bindPattern(sub, field);
        }
    }

    /// One end of a range pattern: `subj <op> bound`, the bound a number
    /// literal (a string bound has no wasm ordering yet and answers `0`).
    fn emitRangeBound(self: *Emitter, bound: ast.Pattern, subj: []const u8, cmp: []const u8, loc: ast.Loc) anyerror!void {
        switch (bound) {
            .numberLit => |n| {
                if (lexerMod.isBigintText(n)) {
                    // Decision 332 — `subj <cmp> bound` by std-wasm's `bigint.compare`'s sign.
                    try self.emit(.{ .local_get = subj });
                    try self.lowerBigintLiteral(n);
                    try self.emitStdCall("bigint.compare");
                    try self.emit(zero);
                    try self.emit(opOf(.i32, cmp));
                    return;
                }
                try self.emit(.{ .local_get = subj });
                const t = numLitType(n);
                const st = self.locals.get(subj) orelse .i32;
                if (!st.isWord()) {
                    // `subj <cmp> bound` as the subject's own wasm type; a
                    // float's comparisons carry no signedness.
                    try self.emit(constOf(st, try numeralText(self.arena(), n)));
                    try self.emit(opOf(st, if (st.isFloat()) cmp[0..2] else cmp));
                    return;
                }
                if (t.isFloat()) {
                    try self.emit(constOf(.f64, n));
                    try self.emit(.{ .convert = "i32.trunc_f64_s" });
                } else try self.emit(try numLitConst(self.arena(), n));
                try self.emit(opOf(.i32, cmp));
            },
            else => return self.refuse(loc, "the wasm backend tests a range pattern against a number literal bound only", .{}),
        }
    }

    /// A user variant's identity over a subject that may not be a value of its
    /// enum at all: an all-unit enum's member is its ordinal, which no pointer
    /// equals (a pointer is at least the heap floor); a payload enum's member
    /// is allocated and carries its variant's descriptor, so the test is the
    /// header one, never a load of what would be a record's first field.
    fn emitVariantIdentityTest(self: *Emitter, fv: FoundVariant, subj: []const u8, loc: ast.Loc) anyerror!void {
        if (enumHasPayload(fv.variants)) {
            var it = self.enums.iterator();
            while (it.next()) |entry| {
                if (entry.value_ptr.*.ptr != fv.variants.ptr) continue;
                const d = try self.variantDescriptorAddr(entry.key_ptr.*, fv.variant) orelse break;
                try self.emit(.{ .local_get = subj });
                try self.emit(try self.constInt(heap_floor));
                try self.emit(opOf(.i32, "ge_u"));
                try self.emitHeaderLoad(subj);
                try self.emit(try self.constInt(d));
                try self.emit(opOf(.i32, "eq"));
                try self.emit(opOf(.i32, "and"));
                return;
            }
            return self.refuse(loc, "the wasm backend has no descriptor for the variant `{s}`, so the arm cannot be tested", .{fv.variant.name});
        }
        try self.emitTagTest(.{ .user = fv }, subj);
    }

    /// The enum whose variants are `variants` (by identity of the slice).
    fn enumNameOfVariants(self: *Emitter, variants: []const ast.EnumVariant) ?[]const u8 {
        var it = self.enums.iterator();
        while (it.next()) |entry| if (entry.value_ptr.*.ptr == variants.ptr) return entry.key_ptr.*;
        return null;
    }

    /// Front 164 s2 P2 — the type of the struct a value of variant `fv` is:
    /// null (and a gap) when the enum is generic or no enum declares it.
    fn gcVariantTy(self: *Emitter, fv: FoundVariant) anyerror!u16 {
        const en = self.enumNameOfVariants(fv.variants) orelse return self.gcFail("a variant of no enum");
        return self.gcTyIndex(.{ .variant = .{ .en = en, .name = fv.variant.name } });
    }

    fn emitTagTest(self: *Emitter, ref: VariantRef, subj: []const u8) anyerror!void {
        switch (ref) {
            .user => |fv| {
                // A payload enum's value in a GC module is a struct of its
                // variant's type: the test is the type's, and a null is none.
                if (self.mode == .gc and enumHasPayload(fv.variants)) {
                    const vv = ValType.def(try self.gcVariantTy(fv));
                    try self.emit(.{ .local_get = subj });
                    try self.emit(.{ .ref_test = vv });
                    try self.emit(.{ .local_get = subj });
                    try self.emit(.ref_is_null);
                    try self.emit(opOf(.i32, "eqz"));
                    try self.emit(opOf(.i32, "and"));
                    return;
                }
                try self.emit(.{ .local_get = subj });
                if (enumHasPayload(fv.variants)) try self.emitC(.{ .load = .{} }, "variant tag");
                try self.emitCf(try self.constInt(fv.tag), "{s}", .{fv.variant.name});
                try self.emit(opOf(.i32, "eq"));
            },
            .result_ok, .result_err => {
                try self.emit(.{ .local_get = subj });
                if (self.mode == .gc)
                    try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.result), .field = 0 } })
                else
                    try self.emitC(.{ .load = .{} }, result_tag);
                if (ref == .result_ok) try self.emit(opOf(.i32, "eqz"));
            },
        }
    }

    fn resolveName(self: *Emitter, n: []const u8) []const u8 {
        if (self.aliases.get(n)) |a| return a;
        // A module-level `val` two linked modules declare: this module's
        // read means its own (mangled) one, unless a local shadows it.
        if (self.global_renames) |m| if (m.get(n)) |g| if (!self.locals.contains(n)) return g;
        return n;
    }

    /// The local a pattern binding `n` of wasm type `ty` is stored in: `n`
    /// itself, or — when `n` is already a local of another type — a fresh
    /// alias the arm's uses resolve to (until `emitCaseArms` drops it).
    fn bindName(self: *Emitter, n: []const u8, ty: Repr) ![]const u8 {
        if (self.locals.get(n)) |existing| {
            // A binder over a name an enclosing statement list (or a
            // parameter) binds is a local of its own too: `case 5 { n -> … }`
            // under a `val n` wrote the outer `$n`.
            const shadows = self.bound_names.contains(n) or self.isParamLocal(n);
            // A GC module's pattern local was declared a word before the
            // subject's payload types were known: a payload of another
            // representation is a local of its own.
            if (shadows or (!self.sameVal(existing, ty) and (!self.pattern_locals.contains(n) or self.mode == .gc))) return self.bindAlias(n, ty);
        }
        _ = self.aliases.remove(n);
        try self.declareLocal(n, ty);
        return n;
    }

    /// A fresh local of type `ty` the name `n` stands for from here on.
    fn bindAlias(self: *Emitter, n: []const u8, ty: Repr) ![]const u8 {
        const alias = try std.fmt.allocPrint(self.arena(), "{s}__{d}", .{ n, self.alias_seq });
        self.alias_seq += 1;
        try self.declareLocal(alias, ty);
        try self.aliases.put(n, alias);
        return alias;
    }

    /// Bind the names a pattern introduces, from the subject held in `subj`.
    /// A record constructor in binding position (`val Circle(r) = s;`): the
    /// record's declared field names and, per position, the name each binds
    /// (`""` for `_`). Null when the pattern names no record of this module or
    /// nests a pattern (the binding then takes `bindPattern`'s walk).
    fn ctorRecordFields(self: *Emitter, pat: ast.Pattern) ?struct { record: []const u8, fields: []const []const u8, binds: []const []const u8 } {
        if (pat != .variant) return null;
        const v = pat.variant;
        const name = bareVariantName(v.name);
        const fields = self.records.get(name) orelse return null;
        if (v.payload != .literals) return null;
        const lits = v.payload.literals;
        if (lits.len > fields.len) return null;
        const binds = self.arena().alloc([]const u8, lits.len) catch return null;
        for (lits, 0..) |l, i| binds[i] = switch (l) {
            .wildcard => "",
            .ident => |n| n,
            else => return null,
        };
        return .{ .record = name, .fields = fields, .binds = binds };
    }

    /// A variant constructor in binding position (`val Sq(side) = q;`) as the
    /// `case` arm pattern `bindPattern` already reads — its positional names
    /// as `.fields`. Null for a nested pattern or an unknown variant.
    fn ctorAsFieldsPattern(self: *Emitter, pat: ast.Pattern) !?ast.Pattern {
        if (pat != .variant) return null;
        const v = pat.variant;
        if (self.variantRef(v.name) == null) return null;
        if (v.payload != .literals) return pat;
        const lits = v.payload.literals;
        const names = try self.arena().alloc([]const u8, lits.len);
        for (lits, 0..) |l, i| names[i] = switch (l) {
            .wildcard => "_",
            .ident => |n| n,
            else => return null,
        };
        var out = v;
        out.payload = .{ .fields = names };
        return .{ .variant = out };
    }

    /// The enum `subject` is a value of, when its declared type names one:
    /// a parameter, a local, a field or a call typed by the enum, `self`
    /// inside the enum's own method, and a section written as a path
    /// (`Token.Layout.Break`), declared under the F1 mangling
    /// (`__Token__Layout__Break`).
    fn enumOfSubject(self: *Emitter, subject: ast.Expr) ?[]const u8 {
        const written: []const u8 = blk: {
            if (subject == .identifier and subject.identifier.kind == .ident and
                std.mem.eql(u8, subject.identifier.kind.ident, "self"))
            {
                if (self.self_type) |st| break :blk st;
            }
            const tr = self.typeRefOf(subject) orelse return null;
            break :blk switch (tr) {
                .named => |n| n,
                .generic => |g| g.name,
                else => return null,
            };
        };
        if (self.enums.contains(written)) return written;
        if (std.mem.indexOfScalar(u8, written, '.') == null) return null;
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        var it = std.mem.splitScalar(u8, written, '.');
        while (it.next()) |seg| {
            buf.appendSlice(self.arena(), "__") catch return null;
            buf.appendSlice(self.arena(), seg) catch return null;
        }
        if (self.enums.getKey(buf.items)) |declared| return declared;
        return null;
    }

    /// The record a constructor pattern names (`Person(n, a)`), when no enum
    /// declares a variant of that name: the pattern is then the record's.
    fn recordPatternType(self: *Emitter, v: anytype) ?[]const u8 {
        if (v.shape != .variant or isResultPath(v.name)) return null;
        if (isVariantPath(v.name)) return null;
        if (self.findVariant(v.name) != null) return null;
        return self.resolveRecordName(v.name);
    }

    /// The field the i-th element of a record pattern stands at: its label,
    /// else the declared field at that position.
    fn recordPatternField(self: *Emitter, rty: []const u8, v: anytype, i: usize) ?[]const u8 {
        const fields = self.records.get(rty) orelse return null;
        if (v.labels.len > i and v.labels[i].len > 0) {
            for (fields) |f| if (std.mem.eql(u8, f, v.labels[i])) return f;
            return null;
        }
        return if (i < fields.len) fields[i] else null;
    }

    /// `subj.field` over the record `rty` in `subj`, as the source would
    /// write it — lowered by the field read every other access takes, a boxed
    /// float field included.
    fn recordFieldAccess(self: *Emitter, subj: []const u8, rty: []const u8, fname: []const u8) !ast.Expr {
        try self.local_types.put(subj, rty);
        const recv = try self.arena().create(ast.Expr);
        recv.* = .{ .identifier = .{ .loc = .{ .line = 0, .col = 0 }, .kind = .{ .ident = subj } } };
        return .{ .identifier = .{ .loc = .{ .line = 0, .col = 0 }, .kind = .{ .identAccess = .{ .receiver = recv, .member = fname } } } };
    }

    /// A local bound from a record field carries the field's declared shape.
    fn noteFieldBinder(self: *Emitter, n: []const u8, rty: []const u8, fname: []const u8) !void {
        const ft = self.fieldTypeIn(rty, fname) orelse return;
        if (std.mem.eql(u8, ft, "string")) try self.str_locals.put(n, {});
        if (std.mem.eql(u8, ft, "bool")) try self.bool_locals.put(n, {});
        if (self.resolveRecordName(ft)) |r| try self.local_types.put(n, r);
        // The binder carries the field's whole declared type, as a parameter
        // does: `Dog(age: a)` over `age: ?i32` is a `?i32`, so `a ?? 0`
        // unboxes it — read as a plain word, `"${a ?? 0}"` printed the box's
        // address.
        if (self.fieldTypeRefIn(rty, fname)) |t| try self.noteTypedBinder(n, t);
    }

    /// The local a multi-subject `case` holds its i-th subject in.
    fn multiSubjectLocal(a: std.mem.Allocator, subj: []const u8, i: usize) ![]const u8 {
        return std.fmt.allocPrint(a, "{s}_{d}", .{ subj, i });
    }

    fn bindPattern(self: *Emitter, p: ast.Pattern, subj: []const u8) anyerror!void {
        const prev_hint = self.case_enum_hint;
        self.case_enum_hint = self.subject_enums.get(subj);
        defer self.case_enum_hint = prev_hint;
        switch (p) {
            .multi => |pats| for (pats, 0..) |sub, i| {
                const local = try multiSubjectLocal(self.arena(), subj, i);
                // A primitive type names no binder.
                if (sub == .ident and self.unknown_subjects.contains(local) and primTestOf(.{ .named = sub.ident }) != null) continue;
                try self.bindPattern(sub, local);
            },
            .ident => |n0| if (!isLitPatternName(n0) and !isVariantPath(n0) and self.findVariant(n0) == null) {
                const n = try self.bindName(n0, self.locals.get(subj) orelse .i32);
                if (self.str_locals.contains(subj)) try self.str_locals.put(n, {});
                try self.emit(.{ .local_get = subj });
                try self.emit(.{ .local_set = n });
            },
            .list => |l| try self.bindListPattern(l, subj),
            .variant => |v| {
                if (v.shape == .tuple) return self.bindTuplePattern(v, subj);
                // A record's constructor pattern binds each name from the
                // field it stands at — by label when the pattern wrote one.
                if (self.recordPatternType(v)) |rty| {
                    switch (v.payload) {
                        .binding => |bn| try self.bindPattern(.{ .ident = bn }, subj),
                        .fields => |fs| for (fs, 0..) |n0, i| {
                            if (std.mem.eql(u8, n0, "_")) continue;
                            const fname = self.recordPatternField(rty, v, i) orelse continue;
                            const acc = try self.recordFieldAccess(subj, rty, fname);
                            const ty = self.wasmTypeOf(acc);
                            const n = try self.bindName(n0, ty);
                            try self.lowerValue(acc);
                            try self.emitConvert(ty, self.locals.get(n) orelse ty);
                            try self.emit(.{ .local_set = n });
                            try self.noteFieldBinder(n, rty, fname);
                        },
                        .literals => |lits| for (lits, 0..) |sub, i| {
                            const fname = self.recordPatternField(rty, v, i) orelse continue;
                            const field = try std.fmt.allocPrint(self.arena(), "__case_{d}", .{self.case_depth});
                            self.case_depth += 1;
                            const acc = try self.recordFieldAccess(subj, rty, fname);
                            try self.declareLocal(field, self.wasmTypeOf(acc));
                            try self.lowerValue(acc);
                            try self.emit(.{ .local_set = field });
                            try self.noteFieldBinder(field, rty, fname);
                            try self.bindPattern(sub, field);
                        },
                    }
                    return;
                }
                const ref = self.variantRef(v.name) orelse return;
                switch (v.payload) {
                    .binding => |b| try self.bindPayloadName(ref, subj, 0, b),
                    .fields => |fs| for (fs, 0..) |n0, i| {
                        if (std.mem.eql(u8, n0, "_")) continue;
                        const slot = payloadSlot(ref, v, i) orelse continue;
                        try self.bindPayloadName(ref, subj, slot, n0);
                    },
                    // `Rect(w, _)`, `Two(Rect(w, _), r)`: a `_` binds nothing,
                    // a plain name binds its slot as `.fields` does, and a
                    // nested pattern binds from its slot's own local. This
                    // returned without binding anything, so every name of the
                    // payload read the 0 its local was declared with.
                    .literals => |lits| for (lits, 0..) |sub, i| {
                        if (sub == .wildcard) continue;
                        const slot = payloadSlot(ref, v, i) orelse continue;
                        if (sub == .ident and self.patternOnlyBinds(sub)) {
                            if (std.mem.eql(u8, sub.ident, "_")) continue;
                            try self.bindPayloadName(ref, subj, slot, sub.ident);
                            continue;
                        }
                        const field = try self.payloadFieldLocal(ref, subj, slot);
                        try self.bindPattern(sub, field);
                    },
                }
            },
            else => {},
        }
    }

    /// The payload slot (0-based, after the tag) the i-th element of a
    /// variant pattern stands at: the declared position of the label it wrote
    /// (§5.1 P4), else `i`. Null when the label names no declared field.
    fn payloadSlot(ref: VariantRef, v: anytype, i: usize) ?usize {
        if (v.labels.len > i and v.labels[i].len > 0) switch (ref) {
            .user => |fv| {
                for (fv.variant.fields, 0..) |f, at| if (std.mem.eql(u8, f.name, v.labels[i])) return at;
                return null;
            },
            else => {},
        };
        return i;
    }

    /// The declared type of payload slot `slot` of the variant `ref` names;
    /// null for `@Result`'s and an undeclared slot.
    fn payloadFieldType(ref: VariantRef, slot: usize) ?ast.TypeRef {
        return switch (ref) {
            .user => |fv| if (slot < fv.variant.fields.len) fv.variant.fields[slot].typeRef else null,
            else => null,
        };
    }

    /// A payload typed by a type parameter of the subject's enum (`value: T`
    /// of `Maybe<T>`), read as the argument the subject's written type gives it.
    fn substSubjectParam(self: *Emitter, subj: []const u8, t: ast.TypeRef) ast.TypeRef {
        if (t != .named) return t;
        const sub = self.subject_generic.get(subj) orelse return t;
        const params = self.enum_generics.get(sub.generic.name) orelse return t;
        for (params, 0..) |gp, k| {
            if (std.mem.eql(u8, gp.name, t.named) and k < sub.generic.args.len) return sub.generic.args[k];
        }
        return t;
    }

    /// Payload slot `slot` of the variant in `subj`, in a fresh i32 local a
    /// nested pattern is tested against and binds from — carrying the field's
    /// declared shape: a string, a record, and the enum a nested variant
    /// pattern resolves its bare name against (`subject_enums`).
    fn payloadFieldLocal(self: *Emitter, ref: VariantRef, subj: []const u8, slot: usize) ![]const u8 {
        const field = try std.fmt.allocPrint(self.arena(), "__case_{d}", .{self.case_depth});
        self.case_depth += 1;
        if (self.mode == .gc) {
            const ft = payloadFieldType(ref, slot) orelse return self.gcFail("a payload of no declared type");
            const er = self.gcPayloadDeclRepr(ref, ft);
            const fr = self.gcPayloadRepr(ref, subj, ft, er);
            try self.declareLocal(field, fr);
            try self.emit(.{ .local_get = subj });
            try self.gcLoadPayload(ref, slot);
            try self.emitConvert(er, fr);
        } else {
            try self.declareLocal(field, .i32);
            try self.emit(.{ .local_get = subj });
            try self.emit(.{ .load = .{ .offset = @intCast((slot + 1) * 4) } });
        }
        try self.emit(.{ .local_set = field });
        _ = self.subject_enums.remove(field);
        if (payloadFieldType(ref, slot)) |t0| {
            const t = self.substSubjectParam(subj, t0);
            if (try self.typeRefShape(t)) |sh| if (sh[0] == '(' or sh[0] == '[') try self.print_shape_locals.put(field, sh);
            if (isStringTypeRef(t)) try self.str_locals.put(field, {});
            if (isBoolTypeRef(t)) try self.bool_locals.put(field, {});
            try self.noteTypedBinder(field, t);
            const tn = typeRefName(t);
            if (self.enums.contains(tn)) try self.subject_enums.put(self.alloc, field, tn);
        }
        return field;
    }

    /// The repr a payload declared `t` of the variant `ref` has in its
    /// struct: erased when the enum is generic (`gcErasedRepr`).
    fn gcPayloadDeclRepr(self: *Emitter, ref: VariantRef, t: ast.TypeRef) Repr {
        if (ref == .user) if (self.enumNameOfVariants(ref.user.variants)) |en| if (self.enum_generics.get(en)) |gps|
            return self.gcErasedRepr(gps, t);
        return self.reprOf(t);
    }

    /// The repr a payload declared `t` binds as: a type parameter's slot
    /// (`er` an `unknown`) as the subject's type argument when it is known
    /// (`tparamArgOf`), else as declared.
    fn gcPayloadRepr(self: *Emitter, ref: VariantRef, subj: []const u8, t: ast.TypeRef, er: Repr) Repr {
        if (!(er == .ref and er.ref == .unknown)) return er;
        if (eagerTypeRef(t) != .named) return er;
        if (self.tparamArgOf(ref, subj, t)) |arg| return self.reprOf(arg);
        const r = self.reprOf(t);
        return r;
    }

    /// Front 164 s2 P2 — with the subject (an `anyref`) on the stack, the
    /// payload at `slot` of the variant `ref` names: the value cast to the
    /// variant's struct, and its field read.
    fn gcLoadPayload(self: *Emitter, ref: VariantRef, slot: usize) anyerror!void {
        const fv = switch (ref) {
            .user => |fv| fv,
            else => return self.gcFail("a @Result payload"),
        };
        const k = try self.gcVariantTy(fv);
        try self.emit(.{ .ref_cast = ValType.def(k) });
        try self.emit(.{ .struct_get = .{ .ty = k, .field = @intCast(slot) } });
    }

    /// The type a payload declared `t` (one of the enum's type parameters)
    /// stands for in the subject `subj`: the matching argument of its
    /// recorded `Name<…>` type, or `unknown` for an `unknown` subject.
    fn tparamArgOf(self: *Emitter, ref: VariantRef, subj: []const u8, t: ast.TypeRef) ?ast.TypeRef {
        if (ref != .user or t != .named) return null;
        const en = self.enumOfVariant(ref.user.variant.name) orelse return null;
        const egens = self.enum_generics.get(en) orelse return null;
        const idx = for (egens, 0..) |gp, i| {
            if (std.mem.eql(u8, gp.name, t.named)) break i;
        } else return null;
        if (self.local_typerefs.get(subj)) |st| if (st == .generic and std.mem.eql(u8, st.generic.name, en) and st.generic.args.len == egens.len)
            return st.generic.args[idx];
        if (self.unknown_subjects.contains(subj)) return .{ .named = ast.unknown_type_name };
        return null;
    }

    /// Bind `n0` to payload slot `slot` of the variant in `subj`, typed by the
    /// slot's declaration.
    fn bindPayloadName(self: *Emitter, ref: VariantRef, subj: []const u8, slot: usize, n0: []const u8) !void {
        const field_ty = payloadFieldType(ref, slot);
        // A `@Result` payload is typed by the subject's recorded shape.
        const result_ty: ?ast.TypeRef = switch (ref) {
            .result_ok, .result_err => if (self.result_subjects.get(subj)) |sh| (if (ref == .result_ok) sh.ok else sh.err) else null,
            else => null,
        };
        const result_cell = if (result_ty) |t| resultPayloadCell(t) else .none;
        if (self.mode == .gc and field_ty == null and result_ty == null) return self.gcFail("a payload of no declared type");
        const ty = if (field_ty) |t| (if (self.mode == .gc) self.gcPayloadRepr(ref, subj, t, self.gcPayloadDeclRepr(ref, t)) else self.reprOf(t)) else if (self.mode == .gc) self.reprOf(result_ty.?) else if (result_cell != .none) watType(result_ty.?) else Repr.i32;
        // `declarePatternLocals` declared the name a word, not knowing the
        // subject: an `f64` / `i64` payload binds a local of its own type.
        const n = if (result_cell != .none and !self.sameVal(self.locals.get(n0) orelse ty, ty))
            try self.bindAlias(n0, ty)
        else
            try self.bindName(n0, ty);
        const local_ty = self.locals.get(n) orelse ty;
        if (field_ty) |t| {
            if (isStringTypeRef(t)) try self.str_locals.put(n, {});
            if (isBoolTypeRef(t)) try self.bool_locals.put(n, {});
        }
        // The payload of a variant declared as one of the enum's type
        // parameters is typed by what the subject says it is: the argument of
        // its `Name<…>` type, else — a subject that is an `unknown` (decision
        // 8 §5.1 P5) — the `unknown` its slot holds.
        if (field_ty) |t| if (self.tparamArgOf(ref, subj, t)) |arg| {
            if (isUnknownTypeRef(arg)) {
                try self.local_typerefs.put(n, arg);
            } else if (arg == .named and !watType(arg).isFloat() and !watType(arg).isI64()) {
                if (isStringTypeRef(arg)) try self.str_locals.put(n, {});
                if (isBoolTypeRef(arg)) try self.bool_locals.put(n, {});
                try self.noteTypedBinder(n, arg);
            }
        };
        if (self.mode == .gc and ref != .user) {
            const shape = self.result_subjects.get(subj) orelse ResultShape{};
            if ((ref == .result_ok and shape.ok_str) or (ref == .result_err and shape.err_str))
                try self.str_locals.put(n, {});
            if (if (ref == .result_ok) shape.ok else shape.err) |t| try self.noteTypedBinder(n, t);
            try self.emit(.{ .local_get = subj });
            try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.result), .field = 1 } });
            try self.gcUnbox(ty);
            try self.emitConvert(ty, local_ty);
            try self.emit(.{ .local_set = n });
            return;
        }
        switch (ref) {
            .result_ok, .result_err => {
                const shape = self.result_subjects.get(subj) orelse ResultShape{};
                if ((ref == .result_ok and shape.ok_str) or (ref == .result_err and shape.err_str))
                    try self.str_locals.put(n, {});
                const pt = if (ref == .result_ok) shape.ok else shape.err;
                if (pt) |t| try self.noteTypedBinder(n, t);
                // An `f64` / `i64` payload is its cell's address
                // (`resultPayloadCell`); the binder's own type when the
                // subject's shape is not recorded.
                const cell = if (pt) |t| resultPayloadCell(t) else Cell.of(local_ty);
                if (cell != .none) {
                    try self.emit(.{ .local_get = subj });
                    try self.emitC(.{ .load = .{ .offset = 4 } }, "payload cell");
                    try self.emitFromCell(cell);
                    try self.emitConvert(cell.ty(), local_ty);
                    try self.emit(.{ .local_set = n });
                    return;
                }
            },
            else => {},
        }
        if (self.mode == .gc) {
            try self.emit(.{ .local_get = subj });
            try self.gcLoadPayload(ref, slot);
            try self.emitConvert(self.gcPayloadDeclRepr(ref, field_ty.?), ty);
            try self.emitConvert(ty, local_ty);
            try self.emit(.{ .local_set = n });
            return;
        }
        // payload slots are 4 bytes: a float field's holds its cell
        const slot_float = local_ty.isFloat();
        try self.emit(.{ .local_get = subj });
        try self.emit(.{ .load = .{ .offset = @intCast((slot + 1) * 4) } });
        if (slot_float) try self.emitFromFloatSlot();
        try self.emitConvert(if (slot_float) .f64 else .i32, local_ty);
        try self.emit(.{ .local_set = n });
    }

    /// A unit variant value: its tag, or — when the enum has payload variants,
    /// whose values are `[tag, …fields]` pointers — a one-slot `[tag]` cell, so
    /// every value of the enum has the same shape.
    fn emitUnitVariant(self: *Emitter, variants: []const ast.EnumVariant, tag: u32, ename: []const u8, vname: []const u8) anyerror!void {
        if (!enumHasPayload(variants)) {
            if (ename.len > 0)
                try self.emitCf(try self.constInt(tag), "{s}.{s}", .{ ename, vname })
            else
                try self.emitCf(try self.constInt(tag), ".{s}", .{vname});
            return;
        }
        if (self.mode == .gc) {
            try self.emit(.{ .struct_new = self.gcTyIndex(.{ .variant = .{ .en = ename, .name = vname } }) });
            return;
        }
        const desc = blk: {
            for (variants) |v| {
                if (std.mem.eql(u8, v.name, vname)) break :blk try self.variantDescriptorAddr(ename, v);
            }
            break :blk null;
        };
        const base = try self.allocTagged(desc orelse 0, 4);
        try self.storeSlotConst(base, tag_header_bytes, tag);
        try self.loadTaggedBase(base);
    }

    /// The `(if (result …) (then <arm body>) (else <rest of the chain>))` a
    /// tested case arm expands to. The arm's test is already on the stack.
    fn emitArmChain(self: *Emitter, arms: anytype, subj: []const u8, idx: usize, body: ast.Expr) anyerror!void {
        const ty = self.vtOf(self.cur_result);

        var then_c: Capture = .{};
        self.open(&then_c);
        var arm_aliases = try self.aliases.clone();
        var restored = false;
        errdefer if (!restored) arm_aliases.deinit();
        try self.bindPattern(arms[idx].pattern, subj);
        // An arm naming a record over a union subject (`DogB { d -> … }`):
        // the binder is the record the test proved. It took the subject's
        // type, which a union has none of, so `d.name` printed an address.
        const prev_record = self.arm_record;
        defer self.arm_record = prev_record;
        self.arm_record = switch (arms[idx].pattern) {
            .ident => |n| if (!isVariantPath(n) and self.findVariant(n) == null and self.records.contains(n)) n else null,
            else => null,
        };
        if (arms[idx].guard) |g| {
            try self.emitGuardChain(arms, subj, idx, g);
        } else {
            self.arm_box_as = self.caseArmBoxType(idx);
            try self.lowerArmBody(body, subj);
        }
        self.arm_record = prev_record;
        self.restoreAliases(arm_aliases);
        restored = true;
        const then_seq = self.seal(&then_c, .{ .value = ty });

        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emitCaseArms(arms, subj, idx + 1);
        const else_seq = self.seal(&else_c, .{ .value = ty });

        try self.emit(.{ .@"if" = .{
            .result = ty,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
    }

    // ── aggregates in linear memory ───────────────────────────────────────────
    //
    // Tuples, arrays, records and enum payloads are laid out as a contiguous run
    // of 4-byte slots in the bump-allocated heap. Construction leaves a pointer
    // to the first slot on the stack; element/field access loads from a fixed
    // offset. `$__mem{n}` scratch locals hold the base pointer while the slots
    // are filled (WAT has no `dup`, so the base must be reloaded per slot).

    /// Reserve the next `$__mem` scratch index without emitting anything.
    fn nextMem(self: *Emitter) u32 {
        const k = self.mem_seq;
        self.mem_seq += 1;
        // `countMems` sizes the pool up front; a construct it does not walk
        // (an inlined lambda body, say) still gets a declared slot. Idempotent,
        // so a pre-counted slot keeps its place in the local list.
        const name = self.memName(k) catch return k;
        self.declareLocal(name, .i32) catch {};
        return k;
    }

    /// Bump the heap by `nbytes`, stash the base pointer in a fresh `$__mem{k}`
    /// scratch local, and return `k`.
    fn allocSlots(self: *Emitter, nbytes: u32) ![]const u8 {
        const base = try self.memName(self.nextMem());
        // Every allocation goes through `$__alloc`, the one bump that grows
        // the memory (decision 261); a zero-byte one only reads the pointer.
        if (nbytes > 0) {
            try self.emit(try self.constInt(nbytes));
            try self.emit(self.builder().helper(.alloc));
        } else {
            try self.emit(.{ .global_get = heap_ptr });
        }
        try self.emit(.{ .local_set = base });
        return base;
    }

    /// Store one 4-byte slot. A float operand goes in as the address of its
    /// own `f64` cell (`emitToFloatSlot`); narrowed to an `f32` in the slot,
    /// `1.1` read back as `1.100000023841858` at exit 0.
    fn storeSlotExpr(self: *Emitter, base: []const u8, offset: u32, value: ast.Expr) !void {
        try self.emit(.{ .local_get = base });
        try self.lowerSlotWord(value);
        try self.emit(.{ .store = .{ .offset = offset } });
    }

    /// Leave the word a 4-byte slot holds for `value`: a float's `f64` cell
    /// (`$__box_f64`), anything else the `i32` word itself.
    fn lowerSlotWord(self: *Emitter, value: ast.Expr) anyerror!void {
        if (self.wasmTypeOf(value).isFloat()) {
            try self.lowerCoerced(value, .f64);
            try self.emitToFloatSlot();
        } else try self.lowerCoerced(value, .i32);
    }

    /// Leave the address of `value`'s 8-byte `cell` — an `f64` or an `i64`
    /// — the word a declared field or optional of that type holds.
    fn lowerCellWord(self: *Emitter, value: ast.Expr, cell: Cell) anyerror!void {
        try self.lowerCoerced(value, cell.ty());
        try self.emit(self.builder().helper(switch (cell) {
            .f64 => .box_f64,
            .i64 => .box_i64,
            .none => unreachable,
        }));
    }

    /// The value a cell's address on the stack stands for.
    fn emitFromCell(self: *Emitter, cell: Cell) !void {
        if (cell != .none) try self.emit(.{ .load = .{ .ty = (cell.ty()).num() } });
    }

    /// The word an element of an array of `kind` holds for `value`: a float
    /// array's every element is an `f64` cell (an integer one too —
    /// `[1, 2.5]`), and a float never enters an array whose readers take
    /// words: `var xs = []; xs.push(0.15)` has no element type the backend
    /// can see, and its pointer printed as an integer at exit 0.
    fn lowerElemWord(self: *Emitter, kind: ElemKind, value: ast.Expr) anyerror!void {
        if (kind == .f64) {
            try self.lowerCoerced(value, .f64);
            return self.emitToFloatSlot();
        }
        if (self.wasmTypeOf(value).isFloat())
            return self.refuse(value.getLoc(), "the wasm backend cannot place a float in this array: nothing types its elements as floats (write the array's type, `Array<f64>`)", .{});
        try self.lowerCoerced(value, .i32);
    }

    /// A float in a 4-byte word slot — an array or tuple element, a variant's
    /// payload, a `?f64`, a closure's capture — is the address of an 8-byte
    /// `f64` cell, as a record's float field is (`storeBoxedF64`): the `f64`
    /// on the stack becomes that address.
    fn emitToFloatSlot(self: *Emitter) !void {
        try self.emit(self.builder().helper(.box_f64));
    }

    /// The `f64` a float slot's word (the address of its cell) stands for.
    fn emitFromFloatSlot(self: *Emitter) !void {
        try self.emit(.{ .load = .{ .ty = .f64 } });
    }

    /// Store a float field of a named record: the 4-byte slot holds the
    /// address of an 8-byte `f64` cell, so the field keeps the precision its
    /// declared `f64` promises. Narrowed into the slot as an `f32`, `5e-324`
    /// was `0`, and a read that loaded the slot as an `i32` answered the float's
    /// bits (`1069547520` for `1.5`). `lowerIdentAccess` reads it back
    /// (`i32.load`, then `f64.load`).
    fn storeBoxedF64(self: *Emitter, base: []const u8, offset: u32, value: ast.Expr) !void {
        try self.emit(.{ .local_get = base });
        const cell = try self.allocSlots(8);
        try self.emit(.{ .local_get = cell });
        try self.lowerCoerced(value, .f64);
        try self.emit(.{ .store = .{ .ty = .f64 } });
        try self.emitC(.{ .local_get = cell }, "boxed f64 field");
        try self.emit(.{ .store = .{ .offset = offset } });
    }

    fn storeSlotConst(self: *Emitter, base: []const u8, offset: u32, value: i64) !void {
        try self.emit(.{ .local_get = base });
        try self.emit(try self.constInt(value));
        try self.emit(.{ .store = .{ .offset = offset } });
    }

    fn loadBase(self: *Emitter, base: []const u8) !void {
        try self.emit(.{ .local_get = base });
    }

    /// The VALUE of a tagged allocation: the pointer one header word past the
    /// base (13-module-identity half 3). The header sits BEHIND the pointer on
    /// purpose — every field offset stays what it was, so no read moved.
    fn loadTaggedBase(self: *Emitter, base: []const u8) !void {
        try self.emit(.{ .local_get = base });
        try self.emit(try self.constInt(tag_header_bytes));
        try self.emit(opOf(.i32, "add"));
    }

    /// Allocate `nbytes` of payload behind a header holding `desc` — the
    /// address of the declaration's descriptor. Returns the BASE local; the
    /// payload starts at `tag_header_bytes`.
    fn allocTagged(self: *Emitter, desc: u32, nbytes: u32) ![]const u8 {
        const base = try self.allocSlots(tag_header_bytes + nbytes);
        try self.storeSlotConst(base, 0, desc);
        return base;
    }

    /// `i32.load` at `offset` — the emitter drops a zero `offset=`. Expects the
    /// base pointer on the stack.
    fn emitLoadOffset(self: *Emitter, offset: u32) !void {
        try self.emit(.{ .load = .{ .offset = offset } });
    }

    /// A tuple's slots are words: a float element holds its `f64` cell and a
    /// 64-bit integer (`i64`, `u32`, `u64`) its `i64` cell (`$__box_i64`),
    /// the codes `f` / `l` / `u` of its print shape (`valueShapeOf`), which
    /// every reader of an element goes by. The checker types each element by
    /// itself (`#(1, true)` is no `#(i64, bool)`), so the element's own type
    /// is the slot's. An `i64` element was refused as a narrowing.
    fn lowerTupleLit(self: *Emitter, tl: anytype) anyerror!void {
        return self.lowerTupleLitAs(tl, null);
    }

    /// The same, each element widened to the type `as` gives its slot when
    /// one is given: `pair(5) == #(5, true)` over a `#(u64, bool)`, where the
    /// checker typed the literal by the other operand and the `5` is a `u64`.
    fn lowerTupleLitAs(self: *Emitter, tl: anytype, as: ?[]const ast.TypeRef) anyerror!void {
        if (self.mode == .gc) return self.gcTupleLit(tl, as);
        const base = try self.allocSlots(@intCast(tl.elems.len * 4));
        for (tl.elems, 0..) |el, i| {
            const want: ?ast.TypeRef = if (as) |ts| (if (i < ts.len) ts[i] else null) else null;
            const wide = if (want) |w| (w == .named and fieldCellOf(w.named) == .i64) else self.wasmTypeOf(el).isI64();
            if (wide) {
                try self.emit(.{ .local_get = base });
                try self.lowerCellWord(el, .i64);
                try self.emit(.{ .store = .{ .offset = @intCast(i * 4) } });
            } else try self.storeSlotExpr(base, @intCast(i * 4), el);
        }
        try self.loadBase(base);
    }

    /// The cell a tuple element's shape code says its slot holds.
    fn shapeCell(code: []const u8) Cell {
        if (code.len == 0) return .none;
        return switch (code[0]) {
            'f' => .f64,
            'l', 'u' => .i64,
            else => .none,
        };
    }

    /// F4 — list literals over linear memory with an explicit i32 length
    /// prefix. Layout: `[len i32][elem0 i32][elem1 i32]...`. `.len` reads
    /// the prefix (`i32.load` at offset 0); element access via `arr[N]`
    /// is `i32.load offset=(N+1)*4`. Matches the string layout convention
    /// so `.len` is uniform across both. A trailing spread (`[1, 2, ..rest]`
    /// — the parser admits no other position) is the literal's elements
    /// followed by the spread value's, through std-wasm's `array.concat`; before, the
    /// spread was dropped with a `;; note` and the array was two short.
    fn lowerArrayLit(self: *Emitter, al: anytype, loc: ast.Loc) anyerror!void {
        if (self.mode == .gc) return self.gcArrayLit(al);
        const total: u32 = @intCast((al.elems.len + 1) * 4);
        // Decision 150 — the elements of a union array are each boxed as the
        // member they are: written so (`expected_union_array`), or disagreeing
        // in the literal (`[1, "a"]`). Stored as bare words, `[3, "abcd"]`
        // printed `[3, 256]` and its elements could not be told apart.
        const union_elems = self.expected_union_array or (try self.unionArrayLitTypeRef(al)) != null;
        self.expected_union_array = false;
        if (union_elems) {
            if (self.mode != .gc) self.builder().helpers.require(.print_shaped_unknown);
            const ubase = try self.allocSlots(total);
            try self.storeSlotConst(ubase, 0, @intCast(al.elems.len));
            for (al.elems, 0..) |el, i| {
                try self.emit(.{ .local_get = ubase });
                try self.lowerAsUnknown(el);
                try self.emit(.{ .store = .{ .offset = @intCast((i + 1) * 4) } });
            }
            try self.loadBase(ubase);
            if (al.spreadExpr != null or al.spread != null)
                return self.refuse(loc, "the wasm backend has no spread into an array of a union yet", .{});
            return;
        }
        // One element kind for the whole literal (`elemKindOf`: a float
        // anywhere makes every slot a cell), which is the kind its readers ask.
        const kind = self.elemKindOf(.{ .collection = .{ .loc = loc, .kind = .{ .arrayLit = al } } });
        const base = try self.allocSlots(total);
        try self.storeSlotConst(base, 0, @intCast(al.elems.len));
        for (al.elems, 0..) |el, i| {
            const off: u32 = @intCast((i + 1) * 4);
            try self.emit(.{ .local_get = base });
            try self.lowerElemWord(kind, el);
            try self.emit(.{ .store = .{ .offset = off } });
        }
        try self.loadBase(base);
        if (al.spreadExpr) |se| {
            try self.lowerCoerced(se.*, .i32);
            try self.emitStdCall("array.concat");
        } else if (al.spread) |name| {
            if (name.len == 0) return self.refuse(loc, "a bare `..` in an array literal spreads nothing", .{});
            const rest = try self.arena().create(ast.Expr);
            rest.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = name } } };
            try self.lowerCoerced(rest.*, .i32);
            try self.emitStdCall("array.concat");
        }
    }

    /// `record { a: 1, b: "x" }` → contiguous 4-byte slots in source-text order.
    /// Mirrors `lowerRecordCtor` but for anonymous records: the field list is
    /// taken from the literal itself.
    /// F1 tail: also registers the literal under its synthetic name
    /// (`__anon_L{line}_C{col}`) so subsequent `recv.field` reads against
    /// `val r = record { ... }` resolve to a real `i32.load offset=N`.
    fn lowerRecordLit(self: *Emitter, rl: anytype) anyerror!void {
        // Drop the returned name — registration is the side-effect we want.
        // `lowerExpr` callers feed `Expr.loc` into us; the surrounding
        // `lowerExpr` arm already has the loc, but the recordLit path inside
        // `recordTypeOfExpr` is the one that needs the synthetic name. We
        // pre-register here so the registry is non-empty by the time a later
        // `recv.field` access fires.
        _ = self.ensureAnonRecordFromLit(rl) catch {};
        const base = try self.allocSlots(@intCast(rl.fields.len * 4));
        for (rl.fields, 0..) |f, i| {
            try self.storeSlotExpr(base, @intCast(i * 4), f.value.*);
        }
        try self.loadBase(base);
    }

    /// `@Greeter(greet: { self, who -> … })` — a record literal whose lambda
    /// fields take their parameter types from the behavior's declaration of
    /// the method, so `who` is a string inside the lifted lambda.
    fn lowerBehaviorLit(self: *Emitter, il: anytype) anyerror!void {
        _ = self.ensureAnonRecordFromLit(.{ .fields = il.fields }) catch {};
        const base = try self.allocSlots(@intCast(il.fields.len * 4));
        for (il.fields, 0..) |f, i| {
            var buf: [256]u8 = undefined;
            const key = std.fmt.bufPrint(&buf, "{s}.{s}", .{ il.name, f.name }) catch "";
            if (self.behavior_methods.get(key)) |m| {
                if (f.value.* == .function) self.expected_params = m.params;
            }
            defer self.expected_params = null;
            try self.storeSlotExpr(base, @intCast(i * 4), f.value.*);
        }
        try self.loadBase(base);
    }

    /// `lowerRecordLit` has no `Loc` in hand (`lowerExpr` calls the arm with
    /// just the kind payload). We synthesise a loc from the first field's
    /// loc as a stable identity — a literal with N fields will produce the
    /// same name on every encounter.
    fn ensureAnonRecordFromLit(self: *Emitter, rl: anytype) ![]const u8 {
        const loc: ast.Loc = if (rl.fields.len > 0) rl.fields[0].value.getLoc() else .{ .line = 0, .col = 0 };
        return self.ensureAnonRecord(loc, rl);
    }

    /// `Rec(a: 1, b: 2)` → contiguous slots in declaration order. Named args are
    /// matched to fields by label; otherwise positional order is used.
    /// Static extension dispatch (F6). Returns true when `cc` is an activated
    /// or qualified extension call and was lowered to `call $<target>_<method>`.
    fn lowerDispatchCall(self: *Emitter, cc: anytype, loc: ast.Loc) anyerror!bool {
        var nbuf: [256]u8 = undefined;
        // Activated: `recv.m(args)` carries a rewrite entry → push the receiver
        // as the first argument, then the explicit args.
        if (self.rewrites.get(loc)) |sym| {
            const mangled = self.extMangledName(&nbuf, sym, cc.callee) orelse return false;
            const sig = self.fn_sigs.get(mangled) orelse
                return self.refuse(loc, "`{s}` resolves to a method the wasm backend emitted no function for", .{mangled});
            var base: usize = 0;
            if (cc.receiver) |recv| if (sig.params.len > 0) {
                try self.lowerCoerced(recv.*, sig.params[0]);
                base = 1;
            };
            try self.lowerCallArgs(cc.args, sig, base);
            // `mangled` lives in a stack buffer; the node outlives this frame.
            try self.emit(.{ .call = try self.arena().dupe(u8, mangled) });
            return true;
        }
        // Qualified: `Sym.m(obj, args)` where `Sym` names an extension block —
        // the object is already arg 0, so only the args are pushed.
        if (receiverName(cc)) |rn| {
            if (self.ext_by_name.contains(rn)) {
                const mangled = self.extMangledName(&nbuf, rn, cc.callee) orelse return false;
                const sig = self.fn_sigs.get(mangled) orelse
                    return self.refuse(loc, "`{s}` resolves to a method the wasm backend emitted no function for", .{mangled});
                try self.lowerCallArgs(cc.args, sig, 0);
                try self.emit(.{ .call = try self.arena().dupe(u8, mangled) });
                return true;
            }
        }
        return false;
    }

    /// Push the explicit arguments of a call, coerced to the callee's declared
    /// parameter types, padding a short call with zeros.
    fn lowerCallArgs(self: *Emitter, args: anytype, sig: FnSig, base: usize) anyerror!void {
        for (args, 0..) |arg, i| {
            if (base + i >= sig.params.len) break;
            try self.lowerCoerced(arg.value.*, sig.params[base + i]);
        }
        var k = base + args.len;
        while (k < sig.params.len) : (k += 1) {
            try self.emitC(constOf(sig.params[k], "0"), "missing argument");
        }
    }

    /// The WAT symbol a non-builtin call resolves to, or null when this module
    /// defines nothing by that name. Mirrors `lowerDispatchCall` + `lowerPlainCall`
    /// so `exprTail` and the emitter agree on whether a `call` pushes a value.
    /// The symbol a call emits, method calls included: `recordMethodSym` reads
    /// the receiver's type off inference's per-loc note (`d.hasKey(…)` →
    /// `Dict_hasKey`), which is the path `lowerRecordMethod` itself takes, and
    /// `calleeSymbol` covers the rest. The shape predicates ask *this*, not
    /// `calleeSymbol` alone: without the first half a method's declared return
    /// type was invisible to them, so a method answering a `bool` or an array was
    /// printed through `$__print_i32` — `0`/`1` for a bool, and a **pointer**
    /// (`444` for `["a", "b"]`) for an array.
    fn resolvedCallSym(self: *Emitter, cc: anytype, loc: ast.Loc) ?[]const u8 {
        if (self.recordMethodSym(cc, loc)) |sym| return sym;
        if (self.behaviorMethodShadowsFn(cc, loc)) {
            const impls = self.behaviorImplementers(cc.callee, cc.args.len) catch return null;
            if (impls.len > 0) return std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ impls[0], cc.callee }) catch null;
        }
        if (self.calleeSymbol(cc, loc)) |sym| return sym;
        // A behavior-typed receiver dispatches (`lowerBehaviorDispatch`) to
        // implementers that all answer the method's one declared type, so
        // the first one says what the call answers — a string, a bool, an
        // array's elements.
        if (cc.receiver != null and !cc.is_builtin and self.dispatchesByValue(loc)) {
            const impls = self.behaviorImplementers(cc.callee, cc.args.len) catch return null;
            if (impls.len == 0) return null;
            return std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ impls[0], cc.callee }) catch null;
        }
        return null;
    }

    fn calleeSymbol(self: *Emitter, cc: anytype, loc: ast.Loc) ?[]const u8 {
        if (self.rewrites.get(loc)) |sym| {
            if (self.extMangledName(&self.sym_buf, sym, cc.callee)) |m| return m;
        }
        if (receiverName(cc)) |rn| {
            if (self.ext_by_name.contains(rn)) {
                if (self.extMangledName(&self.sym_buf, rn, cc.callee)) |m| return m;
            }
            if (self.assocSym(cc)) |m| {
                const generic = self.arena().dupe(u8, m) catch return m;
                return (self.specializeFor(generic, cc.args) catch null) orelse
                    (if (self.generic_methods.contains(generic)) (self.specializeMethod(generic, cc) catch null) else null) orelse generic;
            }
        }
        // A local named like a function is the function value it holds.
        if (cc.receiver == null and self.locals.contains(cc.callee)) return null;
        if (self.specializedCallee(cc) catch null) |sym| return sym;
        if (self.fn_sigs.contains(cc.callee)) return cc.callee;
        return null;
    }

    /// A call to an ordinary (non-constructor, non-builtin) function. Arguments
    /// are coerced to the callee's declared parameter types and a short call is
    /// padded with zeros, so the emitted `call` always type-checks.
    ///
    /// A **host-backed `declare fn` that names another target and no `wasm`
    /// one is refused here**, at the call site, with the diagnostic commonJS,
    /// erlang and beam already print (06 C13's `MissingExternal`). It used to
    /// lower to `unreachable` "so the module still loads", which made wasm the
    /// only backend where such a program compiled and then trapped at run time
    /// — a silent divergence decision 67 rules out, and no flag turns it back
    /// on.
    ///
    /// A name nothing in the module, its linked imports, the primitive method
    /// table or a function value resolves is refused where it is written
    /// (`refuseUnlessTemplate`: in a generic body, an `unreachable` the
    /// concrete call that reaches it is refused for), and so is a call of a
    /// bodyless `declare fn` with no `#[@External.<Target>(…)]` at all. Both
    /// used to lower to `unreachable` "so the module still loads".
    fn lowerPlainCall(self: *Emitter, cc: anytype, loc: ast.Loc) anyerror!void {
        // A local shadows a function of its name: `val #(n, push) = …;
        // push(n)` beside std's linked `push` called the function.
        if (cc.receiver == null and cc.calleeExpr == null and self.locals.contains(cc.callee))
            if (try self.lowerValueCall(cc)) return;
        if (cc.receiver == null and scopeCarry.isRun(cc.callee)) return self.lowerRun(cc, false);
        if (cc.receiver == null) _ = try self.adoptPreludeHostFn(cc.callee);
        if (try self.specializedCallee(cc)) |sym| {
            var spec = cc;
            spec.callee = sym;
            return self.lowerPlainCall(spec, loc);
        }
        // A behavior method on a behavior-typed value is the value's, even
        // when a function of the module or its imports shares its name
        // (`r.find(1)` beside std `context`'s `find`, which the scope lowering
        // links): that function took the receiver's place and answered `0`.
        if (self.behaviorMethodShadowsFn(cc, loc)) if (try self.lowerBehaviorDispatch(cc)) return;
        // The ONE body of a generic `fn` holds every type parameter as a word.
        // A float or an `i64` reaching it inside a parameter typed by one
        // (`first(#(1.1, 2))` over `#(A, B)`, `headOf([1.1])` over
        // `Array<T>`) is a cell that body reads as a word: `264` printed for
        // `1.1` at exit 0. No specialisation took it, so it is refused.
        if (self.generic_fns.get(self.import_aliases.get(cc.callee) orelse cc.callee)) |g| {
            var pi: usize = 0;
            for (g.decl.params) |p| {
                if (std.mem.eql(u8, p.name, "self")) continue;
                defer pi += 1;
                if (pi >= cc.args.len) break;
                // A bare `T` passes its argument through untouched (a float
                // one takes a specialised copy); a container OF one is read
                // inside by the body.
                if (p.typeRef == .named or !typeMentionsParam(p.typeRef, g.decl.genericParams)) continue;
                const arg = cc.args[pi].value.*;
                const sh = (try self.printShapeOf(arg)) orelse "";
                if (Cell.of(self.wasmTypeOf(arg)) != .none or std.mem.indexOfAny(u8, sh, "flu") != null)
                    return self.refuse(arg.getLoc(), "the wasm backend has one body for generic `{s}`, where `{s}`'s type parameter is a word: a float or an `i64` in it has no lowering", .{ cc.callee, p.name });
            }
        }
        if (self.host_bindings.get(cc.callee)) |hb| if (hb.binding == .wasi and hb.binding.wasi.task != null) {
            try self.refuseWideTaskValues(cc);
            if (self.mode == .gc and std.mem.eql(u8, hb.binding.wasi.name, "spawn_all")) try self.gcSpawnAllAnswers(cc);
        };
        // 144 B-150 — `e.make()` where `make` is a function-typed field of the
        // receiver's record is the field's value, even when the module also
        // declares a top-level `fn make`: the field is the receiver's own.
        if (cc.receiver) |recv| if (cc.calleeExpr == null and !cc.is_builtin) if (self.recordTypeOfExpr(recv.*)) |rty| {
            if (self.fieldOffsetIn(rty, cc.callee) != null) if (try self.lowerValueCall(cc)) return;
        };
        if (self.fn_sigs.get(cc.callee)) |sig| {
            var base: usize = 0;
            // `recv.m(a)` against a top-level `fn m(self, a)`: the receiver is
            // argument 0.
            if (cc.receiver != null and sig.params.len == cc.args.len + 1) {
                try self.lowerCoerced(cc.receiver.?.*, sig.params[0]);
                base = 1;
            }
            const ptrefs = self.fn_param_typerefs.get(cc.callee);
            for (cc.args, 0..) |arg, i| {
                if (base + i >= sig.params.len) {
                    try self.noteF("extra argument {d} ignored ({s}/{d})", .{ i, cc.callee, sig.params.len });
                    break;
                }
                const ptref: ?ast.TypeRef = if (ptrefs) |ps| (if (base + i < ps.len) ps[base + i] else null) else null;
                if (ptref) |pt| if (plainIdentName(arg.value.*)) |an| if (!self.locals.contains(an)) {
                    if (try self.specializeByFnType(self.import_aliases.get(an) orelse an, pt)) |sym| {
                        try self.lowerFnRef(sym, null);
                        continue;
                    }
                };
                if (ptref) |pt| if (pt == .generic and self.record_generics.contains(pt.generic.name)) {
                    self.expected_ctor = pt;
                };
                defer self.expected_ctor = null;
                // A lambda passed for a function-typed parameter takes its
                // parameter types from the declaration, as one bound to an
                // annotated `val` does: `{ p -> p.nome }` for `fn(Pessoa) ->
                // Pessoa` reads `Pessoa`'s field, `{ s -> "a" + s }` for
                // `fn(string) -> string` concatenates.
                if (ptref) |pt| if (pt == .function and arg.value.* == .function) {
                    self.expected_fn = pt;
                };
                defer self.expected_fn = null;
                if (ptref) |pt| if (isUnionArrayTypeRef(pt) and isArrayLit(arg.value.*)) {
                    self.expected_union_array = true;
                };
                defer self.expected_union_array = false;
                // A lambda written as an argument is written against the
                // parameter's declared function type: `{ n -> n.startsWith(p) }`
                // for `gone: fn(name: string) -> bool` has a string `n`.
                if (ptref) |pt| if (pt == .function and arg.value.* == .function) {
                    self.expected_fn = pt;
                };
                defer self.expected_fn = null;
                // Decision 504 — a value crosses the render scope as its own
                // word (`wat/scope_carry.zig`); a float or an `i64` the call
                // carries (its type argument, the context's or the body's
                // type) crosses as the address of its 8-byte cell, as a
                // function value's does, and its reader's wrapper loads it.
                if (scopeCarry.isWrapper(cc.callee) and self.mode == .linear) {
                    const carries = if (scopeCarry.valueArg(cc.callee)) |va| va == i else false;
                    const cell: Cell = if (!carries) .none else if (cc.typeArgs) |ta|
                        (if (ta.len == 1) cellOfTypeRef(ta[0]) else .none)
                    else
                        .none;
                    if (cell != .none)
                        try self.lowerCellWord(arg.value.*, cell)
                    else if (!self.wasmTypeOf(arg.value.*).isWord())
                        return self.refuse(arg.value.getLoc(), "the wasm backend cannot carry this value through a component's render scope: nothing types it here as a float or an `i64`", .{})
                    else
                        try self.lowerCoerced(arg.value.*, .i32);
                } else if (self.boxesInto(ptref, arg.value.*))
                    try self.lowerBoxedInto(ptref, arg.value.*)
                else
                    try self.lowerCoerced(arg.value.*, sig.params[base + i]);
            }
            var k = base + cc.args.len;
            while (k < sig.params.len) : (k += 1) {
                try self.emitC(constOf(sig.params[k], "0"), "missing argument");
            }
            const callee = self.import_aliases.get(cc.callee) orelse cc.callee;
            if (self.generic_fns.contains(callee)) try self.noteTemplateCall(callee, loc);
            try self.emit(.{ .call = callee });
            return;
        }
        // A method on a behavior-typed value — or on a receiver inference
        // placed nowhere (a lambda parameter typed by an alias naming the
        // behavior) — is answered by the value's own type at run time.
        if (cc.receiver != null and !cc.is_builtin and self.dispatchesByValue(loc)) {
            if (try self.lowerBehaviorDispatch(cc)) return;
        }
        // 144 B-122 — `t.toString()` on a tuple is the text `@print` writes for
        // it (`#(1, 2)`), captured into a string, as a tuple joins a `+`.
        if (self.isTupleToString(cc)) return self.lowerCapturedPrint(cc.receiver.?.*);
        if (try self.lowerCollectionMethod(cc)) return;
        if (try self.lowerValueCall(cc)) return;
        if (cc.receiver == null and self.external_missing.contains(cc.callee)) {
            self.missing_external = .{ .name = cc.callee, .target = "wasm", .loc = loc };
            return error.MissingExternalTarget;
        }
        if (cc.receiver == null and self.host_fns.contains(cc.callee)) {
            return self.refuse(loc, "`{s}` is a bodyless `declare fn` with no implementation: the wasm backend has nothing to call", .{cc.callee});
        }
        // `Ok(v)` / `Err(e)` / `new Error(msg)` outside the `#[@result]`
        // transform build the same `[tag, payload]` pair as `__bp_ok` /
        // `__bp_error` — the lowering beam and erlang give them (`{error, Msg}`).
        // A user enum variant of the same name was matched before this.
        if (cc.receiver == null and cc.args.len == 1 and cc.trailing.len == 0 and self.findVariant(cc.callee) == null) {
            if (self.variantRef(cc.callee)) |ref| switch (ref) {
                .result_ok => return self.lowerResultOptionOp("__bp_ok", cc.args, loc),
                .result_err => return self.lowerResultOptionOp("__bp_error", cc.args, loc),
                .user => {},
            };
        }
        // A method on a behavior no type of the program implements: the value
        // is built by the host (`behavior_host_dispatch`), and the `declare fn`
        // answering that behavior with no wasm cell is what the program lacks.
        if (cc.receiver != null and !cc.is_builtin and self.cur_template == null and (try self.behaviorImplementers(cc.callee, cc.args.len)).len == 0) {
            var best: ?[]const u8 = null;
            var it = self.external_missing.iterator();
            while (it.next()) |e| {
                const rt = e.value_ptr.* orelse continue;
                if (self.records.contains(rt) or self.enums.contains(rt)) continue;
                if (best == null or std.mem.lessThan(u8, e.key_ptr.*, best.?)) best = e.key_ptr.*;
            }
            if (best) |name| {
                self.missing_external = .{ .name = name, .target = "wasm", .loc = loc };
                return error.MissingExternalTarget;
            }
        }
        return self.refuseUnlessTemplate(loc, "the wasm backend cannot resolve the call `{s}/{d}`: no function, method, variant or function value of the module or its imports answers it", .{ cc.callee, cc.args.len });
    }

    /// A free host function of std's prelude that a prelude `default fn`'s
    /// copy calls (`stringSlice0` in `String.parseFloat`): the module declares
    /// none of it, so the first call adopts it — its signature registered, its
    /// `#[@External.Wasm(std: "…")]` cell the binding, its wrapper emitted with
    /// the pending functions. A name the module declares, or a prelude
    /// function with no `std:` cell, is left to the ordinary resolution.
    fn adoptPreludeHostFn(self: *Emitter, name: []const u8) !bool {
        if (self.fn_sigs.contains(name) or self.host_fns.contains(name) or self.generic_fns.contains(name)) return false;
        const f = preludeCache.freeFn(name) orelse return false;
        // Decision 565 — a private body of the prelude a `String` method's
        // `fn:` cell names (and the private fns it calls): adopted whole, its
        // locations `primitives.bp`'s, a refusal inside it reported at the call.
        if (!f.isDeclare and f.body.len > 0 and !f.isPub and !f.isExternal()) {
            try self.registerFn(f);
            try self.spec_pending.append(self.alloc, .{
                .decl = f,
                .rewrites = self.rewrites,
                .lowerings = self.instance_lowerings,
                .renames = self.global_renames,
                .origin = self.foreign_origin orelse self.call_loc,
            });
            return true;
        }
        if (!f.isDeclare or f.body.len > 0) return false;
        const ext = f.externalFor("wasm") orelse return false;
        const parsed = try hostBinding.parse(self.arena(), ext.text, .{ .params = &.{}, .result = null });
        if (parsed != .ok or parsed.ok != .std_) return false;
        try self.host_bindings.put(self.alloc, f.name, .{ .binding = parsed.ok });
        try self.registerFn(f);
        try self.spec_pending.append(self.alloc, .{
            .decl = f,
            .rewrites = self.rewrites,
            .lowerings = self.instance_lowerings,
            .renames = self.global_renames,
        });
        return true;
    }

    // ── primitive instance methods ───────────────────────────────────────────
    //
    // `xs.join(",")`, `s.toUpper()`, `n.abs()`: inference records the
    // receiver's primitive family at the call loc (`instance_lowerings`), and
    // the method lowers to an opcode, a runtime helper from
    // `wat/wat_prelude.zig`, or — for a higher-order method whose argument is a
    // literal lambda — a loop over the array blob with the lambda body inlined
    // (there are no function values to pass). A method with no wasm lowering
    // is refused at the call (`primNotLowered`).

    /// The primitive family of `recv.method(…)`'s receiver, when inference
    /// recorded one.
    /// Whether `e` is a primitive method call that answers an array
    /// (`s.split(c)`, `xs.map(f)`): the family comes from the call's own
    /// receiver, so it holds where the call sits in a lambda whose parameter
    /// inference left unplaced.
    fn arrayAnsweredBy(self: *Emitter, e: ast.Expr) bool {
        const c = switch (e) {
            .call => |c| c,
            else => return false,
        };
        const cc = switch (c.kind) {
            .call => |cc| cc,
            else => return false,
        };
        const k = self.primKindAt(cc, c.loc) orelse return false;
        return (primCallRes(k, cc) orelse return false) == .arr;
    }

    fn primKindAt(self: *Emitter, cc: anytype, loc: ast.Loc) ?envMod.PrimKind {
        if (cc.receiver == null or cc.is_builtin) return null;
        // In a specialisation the substituted type is the answer: inference
        // saw a type variable (`x: T`, `xs: Array<A>`) and recorded nothing,
        // or a dispatch by value where the type is now a primitive.
        if (self.in_spec) if (self.typeRefOf(cc.receiver.?.*)) |tr| {
            const k: ?envMod.PrimKind = switch (tr) {
                .named => |n| primKindOfName(n),
                .array => .array,
                .generic => |g| if (std.mem.eql(u8, g.name, "Array")) .array else null,
                else => null,
            };
            if (k) |kk| return kk;
        };
        const il = self.instance_lowerings.get(loc) orelse {
            // A tuple pattern's binder (`#(n, "x") { n.toString() }`):
            // inference recorded no lowering at its loc, and the binder's
            // declared type — the element's, `noteTupleElemLocal` — says
            // which primitive it is. It was an `unresolved call` trap.
            //
            // A method call answering a primitive inside an adopted
            // behavior `default fn` (`self.twice().toString()` in `Sq`'s
            // copy of `Shape.label`): inference typed the body against
            // `Self`, so the call's result was a type variable and no
            // lowering was recorded. The callee's declared return —
            // `Sq_twice -> i32` — is the primitive, when it has the method.
            // It trapped in `Sq_label` (`unresolved call: toString/0`).
            const recv = cc.receiver.?.*;
            if (recv == .call) {
                // A chain whose first link answers an array by its own
                // primitive family (`acc.split(c).join("")` in a lambda
                // whose accumulator inference left a type variable): the
                // link's answer is the next link's receiver.
                if (self.arrayAnsweredBy(recv)) return if (primCallRes(.array, cc) != null) .array else null;
                const tr = self.typeRefOf(recv) orelse return null;
                const k = switch (tr) {
                    .named => |tn| primKindOfName(tn) orelse return null,
                    // A method answering `Array<T>` / `T[]` (`kit.of(xs)
                    // .toArray()` through a namespace member, which inference
                    // records no lowering for): the array's methods.
                    .array => envMod.PrimKind.array,
                    .generic => |g| if (std.mem.eql(u8, g.name, "Array")) envMod.PrimKind.array else return null,
                    else => return null,
                };
                return if (primCallRes(k, cc) != null) k else null;
            }
            const n = plainIdentName(recv) orelse return null;
            // A lambda parameter inference left a type variable (`acc` of
            // `fold`) that the inlined walk bound to a string: its methods are
            // the string's.
            // A local bound to an array in a body inference saw apart from
            // this module — std's `Array.range` copy, `low.append(high)` —
            // has the array's methods.
            if (!self.tuple_binders.contains(n) and self.arr_locals.contains(self.resolveName(n)) and primCallRes(.array, cc) != null) return .array;
            if (!self.tuple_binders.contains(n)) {
                if (self.str_locals.contains(self.resolveName(n)) and primCallRes(.string, cc) != null) return .string;
                // A lambda parameter its declared function type types
                // (`Lifted.param_tref`), or a closure parameter bound to a
                // `@Result`'s payload (`lowerResultOptionOp`).
                if (self.local_typerefs.get(n)) |tr| if (tr == .named) if (primKindOfName(tr.named)) |k| if (primCallRes(k, cc) != null) return k;
                return null;
            }
            const tr = self.local_typerefs.get(n) orelse return null;
            return switch (tr) {
                .named => |tn| primKindOfName(tn),
                else => null,
            };
        };
        return switch (il) {
            .prim => |k| k,
            .type_, .field_of, .sequence_next, .division, .by_value, .unplaced_type, .assoc_fn_value, .task_await, .task_return, .failing_task_block, .union_value, .text_value => null,
        };
    }

    // ── a method on the rest of a `?.` chain ─────────────────────────────────
    //
    // `es.at(1)?.key.length().toString()`: the `?.` makes EVERYTHING after it
    // conditional — absent short-circuits the whole chain — but only the link
    // written with `?.` carried the guard. The next method started from a
    // carrier that may be `0` and read it as a string (`length` loaded a
    // length from address 0, the WASI iovec, at exit 0) or found no receiver
    // type at all (`unresolved call: toString/0`, a trap). A primitive method
    // written with `?.` (`s?.length()` read a length off address 0 for an
    // absent `s`), or whose receiver is such a chain, is lowered under the
    // guard: absent
    // stays `0`, present unboxes the receiver, runs the method on it, and
    // boxes a scalar result — so the whole expression is the `?T` the checker
    // typed it as, and prints `null` or its value.

    /// Whether `e` is, or continues, a `?.` chain.
    fn isOptionalChain(e: ast.Expr) bool {
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .identAccess => |ia| ia.optional or isOptionalChain(ia.receiver.*),
                else => false,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| cc.optional or (if (cc.receiver) |r| isOptionalChain(r.*) else false),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| isOptionalChain(inner.*),
                else => false,
            },
            else => false,
        };
    }

    /// The primitive family of the PAYLOAD of an optional-chain receiver:
    /// what inference recorded for it, what the previous guarded link answers,
    /// or a string field read through `?.`.
    fn chainPayloadKind(self: *Emitter, recv: ast.Expr) ?envMod.PrimKind {
        switch (recv) {
            .call => |c| switch (c.kind) {
                .call => |inner| if (self.chainedCallKind(inner, c.loc)) |k| {
                    return switch (primCallRes(k, inner) orelse return null) {
                        .i32 => .int,
                        .bool_ => .bool,
                        .str => .string,
                        .arr => .array,
                        .f64, .i64, .none => null,
                    };
                },
                else => {},
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.chainPayloadKind(inner.*),
                else => {},
            },
            // `x?.n` — a field read through the chain: its declared type. A
            // float field has no chained lowering here, so it is left to the
            // unguarded path.
            .identifier => |id| switch (id.kind) {
                .identAccess => |ia| if (self.recordTypeOfExpr(ia.receiver.*)) |rty| {
                    if (self.fieldTypeIn(rty, ia.member)) |ft| {
                        if (self.typeRefOf(recv)) |tr| if (arrayElemOfTypeRef(tr) != null) return .array;
                        if (std.mem.eql(u8, ft, "string")) return .string;
                        if (std.mem.eql(u8, ft, "bool")) return .bool;
                        for ([_][]const u8{ "i32", "i64", "u32", "u64", "int" }) |n| {
                            if (std.mem.eql(u8, ft, n)) return .int;
                        }
                        return null;
                    }
                },
                else => {},
            },
            else => {},
        }
        if (self.isStringExpr(recv)) return .string;
        // A field written as an array (`m?.list`, `list: string[]`): the
        // payload is an array, whose element the type spells.
        if (self.typeRefOf(recv)) |tr| if (arrayElemOfTypeRef(tr) != null) return .array;
        return null;
    }

    /// The family `cc`'s receiver has once the chain is present — for a call
    /// written with `?.` (`s?.length()`, its receiver the optional itself)
    /// and for one that continues a `?.` chain.
    fn chainedCallKind(self: *Emitter, cc: anytype, loc: ast.Loc) ?envMod.PrimKind {
        if (cc.is_builtin) return null;
        const recv = cc.receiver orelse return null;
        if (cc.optional) {
            if (self.primKindAt(cc, loc)) |k| return k;
            // A receiver inference recorded no lowering for (`find(k)?.length()`,
            // `xs.at(i)?.slice(1, 3)`): the family of its optional's payload.
            const k: envMod.PrimKind = if (self.typeRefOf(recv.*)) |tr| switch (tr) {
                .optional => |inner| switch (inner.*) {
                    .named => |n| primKindOfName(n) orelse return null,
                    .array => .array,
                    .generic => |g| if (std.mem.eql(u8, g.name, "Array")) .array else return null,
                    else => return null,
                },
                else => return null,
            } else if (self.optInfoOf(recv.*)) |oi|
                (if (oi.str) .string else return null)
            else
                return null;
            return if (primCallRes(k, cc) != null) k else null;
        }
        if (!isOptionalChain(recv.*)) return null;
        if (self.primKindAt(cc, loc)) |k| return k;
        return self.chainPayloadKind(recv.*);
    }

    /// What a guarded chain link leaves: a boxed scalar or a pointer (`0` is
    /// absence either way). Null when the link is not one this lowers — a
    /// float result has no box here.
    fn chainedCallOpt(self: *Emitter, cc: anytype, loc: ast.Loc) ?OptInfo {
        const k = self.chainedCallKind(cc, loc) orelse return null;
        return switch (primCallRes(k, cc) orelse return null) {
            .i32 => .{ .boxed = true },
            .bool_ => .{ .boxed = true, .bool_ = true },
            .str => .{ .boxed = false, .str = true },
            .arr => .{ .boxed = false },
            .f64, .i64, .none => null,
        };
    }

    fn lowerChainedCall(self: *Emitter, cc: anytype, loc: ast.Loc) anyerror!bool {
        const res = self.chainedCallOpt(cc, loc) orelse return false;
        const k = self.chainedCallKind(cc, loc).?;
        const recv = cc.receiver.?.*;
        const recv_boxed = if (self.optInfoOf(recv)) |oi| oi.boxed else false;
        const mem = try self.memName(self.nextMem());
        try self.lowerValue(recv);
        try self.emit(.{ .local_tee = mem });
        try self.emit(opOf(.i32, "eqz"));

        var then_c: Capture = .{};
        self.open(&then_c);
        try self.emitC(zero, "?. chain: absent");
        const then_seq = self.seal(&then_c, .{ .value = .i32 });

        var else_c: Capture = .{};
        self.open(&else_c);
        // A `?f64` / `?i64` holds its 8-byte cell: the payload is read in its
        // own type, into a local of that type (read as an `i32` it answered `0.0`).
        var pname = mem;
        const rcell: Cell = if (self.optInfoOf(recv)) |oi| oi.cell else .none;
        if (recv_boxed and rcell != .none) {
            pname = try std.fmt.allocPrint(self.arena(), "__optc{d}", .{self.loop_seq});
            self.loop_seq += 1;
            try self.declareLocal(pname, if (rcell == .f64) .f64 else .i64);
            try self.local_typerefs.put(pname, .{ .named = if (rcell == .f64) "f64" else "i64" });
            try self.emit(.{ .local_get = mem });
            try self.emitUnboxPayload(self.optInfoOf(recv).?, "?. chain: unbox cell");
            try self.emit(.{ .local_set = pname });
        } else if (recv_boxed) {
            try self.emit(.{ .local_get = mem });
            try self.emitC(.{ .load = .{} }, "?. chain: unbox");
            try self.emit(.{ .local_set = mem });
        }
        if (k == .string) try self.str_locals.put(mem, {});
        // An array payload: its element shape is the optional's type's.
        if (k == .array) if (self.typeRefOf(recv)) |tr| if (arrayElemOfTypeRef(tr)) |ek| {
            try self.arr_locals.put(pname, {});
            try self.arr_elem_locals.put(pname, ek);
        };
        const payload = try self.arena().create(ast.Expr);
        payload.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = pname } } };
        var link = cc;
        link.receiver = payload;
        link.optional = false;
        try self.lowerPrimMethod(k, link);
        if (res.boxed) try self.emit(self.builder().helper(.box_i32));
        const else_seq = self.seal(&else_c, .{ .value = .i32 });

        try self.emit(.{ .@"if" = .{
            .result = .i32,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
        return true;
    }

    /// `recv?.m(args)` over a method of a record or an enum the program
    /// declares (decision 330): the optional receiver is evaluated once, the
    /// method runs only on a present one, and its answer is the `?R` the
    /// checker typed the call as. Unguarded, an absent receiver reached the
    /// method as address `0` — an enum's dispatcher trapped, a record's method
    /// read its fields off address 0 — and an unboxed `0` answered by a
    /// present one read as absent (`p?.twice() ?? -1` printed `-1`).
    const OptTypedMethod = struct {
        payload: ast.TypeRef,
        ret: ast.TypeRef,
        word: Repr,
        /// `<Owner>_<method>`, called on the payload directly: the owner is
        /// the optional's payload type, so nothing dispatches by value (an
        /// all-unit enum's values carry no header to dispatch on).
        direct: ?[]const u8,
    };

    fn optionalTypedMethod(self: *Emitter, cc: anytype, loc: ast.Loc) ?OptTypedMethod {
        if (!cc.optional or cc.is_builtin) return null;
        const recv = cc.receiver orelse return null;
        const rtr = self.typeRefOf(recv.*) orelse return null;
        if (rtr != .optional or rtr.optional.* != .named) return null;
        const owner = rtr.optional.named;
        if (!self.records.contains(owner) and !self.enums.contains(owner)) return null;
        const own = std.fmt.allocPrint(self.arena(), "{s}_{s}", .{ owner, cc.callee }) catch return null;
        const direct: ?[]const u8 = if (self.fn_sigs.get(own)) |sig|
            (if (!self.generic_methods.contains(own) and sig.params.len == cc.args.len + 1) own else null)
        else
            null;
        const sym = direct orelse self.resolvedCallSym(cc, loc) orelse return null;
        const ret = self.fn_ret_typerefs.get(sym) orelse return null;
        const sig = self.fn_sigs.get(sym) orelse return null;
        return .{ .payload = rtr.optional.*, .ret = ret, .word = sig.result orelse .i32, .direct = direct };
    }

    /// The carrier `optionalTypedMethod`'s call answers: the method's own
    /// optional when it answers one (`?.` flattens), else a `?R` of its answer.
    fn optionalTypedMethodOpt(self: *Emitter, cc: anytype, loc: ast.Loc) ?OptInfo {
        const m = self.optionalTypedMethod(cc, loc) orelse return null;
        if (m.ret == .optional) return self.optInfoOfTypeRef(m.ret);
        const inner = self.arena().create(ast.TypeRef) catch return null;
        inner.* = m.ret;
        return self.optInfoOfTypeRef(.{ .optional = inner });
    }

    fn lowerOptionalTypedMethod(self: *Emitter, c: anytype) anyerror!bool {
        const cc = c.kind.call;
        const res = self.optionalTypedMethodOpt(cc, c.loc) orelse return false;
        const m = self.optionalTypedMethod(cc, c.loc).?;
        const recv = cc.receiver.?.*;
        const recv_boxed = if (self.optInfoOf(recv)) |oi| oi.boxed else false;
        const mem = try self.memName(self.nextMem());
        try self.lowerValue(recv);
        try self.emit(.{ .local_tee = mem });
        try self.emit(opOf(.i32, "eqz"));

        var then_c: Capture = .{};
        self.open(&then_c);
        try self.emitC(zero, "?. method: absent");
        const then_seq = self.seal(&then_c, .{ .value = .i32 });

        var else_c: Capture = .{};
        self.open(&else_c);
        if (recv_boxed) {
            try self.emit(.{ .local_get = mem });
            try self.emitC(.{ .load = .{} }, "?. method: unbox");
            try self.emit(.{ .local_set = mem });
        }
        try self.local_typerefs.put(mem, m.payload);
        const payload = try self.arena().create(ast.Expr);
        payload.* = .{ .identifier = .{ .loc = c.loc, .kind = .{ .ident = mem } } };
        var link = cc;
        link.receiver = payload;
        link.optional = false;
        var call = c;
        call.kind = .{ .call = link };
        // The method's own answer, as its signature leaves it: the payload
        // receiver is dispatched as the optional one was (`resolvedCallSym`).
        if (m.direct) |sym| {
            try self.emit(.{ .local_get = mem });
            try self.lowerCallArgs(cc.args, self.fn_sigs.get(sym).?, 1);
            try self.emit(.{ .call = sym });
        } else try self.lowerValue(.{ .call = call });
        if (m.ret == .optional) {
            try self.emitConvert(m.word, .i32);
        } else if (res.cell != .none) {
            try self.emitConvert(m.word, res.cell.ty());
            try self.emit(self.builder().helper(switch (res.cell) {
                .f64 => .box_f64,
                .i64 => .box_i64,
                .none => unreachable,
            }));
        } else {
            try self.emitConvert(m.word, .i32);
            if (res.boxed) try self.emit(self.builder().helper(.box_i32));
        }
        const else_seq = self.seal(&else_c, .{ .value = .i32 });

        try self.emit(.{ .@"if" = .{
            .result = .i32,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
        return true;
    }

    /// What a primitive method leaves on the stack. Null: no wasm lowering.
    /// `i64` is `bigint.toI64()`'s (decision 332).
    const PrimRes = enum { i32, i64, f64, bool_, str, arr, none };

    /// The primitive kinds a behavior of `primitives.bp` covers — the ones a
    /// program's own `behavior <Name>` extends (01-checker). Arrays are not
    /// here as `.array`: its defaults' `Self<T>` is the receiver's written
    /// array type in the copy (`primDefaultSelf`).
    fn primBehaviorKinds(name: []const u8) []const envMod.PrimKind {
        const eq = std.mem.eql;
        if (eq(u8, name, "String")) return &.{.string};
        if (eq(u8, name, "Bool")) return &.{.bool};
        if (eq(u8, name, "Number")) return &.{ .int, .float };
        for ([_][]const u8{ "Integer", "Signed", "I32", "I64", "U32", "U64" }) |n| if (eq(u8, name, n)) return &.{.int};
        for ([_][]const u8{ "Float", "F32", "F64" }) |n| if (eq(u8, name, n)) return &.{.float};
        if (eq(u8, name, "Array")) return &.{.array};
        return &.{};
    }

    fn primDefaultOf(self: *Emitter, k: envMod.PrimKind, name: []const u8) ?PrimDefault {
        var buf: [256]u8 = undefined;
        const key = std.fmt.bufPrint(&buf, "{s}.{s}", .{ @tagName(k), name }) catch return null;
        return self.prim_defaults.get(key);
    }

    /// The type `Self` is in a primitive default's copy for kind `k`.
    fn primSelfType(k: envMod.PrimKind) []const u8 {
        return switch (k) {
            .string => "string",
            .bool => "bool",
            .int => "i32",
            .float => "f64",
            .array => "i32",
            .bigint => "bigint",
            .bytes => "Bytes",
        };
    }

    /// `primCallRes`, and what a program's own primitive `default fn`
    /// answers by its declared return (`Self` the receiver's kind).
    fn primRes(self: *Emitter, k: envMod.PrimKind, cc: anytype) ?PrimRes {
        if (primCallRes(k, cc)) |r| return r;
        // Decision 565 — a program's `String` method bound by `fn:` answers
        // what its body declares.
        if (k == .string) if (self.string_fn_cells.get(cc.callee)) |sym| {
            const rt = (self.fn_ret_typerefs.get(sym) orelse return .none);
            return switch (rt) {
                .named => |n| if (std.mem.eql(u8, n, "string")) .str else if (std.mem.eql(u8, n, "bool")) .bool_ else if (isFloatTypeName(n)) .f64 else .i32,
                .array, .generic => .arr,
                .optional => |o| if (o.* == .named and std.mem.eql(u8, o.named, "string")) .str else .i32,
                else => .i32,
            };
        };
        const pd = self.primDefaultOf(k, cc.callee) orelse return null;
        if (pd.method.params.len != cc.args.len + 1) return null;
        if (k == .array) {
            // The copy's declared return, `Self<T>` and `T` written in.
            const sym = (self.ensurePrimDefault(k, pd, cc.receiver.?.*) catch return null);
            const rt = self.fn_ret_typerefs.get(sym) orelse return .none;
            return switch (rt) {
                .array, .generic => .arr,
                .named => |n| if (std.mem.eql(u8, n, "string")) .str else if (std.mem.eql(u8, n, "bool")) .bool_ else if (isFloatTypeName(n)) .f64 else .i32,
                else => .i32,
            };
        }
        const rt = pd.method.returnType orelse return .none;
        const n = switch (rt) {
            .named => |n| n,
            .array, .generic => return .arr,
            else => return .i32,
        };
        const t = if (std.mem.eql(u8, n, "Self")) primSelfType(k) else n;
        if (std.mem.eql(u8, t, "string")) return .str;
        if (std.mem.eql(u8, t, "bool")) return .bool_;
        if (isFloatTypeName(t)) return .f64;
        return .i32;
    }

    /// Decision 565 — a `String` method of the program's own `behavior String`
    /// whose wasm cell is `fn: <name>`: `<name>` is a private bodied fn of the
    /// program taking the receiver first, then the method's parameters, and
    /// answering its type (`hostFnBinding.resolve`, refused at the annotation
    /// otherwise). `primitives.bp`'s own members, which a materialised prelude
    /// may bring along, are the prelude's (`stringFnCellOf`).
    fn registerStringFnCell(self: *Emitter, m: ast.BehaviorMethod, name: []const u8, program: ast.Program) !void {
        if (preludeStringFnCell(m.name)) |pn| if (std.mem.eql(u8, pn, name)) return;
        const ra = self.reg_arena.allocator();
        const as_fn = try stringMethodAsFn(ra, m);
        switch (try hostFnBinding.resolve(ra, as_fn, name, program, "", "Wasm")) {
            .refused => |message| return self.refuse(hostFnBinding.annotationLoc(as_fn, "Wasm"), "{s}", .{message}),
            .ok => {},
        }
        try self.string_fn_cells.put(ra, m.name, name);
    }

    /// The body symbol a `String.<method>` call lowers to on wasm (decision
    /// 565): the program's own binding, else `primitives.bp`'s — its private
    /// body adopted from the prelude (`adoptPreludeHostFn`). Null when the
    /// method's wasm cell is no `fn:` (a `std:` cell, `lowerStringMethod`).
    fn stringFnCellOf(self: *Emitter, method: []const u8) !?[]const u8 {
        if (self.string_fn_cells.get(method)) |sym| return sym;
        const m = preludeStringMethod(method) orelse return null;
        const name = methodFnCell(m) orelse return null;
        if (self.fn_sigs.contains(name)) return name;
        const ra = self.reg_arena.allocator();
        switch (try hostFnBinding.resolve(ra, try stringMethodAsFn(ra, m), name, preludeCache.primitives().?, "", "Wasm")) {
            .refused => |message| return self.refuse(self.call_loc, "{s} (in `primitives.bp`)", .{message}),
            .ok => {},
        }
        _ = try self.adoptPreludeHostFn(name);
        return name;
    }

    /// `s.<method>(…)` whose wasm cell is `fn: <body>` (decision 565): a call
    /// of the body, the receiver its first argument. Where `primitives.bp`'s
    /// method also has a std-wasm row, the body's answer is coerced to what
    /// that row leaves (a `?string` is the `$str` reference `text.at` left), so
    /// the call site reads the same value either way.
    fn lowerStringFnCell(self: *Emitter, sym: []const u8, cc: anytype) anyerror!void {
        const sig = self.fn_sigs.get(sym).?;
        try self.lowerCoerced(cc.receiver.?.*, sig.params[0]);
        try self.lowerCallArgs(cc.args, sig, 1);
        try self.emit(.{ .call = sym });
        const res = sig.result orelse return;
        if (self.mode != .gc) return;
        const export_name = stdMethodExport("String", cc.callee) orelse return;
        if (stdLeaves.find(export_name) != null) return;
        const ex = gcStdSig(export_name) orelse return;
        try self.emitConvert(res, try stdRepr(ex.result));
    }

    /// `"a+b".tailShout()` over a program's `behavior String { default fn
    /// tailShout(self: Self) … }`: a copy of the default with `Self` written
    /// as the receiver's primitive (`String_tailShout__string`), emitted once
    /// like a specialisation, called with the receiver as `self`. It trapped
    /// (`prim method not lowered on wasm`) — every program-declared default
    /// of a primitive did.
    fn lowerPrimDefault(self: *Emitter, k: envMod.PrimKind, pd: PrimDefault, cc: anytype) anyerror!void {
        const sym = try self.ensurePrimDefault(k, pd, cc.receiver.?.*);
        const sig = self.fn_sigs.get(sym).?;
        try self.lowerCoerced(cc.receiver.?.*, sig.params[0]);
        try self.lowerCallArgs(cc.args, sig, 1);
        try self.emit(.{ .call = sym });
    }

    /// The element type an `Array<T>` default's copy writes for `T`: the
    /// receiver's record, a bool by its shape, else its element kind.
    fn primArrayElemName(self: *Emitter, recv: ast.Expr) []const u8 {
        if (self.elemRecordOf(recv)) |r| return r;
        if (self.elemIsBool(recv) catch false) return "bool";
        return switch (self.elemKindOf(recv)) {
            .str => "string",
            .f64 => "f64",
            .i32 => "i32",
        };
    }

    /// The copy of a program's primitive default for a receiver of kind `k`,
    /// registered (its signature, its declared return) and queued once;
    /// its symbol.
    fn ensurePrimDefault(self: *Emitter, k: envMod.PrimKind, pd: PrimDefault, recv: ast.Expr) ![]const u8 {
        const ar = self.reg_arena.allocator();
        const elem: []const u8 = if (k == .array) self.primArrayElemName(recv) else "";
        const st = if (k == .array) try std.fmt.allocPrint(ar, "arr_{s}", .{elem}) else primSelfType(k);
        const mname = try std.fmt.allocPrint(ar, "{s}__{s}", .{ pd.method.name, st });
        const sym = try std.fmt.allocPrint(ar, "{s}_{s}", .{ pd.behavior, mname });
        if (!self.spec_names.contains(sym)) {
            try self.spec_names.put(self.alloc, sym, {});
            var subs_l: std.ArrayListUnmanaged(TypeSub) = .empty;
            if (k == .array) {
                const inner = try ar.create(ast.TypeRef);
                inner.* = .{ .named = elem };
                try subs_l.append(ar, .{ .name = "Self", .to = .{ .array = inner } });
                for (pd.tparams) |gp| try subs_l.append(ar, .{ .name = gp.name, .to = .{ .named = elem } });
            } else try subs_l.append(ar, .{ .name = "Self", .to = .{ .named = st } });
            const subs = subs_l.items;
            var m = try substTypeParams(ast.BehaviorMethod, ar, pd.method, subs);
            m.name = mname;
            // A method of the behavior, `self` its first parameter — the
            // member emission path (`emitMemberFn`) keeps it.
            try self.registerInterfaceSigs(pd.behavior, &.{}, &.{m});
            try self.mspec_pending.append(self.alloc, .{
                .owner = pd.behavior,
                .tparams = &.{},
                .method = m,
                .rewrites = self.rewrites,
                .lowerings = self.instance_lowerings,
                .renames = self.global_renames,
                // A prelude default's locations are `primitives.bp`'s: a
                // refusal inside its copy is reported at the call reaching it.
                .origin = self.foreign_origin orelse if (pd.method.from_prelude) self.call_loc else null,
            });
        }
        return sym;
    }

    fn primCallRes(k: envMod.PrimKind, cc: anytype) ?PrimRes {
        const name: []const u8 = cc.callee;
        const argc = cc.args.len + cc.trailing.len;
        const Row = struct { []const u8, usize, PrimRes };
        const rows: []const Row = switch (k) {
            .array => &.{
                .{ "length", 0, .i32 },     .{ "at", 1, .i32 },        .{ "first", 0, .i32 },
                .{ "find", 1, .i32 },       .{ "join", 1, .str },      .{ "indexOf", 1, .i32 },
                .{ "contains", 1, .bool_ }, .{ "isEmpty", 0, .bool_ }, .{ "reverse", 0, .arr },
                .{ "prepend", 1, .arr },    .{ "append", 1, .arr },    .{ "push", 1, .none },
                .{ "zip", 1, .arr },        .{ "slice", 1, .arr },     .{ "slice", 2, .arr },
                .{ "rest", 0, .arr },       .{ "take", 1, .arr },      .{ "drop", 1, .arr },
                .{ "toList", 0, .arr },     .{ "map", 1, .arr },       .{ "filter", 1, .arr },
                .{ "forEach", 1, .none },   .{ "all", 1, .bool_ },     .{ "every", 1, .bool_ },
                .{ "any", 1, .bool_ },      .{ "some", 1, .bool_ },    .{ "count", 1, .i32 },
                .{ "findIndex", 1, .i32 },  .{ "fold", 2, .i32 },      .{ "lastIndexOf", 1, .i32 },
                .{ "pop", 0, .i32 },        .{ "unique", 0, .arr },    .{ "flatten", 0, .arr },
                .{ "flat", 0, .arr },       .{ "flatMap", 1, .arr },   .{ "chunked", 1, .arr },
                .{ "sliding", 1, .arr },    .{ "fill", 1, .arr },
            },
            .string => &.{
                .{ "length", 0, .i32 },     .{ "toUpper", 0, .str },      .{ "toLower", 0, .str },
                .{ "contains", 1, .bool_ }, .{ "startsWith", 1, .bool_ }, .{ "endsWith", 1, .bool_ },
                .{ "indexOf", 1, .i32 },    .{ "trim", 0, .str },         .{ "trimStart", 0, .str },
                .{ "trimEnd", 0, .str },    .{ "split", 1, .arr },        .{ "slice", 1, .str },
                .{ "slice", 2, .str },      .{ "repeat", 1, .str },       .{ "toString", 0, .str },
                // `Index<i32, string>.at` (decision 63's amendment) — a
                // `?string`, absent as the pointer 0. `.str` is its stack
                // shape; `optInfoOf` is what routes the print through
                // `$__print_opt_str`, and std-wasm's `text.at` is the lowering.
                .{ "at", 1, .str },
                // `00 · 05-wasm` step 6's audit: the rest of `primitives.bp`'s
                // `String` that has a byte-level answer.
                        .{ "charCodeAt", 1, .i32 },   .{ "lastIndexOf", 1, .i32 },
                .{ "padStart", 2, .str },   .{ "padEnd", 2, .str },       .{ "replace", 2, .str },
                .{ "replaceAll", 2, .str }, .{ "chars", 0, .arr },        .{ "lines", 0, .arr },
                .{ "words", 0, .arr },
            },
            .bool => &.{
                .{ "negate", 0, .bool_ },      .{ "nor", 1, .bool_ },          .{ "nand", 1, .bool_ },
                .{ "exclusiveOr", 1, .bool_ }, .{ "exclusiveNor", 1, .bool_ }, .{ "toString", 0, .str },
            },
            .int => &.{
                .{ "abs", 0, .i32 },      .{ "min", 1, .i32 },      .{ "max", 1, .i32 },
                .{ "clamp", 2, .i32 },    .{ "isEven", 0, .bool_ }, .{ "isOdd", 0, .bool_ },
                .{ "toString", 0, .str },
                // Decision 319's conversions (`lowerIntConversion`); a `u32`
                // lives in an `i64`.
                .{ "toI32", 0, .i32 },    .{ "toI64", 0, .i64 },
                .{ "toU32", 0, .i64 },    .{ "toU64", 0, .i64 },    .{ "toF64", 0, .f64 },
            },
            .float => &.{
                .{ "abs", 0, .f64 },   .{ "min", 1, .f64 },        .{ "max", 1, .f64 },
                .{ "clamp", 2, .f64 }, .{ "floor", 0, .f64 },      .{ "ceil", 0, .f64 },
                .{ "round", 0, .f64 }, .{ "squareRoot", 0, .f64 }, .{ "toString", 0, .str },
            },
            // Decision 332 — through the `bigint` group.
            .bigint => &.{ .{ "toString", 0, .str }, .{ "toI64", 0, .i64 }, .{ "toF64", 0, .f64 } },
            // Decision 346 — a `Bytes` is laid out as a string is, and is no
            // string: its results are addresses (`.i32`), never `.str`, which
            // would print it as text.
            .bytes => &.{
                .{ "length", 0, .i32 }, .{ "toUtf8", 0, .i32 }, .{ "concat", 1, .i32 },
                .{ "slice", 1, .i32 },  .{ "slice", 2, .i32 },
            },
        };
        for (rows) |r| {
            if (r[1] == argc and std.mem.eql(u8, r[0], name)) return r[2];
        }
        return null;
    }

    /// The `i`-th argument of a call, counting trailing lambdas after the
    /// parenthesised ones.
    fn callArg(cc: anytype, i: usize) ?ast.Expr {
        if (i < cc.args.len) return cc.args[i].value.*;
        return null;
    }

    /// A lambda written at argument `i` — `xs.map({ x -> … })` or the trailing
    /// form `xs.map { x -> … }`.
    const LambdaView = struct { params: []const []const u8, body: []const ast.Stmt };

    fn lambdaAt(cc: anytype, i: usize) ?LambdaView {
        if (i < cc.args.len) {
            const a = cc.args[i].value;
            if (a.* != .function) return null;
            return .{ .params = a.function.kind.params, .body = a.function.kind.body };
        }
        const t = i - cc.args.len;
        if (t < cc.trailing.len) return .{ .params = cc.trailing[t].params, .body = cc.trailing[t].body };
        return null;
    }

    /// `lambdaAt`, and a FUNCTION NAMED as the argument (`xs.map(inc)`, a
    /// local or an imported fn, or a local holding a function value): the
    /// lambda `{ p0, … -> name(p0, …) }` with the `arity` parameters the
    /// method hands it, inlined like any other. It trapped — `map needs a
    /// literal lambda`.
    fn hofLambdaAt(self: *Emitter, cc: anytype, i: usize, arity: usize) !?LambdaView {
        if (lambdaAt(cc, i)) |l| return l;
        if (i >= cc.args.len) return null;
        const a = cc.args[i].value.*;
        const name = switch (a) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| n,
                else => return null,
            },
            else => return null,
        };
        const ar = self.arena();
        const params = try ar.alloc([]const u8, arity);
        const args = try ar.alloc(ast.CallArg, arity);
        for (params, args, 0..) |*p, *arg, k| {
            p.* = try std.fmt.allocPrint(ar, "__hof{d}_{d}", .{ self.loop_seq, k });
            const v = try ar.create(ast.Expr);
            v.* = .{ .identifier = .{ .loc = a.identifier.loc, .kind = .{ .ident = p.* } } };
            arg.* = .{ .label = null, .value = v };
        }
        self.loop_seq += 1;
        const body = try ar.alloc(ast.Stmt, 1);
        body[0] = .{ .expr = .{ .call = .{ .loc = a.identifier.loc, .kind = .{ .call = .{
            .receiver = null,
            .callee = name,
            .is_builtin = false,
            .args = args,
            .trailing = &.{},
        } } } } };
        return .{ .params = params, .body = body };
    }

    /// std-wasm's `array.unique`'s equality for the elements of `recv`: `0` the slot's
    /// word (an integer, a bool, an all-unit enum's ordinal), `1` its cell's `f64`,
    /// `2` a string's content. Null for an element whose `!=` this backend
    /// has no lowering for — a record, an array, a tuple —, which is refused.
    fn uniqueMode(self: *Emitter, recv: ast.Expr) anyerror!?i32 {
        if (self.elemRecordOf(recv) != null) return null;
        if (try self.printShapeOf(recv)) |sh| {
            if (sh.len < 2 or sh[0] != '[') return null;
            return switch (sh[1]) {
                'i', 'b', 'E' => 0,
                'f' => 1,
                's' => 2,
                else => null,
            };
        }
        return switch (self.elemKindOf(recv)) {
            .i32 => 0,
            .f64 => 1,
            .str => 2,
        };
    }

    /// The print shape of what a HOF lambda's body answers, asked with its
    /// element parameter bound (as `elemKindOf`'s `map` arm asks).
    fn lambdaTailShape(self: *Emitter, lam: LambdaView, recv: ast.Expr) anyerror!?[]const u8 {
        if (lam.body.len == 0) return null;
        const last = lam.body[ast.lastRealIndex(lam.body)].expr;
        const v = switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |x| x.* else return null,
                else => return null,
            },
            else => last,
        };
        const held = self.holdElemParam(lam, recv);
        defer self.releaseElemParam(held);
        return self.printShapeOf(v);
    }

    fn lambdaTailIsBool(self: *Emitter, lam: LambdaView, recv: ast.Expr) bool {
        if (lam.body.len == 0) return false;
        const last = lam.body[ast.lastRealIndex(lam.body)].expr;
        const v = switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |x| x.* else return false,
                else => return false,
            },
            else => last,
        };
        const held = self.holdElemParam(lam, recv);
        defer self.releaseElemParam(held);
        return self.isBoolExpr(v);
    }

    /// The print shape of the arrays `05-wasm` step 1's methods build, read
    /// off their receiver: `unique` keeps it, `flatten`/`flat` drop one `[`,
    /// `flatMap` is its function's array, `chunked`/`sliding` add one, `fill`
    /// is an array of its value. Null for any other call.
    fn newArrShape(self: *Emitter, cc: anytype, loc: ast.Loc) anyerror!?[]const u8 {
        const k = self.primKindAt(cc, loc) orelse return null;
        if (k != .array or cc.receiver == null) return null;
        const recv = cc.receiver.?.*;
        const eq = std.mem.eql;
        const name: []const u8 = cc.callee;
        if (primCallRes(k, cc) == null) return null;
        // `xs.map(f)` answering a bool or a container: an array of it. A bool
        // printed `1`, a nested array its rows' addresses.
        if (eq(u8, name, "map")) {
            const lam = lambdaAt(cc, 0) orelse return null;
            if (try self.lambdaTailShape(lam, recv)) |sh| return try std.fmt.allocPrint(self.arena(), "[{s}", .{sh});
            if (self.lambdaTailIsBool(lam, recv)) return "[b";
            return null;
        }
        if (eq(u8, name, "unique")) return self.printShapeOf(recv);
        if (eq(u8, name, "flatten") or eq(u8, name, "flat")) {
            const sh = (try self.printShapeOf(recv)) orelse return null;
            return if (sh.len >= 2 and sh[0] == '[' and sh[1] == '[') sh[1..] else null;
        }
        if (eq(u8, name, "flatMap")) {
            const lam = lambdaAt(cc, 0) orelse return null;
            const sh = (try self.lambdaTailShape(lam, recv)) orelse return null;
            return if (sh[0] == '[') sh else null;
        }
        if (eq(u8, name, "chunked") or eq(u8, name, "sliding")) {
            const inner = (try self.printShapeOf(recv)) orelse
                try std.fmt.allocPrint(self.arena(), "[{c}", .{elemCode(self.elemKindOf(recv))});
            return try std.fmt.allocPrint(self.arena(), "[{s}", .{inner});
        }
        if (eq(u8, name, "fill")) {
            const v = callArg(cc, 0) orelse return null;
            return try std.fmt.allocPrint(self.arena(), "[{s}", .{try self.valueShapeOf(v)});
        }
        return null;
    }

    fn primNotLowered(self: *Emitter, k: envMod.PrimKind, cc: anytype) anyerror!void {
        return self.refuseUnlessTemplate(self.call_loc, "the wasm backend has no lowering for the {s} method `{s}/{d}`", .{
            @tagName(k), cc.callee, cc.args.len + cc.trailing.len,
        });
    }

    fn lowerPrimMethod(self: *Emitter, k: envMod.PrimKind, cc: anytype) anyerror!void {
        if (k == .string) if (try self.stringFnCellOf(cc.callee)) |sym| return self.lowerStringFnCell(sym, cc);
        if (primCallRes(k, cc) == null) {
            if (self.primDefaultOf(k, cc.callee)) |pd| if (pd.method.params.len == cc.args.len + 1)
                return self.lowerPrimDefault(k, pd, cc);
            return self.primNotLowered(k, cc);
        }
        const recv = cc.receiver.?.*;
        const name: []const u8 = cc.callee;
        const eq = std.mem.eql;
        const b = self.builder();
        switch (k) {
            .bool => {
                try self.lowerCoerced(recv, .i32);
                if (eq(u8, name, "negate")) {
                    try self.emit(opOf(.i32, "eqz"));
                } else if (eq(u8, name, "toString")) {
                    const sty = self.vtOf(Repr.string);
                    var then_c: Capture = .{};
                    self.open(&then_c);
                    try self.emitStrLit("true");
                    const then_seq = self.seal(&then_c, .{ .value = sty });
                    var else_c: Capture = .{};
                    self.open(&else_c);
                    try self.emitStrLit("false");
                    const else_seq = self.seal(&else_c, .{ .value = sty });
                    try self.emit(.{ .@"if" = .{ .result = sty, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                } else {
                    try self.lowerCoerced(callArg(cc, 0).?, .i32);
                    if (eq(u8, name, "nor")) {
                        try self.emit(opOf(.i32, "or"));
                        try self.emit(opOf(.i32, "eqz"));
                    } else if (eq(u8, name, "nand")) {
                        try self.emit(opOf(.i32, "and"));
                        try self.emit(opOf(.i32, "eqz"));
                    } else if (eq(u8, name, "exclusiveOr")) {
                        try self.emit(opOf(.i32, "ne"));
                    } else {
                        try self.emit(opOf(.i32, "eq"));
                    }
                }
            },
            .int => {
                if (intConversionType(name) != null and cc.args.len == 0) return self.lowerIntConversion(recv, name);
                // An `i64` answers its text in all its digits; its other
                // methods have no `i64` lowering here, and the narrowing
                // below refuses them.
                if (self.wasmTypeOf(recv).isI64() and eq(u8, name, "toString")) {
                    try self.lowerValue(recv);
                    try self.emitStdCall(if (self.isU64Expr(recv)) "number.u64ToString" else "number.i64ToString");
                    return;
                }
                try self.lowerCoerced(recv, .i32);
                if (eq(u8, name, "abs")) {
                    try self.emit(b.helper(.i32_abs));
                } else if (eq(u8, name, "min") or eq(u8, name, "max")) {
                    try self.lowerCoerced(callArg(cc, 0).?, .i32);
                    try self.emit(b.helper(if (eq(u8, name, "min")) .i32_min else .i32_max));
                } else if (eq(u8, name, "clamp")) {
                    try self.lowerCoerced(callArg(cc, 0).?, .i32);
                    try self.emit(b.helper(.i32_max));
                    try self.lowerCoerced(callArg(cc, 1).?, .i32);
                    try self.emit(b.helper(.i32_min));
                } else if (eq(u8, name, "isEven") or eq(u8, name, "isOdd")) {
                    try self.emit(try self.constInt(2));
                    try self.emit(opOf(.i32, "rem_s"));
                    try self.emit(opOf(.i32, "eqz"));
                    if (eq(u8, name, "isOdd")) try self.emit(opOf(.i32, "eqz"));
                } else {
                    try self.emitStdCall("number.i32ToString");
                }
            },
            .float => {
                try self.lowerCoerced(recv, .f64);
                if (eq(u8, name, "min") or eq(u8, name, "max")) {
                    try self.lowerCoerced(callArg(cc, 0).?, .f64);
                    try self.emit(opOf(.f64, name));
                } else if (eq(u8, name, "clamp")) {
                    try self.lowerCoerced(callArg(cc, 0).?, .f64);
                    try self.emit(opOf(.f64, "max"));
                    try self.lowerCoerced(callArg(cc, 1).?, .f64);
                    try self.emit(opOf(.f64, "min"));
                } else if (eq(u8, name, "round")) {
                    // `Math.round`: ties round up — `floor(x + 0.5)`.
                    try self.emit(constOf(.f64, "0.5"));
                    try self.emit(opOf(.f64, "add"));
                    try self.emit(opOf(.f64, "floor"));
                } else if (eq(u8, name, "squareRoot")) {
                    try self.emit(opOf(.f64, "sqrt"));
                } else if (eq(u8, name, "toString")) {
                    try self.emitStdCall("number.floatToString");
                } else {
                    // abs / floor / ceil are opcodes of the same name.
                    try self.emit(opOf(.f64, name));
                }
            },
            .string => try self.lowerStringMethod(cc),
            .array => try self.lowerArrayMethod(cc),
            .bytes => try self.lowerBytesMethod(cc),
            .bigint => {
                try self.lowerCoerced(recv, .i32);
                try self.emitStdCall(if (eq(u8, name, "toString"))
                    "bigint.toString"
                else if (eq(u8, name, "toI64"))
                    "bigint.toI64"
                else
                    "bigint.toF64");
            },
        }
    }

    /// Decision 319 — `toI32()`, `toI64()`, `toU32()`, `toU64()` and `toF64()`
    /// of an integer: the value in the target type's carrier when the type
    /// holds it, else `<name>: <value> does not fit <type>` (`has no exact
    /// f64`) on stderr and a trap — never a wrap, a saturation or a rounding.
    /// The receiver's carrier is an `i32` (`i8` … `i32`) or an `i64` (`u32`,
    /// `i64`, and a `u64` read unsigned); `u32` answers in an `i64`, as a
    /// `u32` lives here.
    fn lowerIntConversion(self: *Emitter, recv: ast.Expr, name: []const u8) anyerror!void {
        const eq = std.mem.eql;
        const wide = self.wasmTypeOf(recv).isI64();
        const unsigned = wide and self.isU64Expr(recv);
        const from: Repr = if (wide) .i64 else .i32;
        const v = try std.fmt.allocPrint(self.arena(), "__conv{d}", .{self.res_seq});
        self.res_seq += 1;
        try self.declareLocal(v, from);
        try self.lowerCoerced(recv, from);
        try self.emit(.{ .local_set = v });

        const to_f64 = eq(u8, name, "toF64");
        const f = if (to_f64 and wide) blk: {
            const fl = try std.fmt.allocPrint(self.arena(), "__conv{d}", .{self.res_seq});
            self.res_seq += 1;
            try self.declareLocal(fl, .f64);
            break :blk fl;
        } else "";

        // The test that the value fits, on the stack as an `i32`; none when
        // every value of the receiver's carrier does.
        var checked = true;
        if (eq(u8, name, "toI32")) {
            if (!wide) {
                checked = false;
            } else if (unsigned) {
                try self.emitRangeTest(v, null, "2147483647", true);
            } else {
                try self.emitRangeTest(v, "-2147483648", "2147483647", false);
            }
        } else if (eq(u8, name, "toI64")) {
            if (unsigned) try self.emitRangeTest(v, "0", null, false) else checked = false;
        } else if (eq(u8, name, "toU32")) {
            if (!wide) {
                try self.emit(.{ .local_get = v });
                try self.emit(zero);
                try self.emit(opOf(.i32, "ge_s"));
            } else if (unsigned) {
                try self.emitRangeTest(v, null, "4294967295", true);
            } else {
                try self.emitRangeTest(v, "0", "4294967295", false);
            }
        } else if (eq(u8, name, "toU64")) {
            if (!wide) {
                try self.emit(.{ .local_get = v });
                try self.emit(zero);
                try self.emit(opOf(.i32, "ge_s"));
            } else if (unsigned) {
                checked = false;
            } else {
                try self.emitRangeTest(v, "0", null, false);
            }
        } else {
            // `toF64`: an `i32` always converts exactly; an `i64` does when
            // the `f64` nearest it truncates back to it. The `f64` past the
            // carrier's top (`2^63`, `2^64`) is a rounding up, never exact,
            // and is tested first — truncating it would trap.
            if (!wide) {
                checked = false;
            } else {
                try self.emit(.{ .local_get = v });
                try self.emit(.{ .convert = if (unsigned) "f64.convert_i64_u" else "f64.convert_i64_s" });
                try self.emit(.{ .local_set = f });
                try self.emit(.{ .local_get = f });
                try self.emit(constOf(.f64, if (unsigned) "18446744073709551616.0" else "9223372036854775808.0"));
                try self.emit(opOf(.f64, "lt"));
                var then_c: Capture = .{};
                self.open(&then_c);
                try self.emit(.{ .local_get = f });
                try self.emit(.{ .convert = if (unsigned) "i64.trunc_f64_u" else "i64.trunc_f64_s" });
                try self.emit(.{ .local_get = v });
                try self.emit(opOf(.i64, "eq"));
                const then_seq = self.seal(&then_c, .{ .value = .i32 });
                var else_c: Capture = .{};
                self.open(&else_c);
                try self.emit(zero);
                const else_seq = self.seal(&else_c, .{ .value = .i32 });
                try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
            }
        }

        if (checked) {
            try self.emit(opOf(.i32, "eqz"));
            var fail_c: Capture = .{};
            self.open(&fail_c);
            const head_text = try std.fmt.allocPrint(self.arena(), "{s}: ", .{name});
            const tail_text = if (to_f64)
                " has no exact f64"
            else
                try std.fmt.allocPrint(self.arena(), " does not fit {s}", .{intConversionType(name).?});
            try self.emitStrLit(head_text);
            try self.emit(.{ .local_get = v });
            try self.emitStdCall(if (!wide) "number.i32ToString" else if (unsigned) "number.u64ToString" else "number.i64ToString");
            try self.emit(self.builder().helper(.str_concat));
            try self.emitStrLit(tail_text);
            try self.emit(self.builder().helper(.str_concat));
            try self.emit(self.builder().helper(.panic_fail));
            try self.emit(.@"unreachable");
            const fail_seq = self.seal(&fail_c, .terminated);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = fail_seq } } });
        }

        // The value in the target's carrier.
        if (to_f64) {
            if (wide) {
                try self.emit(.{ .local_get = f });
            } else {
                try self.emit(.{ .local_get = v });
                try self.emit(.{ .convert = "f64.convert_i32_s" });
            }
            return;
        }
        try self.emit(.{ .local_get = v });
        const to_i32 = eq(u8, name, "toI32");
        if (to_i32 and wide) try self.emit(.{ .convert = "i32.wrap_i64" });
        if (!to_i32 and !wide) try self.emit(.{ .convert = "i64.extend_i32_s" });
    }

    /// `v >= lo && v <= hi` over the `i64` local `v` (either bound absent),
    /// compared unsigned when `unsigned`; an `i32` on the stack.
    fn emitRangeTest(self: *Emitter, v: []const u8, lo: ?[]const u8, hi: ?[]const u8, unsigned: bool) anyerror!void {
        if (lo) |l| {
            try self.emit(.{ .local_get = v });
            try self.emit(constOf(.i64, l));
            try self.emit(opOf(.i64, if (unsigned) "ge_u" else "ge_s"));
        }
        if (hi) |h| {
            try self.emit(.{ .local_get = v });
            try self.emit(constOf(.i64, h));
            try self.emit(opOf(.i64, if (unsigned) "le_u" else "le_s"));
            if (lo != null) try self.emit(opOf(.i32, "and"));
        }
    }

    /// The type decision 319's conversion `name` answers (`toU32` → `u32`),
    /// or null for any other method.
    fn intConversionType(name: []const u8) ?[]const u8 {
        const eq = std.mem.eql;
        if (eq(u8, name, "toI32")) return "i32";
        if (eq(u8, name, "toI64")) return "i64";
        if (eq(u8, name, "toU32")) return "u32";
        if (eq(u8, name, "toU64")) return "u64";
        if (eq(u8, name, "toF64")) return "f64";
        return null;
    }

    /// Decision 346 — `Bytes`' methods. A `Bytes` is laid out as a string is
    /// (the address of its `u32` byte count, the bytes behind it), so its
    /// length is that word, `concat` the strings' concatenation, `slice`
    /// std-wasm's `bytes.slice` (byte bounds, `slice`'s normalisation), and
    /// `toUtf8` the same address once std-wasm's `bytes.isUtf8` accepts it.
    fn lowerBytesMethod(self: *Emitter, cc: anytype) anyerror!void {
        const recv = cc.receiver.?.*;
        const name: []const u8 = cc.callee;
        const eq = std.mem.eql;
        if (self.mode == .gc) return self.gcBytesMethod(cc, recv, name);
        if (eq(u8, name, "slice")) {
            try self.lowerCoerced(recv, .i32);
            if (cc.args.len > 0) try self.lowerCoerced(cc.args[0].value.*, .i32) else try self.emit(zero);
            if (cc.args.len > 1 and !isNullLit(cc.args[1].value.*))
                try self.lowerSliceEnd(cc.args[1].value.*)
            else
                try self.emit(try self.constInt(std.math.maxInt(i32)));
            try self.emitStdCall("bytes.slice");
            return;
        }
        if (eq(u8, name, "length")) {
            try self.lowerCoerced(recv, .i32);
            try self.emitC(.{ .load = .{} }, "byte count");
            return;
        }
        if (eq(u8, name, "concat")) {
            try self.lowerCoerced(recv, .i32);
            try self.lowerCoerced(callArg(cc, 0).?, .i32);
            try self.emit(self.builder().helper(.str_concat));
            return;
        }
        // `toUtf8`: `Ok` holding the same buffer (a string's layout), or the
        // `Error` the other targets write.
        const p = try self.declRes();
        const out = try self.declRes();
        try self.lowerCoerced(recv, .i32);
        try self.emit(.{ .local_set = p });
        try self.allocResultPair(out);
        try self.emit(.{ .local_get = p });
        try self.emitStdCall("bytes.isUtf8");
        var then_c: Capture = .{};
        self.open(&then_c);
        try self.emit(.{ .local_get = out });
        try self.emit(zero);
        try self.emitC(.{ .store = .{} }, "Ok tag");
        try self.emit(.{ .local_get = out });
        try self.emit(.{ .local_get = p });
        try self.emitC(.{ .store = .{ .offset = 4 } }, "payload");
        const then_seq = self.seal(&then_c, .none);
        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emit(.{ .local_get = out });
        try self.emit(one);
        try self.emitC(.{ .store = .{} }, "Error tag");
        try self.emit(.{ .local_get = out });
        const msg = try self.internString("Bytes.toUtf8: not valid UTF-8");
        try self.emit(try self.constInt(msg.offset));
        try self.emitC(.{ .store = .{ .offset = 4 } }, "payload");
        const else_seq = self.seal(&else_c, .none);
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
        try self.emit(.{ .local_get = out });
    }

    /// Decision 346 — `Bytes.fromUtf8(s)`, which inference names by the
    /// behavior: the string's own buffer, a `Bytes`' layout (both immutable).
    fn isBytesFromUtf8(self: *Emitter, cc: anytype) bool {
        const rn = receiverName(cc) orelse return false;
        if (!std.mem.eql(u8, rn, "Bytes") or cc.args.len != 1 or cc.trailing.len != 0) return false;
        if (self.locals.contains(rn) or self.globals.contains(rn) or self.records.contains(rn) or self.enums.contains(rn)) return false;
        return std.mem.eql(u8, cc.callee, "fromUtf8");
    }

    fn lowerStringMethod(self: *Emitter, cc: anytype) anyerror!void {
        const recv = cc.receiver.?.*;
        const name: []const u8 = cc.callee;
        const eq = std.mem.eql;
        if (eq(u8, name, "slice")) return self.lowerStrSlice(cc);
        try self.lowerCoerced(recv, Repr.string);
        if (eq(u8, name, "toString")) return; // already the string
        // Decision 442 (2) — every other method is std-wasm's, the function
        // `primitives.bp`'s `std:` cell names (`std_method_exports`), its
        // arguments as the declaration orders them.
        const export_name = stdMethodExport("String", name) orelse
            return self.refuseUnlessTemplate(self.call_loc, "`String.{s}` has no lowering on the wasm backend", .{name});
        const ex = stdWasm.find(export_name).?;
        for (ex.params[1..], 0..) |t, k| {
            // In a GC module each argument is the value its parameter is
            // marshalled from (`emitStdCall`); in linear memory every one is a word.
            const want: Repr = if (self.mode == .gc) try stdRepr(gcStdTy(t) orelse return self.gcFail("a std-wasm parameter with no marshal")) else .i32;
            try self.lowerCoerced(callArg(cc, k).?, want);
        }
        try self.emitStdCall(export_name);
    }

    fn lowerArrayMethod(self: *Emitter, cc: anytype) anyerror!void {
        const recv = cc.receiver.?.*;
        const name: []const u8 = cc.callee;
        const eq = std.mem.eql;
        const b = self.builder();

        if (self.mode == .gc) if (try self.gcArrayMethod(cc, recv, name)) return;
        const Hof = enum { map, filter, for_each, all, any, count, find_index, fold };
        const hof: ?Hof = if (eq(u8, name, "map")) .map else if (eq(u8, name, "filter")) .filter else if (eq(u8, name, "forEach")) .for_each else if (eq(u8, name, "all") or eq(u8, name, "every")) .all else if (eq(u8, name, "any") or eq(u8, name, "some")) .any else if (eq(u8, name, "count")) .count else if (eq(u8, name, "findIndex")) .find_index else if (eq(u8, name, "fold")) .fold else null;
        if (hof) |h| {
            const lam = (try self.hofLambdaAt(cc, if (h == .fold) 1 else 0, if (h == .fold) 2 else 1)) orelse {
                return self.refuseUnlessTemplate(self.call_loc, "`{s}` on the wasm backend takes a closure written at the call; a function value is not lowered", .{name});
            };
            return self.lowerArrayHof(@intFromEnum(h), recv, lam, if (h == .fold) callArg(cc, 0) else null);
        }
        if (eq(u8, name, "push")) return self.lowerArrayPush(cc);
        if (eq(u8, name, "pop")) return self.lowerArrayPop(cc);
        // `xs.find(pred)` is `xs.filter(pred).at(0)` — `primitives.bp`'s own
        // body — as the `?T` `at` answers (`arrayElemOpt`: a scalar boxed, a
        // pointer as itself).
        if (eq(u8, name, "find")) {
            const lam = (try self.hofLambdaAt(cc, 0, 1)) orelse {
                return self.refuseUnlessTemplate(self.call_loc, "`{s}` on the wasm backend takes a closure written at the call; a function value is not lowered", .{name});
            };
            try self.lowerArrayHof(@intFromEnum(Hof.filter), recv, lam, null);
            try self.emit(zero);
            try self.emit(b.helper(self.arrAtHelper(recv)));
            return;
        }
        // `xs.flatMap(f)` is `primitives.bp`'s own body, `xs.map(f).flatten()`
        // — when what `f` answers is known to be an array. Anything else has
        // no flattening this backend can answer by: a refusal, never a guess.
        if (eq(u8, name, "flatMap")) {
            const lam = (try self.hofLambdaAt(cc, 0, 1)) orelse {
                return self.refuseUnlessTemplate(self.call_loc, "`{s}` on the wasm backend takes a closure written at the call; a function value is not lowered", .{name});
            };
            const tail = (try self.lambdaTailShape(lam, recv)) orelse
                return self.refuseUnlessTemplate(self.call_loc, "`flatMap` on the wasm backend: nothing shows that its function answers an array", .{});
            if (tail[0] != '[')
                return self.refuseUnlessTemplate(self.call_loc, "`flatMap` on the wasm backend: its function answers no array, so there is nothing to flatten", .{});
            try self.lowerArrayHof(@intFromEnum(Hof.map), recv, lam, null);
            try self.emitStdCall("array.flatten");
            return;
        }
        if (eq(u8, name, "flatten") or eq(u8, name, "flat")) {
            const sh = (try self.printShapeOf(recv)) orelse "";
            if (!(sh.len >= 2 and sh[0] == '[' and sh[1] == '[')) {
                return self.refuseUnlessTemplate(self.call_loc, "`{s}` on the wasm backend: nothing shows that the receiver's elements are arrays", .{name});
            }
            try self.lowerCoerced(recv, .i32);
            try self.emitStdCall("array.flatten");
            return;
        }
        if (eq(u8, name, "unique")) {
            const mode = (try self.uniqueMode(recv)) orelse {
                return self.refuseUnlessTemplate(self.call_loc, "`unique` on the wasm backend compares integers, floats, bools and strings; these elements (a record, an array, a tuple) have no equality here", .{});
            };
            try self.lowerCoerced(recv, .i32);
            try self.emit(try self.constInt(mode));
            try self.emitStdCall("array.unique");
            return;
        }
        if (eq(u8, name, "fill")) {
            const v = callArg(cc, 0).?;
            try self.lowerCoerced(recv, .i32);
            try self.emitC(.{ .load = .{} }, "element count");
            // The result holds `v`s whatever the receiver held (its shape is
            // `v`'s, `newArrShape`): a float fills every slot with the one
            // cell — a cell is never written again, so sharing it is sharing
            // a value.
            try self.lowerSlotWord(v);
            try self.emitStdCall("array.fill");
            return;
        }
        if (eq(u8, name, "chunked") or eq(u8, name, "sliding")) {
            try self.lowerCoerced(recv, .i32);
            try self.lowerCoerced(callArg(cc, 0).?, .i32);
            try self.emitStdCall(if (eq(u8, name, "chunked")) "array.chunked" else "array.sliding");
            return;
        }

        try self.lowerCoerced(recv, .i32);
        const elem = self.elemKindOf(recv);
        if (eq(u8, name, "length")) {
            try self.emitC(.{ .load = .{} }, "element count");
        } else if (eq(u8, name, "isEmpty")) {
            try self.emitC(.{ .load = .{} }, "element count");
            try self.emit(opOf(.i32, "eqz"));
        } else if (eq(u8, name, "at") or eq(u8, name, "first")) {
            // `?T`: a pointer element (a string, a record) is its own offset; a
            // scalar is boxed. `arrayElemOpt` is the ONE place that decides,
            // and `optInfoOf` reads the same answer — see its doc comment.
            if (eq(u8, name, "first")) try self.emit(zero) else try self.lowerCoerced(callArg(cc, 0).?, .i32);
            try self.emit(b.helper(self.arrAtHelper(recv)));
        } else if (eq(u8, name, "toList")) {
            // the array itself
        } else if (eq(u8, name, "reverse")) {
            try self.emitStdCall("array.reverse");
        } else if (eq(u8, name, "rest") or eq(u8, name, "take") or eq(u8, name, "drop") or eq(u8, name, "slice")) {
            // `arr_slice` clamps its bounds, so "to the end" is the largest i32.
            const whole = try self.constInt(std.math.maxInt(i32));
            if (eq(u8, name, "rest")) {
                try self.emit(one);
                try self.emit(whole);
            } else if (eq(u8, name, "take")) {
                try self.emit(zero);
                try self.lowerCoerced(callArg(cc, 0).?, .i32);
            } else {
                try self.lowerCoerced(callArg(cc, 0).?, .i32);
                if (callArg(cc, 1)) |end| {
                    if (isNullLit(end)) try self.emit(whole) else try self.lowerSliceEnd(end);
                } else try self.emit(whole);
            }
            try self.emitStdCall("array.slice");
        } else {
            const arg = callArg(cc, 0).?;
            if (eq(u8, name, "join")) {
                try self.lowerCoerced(arg, .i32);
                try self.emitStdCall(if (elem == .str) "array.joinStrings" else if (elem == .f64) "array.joinFloats" else "array.joinInts");
            } else if (eq(u8, name, "lastIndexOf")) {
                if (elem == .f64) {
                    try self.lowerCoerced(arg, .f64);
                    try self.emitStdCall("array.lastIndexOfFloat");
                } else {
                    try self.lowerCoerced(arg, .i32);
                    try self.emitStdCall(if (elem == .str or self.isStringExpr(arg)) "array.lastIndexOfString" else "array.lastIndexOfWord");
                }
            } else if (eq(u8, name, "indexOf") or eq(u8, name, "contains")) {
                if (elem == .f64) {
                    try self.lowerCoerced(arg, .f64);
                    try self.emitStdCall("array.indexOfFloat");
                } else {
                    try self.lowerCoerced(arg, .i32);
                    try self.emitStdCall(if (elem == .str or self.isStringExpr(arg)) "array.indexOfString" else "array.indexOfWord");
                }
                if (eq(u8, name, "contains")) {
                    try self.emit(try self.constInt(-1));
                    try self.emit(opOf(.i32, "ne"));
                }
            } else {
                // `prepend` takes an element (a float as its cell), `append`
                // and `zip` an array.
                if (eq(u8, name, "prepend")) try self.lowerElemWord(elem, arg) else try self.lowerCoerced(arg, .i32);
                try self.emitStdCall(if (eq(u8, name, "prepend")) "array.prepend" else if (eq(u8, name, "append")) "array.concat" else "array.zip");
            }
        }
    }

    /// Decision 122 — `seq.next()` by hand. The eager sequence is an array blob
    /// (`[len][e0][e1]…`), so the step is its head: the prelude `YieldStep`'s
    /// `Yield(e0)` when `len > 0`, `Done` otherwise. A local receiver is then
    /// rebound to the rest (std-wasm's `array.slice(seq, 1, len)`, a copy — an alias of
    /// the same sequence keeps its items), as `push` rebinds it, so the next
    /// `.next()` reads on. The item is copied as one 4-byte slot, which is
    /// what every element layout of the blob is.
    fn lowerSequenceNext(self: *Emitter, cc: anytype) anyerror!void {
        const recv = cc.receiver.?.*;
        const variants = self.enums.get("YieldStep") orelse {
            return self.refuse(self.call_loc, "`.next()` on a sequence: `YieldStep` is not declared in this module", .{});
        };
        var yield_tag: ?u32 = null;
        var done_tag: ?u32 = null;
        for (variants, 0..) |v, i| {
            if (std.mem.eql(u8, v.name, "Yield")) yield_tag = @intCast(i);
            if (std.mem.eql(u8, v.name, "Done")) done_tag = @intCast(i);
        }
        const yi = yield_tag orelse return self.refuse(self.call_loc, "`.next()` on a sequence: `YieldStep` declares no `Yield`", .{});
        const di = done_tag orelse return self.refuse(self.call_loc, "`.next()` on a sequence: `YieldStep` declares no `Done`", .{});
        const local: ?[]const u8 = switch (recv) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| if (self.locals.contains(n)) n else null,
                else => null,
            },
            else => null,
        };

        const seq = try self.memName(self.nextMem());
        try self.lowerCoerced(recv, .i32);
        try self.emit(.{ .local_tee = seq });
        try self.emitC(.{ .load = .{} }, "items left");

        var then_c: Capture = .{};
        self.open(&then_c);
        const desc = try self.variantDescriptorAddr("YieldStep", variants[yi]);
        const base = try self.allocTagged(desc orelse 0, 8);
        try self.storeSlotConst(base, tag_header_bytes, yi);
        try self.emit(.{ .local_get = base });
        try self.emit(.{ .local_get = seq });
        try self.emitC(.{ .load = .{ .offset = 4 } }, "the head");
        try self.emit(.{ .store = .{ .offset = tag_header_bytes + 4 } });
        if (local) |n| {
            try self.emit(.{ .local_get = seq });
            try self.emit(try self.constInt(1));
            try self.emit(.{ .local_get = seq });
            try self.emit(.{ .load = .{} });
            try self.emitStdCall("array.slice");
            try self.emitCf(.{ .local_set = n }, "{s} = the rest", .{n});
        }
        try self.loadTaggedBase(base);
        const then_seq = self.seal(&then_c, .{ .value = .i32 });

        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emitUnitVariant(variants, di, "YieldStep", "Done");
        const else_seq = self.seal(&else_c, .{ .value = .i32 });

        try self.emit(.{ .@"if" = .{
            .result = .i32,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
    }

    /// `xs.push(v)` — the blob has a fixed size, so the receiver is rebound to
    /// a copy with `v` appended (the erlang backend threads the same way). A
    /// receiver that is not a name or a record field cannot be rebound.
    /// `xs.pop()` on a local: the last element as the `?T` `xs.at(-1)`
    /// answers (`arrayElemOpt` decides the box, as for `at`), then the local
    /// rebound to `xs.slice(0, len - 1)` — `pop` SHRINKS the array, and a
    /// blob is a value here, as `push` rebinds it to a grown copy. An empty
    /// array answers absent and stays empty (`arr_slice` clamps `-1` to 0).
    fn lowerArrayPop(self: *Emitter, cc: anytype) anyerror!void {
        const recv = cc.receiver.?.*;
        const n = switch (recv) {
            .identifier => |id| switch (id.kind) {
                .ident => |n0| blk: {
                    const n = self.resolveName(n0);
                    break :blk if (self.locals.contains(n) or self.globals.contains(n)) n else null;
                },
                else => null,
            },
            else => null,
        } orelse {
            // A field of a record whose type is known here — `push`'s field
            // path: the last element, then the field rewritten one shorter.
            if (recv == .identifier and recv.identifier.kind == .identAccess) {
                const ia = recv.identifier.kind.identAccess;
                if (self.recordTypeOfExpr(ia.receiver.*)) |rty| if (self.fieldOffsetIn(rty, ia.member)) |off| {
                    const b = self.builder();
                    const owner = try self.memName(self.nextMem());
                    const arr = try self.memName(self.nextMem());
                    try self.lowerValue(ia.receiver.*);
                    try self.emit(.{ .local_tee = owner });
                    try self.emit(.{ .load = .{ .offset = off } });
                    try self.emit(.{ .local_tee = arr });
                    try self.emit(try self.constInt(-1));
                    try self.emit(b.helper(self.arrAtHelper(recv)));
                    try self.emit(.{ .local_get = owner });
                    try self.emit(.{ .local_get = arr });
                    try self.emit(zero);
                    try self.emit(.{ .local_get = arr });
                    try self.emitC(.{ .load = .{} }, "element count");
                    try self.emit(one);
                    try self.emit(opOf(.i32, "sub"));
                    try self.emitStdCall("array.slice");
                    try self.emitCf(.{ .store = .{ .offset = off } }, ".{s} = pop", .{ia.member});
                    return;
                };
            }
            // Any other receiver — a call's result, an element — may be an
            // array some other name still holds, which `pop` shrinks in
            // place on the other backends; a copy here would leave it whole.
            return self.refuse(self.call_loc, "`pop` on the wasm backend rebinds its receiver, which must be a local, a module `var` or a field of a record whose type is known here", .{});
        };
        const b = self.builder();
        const get: Instr = if (self.locals.contains(n)) .{ .local_get = n } else .{ .global_get = n };
        try self.emit(get);
        try self.emit(try self.constInt(-1));
        try self.emit(b.helper(self.arrAtHelper(recv)));
        try self.emit(get);
        try self.emit(zero);
        try self.emit(get);
        try self.emitC(.{ .load = .{} }, "element count");
        try self.emit(one);
        try self.emit(opOf(.i32, "sub"));
        try self.emitStdCall("array.slice");
        try self.emit(if (self.locals.contains(n)) .{ .local_set = n } else .{ .global_set = n });
    }

    fn lowerArrayPush(self: *Emitter, cc: anytype) anyerror!void {
        const recv = cc.receiver.?.*;
        const arg = callArg(cc, 0) orelse {
            return self.refuse(self.call_loc, "`push` with no value to push", .{});
        };
        switch (recv) {
            .identifier => |id| switch (id.kind) {
                .ident => |n0| if (self.locals.contains(self.resolveName(n0)) or self.globals.contains(self.resolveName(n0))) {
                    const n = self.resolveName(n0);
                    if (self.mode == .gc) {
                        const ar = self.wasmTypeOf(recv);
                        if (!ar.isArrRef()) return self.gcFail("a push onto a value of no known array type");
                        const cls = ar.ref.arr;
                        const er: Repr = if (cls == .any) (self.gcElemRepr(recv) orelse return self.gcFail("a push onto an array of no known element type")) else if (cls == .f64) .f64 else .i32;
                        try self.lowerCoerced(recv, ar);
                        try self.lowerCoerced(arg, er);
                        if (cls == .any) try self.gcBox(er);
                        try self.emit(.{ .call = try self.gcArrPush(cls) });
                        try self.emit(if (self.locals.contains(n)) .{ .local_set = n } else .{ .global_set = n });
                        return;
                    }
                    try self.lowerCoerced(recv, .i32);
                    try self.lowerElemWord(self.elemKindOf(recv), arg);
                    try self.emit(self.builder().helper(.arr_push));
                    try self.emit(if (self.locals.contains(n)) .{ .local_set = n } else .{ .global_set = n });
                    return;
                },
                .identAccess => |ia| if (self.recordTypeOfExpr(ia.receiver.*)) |rty| if (self.fieldOffsetIn(rty, ia.member)) |off| {
                    const mem = try self.memName(self.nextMem());
                    try self.lowerValue(ia.receiver.*);
                    try self.emit(.{ .local_tee = mem });
                    try self.emit(.{ .local_get = mem });
                    try self.emit(.{ .load = .{ .offset = off } });
                    try self.lowerElemWord(self.elemKindOf(recv), arg);
                    try self.emit(self.builder().helper(.arr_push));
                    try self.emitCf(.{ .store = .{ .offset = off } }, ".{s} = push", .{ia.member});
                    return;
                },
                else => {},
            },
            else => {},
        }
        return self.refuse(self.call_loc, "`push` on the wasm backend rebinds its receiver, which must be a local, a module `var` or a field of a record whose type is known here", .{});
    }

    /// A higher-order array method over a literal lambda: a counted walk of the
    /// `[len][e0][e1]…` blob with the lambda's parameters bound to locals and
    /// its body inlined per element. `hof` is `lowerArrayMethod`'s `Hof`.
    fn lowerArrayHof(self: *Emitter, hof: u8, recv: ast.Expr, lam: LambdaView, init_expr: ?ast.Expr) anyerror!void {
        if (self.mode == .gc) return self.gcArrayHof(hof, recv, lam, init_expr);
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        const map = 0;
        const filter = 1;
        const for_each = 2;
        const all = 3;
        const any = 4;
        const count = 5;
        const find_index = 6;
        const fold = 7;

        const ra = self.reg_arena.allocator();
        const n = self.loop_seq;
        self.loop_seq += 1;
        const base = try std.fmt.allocPrint(ra, "__iter{d}", .{n});
        const cur = try std.fmt.allocPrint(ra, "__idx{d}", .{n});
        const len = try std.fmt.allocPrint(ra, "__len{d}", .{n});
        const acc = try std.fmt.allocPrint(ra, "__acc{d}", .{n});
        const out = try std.fmt.allocPrint(ra, "__out{d}", .{n});
        try self.declareLocal(base, .i32);
        try self.declareLocal(cur, .i32);
        try self.declareLocal(len, .i32);

        const elem_kind = self.elemKindOf(recv);
        const elem_ty: Repr = if (elem_kind == .f64) .f64 else .i32;
        // fold binds (acc, item); the others bind (item).
        const acc_param0: ?[]const u8 = if (hof == fold and lam.params.len > 0) lam.params[0] else null;
        const elem_param0: ?[]const u8 = if (hof == fold)
            (if (lam.params.len > 1) lam.params[1] else null)
        else if (lam.params.len > 0) lam.params[0] else null;
        // A binder over a name the function already binds (`val e = 5;
        // xs.forEach({ e -> … })`) is a local of its own — read `e` after the
        // walk and it answered the last element.
        const acc_ty: Repr = if (hof == fold) (if (init_expr) |i| self.wasmTypeOf(i) else .i32) else .i32;
        const acc_param: ?[]const u8 = if (acc_param0) |p| try self.bindTargetAs(p, acc_ty) else null;
        const elem_param: ?[]const u8 = if (elem_param0) |p| try self.bindTargetAs(p, elem_ty) else null;
        try self.declareLocal(acc, acc_ty);
        if (hof == map or hof == filter) try self.declareLocal(out, .i32);
        if (elem_param) |p| {
            try self.declareLocal(p, elem_ty);
            try self.noteElemShape(p, recv);
            if (elem_kind == .str) try self.str_locals.put(p, {});
            if (try self.elemIsBool(recv)) try self.bool_locals.put(p, {});
            // An element of a generic record whose type arguments are known
            // (`ctorTypeRef`) keeps them, so `p.matched()` specialises.
            if (self.elemTypeRefOf(recv)) |et| if (et == .generic and self.record_generics.contains(et.generic.name)) try self.local_typerefs.put(p, et);
            // An element of an `unknown[]` is an `unknown` (its own header):
            // `v is i32` reads the box, not a guess at a static type
            // (`modules/is/cases/is_truth_table`).
            if (self.elemTypeRefOf(recv)) |et| if (isUnknownTypeRef(et)) try self.local_typerefs.put(p, et);
            // The parameter is one ELEMENT, so it has the element's record
            // type. Without it a field read off it had no receiver type and
            // fell to the unique-field guess, or to the `0` stub.
            if (self.elemRecordOf(recv)) |r| try self.local_types.put(p, r);
        }
        if (acc_param) |p| {
            try self.declareLocal(p, acc_ty);
            if (init_expr) |i| if (self.isStringExpr(i)) try self.str_locals.put(p, {});
        }

        try self.lowerCoerced(recv, .i32);
        try self.emit(.{ .local_set = base });
        if (elem_param0) |p| self.installShadow(p, elem_param.?);
        if (acc_param0) |p| self.installShadow(p, acc_param.?);
        try self.emit(.{ .local_get = base });
        try self.emitC(.{ .load = .{} }, "element count");
        try self.emit(.{ .local_set = len });
        try self.emit(zero);
        try self.emit(.{ .local_set = cur });
        switch (hof) {
            map, filter => {
                try self.emit(.{ .local_get = len });
                try self.emit(self.builder().helper(.arr_new));
                try self.emit(.{ .local_set = out });
                try self.emit(zero);
                try self.emit(.{ .local_set = acc });
            },
            fold => {
                try self.lowerCoerced(init_expr.?, acc_ty);
                try self.emit(.{ .local_set = acc });
            },
            all => {
                try self.emit(one);
                try self.emit(.{ .local_set = acc });
            },
            find_index => {
                try self.emit(try self.constInt(-1));
                try self.emit(.{ .local_set = acc });
            },
            else => {
                try self.emit(zero);
                try self.emit(.{ .local_set = acc });
            },
        }

        var loop_c: Capture = .{};
        self.open(&loop_c);
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, .{ .local_get = len });
        try self.emitAt(8, opOf(.i32, "ge_s"));
        try self.emitAt(8, .{ .br_if = break_label });
        if (hof == find_index) {
            try self.emitAt(8, .{ .local_get = acc });
            try self.emitAt(8, try self.constInt(-1));
            try self.emitAt(8, opOf(.i32, "ne"));
            try self.emitAt(8, .{ .br_if = break_label });
        }
        if (elem_param) |p| {
            try self.emitAt(8, .{ .local_get = base });
            try self.emitAt(8, .{ .local_get = cur });
            try self.emitAt(8, try self.constInt(4));
            try self.emitAt(8, opOf(.i32, "mul"));
            try self.emitAt(8, opOf(.i32, "add"));
            try self.emitAt(8, .{ .load = .{ .offset = 4 } });
            if (elem_kind == .f64) try self.emitAt(8, .{ .load = .{ .ty = .f64 } });
            try self.emitAt(8, .{ .local_set = p });
        }
        if (acc_param) |p| {
            try self.emitAt(8, .{ .local_get = acc });
            try self.emitAt(8, .{ .local_set = p });
        }
        switch (hof) {
            for_each => {
                const mark = self.defer_stack.items.len;
                const tail = try self.emitStmtsFrom(lam.body, 0, false, null, true, null);
                try self.closeDefers(mark, tail);
            },
            map => {
                const tail_ty = self.lambdaTailType(lam.body);
                const is_float = tail_ty.isFloat();
                // the slot address first, then the value
                try self.emit(.{ .local_get = out });
                try self.emit(.{ .local_get = cur });
                try self.emit(try self.constInt(4));
                try self.emit(opOf(.i32, "mul"));
                try self.emit(opOf(.i32, "add"));
                try self.inlineLambdaBody(lam.body);
                try self.emitConvert(tail_ty, if (is_float) .f64 else .i32);
                if (is_float) try self.emitToFloatSlot();
                try self.emit(.{ .store = .{ .offset = 4 } });
            },
            fold => {
                const tail_ty = self.lambdaTailType(lam.body);
                try self.inlineLambdaBody(lam.body);
                try self.emitConvert(tail_ty, acc_ty);
                try self.emit(.{ .local_set = acc });
            },
            else => {
                try self.inlineLambdaBody(lam.body);
                var then_c: Capture = .{};
                self.open(&then_c);
                switch (hof) {
                    filter => {
                        try self.emit(.{ .local_get = out });
                        try self.emit(.{ .local_get = acc });
                        try self.emit(try self.constInt(4));
                        try self.emit(opOf(.i32, "mul"));
                        try self.emit(opOf(.i32, "add"));
                        try self.emit(.{ .local_get = base });
                        try self.emit(.{ .local_get = cur });
                        try self.emit(try self.constInt(4));
                        try self.emit(opOf(.i32, "mul"));
                        try self.emit(opOf(.i32, "add"));
                        try self.emit(.{ .load = .{ .offset = 4 } });
                        try self.emit(.{ .store = .{ .offset = 4 } });
                        try self.emit(.{ .local_get = acc });
                        try self.emit(one);
                        try self.emit(opOf(.i32, "add"));
                        try self.emit(.{ .local_set = acc });
                    },
                    all => {
                        try self.emit(zero);
                        try self.emit(.{ .local_set = acc });
                    },
                    any => {
                        try self.emit(one);
                        try self.emit(.{ .local_set = acc });
                    },
                    count => {
                        try self.emit(.{ .local_get = acc });
                        try self.emit(one);
                        try self.emit(opOf(.i32, "add"));
                        try self.emit(.{ .local_set = acc });
                    },
                    else => {
                        try self.emit(.{ .local_get = cur });
                        try self.emit(.{ .local_set = acc });
                    },
                }
                const then_seq = self.seal(&then_c, .none);
                if (hof == all) try self.emit(opOf(.i32, "eqz"));
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq } } });
            },
        }
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, one);
        try self.emitAt(8, opOf(.i32, "add"));
        try self.emitAt(8, .{ .local_set = cur });
        try self.emitAt(8, .{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);
        try self.emitLoopBlock(loop_seq, null);

        switch (hof) {
            for_each => {},
            map => try self.emit(.{ .local_get = out }),
            filter => {
                try self.emit(.{ .local_get = out });
                try self.emit(.{ .local_get = acc });
                try self.emitC(.{ .store = .{} }, "kept count");
                try self.emit(.{ .local_get = out });
            },
            else => try self.emit(.{ .local_get = acc }),
        }
    }

    /// An inlined lambda body in a GC module: its statements, then its tail
    /// (a trailing `return`'s value) coerced to `want`, or as the value it
    /// is; answers the repr left on the stack.
    fn gcInlineTail(self: *Emitter, body: []const ast.Stmt, want: ?Repr) anyerror!Repr {
        if (body.len == 0) return self.gcFail("an inlined lambda with no body");
        for (body[0..ast.lastRealIndex(body)]) |st| _ = try self.emitStmt(st, false);
        const last = body[ast.lastRealIndex(body)].expr;
        const tail: ast.Expr = switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |v| v.* else return self.gcFail("an inlined lambda answering nothing"),
                else => return self.gcFail("an inlined lambda ending in a jump"),
            },
            .binding => return self.gcFail("an inlined lambda ending in a binding"),
            else => last,
        };
        const r = want orelse self.wasmTypeOf(tail);
        try self.lowerCoerced(tail, r);
        return r;
    }

    /// What the closure `lam` of `recv.map(lam)` answers for one element of
    /// the GC array `recv`: its tail's repr with the parameter bound as the
    /// walk binds it (`gcArrayHof`), a `bool` told from the word it is.
    fn gcMapTail(self: *Emitter, lam: LambdaView, recv: ast.Expr) Repr {
        const ar = self.wasmTypeOf(recv);
        const er: Repr = if (!ar.isArrRef()) .i32 else switch (ar.ref.arr) {
            .any => self.gcElemRepr(recv) orelse .i32,
            .f64 => .f64,
            .i32 => .i32,
        };
        if (lam.params.len == 0) return self.lambdaTailType(lam.body);
        const p = lam.params[0];
        const prev_local = self.locals.get(p);
        const prev_tref = self.local_typerefs.get(p);
        const prev_type = self.local_types.get(p);
        const prev_alias = self.aliases.get(p);
        const prev_str = self.str_locals.contains(p);
        defer {
            if (prev_local) |t| self.locals.put(p, t) catch {} else _ = self.locals.remove(p);
            if (prev_tref) |t| self.local_typerefs.put(p, t) catch {} else _ = self.local_typerefs.remove(p);
            if (prev_type) |t| self.local_types.put(p, t) catch {} else _ = self.local_types.remove(p);
            if (prev_alias) |a| self.aliases.put(p, a) catch {};
            if (!prev_str) _ = self.str_locals.remove(p);
        }
        _ = self.aliases.remove(p);
        self.locals.put(p, er) catch {};
        if (self.elemTypeRefOf(recv)) |et| self.local_typerefs.put(p, et) catch {} else _ = self.local_typerefs.remove(p);
        if (self.elemRecordOf(recv)) |r| self.local_types.put(p, r) catch {};
        if (self.elemKindOf(recv) == .str) self.str_locals.put(p, {}) catch {};
        var t = self.lambdaTailType(lam.body);
        if (t == .i32) {
            const last = if (lam.body.len > 0) lam.body[ast.lastRealIndex(lam.body)].expr else return t;
            const v = switch (last) {
                .jump => |j| switch (j.kind) {
                    .@"return" => |r| if (r) |x| x.* else return t,
                    else => return t,
                },
                else => last,
            };
            if (self.isBoolExpr(v)) t = .bool;
        }
        return t;
    }

    /// `xs.map / filter / forEach / all / any / count / findIndex / fold` with
    /// a closure written at the call, over a GC array (front 164 s2 P2b): the
    /// closure's body inlined into a walk of the elements, as
    /// `lowerArrayHof` does over the words. `map` answers an array of the
    /// class of what the body answers; `filter` the kept elements.
    fn gcArrayHof(self: *Emitter, hof: u8, recv: ast.Expr, lam: LambdaView, init_expr: ?ast.Expr) anyerror!void {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        const map = 0;
        const filter = 1;
        const for_each = 2;
        const all = 3;
        const any = 4;
        const count = 5;
        const find_index = 6;
        const fold = 7;
        const ar = self.wasmTypeOf(recv);
        if (!ar.isArrRef()) return self.gcFail("a walk over a value of no known array type");
        const cls = ar.ref.arr;
        const elem_bool = try self.elemIsBool(recv);
        const er: Repr = switch (cls) {
            .any => self.gcElemRepr(recv) orelse return self.gcFail("a walk over an array of no known element type"),
            .f64 => .f64,
            .i32 => if (elem_bool) .bool else .i32,
        };
        if (gcElemClassOf(er) != cls) return self.gcFail("an array whose elements disagree with its class");
        const ti = self.gcTyIndex(.{ .arr = cls });

        const ra = self.reg_arena.allocator();
        const n = self.loop_seq;
        self.loop_seq += 1;
        const base = try std.fmt.allocPrint(ra, "__iter{d}", .{n});
        const cur = try std.fmt.allocPrint(ra, "__idx{d}", .{n});
        const len = try std.fmt.allocPrint(ra, "__len{d}", .{n});
        const acc = try std.fmt.allocPrint(ra, "__acc{d}", .{n});
        const out = try std.fmt.allocPrint(ra, "__out{d}", .{n});
        try self.declareLocal(base, ar);
        try self.declareLocal(cur, .i32);
        try self.declareLocal(len, .i32);

        const acc_param0: ?[]const u8 = if (hof == fold and lam.params.len > 0) lam.params[0] else null;
        const elem_param0: ?[]const u8 = if (hof == fold)
            (if (lam.params.len > 1) lam.params[1] else null)
        else if (lam.params.len > 0) lam.params[0] else null;
        const acc_ty: Repr = if (hof == fold) (if (init_expr) |i| self.wasmTypeOf(i) else .i32) else .i32;
        const acc_param: ?[]const u8 = if (acc_param0) |p| try self.bindTargetAs(p, acc_ty) else null;
        const elem_param: ?[]const u8 = if (elem_param0) |p| try self.bindTargetAs(p, er) else null;
        try self.declareLocal(acc, acc_ty);
        if (elem_param) |p| {
            try self.declareLocal(p, er);
            try self.noteElemShape(p, recv);
            if (self.elemKindOf(recv) == .str) try self.str_locals.put(p, {});
            if (elem_bool) try self.bool_locals.put(p, {});
            if (self.elemTypeRefOf(recv)) |et| try self.noteTypedBinder(p, et);
            if (self.elemTypeRefOf(recv)) |et| if (et == .generic and self.record_generics.contains(et.generic.name)) try self.local_typerefs.put(p, et);
            if (self.elemTypeRefOf(recv)) |et| if (isUnknownTypeRef(et)) try self.local_typerefs.put(p, et);
            if (self.elemRecordOf(recv)) |r| try self.local_types.put(p, r);
        }
        if (acc_param) |p| {
            try self.declareLocal(p, acc_ty);
            if (init_expr) |i| if (self.isStringExpr(i)) try self.str_locals.put(p, {});
        }

        try self.lowerCoerced(recv, ar);
        try self.emit(.{ .local_set = base });
        if (elem_param0) |p| self.installShadow(p, elem_param.?);
        if (acc_param0) |p| self.installShadow(p, acc_param.?);
        try self.emit(.{ .local_get = base });
        try self.emit(.array_len);
        try self.emit(.{ .local_set = len });
        try self.emit(zero);
        try self.emit(.{ .local_set = cur });
        // `map`'s out array is of the class of what the body answers.
        var out_cls: Repr.Elem = cls;
        var tail_ty: Repr = .i32;
        if (hof == map) {
            tail_ty = self.gcMapTail(lam, recv);
            out_cls = gcElemClassOf(tail_ty);
        }
        const oti = self.gcTyIndex(.{ .arr = out_cls });
        switch (hof) {
            map, filter => {
                try self.declareLocal(out, .{ .ref = .{ .arr = out_cls } });
                try self.emit(.{ .local_get = len });
                try self.emit(.{ .array_new_default = oti });
                try self.emit(.{ .local_set = out });
                try self.emit(zero);
                try self.emit(.{ .local_set = acc });
            },
            fold => {
                try self.lowerCoerced(init_expr.?, acc_ty);
                try self.emit(.{ .local_set = acc });
            },
            all => {
                try self.emit(one);
                try self.emit(.{ .local_set = acc });
            },
            find_index => {
                try self.emit(try self.constInt(-1));
                try self.emit(.{ .local_set = acc });
            },
            else => {
                try self.emit(zero);
                try self.emit(.{ .local_set = acc });
            },
        }

        var loop_c: Capture = .{};
        self.open(&loop_c);
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, .{ .local_get = len });
        try self.emitAt(8, opOf(.i32, "ge_s"));
        try self.emitAt(8, .{ .br_if = break_label });
        if (hof == find_index) {
            try self.emitAt(8, .{ .local_get = acc });
            try self.emitAt(8, try self.constInt(-1));
            try self.emitAt(8, opOf(.i32, "ne"));
            try self.emitAt(8, .{ .br_if = break_label });
        }
        if (elem_param) |p| {
            try self.emitAt(8, .{ .local_get = base });
            try self.emitAt(8, .{ .local_get = cur });
            try self.emitAt(8, .{ .array_get = .{ .ty = ti } });
            if (cls == .any) try self.gcUnbox(er);
            try self.emitAt(8, .{ .local_set = p });
        }
        if (acc_param) |p| {
            try self.emitAt(8, .{ .local_get = acc });
            try self.emitAt(8, .{ .local_set = p });
        }
        switch (hof) {
            for_each => for (lam.body) |stmt| {
                _ = try self.emitStmt(stmt, false);
            },
            map => {
                try self.emit(.{ .local_get = out });
                try self.emit(.{ .local_get = cur });
                const r = try self.gcInlineTail(lam.body, tail_ty);
                if (out_cls == .any) try self.gcBox(r);
                try self.emit(.{ .array_set = oti });
            },
            fold => {
                _ = try self.gcInlineTail(lam.body, acc_ty);
                try self.emit(.{ .local_set = acc });
            },
            else => {
                _ = try self.gcInlineTail(lam.body, .i32);
                var then_c: Capture = .{};
                self.open(&then_c);
                switch (hof) {
                    filter => {
                        try self.emit(.{ .local_get = out });
                        try self.emit(.{ .local_get = acc });
                        try self.emit(.{ .local_get = base });
                        try self.emit(.{ .local_get = cur });
                        try self.emit(.{ .array_get = .{ .ty = ti } });
                        try self.emit(.{ .array_set = ti });
                        try self.emit(.{ .local_get = acc });
                        try self.emit(one);
                        try self.emit(opOf(.i32, "add"));
                        try self.emit(.{ .local_set = acc });
                    },
                    all => {
                        try self.emit(zero);
                        try self.emit(.{ .local_set = acc });
                    },
                    any => {
                        try self.emit(one);
                        try self.emit(.{ .local_set = acc });
                    },
                    count => {
                        try self.emit(.{ .local_get = acc });
                        try self.emit(one);
                        try self.emit(opOf(.i32, "add"));
                        try self.emit(.{ .local_set = acc });
                    },
                    else => {
                        try self.emit(.{ .local_get = cur });
                        try self.emit(.{ .local_set = acc });
                    },
                }
                const then_seq = self.seal(&then_c, .none);
                if (hof == all) try self.emit(opOf(.i32, "eqz"));
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq } } });
            },
        }
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, one);
        try self.emitAt(8, opOf(.i32, "add"));
        try self.emitAt(8, .{ .local_set = cur });
        try self.emitAt(8, .{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);
        try self.emitLoopBlock(loop_seq, null);
        switch (hof) {
            for_each => {},
            map => try self.emit(.{ .local_get = out }),
            filter => {
                try self.emit(.{ .local_get = out });
                try self.emit(zero);
                try self.emit(.{ .local_get = acc });
                try self.emit(.{ .call = try self.gcArrOp("slice", cls) });
            },
            else => try self.emit(.{ .local_get = acc }),
        }
    }

    /// The wasm type an inlined lambda body leaves (its tail, or the value of a
    /// trailing `return`).
    fn lambdaTailType(self: *Emitter, body: []const ast.Stmt) Repr {
        if (body.len == 0) return .i32;
        const last = body[ast.lastRealIndex(body)].expr;
        return switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |v| self.wasmTypeOf(v.*) else .i32,
                else => .i32,
            },
            else => self.wasmTypeOf(last),
        };
    }

    // ── array element shapes ─────────────────────────────────────────────────

    /// `f64`: each slot holds the address of the element's `f64` cell
    /// (`emitToFloatSlot`).
    const ElemKind = enum { i32, f64, str };

    /// Whether `t` is an array (`T[]`, `Array<T>`) whose element is a union or
    /// `unknown` — its slots hold boxes (`lowerArrayLit`).
    fn isUnionArrayTypeRef(t: ast.TypeRef) bool {
        const elem: ast.TypeRef = switch (t) {
            .array => |inner| inner.*,
            .generic => |g| if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array")) g.args[0] else return false,
            else => return false,
        };
        return isUnknownTypeRef(elem);
    }

    /// The member an element of an array literal is, by what this backend
    /// can tell of it: a string, a bool, a float, an integer, or the record it
    /// constructs. Null when it cannot tell.
    fn litMemberName(self: *Emitter, e: ast.Expr) ?[]const u8 {
        if (self.isStringExpr(e)) return "string";
        if (self.isBoolExpr(e)) return "bool";
        if (self.isTaggedValue(e)) return self.recordTypeOfExpr(e);
        const t = self.wasmTypeOf(e);
        if (t.isFloat()) return "f64";
        if (t.isI64()) return "i64";
        if (self.isKnownInteger(e)) return "i32";
        return null;
    }

    /// Decision 150 (decision 8 §3.2) — `[1, "a"]` is `(i32 | string)[]`: the
    /// literal's elements disagree, and each member they are is one of the
    /// union's. Numbers alone (`[1, 2.5]`) are not a union here: they widen.
    /// Null when the elements agree or one cannot be told.
    fn unionArrayLitTypeRef(self: *Emitter, al: anytype) !?ast.TypeRef {
        if (al.elems.len < 2) return null;
        const ar = self.reg_arena.allocator();
        var members: std.ArrayListUnmanaged(ast.TypeRef) = .empty;
        var numeric_only = true;
        for (al.elems) |el| {
            const m = self.litMemberName(el) orelse return null;
            const numeric = std.mem.eql(u8, m, "i32") or std.mem.eql(u8, m, "f64") or std.mem.eql(u8, m, "i64");
            if (!numeric) numeric_only = false;
            const seen = for (members.items) |x| {
                if (std.mem.eql(u8, x.named, m)) break true;
            } else false;
            if (!seen) try members.append(ar, .{ .named = m });
        }
        if (members.items.len < 2 or numeric_only) return null;
        const inner = try ar.create(ast.TypeRef);
        inner.* = .{ .generic = .{ .name = ast.union_type_name, .args = members.items, .is_builtin = false } };
        return .{ .array = inner };
    }

    /// The element shape a `T[]` / `Array<T>` type spells, when it is an array.
    fn arrayElemOfTypeRef(t: ast.TypeRef) ?ElemKind {
        const elem: ast.TypeRef = switch (eagerTypeRef(t)) {
            .array => |inner| inner.*,
            // An iterator runs eagerly here: it is the array of what it yields.
            .generic => |g| if (g.args.len == 1 and (std.mem.eql(u8, g.name, "Array") or
                std.mem.eql(u8, g.name, "Iterator") or std.mem.eql(u8, g.name, "Stream")))
                g.args[0]
            else
                return null,
            .optional => |inner| return arrayElemOfTypeRef(inner.*),
            else => return null,
        };
        return elemKindOfTypeRef(elem);
    }

    fn elemKindOfTypeRef(t: ast.TypeRef) ElemKind {
        return switch (t) {
            .named => |n| if (std.mem.eql(u8, n, "string"))
                .str
            else if (std.mem.eql(u8, n, "f32") or std.mem.eql(u8, n, "f64"))
                .f64
            else
                .i32,
            else => .i32,
        };
    }

    /// Record what a parameter's declared type says about its value.
    fn noteParamShape(self: *Emitter, sym: []const u8, t: ast.TypeRef) !void {
        if (isStringTypeRef(t)) try self.str_locals.put(sym, {});
        if (isBoolTypeRef(t)) try self.bool_locals.put(sym, {});
        if (arrayElemOfTypeRef(t)) |ek| {
            try self.arr_locals.put(sym, {});
            try self.arr_elem_locals.put(sym, ek);
        }
        if (self.elemRecordOfTypeRef(t)) |rec| try self.arr_elem_recs.put(sym, rec);
        if (resultShapeOfTypeRef(t)) |shape| try self.result_shape_locals.put(sym, shape);
    }

    /// A binder the source did not annotate but whose type is known from
    /// where it is bound — a `case` arm's `Ok(v)` / `Error(e)` over a declared
    /// `@Result`, a `for` element over a declared array or iterator: it gets
    /// everything a parameter of that type gets, so a string payload prints as
    /// text, a record payload's fields are found, a nested `@Result` can be
    /// matched again.
    fn noteTypedBinder(self: *Emitter, sym: []const u8, t: ast.TypeRef) !void {
        if (self.resolveRecordName(typeRefName(t))) |rty| try self.local_types.put(sym, rty);
        try self.noteParamShape(sym, t);
        try self.local_typerefs.put(sym, t);
    }

    /// The declared element type of what a `for` walks — an array, an
    /// `Array<T>`, an eager `@Iterator<T>` / `@Stream<T>` — when its type is
    /// known.
    /// `e` is declared `Children`, the compiler-known markup child list. Its
    /// coercion is type-level only (`codegen/AGENTS.md`), so a value the
    /// program built is the `[len][e0]…` blob of an array literal — what
    /// `for (e.children)` walks; its element is a word the loop binds untyped.
    fn isChildrenTyped(self: *Emitter, e: ast.Expr) bool {
        const t = self.typeRefOf(e) orelse return false;
        return t == .named and std.mem.eql(u8, t.named, "Children");
    }

    fn elemTypeRefOf(self: *Emitter, e: ast.Expr) ?ast.TypeRef {
        const t = eagerTypeRef(self.typeRefOf(e) orelse return null);
        return switch (t) {
            .array => |inner| inner.*,
            .generic => |g| if (g.args.len == 1 and (std.mem.eql(u8, g.name, "Array") or
                std.mem.eql(u8, g.name, "Iterator") or std.mem.eql(u8, g.name, "Stream")))
                g.args[0]
            else
                null,
            else => null,
        };
    }

    /// A local bound to something `isArrayExpr` recognises is an array too,
    /// with the element shape of its initialiser.
    fn noteArrayLocal(self: *Emitter, name: []const u8, value: ast.Expr) !void {
        if (try self.printShapeOf(value)) |shape| try self.print_shape_locals.put(name, shape);
        if (!self.isArrayExpr(value)) return;
        try self.arr_locals.put(name, {});
        try self.arr_elem_locals.put(name, self.elemKindOf(value));
        if (self.elemRecordOf(value)) |rec| try self.arr_elem_recs.put(name, rec) else _ = self.arr_elem_recs.remove(name);
    }

    /// A local whose written type is an array: the element shape, kind and
    /// record the TYPE names, over whatever its initialiser suggested.
    fn noteAnnotatedArray(self: *Emitter, name: []const u8, ta: ast.TypeRef) !void {
        if (ta == .optional) return;
        const ek = arrayElemOfTypeRef(ta) orelse return;
        try self.arr_locals.put(name, {});
        try self.arr_elem_locals.put(name, ek);
        if (try self.typeRefShape(ta)) |sh| try self.print_shape_locals.put(name, sh);
        if (self.elemRecordOfTypeRef(ta)) |rec| try self.arr_elem_recs.put(name, rec);
    }

    /// The shape `$__print_shaped_raw` walks for `e` (semantics decision 1a):
    /// `i` an i32, `f` a float's cell, `b` a bool, `s` a string, `[X` an array of
    /// `X`, `(XY…)` a tuple. Null when `e` is not known to be an array or a
    /// tuple.
    fn printShapeOf(self: *Emitter, e: ast.Expr) anyerror!?[]const u8 {
        // 144 B-142 — a generator's `toArray()` is the array of its items.
        if (self.genMethodOf(e)) |m| if (m == .to_array) {
            const yitem = (try self.genItemOf(e.call.kind.call.receiver.?.*)) orelse return null;
            const it = reprTypeRef(yitem) orelse return null;
            if (try self.typeRefShape(it)) |inner| return try std.fmt.allocPrint(self.arena(), "[{s}", .{inner});
            const code = scalarCode(it) orelse return null;
            return try std.fmt.allocPrint(self.arena(), "[{c}", .{code});
        };
        if (self.genericResultOf(e)) |a| return self.printShapeOf(a);
        if (self.unitEnumOf(e)) |en| return try self.unitEnumShape(en);
        // `o ?? d` (decision 330: `?T`'s `unwrapOr` is `??`) answers the
        // payload or `d`, one type — read as `o.unwrapOr(d)` is below.
        if (nullishParts(e)) |nu| {
            if (self.optInfoOf(nu.opt.*)) |oi| if (oi.shape) |sh| return sh;
            if (!isEmptyArrayLit(nu.dflt)) if (try self.printShapeOf(nu.dflt)) |sh| return sh;
        }
        if (optOperatorParts(e)) |op| if (op.bang) if (self.optInfoOf(op.cond.*)) |oi| if (oi.shape) |sh| return sh;
        switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| {
                    const rn = self.resolveName(n);
                    if (self.print_shape_locals.get(rn)) |shape| return shape;
                    if (!self.locals.contains(rn)) if (self.print_shape_globals.get(rn)) |shape| return shape;
                },
                // A tuple element that is itself a container — `t._0` of
                // `#(#(1, 2), "x")`. The same slice `isStringExpr` takes, kept
                // only when it is an array or a tuple, which is this
                // function's contract.
                .identAccess => if (try self.tupleElemShapeOf(e)) |el| {
                    if (el[0] == '[' or el[0] == '(') return el;
                },
                else => {},
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.printShapeOf(inner.*),
                .tupleLit => |tl| {
                    var out: std.ArrayListUnmanaged(u8) = .empty;
                    try out.append(self.arena(), '(');
                    for (tl.elems) |el| try out.appendSlice(self.arena(), try self.valueShapeOf(el));
                    try out.append(self.arena(), ')');
                    return out.items;
                },
                .arrayLit => |al| if (al.elems.len > 0) {
                    if ((try self.unionArrayLitTypeRef(al)) != null) {
                        if (self.mode != .gc) self.builder().helpers.require(.print_shaped_unknown);
                        return "[U";
                    }
                    if (try self.printShapeOf(al.elems[0])) |inner| return try std.fmt.allocPrint(self.arena(), "[{s}", .{inner});
                    if (self.isTaggedValue(al.elems[0])) return "[T";
                    // A bool is an `i32` slot like an integer; only the shape
                    // tells the printer to write `true` (`[1, 0]` at exit 0).
                    if (self.isBoolExpr(al.elems[0])) return "[b";
                },
                else => {},
            },
            .call => |c| switch (c.kind) {
                .call => |cc| {
                    // `o.unwrapOr(d)` answers the payload or `d`, one type:
                    // the payload's declared shape (`r.unwrapOr([])` over an
                    // `@Result<Array<#(string, string)>, …>`), the optional's
                    // own, or a container default's (`pairs.at(1).unwrapOr(
                    // #("", ""))._1`) — an empty `[]` says nothing. Each
                    // printed a string's address at exit 0.
                    if (isUnwrapOr(cc)) {
                        if (self.typeRefOf(cc.args[0].value.*)) |tr| if (tr == .generic and tr.generic.args.len == 2 and
                            std.mem.endsWith(u8, tr.generic.name, "Result"))
                        {
                            if (try self.typeRefShape(tr.generic.args[0])) |sh| return sh;
                        };
                        if (self.optInfoOf(cc.args[0].value.*)) |oi| if (oi.shape) |sh| return sh;
                        if (!isEmptyArrayLit(cc.args[1].value.*)) if (try self.printShapeOf(cc.args[1].value.*)) |sh| return sh;
                    }
                    if (std.mem.eql(u8, cc.callee, "zip") and cc.args.len == 1 and cc.receiver != null) {
                        if (self.primKindAt(cc, c.loc) == .array) return try std.fmt.allocPrint(self.arena(), "[({c}{c})", .{
                            elemCode(self.elemKindOf(cc.receiver.?.*)),
                            elemCode(self.elemKindOf(cc.args[0].value.*)),
                        });
                    }
                    // `rows[1]` keeps the shape of one element of `rows`.
                    if (try self.indexElemShape(cc)) |inner| return inner;
                    if (try self.newArrShape(cc, c.loc)) |sh| return sh;
                    // `rows.reverse()`, `bs.filter(…)`: the receiver's elements,
                    // so the receiver's shape — a nested array printed its
                    // rows' addresses, a bool array `[1, 0]`.
                    if (cc.receiver != null and keepsElements(cc.callee)) if (self.primKindAt(cc, c.loc)) |k| if (k == .array) {
                        if (try self.printShapeOf(cc.receiver.?.*)) |sh| return sh;
                    };
                },
                else => {},
            },
            else => {},
        }
        // A `@Result` — a call to a fn declared to answer one, a local, a
        // parameter or a field of one — prints `Ok(…)` / `Error(…)` by the
        // shapes of its two payloads.
        if (self.resultShapeOf(e)) |rs| if (rs.ok) |ok| if (rs.err) |err| if (try self.resultTypeShape(ok, err)) |sh| return sh;
        // A parameter, a fn result or a local whose declared type spells a tuple.
        if (self.typeRefOf(e)) |tr| if (try self.typeRefShape(tr)) |shape| return shape;
        if (!self.isArrayExpr(e)) return null;
        return switch (self.elemKindOf(e)) {
            .i32 => "[i",
            .f64 => "[f",
            .str => "[s",
        };
    }

    /// The print shape a declared type spells, when it holds a tuple or a
    /// string somewhere inside an array or a tuple; null for anything the
    /// shape codes cannot describe (a record, an enum, a map).
    fn typeRefShape(self: *Emitter, t: ast.TypeRef) anyerror!?[]const u8 {
        switch (t) {
            .tuple_, .labeledTuple => {
                const elems = t.tupleElems().?;
                var out: std.ArrayListUnmanaged(u8) = .empty;
                try out.append(self.arena(), '(');
                for (elems) |el| {
                    if (el == .optional) {
                        const oi = self.optInfoOfTypeRef(el) orelse return null;
                        try out.appendSlice(self.arena(), (try self.optElemShape(oi, null)) orelse return null);
                        continue;
                    }
                    if (try self.typeRefShape(el)) |inner| {
                        try out.appendSlice(self.arena(), inner);
                        continue;
                    }
                    // A 64-bit integer element's slot holds its cell.
                    if (el == .named) if (i64CellCode(el.named)) |c| {
                        try out.append(self.arena(), c);
                        continue;
                    };
                    try out.append(self.arena(), scalarCode(el) orelse return null);
                }
                try out.append(self.arena(), ')');
                return out.items;
            },
            .array => |inner| return self.arrayTypeShape(inner.*),
            .generic => |g| {
                if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array")) return self.arrayTypeShape(g.args[0]);
                if (std.mem.endsWith(u8, g.name, "Result") and g.args.len == 2) return self.resultTypeShape(g.args[0], g.args[1]);
                // A generic record (`Queue<i32>`) carries its declaration too.
                if (self.records.contains(g.name)) return "T";
            },
            // A written record type: the element carries its own declaration.
            .named => |n| {
                // Decision 332 — a `bigint` slot holds its block's address,
                // printed by the `n` code, which the `bigint` group's module
                // links (`print_shaped_items_bigint`).
                if (std.mem.eql(u8, n, "bigint")) {
                    self.builder().helpers.require(.bigint);
                    return "n";
                }
                if (self.records.contains(n)) return "T";
                if (self.isAllUnitEnum(n)) return try self.unitEnumShape(n);
            },
            else => {},
        }
        return null;
    }

    /// `R<ok><err>`: the print shape of a `@Result<Ok, Err>` — the shape of
    /// each payload, a word at +4 of the `{ tag, payload }` pair. Null when a
    /// payload has no shape code (a float or an `i64` cannot be held at all).
    fn resultTypeShape(self: *Emitter, ok: ast.TypeRef, err: ast.TypeRef) anyerror!?[]const u8 {
        var out: std.ArrayListUnmanaged(u8) = .empty;
        try out.append(self.arena(), 'R');
        for ([_]ast.TypeRef{ ok, err }) |side| {
            if (try self.typeRefShape(side)) |inner| {
                try out.appendSlice(self.arena(), inner);
                continue;
            }
            if (side == .named and self.enums.contains(side.named) and !self.isAllUnitEnum(side.named)) {
                try out.append(self.arena(), 'T');
                continue;
            }
            const code = scalarCode(side) orelse return null;
            if (code == 'f') return null;
            try out.append(self.arena(), code);
        }
        return out.items;
    }

    fn arrayTypeShape(self: *Emitter, elem: ast.TypeRef) anyerror!?[]const u8 {
        // A union's (or `unknown`'s) slot is a box that names what it holds.
        if (isUnknownTypeRef(elem)) {
            if (self.mode != .gc) self.builder().helpers.require(.print_shaped_unknown);
            return "[U";
        }
        if (try self.typeRefShape(elem)) |inner| return try std.fmt.allocPrint(self.arena(), "[{s}", .{inner});
        // An array OF arrays of a scalar — `i32[][]` — is a container whose
        // elements are pointers (`elemIsPointer`), whatever its innermost
        // code: without the shape, `rows.at(1)` boxed the row's address and
        // printed it as a number.
        const nested: ?ast.TypeRef = switch (elem) {
            .array => |ie| ie.*,
            .generic => |g| if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array")) g.args[0] else null,
            else => null,
        };
        if (nested) |ie| if (scalarCode(ie)) |c| return try std.fmt.allocPrint(self.arena(), "[[{c}", .{c});
        return switch (scalarCode(elem) orelse return null) {
            's' => "[s",
            'b' => "[b",
            else => null,
        };
    }

    /// The shape of a record written as a FIELD's type is `T` — its own
    /// header names it, and `$__print_shaped_raw`'s `T` arm reads that.
    /// The shape code of a scalar named type: `i` an integer, `f` a float, `b`
    /// a bool, `s` a string.
    fn scalarCode(t: ast.TypeRef) ?u8 {
        const n = switch (t) {
            .named => |n| n,
            else => return null,
        };
        if (std.mem.eql(u8, n, "string")) return 's';
        if (std.mem.eql(u8, n, "bool")) return 'b';
        if (std.mem.eql(u8, n, "i32") or std.mem.eql(u8, n, "int") or std.mem.eql(u8, n, "Int")) return 'i';
        if (std.mem.eql(u8, n, "f32") or std.mem.eql(u8, n, "f64") or std.mem.eql(u8, n, "float")) return 'f';
        return null;
    }

    /// The shape of the element `t._N` reads — **scalar codes included**, which
    /// is what tells it apart from `printShapeOf`. `printShapeOf(t)` already
    /// builds the whole tuple's shape (`((ii)s)` for `#(#(1, 2), "x")`, `(si)`
    /// for a `#(name: string, pop: i32)`), so element `N` only has to be sliced
    /// out of it; nothing else in this backend knew an element's type.
    ///
    /// Both readers of an element need it and neither could ask the other:
    /// `printShapeOf`'s contract is to answer only containers, while
    /// `isStringExpr` is the question `@print` asks about a **single** value.
    /// While only the container half existed, `@print(t.1)` and `@print(row.name)`
    /// printed the element's heap address — `256` where they mean `x` and `SP` —
    /// with exit 0 and no diagnostic.
    ///
    /// A label is not a case here: the checker resolves `row.name` to `row._0`
    /// before this backend sees it (decision 8 §6 T4), so the member is always
    /// `_N` or a bare `N`.
    fn tupleElemShapeOf(self: *Emitter, e: ast.Expr) anyerror!?[]const u8 {
        const ia = switch (e) {
            .identifier => |id| switch (id.kind) {
                .identAccess => |a| a,
                else => return null,
            },
            else => return null,
        };
        if (ia.optional) return null;
        const idx = tupleIndex(ia.member) orelse return null;
        const sh = (try self.printShapeOf(ia.receiver.*)) orelse return null;
        return tupleShapeElem(sh, idx);
    }

    /// The shape of the element `recv?._N` reads off an optional tuple: the
    /// receiver's payload shape (`rs.at(1)` over a `#(a: i32, b: string)[]`),
    /// else its print shape behind its `?`.
    fn optTupleElemShapeOf(self: *Emitter, ia: anytype) anyerror!?[]const u8 {
        const idx = tupleIndex(ia.member) orelse return null;
        if (self.optInfoOf(ia.receiver.*)) |oi| if (oi.shape) |psh| return tupleShapeElem(psh, idx);
        var sh = (try self.printShapeOf(ia.receiver.*)) orelse return null;
        if (sh.len > 0 and sh[0] == '?') sh = sh[1..];
        return tupleShapeElem(sh, idx);
    }

    /// The length of the element shape starting at `sh[0]`: `i`/`f`/`b`/`s` are
    /// one byte, `[X` is one plus its element's, `(XY…)` runs to its `)`. The
    /// Zig twin of `$__print_shaped_raw`'s `go = 0` measuring mode, and it has
    /// to agree with it — the two walk the same strings.
    fn shapeSpan(sh: []const u8) usize {
        if (sh.len == 0) return 0;
        switch (sh[0]) {
            '[', '?', '!' => return 1 + shapeSpan(sh[1..]),
            // `R<ok><err>`: a `@Result` is its two payload shapes.
            'R' => {
                const ok = shapeSpan(sh[1..]);
                return 1 + ok + shapeSpan(sh[1 + ok ..]);
            },
            '(' => {
                var i: usize = 1;
                while (i < sh.len and sh[i] != ')') {
                    const n = shapeSpan(sh[i..]);
                    if (n == 0) return i;
                    i += n;
                }
                return if (i < sh.len) i + 1 else i;
            },
            else => return 1,
        }
    }

    /// Element `idx` of the tuple shape `sh` (`(XY…)`), or null when `sh` is
    /// not a tuple shape or has no such element.
    fn tupleShapeElem(sh: []const u8, idx: u32) ?[]const u8 {
        if (sh.len == 0 or sh[0] != '(') return null;
        var i: usize = 1;
        var k: u32 = 0;
        while (i < sh.len and sh[i] != ')') {
            const n = shapeSpan(sh[i..]);
            if (n == 0) return null;
            if (k == idx) return sh[i .. i + n];
            i += n;
            k += 1;
        }
        return null;
    }

    /// The shape of one element of a tuple.
    fn valueShapeOf(self: *Emitter, e: ast.Expr) anyerror![]const u8 {
        // A `?T` element: its slot is the optional's carrier, `0` absence.
        // Read through its payload's code it printed the box's address
        // (`#(1, 328)` for `#(1, [7].at(0))`) at exit 0.
        // One whose payload is not known here is refused — in a generic
        // body, the body is marked instead (`template_traps`): a concrete
        // call that reaches it unspecialised is refused at the call.
        if (self.optInfoOf(e)) |oi| {
            if (try self.optElemShape(oi, e)) |sh| return sh;
            if (self.cur_template) |t| {
                try self.template_traps.put(self.reg_arena.allocator(), t, {});
                return "!i";
            }
            return self.refuse(e.getLoc(), "the wasm backend has no printed form for this optional inside a tuple or an array: its payload's type is not known here", .{});
        }
        if (try self.printShapeOf(e)) |shape| return shape;
        // A value that carries its own declaration reads its text from the
        // header (13-module-identity half 3), so a tuple or an array holding
        // one names its type too.
        if (self.isTaggedValue(e)) return "T";
        if (self.isStringExpr(e)) return "s";
        if (self.isBoolExpr(e)) return "b";
        if (self.wasmTypeOf(e).isFloat()) return "f";
        if (self.wasmTypeOf(e).isI64()) return if (self.isU64Expr(e)) "u" else "l";
        return "i";
    }

    /// The print shape of a `?T` held in a tuple's or an array's slot:
    /// `?X` when the slot is the payload's own pointer (a string, a record, a
    /// container) or its 8-byte cell (`?f64`, `?i64`), `!X` when the payload
    /// is a scalar in a `$__box_i32` cell — `0` is absence in both, printed
    /// `null`. Null when the payload's code is not known here (a `?T` over a
    /// type parameter, an all-unit enum): the caller refuses.
    fn optElemShape(self: *Emitter, oi: OptInfo, e: ?ast.Expr) anyerror!?[]const u8 {
        _ = e;
        const inner_name: ?[]const u8 = if (oi.inner) |inner| switch (inner) {
            .named => |n| n,
            else => null,
        } else null;
        if (oi.boxed) {
            if (oi.cell == .f64) return "?f";
            if (oi.cell == .i64) return if (optIsU64(oi)) "?u" else "?l";
            if (oi.bool_) return "!b";
            const n = inner_name orelse return if (oi.inner == null) "!i" else null;
            if (std.mem.eql(u8, n, "bool")) return "!b";
            return if (scalarCode(.{ .named = n }) == @as(?u8, 'i')) "!i" else null;
        }
        if (oi.str) return "?s";
        if (oi.rec != null) return "?T";
        if (oi.shape) |sh| return try std.fmt.allocPrint(self.arena(), "?{s}", .{sh});
        if (oi.inner) |inner| {
            if (try self.typeRefShape(inner)) |sh| return try std.fmt.allocPrint(self.arena(), "?{s}", .{sh});
            if (scalarCode(inner) == @as(?u8, 's')) return "?s";
        }
        return null;
    }

    fn elemCode(k: ElemKind) u8 {
        return switch (k) {
            .i32 => 'i',
            .f64 => 'f',
            .str => 's',
        };
    }

    /// Best-effort element shape of an array-valued expression. `i32` covers
    /// integers, bools and pointers alike.
    fn elemKindOf(self: *Emitter, e: ast.Expr) ElemKind {
        if (self.genericResultOf(e)) |a| return self.elemKindOf(a);
        // `o ?? d` over an optional array: the elements are the optional's
        // (`(m?.list ?? []).join(",")`); an empty default says nothing.
        if (nullishParts(e)) |nu| {
            if (self.typeRefOf(nu.opt.*)) |ot| if (arrayElemOfTypeRef(ot)) |ek| return ek;
            if (!isEmptyArrayLit(nu.dflt)) return self.elemKindOf(nu.dflt);
        }
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| self.arr_elem_locals.get(self.resolveName(n)) orelse self.arr_elem_globals.get(self.resolveName(n)) orelse .i32,
                // A record FIELD declared as an array: its element shape is in
                // the field's declared type, and reading it is what tells
                // `self.cells.at(0)` it is a `?string` and not a boxed `?i32`.
                // While this arm answered `.i32` unconditionally, `(self.cells
                // .at(0) ?? "").length()` and its narrowed twin read the box
                // as a string pointer and printed a heap address at exit 0.
                .identAccess => blk: {
                    const tr = self.typeRefOf(e) orelse break :blk .i32;
                    break :blk arrayElemOfTypeRef(tr) orelse .i32;
                },
                else => .i32,
            },
            .loop => |lp| self.yieldElemKind(lp.body),
            .jump => if (self.tryPayloadTypeRef(e)) |t| arrayElemOfTypeRef(t) orelse .i32 else .i32,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.elemKindOf(inner.*),
                .arrayLit => |al| blk: {
                    if (al.elems.len == 0) break :blk .i32;
                    // A union's slots are boxes, whatever the members are.
                    if ((self.unionArrayLitTypeRef(al) catch null) != null) break :blk .i32;
                    const first = al.elems[0];
                    if (self.isStringExpr(first)) break :blk .str;
                    // A float anywhere makes it a float array: `[1, 2.5]`.
                    for (al.elems) |el| if (self.wasmTypeOf(el).isFloat()) break :blk .f64;
                    break :blk .i32;
                },
                else => .i32,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (self.primKindAt(cc, c.loc)) |k| switch (k) {
                        .string => break :blk .str, // split
                        .array => {
                            const recv = cc.receiver.?.*;
                            if (std.mem.eql(u8, cc.callee, "map")) {
                                const lam = lambdaAt(cc, 0) orelse {
                                    // `xs.map(inc)`: the named function's
                                    // declared return.
                                    const fname = if (cc.args.len == 1) switch (cc.args[0].value.*) {
                                        .identifier => |id| switch (id.kind) {
                                            .ident => |n| n,
                                            else => break :blk .i32,
                                        },
                                        else => break :blk .i32,
                                    } else break :blk .i32;
                                    const rt = self.fn_ret_typerefs.get(self.import_aliases.get(fname) orelse fname) orelse break :blk .i32;
                                    break :blk elemKindOfTypeRef(rt);
                                };
                                if (lam.body.len == 0) break :blk .i32;
                                const last = lam.body[ast.lastRealIndex(lam.body)].expr;
                                const v = switch (last) {
                                    .jump => |j| switch (j.kind) {
                                        .@"return" => |r| if (r) |x| x.* else break :blk .i32,
                                        else => break :blk .i32,
                                    },
                                    else => last,
                                };
                                // The tail reads the ELEMENT parameter, whose
                                // record type `lowerArrayHof` binds only while
                                // it lowers the body — so it is bound here for
                                // the duration of the question (`00 · 05-wasm`
                                // step 9). Unbound, `es.map({ e -> e.key })`
                                // answered `.i32` and `ks.at(0)` was read as a
                                // boxed `?i32`: a heap address at exit 0.
                                const held = self.holdElemParam(lam, recv);
                                defer self.releaseElemParam(held);
                                if (self.isStringExpr(v)) break :blk .str;
                                if (self.wasmTypeOf(v).isFloat()) break :blk .f64;
                                break :blk .i32;
                            }
                            // `05-wasm` step 1's arrays: their element is
                            // read off the shape they build.
                            if ((self.newArrShape(cc, c.loc) catch null)) |sh| {
                                if (sh.len >= 2) break :blk switch (sh[1]) {
                                    's' => .str,
                                    'f' => .f64,
                                    else => .i32,
                                };
                            }
                            // A method the array family does not know (a library's
                            // `toArray()` answering `Array<string>`) answers its
                            // declared element, not the receiver's.
                            if (primCallRes(.array, cc) == null) if (self.typeRefOf(e)) |t| if (arrayElemOfTypeRef(t)) |ek| break :blk ek;
                            break :blk self.elemKindOf(recv);
                        },
                        else => break :blk .i32,
                    };
                    // `xs[a..b]` keeps the elements of `xs`
                    if (self.indexArgs(cc)) |ix| break :blk if (ix.is_slice) self.elemKindOf(ix.recv) else .i32;
                    if (cc.is_builtin) break :blk .i32;
                    if (cc.receiver != null) if (self.typeRefOf(e)) |t| if (arrayElemOfTypeRef(t)) |k| if (k != .i32) break :blk k;
                    if (self.resolvedCallSym(cc, c.loc)) |sym| break :blk self.fn_arr_elem.get(sym) orelse .i32;
                    if (self.valueCallTypeRef(cc)) |t| if (arrayElemOfTypeRef(t)) |k| break :blk k;
                    break :blk self.fn_arr_elem.get(cc.callee) orelse .i32;
                },
                else => .i32,
            },
            else => .i32,
        };
    }

    /// What `holdElemParam` displaced, so `releaseElemParam` can put it back.
    const HeldElemParam = struct {
        name: ?[]const u8 = null,
        prev_type: ?[]const u8 = null,
        prev_str: bool = false,
        /// The name's wasm type and alias before the question: the element
        /// parameter is the element's width while it is asked about, whatever
        /// another local of that name holds (`xs.map({ x -> x * 3.0 })`, then
        /// `[1, 2].map({ x -> x + 1 })` printed its integers as floats).
        prev_local: ?Repr = null,
        prev_alias: ?[]const u8 = null,
        /// The written type the parameter held, when the question set it
        /// (`set_tref`): a primitive element's methods resolve by it
        /// (`primKindAt`).
        prev_tref: ?ast.TypeRef = null,
        set_tref: bool = false,
    };

    /// Bind a HOF lambda's element parameter the way `lowerArrayHof` does —
    /// its record type and its string-ness — so a shape question asked about
    /// the body before it is lowered sees the element and not an unknown name.
    fn holdElemParam(self: *Emitter, lam: LambdaView, recv: ast.Expr) HeldElemParam {
        if (lam.params.len == 0) return .{};
        const p = lam.params[0];
        const held: HeldElemParam = .{
            .name = p,
            .prev_type = self.local_types.get(p),
            .prev_str = self.str_locals.contains(p),
            .prev_local = self.locals.get(p),
            .prev_alias = self.aliases.get(p),
        };
        if (self.elemRecordOf(recv)) |r| self.local_types.put(p, r) catch {};
        if (self.elemKindOf(recv) == .str) self.str_locals.put(p, {}) catch {};
        _ = self.aliases.remove(p);
        self.locals.put(p, if (self.elemKindOf(recv) == .f64) .f64 else .i32) catch {};
        return held;
    }

    fn releaseElemParam(self: *Emitter, held: HeldElemParam) void {
        const p = held.name orelse return;
        if (held.prev_type) |t| self.local_types.put(p, t) catch {} else _ = self.local_types.remove(p);
        if (!held.prev_str) _ = self.str_locals.remove(p);
        if (held.prev_local) |t| self.locals.put(p, t) catch {} else _ = self.locals.remove(p);
        if (held.prev_alias) |a| self.aliases.put(p, a) catch {};
        if (held.set_tref) {
            if (held.prev_tref) |t| self.local_typerefs.put(p, t) catch {} else _ = self.local_typerefs.remove(p);
        }
    }

    // ── function values ──────────────────────────────────────────────────────
    //
    // A lambda used as a value is lifted into a function of its own,
    // `$__lambda{n}(env, a0, …) -> i32`, and listed in the module's function
    // table. The value is a pointer to an environment cell: `[table index]`
    // then one 4-byte slot per captured local, copied at creation (a capture is
    // a snapshot — a lambda that assigns an outer local does not change it).
    // Calling a value is `call_indirect` with the cell as the first argument.
    // Every parameter and the result are `i32`: a float or a 64-bit value
    // travels as the address of its 8-byte cell (`Lifted.param_cell`,
    // `ret_cell`), when the function type says so on both sides
    // (`valueCallCells`); a caller that cannot tell refuses the argument.
    //
    // A lambda passed straight to an array method is not lifted: it is inlined
    // (`lowerArrayHof`), which is what lets `forEach` mutate outer locals.

    const Captured = struct {
        name: []const u8,
        ty: Repr,
        str: bool,
        record: ?[]const u8,
        arr_elem: ?ElemKind,
        /// The written type the name had where the lambda was made (a
        /// parameter's, an annotation's): inside the lambda a field of an
        /// element of a captured `Rule[]` is typed as outside it.
        typeref: ?ast.TypeRef = null,
        bool_: bool = false,
        /// The lambda body assigns it: the environment slot is the variable
        /// while the lambda runs, and a call through a known closure local
        /// copies it in before the call and back out after.
        threaded: bool = false,
    };

    const ParamShape = struct { names: []const []const u8, str: []const bool };

    const FieldLambda = struct { params: []const []const u8, body: []const ast.Stmt };

    const Lifted = struct {
        name: []const u8,
        params: []const []const u8,
        body: []const ast.Stmt,
        captures: []const Captured,
        /// Per parameter: some call through a closure local passed a string
        /// (`lowerValueCall`). The program type-checked, so one proven string
        /// argument makes the parameter a string.
        param_str: []bool = &.{},
        /// Per parameter: the record type the declared function type the
        /// lambda is written against gives it, so `out.tag` reads the slot
        /// `Out` declares rather than guessing one by the field's name.
        param_rec: []const ?[]const u8 = &.{},
        /// Per parameter: the primitive type the declared function type gives
        /// it (`{ x -> x.toString() }` against `fn(x: T)` with `T` bound to
        /// `i32`), so a method on it resolves (`primKindAt`).
        param_tref: []const ?ast.TypeRef = &.{},
        /// Per parameter: something gave it a type — the declared function
        /// type the lambda is written against, a behavior's declaration, or
        /// a call through a closure local passing an argument. A parameter
        /// the body reads that nothing typed is refused where the lambda is
        /// written (`emitLifted`): its word could be a string or an integer,
        /// and guessing printed `300?` for `"d" + "?"` at exit 0.
        param_known: []bool = &.{},
        /// Where the lambda is written: a parameter nothing types is refused
        /// here (`emitLifted`).
        loc: ?ast.Loc = null,
        /// The generic body the lambda is written in (`cur_template`).
        template_of: ?[]const u8 = null,
        /// `Emitter.foreign_origin` where the lambda is written.
        origin: ?ast.Loc = null,
        /// The checker's answers for the module the lambda is written in
        /// (`rewrites`, `instance_lowerings`, `global_renames`): the lambda
        /// is lowered after its module's declarations, when the emitter
        /// holds another module's — a linked module's body lost its
        /// primitive methods (`5.toString()` in an imported component).
        rewrites: ?std.AutoHashMap(ast.Loc, []const u8) = null,
        lowerings: ?std.AutoHashMap(ast.Loc, envMod.InstanceLowering) = null,
        renames: ?*const std.StringHashMapUnmanaged([]const u8) = null,
        /// Set for a trampoline standing for a top-level fn used as a value.
        fn_ref: ?[]const u8 = null,
        /// Per parameter: the cell a float or 64-bit argument arrives in —
        /// the indirect call carries words only, so such an argument is the
        /// address of its `$__box_f64` / `$__box_i64` cell
        /// (`valueCallCells`, the caller's half).
        param_cell: []const Cell = &.{},
        /// The cell a float or 64-bit answer leaves in, the same way.
        ret_cell: Cell = .none,
        /// An `async { }` block: its closure answers the task the block's
        /// state machine runs (decision 392).
        async_block: bool = false,
        /// The lambda's index in `lambdas` and in the function table.
        idx: u32 = 0,
        /// A `.gc` module (front 164 s2 P3) — per parameter, the type the
        /// declared function type the lambda is written against gives it.
        param_ft: []const ?ast.TypeRef = &.{},
        /// The type that function type answers.
        ret_ft: ?ast.TypeRef = null,
        /// Per parameter, the repr of the argument a call through a closure
        /// local passed (a parameter nothing declared takes it).
        param_seen: []?Repr = &.{},
        /// The repr a call through a closure local read the answer as.
        ret_seen: ?Repr = null,
        /// Decision 105 (144 B-128) — an `iter` loop's body: the lambda's
        /// body is a generator state machine and its closure answers the
        /// handle (`lowerGenLoopValue`); `gen_item` is what it yields.
        generator: bool = false,
        gen_item: GenItem = .{ .repr = .i32 },
    };

    // ── decision 392: an asynchronous function is a state machine ───────────
    //
    // `fn f(a) -> @Task<T> { … await t … }` (an `async { }` block and a method
    // answering `@Task` alike) lowers to three functions:
    //
    //   $f(a) -> i32          the task: a frame holding every local, the
    //                         arguments stored in it, `$__task_start(kind,
    //                         frame)` — the task starts when it is made and
    //                         runs to its first `await` (392 (1))
    //   $f__body(task) -> T   the body, entered again at the resume index the
    //                         frame holds: every local restored from it, and
    //                         `$__seek` set until that index is reached
    //   $f__step(task)        `$f__body`, then the task settled with its
    //                         answer — unless the body suspended
    //
    // An `await` on a task still pending saves every local into the frame,
    // records its index there and returns; `$__task_wake` puts the task back
    // in the ready queue when the awaited one settles. Entered again, a
    // statement runs only when the resume index is inside it (`emitStmt`),
    // an `if`'s condition, a `case`'s subject and a loop's start are read
    // back instead of evaluated (`lowerCondition`, `guardStart`), and the
    // `await` the index names clears `$__seek` and answers the settled
    // value. So a loop, a `try` and a `case` holding an `await` are resumed
    // in place. A synchronous function is untouched.

    /// The state machine being lowered: the next resume index (0 is "from
    /// the top").
    const Machine = struct {
        next: u32 = 1,
        /// A GC module's machine: the index of its frame type (`gc_frames`).
        frame: u32 = 0,
    };

    /// The comment line `lowerAwait` writes where a suspension saves the
    /// frame; `emitStateMachine` replaces it with the stores once every local
    /// of the function is known.
    const save_marker = "\x00bp-task-save";
    const sm_task = "__task";
    const sm_frame = "__frame";
    const sm_seek = "__seek";
    const sm_state = "__state";

    fn isMachineLocal(name: []const u8) bool {
        inline for (.{ sm_task, sm_frame, sm_seek, sm_state }) |n| if (std.mem.eql(u8, name, n)) return true;
        return false;
    }

    /// Open a state machine over the function whose state was just reset.
    fn beginMachine(self: *Emitter, body: []const ast.Stmt) !void {
        try self.checkAwaitOrder(body);
        self.machine = .{};
        if (self.mode == .gc) {
            // Front 164 s2 P4 — the task and its typed frame are references;
            // the frame's slots are known once the body is lowered.
            const n: u32 = @intCast(self.gc_frames.items.len);
            try self.gc_frames.append(self.alloc, &.{});
            self.machine.?.frame = n;
            try self.declareLocal(sm_task, .{ .ref = .task });
            try self.declareLocal(sm_frame, .{ .ref = .{ .frame = n } });
            try self.declareLocal(sm_seek, .i32);
            try self.declareLocal(sm_state, .i32);
            return;
        }
        inline for (.{ sm_task, sm_frame, sm_seek, sm_state }) |n| try self.declareLocal(n, .i32);
    }

    /// Whether `e` answers a task (decision 392): a call of a function, a
    /// method or an adapter declaring `@Task<T>`, an `async { }` block, a
    /// function value whose type answers one, a name or a field of that
    /// type. Anything else is awaited as the value it is — an eager
    /// `@Component` is its own value here.
    fn isTaskExpr(self: *Emitter, e: ast.Expr) bool {
        // `o ?? t` over a `?@Task<T>` (front 164 s2 P4, a GC module).
        if (self.mode == .gc) if (nullishParts(e)) |nu| return self.isTaskExpr(nu.dflt);
        return switch (e) {
            .function => |f| f.kind.syntax == .asyncBlock,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.isTaskExpr(inner.*),
                else => false,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (cc.is_builtin) break :blk false;
                    if (cc.receiver != null) if (self.recordMethodSym(cc, c.loc)) |sym| break :blk self.task_syms.contains(sym);
                    if (self.calleeSymbol(cc, c.loc)) |sym| if (self.task_syms.contains(sym)) break :blk true;
                    if (self.valueCallTypeRef(cc)) |t| break :blk isTaskTypeRef(t);
                    break :blk false;
                },
                else => false,
            },
            .identifier => if (self.typeRefOf(e)) |t| isTaskTypeRef(t) else false,
            // `tasks[1]!` over an array of tasks: the task itself.
            .branch => if (optOperatorParts(e)) |op| (if (op.bang) (if (self.typeRefOf(op.cond.*)) |t| (t == .optional and isTaskTypeRef(t.optional.*)) else false) else false) else false,
            else => false,
        };
    }

    /// The type of `val f = { n -> async { … } }` written without an
    /// annotation — `fn(i32) -> @Task<@Result<V, E>>` (`@Task<V>` when the
    /// block cannot fail) — read off the block, since the checker's type is
    /// not handed to this backend: `E` is the type of the first `throw`'s
    /// operand and `V` that of the first `return`'s (`i32` where none says).
    /// What `isTaskExpr`, `awaitedType` and the `Error(e)` / `Ok(v)` patterns
    /// of a `case` over the awaited value read, as they do an annotation.
    fn lambdaTaskTypeRef(self: *Emitter, e: ast.Expr) !?ast.TypeRef {
        if (e != .function or e.function.kind.syntax != .lambda) return null;
        const lbody = e.function.kind.body;
        if (lbody.len == 0) return null;
        const tail = lbody[ast.lastRealIndex(lbody)].expr;
        const blk: ast.Expr = if (tail == .jump and tail.jump.kind == .@"return")
            (if (tail.jump.kind.@"return") |rv| rv.* else return null)
        else
            tail;
        if (blk != .function or blk.function.kind.syntax != .asyncBlock) return null;
        const task = (try self.asyncBlockTaskType(blk, false)) orelse return null;
        const ar = self.reg_arena.allocator();
        const ret = try ar.create(ast.TypeRef);
        ret.* = task;
        const params = try ar.alloc(ast.TypeRef, e.function.kind.params.len);
        for (params) |*p| p.* = .{ .named = "i32" };
        return .{ .function = .{ .params = params, .returnType = ret } };
    }

    /// `val t = async { … throw e … }`: the block's `@Task<@Result<V, E>>`,
    /// so `await t` types its answer and `@print` / `Error(e)` read it (a
    /// block that cannot fail keeps the untyped task).
    fn failingAsyncTypeRef(self: *Emitter, e: ast.Expr) !?ast.TypeRef {
        if (e != .function or e.function.kind.syntax != .asyncBlock) return null;
        return self.asyncBlockTaskType(e, true);
    }

    /// The `@Task<V>` (`@Task<@Result<V, E>>` when the block fails) of the
    /// `async { }` block `blk`, read off its `return`s and `throw`s.
    fn asyncBlockTaskType(self: *Emitter, blk: ast.Expr, only_failing: bool) !?ast.TypeRef {
        const body = blk.function.kind.body;
        const ar = self.reg_arena.allocator();
        // The transform has rewritten a `throw x` to `return __bp_error(x)`
        // and a `return v` of a failing block to `return __bp_ok(v)`.
        var ok_v: ?ast.Expr = null;
        var err_v: ?ast.Expr = null;
        scanBlockReturns(body, &ok_v, &err_v);
        const fails = err_v != null or ast.bodyFails(body);
        const ok_name = if (ok_v) |v| self.operandTypeName(v) else "i32";
        if (only_failing and !fails) return null;
        var task_arg: ast.TypeRef = .{ .named = ok_name };
        if (fails) {
            const err_name = if (err_v) |v| self.operandTypeName(v) else "i32";
            const rargs = try ar.alloc(ast.TypeRef, 2);
            rargs[0] = .{ .named = ok_name };
            rargs[1] = .{ .named = err_name };
            task_arg = .{ .generic = .{ .name = "Result", .args = rargs, .is_builtin = true } };
        }
        const targs = try ar.alloc(ast.TypeRef, 1);
        targs[0] = task_arg;
        return .{ .generic = .{ .name = "Task", .args = targs, .is_builtin = true } };
    }

    fn operandTypeName(self: *Emitter, v: ast.Expr) []const u8 {
        if (self.isStringExpr(v)) return "string";
        if (self.isBoolExpr(v)) return "bool";
        if (self.wasmTypeOf(v).isFloat()) return "f64";
        return "i32";
    }

    /// The first value an `async { }` block's `return`s hand over, and the
    /// first error it fails with: `__bp_ok(v)` / `__bp_error(e)` as the
    /// transform leaves them, or a bare `return v` / `throw e`. Its own scope
    /// and the arms of its `if`s, not a nested block or lambda.
    fn scanBlockReturns(body: []const ast.Stmt, ok_v: *?ast.Expr, err_v: *?ast.Expr) void {
        for (body) |st| switch (st.expr) {
            .jump => |j| switch (j.kind) {
                .@"return" => |v| if (v) |x| {
                    if (x.* == .call and x.call.kind == .call) {
                        const cc = x.call.kind.call;
                        if (cc.is_builtin and cc.args.len == 1 and std.mem.eql(u8, cc.callee, "__bp_error")) {
                            if (err_v.* == null) err_v.* = cc.args[0].value.*;
                            continue;
                        }
                        if (cc.is_builtin and cc.args.len == 1 and std.mem.eql(u8, cc.callee, "__bp_ok")) {
                            if (ok_v.* == null) ok_v.* = cc.args[0].value.*;
                            continue;
                        }
                    }
                    if (ok_v.* == null) ok_v.* = x.*;
                },
                .throw_ => |v| if (v) |x| {
                    if (err_v.* == null) err_v.* = x.*;
                },
                else => {},
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    scanBlockReturns(i.then_, ok_v, err_v);
                    if (i.else_) |els| scanBlockReturns(els, ok_v, err_v);
                },
                else => {},
            },
            else => {},
        };
    }

    /// `return t` in a state machine, `t` a task: the machine answers what
    /// `t` settles with — a Promise returned from an `async function` is
    /// adopted the same way — so it is `return await t`.
    fn adoptTask(self: *Emitter, r: ?*ast.Expr) !?*ast.Expr {
        const v = r orelse return null;
        if (self.machine == null or !self.isTaskExpr(v.*)) return v;
        const e = try self.reg_arena.allocator().create(ast.Expr);
        e.* = .{ .jump = .{ .loc = v.getLoc(), .kind = .{ .await_ = v } } };
        return e;
    }

    /// Whether `e` is a state machine's `return t` of a task, which the
    /// machine adopts (`adoptTask`): its value is what `t` settles with, read
    /// as the machine's own answer.
    fn adoptsTask(self: *Emitter, e: ast.Expr) bool {
        if (self.machine == null or e != .jump or e.jump.kind != .@"return") return false;
        const v = e.jump.kind.@"return" orelse return false;
        return self.isTaskExpr(v.*);
    }

    /// The wasm type of the value a task `e` settles with.
    fn awaitedType(self: *Emitter, e: ast.Expr) Repr {
        if (e == .function) return .i32;
        if (e == .collection and e.collection.kind == .grouped) return self.awaitedType(e.collection.kind.grouped.*);
        const t = self.typeRefOf(e) orelse return .i32;
        const inner = taskValueTypeRef(t) orelse return .i32;
        return watType(inner);
    }

    /// `await e` (decision 392). On a task, inside a state machine: the task
    /// is evaluated into `$__aw<k>` unless the machine is re-entering past
    /// this point; still pending, the machine suspends here — the frame
    /// saved, `k` recorded, the task waited on — and when it is entered
    /// again with index `k` the value is read from the settled task:
    ///
    ///     (block $__aw<k>
    ///       local.get $__seek
    ///       (if (then  ;; re-entering: here, before here, or inside the operand
    ///         … i32.const k i32.eq (if (then i32.const 0 local.set $__seek br $__aw<k>))
    ///         … br_if $__aw<k>))
    ///       <operand> local.set $__aw<k>
    ///       local.get $__aw<k> call $__task_pending
    ///       (if (then … save the frame, k, return)))
    ///     local.get $__aw<k> <T>.load offset=8
    ///
    /// Outside a state machine (an eager `@Component` body) the scheduler
    /// runs until the task settles (`$__task_block_on`). On anything that
    /// is not a task `await` is the identity it has always been here.
    fn lowerAwait(self: *Emitter, operand_in: ast.Expr) anyerror!void {
        if (runCallOf(operand_in)) |rc| return self.lowerRun(rc.call.kind.call, true);
        const operand = innerClosureBlock(operand_in) orelse operand_in;
        if (!self.isTaskExpr(operand)) return self.lowerExpr(operand);
        const read: Settled = if (self.mode == .gc)
            .{ .gc = try self.gcAwaitedRead(operand) }
        else
            .{ .load = .{ .load = .{ .ty = self.awaitedType(operand).num(), .offset = 8 } } };
        const task_r: Repr = if (self.mode == .gc) .{ .ref = .task } else .i32;
        // 144 B-142 — an `await` in a stream's generator machine runs the
        // task to its end where the step is taken: the machine suspends at
        // its `yield`s only.
        if (self.machine == null or self.gen_item != null) {
            try self.lowerCoerced(operand, task_r);
            try self.emit(self.builder().helper(.task_block_on));
            try self.emitSettledRead(read);
            return;
        }
        const lo = self.machine.?.next;
        var op_c: Capture = .{};
        self.open(&op_c);
        try self.lowerCoerced(operand, task_r);
        const op_seq = self.seal(&op_c, .{ .value = self.vtOf(task_r) });
        return self.emitSuspension(lo, op_seq, null, read);
    }

    /// How an `await` reads the value a settled task holds: in linear memory
    /// a load off the task's record; in a GC module the task's `value` field,
    /// unboxed to the repr the task settles with (`raw`: kept the `anyref` it
    /// is — a component run's answer, decision 504); a `void` one is `0`.
    const Settled = union(enum) {
        load: Instr,
        gc: GcSettled,
    };
    const GcSettled = struct { repr: Repr, void_: bool = false, raw: bool = false };

    /// The settled task on the stack read as `read` says.
    fn emitSettledRead(self: *Emitter, read: Settled) anyerror!void {
        switch (read) {
            .load => |l| try self.emitC(l, "the settled value"),
            .gc => |g| {
                if (g.void_) {
                    try self.emit(.drop);
                    try self.emit(zero);
                    return;
                }
                try self.emitC(.{ .struct_get = .{ .ty = self.gcTyIndex(.task), .field = 2 } }, "the settled value");
                if (!g.raw) try self.gcUnbox(g.repr);
            },
        }
    }

    /// Front 164 s2 P4 — the repr an awaited task `e` settles with in a GC
    /// module: `T` of its `@Task<T>` (an `async { }` block's by its value);
    /// a task whose `T` nothing here can tell keeps the module in linear
    /// memory, since a box read as another kind traps.
    fn gcAwaitedRead(self: *Emitter, e: ast.Expr) anyerror!GcSettled {
        if (e == .collection and e.collection.kind == .grouped) return self.gcAwaitedRead(e.collection.kind.grouped.*);
        if (e == .function) return .{ .repr = (try self.gcBlockRepr(e)) orelse return self.gcFail("an awaited async block of no known type") };
        if (plainIdentName(e)) |n| if (self.gc_block_locals.get(self.resolveName(n))) |r| return .{ .repr = r };
        const t: ast.TypeRef = self.typeRefOf(e) orelse return self.gcFail("an awaited task of no known type");
        var inner = taskValueTypeRef(t) orelse return self.gcFail("an awaited task of no known type");
        if (!self.typeConcrete(inner)) {
            // A generic task's `T`: bound by the call's arguments, or read off
            // the expression the shape readers see the task's value as
            // (`delay`'s value argument, `race`'s first task, …).
            if (self.bindAwaitedGeneric(e, inner)) |b| inner = b;
        }
        if (!self.typeConcrete(inner)) {
            if (e == .call and e.call.kind == .call) if (self.genericResultArg(e.call.kind.call)) |v| {
                if (self.isTaskExpr(v)) return self.gcAwaitedRead(v);
                const r = self.wasmTypeOf(v);
                if (r == .ref and r.ref == .task) return self.gcFail("an awaited task of a type parameter");
                return .{ .repr = r };
            };
            return self.gcFail("an awaited task of a type parameter");
        }
        if (inner == .named and std.mem.eql(u8, inner.named, "void")) return .{ .repr = .i32, .void_ = true };
        return .{ .repr = self.reprOf(inner) };
    }

    /// The repr an `async { }` block settles with, as its lifted body
    /// answers it: a failing block's `@Result`, else the type of its value
    /// (`asyncBlockValue` — a name the block binds read by its value, an
    /// awaited task by what it settles with). Null when that value names
    /// something only the block declares.
    fn gcBlockRepr(self: *Emitter, e: ast.Expr) anyerror!?Repr {
        if ((try self.failingAsyncTypeRef(e)) != null) return .{ .ref = .result };
        const v = asyncBlockValue(e) orelse return null;
        if (plainIdentName(v)) |n| {
            const rn = self.resolveName(n);
            if (!self.locals.contains(rn) and !self.globals.contains(rn)) return null;
        }
        if (v == .jump and v.jump.kind == .@"return") return null;
        if (v == .jump and v.jump.kind == .await_) {
            const inner = v.jump.kind.await_.*;
            if (!self.isTaskExpr(inner)) return self.wasmTypeOf(inner);
            const g = self.gcAwaitedRead(inner) catch return null;
            return if (g.void_) null else g.repr;
        }
        if (self.isTaskExpr(v)) {
            const g = self.gcAwaitedRead(v) catch return null;
            return if (g.void_) null else g.repr;
        }
        return self.wasmTypeOf(v);
    }

    /// Whether `t` names only types this module knows — no type parameter
    /// left unbound (front 164 s2 P4: a box read as another kind traps).
    fn typeConcrete(self: *Emitter, t: ast.TypeRef) bool {
        return switch (t) {
            // A type parameter of the body being lowered is an `anyref` here.
            .named => |n| self.namesConcreteType(n) or std.mem.eql(u8, n, "unknown") or std.mem.eql(u8, n, "Bytes") or std.mem.eql(u8, n, "bigint") or isGenericParamName(n, self.owner_tparams, self.fn_tparams),
            .array => |inner| self.typeConcrete(inner.*),
            .optional => |inner| self.typeConcrete(inner.*),
            .generic => |g| blk: {
                for (g.args) |a| if (!self.typeConcrete(a)) break :blk false;
                break :blk true;
            },
            .tuple_, .labeledTuple, .function => true,
            else => false,
        };
    }

    /// Decision 504 — a component body that keeps a bare `try` runs its
    /// tail as an inner closure called in place (`context_lower`
    /// `lowerComponentBody`: `await ({ -> rest })()` when the tail awaits).
    /// Awaited, that call is an `async { rest }` block: the closure is a
    /// state machine like the component's lambda around it, so a task the
    /// host still holds suspends both instead of trapping in
    /// `$__task_block_on`. A `return` in it leaves the closure, as in an
    /// async block (`modules/decisions-taken/components_compose_by_data-504/cases/component_try_then_awaits_host_task`).
    fn innerClosureBlock(e: ast.Expr) ?ast.Expr {
        if (e != .call or e.call.kind != .call) return null;
        const cc = e.call.kind.call;
        const ce = cc.calleeExpr orelse return null;
        if (cc.receiver != null or cc.args.len != 0 or ce.* != .function) return null;
        const f = ce.function;
        if (f.kind.syntax != .lambda or f.kind.params.len != 0) return null;
        if (!context_lower.containsAwait(f.kind.body)) return null;
        return .{ .function = .{ .loc = f.loc, .kind = .{ .syntax = .asyncBlock, .params = &.{}, .body = f.kind.body } } };
    }

    /// `e` when it is a run's call (`scope_carry.isRun`).
    fn runCallOf(e: ast.Expr) ?ast.Expr {
        return switch (e) {
            .call => |c| switch (c.kind) {
                .call => |cc| if (cc.receiver == null and scopeCarry.isRun(cc.callee)) e else null,
                else => null,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| runCallOf(inner.*),
                else => null,
            },
            else => null,
        };
    }

    /// Decision 504 — a run of a component value `c` with a scope
    /// (`bpScopeRaw__run<n>(c, scope)`, `scope_carry.zig`): the lambda is
    /// called, and its mark (the word behind its closure cell) says what the
    /// call answered — a direct lambda its `Rendered`, a state machine its
    /// task. A task is awaited where the run is (`awaited`, in a state
    /// machine: suspending while it waits), else run until it settles
    /// (`$__task_block_on`); the word of a direct run is its value, so a
    /// synchronous component pays nothing and a task's address and a
    /// `Rendered` are never told apart by their word.
    fn lowerRun(self: *Emitter, cc: anytype, awaited: bool) anyerror!void {
        if (cc.args.len != 2) return self.refuse(self.call_loc, "a component run takes the component and the scope", .{});
        if (self.mode == .gc) return self.gcRun(cc, awaited);
        const ra = self.reg_arena.allocator();
        const k = self.loop_seq;
        self.loop_seq += 1;
        const cv = try std.fmt.allocPrint(ra, "__runc{d}", .{k});
        const mk = try std.fmt.allocPrint(ra, "__runm{d}", .{k});
        try self.declareLocal(cv, .i32);
        try self.declareLocal(mk, .i32);
        const load: Instr = .{ .load = .{ .offset = 8 } };
        const lo: u32 = if (self.machine) |m| m.next else 0;
        var op_c: Capture = .{};
        self.open(&op_c);
        try self.lowerCoerced(cc.args[0].value.*, .i32);
        try self.emit(.{ .local_tee = cv });
        try self.emit(try self.constInt(4));
        try self.emit(opOf(.i32, "sub"));
        try self.emitC(.{ .load = .{} }, "the lambda's mark: a state machine?");
        try self.emit(.{ .local_set = mk });
        try self.emit(.{ .local_get = cv });
        try self.lowerCoerced(cc.args[1].value.*, .i32);
        try self.emitIndirect(cv, 1);
        const op_seq = self.seal(&op_c, .{ .value = .i32 });
        if (awaited and self.machine != null) return self.emitSuspension(lo, op_seq, mk, .{ .load = load });
        for (op_seq.lines) |l| try self.cur.?.append(self.arena(), l);
        const w = try std.fmt.allocPrint(ra, "__runw{d}", .{k});
        try self.declareLocal(w, .i32);
        try self.emit(.{ .local_set = w });
        try self.emit(.{ .local_get = mk });
        var then_c: Capture = .{};
        self.open(&then_c);
        try self.emit(.{ .local_get = w });
        try self.emit(self.builder().helper(.task_block_on));
        try self.emitC(load, "the settled value");
        const then_seq = self.seal(&then_c, .{ .value = .i32 });
        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emit(.{ .local_get = w });
        const else_seq = self.seal(&else_c, .{ .value = .i32 });
        try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
    }

    /// A component's run in a GC module: the lambda is called with the
    /// scope and answers what the run wrapper declares. A component that
    /// awaits is a state machine, which has no GC form (`gcEmitLifted`).
    fn gcRun(self: *Emitter, cc: anytype, awaited: bool) anyerror!void {
        const sig = self.fn_sigs.get(cc.callee) orelse return self.gcFail("a component run of no signature");
        const ra = self.reg_arena.allocator();
        const k = self.loop_seq;
        self.loop_seq += 1;
        const cv = try std.fmt.allocPrint(ra, "__runc{d}", .{k});
        const mk = try std.fmt.allocPrint(ra, "__runm{d}", .{k});
        try self.declareLocal(cv, .{ .ref = .closure });
        try self.declareLocal(mk, .i32);
        const lo: u32 = if (self.machine) |m| m.next else 0;
        var op_c: Capture = .{};
        self.open(&op_c);
        try self.lowerCoerced(cc.args[0].value.*, .{ .ref = .closure });
        try self.emit(.{ .local_tee = cv });
        try self.emitC(.{ .struct_get = .{ .ty = self.gcTyIndex(.closure), .field = 1 } }, "the lambda's mark: a state machine?");
        try self.emit(.{ .local_set = mk });
        try self.emit(.{ .local_get = cv });
        try self.lowerCoerced(cc.args[1].value.*, .{ .ref = .unknown });
        try self.gcEmitIndirect(cv, 1);
        const op_seq = self.seal(&op_c, .{ .value = .anyref });
        // Decision 504 — a marked lambda answers its task: awaited where
        // the run is awaited inside a machine, else run until it settles.
        if (awaited and self.machine != null) {
            try self.emitSuspension(lo, op_seq, mk, .{ .gc = .{ .repr = .{ .ref = .unknown }, .raw = true } });
        } else {
            for (op_seq.lines) |l| try self.cur.?.append(self.arena(), l);
            const w = try std.fmt.allocPrint(ra, "__runw{d}", .{k});
            try self.declareLocal(w, .{ .ref = .unknown });
            try self.emit(.{ .local_set = w });
            try self.emit(.{ .local_get = mk });
            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emit(.{ .local_get = w });
            try self.emit(.{ .ref_cast = self.gcTy(.task) });
            try self.emit(self.builder().helper(.task_block_on));
            try self.emitSettledRead(.{ .gc = .{ .repr = .{ .ref = .unknown }, .raw = true } });
            const then_seq = self.seal(&then_c, .{ .value = .anyref });
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emit(.{ .local_get = w });
            const else_seq = self.seal(&else_c, .{ .value = .anyref });
            try self.emit(.{ .@"if" = .{ .result = .anyref, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
        }
        try self.emitConvert(.{ .ref = .unknown }, sig.result orelse .i32);
    }

    /// The suspension point of an `await` in a state machine over the task
    /// `op_seq` leaves (`lowerAwait`'s comment). With `mark` (a run, decision
    /// 504), the word is a task only when the local `mark` is set: otherwise
    /// it is the value, and nothing suspends.
    fn emitSuspension(self: *Emitter, lo: u32, op_seq: wat.Seq, mark: ?[]const u8, read: Settled) anyerror!void {
        const k = self.machine.?.next;
        self.machine.?.next += 1;
        const ra = self.reg_arena.allocator();
        const aw = try std.fmt.allocPrint(ra, "__aw{d}", .{k});
        const label = aw;
        const gc = self.mode == .gc;
        // In a GC module the awaited word is a `$task`, or — a run's, whose
        // mark says whether it is one — an `anyref` cast where it is one.
        const aw_r: Repr = if (!gc) .i32 else if (mark != null) .{ .ref = .unknown } else .{ .ref = .task };
        try self.declareLocal(aw, aw_r);
        const as_task: ?Instr = if (gc and mark != null) .{ .ref_cast = self.gcTy(.task) } else null;

        var c: Capture = .{};
        self.open(&c);
        // Re-entering: at this `await` the value is read; before it (an
        // earlier `await` of the statement) the settled task is read back;
        // inside the operand, the operand runs to the `await` it holds.
        {
            var seek_c: Capture = .{};
            self.open(&seek_c);
            try self.emit(.{ .local_get = sm_state });
            try self.emit(try self.constInt(k));
            try self.emit(opOf(.i32, "eq"));
            {
                var hit_c: Capture = .{};
                self.open(&hit_c);
                try self.emit(zero);
                try self.emit(.{ .local_set = sm_seek });
                try self.emitC(.{ .br = label }, "resumed here");
                const hit = self.seal(&hit_c, .terminated);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit } } });
            }
            if (lo < k) {
                try self.emit(.{ .local_get = sm_state });
                try self.emit(try self.constInt(lo));
                try self.emit(opOf(.i32, "lt_u"));
                try self.emit(.{ .local_get = sm_state });
                try self.emit(try self.constInt(k));
                try self.emit(opOf(.i32, "gt_u"));
                try self.emit(opOf(.i32, "or"));
                try self.emitC(.{ .br_if = label }, "resuming past this await");
            } else try self.emitC(.{ .br = label }, "resuming past this await");
            const seek = self.seal(&seek_c, .none);
            try self.emit(.{ .local_get = sm_seek });
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = seek } } });
        }
        for (op_seq.lines) |l| try self.cur.?.append(self.arena(), l);
        try self.emit(.{ .local_set = aw });
        if (mark) |m| {
            try self.emit(.{ .local_get = m });
            var p_c: Capture = .{};
            self.open(&p_c);
            try self.emit(.{ .local_get = aw });
            if (as_task) |i| try self.emit(i);
            try self.emit(self.builder().helper(.task_pending));
            const p_seq = self.seal(&p_c, .{ .value = .i32 });
            var n_c: Capture = .{};
            self.open(&n_c);
            try self.emit(zero);
            const n_seq = self.seal(&n_c, .{ .value = .i32 });
            try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = p_seq }, .@"else" = .{ .seq = n_seq } } });
        } else {
            try self.emit(.{ .local_get = aw });
            try self.emit(self.builder().helper(.task_pending));
        }
        {
            var sus_c: Capture = .{};
            self.open(&sus_c);
            try self.emit(.{ .local_get = aw });
            if (as_task) |i| try self.emit(i);
            try self.emit(.{ .local_get = sm_task });
            try self.emit(self.builder().helper(.task_wait));
            try self.emit(.{ .comment = save_marker });
            try self.emit(.{ .local_get = sm_frame });
            try self.emit(try self.constInt(k));
            if (gc)
                try self.emitC(.{ .struct_set = .{ .ty = self.gcTyIndex(.{ .frame = self.machine.?.frame }), .field = 0 } }, "the resume index")
            else
                try self.emitC(.{ .store = .{} }, "the resume index");
            try self.emit(one);
            try self.emit(.{ .global_set = "__task_suspended" });
            try self.pushZero();
            try self.emitC(.@"return", "suspended");
            const sus = self.seal(&sus_c, .terminated);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = sus } } });
        }
        const inner = self.seal(&c, .none);
        try self.emit(.{ .block = .{ .kind = .block, .label = label, .body = inner } });
        if (mark) |m| {
            const vt = self.vtOf(aw_r);
            try self.emit(.{ .local_get = m });
            var t_c: Capture = .{};
            self.open(&t_c);
            try self.emit(.{ .local_get = aw });
            if (as_task) |i| try self.emit(i);
            try self.emitSettledRead(read);
            const t_seq = self.seal(&t_c, .{ .value = vt });
            var v_c: Capture = .{};
            self.open(&v_c);
            try self.emit(.{ .local_get = aw });
            const v_seq = self.seal(&v_c, .{ .value = vt });
            try self.emit(.{ .@"if" = .{ .result = vt, .then = .{ .seq = t_seq }, .@"else" = .{ .seq = v_seq } } });
            return;
        }
        try self.emit(.{ .local_get = aw });
        try self.emitSettledRead(read);
    }

    /// `!$__seek || lo <= $__state <= hi` — the condition a statement (or a
    /// loop's start, a `case`'s subject) runs under in a state machine: always
    /// once the resume index is reached, and before it only when the index is
    /// one of its own `await`s. `range` null: it holds none.
    fn emitRunsWhileSeeking(self: *Emitter, range: ?[2]u32) !void {
        try self.emit(.{ .local_get = sm_seek });
        try self.emit(opOf(.i32, "eqz"));
        const r = range orelse return;
        try self.emit(.{ .local_get = sm_state });
        try self.emit(try self.constInt(r[0]));
        try self.emit(opOf(.i32, "ge_u"));
        try self.emit(.{ .local_get = sm_state });
        try self.emit(try self.constInt(r[1]));
        try self.emit(opOf(.i32, "le_u"));
        try self.emit(opOf(.i32, "and"));
        try self.emit(opOf(.i32, "or"));
    }

    /// The resume indices handed out since `lo`, as a range.
    fn awaitRange(self: *Emitter, lo: u32) ?[2]u32 {
        const m = self.machine orelse return null;
        return if (m.next > lo) .{ lo, m.next - 1 } else null;
    }

    /// `seq` (it leaves nothing) run under `emitRunsWhileSeeking`.
    fn emitGuarded(self: *Emitter, seq: Seq, range: ?[2]u32) !void {
        try self.emitRunsWhileSeeking(range);
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = seq } } });
    }

    /// A statement of a state machine, run under `emitRunsWhileSeeking`.
    fn emitGuardedStmt(self: *Emitter, stmt: ast.Stmt) anyerror!Tail {
        const lo = self.machine.?.next;
        var c: Capture = .{};
        self.open(&c);
        const tail = try self.emitStmtNormalised(stmt, false);
        const seq = self.seal(&c, if (tail == .terminated) .terminated else .none);
        try self.emitGuarded(seq, self.awaitRange(lo));
        return .none;
    }

    /// A loop's start (its iterable, its counters) in a state machine: run
    /// under `emitRunsWhileSeeking`, so re-entering the loop keeps the
    /// counters the frame restored. Outside one, emitted as it is.
    fn guardStart(self: *Emitter, start: *Capture, lo: u32) !void {
        const seq = self.seal(start, .none);
        if (self.machine == null) {
            for (seq.lines) |l| try self.cur.?.append(self.arena(), l);
            return;
        }
        try self.emitGuarded(seq, self.awaitRange(lo));
    }

    /// An `if`'s condition (`tee` names the local an optional binding keeps
    /// it in). In a state machine the value is kept in a local the frame
    /// saves, and re-entering reads it back instead of evaluating the
    /// condition again — unless an `await` is inside it.
    fn lowerCondition(self: *Emitter, cond: ast.Expr, tee: ?[]const u8) anyerror!void {
        // A GC module's optional is a reference: present when it is not null.
        if (self.mode == .gc) {
            const r = self.wasmTypeOf(cond);
            if (r.isRef()) {
                if (self.machine != null) return self.gcMachineRefCondition(cond, r, tee);
                try self.lowerCoerced(cond, r);
                if (tee) |t| try self.emit(.{ .local_tee = t });
                try self.emit(.ref_is_null);
                try self.emit(opOf(.i32, "eqz"));
                return;
            }
        }
        if (self.machine == null) {
            if (tee) |t| {
                try self.lowerCoerced(cond, .i32);
                try self.emit(.{ .local_tee = t });
            } else try self.lowerExpr(cond);
            return;
        }
        const lo = self.machine.?.next;
        var c: Capture = .{};
        self.open(&c);
        const keep = tee orelse blk: {
            const n = try std.fmt.allocPrint(self.reg_arena.allocator(), "__cnd{d}", .{self.loop_seq});
            self.loop_seq += 1;
            try self.declareLocal(n, .i32);
            break :blk n;
        };
        try self.lowerCoerced(cond, .i32);
        try self.emit(.{ .local_tee = keep });
        const seq = self.seal(&c, .{ .value = .i32 });
        if (self.awaitRange(lo) != null) {
            for (seq.lines) |l| try self.cur.?.append(self.arena(), l);
            return;
        }
        var back_c: Capture = .{};
        self.open(&back_c);
        try self.emitC(.{ .local_get = keep }, "the condition, read back");
        const back = self.seal(&back_c, .{ .value = .i32 });
        try self.emit(.{ .local_get = sm_seek });
        try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = back }, .@"else" = .{ .seq = seq } } });
    }

    /// An optional condition (a reference: present when not null) of a GC
    /// module's state machine: the reference is kept in a local the frame
    /// saves (`tee`, the binding's own, else `__cnd<n>`), and re-entering
    /// reads it back instead of evaluating the condition again — unless an
    /// `await` is inside it (front 164 s2 P4).
    fn gcMachineRefCondition(self: *Emitter, cond: ast.Expr, r: Repr, tee: ?[]const u8) anyerror!void {
        const lo = self.machine.?.next;
        const vt = self.vtOf(r);
        var c: Capture = .{};
        self.open(&c);
        const keep = tee orelse blk: {
            const n = try std.fmt.allocPrint(self.reg_arena.allocator(), "__cnd{d}", .{self.loop_seq});
            self.loop_seq += 1;
            try self.declareLocal(n, r);
            break :blk n;
        };
        try self.lowerCoerced(cond, r);
        try self.emit(.{ .local_tee = keep });
        const seq = self.seal(&c, .{ .value = vt });
        if (self.awaitRange(lo) != null) {
            for (seq.lines) |l| try self.cur.?.append(self.arena(), l);
        } else {
            var back_c: Capture = .{};
            self.open(&back_c);
            try self.emitC(.{ .local_get = keep }, "the condition, read back");
            const back = self.seal(&back_c, .{ .value = vt });
            try self.emit(.{ .local_get = sm_seek });
            try self.emit(.{ .@"if" = .{ .result = vt, .then = .{ .seq = back }, .@"else" = .{ .seq = seq } } });
        }
        try self.emit(.ref_is_null);
        try self.emit(opOf(.i32, "eqz"));
    }

    /// Decision 392 — `fn`'s lowered body as a state machine (§ above): `f`
    /// is the function the body would have been, its `result` the task's
    /// value type.
    fn emitStateMachine(self: *Emitter, f: wat.Func) !void {
        if (self.mode == .gc) return self.gcEmitStateMachine(f);
        const ar = self.arena();
        const ty: ValType = f.result orelse .i32;
        var slots: std.ArrayListUnmanaged(wat.Local) = .empty;
        for (f.params) |p| try slots.append(ar, .{ .name = p.name, .ty = p.ty });
        var body_locals: std.ArrayListUnmanaged(wat.Local) = .empty;
        for (f.params) |p| try body_locals.append(ar, .{ .name = p.name, .ty = p.ty });
        for (f.locals) |group| for (group) |l| {
            if (std.mem.eql(u8, l.name, sm_task)) continue;
            try body_locals.append(ar, l);
            if (!isMachineLocal(l.name)) try slots.append(ar, l);
        };
        const kind = self.task_kinds.items.len;
        const body_name = try std.fmt.allocPrint(ar, "{s}__body", .{f.name});
        const step_name = try std.fmt.allocPrint(ar, "{s}__step", .{f.name});
        try self.task_kinds.append(self.alloc, step_name);
        try self.task_edges.append(self.alloc, .{ .from = f.name, .to = step_name });

        var saves: std.ArrayListUnmanaged(wat.Line) = .empty;
        var restores: std.ArrayListUnmanaged(wat.Line) = .empty;
        for (slots.items, 0..) |s, i| {
            const at: wat.MemArg = .{ .ty = s.ty, .offset = @intCast(8 + 8 * i) };
            try saves.appendSlice(ar, &.{ .{ .instr = .{ .local_get = sm_frame } }, .{ .instr = .{ .local_get = s.name } }, .{ .instr = .{ .store = at } } });
            try restores.appendSlice(ar, &.{ .{ .instr = .{ .local_get = sm_frame } }, .{ .instr = .{ .load = at } }, .{ .instr = .{ .local_set = s.name } } });
        }

        // $f — the task.
        var start: std.ArrayListUnmanaged(wat.Line) = .empty;
        try start.appendSlice(ar, &.{
            .{ .instr = try self.constInt(8 + 8 * slots.items.len), .comment = "the frame: the resume index, then every local" },
            .{ .instr = self.builder().helper(.alloc) },
            .{ .instr = .{ .local_set = "__fr" } },
        });
        for (f.params, 0..) |p, i| try start.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = "__fr" } },
            .{ .instr = .{ .local_get = p.name } },
            .{ .instr = .{ .store = .{ .ty = p.ty, .offset = @intCast(8 + 8 * i) } } },
        });
        try start.appendSlice(ar, &.{
            .{ .instr = try self.constInt(kind), .comment = step_name },
            .{ .instr = .{ .local_get = "__fr" } },
            .{ .instr = self.builder().helper(.task_start), .comment = "runs to its first await" },
        });
        try self.item(.{ .func = try self.builder().func(.{
            .name = f.name,
            .exports = f.exports,
            .params = f.params,
            .result = .i32,
            .locals = try self.builder().localLines(&.{.{ .name = "__fr", .ty = .i32 }}),
            .body = .{ .lines = start.items, .stack = .{ .value = .i32 } },
        }) });

        // $f__body — entered again at the frame's resume index.
        var lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = sm_task } },
            .{ .instr = .{ .load = .{ .offset = 16 } } },
            .{ .instr = .{ .local_set = sm_frame } },
        });
        try lines.appendSlice(ar, restores.items);
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = sm_frame } },
            .{ .instr = .{ .load = .{} }, .comment = "the resume index" },
            .{ .instr = .{ .local_tee = sm_state } },
            .{ .instr = zero },
            .{ .instr = opOf(.i32, "ne") },
            .{ .instr = .{ .local_set = sm_seek } },
        });
        const replaced = try self.withFrameSaves(f.body, saves.items);
        try lines.appendSlice(ar, replaced.lines);
        try self.item(.{ .func = try self.builder().func(.{
            .name = body_name,
            .params = &.{wat.Builder.param(sm_task, .i32)},
            .result = f.result,
            .locals = try self.builder().localLines(body_locals.items),
            .body = .{ .lines = lines.items, .stack = replaced.stack },
        }) });

        // $f__step — the body, then the task settled unless it suspended.
        var step: std.ArrayListUnmanaged(wat.Line) = .empty;
        try step.append(ar, .{ .instr = .{ .local_get = sm_task } });
        try step.append(ar, .{ .instr = .{ .call = body_name } });
        if (f.result == null) try step.append(ar, .{ .instr = zero });
        try step.append(ar, .{ .instr = .{ .local_set = "__v" } });
        try step.append(ar, .{ .instr = .{ .global_get = "__task_suspended" } });
        try step.append(ar, .{ .instr = .{ .@"if" = .{ .then = .{ .seq = .{ .lines = try ar.dupe(wat.Line, &.{
            .{ .instr = zero },
            .{ .instr = .{ .global_set = "__task_suspended" } },
            .{ .instr = .@"return" },
        }), .stack = .terminated } } } } });
        try step.append(ar, .{ .instr = .{ .local_get = sm_task } });
        try step.append(ar, .{ .instr = .{ .local_get = "__v" } });
        try step.append(ar, .{ .instr = self.builder().helper(switch (ty) {
            .i64 => .task_settle_i64,
            .f64, .f32 => .task_settle_f64,
            else => .task_settle_i32,
        }) });
        try self.item(.{ .func = try self.builder().func(.{
            .name = step_name,
            .params = &.{wat.Builder.param(sm_task, .i32)},
            .locals = try self.builder().localLines(&.{.{ .name = "__v", .ty = if (ty == .f32) .f64 else ty }}),
            .body = .{ .lines = step.items, .stack = .none },
        }) });
    }

    /// Decision 392 in a GC module (front 164 s2 P4): the same three
    /// functions over a `$task` and the machine's typed frame `$frame<n>` —
    /// field 0 its resume index, then one field per local. `$f` makes the
    /// frame (`struct.new_default`, the arguments stored) and starts the task;
    /// `$f__body(task)` casts the task's frame back and restores every local
    /// from it; `$f__step(task)` settles the task with the body's answer in its
    /// box (`gcBox`, decision 544: shared, never copied) unless it suspended.
    fn gcEmitStateMachine(self: *Emitter, f: wat.Func) !void {
        const ar = self.arena();
        const n = self.machine.?.frame;
        var slots: std.ArrayListUnmanaged(wat.Local) = .empty;
        for (f.params) |p| try slots.append(ar, .{ .name = p.name, .ty = p.ty });
        var body_locals: std.ArrayListUnmanaged(wat.Local) = .empty;
        for (f.params) |p| try body_locals.append(ar, .{ .name = p.name, .ty = p.ty });
        for (f.locals) |group| for (group) |l| {
            if (std.mem.eql(u8, l.name, sm_task)) continue;
            try body_locals.append(ar, l);
            if (!isMachineLocal(l.name)) try slots.append(ar, l);
        };
        const slot_tys = try ar.alloc(ValType, slots.items.len);
        for (slots.items, slot_tys) |sl, *t| t.* = sl.ty;
        self.gc_frames.items[n] = slot_tys;
        const fty = self.gcTyIndex(.{ .frame = n });
        const frame_vt = ValType.def(fty);
        const task_vt = self.gcTy(.task);
        const kind = self.task_kinds.items.len;
        const body_name = try std.fmt.allocPrint(ar, "{s}__body", .{f.name});
        const step_name = try std.fmt.allocPrint(ar, "{s}__step", .{f.name});
        try self.task_kinds.append(self.alloc, step_name);
        try self.task_edges.append(self.alloc, .{ .from = f.name, .to = step_name });

        var saves: std.ArrayListUnmanaged(wat.Line) = .empty;
        var restores: std.ArrayListUnmanaged(wat.Line) = .empty;
        for (slots.items, 0..) |sl, i| {
            const field: wat.FieldRef = .{ .ty = fty, .field = @intCast(1 + i) };
            try saves.appendSlice(ar, &.{ .{ .instr = .{ .local_get = sm_frame } }, .{ .instr = .{ .local_get = sl.name } }, .{ .instr = .{ .struct_set = field } } });
            try restores.appendSlice(ar, &.{ .{ .instr = .{ .local_get = sm_frame } }, .{ .instr = .{ .struct_get = field } }, .{ .instr = .{ .local_set = sl.name } } });
        }

        // $f — the task.
        var start: std.ArrayListUnmanaged(wat.Line) = .empty;
        try start.appendSlice(ar, &.{
            .{ .instr = .{ .struct_new_default = fty }, .comment = "the frame: the resume index, then every local" },
            .{ .instr = .{ .local_set = "__fr" } },
        });
        for (f.params, 0..) |p, i| try start.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = "__fr" } },
            .{ .instr = .{ .local_get = p.name } },
            .{ .instr = .{ .struct_set = .{ .ty = fty, .field = @intCast(1 + i) } } },
        });
        try start.appendSlice(ar, &.{
            .{ .instr = try self.constInt(kind), .comment = step_name },
            .{ .instr = .{ .local_get = "__fr" } },
            .{ .instr = self.builder().helper(.task_start), .comment = "runs to its first await" },
        });
        try self.item(.{ .func = try self.builder().func(.{
            .name = f.name,
            .exports = f.exports,
            .params = f.params,
            .result = task_vt,
            .locals = try self.builder().localLines(&.{.{ .name = "__fr", .ty = frame_vt }}),
            .body = .{ .lines = start.items, .stack = .{ .value = task_vt } },
        }) });

        // $f__body — entered again at the frame's resume index.
        var lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = sm_task } },
            .{ .instr = .{ .struct_get = .{ .ty = self.gcTyIndex(.task), .field = 3 } } },
            .{ .instr = .{ .ref_cast = frame_vt } },
            .{ .instr = .{ .local_set = sm_frame } },
        });
        try lines.appendSlice(ar, restores.items);
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = sm_frame } },
            .{ .instr = .{ .struct_get = .{ .ty = fty, .field = 0 } }, .comment = "the resume index" },
            .{ .instr = .{ .local_tee = sm_state } },
            .{ .instr = zero },
            .{ .instr = opOf(.i32, "ne") },
            .{ .instr = .{ .local_set = sm_seek } },
        });
        const replaced = try self.withFrameSaves(f.body, saves.items);
        try lines.appendSlice(ar, replaced.lines);
        try self.item(.{ .func = try self.builder().func(.{
            .name = body_name,
            .params = &.{wat.Builder.param(sm_task, task_vt)},
            .result = f.result,
            .locals = try self.builder().localLines(body_locals.items),
            .body = .{ .lines = lines.items, .stack = replaced.stack },
        }) });

        // $f__step — the body, then the task settled unless it suspended.
        var step: std.ArrayListUnmanaged(wat.Line) = .empty;
        try step.append(ar, .{ .instr = .{ .local_get = sm_task } });
        try step.append(ar, .{ .instr = .{ .call = body_name } });
        if (f.result != null) try step.append(ar, .{ .instr = .{ .local_set = "__v" } });
        try step.append(ar, .{ .instr = .{ .global_get = "__task_suspended" } });
        try step.append(ar, .{ .instr = .{ .@"if" = .{ .then = .{ .seq = .{ .lines = try ar.dupe(wat.Line, &.{
            .{ .instr = zero },
            .{ .instr = .{ .global_set = "__task_suspended" } },
            .{ .instr = .@"return" },
        }), .stack = .terminated } } } } });
        try step.append(ar, .{ .instr = .{ .local_get = sm_task } });
        if (f.result != null) {
            try step.append(ar, .{ .instr = .{ .local_get = "__v" } });
            var box_c: Capture = .{};
            self.open(&box_c);
            try self.gcBox(self.cur_result);
            const boxed = self.seal(&box_c, .{ .value = .anyref });
            try step.appendSlice(ar, boxed.lines);
        } else try step.append(ar, .{ .instr = .{ .ref_null = .anyref } });
        try step.append(ar, .{ .instr = .{ .call = "__task_settle" } });
        try self.item(.{ .func = try self.builder().func(.{
            .name = step_name,
            .params = &.{wat.Builder.param(sm_task, task_vt)},
            .locals = if (f.result) |rt| try self.builder().localLines(&.{.{ .name = "__v", .ty = rt }}) else &.{},
            .body = .{ .lines = step.items, .stack = .none },
        }) });
    }

    /// `seq` with each `save_marker` line replaced by `saves`.
    fn withFrameSaves(self: *Emitter, seq: Seq, saves: []const wat.Line) !Seq {
        const ar = self.arena();
        var out: std.ArrayListUnmanaged(wat.Line) = .empty;
        for (seq.lines) |l| switch (l.instr) {
            .comment => |t| if (std.mem.eql(u8, t, save_marker))
                try out.appendSlice(ar, saves)
            else
                try out.append(ar, l),
            .@"if" => |n| {
                var m = n;
                m.then.seq = try self.withFrameSaves(n.then.seq, saves);
                if (n.@"else") |e| {
                    var ee = e;
                    ee.seq = try self.withFrameSaves(e.seq, saves);
                    m.@"else" = ee;
                }
                var nl = l;
                nl.instr = .{ .@"if" = m };
                try out.append(ar, nl);
            },
            .block => |bk| {
                var m = bk;
                m.body = try self.withFrameSaves(bk.body, saves);
                var nl = l;
                nl.instr = .{ .block = m };
                try out.append(ar, nl);
            },
            else => try out.append(ar, l),
        };
        return .{ .lines = out.items, .stack = seq.stack };
    }

    /// `$__task_resume(t)` — the step of the state machine a task runs, by
    /// its `kind` (`task_kinds`).
    fn taskResumeFunc(self: *Emitter) !wat.Func {
        const ar = self.arena();
        const gc = self.mode == .gc;
        var lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = "t" } },
            .{ .instr = if (gc) .{ .struct_get = .{ .ty = self.gcTyIndex(.task), .field = 4 } } else .{ .load = .{ .offset = 20 } }, .comment = "kind" },
            .{ .instr = .{ .local_set = "k" } },
        });
        for (self.task_kinds.items, 0..) |step, i| {
            try lines.appendSlice(ar, &.{
                .{ .instr = .{ .local_get = "k" } },
                .{ .instr = try self.constInt(i) },
                .{ .instr = opOf(.i32, "eq") },
                .{ .instr = .{ .@"if" = .{ .then = .{ .seq = .{ .lines = try ar.dupe(wat.Line, &.{
                    .{ .instr = .{ .local_get = "t" } },
                    .{ .instr = .{ .call = step } },
                    .{ .instr = .@"return" },
                }), .stack = .terminated } } } } },
            });
        }
        try lines.append(ar, .{ .instr = .@"unreachable" });
        return self.builder().func(.{
            .name = "__task_resume",
            .params = &.{wat.Builder.param("t", if (gc) self.gcTy(.task) else .i32)},
            .locals = try self.builder().localLines(&.{.{ .name = "k", .ty = .i32 }}),
            .body = .{ .lines = lines.items, .stack = .terminated },
        });
    }

    /// Decision 392 — a state machine re-enters the statement of the `await`
    /// it suspended at, reading back what it passed on the way (conditions,
    /// subjects, loop starts) and skipping the statements before it; an
    /// operand evaluated before the `await` in its own statement runs again.
    /// A call there would run twice (it may print, or answer otherwise the
    /// second time), so it is refused — bound to a `val` first, it is a
    /// statement of its own.
    fn checkAwaitOrder(self: *Emitter, body: []const ast.Stmt) !void {
        _ = try self.awaitOrderStmts(body, false);
    }

    /// Each statement of `body` walked from `dirty`; true when one of them
    /// calls something.
    fn awaitOrderStmts(self: *Emitter, body: []const ast.Stmt, dirty: bool) anyerror!bool {
        var any = false;
        for (body) |st| {
            var d = dirty;
            try self.awaitOrderExpr(st.expr, &d);
            if (d) any = true;
        }
        return any;
    }

    /// A constructor call allocates and runs nothing: evaluated again, it
    /// builds the same value.
    fn isPureCall(self: *Emitter, cc: anytype) bool {
        if (cc.is_builtin or cc.receiver != null) return false;
        return self.records.contains(cc.callee) or std.mem.eql(u8, cc.callee, "Ok") or std.mem.eql(u8, cc.callee, "Error");
    }

    fn awaitOrderExpr(self: *Emitter, e: ast.Expr, dirty: *bool) anyerror!void {
        switch (e) {
            .jump => |j| switch (j.kind) {
                .await_ => |a| {
                    if (dirty.*) return self.refuse(j.loc, "the wasm backend resumes an `await` by entering its statement again, and a call evaluated before it in that statement would run twice — bind the call's result to a `val` before the statement (decision 392)", .{});
                    var d = false;
                    try self.awaitOrderExpr(a.*, &d);
                },
                .@"return", .throw_, .try_ => |v| if (v) |x| try self.awaitOrderExpr(x.*, dirty),
                inline .@"break", .yield => |jl| if (jl.value) |x| try self.awaitOrderExpr(x.*, dirty),
                else => {},
            },
            .identifier => |id| switch (id.kind) {
                .identAccess => |ia| try self.awaitOrderExpr(ia.receiver.*, dirty),
                else => {},
            },
            .binaryOp => |b| {
                try self.awaitOrderExpr(b.lhs.*, dirty);
                try self.awaitOrderExpr(b.rhs.*, dirty);
            },
            .unaryOp => |u| try self.awaitOrderExpr(u.expr.*, dirty),
            .call => |c| switch (c.kind) {
                .call => |cc| {
                    if (cc.receiver) |r| try self.awaitOrderExpr(r.*, dirty);
                    for (cc.args) |a| try self.awaitOrderExpr(a.value.*, dirty);
                    for (cc.trailing) |t| if (try self.awaitOrderStmts(t.body, dirty.*)) {
                        dirty.* = true;
                    };
                    if (!self.isPureCall(cc)) dirty.* = true;
                },
                .pipeline => |pl| {
                    try self.awaitOrderExpr(pl.lhs.*, dirty);
                    try self.awaitOrderExpr(pl.rhs.*, dirty);
                    dirty.* = true;
                },
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    const before = dirty.*;
                    try self.awaitOrderExpr(i.cond.*, dirty);
                    if (try self.awaitOrderStmts(i.then_, before)) dirty.* = true;
                    if (i.else_) |els| if (try self.awaitOrderStmts(els, before)) {
                        dirty.* = true;
                    };
                },
                .tryCatch => |tc| {
                    try self.awaitOrderExpr(tc.expr.*, dirty);
                    try self.awaitOrderExpr(tc.handler.*, dirty);
                },
            },
            .binding => |b| switch (b.kind) {
                .localBind => |lb| try self.awaitOrderExpr(lb.value.*, dirty),
                .localBindDestruct => |lb| try self.awaitOrderExpr(lb.value.*, dirty),
                .assign => |a| try self.awaitOrderExpr(a.value.*, dirty),
            },
            .loop => |lp| {
                const before = dirty.*;
                try self.awaitOrderExpr(lp.iter.*, dirty);
                if (try self.awaitOrderStmts(lp.body, before)) dirty.* = true;
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| try self.awaitOrderExpr(inner.*, dirty),
                .case => |cs| {
                    const before = dirty.*;
                    for (cs.subjects) |sj| try self.awaitOrderExpr(sj, dirty);
                    for (cs.arms) |arm| {
                        var ad = before;
                        if (arm.guard) |g| try self.awaitOrderExpr(g, &ad);
                        if (armLambda(arm.body)) |al| {
                            if (try self.awaitOrderStmts(al.body, ad)) ad = true;
                        } else try self.awaitOrderExpr(arm.body, &ad);
                        if (ad) dirty.* = true;
                    }
                },
                .tupleLit => |tl| for (tl.elems) |el| try self.awaitOrderExpr(el, dirty),
                .arrayLit => |al| for (al.elems) |el| try self.awaitOrderExpr(el, dirty),
                .behaviorLit => |il| for (il.fields) |f| try self.awaitOrderExpr(f.value.*, dirty),
                .range => |r| {
                    try self.awaitOrderExpr(r.start.*, dirty);
                    if (r.end) |x| try self.awaitOrderExpr(x.*, dirty);
                },
            },
            .useHook => |uh| {
                try self.awaitOrderExpr(uh.kind.inner.*, dirty);
                dirty.* = true;
            },
            else => {},
        }
    }

    /// `async { … }` (decision 124): the block is lifted like a lambda and
    /// its closure called in place, so a `return` inside it leaves the block,
    /// not the enclosing function. The closure is a state machine (decision
    /// 392): the call answers the block's task, started and run to its first
    /// `await`.
    fn lowerAsyncBlock(self: *Emitter, body: []const ast.Stmt) anyerror!void {
        const gc = self.mode == .gc;
        const idx = self.lambdas.items.len;
        const slot = try std.fmt.allocPrint(self.reg_arena.allocator(), "__async{d}", .{idx});
        try self.declareLocal(slot, if (gc) .{ .ref = .closure } else .i32);
        try self.lowerLambdaValue(&.{}, body, null);
        self.lambdas.items[idx].async_block = true;
        try self.emit(.{ .local_set = slot });
        try self.emitC(.{ .local_get = slot }, "the block's environment");
        if (!gc) return self.emitIndirect(slot, 0);
        // Front 164 s2 P4 — the table's wrapper answers the task as an `anyref`.
        try self.gcEmitIndirect(slot, 0);
        try self.emit(.{ .ref_cast = self.gcTy(.task) });
    }

    fn lowerLambdaValue(self: *Emitter, params: []const []const u8, body: []const ast.Stmt, loc: ?ast.Loc) anyerror!void {
        const ra = self.reg_arena.allocator();
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        for (body) |st| try self.collectIdents(st.expr, &names);
        var caps: std.ArrayListUnmanaged(Captured) = .empty;
        outer: for (names.items) |n| {
            for (params) |p| if (std.mem.eql(u8, p, n)) continue :outer;
            for (caps.items) |cp| if (std.mem.eql(u8, cp.name, n)) continue :outer;
            const ty = self.locals.get(n) orelse continue;
            try caps.append(ra, .{
                .name = n,
                .ty = ty,
                .str = self.str_locals.contains(n),
                .record = self.local_types.get(n),
                .arr_elem = self.arr_elem_locals.get(n),
                .typeref = self.local_typerefs.get(n),
                .bool_ = self.bool_locals.contains(n),
                .threaded = bodyAssigns(body, n),
            });
        }
        const idx: u32 = @intCast(self.lambdas.items.len);
        const param_str = try ra.alloc(bool, params.len);
        @memset(param_str, false);
        // A declared function type the lambda is written against types its
        // parameters: `fn greeter(p: string) -> fn(x: string) -> string {
        // return { x -> p + x }; }` concatenates, where an untyped `x` was an
        // `i32` and `p + x` wrote the number (`a264`, exit 0).
        const expected = self.expected_fn;
        self.expected_fn = null;
        const param_rec = try ra.alloc(?[]const u8, params.len);
        @memset(param_rec, null);
        const param_tref = try ra.alloc(?ast.TypeRef, params.len);
        @memset(param_tref, null);
        // Known unless the slot the lambda goes into says nothing about it
        // (`lowerRecordCtor` clears it for a field written as a type
        // parameter); a call through the slot sets it again.
        const param_known = try ra.alloc(bool, params.len);
        @memset(param_known, true);
        const param_cell = try ra.alloc(Cell, params.len);
        @memset(param_cell, .none);
        var ret_cell: Cell = .none;
        const param_ft = try ra.alloc(?ast.TypeRef, params.len);
        @memset(param_ft, null);
        const param_seen = try ra.alloc(?Repr, params.len);
        @memset(param_seen, null);
        var ret_ft: ?ast.TypeRef = null;
        if (expected) |et| if (et == .function) {
            const pts = et.function.params;
            for (param_ft, 0..) |*pf, i| {
                if (i < pts.len) pf.* = pts[i];
            }
            ret_ft = et.function.returnType.*;
            for (param_cell, 0..) |*pc, i| {
                if (i < pts.len) pc.* = cellOfTypeRef(pts[i]);
            }
            ret_cell = cellOfTypeRef(et.function.returnType.*);
            for (param_str, 0..) |*ps, i| {
                if (i < pts.len and isStringTypeRef(pts[i])) ps.* = true;
            }
            for (param_rec, 0..) |*pr, i| {
                if (i < pts.len and pts[i] == .named) pr.* = self.resolveRecordName(pts[i].named);
            }
            for (param_tref, 0..) |*pt, i| {
                if (i < pts.len and pts[i] == .named and primKindOfName(pts[i].named) != null) pt.* = pts[i];
            }
        };
        const expected_params = self.expected_params;
        self.expected_params = null;
        if (expected_params) |eps| for (param_str, 0..) |*ps, i| {
            if (i < eps.len and isStringTypeRef(eps[i].typeRef)) ps.* = true;
        };
        if (expected_params) |eps| for (param_ft, 0..) |*pf, i| {
            if (pf.* == null and i < eps.len) pf.* = eps[i].typeRef;
        };
        try self.lambdas.append(self.alloc, .{
            .name = try std.fmt.allocPrint(ra, "__lambda{d}", .{idx}),
            .params = params,
            .body = body,
            .captures = caps.items,
            .param_str = param_str,
            .param_rec = param_rec,
            .param_tref = param_tref,
            .param_known = param_known,
            .param_cell = param_cell,
            .ret_cell = ret_cell,
            .loc = loc,
            .template_of = self.cur_template,
            .origin = self.foreign_origin,
            .rewrites = self.rewrites,
            .lowerings = self.instance_lowerings,
            .renames = self.global_renames,
            .idx = idx,
            .param_ft = param_ft,
            .ret_ft = ret_ft,
            .param_seen = param_seen,
        });
        // Decision 504 — a component's lambda (the scope lowering's `{
        // bpScope__ -> … }`) is a state machine only when its body awaits;
        // its closure cell carries that mark one word behind it, which a
        // run reads (`lowerRun`).
        const mark: ?bool = if (params.len == 1 and std.mem.eql(u8, params[0], context_lower.scope_param))
            context_lower.containsAwait(body)
        else
            null;
        if (mark) |m| self.lambdas.items[idx].async_block = m;
        try self.emitClosureCell(idx, caps.items, mark);
    }

    fn fieldClosureOf(self: *Emitter, recv: ast.Expr, field: []const u8) ?u32 {
        const n = plainIdentName(recv) orelse return null;
        var buf: [256]u8 = undefined;
        const key = std.fmt.bufPrint(&buf, "{s}.{s}", .{ self.resolveName(n), field }) catch return null;
        return self.field_closures.get(key);
    }

    fn fieldClosureOfExpr(self: *Emitter, e: ast.Expr) ?u32 {
        if (e != .identifier or e.identifier.kind != .identAccess) return null;
        const ia = e.identifier.kind.identAccess;
        return self.fieldClosureOf(ia.receiver.*, ia.member);
    }

    /// Allocate the environment cell of table slot `idx` and leave its pointer.
    /// A component's lambda (`mark` set, decision 504) has one word more,
    /// behind the pointer: `1` when the lambda is a state machine.
    fn emitClosureCell(self: *Emitter, idx: u32, caps: []const Captured, mark: ?bool) anyerror!void {
        if (self.mode == .gc) return self.gcClosureNew(idx, caps, mark);
        const head: u32 = if (mark != null) 4 else 0;
        const base = try self.allocSlots(@intCast(head + (1 + caps.len) * 4));
        if (mark) |m| try self.storeSlotConst(base, 0, @intFromBool(m));
        try self.storeSlotConst(base, head, idx);
        for (caps, 0..) |cp, i| {
            // A float or `i64` capture is a cell of its own (`lowerCellWord`),
            // which the lambda and the syncs write in place.
            const cell = Cell.of(cp.ty);
            try self.emit(.{ .local_get = base });
            try self.emit(.{ .local_get = cp.name });
            try self.emitConvert(cp.ty, cell.ty());
            if (cell != .none) try self.emit(self.builder().helper(if (cell == .f64) .box_f64 else .box_i64));
            try self.emitCf(.{ .store = .{ .offset = @intCast(head + (i + 1) * 4) } }, "capture {s}", .{cp.name});
        }
        try self.loadBase(base);
        if (head > 0) {
            try self.emit(try self.constInt(head));
            try self.emitC(opOf(.i32, "add"), "a component's lambda: past its mark");
        }
    }

    // ── function values in a GC module (front 164 s2 P3) ─────────────────────
    //
    // A function value is a reference to `$closure {idx, mark}` or to one of
    // its subtypes, the environment struct of the lambda that made it:
    // `$env<n> {idx, mark, c0, c1, …}`, one typed field per captured local
    // (copied when the value is made; a capture the lambda assigns is a field
    // the lambda writes in place and a call through a known closure local
    // copies in and out, as in linear memory). `idx` is the lambda's slot in
    // the function table, `mark` a component's (decision 504: `1` when it is a
    // state machine).
    //
    // A lifted lambda is two functions. `$__lambda<n>__b(env, a0, …)` is the
    // body, typed like any function: the environment as its own struct, each
    // parameter as the repr the declared function type (or the argument a call
    // passed) gives it, the answer as the declared one. `$__lambda<n>` is what
    // the table holds: `(closure, anyref…) -> anyref`, which casts the closure
    // to its environment, unboxes each argument by the body's parameter repr,
    // calls the body and boxes the answer (a scalar in its box, a reference as
    // it is). So `call_indirect` carries one signature per arity and a call
    // site needs no knowledge of the callee but its declared function type.

    /// `(closure, anyref × argc) -> anyref`.
    fn gcClosureSig(self: *Emitter, argc: usize) !wat.FuncType {
        const params = try self.arena().alloc(ValType, argc + 1);
        params[0] = self.gcTy(.closure);
        for (params[1..]) |*p| p.* = .anyref;
        return .{ .params = params, .result = .anyref };
    }

    const GcCalleeType = struct { ft: ast.TypeRef, gps: ?[]const ast.GenericParam };

    /// The function type of a call's callee, when the program declares it,
    /// and the generic parameters of the record it is a field of.
    fn gcCalleeFnType(self: *Emitter, cc: anytype) ?GcCalleeType {
        var gps: ?[]const ast.GenericParam = null;
        const t0: ast.TypeRef = blk: {
            if (cc.calleeExpr) |ce| break :blk self.typeRefOf(ce.*) orelse return null;
            if (cc.receiver) |recv| {
                const rty = self.recordTypeOfExpr(recv.*) orelse return null;
                gps = self.record_generics.get(rty);
                break :blk self.fieldTypeRefIn(rty, cc.callee) orelse return null;
            }
            break :blk self.local_typerefs.get(self.resolveName(cc.callee)) orelse
                self.local_typerefs.get(cc.callee) orelse
                self.global_typerefs.get(self.resolveName(cc.callee)) orelse return null;
        };
        var t = eagerTypeRef(t0);
        if (t == .optional) t = eagerTypeRef(t.optional.*);
        if (t != .function) return null;
        return .{ .ft = t, .gps = gps };
    }

    /// The repr a written type has in a function value's signature: a
    /// generic record's type parameters are erased, a name nothing declares
    /// (a type parameter out of scope) has none.
    fn gcSigRepr(self: *Emitter, t: ast.TypeRef, gps: ?[]const ast.GenericParam) ?Repr {
        if (gps) |g| return self.gcErasedRepr(g, t);
        switch (eagerTypeRef(t)) {
            .named => |n| {
                if (isScalarName(n) or std.mem.eql(u8, n, "bool") or std.mem.eql(u8, n, "string") or std.mem.eql(u8, n, "unknown") or std.mem.eql(u8, n, "Bytes")) return self.reprOf(t);
                const name = if (std.mem.eql(u8, n, "Self")) (self.self_type orelse self.sig_owner orelse return null) else n;
                if (self.records.contains(name) or self.enums.contains(name)) return self.reprOf(t);
                if (isGenericParamName(n, self.owner_tparams, self.fn_tparams)) return self.reprOf(t);
                // `void`, `unit`: the word a unit answer is.
                if (std.mem.eql(u8, n, "void") or std.mem.eql(u8, n, "unit")) return .i32;
                return null;
            },
            else => return self.reprOf(t),
        }
    }

    /// The repr a call through a function value answers: the declared
    /// function type's, else the lambda a known closure local holds.
    /// Whether `(fn(p) { … })(args)` answers a string: its body, with each
    /// parameter a string when its argument is one.
    fn inlineCallIsString(self: *Emitter, k: anytype, cc: anytype) bool {
        if (k.returnType) |rt| return isStringTypeRef(rt);
        const flags = self.arena().alloc(bool, k.params.len) catch return false;
        for (flags, 0..) |*f, i| f.* = i < cc.args.len and self.isStringExpr(cc.args[i].value.*);
        const saved = self.param_shape;
        defer self.param_shape = saved;
        self.param_shape = .{ .names = k.params, .str = flags };
        return self.bodyIsString(k.body);
    }

    /// The fn expression a call's callee is, parentheses looked through.
    fn inlineFnExpr(e: ast.Expr) ?@TypeOf(e.function) {
        var cur = e;
        while (cur == .collection and cur.collection.kind == .grouped) cur = cur.collection.kind.grouped.*;
        if (cur != .function or cur.function.kind.syntax == .asyncBlock) return null;
        return cur.function;
    }

    fn gcValueCallRepr(self: *Emitter, cc: anytype) ?Repr {
        if (self.gcCalleeFnType(cc)) |d| return self.gcSigRepr(d.ft.function.returnType.*, d.gps);
        // A lambda stored in a field a type parameter types: the lambda the
        // constructor was given.
        if (cc.calleeExpr == null and cc.receiver != null) if (self.fieldClosureOf(cc.receiver.?.*, cc.callee)) |li| {
            const l = self.lambdas.items[li];
            if (l.ret_ft) |rt| return self.gcSigRepr(rt, null);
            return self.lambdaTailType(l.body);
        };
        // A fn expression called where it is written: its parameters are typed by
        // the arguments, as a closure local's are (`closureCallIsString`).
        if (cc.calleeExpr) |ce| if (inlineFnExpr(ce.*)) |inl| {
            const k = inl.kind;
            if (k.returnType) |rt| return self.gcSigRepr(rt, null);
            if (self.inlineCallIsString(k, cc)) return Repr.string;
            return self.lambdaTailType(k.body);
        };
        if (cc.calleeExpr == null and cc.receiver == null and self.locals.contains(cc.callee)) {
            if (self.closure_locals.get(cc.callee)) |li| {
                const l = self.lambdas.items[li];
                if (l.fn_ref) |target| {
                    const sig = self.fn_sigs.get(target) orelse return null;
                    return sig.result orelse .i32;
                }
                if (l.ret_ft) |rt| return self.gcSigRepr(rt, null);
                if (self.closureCallIsString(li, cc)) return Repr.string;
                return self.lambdaTailType(l.body);
            }
        }
        return null;
    }

    /// The value of repr `from` on the stack is a function value: an
    /// `unknown` is cast.
    fn gcAsClosure(self: *Emitter, from: Repr) !void {
        if (from == .ref and from.ref == .closure) return;
        if (from == .ref and from.ref == .unknown) return self.emit(.{ .ref_cast = self.gcTy(.closure) });
        return self.gcFail("a function value of another shape");
    }

    /// `call_indirect` of the function value in the local `fnv`, its
    /// arguments boxed on the stack under the environment.
    fn gcEmitIndirect(self: *Emitter, fnv: []const u8, argc: usize) anyerror!void {
        self.uses_table = true;
        try self.emit(.{ .local_get = fnv });
        try self.emitC(.{ .struct_get = .{ .ty = self.gcTyIndex(.closure), .field = 0 } }, "table index");
        try self.emit(.{ .call_indirect = try self.gcClosureSig(argc) });
    }

    /// `f(a, b)` through a function value in a GC module.
    fn gcValueCall(self: *Emitter, cc: anytype) anyerror!bool {
        const Slot = union(enum) { field: struct { rty: []const u8, idx: u32 }, tuple: u32 };
        const slot: ?Slot = blk: {
            if (cc.calleeExpr != null) break :blk null;
            const recv = cc.receiver orelse break :blk null;
            if (self.recordTypeOfExpr(recv.*)) |rty| {
                if (self.fieldOffsetIn(rty, cc.callee)) |off| break :blk .{ .field = .{ .rty = rty, .idx = off / 4 } };
            }
            if (tupleIndex(cc.callee)) |idx| break :blk .{ .tuple = idx };
            break :blk null;
        };
        const is_value = if (cc.calleeExpr != null) true else if (cc.receiver != null) slot != null else (self.locals.contains(cc.callee) or self.globals.contains(cc.callee));
        if (!is_value) return false;
        const ra = self.reg_arena.allocator();
        const tmp = try std.fmt.allocPrint(ra, "__fnv{d}", .{self.loop_seq});
        self.loop_seq += 1;
        try self.declareLocal(tmp, .{ .ref = .closure });
        const clo: Repr = .{ .ref = .closure };
        // A fn expression called where it is written (`(fn(s) { … })("a")`) is
        // the closure its call types: its lambda is the last one lowered.
        const lambdas_before = self.lambdas.items.len;
        if (cc.calleeExpr) |ce| {
            try self.lowerCoerced(ce.*, clo);
        } else if (cc.receiver) |recv| switch (slot.?) {
            .field => |f| {
                if (self.self_method_fields.contains(try std.fmt.allocPrint(ra, "{s}.{s}", .{ f.rty, cc.callee }))) return self.gcFail("a behavior literal's self method");
                try self.lowerCoerced(recv.*, .{ .ref = .{ .record = f.rty } });
                try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.{ .record = f.rty }), .field = f.idx } });
                if (self.gcGenericFieldDecl(f.rty, cc.callee) != null) try self.gcAsClosure(.{ .ref = .unknown });
            },
            .tuple => |idx| {
                try self.lowerCoerced(recv.*, .{ .ref = .tuple });
                try self.emit(try self.constInt(idx));
                try self.emit(.{ .array_get = .{ .ty = self.gcTyIndex(.{ .arr = .any }) } });
                try self.gcAsClosure(.{ .ref = .unknown });
            },
        } else if (self.locals.contains(cc.callee)) {
            const n = self.resolveName(cc.callee);
            try self.emit(.{ .local_get = n });
            try self.gcAsClosure(self.locals.get(n) orelse return self.gcFail("a function value local of no repr"));
        } else {
            try self.emit(.{ .global_get = self.globalName(cc.callee) });
            try self.gcAsClosure(self.global_types.get(cc.callee) orelse return self.gcFail("a function value global of no repr"));
        }
        try self.emit(.{ .local_set = tmp });
        const li: ?u32 = if (cc.calleeExpr == null and cc.receiver == null and self.locals.contains(cc.callee))
            self.closure_locals.get(cc.callee)
        else if (cc.calleeExpr == null and cc.receiver != null)
            self.fieldClosureOf(cc.receiver.?.*, cc.callee)
        else if (cc.calleeExpr) |ce|
            (if (inlineFnExpr(ce.*) != null and self.lambdas.items.len == lambdas_before + 1) @as(u32, @intCast(lambdas_before)) else null)
        else
            null;
        const decl = self.gcCalleeFnType(cc);
        if (li) |i| {
            const l = self.lambdas.items[i];
            for (cc.args, 0..) |a, k| {
                if (k < l.param_str.len and self.isStringExpr(a.value.*)) l.param_str[k] = true;
                if (k < l.param_known.len) l.param_known[k] = true;
            }
            if (l.fn_ref == null) try self.gcSyncCaptures(tmp, l, .into_env);
        }
        try self.emit(.{ .local_get = tmp });
        for (cc.args, 0..) |a, k| {
            const pdecl: ?ast.TypeRef = if (decl) |d| (if (k < d.ft.function.params.len) d.ft.function.params[k] else null) else null;
            const pr: Repr = if (pdecl) |pt| (self.gcSigRepr(pt, decl.?.gps) orelse return self.gcFail("an argument against a parameter of no repr")) else self.wasmTypeOf(a.value.*);
            self.expected_fn = if (pdecl) |pt| (if (pt == .function and a.value.* == .function) pt else null) else null;
            defer self.expected_fn = null;
            if (pdecl == null) if (li) |i| {
                const seen = self.lambdas.items[i].param_seen;
                if (k < seen.len) {
                    if (seen[k]) |have| {
                        if (!self.sameVal(have, pr)) return self.gcFail("a closure called with arguments of two reprs");
                    } else seen[k] = pr;
                }
            };
            try self.lowerCoerced(a.value.*, pr);
            try self.gcBox(pr);
        }
        for (cc.trailing) |t| {
            self.expected_fn = if (decl) |d| (if (d.ft.function.params.len == cc.args.len + 1) d.ft.function.params[cc.args.len] else null) else null;
            defer self.expected_fn = null;
            try self.lowerLambdaValue(t.params, t.body, self.call_loc);
        }
        try self.gcEmitIndirect(tmp, cc.args.len + cc.trailing.len);
        if (li) |i| {
            const l = self.lambdas.items[i];
            if (l.fn_ref == null) try self.gcSyncCaptures(tmp, l, .out_of_env);
        }
        const rr = self.gcValueCallRepr(cc) orelse return self.gcFail("a call through a function value of no known result");
        if (li) |i| if (decl == null) {
            self.lambdas.items[i].ret_seen = rr;
        };
        try self.gcUnbox(rr);
        return true;
    }

    /// Around a call through a closure local (`syncCaptures`) in a GC module:
    /// the environment's fields.
    fn gcSyncCaptures(self: *Emitter, env: []const u8, l: Lifted, dir: enum { into_env, out_of_env }) anyerror!void {
        const ety = self.gcTyIndex(.{ .env = l.idx });
        for (l.captures, 0..) |cp, i| {
            // Decision 105 — a captured `var` is one variable on both sides:
            // what the function wrote since the closure was made is what the
            // body reads (every capture copied in), what the body assigns is
            // what the function reads after (the threaded ones copied out).
            if (dir == .out_of_env and !cp.threaded) continue;
            if (!self.locals.contains(cp.name)) continue;
            const f: wat.FieldRef = .{ .ty = ety, .field = @intCast(2 + i) };
            try self.emit(.{ .local_get = env });
            try self.emit(.{ .ref_cast = ValType.def(ety) });
            switch (dir) {
                .into_env => {
                    try self.emit(.{ .local_get = cp.name });
                    try self.emitCf(.{ .struct_set = f }, "sync {s} into env", .{cp.name});
                },
                .out_of_env => {
                    try self.emitCf(.{ .struct_get = f }, "sync {s} from env", .{cp.name});
                    try self.emit(.{ .local_set = cp.name });
                },
            }
        }
    }

    /// The closure a lambda value is, in a GC module: a struct of its
    /// environment type holding the table index, the mark and the captures.
    fn gcClosureNew(self: *Emitter, idx: u32, caps: []const Captured, mark: ?bool) anyerror!void {
        try self.emit(try self.constInt(idx));
        try self.emit(try self.constInt(@intFromBool(mark orelse false)));
        for (caps) |cp| try self.emitCf(.{ .local_get = cp.name }, "capture {s}", .{cp.name});
        try self.emit(.{ .struct_new = self.gcTyIndex(.{ .env = idx }) });
    }

    /// The lifted lambda `l` in a GC module: the typed body and the table's
    /// wrapper over it.
    fn gcEmitLifted(self: *Emitter, l: Lifted) anyerror!void {
        if (l.fn_ref) |target| return self.gcFnRefWrapper(l, target);
        self.resetFnState(null);
        const outer_template = self.cur_template;
        self.cur_template = l.template_of;
        defer self.cur_template = outer_template;
        const outer_origin = self.foreign_origin;
        self.foreign_origin = l.origin;
        defer self.foreign_origin = outer_origin;
        const ar = self.arena();
        const ety = self.gcTyIndex(.{ .env = l.idx });
        const env_vt = ValType.def(ety);
        self.gc_env_ty = ety;
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        var reprs: std.ArrayListUnmanaged(Repr) = .empty;
        try params.append(ar, wat.Builder.param("__env", env_vt));
        try self.locals.put("__env", .{ .ref = .closure });
        var c: Capture = .{};
        self.open(&c);
        for (l.params, 0..) |p, i| {
            const ft: ?ast.TypeRef = if (i < l.param_ft.len) l.param_ft[i] else null;
            var r: Repr = undefined;
            if (ft) |t| {
                r = self.gcSigRepr(t, null) orelse return self.gcFail("a lambda parameter of a type with no repr");
                try self.noteTypedBinder(p, t);
            } else if (i < l.param_seen.len and l.param_seen[i] != null) {
                r = l.param_seen[i].?;
                if (r == .ref and r.ref == .record) try self.local_types.put(p, r.ref.record);
                if (r.isStr()) try self.str_locals.put(p, {});
                if (r == .ref and r.ref != .record and !r.isStr() and r.ref != .unknown and r.ref != .closure) return self.gcFail("a lambda parameter of a reference with no declared type");
            } else if (i < l.param_str.len and l.param_str[i]) {
                r = Repr.string;
                try self.str_locals.put(p, {});
            } else if (i < l.param_rec.len and l.param_rec[i] != null) {
                r = .{ .ref = .{ .record = l.param_rec[i].? } };
                try self.local_types.put(p, l.param_rec[i].?);
            } else if (i < l.param_tref.len and l.param_tref[i] != null) {
                r = self.reprOf(l.param_tref[i].?);
            } else {
                // Nothing types the parameter: its word is a guess, and a
                // wrong one would trap at the cast, so a body that reads it
                // keeps its module in linear memory.
                var reads = false;
                for (l.body) |st| {
                    var names: std.ArrayListUnmanaged([]const u8) = .empty;
                    try self.collectIdents(st.expr, &names);
                    for (names.items) |n| if (std.mem.eql(u8, n, p)) {
                        reads = true;
                    };
                }
                if (reads) return self.gcFail("a lambda parameter nothing types");
                r = .i32;
            }
            if (i < l.param_tref.len) if (l.param_tref[i]) |t| try self.local_typerefs.put(p, t);
            try self.locals.put(p, r);
            try params.append(ar, wat.Builder.param(p, self.vtOf(r)));
            try reprs.append(ar, r);
        }
        // A parameter the body reads that nothing typed (as in linear memory).
        var read: std.ArrayListUnmanaged([]const u8) = .empty;
        for (l.body) |st| try self.collectIdents(st.expr, &read);
        for (l.params, 0..) |p, i| {
            if (i < l.param_known.len and !l.param_known[i]) for (read.items) |n| {
                if (!std.mem.eql(u8, n, p)) continue;
                try self.refuseUnlessTemplate(l.loc, "lambda parameter `{s}`: nothing gives it a type the wasm backend can see", .{p});
                break;
            };
        }
        for (l.captures, 0..) |cp, i| {
            try self.declareLocal(cp.name, cp.ty);
            if (cp.threaded) try self.env_slots.put(cp.name, @intCast(2 + i));
            if (cp.str) try self.str_locals.put(cp.name, {});
            if (cp.bool_) try self.bool_locals.put(cp.name, {});
            if (cp.typeref) |t| try self.local_typerefs.put(cp.name, t);
            if (cp.record) |r| try self.local_types.put(cp.name, r);
            if (cp.arr_elem) |ek| {
                try self.arr_locals.put(cp.name, {});
                try self.arr_elem_locals.put(cp.name, ek);
            }
            try self.emit(.{ .local_get = "__env" });
            try self.emit(.{ .struct_get = .{ .ty = ety, .field = @intCast(2 + i) } });
            try self.emit(.{ .local_set = cp.name });
        }
        try self.declareScratch("_try", countTrys(l.body));
        try self.declareScratch("__mem", self.countMems(l.body));
        try self.emitLocalDecls(l.body);
        // Front 164 s2 P4 — an `async { }` block, or a component whose body
        // awaits (decision 504): the body is a state machine whose answer is
        // the task's value; the wrapper answers the task.
        if (l.async_block) try self.beginMachine(l.body);
        // Decision 105 (144 B-128) — an `iter` loop's body: a generator
        // machine, its closure answering the handle (§ generators).
        if (l.generator) {
            defer self.machine = null;
            defer self.gen_item = null;
            const own: ?[]const u8 = if (l.body.len == 1 and l.body[0].expr == .loop) l.body[0].expr.loop.label else null;
            try self.beginGenMachine(l.body, l.gen_item, own);
            self.cur_result = .{ .ref = .gen };
            self.cur_ret_typeref = null;
            // The captures were loaded from the environment above, in `c`:
            // every entry reads them again (a consumer syncs them in).
            self.fn_has_result = false;
            const gtail = try self.emitBody(l.body, false);
            if (gtail != .terminated) try self.emitC(zero, "the sequence ended");
            const gseq = self.seal(&c, if (gtail == .terminated) .terminated else .{ .value = .i32 });
            const gname = try std.fmt.allocPrint(ar, "{s}__b", .{l.name});
            try self.emitGenMachine(try self.builder().func(.{
                .name = gname,
                .params = params.items,
                .result = .i32,
                .locals = try self.localLines(),
                .body = gseq,
            }), "__env");
            var gwc: Capture = .{};
            self.open(&gwc);
            try self.emit(.{ .local_get = "__env" });
            try self.emit(.{ .ref_cast = env_vt });
            try self.emit(.{ .call = gname });
            const gwbody = self.seal(&gwc, .{ .value = .anyref });
            try self.item(.{ .func = try self.builder().func(.{
                .name = l.name,
                .params = &.{wat.Builder.param("__env", self.gcTy(.closure))},
                .result = .anyref,
                .body = gwbody,
            }) });
            return;
        }
        defer self.machine = null;
        const tail_type: ?Repr = if (l.body.len > 0) self.lambdaTailType(l.body) else null;
        const ret: Repr = if (l.ret_ft) |rt|
            // A declared answer naming a type parameter nothing binds here
            // (`attempt<T>(f: fn() -> T)`): the body's own, in its box.
            (self.gcSigRepr(rt, null) orelse tail_type orelse return self.gcFail("a lambda answer of a type with no repr"))
        else if (l.ret_seen) |rs|
            rs
        else
            tail_type orelse .i32;
        if (l.ret_seen) |rs| if (!self.sameVal(rs, ret)) return self.gcFail("a closure called for an answer its body does not give");
        self.cur_result = ret;
        self.fn_has_result = true;
        self.cur_ret_typeref = l.ret_ft;
        const tail = try self.emitBody(l.body, true);
        const outer_loc = self.stmt_loc;
        self.stmt_loc = l.loc;
        if (tail == .value) if (tail_type) |t| try self.gcConvertTail(t, ret);
        self.stmt_loc = outer_loc;
        const body = self.seal(&c, if (tail == .terminated) .terminated else .{ .value = self.vtOf(ret) });
        const bname = try std.fmt.allocPrint(ar, "{s}__b", .{l.name});
        const bfunc = try self.builder().func(.{
            .name = bname,
            .params = params.items,
            .result = self.vtOf(ret),
            .locals = try self.localLines(),
            .body = body,
        });
        if (l.async_block) try self.emitStateMachine(bfunc) else try self.item(.{ .func = bfunc });
        // The table's wrapper.
        var wparams: std.ArrayListUnmanaged(wat.Param) = .empty;
        try wparams.append(ar, wat.Builder.param("__env", self.gcTy(.closure)));
        var wc: Capture = .{};
        self.open(&wc);
        try self.emit(.{ .local_get = "__env" });
        try self.emit(.{ .ref_cast = env_vt });
        for (reprs.items, 0..) |r, i| {
            const pn = try std.fmt.allocPrint(ar, "__a{d}", .{i});
            try wparams.append(ar, wat.Builder.param(pn, .anyref));
            try self.emit(.{ .local_get = pn });
            try self.gcUnbox(r);
        }
        try self.emit(.{ .call = bname });
        if (!l.async_block) try self.gcBox(ret);
        const wbody = self.seal(&wc, .{ .value = .anyref });
        try self.item(.{ .func = try self.builder().func(.{
            .name = l.name,
            .params = wparams.items,
            .result = .anyref,
            .body = wbody,
        }) });
    }

    /// The trampoline of a top-level fn used as a value, in a GC module.
    fn gcFnRefWrapper(self: *Emitter, l: Lifted, target: []const u8) anyerror!void {
        const sig = self.fn_sigs.get(target) orelse return self.gcFail("a function value of a function with no signature");
        const ar = self.arena();
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        try params.append(ar, wat.Builder.param("__env", self.gcTy(.closure)));
        var c: Capture = .{};
        self.open(&c);
        for (sig.params, 0..) |pr, i| {
            const pn = try std.fmt.allocPrint(ar, "__a{d}", .{i});
            try params.append(ar, wat.Builder.param(pn, .anyref));
            try self.emit(.{ .local_get = pn });
            try self.gcUnbox(pr);
        }
        try self.emit(.{ .call = target });
        if (sig.result) |r| try self.gcBox(r) else try self.emit(.{ .ref_null = .anyref });
        const body = self.seal(&c, .{ .value = .anyref });
        try self.item(.{ .func = try self.builder().func(.{
            .name = l.name,
            .params = params.items,
            .result = .anyref,
            .body = body,
        }) });
    }

    /// The tail of a lifted lambda's body, converted to the repr it answers;
    /// a lossy conversion falls back to linear memory rather than refusing.
    fn gcConvertTail(self: *Emitter, from: Repr, to: Repr) anyerror!void {
        if (lossyConversion(from, to)) return self.gcFail("a closure whose answer is narrowed");
        try self.emitConvert(from, to);
    }

    /// A top-level fn used as a value: a closure over a trampoline that
    /// forwards its arguments.
    fn lowerFnRef(self: *Emitter, name: []const u8, loc: ?ast.Loc) anyerror!void {
        // A generic fn as a value: its trampoline calls the one generic body.
        if (self.generic_fns.contains(name)) try self.noteTemplateCall(name, loc);
        const idx = self.fn_refs.get(name) orelse blk: {
            const i: u32 = @intCast(self.lambdas.items.len);
            try self.lambdas.append(self.alloc, .{
                .name = try std.fmt.allocPrint(self.reg_arena.allocator(), "__fnref_{s}", .{name}),
                .params = &.{},
                .body = &.{},
                .captures = &.{},
                .fn_ref = name,
                .idx = i,
            });
            try self.fn_refs.put(name, i);
            break :blk i;
        };
        try self.emitClosureCell(idx, &.{}, null);
    }

    /// `f(a, b)` where `f` is a local or global holding a function value,
    /// `r.field(a)` where the field holds one, or `t._1(a)` — a **tuple slot**
    /// holding one, which is also what a labelled element arrives as: the checker
    /// resolves `c.set(9)` on `#(value: i32, set: fn(n: i32) -> i32)` to the
    /// position, so the callee here is `_1`. Without that last case the call fell
    /// into the unresolved path and trapped (`;; unresolved call: _1/1`), which is
    /// the whole of what "wasm has no function values" ever meant.
    fn lowerValueCall(self: *Emitter, cc: anytype) anyerror!bool {
        if (self.mode == .gc) return self.gcValueCall(cc);
        // The slot the function value sits in, for a call through a receiver.
        const slotOffset = struct {
            fn f(em: *Emitter, recv: ast.Expr, member: []const u8) ?u32 {
                if (em.recordTypeOfExpr(recv)) |rty| {
                    if (em.fieldOffsetIn(rty, member)) |off| return off;
                }
                if (tupleIndex(member)) |idx| return idx * 4;
                return null;
            }
        }.f;
        const is_value = blk: {
            if (cc.calleeExpr != null) break :blk true;
            if (cc.receiver) |recv| break :blk slotOffset(self, recv.*, cc.callee) != null;
            break :blk self.locals.contains(cc.callee) or self.globals.contains(cc.callee);
        };
        if (!is_value) return false;
        const ra = self.reg_arena.allocator();
        const tmp = try std.fmt.allocPrint(ra, "__fnv{d}", .{self.loop_seq});
        self.loop_seq += 1;
        try self.declareLocal(tmp, .i32);
        // A behavior literal's `self` method: the receiver is its first
        // argument, held here between the slot load and the call.
        const self_recv: ?[]const u8 = if (cc.calleeExpr == null) if (cc.receiver) |recv| blk: {
            const rty = self.recordTypeOfExpr(recv.*) orelse break :blk null;
            const key = try std.fmt.allocPrint(ra, "{s}.{s}", .{ rty, cc.callee });
            if (!self.self_method_fields.contains(key)) break :blk null;
            const rt = try std.fmt.allocPrint(ra, "__self{d}", .{self.loop_seq});
            self.loop_seq += 1;
            try self.declareLocal(rt, .i32);
            break :blk rt;
        } else null else null;
        if (cc.calleeExpr) |ce| {
            // `adder(3)(4)` — the callee is the VALUE of an expression (01
            // handover 15), the function value the inner call answered.
            try self.lowerValue(ce.*);
        } else if (cc.receiver) |recv| {
            const off = slotOffset(self, recv.*, cc.callee).?;
            try self.lowerValue(recv.*);
            if (self_recv) |rt| try self.emit(.{ .local_tee = rt });
            try self.emitCf(.{ .load = .{ .offset = off } }, ".{s}", .{cc.callee});
        } else if (self.locals.contains(cc.callee)) {
            // Through `resolveName`: a name narrowed by `is fn(…) -> T`
            // (decision 254) is the closure its box held.
            try self.emit(.{ .local_get = self.resolveName(cc.callee) });
        } else {
            try self.emit(.{ .global_get = self.globalName(cc.callee) });
        }
        try self.emit(.{ .local_set = tmp });
        const closure: ?Lifted = if (cc.calleeExpr == null and cc.receiver == null and self.locals.contains(cc.callee))
            if (self.closure_locals.get(cc.callee)) |li| self.lambdas.items[li] else null
        else if (cc.calleeExpr == null and cc.receiver != null)
            // `lam.value("d")`: the lambda a constructor stored in that field
            // of that local (`field_closures`).
            (if (self.fieldClosureOf(cc.receiver.?.*, cc.callee)) |li| self.lambdas.items[li] else null)
        else
            null;
        if (closure) |l| {
            for (cc.args, 0..) |a, i| {
                if (i < l.param_str.len and self.isStringExpr(a.value.*)) l.param_str[i] = true;
                if (i < l.param_known.len) l.param_known[i] = true;
            }
            try self.syncCaptures(tmp, l.captures, .into_env);
        }
        try self.emit(.{ .local_get = tmp });
        if (self_recv) |rt| try self.emit(.{ .local_get = rt });
        const cells = self.valueCallCells(cc);
        for (cc.args, 0..) |a, i| {
            const cell: Cell = if (cells) |fc| (if (i < fc.params.len) fc.params[i] else .none) else .none;
            if (cell != .none) try self.lowerCellWord(a.value.*, cell) else try self.lowerCoerced(a.value.*, .i32);
        }
        for (cc.trailing) |t| try self.lowerLambdaValue(t.params, t.body, self.call_loc);
        try self.emitIndirect(tmp, cc.args.len + cc.trailing.len + @as(usize, if (self_recv != null) 1 else 0));
        if (closure) |l| try self.syncCaptures(tmp, l.captures, .out_of_env);
        if (cells) |fc| try self.emitFromCell(fc.ret);
        return true;
    }

    /// Around a call through a closure local, copy each capture the lambda
    /// assigns into its environment slot (the caller may have changed it since
    /// the closure was made) or back out of it (the lambda may have changed
    /// it). The call's result stays on the stack underneath.
    fn syncCaptures(self: *Emitter, env: []const u8, caps: []const Captured, dir: enum { into_env, out_of_env }) anyerror!void {
        for (caps, 0..) |cp, i| {
            if (!cp.threaded) continue;
            const ty = self.locals.get(cp.name) orelse continue;
            const cell = Cell.of(cp.ty);
            const slot: wat.MemArg = .{ .offset = @intCast((i + 1) * 4) };
            switch (dir) {
                .into_env => {
                    try self.emit(.{ .local_get = env });
                    if (cell != .none) try self.emit(.{ .load = slot });
                    try self.emit(.{ .local_get = cp.name });
                    try self.emitConvert(ty, cell.ty());
                    try self.emitCf(.{ .store = if (cell != .none) .{ .ty = (cell.ty()).num() } else slot }, "sync {s} into env", .{cp.name});
                },
                .out_of_env => {
                    try self.emit(.{ .local_get = env });
                    try self.emitCf(.{ .load = slot }, "sync {s} from env", .{cp.name});
                    try self.emitFromCell(cell);
                    try self.emitConvert(cell.ty(), ty);
                    try self.emit(.{ .local_set = cp.name });
                },
            }
        }
    }

    /// Inside a lifted lambda, after `name` was assigned: when it is a
    /// threaded capture, store it back into the environment cell.
    fn writeBackCapture(self: *Emitter, name: []const u8) anyerror!void {
        const off = self.env_slots.get(name) orelse return;
        const ty = self.locals.get(name) orelse return;
        if (self.mode == .gc) {
            // The environment struct's field `off`, written in place.
            try self.emit(.{ .local_get = "__env" });
            try self.emit(.{ .local_get = name });
            try self.emitCf(.{ .struct_set = .{ .ty = self.gc_env_ty, .field = off } }, "write {s} back to env", .{name});
            return;
        }
        const cell = Cell.of(ty);
        try self.emit(.{ .local_get = "__env" });
        if (cell != .none) try self.emit(.{ .load = .{ .offset = off } });
        try self.emit(.{ .local_get = name });
        try self.emitConvert(ty, cell.ty());
        try self.emitCf(.{ .store = if (cell != .none) .{ .ty = (cell.ty()).num() } else .{ .offset = off } }, "write {s} back to env", .{name});
    }

    /// Whether a statement list assigns the plain name `n` (`n = …`, `n += …`),
    /// in nested branches, loops, arms and lambdas included.
    fn bodyAssigns(body: []const ast.Stmt, n: []const u8) bool {
        for (body) |st| if (exprAssigns(st.expr, n)) return true;
        return false;
    }

    fn exprAssigns(e: ast.Expr, n: []const u8) bool {
        return switch (e) {
            .binding => |b| switch (b.kind) {
                .assign => |a| switch (a.target) {
                    .name => |t| std.mem.eql(u8, t, n) or exprAssigns(a.value.*, n),
                    .fieldAccess => exprAssigns(a.value.*, n),
                },
                .localBind => |lb| exprAssigns(lb.value.*, n),
                .localBindDestruct => |lb| exprAssigns(lb.value.*, n),
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| bodyAssigns(i.then_, n) or (if (i.else_) |els| bodyAssigns(els, n) else false),
                .tryCatch => |tc| exprAssigns(tc.expr.*, n) or exprAssigns(tc.handler.*, n),
            },
            .loop => |lp| bodyAssigns(lp.body, n),
            .function => |f| bodyAssigns(f.kind.body, n),
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    for (cc.args) |a| if (exprAssigns(a.value.*, n)) break :blk true;
                    for (cc.trailing) |t| if (bodyAssigns(t.body, n)) break :blk true;
                    break :blk false;
                },
                .pipeline => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| exprAssigns(inner.*, n),
                .case => |cs| blk: {
                    for (cs.arms) |arm| if (exprAssigns(arm.body, n)) break :blk true;
                    break :blk false;
                },
                else => false,
            },
            else => false,
        };
    }

    fn fieldLambdaCallIsString(self: *Emitter, cc: anytype) bool {
        const recv = cc.receiver orelse return false;
        const rty = self.recordTypeOfExpr(recv.*) orelse return false;
        var buf: [256]u8 = undefined;
        const key = std.fmt.bufPrint(&buf, "{s}.{s}", .{ rty, cc.callee }) catch return false;
        const fl = self.field_lambdas.get(key) orelse return false;
        const skip: usize = if (self.self_method_fields.contains(key)) 1 else 0;
        const flags = self.arena().alloc(bool, fl.params.len) catch return false;
        for (flags, 0..) |*f, i| f.* = i >= skip and i - skip < cc.args.len and self.isStringExpr(cc.args[i - skip].value.*);
        const saved = self.param_shape;
        defer self.param_shape = saved;
        self.param_shape = .{ .names = fl.params, .str = flags };
        return self.bodyIsString(fl.body);
    }

    /// Whether a call through the closure local bound to lifted lambda `li`
    /// yields a string: its body is judged with each parameter taking the
    /// shape of this call's argument (`{ x, y -> x + y }` over two strings).
    fn closureCallIsString(self: *Emitter, li: u32, cc: anytype) bool {
        const l = self.lambdas.items[li];
        if (l.fn_ref != null) return false;
        const flags = self.arena().alloc(bool, l.params.len) catch return false;
        for (flags, 0..) |*f, i| f.* = (i < l.param_str.len and l.param_str[i]) or
            (i < cc.args.len and self.isStringExpr(cc.args[i].value.*));
        const saved = self.param_shape;
        defer self.param_shape = saved;
        self.param_shape = .{ .names = l.params, .str = flags };
        return self.bodyIsString(l.body);
    }

    const FnCells = struct { params: []const Cell, ret: Cell };

    const GlobalLambda = struct { params: []const []const u8, body: []const ast.Stmt };

    /// The cells a call through a function value passes its float and
    /// 64-bit arguments in and reads its answer out of: from the lambda the
    /// closure local holds, else from the function type of the value — a
    /// local's (a `?fn(…)` binder's included) or the expression's that
    /// answers it. Null when nothing says; a float argument is then refused.
    fn valueCallCells(self: *Emitter, cc: anytype) ?FnCells {
        if (cc.calleeExpr == null and cc.receiver == null) {
            if (self.closure_locals.get(cc.callee)) |li| {
                const l = self.lambdas.items[li];
                if (l.fn_ref == null) return .{ .params = l.param_cell, .ret = l.ret_cell };
            }
        }
        const ft: ast.TypeRef = blk: {
            if (cc.calleeExpr) |ce| break :blk self.typeRefOf(ce.*) orelse return null;
            if (cc.receiver != null) return null;
            break :blk self.local_typerefs.get(self.resolveName(cc.callee)) orelse
                self.local_typerefs.get(cc.callee) orelse return null;
        };
        if (ft != .function) return null;
        const pts = ft.function.params;
        const out = self.arena().alloc(Cell, pts.len) catch return null;
        for (pts, out) |pt, *o| o.* = cellOfTypeRef(pt);
        return .{ .params = out, .ret = cellOfTypeRef(ft.function.returnType.*) };
    }

    /// The box of the value on the stack, of a cell's width.
    fn emitBoxCell(self: *Emitter, cell: Cell) !void {
        try self.emit(self.builder().helper(switch (cell) {
            .f64 => .box_f64,
            .i64 => .box_i64,
            .none => unreachable,
        }));
    }

    /// With the environment and `argc` arguments on the stack, call the
    /// function value held in `fnv`.
    fn emitIndirect(self: *Emitter, fnv: []const u8, argc: usize) anyerror!void {
        self.uses_table = true;
        try self.emit(.{ .local_get = fnv });
        try self.emitC(.{ .load = .{} }, "table index");
        const params = try self.arena().alloc(ValType, argc + 1);
        for (params) |*p| p.* = .i32;
        try self.emit(.{ .call_indirect = .{ .params = params, .result = .i32 } });
    }

    /// Emit every function queued while lowering: lifted lambdas (which may
    /// lift more) and reached interface associated fns.
    fn emitPendingFns(self: *Emitter) anyerror!void {
        var li: usize = 0;
        var ai: usize = 0;
        var si: usize = 0;
        var mi: usize = 0;
        while (li < self.lambdas.items.len or ai < self.assoc_needed.items.len or si < self.spec_pending.items.len or mi < self.mspec_pending.items.len) {
            while (mi < self.mspec_pending.items.len) : (mi += 1) {
                const sp = self.mspec_pending.items[mi];
                const saved = .{ self.rewrites, self.instance_lowerings, self.global_renames, self.owner_tparams, self.field_subs_owner, self.field_subs, self.foreign_origin };
                self.foreign_origin = sp.origin;
                self.rewrites = sp.rewrites;
                self.instance_lowerings = sp.lowerings;
                self.global_renames = sp.renames;
                self.owner_tparams = sp.tparams;
                self.field_subs_owner = sp.owner;
                self.field_subs = sp.subs;
                self.in_spec = true;
                defer {
                    self.rewrites = saved[0];
                    self.instance_lowerings = saved[1];
                    self.global_renames = saved[2];
                    self.owner_tparams = saved[3];
                    self.field_subs_owner = saved[4];
                    self.field_subs = saved[5];
                    self.foreign_origin = saved[6];
                    self.in_spec = false;
                }
                try self.emitMemberFn(sp.owner, sp.method);
            }
            while (si < self.spec_pending.items.len) : (si += 1) {
                const sp = self.spec_pending.items[si];
                const saved = .{ self.rewrites, self.instance_lowerings, self.global_renames, self.foreign_origin };
                self.foreign_origin = sp.origin;
                self.rewrites = sp.rewrites;
                self.instance_lowerings = sp.lowerings;
                self.global_renames = sp.renames;
                self.in_spec = true;
                defer {
                    self.rewrites = saved[0];
                    self.instance_lowerings = saved[1];
                    self.global_renames = saved[2];
                    self.foreign_origin = saved[3];
                    self.in_spec = false;
                }
                try self.emitFn(sp.decl);
            }
            while (li < self.lambdas.items.len) : (li += 1) {
                const l = self.lambdas.items[li];
                const saved = .{ self.rewrites, self.instance_lowerings, self.global_renames };
                if (l.rewrites) |r| self.rewrites = r;
                if (l.lowerings) |il| self.instance_lowerings = il;
                if (l.fn_ref == null) self.global_renames = l.renames;
                defer {
                    self.rewrites = saved[0];
                    self.instance_lowerings = saved[1];
                    self.global_renames = saved[2];
                }
                try self.emitLifted(l);
            }
            while (ai < self.assoc_needed.items.len) : (ai += 1) {
                const sym = self.assoc_needed.items[ai];
                if (self.assoc_emitted.contains(sym)) continue;
                try self.assoc_emitted.put(sym, {});
                const m = self.iface_assoc.get(sym).?;
                try self.emitFn(.{
                    .isPub = false,
                    .name = sym,
                    .genericParams = m.genericParams,
                    .params = m.params,
                    .returnType = m.returnType,
                    .body = m.body.?,
                });
            }
        }
    }

    fn emitLifted(self: *Emitter, l: Lifted) anyerror!void {
        if (self.mode == .gc) return self.gcEmitLifted(l);
        self.resetFnState(.i32);
        const outer_template = self.cur_template;
        self.cur_template = l.template_of;
        defer self.cur_template = outer_template;
        const outer_origin = self.foreign_origin;
        self.foreign_origin = l.origin;
        defer self.foreign_origin = outer_origin;
        const ar = self.arena();
        var params: std.ArrayListUnmanaged(wat.Param) = .empty;
        try params.append(ar, wat.Builder.param("__env", .i32));
        try self.locals.put("__env", .i32);

        var c: Capture = .{};
        self.open(&c);
        if (l.fn_ref) |target| {
            const sig = self.fn_sigs.get(target).?;
            for (sig.params, 0..) |pt, i| {
                const pn = try std.fmt.allocPrint(ar, "__a{d}", .{i});
                try params.append(ar, wat.Builder.param(pn, .i32));
                try self.emit(.{ .local_get = pn });
                // A float or 64-bit argument arrives in its cell.
                const cell = Cell.of(pt);
                try self.emitFromCell(cell);
                try self.emitConvert(cell.ty(), pt);
            }
            try self.emit(.{ .call = target });
            const outer_loc = self.stmt_loc;
            self.stmt_loc = l.loc;
            if (sig.result) |r| {
                const cell = Cell.of(r);
                if (cell != .none) {
                    try self.emitConvert(r, cell.ty());
                    try self.emitBoxCell(cell);
                } else try self.emitConvert(r, .i32);
            } else try self.emit(zero);
            self.stmt_loc = outer_loc;
        } else {
            for (l.params, 0..) |p, i| {
                if (i < l.param_tref.len) if (l.param_tref[i]) |t| try self.local_typerefs.put(p, t);
                const cell: Cell = if (i < l.param_cell.len) l.param_cell[i] else .none;
                if (cell != .none) {
                    // The argument is its cell's address: the parameter is a
                    // local of the value's width, read out of the cell first.
                    const pn = try std.fmt.allocPrint(ar, "__cell_{s}", .{p});
                    try params.append(ar, wat.Builder.param(pn, .i32));
                    try self.locals.put(pn, .i32);
                    try self.declareLocal(p, cell.ty());
                    try self.emit(.{ .local_get = pn });
                    try self.emitFromCell(cell);
                    try self.emit(.{ .local_set = p });
                    continue;
                }
                try params.append(ar, wat.Builder.param(p, .i32));
                try self.locals.put(p, .i32);
                if (i < l.param_str.len and l.param_str[i]) try self.str_locals.put(p, {});
                if (i < l.param_rec.len) if (l.param_rec[i]) |r| try self.local_types.put(p, r);
            }
            // A parameter the body reads that nothing typed: the word it
            // holds may be a string or an integer, and the body's `+`, `==`
            // and `@print` would pick one by guess. Refused where the lambda
            // is written.
            var read: std.ArrayListUnmanaged([]const u8) = .empty;
            for (l.body) |st| try self.collectIdents(st.expr, &read);
            for (l.params, 0..) |p, i| {
                if (i < l.param_known.len and !l.param_known[i]) for (read.items) |n| {
                    if (!std.mem.eql(u8, n, p)) continue;
                    try self.refuseUnlessTemplate(l.loc, "lambda parameter `{s}`: nothing gives it a type the wasm backend can see", .{p});
                    break;
                };
            }
            for (l.captures, 0..) |cp, i| {
                try self.declareLocal(cp.name, cp.ty);
                if (cp.threaded) try self.env_slots.put(cp.name, @intCast((i + 1) * 4));
                if (cp.str) try self.str_locals.put(cp.name, {});
                if (cp.bool_) try self.bool_locals.put(cp.name, {});
                if (cp.typeref) |t| try self.local_typerefs.put(cp.name, t);
                if (cp.record) |r| try self.local_types.put(cp.name, r);
                if (cp.arr_elem) |ek| {
                    try self.arr_locals.put(cp.name, {});
                    try self.arr_elem_locals.put(cp.name, ek);
                }
                const cell = Cell.of(cp.ty);
                try self.emit(.{ .local_get = "__env" });
                try self.emit(.{ .load = .{ .offset = @intCast((i + 1) * 4) } });
                try self.emitFromCell(cell);
                try self.emitConvert(cell.ty(), cp.ty);
                try self.emit(.{ .local_set = cp.name });
            }
            try self.declareScratch("_try", countTrys(l.body));
            try self.declareScratch("__mem", self.countMems(l.body));
            try self.emitLocalDecls(l.body);
            if (l.async_block) try self.beginMachine(l.body);
            const tail_type: ?Repr = if (l.body.len > 0) self.wasmTypeOf(l.body[ast.lastRealIndex(l.body)].expr) else null;
            const tail = try self.emitBody(l.body, true);
            // A closure answers through the indirect call's `i32` word: a
            // float or an `i64` answer leaves in its cell when the function
            // type says so (`ret_cell`), and is refused at the lambda else.
            const outer_loc = self.stmt_loc;
            self.stmt_loc = l.loc;
            if (tail == .value) if (tail_type) |t| {
                if (l.ret_cell != .none) {
                    try self.emitConvert(t, l.ret_cell.ty());
                    try self.emitBoxCell(l.ret_cell);
                } else try self.emitConvert(t, .i32);
            };
            self.stmt_loc = outer_loc;
        }
        const body = self.seal(&c, .{ .value = .i32 });
        defer self.machine = null;
        const func = try self.builder().func(.{
            .name = l.name,
            .params = params.items,
            .result = .i32,
            .locals = try self.localLines(),
            .body = body,
        });
        if (l.async_block) return self.emitStateMachine(func);
        try self.item(.{ .func = func });
    }

    // ── decision 332: `bigint` ───────────────────────────────────────────────
    //
    // A `bigint` is the address of an immutable block (`wat_prelude.zig`
    // § bigint): `[L][limb0][limb1]…`, `L` the limbs' byte count, negated for
    // a negative value. Its operations are the `bigint` helper group, linked
    // only when a module calls one; a literal is a data segment.

    /// Whether inference typed the operator at `loc` `bigint`.
    fn isBigintAt(self: *Emitter, loc: ast.Loc) bool {
        const il = self.instance_lowerings.get(loc) orelse return false;
        return il == .division and il.division == .bigint;
    }

    /// Whether `e` is a `bigint` value.
    fn isBigintExpr(self: *Emitter, e: ast.Expr) bool {
        const t = self.typeRefOf(e) orelse return false;
        return t == .named and std.mem.eql(u8, t.named, "bigint");
    }

    /// Whether `e` is an `if` one of whose arms answers a `bigint` (in a
    /// union with the other's type).
    fn ifBigintArm(self: *Emitter, e: ast.Expr) bool {
        const br = switch (e) {
            .branch => |b| b,
            else => return false,
        };
        const i = switch (br.kind) {
            .if_ => |x| x,
            else => return false,
        };
        for ([_]?[]const ast.Stmt{ i.then_, i.else_ }) |maybe| {
            const body = maybe orelse continue;
            if (body.len == 0) continue;
            if (self.isBigintExpr(body[ast.lastRealIndex(body)].expr)) return true;
        }
        return false;
    }

    /// `bigint` / `?bigint` for an `if` one of whose arms answers a `bigint`
    /// (the other a `bigint` too, or `null`); null otherwise.
    fn ifBigintTypeRef(self: *Emitter, i: anytype) ?ast.TypeRef {
        var big = false;
        var absent = false;
        for ([_]?[]const ast.Stmt{ i.then_, i.else_ }) |maybe| {
            const body = maybe orelse return null;
            if (body.len == 0) return null;
            const last = body[ast.lastRealIndex(body)].expr;
            if (isNullLit(last)) {
                absent = true;
            } else if (self.isBigintExpr(last)) {
                big = true;
            } else if (self.isOptBigintExpr(last)) {
                big = true;
                absent = true;
            } else return null;
        }
        if (!big) return null;
        if (!absent) return .{ .named = "bigint" };
        const inner = self.reg_arena.allocator().create(ast.TypeRef) catch return null;
        inner.* = .{ .named = "bigint" };
        return .{ .optional = inner };
    }

    /// Whether `e` is a `?bigint` (its block's address, or `0`).
    fn isOptBigintExpr(self: *Emitter, e: ast.Expr) bool {
        const t = self.typeRefOf(e) orelse return false;
        return t == .optional and t.optional.* == .named and std.mem.eql(u8, t.optional.named, "bigint");
    }

    const BigintAssoc = enum { of, parse };

    /// `BigInt.of(n)` / `BigInt.parse(text)` — the program's `bigint.of(n)`
    /// / `bigint.parse(text)`, which inference names by the behavior.
    fn bigintAssoc(self: *Emitter, cc: anytype) ?BigintAssoc {
        const rn = receiverName(cc) orelse return null;
        if (!std.mem.eql(u8, rn, "BigInt") or cc.args.len != 1 or cc.trailing.len != 0) return null;
        if (self.locals.contains(rn) or self.globals.contains(rn) or self.records.contains(rn) or self.enums.contains(rn)) return null;
        if (std.mem.eql(u8, cc.callee, "of")) return .of;
        if (std.mem.eql(u8, cc.callee, "parse")) return .parse;
        return null;
    }

    /// A `bigint` literal (`42n`, `0xFFn`): its magnitude's limbs interned as
    /// a data segment, whose length word is the block's `L` (a literal is
    /// never negative — `-5n` is a negation). The address is the value.
    fn lowerBigintLiteral(self: *Emitter, text: []const u8) anyerror!void {
        const digits = lexerMod.bigintDigits(text);
        var clean: std.ArrayListUnmanaged(u8) = .empty;
        var base: u8 = 10;
        var body = digits;
        if (digits.len > 2 and digits[0] == '0' and std.ascii.isAlphabetic(digits[1])) {
            base = switch (digits[1]) {
                'x', 'X' => 16,
                'o', 'O' => 8,
                else => 2,
            };
            body = digits[2..];
        }
        for (body) |c| if (c != '_') try clean.append(self.arena(), c);
        var m = try std.math.big.int.Managed.init(self.arena());
        try m.setString(base, clean.items);
        var bytes: std.ArrayListUnmanaged(u8) = .empty;
        for (m.toConst().limbs[0..m.len()]) |limb| {
            var buf: [@sizeOf(std.math.big.Limb)]u8 = undefined;
            std.mem.writeInt(std.math.big.Limb, &buf, limb, .little);
            try bytes.appendSlice(self.arena(), &buf);
        }
        // Whole `u32` limbs, none zero on top.
        while (bytes.items.len % 4 != 0) try bytes.append(self.arena(), 0);
        while (bytes.items.len >= 4 and std.mem.allEqual(u8, bytes.items[bytes.items.len - 4 ..], 0)) bytes.items.len -= 4;
        const seg = try self.internString(bytes.items);
        try self.emitCf(try self.constInt(seg.offset), "bigint {s}", .{digits});
    }

    /// `lhs <op> rhs` over two `bigint`s: arithmetic through the group's
    /// helpers (`/` truncates, `%` takes the dividend's sign, a zero divisor
    /// traps), a comparison through std-wasm's `bigint.compare`.
    fn lowerBigintBinOp(self: *Emitter, op: anytype, lhs: ast.Expr, rhs: ast.Expr) anyerror!void {
        const Op = @TypeOf(op);
        try self.lowerValue(lhs);
        try self.lowerValue(rhs);
        switch (op) {
            Op.add, Op.sub => {
                try self.emit(try self.constInt(@as(i32, if (op == Op.sub) 1 else 0)));
                try self.emitStdCall("bigint.add");
            },
            Op.mul => try self.emitStdCall("bigint.multiply"),
            Op.div, Op.mod => {
                try self.emit(try self.constInt(@as(i32, if (op == Op.mod) 1 else 0)));
                try self.emitStdCall("bigint.divmod");
            },
            Op.eq, Op.ne, Op.lt, Op.gt, Op.lte, Op.gte => {
                try self.emitStdCall("bigint.compare");
                try self.emit(zero);
                try self.emit(opOf(.i32, switch (op) {
                    Op.eq => "eq",
                    Op.ne => "ne",
                    Op.lt => "lt_s",
                    Op.gt => "gt_s",
                    Op.lte => "le_s",
                    else => "ge_s",
                }));
            },
            else => return self.refuse(lhs.getLoc(), "the wasm backend has no `{s}` over `bigint` operands", .{@tagName(op)}),
        }
    }

    /// `bigint.of(n)` / `bigint.parse(text)`. `parse` answers the `@Result`
    /// pair: `Ok` holding the block, or `Error` holding the text the other
    /// targets write.
    fn lowerBigintAssoc(self: *Emitter, which: BigintAssoc, cc: anytype) anyerror!void {
        const b = self.builder();
        switch (which) {
            .of => {
                try self.lowerCoerced(callArg(cc, 0).?, .i64);
                try self.emitStdCall("bigint.ofI64");
            },
            .parse => {
                const text = try self.declRes();
                const p = try self.declRes();
                const out = try self.declRes();
                try self.lowerCoerced(callArg(cc, 0).?, .i32);
                try self.emit(.{ .local_tee = text });
                try self.emitStdCall("bigint.parse");
                try self.emit(.{ .local_set = p });
                try self.allocResultPair(out);
                try self.emit(.{ .local_get = p });
                var then_c: Capture = .{};
                self.open(&then_c);
                try self.emit(.{ .local_get = out });
                try self.emit(zero);
                try self.emitC(.{ .store = .{} }, "Ok tag");
                try self.emit(.{ .local_get = out });
                try self.emit(.{ .local_get = p });
                try self.emitC(.{ .store = .{ .offset = 4 } }, "payload");
                const then_seq = self.seal(&then_c, .none);
                var else_c: Capture = .{};
                self.open(&else_c);
                try self.emit(.{ .local_get = out });
                try self.emit(one);
                try self.emitC(.{ .store = .{} }, "Error tag");
                try self.emit(.{ .local_get = out });
                const head = try self.internString("bigint.parse: \"");
                const tail = try self.internString("\" is not an integer");
                try self.emit(try self.constInt(head.offset));
                try self.emit(.{ .local_get = text });
                try self.emit(b.helper(.str_concat));
                try self.emit(try self.constInt(tail.offset));
                try self.emit(b.helper(.str_concat));
                try self.emitC(.{ .store = .{ .offset = 4 } }, "payload");
                const else_seq = self.seal(&else_c, .none);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
                try self.emit(.{ .local_get = out });
            },
        }
    }

    /// Decision 262 — an associated host primitive of a prelude behavior,
    /// lowered to its prelude helper: `String.fromCodepoint(cp)` is
    /// std-wasm's `text.fromCodepoint`, which writes the code point's UTF-8 bytes and traps on
    /// a value that is no Unicode scalar value (as erlang's `/utf8` raises and
    /// the Node cell throws). Null for any other call, and when `String` names
    /// something of the program's own.
    fn primAssocHelper(self: *Emitter, cc: anytype) ?[]const u8 {
        const rn = receiverName(cc) orelse return null;
        if (self.locals.contains(rn) or self.globals.contains(rn) or self.records.contains(rn) or self.enums.contains(rn)) return null;
        if (std.mem.eql(u8, rn, "String") and std.mem.eql(u8, cc.callee, "fromCodepoint") and cc.args.len == 1 and cc.trailing.len == 0) return stdMethodExport("String", "fromCodepoint").?;
        return null;
    }

    /// `Iface_method` when `cc` is `Iface.method(…)` naming an interface
    /// associated `default fn`.
    fn assocSym(self: *Emitter, cc: anytype) ?[]const u8 {
        const rn = receiverName(cc) orelse return null;
        if (self.locals.contains(rn) or self.globals.contains(rn)) return null;
        const sym = std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ rn, cc.callee }) catch return null;
        // An interface associated `default fn`, or a record's or an enum's own
        // fn called on the type (`Response.ok(…)`, `Shape.unit()` — which took
        // the variant path and answered `0 ;; unknown variant`).
        if (self.iface_assoc.contains(sym)) return sym;
        // An imported behavior's alias (`Area.scaled` for `Shape.scaled`).
        if (self.import_aliases.get(rn)) |declared| {
            const real = std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ declared, cc.callee }) catch return null;
            if (self.iface_assoc.contains(real)) return real;
            _ = std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ rn, cc.callee }) catch return null;
        }
        if ((self.records.contains(rn) or self.enums.contains(rn)) and self.fn_sigs.contains(sym)) return sym;
        return null;
    }

    /// Every plain identifier `e` mentions (reads and assignment targets),
    /// nested lambdas included — the candidates a lifted lambda captures.
    fn collectIdents(self: *Emitter, e: ast.Expr, out: *std.ArrayListUnmanaged([]const u8)) anyerror!void {
        const ra = self.reg_arena.allocator();
        switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| try out.append(ra, n),
                .identAccess => |ia| try self.collectIdents(ia.receiver.*, out),
                .dotIdent => {},
            },
            .binaryOp => |b| {
                try self.collectIdents(b.lhs.*, out);
                try self.collectIdents(b.rhs.*, out);
            },
            .unaryOp => |u| try self.collectIdents(u.expr.*, out),
            .call => |c| switch (c.kind) {
                .call => |cc| {
                    if (cc.receiver) |r| try self.collectIdents(r.*, out);
                    // `f(x)(y)`: the called expression's names are read too
                    // (a component run, `(state(start))(scope)`).
                    if (cc.calleeExpr) |ce| try self.collectIdents(ce.*, out) else if (!cc.is_builtin and cc.receiver == null) try out.append(ra, cc.callee);
                    for (cc.args) |a| try self.collectIdents(a.value.*, out);
                    for (cc.trailing) |t| for (t.body) |st| try self.collectIdents(st.expr, out);
                },
                .pipeline => |pl| {
                    try self.collectIdents(pl.lhs.*, out);
                    try self.collectIdents(pl.rhs.*, out);
                },
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    try self.collectIdents(i.cond.*, out);
                    for (i.then_) |st| try self.collectIdents(st.expr, out);
                    if (i.else_) |els| for (els) |st| try self.collectIdents(st.expr, out);
                },
                .tryCatch => |tc| {
                    try self.collectIdents(tc.expr.*, out);
                    try self.collectIdents(tc.handler.*, out);
                },
            },
            .binding => |b| switch (b.kind) {
                .localBind => |lb| try self.collectIdents(lb.value.*, out),
                .localBindDestruct => |lb| try self.collectIdents(lb.value.*, out),
                .assign => |a| {
                    try self.collectIdents(a.value.*, out);
                    switch (a.target) {
                        .name => |n| try out.append(ra, n),
                        .fieldAccess => |fa| try self.collectIdents(fa.receiver.*, out),
                    }
                },
            },
            .jump => |j| switch (j.kind) {
                .@"return", .throw_, .try_ => |v| if (v) |x| try self.collectIdents(x.*, out),
                inline .@"break", .yield => |jl| if (jl.value) |x| try self.collectIdents(x.*, out),
                .await_ => |a| try self.collectIdents(a.*, out),
                else => {},
            },
            .loop => |lp| {
                try self.collectIdents(lp.iter.*, out);
                for (lp.body) |st| try self.collectIdents(st.expr, out);
            },
            .function => |f| for (f.kind.body) |st| try self.collectIdents(st.expr, out),
            .collection => |col| switch (col.kind) {
                .grouped => |inner| try self.collectIdents(inner.*, out),
                .case => |cs| {
                    for (cs.subjects) |sj| try self.collectIdents(sj, out);
                    for (cs.arms) |arm| try self.collectIdents(arm.body, out);
                },
                .tupleLit => |tl| for (tl.elems) |el| try self.collectIdents(el, out),
                .arrayLit => |al| for (al.elems) |el| try self.collectIdents(el, out),
                .behaviorLit => |il| for (il.fields) |f| try self.collectIdents(f.value.*, out),
                .range => |r| {
                    try self.collectIdents(r.start.*, out);
                    if (r.end) |x| try self.collectIdents(x.*, out);
                },
            },
            .useHook => |uh| try self.collectIdents(uh.kind.inner.*, out),
            else => {},
        }
    }

    /// Element shape of what a comprehension body yields: the first
    /// `yield`/`break` value found. Loop parameters are not bound yet, so a
    /// float is recognised by its literal or arithmetic, a string by a literal.
    fn yieldElemKind(self: *Emitter, body: []const ast.Stmt) ElemKind {
        // `val taxa = valor * 0.15; break valor + taxa;` — the body's own float
        // locals make the yielded value a float.
        var floats: std.ArrayListUnmanaged([]const u8) = .empty;
        for (body) |st| {
            switch (st.expr) {
                .binding => |b| switch (b.kind) {
                    .localBind => |lb| if (self.wasmTypeOf(lb.value.*).isFloat() or self.mentionsAny(lb.value.*, floats.items))
                        floats.append(self.reg_arena.allocator(), lb.name) catch {},
                    else => {},
                },
                else => {},
            }
            if (self.yieldValue(st.expr)) |v| {
                if (self.isStringExpr(v)) return .str;
                if (self.wasmTypeOf(v).isFloat() or self.mentionsAny(v, floats.items)) return .f64;
                return .i32;
            }
        }
        return .i32;
    }

    fn mentionsAny(self: *Emitter, e: ast.Expr, names: []const []const u8) bool {
        if (names.len == 0) return false;
        var seen: std.ArrayListUnmanaged([]const u8) = .empty;
        self.collectIdents(e, &seen) catch return false;
        for (seen.items) |n| for (names) |m| if (std.mem.eql(u8, n, m)) return true;
        return false;
    }

    fn yieldValue(self: *Emitter, e: ast.Expr) ?ast.Expr {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                inline .@"break", .yield => |jl| if (jl.value) |v| v.* else null,
                else => null,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| blk: {
                    for (i.then_) |st| if (self.yieldValue(st.expr)) |v| break :blk v;
                    if (i.else_) |els| for (els) |st| if (self.yieldValue(st.expr)) |v| break :blk v;
                    break :blk null;
                },
                else => null,
            },
            else => null,
        };
    }

    // ── optionals ────────────────────────────────────────────────────────────
    //
    // `?T` is an i32 offset into linear memory, `0` = null (decision 3 of the
    // 1.0.2-beta semantics decisions). A `T` that is already a pointer (a
    // string, a record, an array) is its own offset. A scalar `T` (an integer,
    // a bool, a float) is boxed: a 4-byte cell holding the payload
    // (`$__box_i32`), so a present `0` is distinguishable from none. The box is
    // made where a `T` flows into a declared `?T` (a return, an annotated
    // binding, an argument, a record field) and read where the program uses
    // the payload (`if (x) { v -> … }`, `@print`, a comparison with a value, a
    // string `+`, `unwrapOr`/`map`).

    /// What an 8-byte cell holds: a float or an `i64`, each wider than the
    /// 4-byte word every slot of this backend is.
    const Cell = enum {
        none,
        f64,
        i64,

        /// The wasm type of what the cell holds — `i32` for a word.
        fn ty(c: Cell) Repr {
            return switch (c) {
                .none => .i32,
                .f64 => .f64,
                .i64 => .i64,
            };
        }

        /// The cell a value of wasm type `t` needs, if any.
        fn of(t: Repr) Cell {
            if (t.isFloat()) return .f64;
            if (t.isI64()) return .i64;
            return .none;
        }
    };

    const OptInfo = struct {
        /// The payload is a scalar in a box (else the value is the payload).
        boxed: bool,
        str: bool = false,
        bool_: bool = false,
        /// The payload is an `f64` or an `i64`, and the box is its 8-byte cell
        /// (`$__box_f64` / `$__box_i64`) — a `?f64`, a `?i64`, a float array's
        /// `at`/`first` (whose slot already holds the cell), a `?.` over such
        /// a field. Read as an `i32` it printed the float's bits.
        cell: Cell = .none,
        /// The payload is a value of this record type — `es.at(0)` over an
        /// `Entry[]`. It names the field offsets a `?.` read needs and the
        /// header `$__print_opt_tagged` writes, and it is the reason a record
        /// element is NOT boxed: a record is its own pointer, so `0` is
        /// absence exactly as it is for a string.
        rec: ?[]const u8 = null,
        inner: ?ast.TypeRef = null,
        /// The payload is a CONTAINER — an array or a tuple — with this print
        /// shape (`[i`, `(is)`): `rows.at(1)` over `[[1, 2], [3]]`. Its own
        /// pointer, `0` absence; printed `null` or by the shape. Through the
        /// integer printer it answered the row's address at exit 0.
        shape: ?[]const u8 = null,
    };

    /// The carrier an element shape that is itself optional (`?X`, `!X`)
    /// takes; null for any other shape.
    fn optInfoOfOptShape(el: []const u8) ?OptInfo {
        if (el.len < 2) return null;
        return switch (el[0]) {
            '!' => .{ .boxed = true, .bool_ = el[1] == 'b' },
            '?' => switch (el[1]) {
                'f' => .{ .boxed = true, .cell = .f64 },
                'l' => .{ .boxed = true, .cell = .i64 },
                'u' => .{ .boxed = true, .cell = .i64, .inner = .{ .named = "u64" } },
                's' => .{ .boxed = false, .str = true },
                else => .{ .boxed = false, .shape = el[1..] },
            },
            else => null,
        };
    }

    /// The `?T` a `recv?._N` read answers, from element `N`'s shape: an
    /// optional element stays what it is (`?.` does not nest), a scalar goes
    /// in a box, a float or `i64` slot already holds its cell, a string or a
    /// container is its own pointer.
    fn optInfoOfElemShape(el: []const u8) ?OptInfo {
        if (optInfoOfOptShape(el)) |oi| return oi;
        if (el.len == 0) return null;
        return switch (el[0]) {
            'i' => .{ .boxed = true },
            'b' => .{ .boxed = true, .bool_ = true },
            'f' => .{ .boxed = true, .cell = .f64 },
            'l' => .{ .boxed = true, .cell = .i64 },
            'u' => .{ .boxed = true, .cell = .i64, .inner = .{ .named = "u64" } },
            's' => .{ .boxed = false, .str = true },
            else => .{ .boxed = false, .shape = el },
        };
    }

    /// Whether a `?T`'s cell holds a `u64` — its bits print unsigned.
    fn optIsU64(oi: OptInfo) bool {
        const inner = oi.inner orelse return false;
        return inner == .named and std.mem.eql(u8, inner.named, "u64");
    }

    fn optInfoOfTypeRef(self: *Emitter, t: ast.TypeRef) ?OptInfo {
        const inner = switch (t) {
            .optional => |i| i.*,
            else => return null,
        };
        // A `?V` over a type parameter is ALWAYS a box: nothing here
        // monomorphises, so the payload may be a scalar, and a present `0` has
        // to differ from absence. Its writer (inside the generic body, where
        // `V` is in scope) and its reader (at the call, where the method's
        // registered return reads `?__tparam`) agree on the box; unboxed,
        // `Dict.at`'s absent key printed `0` and a present `0` was absent
        // (C-18).
        return switch (inner) {
            .named => |n| if (std.mem.eql(u8, n, "string"))
                .{ .boxed = false, .str = true, .inner = inner }
            else if (std.mem.eql(u8, n, "bool"))
                .{ .boxed = true, .bool_ = true, .inner = inner }
            else if (fieldCellOf(n) != .none)
                .{ .boxed = true, .cell = fieldCellOf(n), .inner = inner }
            else if (isScalarName(n))
                .{ .boxed = true, .inner = inner }
                // An all-unit enum's value is its ordinal — `0` for the first
                // variant — so `?Color` is a box as `?i32` is. Unboxed, a present
                // `Color.Red` was absent, and printed as its ordinal.
            else if (self.isAllUnitEnum(n))
                .{ .boxed = true, .inner = inner }
            else if (std.mem.eql(u8, n, tparam_marker) or self.isTypeParamName(n))
                .{ .boxed = true, .inner = inner }
            else
                .{ .boxed = false, .inner = inner },
            else => .{ .boxed = false, .inner = inner },
        };
    }

    fn isTypeParamName(self: *Emitter, n: []const u8) bool {
        for (self.owner_tparams) |gp| if (std.mem.eql(u8, gp.name, n)) return true;
        for (self.fn_tparams) |gp| if (std.mem.eql(u8, gp.name, n)) return true;
        return false;
    }

    /// A declared return type as a CALLER reads it: `?V` over one of `owner` /
    /// `own`'s type parameters becomes `?__tparam`, which `optInfoOfTypeRef`
    /// knows is boxed wherever it is asked — at a call site the parameter
    /// names nothing. A tuple's elements the same way (`dequeue`'s
    /// `#(Queue<T>, ?T)`): its `?T` slot holds the box the generic body wrote,
    /// and read as `?T` at the call — a name nothing in scope binds — the
    /// box's ADDRESS was the payload (`d._1.unwrapOr(-1)` printed `296`).
    fn eraseOptTypeParam(self: *Emitter, owner: []const ast.GenericParam, own: []const ast.GenericParam, rt: ast.TypeRef) !ast.TypeRef {
        const elems: ?[]ast.TypeRef = switch (rt) {
            .tuple_ => |es| es,
            .labeledTuple => |lt| lt.elems,
            else => null,
        };
        if (elems) |es| {
            const ra = self.reg_arena.allocator();
            const out = try ra.alloc(ast.TypeRef, es.len);
            for (es, out) |e, *o| o.* = try self.eraseOptTypeParam(owner, own, e);
            return switch (rt) {
                .tuple_ => .{ .tuple_ = out },
                .labeledTuple => |lt| .{ .labeledTuple = .{ .elems = out, .labels = lt.labels } },
                else => unreachable,
            };
        }
        const inner = switch (rt) {
            .optional => |i| i.*,
            else => return rt,
        };
        const n = switch (inner) {
            .named => |x| x,
            else => return rt,
        };
        const is_param = for (owner) |gp| {
            if (std.mem.eql(u8, gp.name, n)) break true;
        } else for (own) |gp| {
            if (std.mem.eql(u8, gp.name, n)) break true;
        } else false;
        if (!is_param) return rt;
        const ra = self.reg_arena.allocator();
        const boxed = try ra.create(ast.TypeRef);
        boxed.* = .{ .named = tparam_marker };
        return .{ .optional = boxed };
    }

    /// Decision 330 — an optional operator's `if` (`infer.inferOptionalOperator`,
    /// binder `__bp_opt_<line>_<col>`): its operand, the then-arm's value, and
    /// whether it is `x!` (the arm answers the binder itself).
    const OptOperator = struct { cond: *ast.Expr, tail: ast.Expr, bang: bool };

    /// The plain type a decision-330 link answers when its value is no
    /// optional of its own — `f?.(41)` over a `?fn(i32) -> i32` answers an
    /// `i32` — read off the link, or off the function type the operand holds.
    fn optLinkPlainType(self: *Emitter, cond: ast.Expr, tail: ast.Expr) ?ast.TypeRef {
        if (self.typeRefOf(tail)) |t| return t;
        if (tail == .call and tail.call.kind == .call and tail.call.kind.call.calleeExpr != null) {
            if (self.typeRefOf(cond)) |ct| if (ct == .optional and ct.optional.* == .function)
                return ct.optional.function.returnType.*;
        }
        return null;
    }

    /// The optional a link answering a plain value makes of it: boxed as a
    /// `?T` of the link's type is (`optInfoOfTypeRef`), so absence stays the
    /// `0` the other arm answers and a present `0` differs from it.
    fn optLinkBoxInfo(self: *Emitter, cond: ast.Expr, tail: ast.Expr) ?OptInfo {
        const t = self.optLinkPlainType(cond, tail) orelse return null;
        if (t == .optional) return null;
        const inner = self.arena().create(ast.TypeRef) catch return null;
        inner.* = t;
        return self.optInfoOfTypeRef(.{ .optional = inner });
    }

    fn optOperatorParts(e: ast.Expr) ?OptOperator {
        if (e != .branch or e.branch.kind != .if_) return null;
        const i = e.branch.kind.if_;
        const b = i.binding orelse return null;
        if (!std.mem.startsWith(u8, b, "__bp_opt_")) return null;
        if (i.then_.len != 1) return null;
        const tail = i.then_[0].expr;
        const bang = tail == .identifier and tail.identifier.kind == .ident and std.mem.eql(u8, tail.identifier.kind.ident, b);
        return .{ .cond = i.cond, .tail = tail, .bang = bang };
    }

    /// `o ?? d` — the parser's `if (o) { n -> n } else { d }` with the
    /// nullish binder (`ast.nullish_binding_name`): the optional and its
    /// default.
    fn nullishParts(e: ast.Expr) ?struct { opt: *ast.Expr, dflt: ast.Expr } {
        if (e != .branch or e.branch.kind != .if_) return null;
        const i = e.branch.kind.if_;
        const b = i.binding orelse return null;
        if (!std.mem.eql(u8, b, ast.nullish_binding_name)) return null;
        const els = i.else_ orelse return null;
        if (els.len != 1) return null;
        return .{ .opt = i.cond, .dflt = els[0].expr };
    }

    /// `o.unwrapOr(d)` over an `@Option` or a `@Result`, its default written
    /// — the builtin `__bp_*_unwrapOr(o, d)`, whose second argument is `d`.
    fn isUnwrapOr(cc: anytype) bool {
        if (!cc.is_builtin or cc.args.len != 2) return false;
        return std.mem.eql(u8, cc.callee, "__bp_option_unwrapOr") or std.mem.eql(u8, cc.callee, "__bp_result_unwrapOr");
    }

    /// `fn f<T>(…, x: T, …) -> T`: the index of the first parameter declared
    /// `T`, when the return type is that bare type parameter.
    fn genericResultIndex(gps: []const ast.GenericParam, ptrefs: []const ast.TypeRef, rt: ast.TypeRef) ?usize {
        const n = switch (rt) {
            .named => |x| x,
            else => return null,
        };
        for (gps) |gp| {
            if (!std.mem.eql(u8, gp.name, n)) continue;
            for (ptrefs, 0..) |pt, i| switch (pt) {
                .named => |pn| if (std.mem.eql(u8, pn, n)) return i,
                else => {},
            };
            return null;
        }
        return null;
    }

    /// The argument whose shape a generic call answers (`generic_result_arg`):
    /// `ident("a")` is a string, `ident(true)` a bool.
    fn genericResultArg(self: *Emitter, cc: anytype) ?ast.Expr {
        if (cc.is_builtin or cc.calleeExpr != null) return null;
        // A call through a namespace item (`async.delay(5, "x")` after
        // `import {async} from "std"`) reaches here with the namespace as
        // its receiver: it answers what the plain call does. Read as a value
        // receiver it answered nothing, and `"x " + d` added the string's
        // address as a number.
        if (cc.receiver != null and !self.isNamespaceReceiver(cc)) return null;
        if (self.taskAdapterProxy(cc)) |p| return p;
        const ix = self.generic_result_arg.get(cc.callee) orelse return null;
        for (cc.args) |a| if (a.label != null) return null;
        return if (ix < cc.args.len) cc.args[ix].value.* else null;
    }

    /// The receiver of `cc` is a namespace item, not a value: a plain name
    /// no local, global, type or extension block binds, and the callee is a
    /// function of the program (`fn_sigs`).
    fn isNamespaceReceiver(self: *Emitter, cc: anytype) bool {
        const rn = receiverName(cc) orelse return false;
        if (self.locals.contains(rn) or self.globals.contains(rn) or self.records.contains(rn) or self.enums.contains(rn) or self.ext_by_name.contains(rn)) return false;
        return self.fn_sigs.contains(cc.callee);
    }

    /// The name of a primitive type's family, when it is one.
    fn primKindOfName(n: []const u8) ?envMod.PrimKind {
        const eq = std.mem.eql;
        if (eq(u8, n, "string")) return .string;
        if (eq(u8, n, "bool")) return .bool;
        if (eq(u8, n, "f64") or eq(u8, n, "f32")) return .float;
        if (eq(u8, n, "i32") or eq(u8, n, "i64") or eq(u8, n, "u32") or eq(u8, n, "u64")) return .int;
        return null;
    }

    /// `Pair(left: s, right: "ab")` of a generic record: `Pair<string>`, the
    /// type arguments its fields' arguments bind — what a method call on it
    /// specialises by (`specializeMethod`). Null when the record has no type
    /// parameter or some argument does not say what its parameter is.
    fn ctorTypeRef(self: *Emitter, cc: anytype) !?ast.TypeRef {
        if (cc.receiver != null or cc.is_builtin) return null;
        const gps = self.record_generics.get(cc.callee) orelse return null;
        const names = self.records.get(cc.callee) orelse return null;
        const trefs = self.record_field_typerefs.get(cc.callee) orelse return null;
        const ar = self.reg_arena.allocator();
        const args = try ar.alloc(ast.TypeRef, gps.len);
        for (gps, args) |gp, *out| {
            out.* = for (trefs, 0..) |t, i| {
                if (i >= names.len) continue;
                // A field written `Array<T>` / `T[]` binds `T` by its
                // elements (`Bag(items: [1, 2])` is a `Bag<i32>`).
                if (t == .array or t == .generic) {
                    const arg = self.argForField(cc.args, names[i], i) orelse continue;
                    if (self.bindParam(t, arg.value.*, &isGenericParamName, gps, &.{})) |bnd|
                        if (std.mem.eql(u8, bnd.name, gp.name)) break ast.TypeRef{ .named = bnd.ty };
                    continue;
                }
                if (t != .named or !std.mem.eql(u8, t.named, gp.name)) continue;
                const arg = self.argForField(cc.args, names[i], i) orelse continue;
                // A generic record built in place keeps its own arguments
                // (`Box(value: Box(value: hi))` is a `Box<Box<fn() -> string>>`).
                if (self.typeRefOf(arg.value.*)) |at| if (at == .generic and !at.generic.is_builtin) break at;
                if (self.concreteTypeOf(arg.value.*)) |c| break ast.TypeRef{ .named = c };
                // A top-level fn stored in the field (`Box(value: shout)`):
                // its function type, so a call through the field's value
                // answers its declared return.
                if (try self.fnRefTypeRef(arg.value.*)) |ft| break ft;
                // Any other argument whose type is written somewhere — a
                // generic record built in place (`Box(value: Box(value: hi))`),
                // a local holding a function: reading the field back answers
                // that type, and a call through it its return.
                if (self.typeRefOf(arg.value.*)) |at| break at;
                // An array literal in a type parameter's slot: its array type
                // (`Box(value: [1, 2])` is a `Box<i32[]>`), so a read of the
                // slot casts to the array it holds (front 164 s2 P3).
                if (self.mode == .gc and isArrayLit(arg.value.*)) if (try self.eqTypeOf(arg.value.*)) |et| if (et == .array) break et;
            } else return null;
        }
        return .{ .generic = .{ .name = cc.callee, .args = args, .is_builtin = false } };
    }

    /// `wrap(shout)` over `fn wrap<T>(v: T) -> Box<T>`: the declared return
    /// with each type parameter a FUNCTION argument binds written in — a
    /// function type has no specialisation (`bindParam` binds names), so the
    /// call keeps the one body and only its result's type is read.
    fn genericRetByFnArg(self: *Emitter, cc: anytype) !?ast.TypeRef {
        if (cc.is_builtin or cc.calleeExpr != null) return null;
        if (cc.receiver != null and !self.isNamespaceReceiver(cc)) return null;
        const callee = self.import_aliases.get(cc.callee) orelse cc.callee;
        const f = if (self.generic_fns.get(callee)) |g| g.decl else self.host_generic_decls.get(callee) orelse return null;
        const rt = f.returnType orelse return null;
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        var pi: usize = 0;
        for (f.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            defer pi += 1;
            if (pi >= cc.args.len) break;
            // A thunk parameter, `fn() -> T` or `fn() -> @Task<T>` (std's
            // `failure.attempt` / `attemptTask`, decision 518): `T` is what
            // the argument answers — a `@Result` or any other type included.
            if (p.typeRef == .function and p.typeRef.function.params.len == 0) {
                const want = p.typeRef.function.returnType.*;
                const got = self.fnArgReturn(cc.args[pi].value.*) orelse continue;
                const w = if (isTaskTypeRef(want)) (taskValueTypeRef(want) orelse continue) else want;
                const a = if (isTaskTypeRef(want)) (taskValueTypeRef(got) orelse continue) else got;
                if (w == .named and isGenericParamName(w.named, f.genericParams, &.{}))
                    try subs.append(ar, .{ .name = w.named, .to = a });
                continue;
            }
            if (p.typeRef != .named or !isGenericParamName(p.typeRef.named, f.genericParams, &.{})) continue;
            const ft = (try self.fnRefTypeRef(cc.args[pi].value.*)) orelse continue;
            try subs.append(ar, .{ .name = p.typeRef.named, .to = ft });
        }
        if (subs.items.len == 0) return null;
        return try substTypeParams(ast.TypeRef, ar, rt, subs.items);
    }

    /// `await f(args)` of a generic `f` whose declared answer `v` names a
    /// type parameter inside a generic type (`@Result<T, string>`): `v` with
    /// each parameter a plain-`T` argument binds written in. Null when the
    /// call is no generic call, or nothing binds.
    fn bindAwaitedGeneric(self: *Emitter, call: ast.Expr, v: ast.TypeRef) ?ast.TypeRef {
        const cc = switch (call) {
            .call => |c| switch (c.kind) {
                .call => |x| x,
                else => return null,
            },
            else => return null,
        };
        if (cc.is_builtin or cc.calleeExpr != null or cc.receiver != null) return null;
        const callee = self.import_aliases.get(cc.callee) orelse cc.callee;
        const f = if (self.generic_fns.get(callee)) |g| g.decl else return null;
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        var pi: usize = 0;
        for (f.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            defer pi += 1;
            if (pi >= cc.args.len) break;
            if (p.typeRef != .named or !isGenericParamName(p.typeRef.named, f.genericParams, &.{})) continue;
            const arg = cc.args[pi].value.*;
            const to: ast.TypeRef = if (self.concreteTypeOf(arg)) |c| .{ .named = c } else (self.typeRefOf(arg) orelse continue);
            subs.append(ar, .{ .name = p.typeRef.named, .to = to }) catch return null;
        }
        if (subs.items.len == 0) return null;
        return substTypeParams(ast.TypeRef, ar, v, subs.items) catch null;
    }

    /// What a function argument answers: a lambda's last expression's type
    /// (an `async { }` block's value), a value of a written function type
    /// its declared return.
    fn fnArgReturn(self: *Emitter, arg: ast.Expr) ?ast.TypeRef {
        if (thunkTail(arg)) |tail| return self.typeRefOf(tail);
        const t = self.typeRefOf(arg) orelse return null;
        return if (t == .function) t.function.returnType.* else null;
    }

    /// Each type parameter of `gps` the written type `pt` names, bound to the
    /// concrete type at its place in `at` (a primitive or a record name) —
    /// one walk over both, nothing bound twice.
    fn bindByShape(ar: std.mem.Allocator, pt: ast.TypeRef, at: ast.TypeRef, gps: []const ast.GenericParam, subs: *std.ArrayListUnmanaged(TypeSub)) !void {
        switch (pt) {
            .named => |n| {
                if (!isGenericParamName(n, gps, &.{})) return;
                if (at != .named or isGenericParamName(at.named, gps, &.{})) return;
                for (subs.items) |sub| if (std.mem.eql(u8, sub.name, n)) return;
                try subs.append(ar, .{ .name = n, .to = at });
            },
            .generic => |g| {
                if (at != .generic or !std.mem.eql(u8, at.generic.name, g.name) or at.generic.args.len != g.args.len) return;
                for (g.args, at.generic.args) |pa, aa| try bindByShape(ar, pa, aa, gps, subs);
            },
            .array => |inner| if (at == .array) try bindByShape(ar, inner.*, at.array.*, gps, subs),
            .optional => |inner| if (at == .optional) try bindByShape(ar, inner.*, at.optional.*, gps, subs),
            else => {},
        }
    }

    /// `shout` named as a value, a top-level fn of this program: `fn(…) -> R`
    /// from its declaration.
    fn fnRefTypeRef(self: *Emitter, e: ast.Expr) !?ast.TypeRef {
        const n = if (plainIdentName(e)) |n0| blk: {
            if (self.locals.contains(n0)) return null;
            break :blk self.import_aliases.get(n0) orelse n0;
        } else assocValueSym(self, e) orelse return null;
        const ps = self.fn_param_typerefs.get(n) orelse return null;
        const rt = self.fn_ret_typerefs.get(n) orelse return null;
        const ar = self.reg_arena.allocator();
        const ret = try ar.create(ast.TypeRef);
        ret.* = rt;
        return .{ .function = .{ .params = try ar.dupe(ast.TypeRef, ps), .returnType = ret } };
    }

    /// An associated fn named as a value (`City.make`): the symbol it is
    /// emitted as (`City_make`), owned by the registration arena; null for
    /// any other node.
    fn assocValueSym(self: *Emitter, e: ast.Expr) ?[]const u8 {
        if (e != .identifier or e.identifier.kind != .identAccess) return null;
        const ia = e.identifier.kind.identAccess;
        if (ia.optional or ia.receiver.* != .identifier or ia.receiver.identifier.kind != .ident) return null;
        const rn = ia.receiver.identifier.kind.ident;
        if (self.locals.contains(rn) or self.globals.contains(rn)) return null;
        const sym = std.fmt.allocPrint(self.reg_arena.allocator(), "{s}_{s}", .{ rn, ia.member }) catch return null;
        return if (self.fn_param_typerefs.contains(sym)) sym else null;
    }

    /// The type an argument binds a type parameter to, when its shape says:
    /// a primitive, a record, an all-unit enum.
    fn concreteTypeOf(self: *Emitter, e: ast.Expr) ?[]const u8 {
        if (self.isStringExpr(e)) return "string";
        if (self.isBoolExpr(e)) return "bool";
        if (self.recordTypeOfExpr(e)) |r| return r;
        if (self.unitEnumOf(e)) |en| return en;
        if (self.typeRefOf(e)) |tr| switch (tr) {
            .named => |n| if (primKindOfName(n) != null) return n,
            else => {},
        };
        switch (e) {
            .literal => |lit| switch (lit.kind) {
                .numberLit => |n| if (isNumericLiteral(n)) return numLitType(n).name(),
                else => {},
            },
            else => {},
        }
        if (self.wasmTypeOf(e).isFloat()) return "f64";
        return null;
    }

    /// The type parameter a parameter is written as — `x: T`, or the element
    /// of `xs: Array<T>` / `xs: T[]` — and the type the argument binds it to.
    const ParamBinding = struct {
        name: []const u8,
        ty: []const u8,
        /// Decision 210 — a composite the parameter is bound to that no name
        /// spells (`#(i32, string)`, `Array<i32>`), or a payload enum: set
        /// only when the body compares values with `==` (`eqBindParam`).
        tref: ?ast.TypeRef = null,
    };

    /// Decision 210 — `x: T` against an argument whose type is a composite,
    /// in a body that compares values with `==` / `!=`: one body for every
    /// type compares two words, so the copy binds `T` to the composite and
    /// its `==` calls that type's `$__eq_<T>`.
    fn eqBindParam(self: *Emitter, t: ast.TypeRef, arg: ast.Expr, f: ast.FnDecl) !?ParamBinding {
        const n = switch (t) {
            .named => |x| x,
            else => return null,
        };
        if (!isGenericParamName(n, f.genericParams, &.{})) return null;
        // A GC module binds a tuple whatever the body does (decision 568):
        // the copy holds it as the tuple it is, not as an `unknown`.
        if (!comparesValues(ast.FnDecl, f) and !(self.mode == .gc and (isTupleLit(arg) or self.typeRefIsTuple(arg)))) return null;
        const at = (try self.eqTypeOf(arg)) orelse return null;
        if (!self.eqComposite(at)) return null;
        return .{ .name = n, .ty = try self.eqKey(at), .tref = at };
    }

    fn bindParam(self: *Emitter, t: ast.TypeRef, arg: ast.Expr, isParam: *const fn ([]const u8, []const ast.GenericParam, []const ast.GenericParam) bool, a: []const ast.GenericParam, b: []const ast.GenericParam) ?ParamBinding {
        switch (t) {
            .named => |n| {
                if (!isParam(n, a, b)) return null;
                return .{ .name = n, .ty = self.concreteTypeOf(arg) orelse return null };
            },
            .array, .generic => {
                // `p: Pair<T>` against an argument whose type says `Pair<string>`
                // (`ctorTypeRef`, a local bound to one): `T` is what the
                // argument's type argument at its place is.
                if (t == .generic and !std.mem.eql(u8, t.generic.name, "Array")) {
                    const at = self.typeRefOf(arg) orelse return null;
                    if (at != .generic or !std.mem.eql(u8, at.generic.name, t.generic.name) or at.generic.args.len != t.generic.args.len) return null;
                    for (t.generic.args, at.generic.args) |pa, aa| {
                        if (pa != .named or aa != .named) continue;
                        if (!isParam(pa.named, a, b)) continue;
                        if (primKindOfName(aa.named) == null and !self.records.contains(aa.named)) continue;
                        return .{ .name = pa.named, .ty = aa.named };
                    }
                    return null;
                }
                const elem: ast.TypeRef = switch (t) {
                    .array => |inner| inner.*,
                    .generic => |g| if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array")) g.args[0] else return null,
                    else => unreachable,
                };
                // Decision 392 — `Array<@Task<T>>` (started tasks: the shape
                // readers see each as its value) and `Array<fn() -> @Task<T>>`
                // (unstarted ones: the first thunk's answer) bind `T` as the
                // values do; std's `async.all` / `runAll` over strings joined
                // their addresses as numbers.
                if (taskValueTypeRef(elem)) |tv| if (tv == .named and isParam(tv.named, a, b)) {
                    if (!self.isArrayExpr(arg)) return null;
                    if (self.elemRecordOf(arg)) |r| return .{ .name = tv.named, .ty = r };
                    return .{ .name = tv.named, .ty = switch (self.elemKindOf(arg)) {
                        .str => "string",
                        .f64 => return null,
                        .i32 => "i32",
                    } };
                };
                if (elem == .function and elem.function.params.len == 0) if (taskValueTypeRef(elem.function.returnType.*)) |tv| if (tv == .named and isParam(tv.named, a, b)) {
                    if (arg != .collection or arg.collection.kind != .arrayLit) return null;
                    const elems = arg.collection.kind.arrayLit.elems;
                    if (elems.len == 0) return null;
                    const v = taskValueExpr(thunkTail(elems[0]) orelse return null);
                    return .{ .name = tv.named, .ty = self.concreteTypeOf(v) orelse return null };
                };
                const n = switch (elem) {
                    .named => |x| x,
                    else => return null,
                };
                if (!isParam(n, a, b) or !self.isArrayExpr(arg)) return null;
                if (self.elemRecordOf(arg)) |r| return .{ .name = n, .ty = r };
                return .{ .name = n, .ty = switch (self.elemKindOf(arg)) {
                    .str => "string",
                    .f64 => return null,
                    .i32 => "i32",
                } };
            },
            else => return null,
        }
    }

    /// Whether the written type `t` names one of `gps` anywhere in it.
    fn typeMentionsParam(t: ast.TypeRef, gps: []const ast.GenericParam) bool {
        return switch (t) {
            .named => |n| isGenericParamName(n, gps, &.{}),
            .optional, .array => |inner| typeMentionsParam(inner.*, gps),
            .generic => |g| for (g.args) |a| {
                if (typeMentionsParam(a, gps)) break true;
            } else false,
            .tuple_ => |es| for (es) |e| {
                if (typeMentionsParam(e, gps)) break true;
            } else false,
            else => false,
        };
    }

    fn isGenericParamName(n: []const u8, a: []const ast.GenericParam, b: []const ast.GenericParam) bool {
        for (a) |gp| if (std.mem.eql(u8, gp.name, n)) return true;
        for (b) |gp| if (std.mem.eql(u8, gp.name, n)) return true;
        return false;
    }

    /// A generic `fn` has ONE body here, where every type parameter is an
    /// `i32` word: a string, a bool or a float bound to one printed as a
    /// word, compared as a word and narrowed, and a method on a value of one
    /// found no lowering (`x.toString()` trapped). A call whose arguments say
    /// what a type parameter is — `describe("s")`, `pair(1.5, 2.5)` — calls
    /// a copy of the function with the type parameters it binds substituted
    /// in every written type (`<name>__<T>_<type>`), lowered like any other
    /// function. Only when it matters: a string, a bool or a float bound, or
    /// a method called on a value of the parameter.
    fn specializedCallee(self: *Emitter, cc: anytype) !?[]const u8 {
        if (cc.is_builtin or cc.calleeExpr != null) return null;
        // A namespace item's call (`async.all(…)`) is the plain call.
        if (cc.receiver != null and !self.isNamespaceReceiver(cc)) return null;
        return self.specializeFor(self.import_aliases.get(cc.callee) orelse cc.callee, cc.args);
    }

    /// `specializedCallee` for the function `target` (a free `fn`, or a
    /// behavior's associated `default fn` by its symbol `Seq_firstOr`)
    /// called with `args`.
    fn specializeFor(self: *Emitter, target: []const u8, args: anytype) !?[]const u8 {
        const g = self.generic_fns.get(target) orelse return null;
        const f = g.decl;
        const cc = .{ .args = args };
        for (cc.args) |a| if (a.label != null) return null;
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        var needed = false;
        var params_of: std.ArrayListUnmanaged([]const u8) = .empty;
        var pi: usize = 0;
        for (f.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            defer pi += 1;
            if (pi >= cc.args.len) break;
            // `work: fn() -> @Task<@Result<T, E>>` against `{ -> slow(1, "x") }`
            // or a parameter of that function type: every type parameter its
            // answer binds (std's `async.retry`).
            if (p.typeRef == .function) {
                if (self.fnArgReturn(cc.args[pi].value.*)) |at| {
                    const before = subs.items.len;
                    try bindByShape(ar, p.typeRef.function.returnType.*, at, f.genericParams, &subs);
                    for (subs.items[before..]) |sub| {
                        if (sub.to == .named) {
                            const ty = sub.to.named;
                            if (std.mem.eql(u8, ty, "string") or std.mem.eql(u8, ty, "bool") or ty[0] == 'f') needed = true;
                        }
                    }
                    if (subs.items.len > before) try params_of.append(ar, p.name);
                }
                continue;
            }
            const bnd = self.bindParam(p.typeRef, cc.args[pi].value.*, &isGenericParamName, f.genericParams, &.{}) orelse
                (try self.eqBindParam(p.typeRef, cc.args[pi].value.*, f)) orelse continue;
            try params_of.append(ar, p.name);
            var bound = false;
            for (subs.items) |sub| if (std.mem.eql(u8, sub.name, bnd.name)) {
                bound = true;
            };
            if (bound) continue;
            try subs.append(ar, .{ .name = bnd.name, .to = bnd.tref orelse .{ .named = bnd.ty } });
            if (std.mem.eql(u8, bnd.ty, "string") or std.mem.eql(u8, bnd.ty, "bool") or bnd.ty[0] == 'f') needed = true;
            // Decision 210: a composite bound where the body compares with
            // `==` — the one body would compare two pointers.
            if (bnd.tref != null or (self.records.contains(bnd.ty) and comparesValues(ast.FnDecl, f))) needed = true;
        }
        if (subs.items.len == 0) return null;
        // A GC module's one body holds a type parameter as an `unknown`, its
        // arrays of one `anyref` arrays: a call that binds the parameters
        // calls a copy written in its arguments' types (front 164 s2 P2b).
        if (self.mode == .gc) needed = true;
        if (!needed and !callsMethodOn(ast.FnDecl, f, params_of.items)) return null;
        return try self.specCopy(target, g, subs.items);
    }

    /// A generic fn NAMED as an argument whose parameter is written as a
    /// function type — `apply(same, s, "ab")` against `f: fn(a: string, b:
    /// string) -> bool`: the copy the parameter types bind. The trampoline
    /// over the one generic body compared two strings as words.
    fn specializeByFnType(self: *Emitter, target: []const u8, ft: ast.TypeRef) !?[]const u8 {
        const g = self.generic_fns.get(target) orelse return null;
        const fty = switch (ft) {
            .function => |x| x,
            else => return null,
        };
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        var needed = false;
        var pi: usize = 0;
        for (g.decl.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            defer pi += 1;
            if (pi >= fty.params.len) break;
            const tn = switch (p.typeRef) {
                .named => |n| n,
                else => continue,
            };
            if (!isGenericParamName(tn, g.decl.genericParams, &.{})) continue;
            const to = switch (fty.params[pi]) {
                .named => |n| n,
                else => continue,
            };
            if (primKindOfName(to) == null and !self.records.contains(to)) continue;
            const bound = for (subs.items) |sub| {
                if (std.mem.eql(u8, sub.name, tn)) break true;
            } else false;
            if (bound) continue;
            try subs.append(ar, .{ .name = tn, .to = .{ .named = to } });
            if (std.mem.eql(u8, to, "string") or std.mem.eql(u8, to, "bool") or to[0] == 'f') needed = true;
        }
        if (subs.items.len == 0 or !needed) return null;
        return try self.specCopy(target, g, subs.items);
    }

    /// The copy of the generic fn `target` with `subs` written in, queued
    /// for emission once; its symbol `<target>__<T>_<type>…`.
    fn specCopy(self: *Emitter, target: []const u8, g: GenericFn, subs: []const TypeSub) ![]const u8 {
        const f = g.decl;
        const ar = self.reg_arena.allocator();
        var name: std.ArrayListUnmanaged(u8) = .empty;
        try name.appendSlice(ar, target);
        for (subs) |sub| try name.print(ar, "__{s}_{s}", .{ sub.name, if (sub.to == .named) sub.to.named else try self.eqKey(sub.to) });
        const sym = name.items;
        if (self.spec_names.contains(sym)) return sym;
        try self.spec_names.put(self.alloc, sym, {});
        var copy = try substTypeParams(ast.FnDecl, ar, f, subs);
        copy.name = sym;
        copy.isPub = false;
        var left: std.ArrayListUnmanaged(ast.GenericParam) = .empty;
        for (f.genericParams) |gp| {
            const done = for (subs) |sub| {
                if (std.mem.eql(u8, sub.name, gp.name)) break true;
            } else false;
            if (!done) try left.append(ar, gp);
        }
        copy.genericParams = left.items;
        try self.registerFn(copy);
        try self.spec_pending.append(self.alloc, .{ .decl = copy, .rewrites = g.rewrites, .lowerings = g.lowerings, .renames = g.renames, .origin = self.specOrigin(g.linked) });
        return sym;
    }

    /// `e` itself when it is a generic call answering its argument's shape
    /// (`genericResultArg`), that argument.
    fn genericResultOf(self: *Emitter, e: ast.Expr) ?ast.Expr {
        return switch (e) {
            .call => |c| switch (c.kind) {
                .call => |cc| self.genericResultArg(cc),
                else => null,
            },
            // A task's value is read off the task (decision 392).
            .jump => |j| switch (j.kind) {
                .await_ => |a| a.*,
                else => null,
            },
            .function => asyncBlockValue(e),
            else => null,
        };
    }

    /// An `async { }` block's first `return` value — what the shape readers
    /// see the block's task as (decision 392).
    fn asyncBlockValue(e: ast.Expr) ?ast.Expr {
        if (e != .function or e.function.kind.syntax != .asyncBlock) return null;
        const body = e.function.kind.body;
        var v = blockReturnValue(body) orelse if (body.len > 0) body[ast.lastRealIndex(body)].expr else return null;
        // A name the block binds is read in the outer scope by its value:
        // `async { val w = await work(); return w; }` answers what `work`'s
        // task does.
        var hops: u8 = 0;
        while (hops < 8) : (hops += 1) {
            const n = plainIdentName(v) orelse break;
            const bound = for (body) |st| {
                if (st.expr == .binding and st.expr.binding.kind == .localBind and std.mem.eql(u8, st.expr.binding.kind.localBind.name, n))
                    break st.expr.binding.kind.localBind.value.*;
            } else break;
            v = bound;
        }
        return v;
    }

    /// A type a written name spells that is not a type parameter.
    fn namesConcreteType(self: *Emitter, n: []const u8) bool {
        if (isScalarName(n)) return true;
        inline for (.{ "string", "bool", "void" }) |k| if (std.mem.eql(u8, n, k)) return true;
        return self.records.contains(n) or self.enums.contains(n) or self.resolveRecordName(n) != null;
    }

    /// Decision 393 — what a task adapter over a generic `T` answers once
    /// awaited, as an expression the shape readers can classify (they read a
    /// task as its value): `race`'s first task, `race_of`'s first thunk's
    /// answer, `spawn_all`'s thunks' answers as an array. (`delay`'s is its
    /// value argument, `generic_result_arg`.)
    fn taskAdapterProxy(self: *Emitter, cc: anytype) ?ast.Expr {
        const hb = self.host_bindings.get(cc.callee) orelse return null;
        if (hb.binding != .wasi or hb.binding.wasi.task == null or cc.args.len == 0) return null;
        const name = hb.binding.wasi.name;
        const arg = cc.args[0].value.*;
        if (arg != .collection or arg.collection.kind != .arrayLit) return null;
        const elems = arg.collection.kind.arrayLit.elems;
        if (elems.len == 0) return null;
        if (std.mem.eql(u8, name, "race")) return taskValueExpr(elems[0]);
        const thunks = std.mem.eql(u8, name, "race_of") or std.mem.eql(u8, name, "spawn_all");
        if (!thunks) return null;
        if (std.mem.eql(u8, name, "race_of")) return taskValueExpr(thunkTail(elems[0]) orelse return null);
        const ra = self.reg_arena.allocator();
        const out = ra.alloc(ast.Expr, elems.len) catch return null;
        for (elems, out) |el, *o| o.* = taskValueExpr(thunkTail(el) orelse return null);
        return .{ .collection = .{ .loc = arg.collection.loc, .kind = .{ .arrayLit = .{ .elems = out } } } };
    }

    /// The expression a thunk `{ -> e }` answers.
    fn thunkTail(e: ast.Expr) ?ast.Expr {
        if (e != .function or e.function.kind.syntax != .lambda or e.function.kind.body.len == 0) return null;
        return e.function.kind.body[ast.lastRealIndex(e.function.kind.body)].expr;
    }

    /// A task's value as the shape readers see it: an `async { }` block's
    /// first `return`, any other task as itself.
    fn taskValueExpr(e: ast.Expr) ast.Expr {
        return asyncBlockValue(e) orelse e;
    }

    fn isScalarName(n: []const u8) bool {
        for ([_][]const u8{ "i32", "i64", "u32", "u64", "f32", "f64", "int", "float" }) |s| {
            if (std.mem.eql(u8, n, s)) return true;
        }
        return false;
    }

    /// The declared type an expression carries, when a declaration names it.
    /// The return type of a call whose callee is a function VALUE — the
    /// callee expression of `adder(3)(4)` or a local/global declared (or bound
    /// to a call declared) `fn(…) -> R` — or null.
    fn valueCallTypeRef(self: *Emitter, cc: anytype) ?ast.TypeRef {
        // `w.write("a")` where `write` is a record's FUNCTION-TYPED FIELD: the
        // call answers the field type's return. Without it a string answered
        // through the field printed as its heap address.
        if (cc.receiver) |r| {
            // `q.1(7)` over a tuple of function values: the element's type.
            if (tupleIndex(cc.callee)) |idx| {
                const rt = self.typeRefOf(r.*) orelse return null;
                const elems = rt.tupleElems() orelse return null;
                if (idx >= elems.len) return null;
                return switch (elems[idx]) {
                    .function => |f| f.returnType.*,
                    else => null,
                };
            }
            const rty = self.recordTypeOfExpr(r.*) orelse return null;
            if (self.fn_sigs.contains(std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ rty, cc.callee }) catch return null)) return null;
            const ft0 = self.fieldTypeRefIn(rty, cc.callee) orelse return null;
            // `h.value("b")` over `Box<fn(s: string) -> string>`: the field is
            // written `T`, the receiver's type argument is the function type.
            const ft = self.recvTypeArgRef(r.*, rty, ft0);
            return switch (ft) {
                .function => |f| f.returnType.*,
                else => null,
            };
        }
        const ft: ast.TypeRef = if (cc.calleeExpr) |ce|
            self.typeRefOf(ce.*) orelse return null
        else blk: {
            const n = self.resolveName(cc.callee);
            break :blk self.local_typerefs.get(n) orelse
                (if (self.locals.contains(n)) return null else self.global_typerefs.get(n) orelse return null);
        };
        return switch (ft) {
            .function => |f| f.returnType.*,
            else => null,
        };
    }

    /// The element a generic record method hands its lambda: the receiver's
    /// first type argument when it names a concrete type, else what the
    /// receiver was built from — a generic fn over `Array<T>` (`of(rows)`) is
    /// its argument's element, and a method answering the owner's own
    /// parameter (`where`, `orderBy`) keeps its receiver's.
    fn recvElemName(self: *Emitter, recv: ast.Expr) ?[]const u8 {
        if (self.typeRefOf(recv)) |tr| if (tr == .generic and tr.generic.args.len >= 1 and tr.generic.args[0] == .named) {
            const n = tr.generic.args[0].named;
            if (primKindOfName(n) != null or self.records.contains(n)) return n;
        };
        const c = switch (recv) {
            .call => |c| c,
            else => return null,
        };
        const cc = switch (c.kind) {
            .call => |cc| cc,
            else => return null,
        };
        if (cc.receiver) |r| {
            const sym = self.recordMethodSym(cc, c.loc) orelse return null;
            const ret = self.fn_ret_typerefs.get(sym) orelse return null;
            const rec = self.recordTypeOfExpr(r.*) orelse return null;
            const gps = self.record_generics.get(rec) orelse return null;
            if (ret != .generic or ret.generic.args.len == 0 or ret.generic.args[0] != .named or gps.len == 0) return null;
            if (!std.mem.eql(u8, ret.generic.args[0].named, gps[0].name)) return null;
            return self.recvElemName(r.*);
        }
        const g = self.generic_fns.get(self.import_aliases.get(cc.callee) orelse cc.callee) orelse return null;
        if (cc.args.len == 0 or g.decl.params.len == 0) return null;
        const pt = g.decl.params[0].typeRef;
        const inner: ast.TypeRef = switch (pt) {
            .array => |i| i.*,
            .generic => |gg| if (std.mem.eql(u8, gg.name, "Array") and gg.args.len == 1) gg.args[0] else return null,
            else => return null,
        };
        if (inner != .named or !isGenericParamName(inner.named, g.decl.genericParams, &.{})) return null;
        const arg = cc.args[0].value.*;
        if (self.elemRecordOf(arg)) |r| return r;
        if (self.elemKindOf(arg) == .str) return "string";
        return null;
    }

    /// A generic method's declared return, with the type parameters the call
    /// binds written in: the owner's from the receiver's type arguments
    /// (`Query<string>.toArray()` answers `Array<string>`), the method's own
    /// from the tail of a lambda argument whose declared function type returns
    /// one (`q.select({ c -> c.name })` over `select<U>(selector: fn(T) -> U)
    /// -> Query<U>` answers `Query<string>`). Inference records neither, so a
    /// chain through such a method lost its element type — a library's
    /// `.toArray().join(…)` read its strings as integers.
    fn bindMethodRet(self: *Emitter, sym: []const u8, cc: anytype, ret: ast.TypeRef) ast.TypeRef {
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        if (self.typeRefOf(cc.receiver.?.*)) |rt| if (rt == .generic) {
            if (self.record_generics.get(rt.generic.name)) |gps| if (gps.len == rt.generic.args.len) {
                for (gps, rt.generic.args) |gp, arg| {
                    if (arg == .named and std.mem.eql(u8, arg.named, gp.name)) continue;
                    subs.append(ar, .{ .name = gp.name, .to = arg }) catch return ret;
                }
            };
        };
        const generic = if (std.mem.indexOf(u8, sym, "__")) |i| sym[0..i] else sym;
        const elem_name = self.recvElemName(cc.receiver.?.*);
        if (self.generic_methods.get(generic)) |gm| {
            var pi: usize = 0;
            for (gm.method.params) |p| {
                if (std.mem.eql(u8, p.name, "self")) continue;
                defer pi += 1;
                const pt = p.typeRef;
                if (pt != .function or pt.function.returnType.* != .named) continue;
                const un = pt.function.returnType.named;
                if (primKindOfName(un) != null or self.records.contains(un) or self.enums.contains(un)) continue;
                const lam = lambdaAt(cc, pi) orelse continue;
                if (lam.body.len == 0) continue;
                const last = lam.body[ast.lastRealIndex(lam.body)].expr;
                const v = switch (last) {
                    .jump => |j| switch (j.kind) {
                        .@"return" => |r| if (r) |x| x.* else continue,
                        else => continue,
                    },
                    else => last,
                };
                // The lambda's parameter is the receiver's element while its
                // tail is asked about.
                var held: HeldElemParam = if (lam.params.len > 0) .{
                    .name = lam.params[0],
                    .prev_type = self.local_types.get(lam.params[0]),
                    .prev_str = self.str_locals.contains(lam.params[0]),
                    .prev_local = self.locals.get(lam.params[0]),
                    .prev_alias = self.aliases.get(lam.params[0]),
                } else .{};
                defer self.releaseElemParam(held);
                if (held.name) |hp| if (elem_name) |en| {
                    _ = self.aliases.remove(hp);
                    if (self.records.contains(en)) self.local_types.put(hp, en) catch {};
                    if (std.mem.eql(u8, en, "string")) self.str_locals.put(hp, {}) catch {};
                    self.locals.put(hp, if (en.len > 0 and en[0] == 'f') .f64 else .i32) catch {};
                    if (primKindOfName(en) != null) {
                        held.prev_tref = self.local_typerefs.get(hp);
                        held.set_tref = true;
                        self.local_typerefs.put(hp, .{ .named = en }) catch {};
                    }
                };
                const to: []const u8 = if (self.isStringExpr(v)) "string" else if (self.isBoolExpr(v)) "bool" else if (self.wasmTypeOf(v).isFloat()) "f64" else if (self.recordTypeOfExpr(v)) |r| r else continue;
                subs.append(ar, .{ .name = un, .to = .{ .named = to } }) catch return ret;
            }
        }
        if (subs.items.len == 0) return ret;
        return substTypeParams(ast.TypeRef, ar, ret, subs.items) catch ret;
    }

    /// `?T` over a type already in hand.
    fn optionalOf(self: *Emitter, t: ast.TypeRef) ?ast.TypeRef {
        const inner = self.reg_arena.allocator().create(ast.TypeRef) catch return null;
        inner.* = t;
        return .{ .optional = inner };
    }

    fn typeRefOf(self: *Emitter, e: ast.Expr) ?ast.TypeRef {
        // `o ?? d` over a `?T` answers a `T`, as `o.unwrapOr(d)` did below:
        // a `?u64`'s payload stays a `u64`, which prints, compares and turns
        // into text unsigned (`-1` at exit 0 once 330 spelled it `??`).
        if (nullishParts(e)) |nu| {
            if (self.typeRefOf(nu.opt.*)) |ot| if (ot == .optional) return ot.optional.*;
            if (self.optInfoOf(nu.opt.*)) |oi| if (oi.inner) |inner| return inner;
        }
        // `o!` over a `?T` answers the `T`.
        if (optOperatorParts(e)) |op| if (op.bang) if (self.typeRefOf(op.cond.*)) |ot| if (ot == .optional) return ot.optional.*;
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n0| blk: {
                    const n = self.resolveName(n0);
                    if (self.local_typerefs.get(n)) |t| break :blk t;
                    if (self.locals.contains(n)) break :blk null;
                    break :blk self.global_typerefs.get(n);
                },
                .identAccess => |ia| blk: {
                    // `Color.Red` of an all-unit enum: a value of `Color`,
                    // which is what prints it by name once it is in a local.
                    if (self.unitEnumMember(ia)) |en| break :blk .{ .named = en };
                    if (tupleIndex(ia.member)) |idx| {
                        const rt = self.typeRefOf(ia.receiver.*) orelse break :blk null;
                        const elems = rt.tupleElems() orelse break :blk null;
                        break :blk if (idx < elems.len) elems[idx] else null;
                    }
                    const rty = self.recordTypeOfExpr(ia.receiver.*) orelse break :blk null;
                    const fields = self.records.get(rty) orelse break :blk null;
                    const trefs = self.record_field_typerefs.get(rty) orelse break :blk null;
                    for (fields, 0..) |f, i| if (std.mem.eql(u8, f, ia.member) and i < trefs.len) {
                        const ft = self.fieldSub(rty, trefs[i]);
                        break :blk self.recvTypeArgRef(ia.receiver.*, rty, ft);
                    };
                    break :blk null;
                },
                else => null,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    // Decision 150 — an element read off an array of a union
                    // is the union's box (`0` when `at` finds none, which
                    // prints `null`): `xs[1]`, `xs.at(1)`, `xs.first()`.
                    if (self.indexArgs(cc)) |ix| if (!ix.is_slice) if (self.elemTypeRefOf(ix.recv)) |et| if (isUnknownTypeRef(et)) break :blk et;
                    if (cc.receiver) |r| if (cc.args.len <= 1) if (self.elemTypeRefOf(r.*)) |et| if (isUnknownTypeRef(et)) {
                        for ([_][]const u8{ "at", "first", "last", "pop" }) |m| if (std.mem.eql(u8, cc.callee, m)) break :blk et;
                    };
                    // The same read off an array of tasks answers a `?@Task<T>`:
                    // `xs[1] ?? t` and `xs.at(1) ?? t` stay tasks, so `await`
                    // settles them instead of printing the handle.
                    if (self.indexArgs(cc)) |ix| if (!ix.is_slice) if (self.elemTypeRefOf(ix.recv)) |et| if (isTaskTypeRef(et)) break :blk self.optionalOf(et);
                    if (cc.receiver) |r| if (cc.args.len <= 1) if (self.elemTypeRefOf(r.*)) |et| if (isTaskTypeRef(et)) {
                        for ([_][]const u8{ "at", "first", "last", "pop" }) |m| if (std.mem.eql(u8, cc.callee, m)) break :blk self.optionalOf(et);
                    };
                    // `o.unwrapOr(d)` over a `?T` answers a `T`: a `?u64`'s
                    // payload stays a `u64`, which prints, compares and turns
                    // into text unsigned (`-1` at exit 0 before).
                    if (isUnwrapOr(cc)) {
                        if (self.typeRefOf(cc.args[0].value.*)) |ot| if (ot == .optional) break :blk ot.optional.*;
                        // A `?T` element of a tuple no type is written for
                        // names its payload by its print shape (`?u`).
                        if (self.optInfoOf(cc.args[0].value.*)) |oi| if (oi.inner) |inner| break :blk inner;
                        // Decision 332 — `r.unwrapOr(0n)` over a `@Result`
                        // answers the `bigint` its fallback is.
                        if (std.mem.eql(u8, cc.callee, "__bp_result_unwrapOr") and self.isBigintExpr(cc.args[1].value.*)) break :blk .{ .named = "bigint" };
                    }
                    if (cc.is_builtin) break :blk null;
                    // Decision 332 — `bigint.of(n)` answers a `bigint`, and so
                    // does `xs.fold(0n, f)`: a fold answers its accumulator.
                    if (self.bigintAssoc(cc)) |which| if (which == .of) break :blk .{ .named = "bigint" };
                    // Decision 346 — `Bytes.fromUtf8(s)`, `slice` and `concat`
                    // answer a `Bytes`; `toUtf8` its `@Result<string, string>`.
                    if (self.isBytesFromUtf8(cc)) break :blk .{ .named = "Bytes" };
                    // Decision 319 — `x.toU64()` is a `u64`, so it prints and
                    // compares unsigned, and a conversion after it reads it so.
                    if (cc.receiver != null and cc.args.len == 0) if (intConversionType(cc.callee)) |tn| if (self.primKindAt(cc, c.loc)) |k| if (k == .int) break :blk .{ .named = tn };
                    if (cc.receiver != null) if (self.primKindAt(cc, c.loc)) |k| if (k == .bytes) {
                        if (std.mem.eql(u8, cc.callee, "slice") or std.mem.eql(u8, cc.callee, "concat")) break :blk .{ .named = "Bytes" };
                        if (std.mem.eql(u8, cc.callee, "length")) break :blk .{ .named = "i32" };
                        if (std.mem.eql(u8, cc.callee, "toUtf8")) {
                            const args = self.reg_arena.allocator().alloc(ast.TypeRef, 2) catch break :blk null;
                            args[0] = .{ .named = "string" };
                            args[1] = .{ .named = "string" };
                            break :blk .{ .generic = .{ .name = "Result", .args = args, .is_builtin = true } };
                        }
                    };
                    if (cc.receiver != null and std.mem.eql(u8, cc.callee, "fold") and cc.args.len > 0) if (self.primKindAt(cc, c.loc)) |k| if (k == .array and self.isBigintExpr(cc.args[0].value.*)) break :blk .{ .named = "bigint" };
                    // Inside a specialisation a primitive method's result is
                    // typed by what it answers, so the next link of a chain
                    // (`self.max(lo).min(hi)`) and a `val` bound to one
                    // (`val tail = self.slice(1)`) find their primitive —
                    // inference recorded no lowering in a body it typed
                    // against a type variable or `Self`.
                    // A program's `Array<T>` default answers its copy's declared
                    // return (`?T` → `?string` …), which the optional and
                    // print-shape readers take.
                    if (cc.receiver != null) if (self.primKindAt(cc, c.loc)) |k| if (k == .array and primCallRes(k, cc) == null) if (self.primDefaultOf(k, cc.callee)) |pd| {
                        const sym = self.ensurePrimDefault(k, pd, cc.receiver.?.*) catch break :blk null;
                        break :blk self.fn_ret_typerefs.get(sym);
                    };
                    if (self.in_spec and cc.receiver != null) if (self.primKindAt(cc, c.loc)) |k| if (self.primRes(k, cc)) |r| {
                        const t: ?[]const u8 = switch (r) {
                            .str => "string",
                            .bool_ => "bool",
                            .f64 => "f64",
                            .i64 => "i64",
                            .i32 => if (k == .float and !std.mem.eql(u8, cc.callee, "length")) null else "i32",
                            .arr, .none => null,
                        };
                        if (t) |tn| break :blk .{ .named = tn };
                    };
                    // A method on a record value: its declared return type is
                    // registered under the emitted symbol (`Dict_at`), and
                    // asking for it is what keeps the *reader* of a `?T` in step
                    // with the writer. `d.at("a")` returns a `?V` — a type
                    // parameter, so unboxed here — while the reader guessed
                    // "boxed" and loaded through the payload as an address.
                    if (cc.receiver != null) {
                        // A generic function reached through its module's
                        // namespace (`failure.attempt(…)`): its return with
                        // what the arguments bind written in.
                        if (self.isNamespaceReceiver(cc)) if (self.genericRetByFnArg(cc) catch null) |t| break :blk t;
                        if (self.byValueRetTypeRef(cc, c.loc)) |t| break :blk t;
                        if (self.recordMethodSym(cc, c.loc)) |sym| {
                            if (self.fn_ret_typerefs.get(sym)) |t| break :blk self.bindMethodRet(sym, cc, t);
                        }
                        // The same question one step lower: the symbol the call
                        // actually emits — a `rewrites` entry the comptime pass
                        // left, an interface `default fn`, or a method already
                        // flattened to `Dict_at` by the specialisation pass.
                        if (self.calleeSymbol(cc, c.loc)) |sym| if (self.fn_ret_typerefs.get(sym)) |t| break :blk t;
                        // No method answers it: a function-typed field
                        // (`op.run(5)`) or a tuple element answers its type's
                        // return, so `op.run(5).toString()` finds the `i32`.
                        break :blk self.valueCallTypeRef(cc);
                    }
                    // A function VALUE applied — `adder(3)(4)`, or `f(4)` over
                    // a local bound to one: the call answers the function
                    // type's return.
                    if (self.valueCallTypeRef(cc)) |t| break :blk t;
                    if (self.ctorTypeRef(cc) catch null) |t| break :blk t;
                    if (self.genericRetByFnArg(cc) catch null) |t| break :blk t;
                    if (self.specializedCallee(cc) catch null) |sym| break :blk self.fn_ret_typerefs.get(sym);
                    // A call answering a task is one (`isTaskExpr` reads it).
                    if (self.task_syms.contains(cc.callee)) if (self.fn_ret_typerefs.get(cc.callee)) |t| break :blk t;
                    if (self.genericResultArg(cc)) |a| break :blk self.typeRefOf(a);
                    break :blk self.fn_ret_typerefs.get(cc.callee);
                },
                else => null,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.typeRefOf(inner.*),
                // `[Pair(left: s, right: "ab")]`: an array of the generic
                // record its first constructor binds, so a HOF's element
                // parameter specialises a method call on it like the
                // constructor itself does. Only that shape — every other
                // literal keeps answering nothing here.
                .arrayLit => |al| blk: {
                    if (al.elems.len == 0) break :blk null;
                    if (self.unionArrayLitTypeRef(al) catch null) |ut| break :blk ut;
                    // `[double(1), double(2)]`: an array of tasks, so a `for`
                    // over it binds tasks and `await t` settles each one.
                    if (self.isTaskExpr(al.elems[0])) if (self.typeRefOf(al.elems[0])) |tt| if (isTaskTypeRef(tt)) {
                        const inner = self.reg_arena.allocator().create(ast.TypeRef) catch break :blk null;
                        inner.* = tt;
                        break :blk .{ .array = inner };
                    };
                    const first = switch (al.elems[0]) {
                        .call => |c| switch (c.kind) {
                            .call => |fc| fc,
                            else => break :blk null,
                        },
                        else => break :blk null,
                    };
                    const et = (self.ctorTypeRef(first) catch null) orelse break :blk null;
                    const inner = self.reg_arena.allocator().create(ast.TypeRef) catch break :blk null;
                    inner.* = et;
                    break :blk .{ .array = inner };
                },
                // `#(g, h)` of function values: the tuple of their types, so
                // `q.1(7)` answers `h`'s declared return (`valueCallTypeRef`).
                // Only when every element types and one is a function — every
                // other literal keeps answering nothing here.
                .tupleLit => |tl| blk: {
                    if (tl.elems.len == 0) break :blk null;
                    const elems = self.reg_arena.allocator().alloc(ast.TypeRef, tl.elems.len) catch break :blk null;
                    var any_fn = false;
                    for (tl.elems, 0..) |el, i| {
                        elems[i] = self.typeRefOf(el) orelse break :blk null;
                        if (elems[i] == .function) any_fn = true;
                    }
                    if (!any_fn) break :blk null;
                    break :blk .{ .tuple_ = elems };
                },
                else => null,
            },
            // Decision 319 — a `u64` value, so a `val` bound to it keeps
            // printing and comparing unsigned: an integer literal past
            // `i64`'s top (inference stripped its `ul` and refuses it on any
            // other type) and an operator inference typed `u64` / `usize`.
            // `val top = 18446744073709551615ul; @print(top)` printed `-1`.
            .literal => |lit| switch (lit.kind) {
                .numberLit => |n| if (lexerMod.isBigintText(n)) .{ .named = "bigint" } else if (isPastI64Literal(n)) .{ .named = "u64" } else null,
                else => null,
            },
            // Decision 332 — `-x` of a `bigint` is one.
            .unaryOp => |un| if (un.op == .neg and self.isBigintAt(un.loc)) .{ .named = "bigint" } else null,
            // Decision 332 — an `if` answering a `bigint` (`?bigint` when the
            // other arm is `null`).
            .branch => |br| switch (br.kind) {
                .if_ => |i| self.ifBigintTypeRef(i),
                else => null,
            },
            // An `async { }` block is a task whose `T` no type is written for.
            .function => |f| blk: {
                if (f.kind.syntax != .asyncBlock) break :blk null;
                const args = self.reg_arena.allocator().alloc(ast.TypeRef, 1) catch break :blk null;
                args[0] = .{ .named = tparam_marker };
                break :blk .{ .generic = .{ .name = "Task", .args = args, .is_builtin = true } };
            },
            // Decision 392 — `await t` answers the task's `T`; a task adapter's
            // `T` is the argument that binds it.
            .jump => |j| switch (j.kind) {
                .await_ => |a| blk: {
                    const inner = self.typeRefOf(a.*);
                    if (inner) |t| if (taskValueTypeRef(t)) |v| {
                        // `await twice(21)` over `-> @Task<@Result<T, string>>`:
                        // the answer with `T` bound by the arguments, so
                        // `@print` and a `case` binder see `@Result<i32, string>`.
                        if (v == .generic) if (self.bindAwaitedGeneric(a.*, v)) |bound| break :blk bound;
                        if (v != .named or self.namesConcreteType(v.named)) break :blk v;
                        if (self.genericResultOf(a.*)) |pr| break :blk self.typeRefOf(pr);
                        break :blk null;
                    };
                    break :blk inner;
                },
                else => null,
            },
            .binaryOp => |bin| blk: {
                const il = self.instance_lowerings.get(bin.loc) orelse break :blk null;
                if (il != .division) break :blk null;
                break :blk switch (il.division) {
                    .u64 => .{ .named = "u64" },
                    .usize => .{ .named = "usize" },
                    .bigint => .{ .named = "bigint" },
                    else => null,
                };
            },
            else => null,
        };
    }

    /// The `?T` one element of `recv` is — **the one answer the writer and the
    /// reader of `xs.at(i)` / `xs.first()` both take**, so they cannot drift
    /// apart. `lowerArrayMethod` picks `$__arr_at` or `$__arr_at_box` from it
    /// and `optInfoOf` reports it; while the two decided separately, an array
    /// of RECORDS was written boxed (the element kind a record shares with an
    /// integer) and read as a bare pointer, so `es.at(0)?.key.length()` loaded
    /// the box, then the record's first slot, and printed a heap address
    /// (`276`) at exit 0 where the other three backends answer `3`.
    /// The helper `xs.at(i)` reads one element of `recv` with, by
    /// `arrayElemOpt`: a boxed scalar through `$__arr_at_box`, a pointer — and
    /// a float, whose slot already holds its `f64` cell, the box a `?f64` is —
    /// as the slot's own word.
    fn arrAtHelper(self: *Emitter, recv: ast.Expr) wat.Helper {
        const oi = self.arrayElemOpt(recv);
        return if (oi.boxed and oi.cell == .none) .arr_at_box else .arr_at;
    }

    fn arrayElemOpt(self: *Emitter, recv: ast.Expr) OptInfo {
        // A record is its own pointer: `0` is absence, as it is for a string,
        // and a box would only hide the payload from every reader.
        if (self.elemRecordOf(recv)) |rec| return .{ .boxed = false, .rec = rec };
        if (self.elemIsPointer(recv)) {
            const sh = (self.printShapeOf(recv) catch null).?;
            return .{ .boxed = false, .shape = sh[1..] };
        }
        // A bool element is boxed like an integer, and prints as a bool.
        if ((self.printShapeOf(recv) catch null)) |sh| if (std.mem.eql(u8, sh, "[b")) return .{ .boxed = true, .bool_ = true };
        return switch (self.elemKindOf(recv)) {
            .str => .{ .boxed = false, .str = true },
            .f64 => .{ .boxed = true, .cell = .f64 },
            .i32 => .{ .boxed = true },
        };
    }

    /// Whether one element of `recv` is a CONTAINER — an array or a tuple —
    /// and so a pointer of its own. Read off the print shape, which is the one
    /// place a nested container is already tracked (`[[i` an array of integer
    /// arrays, `[(is)` an array of tuples), for a local as much as for a
    /// literal. A record is the other pointer element and `elemRecordOf`
    /// answers it, because a record's NAME is wanted too.
    fn elemIsPointer(self: *Emitter, recv: ast.Expr) bool {
        const sh = (self.printShapeOf(recv) catch null) orelse return false;
        // Decision 332 — a `bigint` element is its block's address, never `0`.
        // Decision 150 — a union's element is its box (`U`), `0` only absent.
        return sh.len >= 2 and sh[0] == '[' and (sh[1] == '[' or sh[1] == '(' or sh[1] == 'n' or sh[1] == 'R' or sh[1] == 'U');
    }

    /// Whether one element of `recv` is a bool — its print shape is `[b`. The
    /// slot is an `i32` like an integer's, so a binder over it needs the
    /// mark to print `true` and not `1`.
    fn elemIsBool(self: *Emitter, recv: ast.Expr) anyerror!bool {
        const sh = (try self.printShapeOf(recv)) orelse return false;
        return std.mem.eql(u8, sh, "[b");
    }

    /// The record type the elements of an array-valued expression name, when
    /// they name one: an array literal of constructor calls, a local or global
    /// bound to one, a declared `Entry[]`, and the array methods that keep
    /// their receiver's elements.
    fn elemRecordOf(self: *Emitter, e: ast.Expr) ?[]const u8 {
        if (self.genericResultOf(e)) |a| return self.elemRecordOf(a);
        switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n0| {
                    const n = self.resolveName(n0);
                    if (self.arr_elem_recs.get(n)) |r| return r;
                    if (!self.locals.contains(n)) if (self.arr_elem_rec_globals.get(n)) |r| return r;
                },
                else => {},
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.elemRecordOf(inner.*),
                .arrayLit => |al| if (al.elems.len > 0) {
                    if (self.recordTypeOfExpr(al.elems[0])) |r| return r;
                },
                else => {},
            },
            .call => |c| switch (c.kind) {
                .call => |cc| {
                    if (self.primKindAt(cc, c.loc)) |k| if (k == .array and keepsElements(cc.callee)) {
                        if (cc.receiver) |r| return self.elemRecordOf(r.*);
                    };
                    // `xs.map({ n -> Y(…) })` holds what its lambda answers:
                    // unregistered, `built.at(1)?.id` read the field off the
                    // element as an address (`modules/decisions-taken/optional_typescript_operators-330/cases/optional_member_default`).
                    if (std.mem.eql(u8, cc.callee, "map") and cc.receiver != null and cc.args.len == 1) {
                        if (lambdaArg(cc.args[0].value)) |lam| {
                            const body = lam.function.kind.body;
                            if (body.len > 0) if (self.recordTypeOfExpr(body[ast.lastRealIndex(body)].expr)) |r| return r;
                        }
                    }
                },
                else => {},
            },
            else => {},
        }
        const t = self.typeRefOf(e) orelse return null;
        return self.elemRecordOfTypeRef(t);
    }

    /// The array methods whose result holds the elements of their receiver.
    fn keepsElements(name: []const u8) bool {
        for ([_][]const u8{ "slice", "rest", "take", "drop", "reverse", "toList", "filter", "sort", "sorted" }) |s| {
            if (std.mem.eql(u8, name, s)) return true;
        }
        return false;
    }

    /// The record an `Entry[]` / `Array<Entry>` / `?Entry[]` spells, when the
    /// element names a record this module declared.
    fn elemRecordOfTypeRef(self: *Emitter, t: ast.TypeRef) ?[]const u8 {
        const elem: ast.TypeRef = switch (eagerTypeRef(t)) {
            .array => |inner| inner.*,
            .generic => |g| if (g.args.len == 1 and (std.mem.eql(u8, g.name, "Array") or
                std.mem.eql(u8, g.name, "Iterator")))
                g.args[0]
            else
                return null,
            .optional => |inner| return self.elemRecordOfTypeRef(inner.*),
            else => return null,
        };
        const name = switch (elem) {
            .named => |n| n,
            // `Declared<unknown>[]`: the generic record the element names.
            .generic => |g| if (g.is_builtin) return null else g.name,
            else => return null,
        };
        return self.resolveRecordName(name);
    }

    /// The optional an expression evaluates to, when it is one.
    fn optInfoOf(self: *Emitter, e: ast.Expr) ?OptInfo {
        if (self.genericResultOf(e)) |a| return self.optInfoOf(a);
        // `xs?.[k]`: the link's own optional, flattened (decision 330).
        if (optOperatorParts(e)) |op| if (!op.bang) return self.optInfoOf(op.tail) orelse self.optLinkBoxInfo(op.cond.*, op.tail);
        switch (e) {
            // An `if` with no `else` in value position: absent when the
            // condition is false (its value when false is the language
            // question decision 2 answers; the `0` here is none).
            .branch => |b| switch (b.kind) {
                .if_ => |i| if (i.else_ == null and !ifIsStatementForm(i) and !branchIsVoid(i.then_)) {
                    if (self.bodyIsString(i.then_)) return .{ .boxed = false, .str = true };
                },
                else => {},
            },

            .call => |c| switch (c.kind) {
                .call => |cc| if (self.chainedCallOpt(cc, c.loc)) |oi| {
                    return oi;
                } else if (self.optionalTypedMethodOpt(cc, c.loc)) |oi| {
                    return oi;
                } else if (cc.is_builtin and std.mem.eql(u8, cc.callee, "__bp_option_map") and cc.args.len > 1 and lambdaArg(cc.args[1].value) != null) {
                    // `opt.map({ x -> … })` is an optional again, boxed when
                    // the closure answers a scalar (`lowerResultOptionOp`).
                    // Unregistered, a `return` into `-> ?i32` boxed the box
                    // (`lookup(pairs, "b")` printed its address).
                    const body = lambdaArg(cc.args[1].value).?.function.kind.body;
                    if (self.lambdaTailIsPointer(body)) return .{ .boxed = false, .str = self.bodyIsString(body) };
                    return .{ .boxed = true };
                } else if (self.primKindAt(cc, c.loc)) |k| {
                    if (k == .array and
                        (std.mem.eql(u8, cc.callee, "at") or std.mem.eql(u8, cc.callee, "first") or std.mem.eql(u8, cc.callee, "find") or std.mem.eql(u8, cc.callee, "pop")))
                    {
                        return self.arrayElemOpt(cc.receiver.?.*);
                    }
                    // `s.at(i)` → `?string`: std-wasm's `text.at` answers the pointer of
                    // a fresh one-byte string, or 0. Without this the result
                    // printed through `$__print_str`, which reads a length at
                    // address 0 — the WASI iovec — and answers whatever is
                    // there with exit 0 instead of saying it is absent.
                    // A program's `String` method bound by `fn:` (decision
                    // 565): the optional its body declares.
                    if (k == .string) if (self.string_fn_cells.get(cc.callee)) |sym| {
                        const rt = self.fn_ret_typerefs.get(sym) orelse return null;
                        return self.optInfoOfTypeRef(rt);
                    };
                    if (k == .string and std.mem.eql(u8, cc.callee, "at")) {
                        return .{ .boxed = false, .str = true };
                    }
                },
                else => {},
            },
            .identifier => |id| switch (id.kind) {
                .ident => |n| {
                    const rn = self.resolveName(n);
                    // Narrowed: inside the branch the name IS the payload.
                    if (self.narrowed_opts.contains(rn)) return null;
                    if (self.opt_locals.get(rn)) |oi| return oi;
                },
                // `t._1` of a `?T` element: the carrier its shape names.
                // A tuple with no shape here falls to its declared type below.
                .identAccess => |ia| if (!ia.optional and tupleIndex(ia.member) != null) {
                    if (self.tupleElemShapeOf(e) catch null) |el| if (optInfoOfOptShape(el)) |oi| return oi;
                } else if (ia.optional) {
                    // `recv?._N` — decision 45 rewrote `?.label` of an optional
                    // tuple to its position: a scalar element goes in a box
                    // (a present `0` is not absence), a float's slot is its
                    // cell, a pointer is its own carrier.
                    if (tupleIndex(ia.member) != null) {
                        const el = (self.optTupleElemShapeOf(ia) catch null) orelse return null;
                        return optInfoOfElemShape(el);
                    }
                    // `recv?.field` of a scalar field is a boxed optional
                    const rty = self.recordTypeOfExpr(ia.receiver.*) orelse return null;
                    const ft = self.fieldTypeIn(rty, ia.member);
                    if (ft == null or self.resolveRecordName(ft.?) != null) return .{ .boxed = false };
                    if (std.mem.eql(u8, ft.?, "string")) return .{ .boxed = false, .str = true };
                    // A float or `i64` field's slot already holds its cell.
                    if (fieldCellOf(ft.?) != .none) return .{ .boxed = true, .cell = fieldCellOf(ft.?) };
                    return .{ .boxed = true, .bool_ = std.mem.eql(u8, ft.?, "bool") };
                },
                else => {},
            },
            else => {},
        }
        const t = self.typeRefOf(e) orelse return null;
        return self.optInfoOfTypeRef(t);
    }

    /// The bare name `e` reads, when it reads one and nothing else.
    fn plainIdentName(e: ast.Expr) ?[]const u8 {
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| n,
                else => null,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| plainIdentName(inner.*),
                else => null,
            },
            else => null,
        };
    }

    fn isEmptyArrayLit(e: ast.Expr) bool {
        return switch (e) {
            .collection => |col| switch (col.kind) {
                .arrayLit => |al| al.elems.len == 0,
                .grouped => |inner| isEmptyArrayLit(inner.*),
                else => false,
            },
            else => false,
        };
    }

    fn isNullLit(e: ast.Expr) bool {
        return switch (e) {
            .literal => |lit| lit.kind == .null_,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| isNullLit(inner.*),
                else => false,
            },
            else => false,
        };
    }

    /// Whether `value` flowing into a slot declared `target` must be boxed:
    /// the slot is a scalar optional and the value is neither `null` nor
    /// already an optional.
    fn boxesInto(self: *Emitter, target: ?ast.TypeRef, value: ast.Expr) bool {
        const t = target orelse return false;
        // An `unknown` / union slot: every value but one that already is one
        // goes in `lowerAsUnknown`'s box (`lowerBoxedInto`).
        if (isUnknownTypeRef(t)) return !isNullLit(value) and !self.isUnknownExpr(value) and (!self.isTaggedValue(value) or self.isGenericEnumCtor(value));
        if (self.ctorUnionArgs(t, value) != null) return true;
        const oi = self.optInfoOfTypeRef(t) orelse return false;
        if (!oi.boxed) return false;
        if (isNullLit(value)) return false;
        return self.optInfoOf(value) == null;
    }

    /// Whether the `@Option` an `__bp_option_*` op receives holds its payload in
    /// a box. Known from the receiver's declared type; otherwise the default
    /// value's shape decides (a string or record default means a pointer
    /// payload), and a scalar is assumed.
    fn optionIsBoxed(self: *Emitter, recv: ast.Expr, default: ?*ast.Expr) bool {
        if (self.optInfoOf(recv)) |oi| return oi.boxed;
        if (default) |d| {
            if (self.isStringExpr(d.*) or self.recordTypeOfExpr(d.*) != null or self.isArrayExpr(d.*)) return false;
        }
        return true;
    }

    fn lambdaTailIsPointer(self: *Emitter, body: []const ast.Stmt) bool {
        if (body.len == 0) return false;
        const last = body[ast.lastRealIndex(body)].expr;
        const v = switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |x| x.* else return false,
                else => last,
            },
            else => last,
        };
        return self.isStringExpr(v) or self.recordTypeOfExpr(v) != null or self.isArrayExpr(v) or self.optInfoOf(v) != null;
    }

    /// The box `boxesInto` asked for: `lowerAsUnknown`'s for an `unknown` /
    /// union slot, a `?T`'s `$__box_i32` cell otherwise.
    fn lowerBoxedInto(self: *Emitter, target: ?ast.TypeRef, value: ast.Expr) anyerror!void {
        if (self.mode == .gc) {
            const t = target orelse return self.gcFail("a box into no declared type");
            if (isUnknownTypeRef(t)) return self.lowerAsUnknown(value);
            // A generic constructor over a union argument: its payloads are
            // boxed whatever the slot (`gcGenericArg`).
            if (self.ctorUnionArgs(t, value) != null) {
                const vr = self.wasmTypeOf(value);
                if (!vr.isRef()) return self.gcFail("a union constructor of no reference");
                return self.lowerCoerced(value, vr);
            }
            if (value == .branch and armAnswersNull(value)) return self.gcFail("an if answering null into an optional");
            const oi = self.optInfoOfTypeRef(t) orelse return self.gcFail("a box into a type that is no optional");
            const pr = self.gcOptPayload(oi) orelse return self.gcFail("an optional of no known payload");
            try self.lowerCoerced(value, pr);
            try self.gcBox(pr);
            return;
        }
        if (target) |t| if (isUnknownTypeRef(t)) return self.lowerAsUnknown(value);
        if (target) |t| if (self.ctorUnionArgs(t, value)) |args| {
            self.ctor_box = .{ .args = args };
            defer self.ctor_box = .none;
            return self.lowerCoerced(value, .i32);
        };
        if (try self.lowerBoxedIfArms(target, value)) return;
        // A `?f64`'s / `?i64`'s box is the value's own 8-byte cell.
        const cell: Cell = if (target) |t| (if (self.optInfoOfTypeRef(t)) |oi| oi.cell else .none) else .none;
        if (cell != .none or Cell.of(self.wasmTypeOf(value)) != .none)
            return self.lowerCellWord(value, if (cell != .none) cell else Cell.of(self.wasmTypeOf(value)));
        try self.lowerCoerced(value, .i32);
        try self.emit(self.builder().helper(.box_i32));
    }

    /// `val n: ?i32 = if (c) 3 else null`: each arm goes into the slot on its
    /// own — a value boxed, `null` the `0` of absence. Boxing the whole `if`
    /// boxed the `0` of its `null` arm too, so an absent `n` read as a
    /// present `0`. Only a value-form `if` with an `else`, no binder, and an
    /// arm answering `null` at some depth takes this path.
    fn lowerBoxedIfArms(self: *Emitter, target: ?ast.TypeRef, value: ast.Expr) anyerror!bool {
        return self.lowerBoxedIf(target, value, false, null);
    }

    /// `force`: the `if` goes into an `unknown` whatever its arms answer
    /// (`lowerAsUnknown`), each arm boxed on its own — by the checker's type
    /// of the arm when it typed the `if` a union, else by `whole`, the type
    /// the `if` itself is boxed as (`unionArmTypes`).
    fn lowerBoxedIf(self: *Emitter, target: ?ast.TypeRef, value: ast.Expr, force: bool, whole: ?ast.TypeRef) anyerror!bool {
        if (value != .branch or value.branch.kind != .if_) return false;
        const i = value.branch.kind.if_;
        if (i.binding != null) return false;
        const els = i.else_ orelse return false;
        if (i.then_.len == 0 or els.len == 0 or !(force or armAnswersNull(value))) return false;
        const arm_types = try self.unionArmTypes(value, 2, whole);
        try self.lowerCondition(i.cond.*, null);

        var then_c: Capture = .{};
        self.open(&then_c);
        var then_names: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectNullTestNames(i.cond.*, true, &then_names);
        const then_marked = try self.applyNarrowing(then_names.items);
        try self.lowerBoxedArm(target, i.then_, if (arm_types) |a| a[0] else null);
        self.dropNarrowing(then_marked);
        const rty: ValType = if (self.mode == .gc) .anyref else .i32;
        const then_seq = self.seal(&then_c, .{ .value = rty });

        var else_c: Capture = .{};
        self.open(&else_c);
        var else_names: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectNullTestNames(i.cond.*, false, &else_names);
        const else_marked = try self.applyNarrowing(else_names.items);
        try self.lowerBoxedArm(target, els, if (arm_types) |a| a[1] else null);
        self.dropNarrowing(else_marked);
        const else_seq = self.seal(&else_c, .{ .value = rty });

        try self.emit(.{ .@"if" = .{
            .result = rty,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
        return true;
    }

    /// One arm of `lowerBoxedIfArms`: its statements, then its tail into the
    /// slot — `null` as `0`, a value boxed when the slot boxes it.
    fn lowerBoxedArm(self: *Emitter, target: ?ast.TypeRef, body: []const ast.Stmt, arm_type: ?ast.TypeRef) anyerror!void {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        if (hasDefer(body)) {
            var site: BoxedLast = .{ .target = target, .arm_type = arm_type };
            const mark = self.defer_stack.items.len;
            const tail = try self.emitStmtsFrom(body, 0, true, .i32, true, .{ .ctx = &site, .run = BoxedLast.run });
            try self.closeDefers(mark, tail);
            return;
        }
        for (body[0..ast.lastRealIndex(body)]) |stmt| _ = try self.emitStmt(stmt, false);
        try self.boxedLastStmt(target, body[ast.lastRealIndex(body)].expr, arm_type);
    }

    const BoxedLast = struct {
        target: ?ast.TypeRef,
        arm_type: ?ast.TypeRef,
        fn run(ctx: *anyopaque, em: *Emitter, stmt: ast.Stmt) anyerror!Tail {
            const self: *BoxedLast = @ptrCast(@alignCast(ctx));
            try em.boxedLastStmt(self.target, stmt.expr, self.arm_type);
            return .value;
        }
    };

    fn boxedLastStmt(self: *Emitter, target: ?ast.TypeRef, last: ast.Expr, arm_type: ?ast.TypeRef) anyerror!void {
        if (isNullLit(last)) {
            if (self.mode == .gc) try self.emit(.{ .ref_null = .anyref }) else try self.pushZero();
        } else if (self.boxesInto(target, last)) {
            if (target) |t| if (isUnknownTypeRef(t)) {
                self.box_as = arm_type;
            };
            try self.lowerBoxedInto(target, last);
        } else {
            try self.lowerCoerced(last, if (self.mode == .gc) .{ .ref = .unknown } else .i32);
        }
    }

    /// Whether a value-form `if` answers `null` from one of its arms, an
    /// `else if` chain followed.
    fn armAnswersNull(e: ast.Expr) bool {
        if (isNullLit(e)) return true;
        if (e != .branch or e.branch.kind != .if_) return false;
        const i = e.branch.kind.if_;
        if (i.binding != null) return false;
        const els = i.else_ orelse return false;
        if (i.then_.len == 0 or els.len == 0) return false;
        return armAnswersNull(i.then_[ast.lastRealIndex(i.then_)].expr) or armAnswersNull(els[ast.lastRealIndex(els)].expr);
    }

    /// The payload of the boxed optional on the stack: the word its box holds,
    /// or — a `?f64` — the `f64` its cell holds.
    fn emitUnboxPayload(self: *Emitter, o: OptInfo, what: []const u8) !void {
        if (self.mode == .gc) {
            const pr = self.gcOptPayload(o) orelse return self.gcFail("an optional of no known payload");
            return self.gcUnbox(pr);
        }
        try self.emitC(.{ .load = .{ .ty = (o.cell.ty()).num() } }, what);
    }

    // ── record inherent methods ──────────────────────────────────────────────

    /// `$<Record>_<method>` for `recv.method(…)` when inference tagged the
    /// receiver as a record value and the module emitted that method.
    /// Inference names a receiver's type by its bare name. When two linked
    /// modules declare that name, the later one is registered as
    /// `<module>/<Name>` (`link_mangled_types`), and the value's own module
    /// says which of the two a method call means — recovered from the
    /// expression as a field read's receiver is. Without this,
    /// `netOutcome().describe()` called the FIRST declaration's `describe`
    /// over the second one's layout and printed the neighbouring field.
    fn ownerAmongTwins(self: *Emitter, rec: []const u8, recv: ast.Expr) []const u8 {
        if (self.link_mangled_types.count() == 0) return rec;
        const own = self.recordTypeOfExpr(recv) orelse return rec;
        if (!std.mem.eql(u8, own, rec) and std.mem.eql(u8, displayTypeName(own), rec)) return own;
        return rec;
    }

    fn recordMethodSym(self: *Emitter, cc: anytype, loc: ast.Loc) ?[]const u8 {
        if (cc.receiver == null or cc.is_builtin) return null;
        // Inference records no note for a method on a value of an IMPORTED
        // type (`queryOf(xs).toArray()` with `Query` declared in `shapes`), so
        // the receiver's record is recovered here as it is for a field read —
        // the modules are linked into this one, so its `<Type>_<method>` is
        // emitted beside the local ones. Without it the call fell through and
        // `.length` on its result answered `0` at exit 0.
        const rec0 = if (self.instance_lowerings.get(loc)) |il| switch (il) {
            // A type this module never imported is linked in all the same.
            .type_, .unplaced_type => |r| r,
            // A behavior-typed receiver is answered by the value's own type
            // (`lowerBehaviorDispatch`) whenever some type of the module
            // declares the method: a record recovered from the expression is
            // a guess — `Array<Request>`'s elements were all read as the
            // first literal's `Page`, and `Api(3).weight(2)` answered `2`.
            .by_value => blk: {
                const impls = self.behaviorImplementers(cc.callee, cc.args.len) catch return null;
                if (impls.len > 0) return null;
                break :blk self.recordTypeOfExpr(cc.receiver.?.*) orelse return null;
            },
            .prim, .field_of, .sequence_next, .division, .assoc_fn_value, .task_await, .task_return, .failing_task_block, .union_value, .text_value => return null,
        } else self.recordTypeOfExpr(cc.receiver.?.*) orelse return null;
        const rec = self.ownerAmongTwins(rec0, cc.receiver.?.*);
        const sym = std.fmt.bufPrint(&self.sym_buf, "{s}_{s}", .{ rec, cc.callee }) catch return null;
        if (!self.fn_sigs.contains(sym)) return null;
        if (self.generic_methods.contains(sym)) {
            const generic = self.reg_arena.allocator().dupe(u8, sym) catch return null;
            return (self.specializeMethod(generic, cc) catch null) orelse generic;
        }
        return sym;
    }

    /// `specializedCallee` for a method of a generic `type`: the receiver's
    /// written type arguments (`Dict<string, string>`) and the arguments'
    /// shapes bind the owner's and the method's type parameters, and the call
    /// goes to a copy of the method with them substituted
    /// (`Dict_at__K_string__V_string`). One body compared two `K` keys as
    /// WORDS — a key `split` built at run time never equalled the literal
    /// (C-18) — and read a `?V` as a box whatever `V` was.
    /// `self` and every parameter of `m`: the names a method on which can
    /// reach an `==` over a record bound to the owner's type parameter.
    fn methodParamNames(ar: std.mem.Allocator, m: ast.BehaviorMethod) ![]const []const u8 {
        const names = try ar.alloc([]const u8, m.params.len + 1);
        names[0] = "self";
        for (m.params, names[1..]) |p, *out| out.* = p.name;
        return names;
    }

    fn specializeMethod(self: *Emitter, sym: []const u8, cc: anytype) !?[]const u8 {
        const gm = self.generic_methods.get(sym) orelse return null;
        const m = gm.method;
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        var needed = false;
        const Local = struct {
            fn has(list: []const TypeSub, n: []const u8) bool {
                for (list) |sub| if (std.mem.eql(u8, sub.name, n)) return true;
                return false;
            }
        };
        // The receiver's written type arguments, in the owner's order.
        if (self.typeRefOf(cc.receiver.?.*)) |tr| switch (tr) {
            .generic => |g| if (g.args.len == gm.tparams.len) for (g.args, gm.tparams) |arg, gp| switch (arg) {
                .named => |n| if (primKindOfName(n) != null or self.records.contains(n)) {
                    try subs.append(ar, .{ .name = gp.name, .to = arg });
                    if (std.mem.eql(u8, n, "string") or std.mem.eql(u8, n, "bool") or n[0] == 'f') needed = true;
                    // Decision 210: a record bound where the body compares with
                    // `==` — the one body would compare two pointers.
                    if (self.records.contains(n) and (comparesValues(ast.BehaviorMethod, m) or callsMethodOn(ast.BehaviorMethod, m, try methodParamNames(ar, m)))) needed = true;
                },
                else => {},
            },
            else => {},
        };
        // The arguments, for a parameter written as a bare type parameter.
        var params_of: std.ArrayListUnmanaged([]const u8) = .empty;
        var pi: usize = 0;
        for (m.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            defer pi += 1;
            if (pi >= cc.args.len) break;
            const bnd = self.bindParam(p.typeRef, cc.args[pi].value.*, &isGenericParamName, gm.tparams, m.genericParams) orelse continue;
            try params_of.append(ar, p.name);
            if (Local.has(subs.items, bnd.name)) continue;
            try subs.append(ar, .{ .name = bnd.name, .to = .{ .named = bnd.ty } });
            if (std.mem.eql(u8, bnd.ty, "string") or std.mem.eql(u8, bnd.ty, "bool") or bnd.ty[0] == 'f') needed = true;
            if (self.records.contains(bnd.ty) and comparesValues(ast.BehaviorMethod, m)) needed = true;
        }
        if (subs.items.len == 0) return null;
        if (self.mode == .gc) needed = true;
        if (!needed and !callsMethodOn(ast.BehaviorMethod, m, params_of.items)) return null;
        var name: std.ArrayListUnmanaged(u8) = .empty;
        try name.appendSlice(ar, m.name);
        for (subs.items) |sub| try name.print(ar, "__{s}_{s}", .{ sub.name, sub.to.named });
        const out = try std.fmt.allocPrint(ar, "{s}_{s}", .{ gm.owner, name.items });
        if (self.spec_names.contains(out)) return out;
        try self.spec_names.put(self.alloc, out, {});
        var copy = try substTypeParams(ast.BehaviorMethod, ar, m, subs.items);
        copy.name = name.items;
        var left_owner: std.ArrayListUnmanaged(ast.GenericParam) = .empty;
        for (gm.tparams) |gp| if (!Local.has(subs.items, gp.name)) try left_owner.append(ar, gp);
        var left_own: std.ArrayListUnmanaged(ast.GenericParam) = .empty;
        for (m.genericParams) |gp| if (!Local.has(subs.items, gp.name)) try left_own.append(ar, gp);
        copy.genericParams = left_own.items;
        try self.registerInterfaceSigs(gm.owner, left_owner.items, &.{copy});
        try self.mspec_pending.append(self.alloc, .{
            .owner = gm.owner,
            .tparams = left_owner.items,
            .method = copy,
            .rewrites = gm.rewrites,
            .lowerings = gm.lowerings,
            .renames = gm.renames,
            .subs = subs.items,
            .origin = self.specOrigin(gm.linked),
        });
        return out;
    }

    /// `c.atual()` on a record value → `call $Contador_atual` with the receiver
    /// as the `self` argument.
    fn lowerRecordMethod(self: *Emitter, cc: anytype, loc: ast.Loc) anyerror!bool {
        const sym_tmp = self.recordMethodSym(cc, loc) orelse return false;
        const sym = try self.arena().dupe(u8, sym_tmp);
        if (self.generic_methods.contains(sym)) try self.noteTemplateCall(sym, loc);
        const sig = self.fn_sigs.get(sym).?;
        var base: usize = 0;
        if (sig.params.len == cc.args.len + 1) {
            try self.lowerCoerced(cc.receiver.?.*, sig.params[0]);
            base = 1;
        }
        const expected = try self.methodLambdaExpectations(sym, cc);
        for (cc.args, 0..) |arg, i| {
            if (base + i >= sig.params.len) break;
            if (expected) |ex| if (arg.value.* == .function) {
                self.expected_fn = ex[i];
            };
            defer self.expected_fn = null;
            try self.lowerCoerced(arg.value.*, sig.params[base + i]);
        }
        var k = base + cc.args.len;
        while (k < sig.params.len) : (k += 1) {
            try self.emitC(constOf(sig.params[k], "0"), "missing argument");
        }
        try self.emit(.{ .call = sym });
        return true;
    }

    /// The function types a generic method declares for its parameters, with
    /// the owner's type parameters written as the receiver's type arguments
    /// (`Bag<i32>.map(f: fn(x: T) -> U)` → `fn(x: i32) -> U`): a lambda
    /// written as the argument is written against them. Inference saw `T`
    /// there and typed nothing the lambda's body could read.
    fn methodLambdaExpectations(self: *Emitter, sym: []const u8, cc: anytype) !?[]const ?ast.TypeRef {
        const gm = self.generic_methods.get(sym) orelse return null;
        const recv = cc.receiver orelse return null;
        const tr = self.typeRefOf(recv.*) orelse return null;
        if (tr != .generic or tr.generic.args.len != gm.tparams.len) return null;
        const ar = self.reg_arena.allocator();
        var subs: std.ArrayListUnmanaged(TypeSub) = .empty;
        for (tr.generic.args, gm.tparams) |arg, gp| try subs.append(ar, .{ .name = gp.name, .to = arg });
        const out = try ar.alloc(?ast.TypeRef, cc.args.len);
        @memset(out, null);
        var pi: usize = 0;
        for (gm.method.params) |p| {
            if (std.mem.eql(u8, p.name, "self")) continue;
            defer pi += 1;
            if (pi >= out.len) break;
            if (p.typeRef == .function) out[pi] = try substTypeParams(ast.TypeRef, ar, p.typeRef, subs.items);
        }
        return out;
    }

    /// Instance methods on the built-in array layout (`[len][e0][e1]…`) that
    /// the wasm memory model can serve directly. Returns false when the method
    /// isn't one of them, so the caller can fall back to the stub.
    fn lowerCollectionMethod(self: *Emitter, cc: anytype) anyerror!bool {
        const recv = cc.receiver orelse return false;
        if (std.mem.eql(u8, cc.callee, "at") and cc.args.len == 1) {
            // `xs.at(i)` → `xs[i]`, or 0 when out of range.
            try self.lowerValue(recv.*);
            try self.lowerCoerced(cc.args[0].value.*, .i32);
            try self.emit(self.builder().helper(.arr_at));
            return true;
        }
        if (std.mem.eql(u8, cc.callee, "length") and cc.args.len == 0) {
            try self.lowerValue(recv.*);
            // Decision 240: a string counts codepoints, an array its slots.
            if (self.isStringExpr(recv.*))
                try self.emitStdCall("text.length")
            else
                try self.emitC(.{ .load = .{} }, ".length (array prefix)");
            return true;
        }
        return false;
    }

    /// Front 164 s2 P2 — a record built in a GC module: its field values
    /// in declaration order, then `struct.new` of the record's type. A field
    /// no argument names is the neutral value of its type.
    fn gcRecordCtor(self: *Emitter, cc: anytype, fields: []const []const u8) anyerror!void {
        self.expected_ctor = null;
        const gps = self.record_generics.get(cc.callee);
        const trefs = self.record_field_typerefs.get(cc.callee) orelse return self.gcFail("a record with no field types");
        for (fields, 0..) |fname, i| {
            const ftref: ast.TypeRef = if (i < trefs.len) trefs[i] else return self.gcFail("a record field with no type");
            const fr = if (gps) |g| self.gcErasedRepr(g, ftref) else self.reprOf(ftref);
            if (self.argForField(cc.args, fname, i)) |arg| {
                // A lambda stored in a function-typed field is written
                // against the declared type.
                if (ftref == .function and arg.value.* == .function) self.expected_fn = ftref;
                defer self.expected_fn = null;
                const lambda_at: u32 = @intCast(self.lambdas.items.len);
                if (gps) |g| if (mentionsGeneric(ftref, g)) {
                    try self.gcGenericArg(ftref, g, fr, arg.value.*);
                    // A lambda in a field a type parameter types takes its
                    // parameters from the call through the field
                    // (`field_closures`).
                    if (arg.value.* == .function and self.lambdas.items.len > lambda_at) {
                        try self.ctor_lambdas.append(self.reg_arena.allocator(), .{ .field = fname, .idx = lambda_at });
                        if (ftref == .named) @memset(self.lambdas.items[lambda_at].param_known, false);
                    }
                    continue;
                };
                if (self.boxesInto(ftref, arg.value.*)) try self.lowerBoxedInto(ftref, arg.value.*) else try self.lowerCoerced(arg.value.*, fr);
                if (arg.value.* == .function and self.lambdas.items.len > lambda_at) try self.ctor_lambdas.append(self.reg_arena.allocator(), .{ .field = fname, .idx = lambda_at });
            } else {
                // A generic field with no argument: linear memory prints its
                // word by `i` (`genericShapes`), which an `anyref` cannot.
                if (gps) |g| if (mentionsGeneric(ftref, g)) return self.gcFail("a generic field with no argument");
                try self.emit(self.zeroOf(fr));
            }
        }
        try self.emit(.{ .struct_new = self.gcTyIndex(.{ .record = cc.callee }) });
    }

    /// The repr a field (or payload) of a generic declaration whose type
    /// parameters are `gps` is declared as: every type parameter erased to
    /// `unknown` — one struct type per declaration, never per instantiation
    /// (front 164 s2 P2b). `T` and `?T` are an `anyref`, `T[]` an `anyref`
    /// array, `#(K, V)` a tuple.
    fn gcErasedRepr(self: *Emitter, gps: []const ast.GenericParam, t: ast.TypeRef) Repr {
        const saved_owner = self.owner_tparams;
        const saved_fn = self.fn_tparams;
        self.owner_tparams = gps;
        self.fn_tparams = &.{};
        defer {
            self.owner_tparams = saved_owner;
            self.fn_tparams = saved_fn;
        }
        if (mentionsGeneric(t, gps)) switch (eagerTypeRef(t)) {
            .named, .optional => return .{ .ref = .unknown },
            .array => return .{ .ref = .{ .arr = .any } },
            .generic => |g| if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array")) return .{ .ref = .{ .arr = .any } },
            else => {},
        };
        return self.reprOf(t);
    }

    /// The erased repr (`gcErasedRepr`) field `member` of `rec` is declared
    /// as, when `rec` is a generic record and the field names one of its
    /// type parameters; null otherwise.
    fn gcGenericFieldDecl(self: *Emitter, rec: []const u8, member: []const u8) ?Repr {
        const gps = self.record_generics.get(rec) orelse return null;
        const fields = self.records.get(rec) orelse return null;
        const trefs = self.record_field_typerefs.get(rec) orelse return null;
        for (fields, 0..) |f, i| if (std.mem.eql(u8, f, member) and i < trefs.len) {
            if (!mentionsGeneric(trefs[i], gps)) return null;
            return self.gcErasedRepr(gps, trefs[i]);
        };
        return null;
    }

    /// The print shape of a field of a generic declaration declared `t`: a
    /// type parameter's slot printed by what it holds (`U`), so the value
    /// built into it must print the same way (`gcGenericArg`).
    fn gcErasedShape(self: *Emitter, gps: []const ast.GenericParam, t: ast.TypeRef) anyerror![]const u8 {
        if (!mentionsGeneric(t, gps)) return self.fieldShape(t);
        return switch (eagerTypeRef(t)) {
            .named, .optional => "U",
            .array => |inner| try std.fmt.allocPrint(self.arena(), "[{s}", .{try self.gcErasedShape(gps, inner.*)}),
            .generic => |g| if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array"))
                try std.fmt.allocPrint(self.arena(), "[{s}", .{try self.gcErasedShape(gps, g.args[0])})
            else
                self.gcFail("a generic field of a generic type"),
            .tuple_ => |elems| blk: {
                var out: std.ArrayListUnmanaged(u8) = .empty;
                try out.append(self.arena(), '(');
                for (elems) |el| try out.appendSlice(self.arena(), try self.gcErasedShape(gps, el));
                try out.append(self.arena(), ')');
                break :blk out.items;
            },
            else => self.gcFail("a generic field of no GC shape"),
        };
    }

    /// The argument `value` of a field (or payload) of a generic declaration
    /// declared `ft` (repr `fr`, `gcErasedRepr`): a value already of that repr
    /// as it is; a scalar into a type parameter's slot boxed by its print
    /// shape, which the slot's printer (`U`) answers the same way. A value
    /// whose text the slot would not print as linear memory does (a float, an
    /// all-unit enum's ordinal, an array of words) is refused here.
    fn gcGenericArg(self: *Emitter, ft: ast.TypeRef, gps: []const ast.GenericParam, fr: Repr, value: ast.Expr) anyerror!void {
        _ = gps;
        const vr = self.wasmTypeOf(value);
        if (isNullLit(value)) {
            if (!fr.isRef()) return self.gcFail("a null into a generic field");
            try self.emit(self.zeroOf(fr));
            return;
        }
        if (isEmptyArrayLit(value) and fr.isArrRef()) {
            try self.emit(zero);
            try self.emit(.{ .array_new_default = self.gcTyIndex(.{ .arr = fr.ref.arr }) });
            return;
        }
        if (vr.isRef() and fr.isRef()) {
            if (vr.eql(fr) or (fr.ref == .unknown and vr.ref != .unknown and vr.ref != .bytes and vr.ref != .cell and vr.ref != .bigint)) {
                // A reference slot of a type parameter: the value prints by
                // what it is — a string quoted, a record or variant by its
                // printer —, an array or a tuple only when its shape has no
                // word the slot could not name.
                if (fr.ref == .unknown and vr.ref == .arr) {
                    // An array of words, floats or strings prints as its
                    // elements do (`$__print_arrs`); a bool array's words
                    // would print as numbers, a nested one is ambiguous.
                    const sh = (try self.printShapeOf(value)) orelse return self.gcFail("an array in a type parameter's slot of no print shape");
                    if (!(std.mem.eql(u8, sh, "[i") or std.mem.eql(u8, sh, "[f") or std.mem.eql(u8, sh, "[s"))) return self.gcFail("an array of another shape in a type parameter's slot");
                }
                if (fr.ref == .arr or fr.ref == .tuple or (fr.ref == .unknown and vr.ref == .tuple)) {
                    const sh = (try self.printShapeOf(value)) orelse return self.gcFail("a generic container of no print shape");
                    // Each element prints by its box (`U`): a bool, an
                    // all-unit enum's ordinal or a `u64` would not.
                    for (sh) |ch| if (std.mem.indexOfScalar(u8, "sifl[()TU?!", ch) == null) return self.gcFail("a generic container holding words");
                }
                try self.lowerCoerced(value, vr);
                return;
            }
            // An array of words or floats into a type parameter's array
            // (`Q(items: [7])` over `items: Array<T>`): its elements boxed
            // into an `anyref` array, which print by their boxes as their
            // words did by `i` / `f`.
            if (vr.isArrRef() and fr.isArrRef() and fr.ref.arr == .any and vr.ref.arr != .any) {
                // A literal only: a named array shares its elements with
                // whoever else holds it, and the boxed copy would not.
                if (!(value == .collection and value.collection.kind == .arrayLit)) return self.gcFail("a named array of words into a generic array");
                const sh = (try self.printShapeOf(value)) orelse return self.gcFail("a generic array of no print shape");
                if (!(std.mem.eql(u8, sh, "[i") or std.mem.eql(u8, sh, "[f"))) return self.gcFail("a generic array of words with no box");
                try self.lowerCoerced(value, vr);
                try self.emit(.{ .call = try self.gcArrBox(vr.ref.arr) });
                return;
            }
            return self.gcFail("a generic field of another shape");
        }
        if (!(fr == .ref and fr.ref == .unknown)) return self.gcFail("a scalar into a generic container field");
        if (eagerTypeRef(ft) == .optional) return self.gcFail("a scalar into a generic optional field");
        // An all-unit enum's ordinal: in its enum's box, which prints by name.
        if (self.unitEnumOf(value) orelse self.unitEnumOfTypeRef(value)) |en| {
            try self.lowerCoerced(value, .i32);
            try self.emit(.{ .struct_new = self.gcTyIndex(.{ .ebox = en }) });
            return;
        }
        const sh = try self.valueShapeOf(value);
        if (sh.len != 1) return self.gcFail("a generic argument of a composite shape");
        switch (sh[0]) {
            'i' => {
                try self.lowerCoerced(value, .i32);
                try self.gcBox(.i32);
            },
            'b' => {
                try self.lowerCoerced(value, .bool);
                try self.gcBox(.bool);
            },
            // A float goes in its own box, which the slot's printer and a
            // reader at the type argument both know (front 164 s2 P3).
            'f' => {
                try self.lowerCoerced(value, .f64);
                try self.gcBox(.f64);
            },
            else => return self.gcFail("a generic argument with no box"),
        }
    }

    fn lowerRecordCtor(self: *Emitter, cc: anytype, fields: []const []const u8) anyerror!void {
        if (self.mode == .gc) return self.gcRecordCtor(cc, fields);
        const expected_ctor = self.expected_ctor;
        self.expected_ctor = null;
        const desc = try self.typeDescriptorAddr(cc.callee, null);
        const rgens = self.record_generics.get(cc.callee) orelse &.{};
        const base = try self.allocTagged(desc orelse 0, @intCast((fields.len + @intFromBool(rgens.len > 0)) * 4));
        if (rgens.len > 0) {
            const refs = self.record_field_typerefs.get(cc.callee) orelse &.{};
            try self.storeSlotConst(base, @intCast(tag_header_bytes + fields.len * 4), try self.genericShapes(cc, fields, refs, rgens));
        }
        for (fields, 0..) |fname, i| {
            const off: u32 = @intCast(tag_header_bytes + i * 4);
            if (self.argForField(cc.args, fname, i)) |arg| {
                const ftref: ?ast.TypeRef = if (self.record_field_typerefs.get(cc.callee)) |ts| (if (i < ts.len) ts[i] else null) else null;
                if (self.boxesInto(ftref, arg.value.*)) {
                    try self.emit(.{ .local_get = base });
                    try self.lowerBoxedInto(ftref, arg.value.*);
                    try self.emit(.{ .store = .{ .offset = off } });
                } else if (self.fieldCellIn(cc.callee, fname) != .none) {
                    // A float or `i64` field holds the address of its cell.
                    try self.emit(.{ .local_get = base });
                    try self.lowerCellWord(arg.value.*, self.fieldCellIn(cc.callee, fname));
                    try self.emit(.{ .store = .{ .offset = off } });
                } else {
                    // A lambda stored in a function-typed field takes its
                    // parameter types from the field's declaration, as one
                    // bound to an annotated `val` does: `{ s -> prefix + s }`
                    // in a `fn(s: string) -> string` field concatenates.
                    // A field written `T` under an expected `Box<fn(…) -> R>`:
                    // the lambda is written against the type argument.
                    const fexp: ?ast.TypeRef = blk: {
                        const ft = ftref orelse break :blk null;
                        const et = expected_ctor orelse break :blk ftref;
                        if (ft != .named or et != .generic or !std.mem.eql(u8, et.generic.name, cc.callee)) break :blk ftref;
                        const gps = self.record_generics.get(cc.callee) orelse break :blk ftref;
                        for (gps, 0..) |gp, gi| if (std.mem.eql(u8, gp.name, ft.named) and gi < et.generic.args.len) break :blk et.generic.args[gi];
                        break :blk ftref;
                    };
                    if (arg.value.* == .function) self.expected_fn = fexp;
                    defer self.expected_fn = null;
                    // A float or an `i64` in a field its declaration does not
                    // type as one (`Box<T>(value: T)`): the slot would hold a
                    // cell that every reader of `T` takes for a word — `300`
                    // printed for `Box(value: 1.1).value` at exit 0.
                    if (Cell.of(self.wasmTypeOf(arg.value.*)) != .none)
                        return self.refuse(arg.value.getLoc(), "the wasm backend cannot hold an `{s}` in field `{s}`: its declared type is not one, and its readers take a word", .{ self.wasmTypeOf(arg.value.*).name(), fname });
                    const lambda_at: u32 = @intCast(self.lambdas.items.len);
                    try self.storeSlotExpr(base, off, arg.value.*);
                    if (arg.value.* == .function and self.lambdas.items.len > lambda_at) {
                        try self.ctor_lambdas.append(self.reg_arena.allocator(), .{ .field = fname, .idx = lambda_at });
                        // A field written as the record's type parameter
                        // (`Box<T>(value: T)`) types nothing: the lambda's
                        // parameters are unknown until a call through the
                        // field passes them (`field_closures`).
                        const generic_slot = (fexp == null or fexp.? != .function) and if (ftref) |ft| ft == .named and (if (self.record_generics.get(cc.callee)) |gps| isGenericParamName(ft.named, gps, &.{}) else false) else false;
                        if (generic_slot) @memset(self.lambdas.items[lambda_at].param_known, false);
                    }
                }
            } else {
                try self.storeSlotConst(base, off, 0);
            }
        }
        try self.loadTaggedBase(base);
    }

    /// Pick the call argument that fills field `fname` (declaration index `idx`):
    /// the labelled arg whose label matches, else the positional arg at `idx`.
    fn argForField(self: *Emitter, args: anytype, fname: []const u8, idx: usize) ?@TypeOf(args[0]) {
        _ = self;
        for (args) |arg| {
            if (arg.label) |lbl| {
                if (std.mem.eql(u8, lbl, fname)) return arg;
            }
        }
        // No matching label — fall back to positional (skipping `..spread`).
        if (idx < args.len and args[idx].label == null) return args[idx];
        return null;
    }

    /// The type arguments of `t` (`Maybe<i32 | string>`) when `value` is a
    /// constructor of that generic enum and some argument is an `unknown` /
    /// union: the payloads of that parameter are boxed (`ctor_box`).
    fn ctorUnionArgs(self: *Emitter, t: ast.TypeRef, value: ast.Expr) ?[]const ast.TypeRef {
        if (t != .generic or !self.isGenericEnumCtor(value)) return null;
        const cc = value.call.kind.call;
        const en = if (receiverName(cc)) |r| (self.enums.getKey(r) orelse return null) else self.enumOfVariant(cc.callee) orelse return null;
        if (!std.mem.eql(u8, en, t.generic.name)) return null;
        for (t.generic.args) |a| if (isUnknownTypeRef(a)) return t.generic.args;
        return null;
    }

    fn isCaseExpr(e: ast.Expr) bool {
        return e == .collection and e.collection.kind == .case;
    }

    /// Whether `e` is a constructor call of a generic enum: written in an
    /// `unknown` slot it boxes its type-parameter payloads (`box_ctor_tparams`).
    fn isGenericEnumCtor(self: *Emitter, e: ast.Expr) bool {
        if (e != .call or e.call.kind != .call) return false;
        const cc = e.call.kind.call;
        if (self.callKind(cc) != .enum_ctor) return false;
        const en = if (receiverName(cc)) |r| (self.enums.getKey(r) orelse return false) else self.enumOfVariant(cc.callee) orelse return false;
        return (self.enum_generics.get(en) orelse return false).len > 0;
    }

    /// Whether a payload declared `t` goes in boxed under `box` (`ctor_box`).
    fn ctorBoxes(box: CtorBox, egens: []const ast.GenericParam, t: ast.TypeRef) bool {
        if (box == .none or t != .named) return false;
        for (egens, 0..) |gp, i| if (std.mem.eql(u8, gp.name, t.named)) return switch (box) {
            .none => false,
            .all => true,
            .args => |args| i < args.len and isUnknownTypeRef(args[i]),
        };
        return false;
    }

    /// `Color.Rgb(r: 1, g: 2, b: 3)` → `[tag, r, g, b]`. The tag (variant index)
    /// lives at offset 0; payload fields follow at 4, 8, ...
    fn lowerEnumCtor(self: *Emitter, cc: anytype, tag: u32, variant: ast.EnumVariant) anyerror!void {
        const nslots = 1 + variant.fields.len;
        const box = self.ctor_box;
        self.ctor_box = .none;
        const ename = receiverName(cc) orelse self.enumOfVariant(variant.name) orelse "";
        if (self.mode == .gc) {
            if (ename.len == 0) return self.gcFail("a variant of no enum");
            // A generic enum's payloads are erased (`gcErasedRepr`): the
            // variant's struct is one per declaration, a type parameter's
            // payload an `anyref` — boxed here whatever slot the value goes
            // into, so `ctor_box` asks nothing more of it.
            const gps = self.enum_generics.get(ename);
            if (box != .none and gps == null) return self.gcFail("a boxed variant");
            for (variant.fields, 0..) |vf, i| {
                const fr = if (gps) |g| self.gcErasedRepr(g, vf.typeRef) else self.reprOf(vf.typeRef);
                if (self.argForField(cc.args, vf.name, i)) |arg| {
                    // A lambda stored in a function-typed payload is written
                    // against the declared type.
                    if (vf.typeRef == .function and arg.value.* == .function) self.expected_fn = vf.typeRef;
                    defer self.expected_fn = null;
                    if (gps) |g| if (mentionsGeneric(vf.typeRef, g)) {
                        try self.gcGenericArg(vf.typeRef, g, fr, arg.value.*);
                        continue;
                    };
                    if (self.boxesInto(vf.typeRef, arg.value.*)) try self.lowerBoxedInto(vf.typeRef, arg.value.*) else try self.lowerCoerced(arg.value.*, fr);
                } else {
                    if (gps) |g| if (mentionsGeneric(vf.typeRef, g)) return self.gcFail("a generic payload with no argument");
                    try self.emit(self.zeroOf(fr));
                }
            }
            try self.emit(.{ .struct_new = self.gcTyIndex(.{ .variant = .{ .en = ename, .name = variant.name } }) });
            return;
        }
        const desc = try self.variantDescriptorAddr(ename, variant);
        const egens = self.enum_generics.get(ename) orelse &.{};
        const base = try self.allocTagged(desc orelse 0, @intCast((nslots + @intFromBool(egens.len > 0)) * 4));
        if (egens.len > 0) {
            var names: std.ArrayListUnmanaged([]const u8) = .empty;
            var refs: std.ArrayListUnmanaged(ast.TypeRef) = .empty;
            for (variant.fields) |vf| {
                try names.append(self.arena(), vf.name);
                try refs.append(self.arena(), vf.typeRef);
            }
            try self.storeSlotConst(base, @intCast(tag_header_bytes + nslots * 4), try self.genericShapes(cc, names.items, refs.items, egens));
        }
        try self.storeSlotConst(base, tag_header_bytes, tag);
        for (variant.fields, 0..) |vf, i| {
            const off: u32 = @intCast(tag_header_bytes + (i + 1) * 4);
            if (self.argForField(cc.args, vf.name, i)) |arg| {
                if (ctorBoxes(box, egens, vf.typeRef)) {
                    try self.emit(.{ .local_get = base });
                    try self.lowerAsUnknown(arg.value.*);
                    try self.emit(.{ .store = .{ .offset = off } });
                    continue;
                }
                // A float's slot holds its cell, which only a payload declared
                // a float is read as: under a type parameter (`Some(v: T)`) a
                // binder and the printer took the cell's address for the value.
                const declared_float = switch (vf.typeRef) {
                    .named => |n| isFloatTypeName(n),
                    else => false,
                };
                if (self.wasmTypeOf(arg.value.*).isFloat() and !declared_float)
                    return self.refuse(arg.value.getLoc(), "the wasm backend cannot hold an `f64` in payload `{s}`: its declared type is not one, and its readers take a word", .{vf.name});
                try self.storeSlotExpr(base, off, arg.value.*);
            } else {
                try self.storeSlotConst(base, off, 0);
            }
        }
        try self.loadTaggedBase(base);
    }

    /// `recv.member` — tuple element (`t._0`), qualified enum unit variant
    /// (`Color.Red`), or a named record field (`r.b` / `self.x`).
    fn lowerIdentAccess(self: *Emitter, ia: anytype, loc: ast.Loc) anyerror!void {
        // 144 B-10 — `Box.wrap` named without a call: the type's associated
        // fn `Box_wrap` as a closure over its trampoline, as a top-level fn
        // named as a value is.
        if (self.instance_lowerings.get(loc)) |il| if (il == .assoc_fn_value) {
            const af = il.assoc_fn_value;
            const sym = try std.fmt.allocPrint(self.reg_arena.allocator(), "{s}_{s}", .{ af.type_name, af.method });
            if (self.fn_sigs.contains(sym)) return self.lowerFnRef(sym, loc);
        };
        // `xs.length` / `s.length` on a primitive: inference recorded the
        // receiver's family at this loc, and both layouts keep the count in the
        // first word.
        if (std.mem.eql(u8, ia.member, "length")) {
            if (self.instance_lowerings.get(loc)) |il| if (il == .prim) {
                try self.lowerValue(ia.receiver.*);
                // Decision 240: a string counts codepoints.
                if (il.prim == .string)
                    try self.emitStdCall("text.length")
                else if (self.mode == .gc)
                    try self.emit(.array_len)
                else
                    try self.emitC(.{ .load = .{} }, ".length");
                return;
            };
            // Inference records `.prim` only where it typed the receiver. It
            // does not type decision 30's index node yet, so `xs[0..2].length`
            // and a local bound to a slice arrived here unrecorded and fell
            // through to the field-access stub — `i32.const 0`, a wrong length
            // with exit 0. This backend's own predicates know the receiver is a
            // blob; neither is ever true of a record, so a field actually named
            // `length` still resolves below.
            if (self.isArrayExpr(ia.receiver.*) or self.isStringExpr(ia.receiver.*)) {
                try self.lowerValue(ia.receiver.*);
                if (self.isStringExpr(ia.receiver.*))
                    try self.emitStdCall("text.length")
                else if (self.mode == .gc)
                    try self.emit(.array_len)
                else
                    try self.emitC(.{ .load = .{} }, ".length");
                return;
            }
        }
        // `.len` on a string → load the length prefix. Strings are
        // length-prefixed buffers, so the value points at the i32 length word.
        // Codegen is untyped; `.len` is assumed to mean string length here.
        if (std.mem.eql(u8, ia.member, "len")) {
            try self.lowerExpr(ia.receiver.*);
            try self.emitC(.{ .load = .{} }, "string length");
            return;
        }
        // Tuple element access: `_0`, `_1`, ... → load at `index * 4`; a
        // float element's slot holds its cell.
        if (tupleIndex(ia.member)) |idx| {
            // `recv?._N`: absent when the tuple is — the load reads a present
            // one only, and a scalar element is boxed (`optInfoOf`).
            if (ia.optional) {
                try self.lowerOptionalField(ia, idx * 4, "");
                return;
            }
            if (self.mode == .gc) return self.gcTupleGet(ia.receiver.*, idx, .{ .identifier = .{ .loc = loc, .kind = .{ .identAccess = ia } } });
            try self.lowerExpr(ia.receiver.*);
            try self.emitLoadOffset(idx * 4);
            if (try self.tupleElemShapeOf(.{ .identifier = .{ .loc = loc, .kind = .{ .identAccess = ia } } })) |el| try self.emitFromCell(shapeCell(el));
            return;
        }
        // Qualified enum unit variant: `Color.Red` → variant tag.
        switch (ia.receiver.*) {
            .identifier => |rid| switch (rid.kind) {
                .ident => |ename| {
                    if (self.enums.get(ename)) |variants| {
                        for (variants, 0..) |v, i| {
                            if (std.mem.eql(u8, v.name, ia.member)) {
                                try self.emitUnitVariant(variants, @intCast(i), ename, ia.member);
                                return;
                            }
                        }
                    }
                },
                else => {},
            },
            else => {},
        }
        // Front 164 s2 P2 — a field of a record in a GC module is a read of
        // the struct's field, typed by the declaration.
        if (self.mode == .gc) {
            const rty = self.recordTypeOfExpr(ia.receiver.*) orelse return self.gcFail("a field of a receiver of no known record");
            const off = self.fieldOffsetIn(rty, ia.member) orelse return self.gcFail("a field the record does not declare");
            if (ia.optional) return self.gcOptionalField(ia, rty);
            try self.lowerCoerced(ia.receiver.*, .{ .ref = .{ .record = rty } });
            try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.{ .record = rty }), .field = off / 4 } });
            // A type parameter's slot of a generic record: read as the
            // receiver's type argument where it is known (unboxed, cast).
            if (self.gcGenericFieldDecl(rty, ia.member)) |dr| if (dr == .ref and dr.ref == .unknown) {
                const want = self.wasmTypeOf(.{ .identifier = .{ .loc = loc, .kind = .{ .identAccess = ia } } });
                if (!(want == .ref and want.ref == .unknown)) try self.gcUnbox(want);
            };
            return;
        }
        // Named record-field access — two-level resolution:
        //   1. **Type recovery** (`recordTypeOfExpr`): walk the receiver's
        //      recovered record type (`self_type` in methods, `local_types`
        //      for let-bindings, fn return-type for direct calls, chained
        //      field types for `a.b.c`) and load at the field's declared
        //      4-byte offset. `?.` guards via `local.tee` + `i32.eqz` +
        //      `(if (result i32) ...)`. Carrier shape: none = `i32.const 0`.
        //   2. **Unique-field heuristic** (`uniqueFieldOffset`): when type
        //      recovery fails (anon record literals bound to a local,
        //      cross-template captures, …), fall back to scanning the
        //      record registry for an unambiguous slot owner of the bare
        //      field name. Templates catalogued in the F0 audit use a
        //      disjoint field vocabulary (`Span.start/end/line`,
        //      `CustomNode.kind/span/ref/children`, …) so the heuristic
        //      terminates uniquely in practice.
        //   3. **Stub** (`i32.const 0`) — recorded backend limit; the
        //      surrounding fn still runs under wasmtime.
        if (self.recordTypeOfExpr(ia.receiver.*)) |rty| {
            if (self.fieldOffsetIn(rty, ia.member)) |off| {
                if (ia.optional) {
                    try self.lowerOptionalField(ia, off, "");
                    return;
                }
                try self.lowerExpr(ia.receiver.*);
                try self.emitCf(.{ .load = .{ .offset = off } }, ".{s}", .{ia.member});
                // A float or `i64` field holds its cell.
                try self.emitFromCell(self.fieldCellIn(rty, ia.member));
                return;
            }
        }
        // Type recovery failed — try the name-unique fallback. `?.` on this
        // path still has to short-circuit on a null pointer, so use the same
        // `local.tee` + `i32.eqz` guard as the typed branch above.
        if (self.uniqueFieldOffset(ia.member)) |off| {
            // The slot of a float field holds a cell, which a read by the
            // name alone cannot tell from an integer's word.
            if (self.someFieldIsFloat(ia.member))
                return self.refuse(loc, "the wasm backend cannot read `.{s}`: the receiver's type is not known here, and a record declares it a float or an `i64`", .{ia.member});
            if (ia.optional) {
                try self.lowerOptionalField(ia, off, " (unique)");
                return;
            }
            try self.lowerExpr(ia.receiver.*);
            try self.emitLoadOffset(off);
            return;
        }
        // Both heuristics failed. This used to write `i32.const 0` "so
        // wasmtime still executes the surrounding fn" — the program then
        // printed `0` for a field it never read, at exit 0.
        return self.refuse(loc, "the wasm backend cannot place `{s}.{s}`: the receiver's type is not known here", .{ if (ia.optional) "?" else "", ia.member });
    }

    /// `recv?.field` → stash the receiver, test it for null, and load the slot
    /// only on the present branch. `suffix` marks which resolution found the
    /// offset, matching the historical comments.
    fn lowerOptionalField(self: *Emitter, ia: anytype, off: u32, suffix: []const u8) anyerror!void {
        const mem = try self.memName(self.nextMem());
        try self.lowerExpr(ia.receiver.*);
        try self.emit(.{ .local_tee = mem });
        try self.emit(opOf(.i32, "eqz"));

        var then_c: Capture = .{};
        self.open(&then_c);
        try self.emitAtCf(8, zero, "?.{s} on null", .{ia.member});
        const then_seq = self.seal(&then_c, .{ .value = .i32 });

        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emitAt(8, .{ .local_get = mem });
        try self.emitAtCf(8, .{ .load = .{ .offset = off } }, "?.{s}{s}", .{ ia.member, suffix });
        // `?.` makes the result a `?T`: a scalar field goes in a box.
        // An element that is itself optional is already its own carrier.
        const elem_opt = tupleIndex(ia.member) != null and if (self.optTupleElemShapeOf(ia) catch null) |el|
            el.len > 0 and (el[0] == '?' or el[0] == '!')
        else
            false;
        if (!elem_opt) if (self.optInfoOf(.{ .identifier = .{ .loc = .{ .line = 0, .col = 0 }, .kind = .{ .identAccess = ia } } })) |oi| {
            if (oi.boxed and oi.cell == .none) try self.emitAt(8, self.builder().helper(.box_i32));
        };
        const else_seq = self.seal(&else_c, .{ .value = .i32 });

        try self.emit(.{ .@"if" = .{
            .result = .i32,
            .then = .{ .seq = then_seq },
            .@"else" = .{ .seq = else_seq },
        } });
    }

    /// Single-field heuristic for untyped wat codegen: returns the slot offset
    /// when every registered record-type with a field named `name` places it at
    /// the same index (i.e., the name maps to one unambiguous offset across the
    /// program's type registry). Returns null when two record types disagree on
    /// the slot — caller falls back to the unresolved-member stub.
    /// Decision 22 — the descriptor a record's values carry:
    /// `'R' <n> Name <k> [ <n> field <shape…> ] * k`, interned as an ordinary
    /// data segment (so two identical descriptors are one blob) and addressed
    /// past its length word. Null when this module never declared the type.
    fn typeDescriptorAddr(self: *Emitter, name: []const u8, _: ?u8) anyerror!?u32 {
        if (self.type_descs.get(name)) |addr| return addr;
        const fields = self.records.get(name) orelse return null;
        var out: std.ArrayListUnmanaged(u8) = .empty;
        try out.append(self.arena(), 'R');
        try self.appendNameAndFields(&out, name, fields, self.record_field_typerefs.get(name), true, self.record_generics.get(name) orelse &.{});
        const seg = try self.internString(out.items);
        const addr = seg.offset + 4;
        try self.type_descs.put(name, addr);
        return addr;
    }

    /// Decision 758 — the static blob a run-time type token `name` points at,
    /// read by `$__is_type_token` (`wat_prelude.zig`): `[0][n][d0]…` a record's
    /// or an enum's descriptors, `[1][lo][hi]` an integer type, `[2]` a float
    /// type, `[3]` `bool`, `[4]` `string`, `[5]` `unknown`. Null for a type
    /// whose values carry no descriptor (an all-unit enum), which `x is T`
    /// refuses too.
    fn typeTokenAddr(self: *Emitter, name: []const u8) anyerror!?u32 {
        var words: std.ArrayListUnmanaged(i32) = .empty;
        const ar = self.arena();
        if (primTestOf(.{ .named = name })) |pt| switch (pt) {
            .int => |r| try words.appendSlice(ar, &.{ 1, r.lo, r.hi }),
            .float => try words.append(ar, 2),
            .bool_ => try words.append(ar, 3),
            .string => try words.append(ar, 4),
        } else if (std.mem.eql(u8, name, ast.unknown_type_name)) {
            try words.append(ar, 5);
        } else {
            const descs = try self.typeDescriptors(.{ .named = name });
            if (descs.len == 0) return null;
            try words.appendSlice(ar, &.{ 0, @intCast(descs.len) });
            for (descs) |d| try words.append(ar, @bitCast(d));
        }
        const bytes = try ar.alloc(u8, words.items.len * 4);
        for (words.items, 0..) |w, i| std.mem.writeInt(i32, bytes[i * 4 ..][0..4], w, .little);
        const seg = try self.internString(bytes);
        return seg.offset + 4;
    }

    /// An enum every variant of which is a unit variant: its value is the
    /// ordinal, with no allocation and no header.
    fn isAllUnitEnum(self: *Emitter, name: []const u8) bool {
        const variants = self.enums.get(name) orelse return false;
        return variants.len > 0 and !enumHasPayload(variants);
    }

    /// `Color.Red` written against an all-unit enum: the enum's name.
    fn unitEnumMember(self: *Emitter, ia: anytype) ?[]const u8 {
        const ename = switch (ia.receiver.*) {
            .identifier => |rid| switch (rid.kind) {
                .ident => |n| n,
                else => return null,
            },
            else => return null,
        };
        if (!self.isAllUnitEnum(ename)) return null;
        for (self.enums.get(ename).?) |v| if (std.mem.eql(u8, v.name, ia.member)) return ename;
        return null;
    }

    /// The all-unit enum `e` is a value of, when a declaration says so: a
    /// member written by its path, a name, a field or a call whose declared
    /// type is the enum. Its value is an ordinal, so it prints by the shape
    /// `unitEnumShape` spells, never through the numeric printer.
    fn unitEnumOf(self: *Emitter, e: ast.Expr) ?[]const u8 {
        switch (e) {
            .identifier => |id| switch (id.kind) {
                .identAccess => |ia| if (self.unitEnumMember(ia)) |en| return en,
                else => {},
            },
            // `if (c) { Color.Green } else { Color.Red }`: both arms answer one
            // type, and an arm's tail says which.
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    const els = i.else_ orelse return null;
                    if (i.then_.len > 0) if (self.unitEnumOf(i.then_[ast.lastRealIndex(i.then_)].expr)) |en| return en;
                    if (els.len > 0) return self.unitEnumOf(els[ast.lastRealIndex(els)].expr);
                    return null;
                },
                else => {},
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.unitEnumOf(inner.*),
                else => {},
            },
            else => {},
        }
        const tr = self.typeRefOf(e) orelse return null;
        return switch (tr) {
            .named => |n| if (self.isAllUnitEnum(n)) n else null,
            else => null,
        };
    }

    /// The print shape of the payload of a boxed `?E` over an all-unit enum:
    /// a declared `?Color`, or `cs.at(i)` / `cs.first()` over an array whose
    /// elements print by such a shape.
    fn optUnitEnumShape(self: *Emitter, e: ast.Expr, oi: OptInfo) anyerror!?[]const u8 {
        if (oi.inner) |inner| switch (inner) {
            .named => |n| if (self.isAllUnitEnum(n)) return try self.unitEnumShape(n),
            else => {},
        };
        if (self.typeRefOf(e)) |tr| switch (tr) {
            .optional => |i| switch (i.*) {
                .named => |n| if (self.isAllUnitEnum(n)) return try self.unitEnumShape(n),
                else => {},
            },
            else => {},
        };
        const cc = switch (e) {
            .call => |c| switch (c.kind) {
                .call => |cc| cc,
                else => return null,
            },
            else => return null,
        };
        const recv = cc.receiver orelse return null;
        const shape = (try self.printShapeOf(recv.*)) orelse return null;
        if (shape.len > 1 and shape[0] == '[' and shape[1] == 'E') return shape[1..];
        return null;
    }

    /// `E k [ <n> Enum.Variant ] * k` — the print shape of an all-unit enum's
    /// value (`$__print_shaped_raw`): the ordinal picks the name.
    fn unitEnumShape(self: *Emitter, ename: []const u8) anyerror![]const u8 {
        const variants = self.enums.get(ename) orelse return error.UnknownEnum;
        if (variants.len > 255) return error.NameTooLong;
        const a = self.arena();
        var out: std.ArrayListUnmanaged(u8) = .empty;
        try out.append(a, 'E');
        try out.append(a, @intCast(variants.len));
        for (variants) |v| {
            const text = try std.fmt.allocPrint(a, "{s}.{s}", .{ self.printed_names.get(ename) orelse displayTypeName(ename), v.name });
            if (text.len > 255) return error.NameTooLong;
            try out.append(a, @intCast(text.len));
            try out.appendSlice(a, text);
        }
        return out.items;
    }

    /// The same for ONE variant — its name is written `Enum.Variant`, which is
    /// the text decision 8 §7 wants, and its fields start one slot in because
    /// slot 0 holds the ordinal the `case` arms test.
    fn variantDescriptorAddr(self: *Emitter, ename: []const u8, v: ast.EnumVariant) anyerror!?u32 {
        if (ename.len == 0) return null;
        const key = try std.fmt.allocPrint(self.reg_arena.allocator(), "{s}.{s}", .{ ename, v.name });
        if (self.type_descs.get(key)) |addr| return addr;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        var refs: std.ArrayListUnmanaged(ast.TypeRef) = .empty;
        for (v.fields) |f| {
            try names.append(self.arena(), f.name);
            try refs.append(self.arena(), f.typeRef);
        }
        var out: std.ArrayListUnmanaged(u8) = .empty;
        try out.append(self.arena(), 'V');
        try self.appendNameAndFields(&out, key, names.items, refs.items, false, self.enum_generics.get(ename) orelse &.{});
        const seg = try self.internString(out.items);
        const addr = seg.offset + 4;
        try self.type_descs.put(key, addr);
        return addr;
    }

    /// `<n> name <k> [ <n> field <shape…> ] * k`. A name longer than 255 bytes
    /// has no descriptor — the format is length-prefixed by a byte, and a
    /// silently truncated name would print the wrong type.
    fn appendNameAndFields(
        self: *Emitter,
        out: *std.ArrayListUnmanaged(u8),
        name: []const u8,
        fields: []const []const u8,
        refs: ?[]const ast.TypeRef,
        /// A record's `i64` field holds a cell (`l`, `u` for a `u64`); a
        /// variant's payload holds only an `i32` word, the one an `i64` slot
        /// is ever given.
        record: bool,
        /// The type parameters of the declaration: a field written as one (or
        /// as an array or tuple of one) is shaped `G`, its construction site
        /// recording the shape, see `genericShapes`.
        generics: []const ast.GenericParam,
    ) anyerror!void {
        const a = self.arena();
        const shown = self.printed_names.get(name) orelse displayTypeName(name);
        if (shown.len > 255 or fields.len > 255) return error.NameTooLong;
        try out.append(a, @intCast(shown.len));
        try out.appendSlice(a, shown);
        try out.append(a, @intCast(fields.len));
        for (fields, 0..) |fname, i| {
            if (fname.len > 255) return error.NameTooLong;
            try out.append(a, @intCast(fname.len));
            try out.appendSlice(a, fname);
            const tref: ?ast.TypeRef = if (refs) |rs| (if (i < rs.len) rs[i] else null) else null;
            const wide: ?u8 = if (tref) |t| switch (t) {
                .named => |n| i64CellCode(n),
                else => null,
            } else null;
            if (record) if (wide) |c| {
                try out.append(a, c);
                continue;
            };
            if (tref) |t| if (isGenericField(t, generics)) {
                try out.append(a, 'G');
                continue;
            };
            try out.appendSlice(a, try self.fieldShape(tref));
        }
    }

    /// Whether a declaration's field is printed by the shape its construction
    /// site records (`G`, `genericShapes`): written as one of its type
    /// parameters, or as an array or a tuple holding one (`items: Array<T>`,
    /// `pairs: #(T, i32)[]`). The declaration alone has one descriptor for
    /// every instantiation, so `Q(items: [7])` and `Q(items: ["a"])` differ
    /// only in what each value says. A `?T`, a function and a record or enum
    /// argument (`Box<T>`) keep the declared shape: a `?T` is always a box, a
    /// record names itself in its header.
    fn isGenericField(t: ast.TypeRef, generics: []const ast.GenericParam) bool {
        return switch (t) {
            .named => |n| isGenericParamName(n, generics, &.{}),
            .array => |inner| mentionsGeneric(inner.*, generics),
            .tuple_, .labeledTuple => mentionsGeneric(t, generics),
            .generic => |g| g.args.len == 1 and std.mem.eql(u8, g.name, "Array") and mentionsGeneric(g.args[0], generics),
            else => false,
        };
    }

    /// Whether `t` names one of `generics` anywhere inside it.
    fn mentionsGeneric(t: ast.TypeRef, generics: []const ast.GenericParam) bool {
        return switch (t) {
            .named => |n| isGenericParamName(n, generics, &.{}),
            .array, .optional => |inner| mentionsGeneric(inner.*, generics),
            .tuple_ => |elems| for (elems) |el| {
                if (mentionsGeneric(el, generics)) break true;
            } else false,
            .labeledTuple => |lt| for (lt.elems) |el| {
                if (mentionsGeneric(el, generics)) break true;
            } else false,
            .generic => |g| for (g.args) |el| {
                if (mentionsGeneric(el, generics)) break true;
            } else false,
            .function => |f| mentionsGeneric(f.returnType.*, generics) or for (f.params) |el| {
                if (mentionsGeneric(el, generics)) break true;
            } else false,
            else => false,
        };
    }

    /// The shapes of the arguments of a generic declaration's `G` fields
    /// (`isGenericField`), one after another in field order — each the code
    /// `$__print_shaped_raw` walks, self-delimiting — interned, and its
    /// address stored after the fields of the value: `$__print_tagged_raw`
    /// reads the next one at each `G`. A field with no argument here (a
    /// default) is a word, `i`.
    fn genericShapes(self: *Emitter, cc: anytype, names: []const []const u8, refs: []const ast.TypeRef, generics: []const ast.GenericParam) anyerror!u32 {
        var out: std.ArrayListUnmanaged(u8) = .empty;
        for (names, 0..) |fname, i| {
            if (i >= refs.len or !isGenericField(refs[i], generics)) continue;
            const arg = self.argForField(cc.args, fname, i) orelse {
                try out.append(self.arena(), 'i');
                continue;
            };
            try out.appendSlice(self.arena(), try self.valueShapeOf(arg.value.*));
        }
        const seg = try self.internString(out.items);
        return seg.offset + 4;
    }

    /// The `$__print_shaped_raw` code a field's declared type takes. An
    /// unknown type is `i`, which is what the numeric printer answered for
    /// every field before this existed.
    fn fieldShape(self: *Emitter, t: ?ast.TypeRef) anyerror![]const u8 {
        const tref = t orelse return "i";
        // Decision 332 — a `?bigint` field is its block's address or `0`.
        if (tref == .optional and tref.optional.* == .named and std.mem.eql(u8, tref.optional.named, "bigint")) {
            self.builder().helpers.require(.bigint);
            return "?n";
        }
        if (try self.typeRefShape(tref)) |shape| return shape;
        // An enum with a payload variant is a pointer to a tagged `[tag, …]`
        // cell, every value of it — a unit variant too — carrying its
        // variant's descriptor, so it prints by its header like a record. An
        // optional field prints by its payload's shape behind `?` / `!`
        // (`optElemShape`). Both fell to `i`, so `place: Place.Here` and
        // `maybe: ?Target` printed the cell's address.
        switch (tref) {
            .named => |n| if (self.enums.contains(n) and !self.isAllUnitEnum(n)) return "T",
            .optional => |inner| {
                if (inner.* == .named and self.enums.contains(inner.named)) {
                    // `?Color` boxes the ordinal (`optInfoOfTypeRef`): `!`
                    // reads the box, then the enum's own names.
                    if (self.isAllUnitEnum(inner.named)) return try std.fmt.allocPrint(self.arena(), "!{s}", .{try self.unitEnumShape(inner.named)});
                    return "?T";
                }
                if (self.optInfoOfTypeRef(tref)) |oi| if (try self.optElemShape(oi, null)) |sh| return sh;
            },
            else => {},
        }
        const code = scalarCode(tref) orelse 'i';
        return switch (code) {
            's' => "s",
            'b' => "b",
            'f' => "f",
            else => "i",
        };
    }

    /// The enum that declares `vname`, when exactly one does.
    fn enumOfVariant(self: *Emitter, vname: []const u8) ?[]const u8 {
        var found: ?[]const u8 = null;
        var it = self.enums.iterator();
        while (it.next()) |e| {
            for (e.value_ptr.*) |v| {
                if (!std.mem.eql(u8, v.name, vname)) continue;
                if (found != null) return null;
                found = e.key_ptr.*;
                break;
            }
        }
        return found;
    }

    /// Whether a record this module knows declares a field `name` held in a
    /// cell — a float or an `i64`.
    fn someFieldIsFloat(self: *Emitter, name: []const u8) bool {
        var it = self.records.iterator();
        while (it.next()) |entry| {
            if (self.fieldCellIn(entry.key_ptr.*, name) != .none) return true;
        }
        return false;
    }

    fn uniqueFieldOffset(self: *Emitter, name: []const u8) ?u32 {
        var found: ?u32 = null;
        var it = self.records.iterator();
        while (it.next()) |entry| {
            for (entry.value_ptr.*, 0..) |fname, idx| {
                if (!std.mem.eql(u8, fname, name)) continue;
                const off: u32 = @intCast(idx * 4);
                if (found) |existing| {
                    if (existing != off) return null;
                } else {
                    found = off;
                }
                break;
            }
        }
        return found;
    }

    /// Returns N for a tuple-accessor member of the form `_N` (e.g. `_0`).
    fn tupleIndex(member: []const u8) ?u32 {
        // `t._N` and the bare `t.N` both read element N.
        const digits = if (member.len > 0 and member[0] == '_') member[1..] else member;
        if (digits.len == 0) return null;
        var n: u32 = 0;
        for (digits) |c| {
            if (!std.ascii.isDigit(c)) return null;
            n = n * 10 + (c - '0');
        }
        return n;
    }

    // ── strings in linear memory ──────────────────────────────────────────────
    //
    // Strings are length-prefixed buffers: a value is a pointer to a 4-byte i32
    // length word immediately followed by the raw bytes. Literals are interned in
    // the data section with this layout; `.len` loads the prefix and `.slice`
    // copies a sub-range into a fresh prefixed buffer, so length travels with the
    // string at runtime (it no longer has to be a compile-time constant).
    // Concatenation and comparison of literals lower to helper calls (offsets +
    // compile-time lengths), demonstrating `memory.copy` and a byte-compare loop;
    // the concat result is itself a valid prefixed string, so `.len`/`.slice`
    // compose on it. Concat/compare of non-literal operands is not detected here
    // (codegen is untyped, so `a + b` on string variables lowers as numeric add).

    fn isStrLit(e: ast.Expr) ?[]const u8 {
        return switch (e) {
            .literal => |lit| switch (lit.kind) {
                .stringLit => |s| s,
                else => null,
            },
            else => null,
        };
    }

    /// True when `e` is known to evaluate to a length-prefixed string pointer:
    /// a literal, a local/param declared or inferred as `string`, a `.slice`
    /// result, or a `+` chain over such operands. Drives string `==`, `+` and
    /// `@print`, none of which may go through the numeric path.
    fn isStringExpr(self: *Emitter, e: ast.Expr) bool {
        if (asyncBlockValue(e)) |a| return self.isStringExpr(a);
        if (optOperatorParts(e)) |op| if (op.bang) return if (self.optInfoOf(op.cond.*)) |oi| oi.str else false;
        return switch (e) {
            .literal => |lit| switch (lit.kind) {
                .stringLit => true,
                else => false,
            },
            .identifier => |id| switch (id.kind) {
                .ident => |n| blk: {
                    if (self.param_shape) |ps| for (ps.names, 0..) |pn, i| {
                        if (std.mem.eql(u8, pn, n)) break :blk ps.str[i];
                    };
                    break :blk self.str_locals.contains(self.resolveName(n)) or self.str_globals.contains(self.resolveName(n));
                },
                .identAccess => |ia| blk: {
                    // A **tuple element** whose type is a string: `t._1`, and a
                    // label the checker resolved to its position
                    // (`row.name` → `row._0`). The tuple's shape was known to
                    // `printShapeOf` and to nothing else, so `@print` fell
                    // through to the numeric printer and answered the element's
                    // heap address — `256` where it means `x`.
                    if (self.tupleElemShapeOf(e) catch null) |el| break :blk std.mem.eql(u8, el, "s");
                    // A record field declared `string`.
                    const rty = self.recordTypeOfExpr(ia.receiver.*) orelse break :blk false;
                    const ft = self.fieldTypeIn(rty, ia.member) orelse break :blk false;
                    break :blk std.mem.eql(u8, self.recvTypeArg(ia.receiver.*, rty, ft), "string");
                },
                else => false,
            },
            .binaryOp => |bin| switch (bin.op) {
                .add => self.isStringExpr(bin.lhs.*) or self.isStringExpr(bin.rhs.*),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.isStringExpr(inner.*),
                // A `case`/`if` yielding strings is itself a string. Without
                // this, `@print(case x { 0 -> "zero"; … })` went through
                // `$__print_i32` and printed the *pointer* (`256`).
                .case => |c| blk: {
                    // A catch-all arm's binder over a record subject reads
                    // the record's fields (`_ { o -> o.label; }`): typed by
                    // the subject while its arm is asked, as `lowerArmBody`
                    // binds it.
                    const subj_rec: ?[]const u8 = if (c.subjects.len == 1) self.recordTypeOfExpr(c.subjects[0]) else null;
                    var any = false;
                    for (c.arms) |arm| {
                        if (self.exprTail(arm.body) == .terminated) continue;
                        // An arm's block that ends in a `return` / `throw`
                        // answers nothing to the `case` (decision 525).
                        if (armLambda(arm.body)) |lam| if (lam.body.len > 0 and self.bodyTail(lam.body) == .terminated) continue;
                        const binder: ?[]const u8 = if (subj_rec != null and arm.pattern == .wildcard) (if (armLambda(arm.body)) |lam| (if (lam.params.len == 1) lam.params[0] else null) else null) else null;
                        const prev: ?[]const u8 = if (binder) |n| self.local_types.get(n) else null;
                        if (binder) |n| self.local_types.put(n, subj_rec.?) catch {};
                        const is_str = self.armIsString(arm.body);
                        if (binder) |n| {
                            if (prev) |t| self.local_types.put(n, t) catch {} else _ = self.local_types.remove(n);
                        }
                        if (!is_str) break :blk false;
                        any = true;
                    }
                    break :blk any;
                },
                else => false,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| blk: {
                    const els = i.else_ orelse break :blk false;
                    // An optional-binding `if` — what `a ?? b` is written as
                    // — has both arms of one type by construction, and the
                    // payload arm reads a binder nothing typed, so the default
                    // arm alone proves it. Requiring both made `["x", "yz"]
                    // .at(1) ?? "none"` print the string's address at exit 0.
                    if (i.binding != null) break :blk self.bodyIsString(i.then_) or self.bodyIsString(els);
                    break :blk self.bodyIsString(i.then_) and self.bodyIsString(els);
                },
                // Both sides have the payload's type; either one proves it.
                .tryCatch => |tc| self.isStringExpr(tc.handler.*) or self.resultOfStringCall(tc.expr.*),
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (self.primAssocHelper(cc) != null) break :blk true;
                    if (self.isTupleToString(cc)) break :blk true;
                    if (self.primKindAt(cc, c.loc)) |k| break :blk self.primRes(k, cc) == .str;
                    if (isStrSlice(cc) and !self.answeredByValue(cc, c.loc)) break :blk true;
                    // `s[i]` / `s[a..b]` (decision 30) answer a string; an
                    // array index answers a string when its elements are ones.
                    if (self.indexArgs(cc)) |ix| break :blk if (self.isStringExpr(ix.recv))
                        true
                    else
                        self.isArrayExpr(ix.recv) and !ix.is_slice and self.elemKindOf(ix.recv) == .str;
                    // `o.unwrapOr(d)` / `r.unwrapOr(d)`: the payload and
                    // the default share one type, and the default says it.
                    if (isUnwrapOr(cc)) break :blk self.isStringExpr(cc.args[1].value.*);
                    if (cc.is_builtin) break :blk false;
                    if (self.genericResultArg(cc)) |a| break :blk self.isStringExpr(a);
                    if (cc.calleeExpr) |ce| if (inlineFnExpr(ce.*)) |inl| break :blk self.inlineCallIsString(inl.kind, cc);
                    if (cc.receiver == null and self.locals.contains(cc.callee)) {
                        if (self.closure_locals.get(cc.callee)) |li| break :blk self.closureCallIsString(li, cc);
                    } else if (cc.receiver == null and cc.calleeExpr == null) if (self.global_lambdas.get(cc.callee)) |gl| {
                        // `g()` over a module-level `val g = { -> "x" }`.
                        const flags = self.arena().alloc(bool, gl.params.len) catch break :blk false;
                        for (flags, 0..) |*f, i| f.* = i < cc.args.len and self.isStringExpr(cc.args[i].value.*);
                        const saved = self.param_shape;
                        defer self.param_shape = saved;
                        self.param_shape = .{ .names = gl.params, .str = flags };
                        break :blk self.bodyIsString(gl.body);
                    };
                    // `lam.value("e")` over a constructor-stored lambda.
                    // Only a yes: the field's declared type may say more than
                    // the body judged alone (`v.tagOf(e)` over `fn(e: El) -> string`).
                    if (cc.receiver) |r| if (self.fieldClosureOf(r.*, cc.callee)) |li| if (self.closureCallIsString(li, cc)) break :blk true;
                    if (self.resolvedCallSym(cc, c.loc)) |sym| {
                        if (self.str_fns.contains(sym)) break :blk true;
                    }
                    // A call through a record literal's lambda field — a
                    // behavior literal's method — is a string when the
                    // lambda's body is, its parameters shaped by the call's
                    // arguments (the receiver first for a `self` method).
                    if (self.fieldLambdaCallIsString(cc)) break :blk true;
                    // A function value whose declared type returns a string:
                    // `greeter("a")("b")`, or `f("b")` after `val f =
                    // greeter("a")`. Without it the result printed as the
                    // string's heap address at exit 0.
                    if (self.valueCallTypeRef(cc)) |t| break :blk isStringTypeRef(t);
                    break :blk false;
                },
                else => false,
            },
            .useHook => |uh| self.isStringExpr(uh.kind.inner.*),
            .jump => |j| switch (j.kind) {
                .try_ => |v| if (v) |x| self.resultOfStringCall(x.*) else false,
                // `await t` is `t` here (the eager `@Task`).
                .await_ => |a| self.isStringExpr(a.*),
                else => false,
            },
            else => false,
        };
    }

    /// `f()` where `f` is declared `-> @Result<string, …>`.
    fn resultOfStringCall(self: *Emitter, e: ast.Expr) bool {
        return switch (e) {
            // A local or a record field declared `@Result<string, …>`.
            .identifier => resultOfString(self.typeRefOf(e) orelse return false),
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    const sym = self.calleeSymbol(cc, c.loc) orelse self.resolvedCallSym(cc, c.loc) orelse break :blk false;
                    break :blk self.result_str_fns.contains(sym);
                },
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.resultOfStringCall(inner.*),
                else => false,
            },
            .jump => |j| switch (j.kind) {
                .await_ => |a| self.resultOfStringCall(a.*),
                else => false,
            },
            .useHook => |uh| self.resultOfStringCall(uh.kind.inner.*),
            else => false,
        };
    }

    /// What a `@Result` value's payloads are: `ok_str` / `err_str` for the
    /// shapes recovered from an expression alone, and — when a declared type
    /// names them — the payload types themselves, so a `case` binder is typed
    /// in full (a string, an array, a record, another `@Result`).
    const ResultShape = struct {
        ok_str: bool = false,
        err_str: bool = false,
        ok: ?ast.TypeRef = null,
        err: ?ast.TypeRef = null,
    };

    fn resultShapeOfTypeRef(t: ast.TypeRef) ?ResultShape {
        return switch (eagerTypeRef(t)) {
            .generic => |g| if (std.mem.endsWith(u8, g.name, "Result") and g.args.len == 2) .{
                .ok_str = isStringTypeRef(g.args[0]),
                .err_str = isStringTypeRef(g.args[1]),
                .ok = g.args[0],
                .err = g.args[1],
            } else null,
            else => null,
        };
    }

    /// The cell a `@Result` payload of type `t` is held in — an `f64` or a
    /// 64-bit integer does not fit the `[tag, payload]` pair's word, so the
    /// payload is the address of its 8-byte cell (`$__box_f64` /
    /// `$__box_i64`), as a `?f64`'s box is; `.none` for a word.
    fn resultPayloadCell(t: ast.TypeRef) Cell {
        return Cell.of(watType(t));
    }

    /// The cell of the `Ok` payload of the `@Result` `e` answers, when its
    /// shape is known.
    /// While a closure's tail is read before its body is lowered, its one
    /// parameter holds `t`'s cell; answers the name to unbind, null when the
    /// parameter was bound already or `t` is a word.
    fn bindLambdaParamType(self: *Emitter, lam: anytype, t: ?ast.TypeRef) ?[]const u8 {
        if (lam.params.len == 0) return null;
        const cell = resultPayloadCell(t orelse return null);
        if (cell == .none) return null;
        const name = lam.params[0];
        if (self.locals.contains(name)) return null;
        self.locals.put(name, cell.ty()) catch return null;
        return name;
    }

    fn unbindLambdaParamType(self: *Emitter, bound: ?[]const u8) void {
        if (bound) |n| _ = self.locals.remove(n);
    }

    fn resultOkCell(self: *Emitter, e: ast.Expr) Cell {
        const sh = self.resultShapeOf(e) orelse return .none;
        return resultPayloadCell(sh.ok orelse return .none);
    }

    /// The payload type a `try <call>` binds — the `Ok` type of the call's
    /// declared `@Result` — or null for anything else.
    fn tryPayloadTypeRef(self: *Emitter, e: ast.Expr) ?ast.TypeRef {
        const inner = switch (e) {
            .jump => |j| switch (j.kind) {
                .try_ => |v| v orelse return null,
                else => return null,
            },
            else => return null,
        };
        const shape = self.resultShapeOf(inner.*) orelse return null;
        return shape.ok;
    }

    fn resultShapeOf(self: *Emitter, e: ast.Expr) ?ResultShape {
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| self.result_shape_locals.get(self.resolveName(n)) orelse
                    resultShapeOfTypeRef(self.typeRefOf(e) orelse return null),
                // A record field declared `@Result<…>`.
                else => resultShapeOfTypeRef(self.typeRefOf(e) orelse return null),
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    // `r.map({ v -> … })` answers what the closure's tail holds.
                    // Its parameter is the receiver's `Ok` payload while the
                    // tail is read (`{ n -> n * 3l }` over a `@Result<i64, …>`).
                    if (cc.is_builtin and std.mem.eql(u8, cc.callee, "__bp_result_map") and cc.args.len == 2) {
                        const inner = self.resultShapeOf(cc.args[0].value.*) orelse ResultShape{};
                        const le = self.resultClosureArg(cc.args[1].value) orelse break :blk null;
                        const bound = self.bindLambdaParamType(le.function.kind, inner.ok);
                        defer self.unbindLambdaParamType(bound);
                        const tail = self.lambdaTailType(le.function.kind.body);
                        var out = inner;
                        out.ok_str = false;
                        out.ok = if (Cell.of(tail) == .f64) .{ .named = "f64" } else if (Cell.of(tail) == .i64) .{ .named = "i64" } else null;
                        // A GC module reads the mapped payload by its type
                        // (`gcResultMap` boxes it by what the body answers).
                        if (self.mode == .gc and out.ok == null) out.ok = switch (tail) {
                            .bool => .{ .named = "bool" },
                            .i32 => .{ .named = "i32" },
                            .ref => |k| switch (k) {
                                .str => blk2: {
                                    out.ok_str = true;
                                    break :blk2 .{ .named = "string" };
                                },
                                .record => |n| .{ .named = n },
                                else => null,
                            },
                            else => null,
                        };
                        break :blk out;
                    }
                    // `r.flatMap({ v -> … })` answers the `@Result` its closure's tail does.
                    if (cc.is_builtin and std.mem.eql(u8, cc.callee, "__bp_result_flatMap") and cc.args.len == 2) {
                        const inner = self.resultShapeOf(cc.args[0].value.*) orelse ResultShape{};
                        const le = self.resultClosureArg(cc.args[1].value) orelse break :blk null;
                        const body = le.function.kind.body;
                        if (body.len == 0) break :blk null;
                        const last = body[ast.lastRealIndex(body)].expr;
                        const tail: ast.Expr = switch (last) {
                            .jump => |j| switch (j.kind) {
                                .@"return" => |r| (r orelse break :blk null).*,
                                else => break :blk null,
                            },
                            else => last,
                        };
                        const bound = self.bindLambdaParamType(le.function.kind, inner.ok);
                        defer self.unbindLambdaParamType(bound);
                        break :blk self.resultShapeOf(tail);
                    }
                    // Decision 346 — `b.toUtf8()` answers `@Result<string, string>`.
                    if (cc.receiver != null) if (self.primKindAt(cc, c.loc)) |k| if (k == .bytes)
                        break :blk resultShapeOfTypeRef(self.typeRefOf(e) orelse break :blk null);
                    // A generic function whose thunk argument binds its type
                    // parameter (`failure.attempt(…)`): the shape of its return
                    // with that written in (a task's value for `attemptTask`).
                    if (cc.receiver == null or self.isNamespaceReceiver(cc)) if (self.genericRetByFnArg(cc) catch null) |t| {
                        if (resultShapeOfTypeRef(taskValueTypeRef(t) orelse t)) |sh| break :blk sh;
                    };
                    if (self.calleeSymbol(cc, c.loc)) |sym| break :blk self.result_shape_fns.get(sym);
                    // A primitive's `default fn` (`"1.5".parseFloat()`): its
                    // copy's declared return.
                    // Only one declared `-> @Result<…>`: asking materialises
                    // the copy, and a default the backend lowers natively
                    // (`xs.slice`) must not be.
                    if (cc.receiver != null) if (self.primKindAt(cc, c.loc)) |k| if (self.primDefaultOf(k, cc.callee)) |pd| {
                        if (resultShapeOfTypeRef(pd.method.returnType orelse break :blk null) == null) break :blk null;
                        const sym = self.ensurePrimDefault(k, pd, cc.receiver.?.*) catch break :blk null;
                        if (self.result_shape_fns.get(sym)) |sh| break :blk sh;
                        break :blk resultShapeOfTypeRef(self.fn_ret_typerefs.get(sym) orelse break :blk null);
                    };
                    break :blk null;
                },
                else => null,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.resultShapeOf(inner.*),
                else => null,
            },
            .jump => |j| switch (j.kind) {
                .await_ => |a| self.resultShapeOf(a.*),
                else => null,
            },
            .useHook => |uh| self.resultShapeOf(uh.kind.inner.*),
            // `async { return f(); }` is the task `f` answers.
            .function => if (asyncBlockValue(e)) |v| self.resultShapeOf(v) else null,
            else => null,
        };
    }

    /// `@Result<string, E>`.
    fn resultOfString(t: ast.TypeRef) bool {
        return switch (eagerTypeRef(t)) {
            .generic => |g| std.mem.endsWith(u8, g.name, "Result") and g.args.len > 0 and isStringTypeRef(g.args[0]),
            else => false,
        };
    }

    /// Whether a body with no declared return type returns a string: some
    /// `return <e>` or its tail is one, judged on literals and fn results
    /// (locals are not known yet).
    fn bodyReturnsString(self: *Emitter, body: []const ast.Stmt) bool {
        if (body.len == 0) return false;
        for (body) |st| switch (st.expr) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |v| if (self.isStringExpr(v.*)) return true,
                else => {},
            },
            else => {},
        };
        return self.isStringExpr(body[ast.lastRealIndex(body)].expr);
    }

    /// `val #(a, b) = #(12, "hello")`: an element of a tuple literal lends its
    /// shape to the name bound to it.
    /// A tuple that is not a literal — a local bound to one — says what its
    /// element `i` is by its print shape: `val #(a, b) = t` over a
    /// `#(1.1, "a")` printed `b` as the string's address (`264`) at exit 0.
    fn noteTupleElemByShape(self: *Emitter, name: []const u8, value: ast.Expr, i: usize) !void {
        const sh = (try self.printShapeOf(value)) orelse return;
        const el = tupleShapeElem(sh, @intCast(i)) orelse return;
        try self.noteTupleElemLocal(name, el);
    }

    /// The binder of one element of the array `arr`, when the element is a
    /// tuple or an array: its print shape, the one its reads go by.
    fn noteElemShape(self: *Emitter, elem: []const u8, arr: ast.Expr) !void {
        const sh = (try self.printShapeOf(arr)) orelse return;
        if (sh.len > 1 and sh[0] == '[' and (sh[1] == '(' or sh[1] == '[')) try self.noteTupleElemLocal(elem, sh[1..]);
    }

    /// The cell element `i` of the tuple `value` holds in its slot: a float's
    /// `f64`, a 64-bit integer's `i64`, `.none` for a word.
    fn tupleElemCell(self: *Emitter, value: ast.Expr, i: usize) !Cell {
        const sh = (try self.printShapeOf(value)) orelse return .none;
        const el = tupleShapeElem(sh, @intCast(i)) orelse return .none;
        return shapeCell(el);
    }

    fn noteTupleElemShape(self: *Emitter, name: []const u8, value: ast.Expr, i: usize) !void {
        const elems = switch (value) {
            .collection => |col| switch (col.kind) {
                .tupleLit => |tl| tl.elems,
                else => return self.noteTupleElemByShape(name, value, i),
            },
            else => return self.noteTupleElemByShape(name, value, i),
        };
        if (i >= elems.len) return;
        if (self.isStringExpr(elems[i])) try self.str_locals.put(name, {});
        if (self.isBoolExpr(elems[i])) try self.bool_locals.put(name, {});
    }

    /// Whether a `case` ARM answers a string. A BRACE arm — `case x { 5 {
    /// "five" } … }` — parses its body as a parameterless block, which arrives
    /// here as a `.function`, and a lambda VALUE is a closure pointer, so only
    /// this position may look through one: its value is its last statement's.
    /// Only the ARROW spelling (`5 -> "five";`) was a string before, so the
    /// same program answered `five` one way and the pointer `256` the other,
    /// at exit 0, where commonJS and erlang answer `five` for both.
    fn armIsString(self: *Emitter, body: ast.Expr) bool {
        return switch (body) {
            // An arm's block, with or without its binder (`_ { n -> "max " +
            // n.toString(); }`): the binder's arm printed its string's
            // address once the case was a `val`'s value.
            .function => |f| (f.kind.params.len == 0 or armLambda(body) != null) and self.bodyIsString(f.kind.body),
            else => self.isStringExpr(body),
        };
    }

    /// Whether a statement list yields a string (its last statement does).
    fn bodyIsString(self: *Emitter, body: []const ast.Stmt) bool {
        if (body.len == 0) return false;
        const last = body[ast.lastRealIndex(body)].expr;
        // `{ return s + "x"; }` answers what the `return` carries.
        if (last == .jump and last.jump.kind == .@"return") return if (last.jump.kind.@"return") |v| self.isStringExpr(v.*) else false;
        return self.isStringExpr(last);
    }

    /// `a + b` on strings → a fresh length-prefixed buffer. Both operands are
    /// plain pointers, so this works for runtime values as well as literals.
    fn lowerStrConcat(self: *Emitter, a: ast.Expr, b: ast.Expr) anyerror!void {
        try self.lowerConcatOperand(a);
        try self.lowerConcatOperand(b);
        try self.emit(self.builder().helper(.str_concat));
    }

    /// One operand of a string `+`. A non-string operand is rendered as text
    /// first — its decimal digits, or `true`/`false` — the rule the erlang
    /// backend's E2 fix follows (`integer_to_binary/1`). It used to be added as
    /// if it were a string pointer.
    fn lowerConcatOperand(self: *Emitter, e: ast.Expr) anyerror!void {
        // Decision 332 — a `bigint` joins a string as its digits.
        if (self.isOptBigintExpr(e))
            return self.refuse(e.getLoc(), "the wasm backend has no text for a `?bigint` yet", .{});
        if (self.isBigintExpr(e)) {
            try self.lowerValue(e);
            return self.emitStdCall("bigint.toString");
        }
        // A value of an enum is written as `@print` writes it (docs § What
        // `@print` writes): its print, captured into a string. The ordinal's
        // digits, or a payload variant's address, were written before.
        if (self.isEnumValueExpr(e)) return self.lowerCapturedPrint(e);
        // Decision 530 — an optional writes `@print`'s text: `null` when
        // absent (`undefined` was written), its value otherwise.
        if (self.optInfoOf(e) != null) return self.lowerCapturedPrint(e);
        if (self.isStringExpr(e)) return self.lowerValue(e);
        if (self.isBoolExpr(e)) {
            try self.lowerCoerced(e, .i32);
            const str_ty = self.vtOf(Repr.string);
            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emitStrLit("true");
            const then_seq = self.seal(&then_c, .{ .value = str_ty });
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emitStrLit("false");
            const else_seq = self.seal(&else_c, .{ .value = str_ty });
            try self.emit(.{ .@"if" = .{ .result = str_ty, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
            return;
        }
        if (self.wasmTypeOf(e).isFloat()) {
            try self.lowerCoerced(e, .f64);
            try self.emitStdCall("number.floatToString");
            return;
        }
        if (self.wasmTypeOf(e).isI64()) {
            try self.lowerValue(e);
            try self.emitStdCall(if (self.isU64Expr(e)) "number.u64ToString" else "number.i64ToString");
            return;
        }
        // Decision 530 — a record, an array, a tuple, `null`: the text
        // `@print` writes, captured into a string; the value's address was
        // written before.
        if (!self.isKnownInteger(e)) return self.lowerCapturedPrint(e);
        try self.lowerCoerced(e, .i32);
        try self.emitStdCall("number.i32ToString");
    }

    /// `e`'s printed text as a string (`text_capture`): what `@print(e)`
    /// would write, appended to the capture instead of written out.
    fn lowerCapturedPrint(self: *Emitter, e: ast.Expr) anyerror!void {
        const prev = if (self.mode == .gc) try self.gcTemp(Repr.string) else try self.declRes();
        try self.emit(self.builder().helper(.cap_begin));
        try self.emit(.{ .local_set = prev });
        try self.lowerPrintArg(e, false);
        try self.emit(.{ .local_get = prev });
        try self.emit(self.builder().helper(.cap_end));
    }

    /// Whether `e` is a value of an enum this program declares — a unit
    /// variant (an all-unit enum's ordinal), a payload variant's cell, a name,
    /// field or call declared as one, a `?` of an enum with payloads.
    fn isEnumValueExpr(self: *Emitter, e: ast.Expr) bool {
        if (self.unitEnumOf(e) != null) return true;
        if (self.payloadEnumOfName(e) != null or self.optPayloadEnumOf(e) != null) return true;
        if (self.enumValueOf(e) != null) return true;
        if (self.namedShapeOf(e)) |ns| if (ns == .variant) return true;
        const t = self.typeRefOf(e) orelse return false;
        return t == .named and self.enums.contains(t.named);
    }

    /// A `recv.slice(...)` method call. Codegen is untyped, so a `slice` with a
    /// receiver (and not a builtin) is treated as a string slice.
    fn isStrSlice(cc: anytype) bool {
        return cc.receiver != null and !cc.is_builtin and std.mem.eql(u8, cc.callee, "slice");
    }

    /// `s.slice(start, end)` → a fresh length-prefixed buffer holding the bytes
    /// `[start, end)` of the receiver. A missing `end` slices to the source's
    /// length. Leaves a pointer to the new string on the stack.
    fn lowerStrSlice(self: *Emitter, cc: anytype) anyerror!void {
        try self.lowerExpr(cc.receiver.?.*);
        if (cc.args.len > 0)
            try self.lowerExpr(cc.args[0].value.*)
        else
            try self.emit(zero);
        if (cc.args.len > 1 and !isNullLit(cc.args[1].value.*)) {
            try self.lowerSliceEnd(cc.args[1].value.*);
        } else {
            // No end argument — or a written `null` (`s.slice(2, null)`, what
            // `s[2..]` passes): slice to the end. std-wasm's `text.slice` clamps an
            // end past the codepoint count to it, so "to the end" is the
            // largest i32. `null` lowered as `0` once made the end fall
            // before the start and the byte cutter read out of bounds.
            try self.emit(try self.constInt(std.math.maxInt(i32)));
        }
        // Decision 240: the bounds are codepoints, normalised as `slice`
        // normalises them (negative from the end, clamped).
        try self.emitStdCall("text.slice");
    }

    /// A slice's `end: ?i32` that is not the literal `null`: a plain `i32`, or
    /// an optional whose absence means "to the end" — the largest i32, which
    /// std-wasm's `text.slice` and `array.slice` both clamp.
    fn lowerSliceEnd(self: *Emitter, end: ast.Expr) anyerror!void {
        const oi = self.optInfoOf(end) orelse return self.lowerCoerced(end, .i32);
        if (!oi.boxed) return self.lowerCoerced(end, .i32);
        const tmp = try self.memName(self.nextMem());
        try self.lowerCoerced(end, .i32);
        try self.emit(.{ .local_tee = tmp });
        try self.emit(opOf(.i32, "eqz"));
        var then_c: Capture = .{};
        self.open(&then_c);
        try self.emit(try self.constInt(std.math.maxInt(i32)));
        const then_seq = self.seal(&then_c, .{ .value = .i32 });
        var else_c: Capture = .{};
        self.open(&else_c);
        try self.emit(.{ .local_get = tmp });
        try self.emitC(.{ .load = .{} }, "slice end");
        const else_seq = self.seal(&else_c, .{ .value = .i32 });
        try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
    }

    /// `a == b` / `a != b` on strings → byte comparison via `$__str_eq`. The
    /// old lowering compared the two *pointers* with `i32.eq`, which only ever
    /// agreed with the other backends because identical literals are interned
    /// at the same address.
    fn lowerStrEq(self: *Emitter, a: ast.Expr, b: ast.Expr, negate: bool) anyerror!void {
        try self.lowerValue(a);
        try self.lowerValue(b);
        try self.emit(self.builder().helper(.str_eq));
        if (negate) try self.emit(opOf(.i32, "eqz"));
    }

    fn lowerLoop(self: *Emitter, lp: anytype) anyerror!void {
        if (lp.generator != null) return self.lowerGeneratorLoop(lp);
        if (self.mode == .gc and !lp.condition and self.isGenExpr(lp.iter.*)) return self.lowerGenFor(lp);
        // Every other loop is a statement (decision 105); inside a generator
        // fn its `yield`s feed the fn's accumulator (`renderAccumulatingBody`).
        const result: ?[]const u8 = null;
        if (lp.condition) return self.lowerConditionLoop(lp, result);
        switch (lp.iter.*) {
            .collection => |col| switch (col.kind) {
                .range => |r| {
                    try self.lowerRangeLoop(lp.params, lp.body, r, result, lp.label);
                    return;
                },
                else => {},
            },
            else => {},
        }
        if (self.isArrayExpr(lp.iter.*)) return self.lowerCollectionLoop(lp, result);
        // An iterable this backend cannot tell is an array — a lambda-backed
        // iterator, an opaque value — has no wasm lowering, and it is REFUSED:
        // the no-op it used to be ran the body zero times at exit 0, which is
        // how `for (try items(n))` summed nothing and printed `6` for `9`.
        return self.refuseUnlessTemplate(lp.iter.*.getLoc(), "the wasm backend walks an array or a range; nothing shows this iterable is one", .{});
    }

    /// `#[@generator] loop { … }` (decision 105) — eager on wasm: the body
    /// runs as `loop { … }` does inside a block of its own, each `yield v`
    /// appends to a fresh array, and the expression is the array:
    ///
    ///     (block $__gen<n> (block $__break (loop $__continue …)))  local.get $__yield<n>
    ///
    /// `break <v>` appends and branches to `$__gen<n>` from any loop depth; a
    /// bare `break` leaves the loop, which falls out of the block too. A
    /// captured `var` is this function's local, so the loop's reassignments
    /// are read after it.
    fn lowerGeneratorLoop(self: *Emitter, lp: anytype) anyerror!void {
        // Decision 105 (144 B-128) — an `iter` loop in a GC module is a
        // generator machine (§ generators); a stream stays eager.
        if (self.mode == .gc) return self.lowerGenLoopValue(lp);
        const ra = self.reg_arena.allocator();
        const n = self.loop_seq;
        self.loop_seq += 1;
        const tgt = try std.fmt.allocPrint(ra, "__yield{d}", .{n});
        const label = try std.fmt.allocPrint(ra, "__gen{d}", .{n});
        const saved_repr = self.gen_repr;
        defer self.gen_repr = saved_repr;
        if (self.mode == .gc) {
            // The array of what the body yields, of the class its yields
            // have (`yieldElemKind`, which the loop's value is read by).
            self.gen_repr = .{ .ref = .{ .arr = switch (self.yieldElemKind(lp.body)) {
                .i32 => .i32,
                .f64 => .f64,
                .str => .any,
            } } };
            try self.declareLocal(tgt, self.gen_repr);
            try self.emit(zero);
            try self.emit(.{ .array_new_default = self.gcTyIndex(.{ .arr = self.gen_repr.ref.arr }) });
            try self.emit(.{ .local_set = tgt });
        } else {
            try self.declareLocal(tgt, .i32);
            try self.emit(zero);
            try self.emit(self.builder().helper(.arr_new));
            try self.emit(.{ .local_set = tgt });
        }
        const saved_target = self.yield_target;
        const saved_end = self.gen_end;
        const saved_item = self.gen_item;
        self.yield_target = tgt;
        self.gen_end = label;
        self.gen_item = null;
        var c: Capture = .{};
        self.open(&c);
        {
            defer {
                self.yield_target = saved_target;
                self.gen_end = saved_end;
                self.gen_item = saved_item;
            }
            try self.lowerConditionLoop(lp, null);
            try self.emit(.drop);
        }
        const seq = self.seal(&c, .none);
        try self.emit(.{ .block = .{ .kind = .block, .label = label, .body = seq } });
        try self.emit(.{ .local_get = tgt });
    }

    /// `break <v>` in a generator scope: append `v`, then end the scope —
    /// branch out of the annotated loop's block, or, in a generator fn,
    /// return what the body collected.
    fn emitGenBreak(self: *Emitter, v: ast.Expr) anyerror!void {
        try self.emitYield(v);
        try self.emitGenEnd();
    }

    /// End the generator scope without emitting: branch out of the annotated
    /// loop's block, or, in a generator fn, return what the body collected —
    /// a bare `break` at the body's own level (decision 103), and the tail
    /// of `break <v>`.
    fn emitGenEnd(self: *Emitter) anyerror!void {
        if (self.gen_item != null) return self.emitGenMachineEnd();
        if (self.gen_end) |label| {
            try self.emit(.{ .br = label });
            return;
        }
        try self.emitC(.{ .local_get = self.yield_target.? }, "everything the body yielded");
        try self.emitConvert(if (self.mode == .gc) self.gen_repr else .i32, self.cur_result);
        try self.runDefers(0);
        try self.emit(.@"return");
    }

    /// Whether a loop body `yield`s or `break`s with a value — directly or in a
    /// nested `if`/`case` arm, but not inside a nested loop or lambda, whose
    /// values are their own.
    fn bodyYields(body: []const ast.Stmt) bool {
        for (body) |st| if (exprYields(st.expr)) return true;
        return false;
    }

    /// A `yield` anywhere in the body, `if` branches and `case` arms included —
    /// what tells a comprehension (which collects) from a search (whose value
    /// is the one its `break` carries). A nested loop is not descended into:
    /// its `yield`s are its own.
    fn bodyHasYield(body: []const ast.Stmt) bool {
        for (body) |st| if (exprHasYield(st.expr)) return true;
        return false;
    }

    fn exprHasYield(e: ast.Expr) bool {
        return switch (e) {
            .jump => |j| j.kind == .yield,
            .branch => |b| switch (b.kind) {
                .if_ => |i| bodyHasYield(i.then_) or (if (i.else_) |els| bodyHasYield(els) else false),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| exprHasYield(inner.*),
                .case => |c| blk: {
                    // Decision 525 — a block `{ … }` runs its body in place.
                    if (c.isBlock) break :blk bodyHasYield(c.arms[0].body.function.kind.body);
                    for (c.arms) |arm| if (exprHasYield(arm.body)) break :blk true;
                    break :blk false;
                },
                else => false,
            },
            else => false,
        };
    }

    fn exprYields(e: ast.Expr) bool {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                inline .@"break", .yield => |jl| jl.value != null,
                else => false,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| bodyYields(i.then_) or (if (i.else_) |els| bodyYields(els) else false),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| exprYields(inner.*),
                .case => |c| blk: {
                    // Decision 525 — a block `{ … }` runs its body in place.
                    if (c.isBlock) break :blk bodyYields(c.arms[0].body.function.kind.body);
                    for (c.arms) |arm| if (exprYields(arm.body)) break :blk true;
                    break :blk false;
                },
                else => false,
            },
            else => false,
        };
    }

    /// Any `yield` with a value anywhere in a fn body, loops included (not
    /// lambdas) — what makes an `#[@resultGenerator]` body an accumulator.
    fn bodyYieldsDeep(body: []const ast.Stmt) bool {
        for (body) |st| {
            if (exprYields(st.expr)) return true;
            switch (st.expr) {
                .loop => |lp| if (bodyYieldsDeep(lp.body)) return true,
                .jump => |j| switch (j.kind) {
                    .@"return" => |r| if (r) |v| switch (v.*) {
                        .loop => |lp| if (bodyYieldsDeep(lp.body)) return true,
                        else => {},
                    },
                    else => {},
                },
                else => {},
            }
        }
        return false;
    }

    /// `yield v` / `break v` inside a comprehension: append `v` to the
    /// accumulator. A float is appended as its cell (`emitToFloatSlot`).
    fn emitYield(self: *Emitter, v: ast.Expr) anyerror!void {
        if (self.gen_item) |yitem| return self.emitGenYield(v, yitem);
        const tgt = self.yield_target.?;
        if (self.mode == .gc) {
            const ar = self.gen_repr;
            if (!ar.isArrRef()) return self.gcFail("a yield into no known array");
            const cls = ar.ref.arr;
            const er: Repr = switch (cls) {
                .i32 => if (self.isBoolExpr(v)) .bool else .i32,
                .f64 => .f64,
                .any => self.wasmTypeOf(v),
            };
            try self.emit(.{ .local_get = tgt });
            try self.lowerCoerced(v, er);
            if (cls == .any) try self.gcBox(er);
            try self.emit(.{ .call = try self.gcArrPush(cls) });
            try self.emit(.{ .local_set = tgt });
            return;
        }
        try self.emit(.{ .local_get = tgt });
        try self.lowerSlotWord(v);
        try self.emit(self.builder().helper(.arr_push));
        try self.emit(.{ .local_set = tgt });
    }

    // ── decision 105 on wasm: a generator is a resumable state machine ──────
    //
    // 144 B-128, a GC module. An `@Iterator<T>` is a handle, `$gen`
    // (`GcTy.gen`), and each `next` runs the body up to its next `yield`:
    // nothing of it runs before the first, and an endless body is consumed
    // one item at a time. The body is a state machine as an asynchronous
    // function's is (decision 392): the same frame (`$frame<n>`, every local),
    // the same resume guards (`emitStmt`, `lowerCondition`, `guardStart`),
    // each `yield` its suspension point (`emitGenYield`) where a task has its
    // `await`s. An `iter fn` (and a method answering `@Iterator<T>`) lowers to
    //
    //   $g(args) -> (ref $gen)    the handle: the frame, the arguments stored
    //                             in it, the body's `kind`; it runs nothing
    //   $g__body(gen) -> i32      the body, entered again at the frame's
    //                             resume index: `1` when it stopped at a
    //                             `yield` (the item boxed in `value`), `0`
    //                             when it ended
    //
    // and an `iter` loop (a marked lambda `iter { -> … }` is one, decision
    // 553) is a lifted lambda whose body is that machine (`gcEmitLifted`), its
    // closure called where the loop is written answering the handle — as an
    // `async { }` block's answers its task. The handle keeps the lambda's
    // environment (`aux`): a consumer in the function that made it copies the
    // captured locals in before each step and the ones the body assigns back
    // out after it (`genSyncCaptures`), so a captured `var` is one variable
    // on both sides. `$__gen_next(gen)` is the step every consumer calls (`0`
    // once the sequence ended); `$__gen_resume` is the module's dispatch by
    // `kind`: the derived iterators `take`, `drop`, `map`, `filter` (a `$gen`
    // over a `src`), then each body. A stream stays the eager array it was.

    /// The handle a generator machine's body is entered with.
    const gen_handle = "__gen";
    /// The `kind`s of the derived iterators; a body's is `gen_body_base` +
    /// its index in `gen_kinds`.
    const GenKind = enum(u32) { take, drop, map, filter };
    const gen_body_base: u32 = 4;
    /// The fields of `$gen`.
    const gen_fld = struct {
        const state = 0;
        const kind = 1;
        const frame = 2;
        const value = 3;
        const src = 4;
        const aux = 5;
        const left = 6;
    };

    /// What a generator yields: the repr its consumers read the item as, and
    /// the type the program writes for it when one is known.
    const GenItem = struct { repr: Repr, tr: ?ast.TypeRef = null, bool_: bool = false };

    /// The methods over a generator this backend answers.
    const GenMethod = enum {
        take,
        drop,
        map,
        filter,
        to_array,
        next,
        // 144 B-142 — the walks that consume the handle (`forEach`, `some`,
        // `every`, `reduce`): stepped one item at a time, stopped early by
        // `some` / `every` (`lowerGenWalk`).
        for_each,
        some,
        every,
        reduce,

        /// Whether the method answers a derived handle.
        fn derives(m: GenMethod) bool {
            return switch (m) {
                .take, .drop, .map, .filter => true,
                else => false,
            };
        }
    };

    /// `@Iterator<T>`, or `@Stream<T>` — one generator handle in a GC module
    /// (144 B-142: a stream's body is a generator machine too, each `await`
    /// in it run to its end where the step is taken).
    fn isIteratorTypeRef(t: ast.TypeRef) bool {
        return switch (t) {
            .generic => |g| g.is_builtin and g.args.len == 1 and (std.mem.eql(u8, g.name, "Iterator") or std.mem.eql(u8, g.name, "Stream")),
            else => false,
        };
    }

    /// Whether the symbol's call answers a generator handle.
    fn symAnswersGen(self: *Emitter, sym: []const u8) bool {
        const sig = self.fn_sigs.get(sym) orelse return false;
        const r = sig.result orelse return false;
        return r == .ref and r.ref == .gen;
    }

    /// Whether `e` is a generator handle in a GC module: an `iter` loop, a
    /// call answering `@Iterator<T>`, a local holding one, a derived
    /// iterator over one.
    fn isGenExpr(self: *Emitter, e: ast.Expr) bool {
        if (self.mode != .gc) return false;
        return switch (e) {
            .loop => |lp| lp.generator != null,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.isGenExpr(inner.*),
                else => false,
            },
            .identifier => |id| switch (id.kind) {
                .ident => |n| blk: {
                    const rn = self.resolveName(n);
                    const r = self.locals.get(rn) orelse self.global_types.get(rn) orelse break :blk false;
                    break :blk r == .ref and r.ref == .gen;
                },
                // A record's field declared `@Iterator<T>` / `@Stream<T>`.
                .identAccess => if (self.typeRefOf(e)) |t| isIteratorTypeRef(eagerTypeRef(t)) else false,
                else => false,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (self.genMethodOf(e)) |m| break :blk m.derives();
                    if (cc.is_builtin) break :blk false;
                    if (cc.receiver != null) {
                        if (self.recordMethodSym(cc, c.loc)) |sym| break :blk self.symAnswersGen(sym);
                        break :blk false;
                    }
                    if (self.calleeSymbol(cc, c.loc)) |sym| if (self.symAnswersGen(sym)) break :blk true;
                    if (self.locals.contains(cc.callee) or cc.calleeExpr != null) if (self.valueCallTypeRef(cc)) |t| break :blk isIteratorTypeRef(t);
                    break :blk false;
                },
                else => false,
            },
            else => false,
        };
    }

    /// The method a call makes over a generator receiver, or null.
    fn genMethodOf(self: *Emitter, e: ast.Expr) ?GenMethod {
        if (self.mode != .gc) return null;
        if (e != .call or e.call.kind != .call) return null;
        const cc = e.call.kind.call;
        const recv = cc.receiver orelse return null;
        if (cc.is_builtin or cc.calleeExpr != null) return null;
        const argc = cc.args.len + cc.trailing.len;
        const eq = std.mem.eql;
        const m: GenMethod = if (eq(u8, cc.callee, "take") and argc == 1)
            .take
        else if (eq(u8, cc.callee, "drop") and argc == 1)
            .drop
        else if (eq(u8, cc.callee, "map") and argc == 1)
            .map
        else if (eq(u8, cc.callee, "filter") and argc == 1)
            .filter
        else if (eq(u8, cc.callee, "toArray") and argc == 0)
            .to_array
        else if (eq(u8, cc.callee, "next") and argc == 0)
            .next
        else if (eq(u8, cc.callee, "forEach") and argc == 1)
            .for_each
        else if (eq(u8, cc.callee, "some") and argc == 1)
            .some
        else if (eq(u8, cc.callee, "every") and argc == 1)
            .every
        else if (eq(u8, cc.callee, "reduce") and argc == 2)
            .reduce
        else
            return null;
        if (!self.isGenExpr(recv.*)) return null;
        return m;
    }

    /// The item of the `@Iterator<T>` type `t`.
    fn genItemOfTypeRef(self: *Emitter, t: ast.TypeRef) GenItem {
        return .{ .repr = self.reprOf(t), .tr = t, .bool_ = isBoolTypeRef(t) };
    }

    /// What the generator `e` yields, null when nothing here tells.
    fn genItemOf(self: *Emitter, e: ast.Expr) anyerror!?GenItem {
        switch (e) {
            .loop => |lp| return self.genLoopItem(lp.body),
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.genItemOf(inner.*),
                else => {},
            },
            else => {},
        }
        if (plainIdentName(e)) |n| if (self.gen_items.get(self.resolveName(n))) |it| return it;
        if (self.genMethodOf(e)) |m| {
            const cc = e.call.kind.call;
            if (!m.derives() and m != .to_array and m != .next) return null;
            const src = (try self.genItemOf(cc.receiver.?.*)) orelse return null;
            if (m != .map) return src;
            const lam = genMethodLambda(cc) orelse return null;
            if (lam.params.len != 1) return null;
            return self.lambdaAnswerOver(lam.params[0], src, lam.body);
        }
        if (self.typeRefOf(e)) |t0| {
            const t = eagerTypeRef(t0);
            if (isIteratorTypeRef(t)) return self.genItemOfTypeRef(t.generic.args[0]);
        }
        return null;
    }

    const GenLambda = struct { params: []const []const u8, body: []const ast.Stmt };

    /// The lambda a `map` / `filter` over a generator is given, written at
    /// the call (an argument or a trailing block).
    fn genMethodLambda(cc: anytype) ?GenLambda {
        if (cc.trailing.len == 1) return .{ .params = cc.trailing[0].params, .body = cc.trailing[0].body };
        if (cc.args.len != 1) return null;
        const v = cc.args[0].value.*;
        if (v != .function or v.function.kind.syntax != .lambda) return null;
        return .{ .params = v.function.kind.params, .body = v.function.kind.body };
    }

    /// The item a `map`'s lambda answers, its parameter the source's item.
    fn lambdaAnswerOver(self: *Emitter, param: []const u8, src: GenItem, body: []const ast.Stmt) anyerror!?GenItem {
        if (body.len == 0) return null;
        const prev = self.locals.get(param);
        const had_str = self.str_locals.contains(param);
        const had_bool = self.bool_locals.contains(param);
        try self.locals.put(param, src.repr);
        if (src.repr.isStr()) try self.str_locals.put(param, {});
        if (src.bool_) try self.bool_locals.put(param, {});
        defer {
            if (prev) |p| self.locals.put(param, p) catch {} else _ = self.locals.remove(param);
            if (!had_str) _ = self.str_locals.remove(param);
            if (!had_bool) _ = self.bool_locals.remove(param);
        }
        const last = body[ast.lastRealIndex(body)].expr;
        const v: ast.Expr = if (last == .jump and last.jump.kind == .@"return") (if (last.jump.kind.@"return") |r| r.* else return null) else last;
        return self.genValueItem(v, &.{}, 0);
    }

    /// What an `iter` loop yields, read off its first `yield v` / `break v`
    /// where it is written (the lifted body is lowered after the function
    /// that consumes it): the value's repr when every name it reads is known
    /// here, or a binding of the body names it.
    fn genLoopItem(self: *Emitter, body: []const ast.Stmt) anyerror!?GenItem {
        const v = genFirstYield(body) orelse return null;
        // 144 B-142 — a `for` of the body binds a name the `yield` may read
        // (`for (xs) { s -> yield s; }`): each binder is known here as an
        // element of what its loop walks, while the item is read.
        var installed: std.ArrayListUnmanaged(GenBinder) = .empty;
        defer installed.deinit(self.alloc);
        defer {
            var i = installed.items.len;
            while (i > 0) {
                i -= 1;
                const b = installed.items[i];
                if (b.prev) |p| self.locals.put(b.name, p) catch {} else _ = self.locals.remove(b.name);
                if (b.had_str) self.str_locals.put(b.name, {}) catch {} else _ = self.str_locals.remove(b.name);
                if (b.had_bool) self.bool_locals.put(b.name, {}) catch {} else _ = self.bool_locals.remove(b.name);
            }
        }
        try self.installGenBinders(body, &installed);
        // Decision 122's sugar (`yield __bp_ok(v)`, `break __bp_error(e)`):
        // the item is the `@Result` of the two payloads the body emits.
        if (try self.genResultItem(body)) |it| return it;
        return self.genValueItem(v, body, 0);
    }

    /// The `@Result<U, E>` item of a generator body the transform rewrote
    /// for decision 122: `U` read off its first `__bp_ok(v)`, `E` off its
    /// first `__bp_error(e)`; null unless both are there and known.
    fn genResultItem(self: *Emitter, body: []const ast.Stmt) anyerror!?GenItem {
        const ok_v = genWrappedYield(body, "__bp_ok") orelse return null;
        const err_v = genWrappedYield(body, "__bp_error") orelse return null;
        const ok_it = (try self.genValueItem(ok_v, body, 0)) orelse return null;
        const err_it = (try self.genValueItem(err_v, body, 0)) orelse return null;
        const ok_t = reprTypeRef(ok_it) orelse return null;
        const err_t = reprTypeRef(err_it) orelse return null;
        const ra = self.reg_arena.allocator();
        const args = try ra.alloc(ast.TypeRef, 2);
        args[0] = ok_t;
        args[1] = err_t;
        const t: ast.TypeRef = .{ .generic = .{ .name = "Result", .args = args, .is_builtin = true } };
        return self.genItemOfTypeRef(t);
    }

    /// The type a scalar, string or record item names.
    fn reprTypeRef(it: GenItem) ?ast.TypeRef {
        if (it.tr) |t| return t;
        if (it.bool_) return .{ .named = "bool" };
        return switch (it.repr) {
            .i32 => .{ .named = "i32" },
            .i64 => .{ .named = "i64" },
            .f64 => .{ .named = "f64" },
            .bool => .{ .named = "bool" },
            .ref => |k| switch (k) {
                .str => .{ .named = "string" },
                .record => |n| .{ .named = n },
                else => null,
            },
        };
    }

    /// The argument of the first `yield` / `break` value of a generator
    /// body's own that is the builtin call `callee(x)`.
    fn genWrappedYield(body: []const ast.Stmt, callee: []const u8) ?ast.Expr {
        for (body) |st| if (genWrappedYieldExpr(st.expr, callee)) |v| return v;
        return null;
    }

    fn genWrappedYieldExpr(e: ast.Expr, callee: []const u8) ?ast.Expr {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                inline .@"break", .yield => |jl| blk: {
                    const v = (jl.value orelse break :blk null).*;
                    if (v != .call or v.call.kind != .call) break :blk null;
                    const cc = v.call.kind.call;
                    if (!cc.is_builtin or cc.receiver != null or cc.args.len != 1 or !std.mem.eql(u8, cc.callee, callee)) break :blk null;
                    break :blk cc.args[0].value.*;
                },
                else => null,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| genWrappedYield(i.then_, callee) orelse (if (i.else_) |els| genWrappedYield(els, callee) else null),
                else => null,
            },
            .loop => |lp| if (lp.generator == null) genWrappedYield(lp.body, callee) else null,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| genWrappedYieldExpr(inner.*, callee),
                .case => |c| blk: {
                    for (c.arms) |arm| {
                        const r = if (arm.body == .function and c.isBlock) genWrappedYield(arm.body.function.kind.body, callee) else genWrappedYieldExpr(arm.body, callee);
                        if (r) |v| break :blk v;
                    }
                    break :blk null;
                },
                else => null,
            },
            else => null,
        };
    }

    const GenBinder = struct { name: []const u8, prev: ?Repr, had_str: bool, had_bool: bool };

    /// The binders of a generator body's own `for` loops (not an inner
    /// generator's or a lambda's), each a local of its loop's element repr.
    fn installGenBinders(self: *Emitter, body: []const ast.Stmt, out: *std.ArrayListUnmanaged(GenBinder)) anyerror!void {
        for (body) |st| try self.installGenBindersExpr(st.expr, out);
    }

    fn installGenBindersExpr(self: *Emitter, e: ast.Expr, out: *std.ArrayListUnmanaged(GenBinder)) anyerror!void {
        switch (e) {
            .loop => |lp| {
                if (lp.generator != null) return;
                if (!lp.condition and lp.params.len == 1) {
                    const n = lp.params[0];
                    const er: ?Repr = if (self.isGenExpr(lp.iter.*))
                        (if (try self.genItemOf(lp.iter.*)) |it| it.repr else null)
                    else
                        self.gcElemRepr(lp.iter.*);
                    if (er) |r| {
                        try out.append(self.alloc, .{ .name = n, .prev = self.locals.get(n), .had_str = self.str_locals.contains(n), .had_bool = self.bool_locals.contains(n) });
                        try self.locals.put(n, r);
                        if (r.isStr()) try self.str_locals.put(n, {}) else _ = self.str_locals.remove(n);
                        if (r == .bool) try self.bool_locals.put(n, {}) else _ = self.bool_locals.remove(n);
                    }
                }
                try self.installGenBinders(lp.body, out);
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    try self.installGenBinders(i.then_, out);
                    if (i.else_) |els| try self.installGenBinders(els, out);
                },
                else => {},
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| try self.installGenBindersExpr(inner.*, out),
                .case => |c| for (c.arms) |arm| {
                    if (arm.body == .function and c.isBlock) try self.installGenBinders(arm.body.function.kind.body, out) else try self.installGenBindersExpr(arm.body, out);
                },
                else => {},
            },
            else => {},
        }
    }

    fn genValueItem(self: *Emitter, v: ast.Expr, body: []const ast.Stmt, depth: u32) anyerror!?GenItem {
        if (depth > 4) return null;
        if (plainIdentName(v)) |n| if (!self.locals.contains(self.resolveName(n)) and !self.globals.contains(n)) {
            const first = genBindingOf(body, n) orelse return null;
            return self.genValueItem(first, body, depth + 1);
        };
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectIdents(v, &names);
        for (names.items) |n| {
            if (self.locals.contains(self.resolveName(n)) or self.globals.contains(n) or self.fn_sigs.contains(n)) continue;
            return null;
        }
        if (self.isBoolExpr(v)) return .{ .repr = .bool, .bool_ = true };
        return .{ .repr = self.wasmTypeOf(v) };
    }

    /// The first `yield v` / `break v` of a generator scope's own body: its
    /// `if` / `case` arms, blocks and unprefixed loops, not a lambda's or an
    /// inner generator's.
    fn genFirstYield(body: []const ast.Stmt) ?ast.Expr {
        for (body) |st| if (genFirstYieldExpr(st.expr)) |v| return v;
        return null;
    }

    fn genFirstYieldExpr(e: ast.Expr) ?ast.Expr {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                inline .@"break", .yield => |jl| if (jl.value) |v| v.* else null,
                else => null,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| genFirstYield(i.then_) orelse (if (i.else_) |els| genFirstYield(els) else null),
                else => null,
            },
            .loop => |lp| if (lp.generator == null) genFirstYield(lp.body) else null,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| genFirstYieldExpr(inner.*),
                .case => |c| blk: {
                    for (c.arms) |arm| {
                        const r = if (arm.body == .function and c.isBlock) genFirstYield(arm.body.function.kind.body) else genFirstYieldExpr(arm.body);
                        if (r) |v| break :blk v;
                    }
                    break :blk null;
                },
                else => null,
            },
            else => null,
        };
    }

    /// The initialiser of the `val` / `var` named `n` in a generator body.
    fn genBindingOf(body: []const ast.Stmt, n: []const u8) ?ast.Expr {
        for (body) |st| switch (st.expr) {
            .binding => |b| switch (b.kind) {
                .localBind => |lb| if (std.mem.eql(u8, lb.name, n)) return lb.value.*,
                else => {},
            },
            .loop => |lp| if (lp.generator == null) if (genBindingOf(lp.body, n)) |v| return v,
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    if (genBindingOf(i.then_, n)) |v| return v;
                    if (i.else_) |els| if (genBindingOf(els, n)) |v| return v;
                },
                else => {},
            },
            else => {},
        };
        return null;
    }

    /// Whether a generator scope's `yield :l` / `break :l v` all name the
    /// scope itself (`own`): one naming an enclosing scope has no lowering
    /// here, the inner scope being a machine of its own.
    fn genLabelsOwn(body: []const ast.Stmt, own: ?[]const u8) bool {
        for (body) |st| if (!genLabelsOwnExpr(st.expr, own)) return false;
        return true;
    }

    fn genLabelsOwnExpr(e: ast.Expr, own: ?[]const u8) bool {
        return switch (e) {
            .jump => |j| switch (j.kind) {
                .yield => |jl| if (jl.label) |l| (if (own) |o| std.mem.eql(u8, l, o) else false) else true,
                .@"break" => |jl| if (jl.value != null) (if (jl.label) |l| (if (own) |o| std.mem.eql(u8, l, o) else false) else true) else true,
                else => true,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| genLabelsOwn(i.then_, own) and (if (i.else_) |els| genLabelsOwn(els, own) else true),
                else => true,
            },
            .loop => |lp| if (lp.generator == null) genLabelsOwn(lp.body, own) else true,
            .collection => |col| switch (col.kind) {
                .grouped => |inner| genLabelsOwnExpr(inner.*, own),
                .case => |c| blk: {
                    for (c.arms) |arm| {
                        const ok = if (arm.body == .function and c.isBlock) genLabelsOwn(arm.body.function.kind.body, own) else genLabelsOwnExpr(arm.body, own);
                        if (!ok) break :blk false;
                    }
                    break :blk true;
                },
                else => true,
            },
            else => true,
        };
    }

    /// Open a generator machine over the function whose state was just
    /// reset: a task machine's locals, the handle in place of the task, and
    /// the item its `yield`s box.
    fn beginGenMachine(self: *Emitter, body: []const ast.Stmt, yitem: GenItem, label: ?[]const u8) !void {
        if (!genLabelsOwn(body, label)) return self.gcFail("a yield naming an enclosing generator scope");
        self.machine = .{};
        const n: u32 = @intCast(self.gc_frames.items.len);
        try self.gc_frames.append(self.alloc, &.{});
        self.machine.?.frame = n;
        try self.declareLocal(gen_handle, .{ .ref = .gen });
        try self.declareLocal(sm_frame, .{ .ref = .{ .frame = n } });
        try self.declareLocal(sm_seek, .i32);
        try self.declareLocal(sm_state, .i32);
        self.gen_item = yitem;
        self.yield_target = gen_handle;
        self.gen_end = null;
        self.gen_used = true;
        self.gen_close_arms = .empty;
        self.gen_defer_floor = self.defer_stack.items.len;
    }

    /// The defers pending at the suspension point `k` of a generator
    /// machine, run when a consumer closes the handle there (`$__gen_close`).
    const GenCloseArm = struct { k: u32, seq: Seq };

    /// A generator machine's body: every statement under its resume guard,
    /// `0` (ended) when it falls off its end.
    fn renderGenBody(self: *Emitter, body: []const ast.Stmt) !Seq {
        var c: Capture = .{};
        self.open(&c);
        self.fn_has_result = false;
        const tail = try self.emitBody(body, false);
        if (tail != .terminated) try self.emitC(zero, "the sequence ended");
        return self.seal(&c, if (tail == .terminated) .terminated else .{ .value = .i32 });
    }

    /// `yield v` in a generator machine — its suspension point `k`: the item
    /// boxed into the handle, the frame saved, `k` recorded, `1` answered.
    /// Entered again at `k`, the body goes on after it:
    ///
    ///     (block $__yd<k>
    ///       local.get $__seek
    ///       (if (then (i32.eq $__state k) (if (then i32.const 0 local.set $__seek)) br $__yd<k>))
    ///       local.get $__gen <v boxed> struct.set $gen value
    ///       … save the frame, k …  i32.const 1 return)
    fn emitGenYield(self: *Emitter, v: ast.Expr, yitem: GenItem) anyerror!void {
        const k = self.machine.?.next;
        self.machine.?.next += 1;
        const label = try std.fmt.allocPrint(self.reg_arena.allocator(), "__yd{d}", .{k});
        if (self.defer_stack.items.len > self.gen_defer_floor) {
            var dc: Capture = .{};
            self.open(&dc);
            try self.runDefers(self.gen_defer_floor);
            try self.gen_close_arms.append(self.reg_arena.allocator(), .{ .k = k, .seq = self.seal(&dc, .none) });
        }
        var c: Capture = .{};
        self.open(&c);
        {
            var seek_c: Capture = .{};
            self.open(&seek_c);
            try self.emit(.{ .local_get = sm_state });
            try self.emit(try self.constInt(k));
            try self.emit(opOf(.i32, "eq"));
            var hit_c: Capture = .{};
            self.open(&hit_c);
            try self.emit(zero);
            try self.emit(.{ .local_set = sm_seek });
            const hit = self.seal(&hit_c, .none);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit } } });
            try self.emitC(.{ .br = label }, "resumed after this yield, or seeking past it");
            const seek = self.seal(&seek_c, .terminated);
            try self.emit(.{ .local_get = sm_seek });
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = seek } } });
        }
        try self.emit(.{ .local_get = gen_handle });
        if (yitem.repr == .bool) {
            try self.lowerCoerced(v, .i32);
        } else try self.lowerCoerced(v, yitem.repr);
        try self.gcBox(yitem.repr);
        try self.emitC(.{ .struct_set = .{ .ty = self.gcTyIndex(.gen), .field = gen_fld.value } }, "the yitem");
        try self.emit(.{ .comment = save_marker });
        try self.emit(.{ .local_get = sm_frame });
        try self.emit(try self.constInt(k));
        try self.emitC(.{ .struct_set = .{ .ty = self.gcTyIndex(.{ .frame = self.machine.?.frame }), .field = 0 } }, "the resume index");
        try self.emit(one);
        try self.emitC(.@"return", "an yitem");
        const inner = self.seal(&c, .terminated);
        try self.emit(.{ .block = .{ .kind = .block, .label = label, .body = inner } });
    }

    /// The end of a generator machine's sequence: `0`, the defers run.
    fn emitGenMachineEnd(self: *Emitter) anyerror!void {
        try self.runDefers(0);
        try self.emitC(zero, "the sequence ended");
        try self.emit(.@"return");
    }

    /// Decision 105 on wasm — `f`'s lowered body as a generator machine (§
    /// above): the handle `$f` and the re-entered body `$f__body`. `aux`
    /// names the parameter the handle keeps as its environment (a lifted
    /// lambda's `__env`).
    fn emitGenMachine(self: *Emitter, f: wat.Func, aux: ?[]const u8) !void {
        const ar = self.arena();
        const n = self.machine.?.frame;
        var slots: std.ArrayListUnmanaged(wat.Local) = .empty;
        for (f.params) |p| try slots.append(ar, .{ .name = p.name, .ty = p.ty });
        var body_locals: std.ArrayListUnmanaged(wat.Local) = .empty;
        for (f.params) |p| try body_locals.append(ar, .{ .name = p.name, .ty = p.ty });
        for (f.locals) |group| for (group) |l| {
            if (std.mem.eql(u8, l.name, gen_handle)) continue;
            try body_locals.append(ar, l);
            if (!isMachineLocal(l.name)) try slots.append(ar, l);
        };
        const slot_tys = try ar.alloc(ValType, slots.items.len);
        for (slots.items, slot_tys) |sl, *t| t.* = sl.ty;
        self.gc_frames.items[n] = slot_tys;
        const fty = self.gcTyIndex(.{ .frame = n });
        const frame_vt = ValType.def(fty);
        const gi = self.gcTyIndex(.gen);
        const gen_vt = ValType.def(gi);
        const kind = gen_body_base + @as(u32, @intCast(self.gen_kinds.items.len));
        const body_name = try std.fmt.allocPrint(ar, "{s}__body", .{f.name});
        try self.gen_kinds.append(self.alloc, body_name);

        var saves: std.ArrayListUnmanaged(wat.Line) = .empty;
        var restores: std.ArrayListUnmanaged(wat.Line) = .empty;
        for (slots.items, 0..) |sl, i| {
            const field: wat.FieldRef = .{ .ty = fty, .field = @intCast(1 + i) };
            try saves.appendSlice(ar, &.{ .{ .instr = .{ .local_get = sm_frame } }, .{ .instr = .{ .local_get = sl.name } }, .{ .instr = .{ .struct_set = field } } });
            try restores.appendSlice(ar, &.{ .{ .instr = .{ .local_get = sm_frame } }, .{ .instr = .{ .struct_get = field } }, .{ .instr = .{ .local_set = sl.name } } });
        }

        // $f — the handle: nothing of the body runs.
        var start: std.ArrayListUnmanaged(wat.Line) = .empty;
        try start.appendSlice(ar, &.{
            .{ .instr = .{ .struct_new_default = fty }, .comment = "the frame: the resume index, then every local" },
            .{ .instr = .{ .local_set = "__fr" } },
        });
        for (f.params, 0..) |p, i| try start.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = "__fr" } },
            .{ .instr = .{ .local_get = p.name } },
            .{ .instr = .{ .struct_set = .{ .ty = fty, .field = @intCast(1 + i) } } },
        });
        try start.appendSlice(ar, &.{
            .{ .instr = zero, .comment = "live" },
            .{ .instr = try self.constInt(kind), .comment = body_name },
            .{ .instr = .{ .local_get = "__fr" } },
            .{ .instr = .{ .ref_null = .anyref } },
            .{ .instr = .{ .ref_null = gen_vt } },
            .{ .instr = if (aux) |a| .{ .local_get = a } else .{ .ref_null = .anyref }, .comment = "the environment" },
            .{ .instr = zero },
            .{ .instr = .{ .struct_new = gi }, .comment = "runs nothing until its first next" },
        });
        try self.item(.{ .func = try self.builder().func(.{
            .name = f.name,
            .exports = f.exports,
            .params = f.params,
            .result = gen_vt,
            .locals = try self.builder().localLines(&.{.{ .name = "__fr", .ty = frame_vt }}),
            .body = .{ .lines = start.items, .stack = .{ .value = gen_vt } },
        }) });

        // $f__body — entered again at the frame's resume index.
        var lines: std.ArrayListUnmanaged(wat.Line) = .empty;
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = gen_handle } },
            .{ .instr = .{ .struct_get = .{ .ty = gi, .field = gen_fld.frame } } },
            .{ .instr = .{ .ref_cast = frame_vt } },
            .{ .instr = .{ .local_set = sm_frame } },
        });
        try lines.appendSlice(ar, restores.items);
        try lines.appendSlice(ar, &.{
            .{ .instr = .{ .local_get = sm_frame } },
            .{ .instr = .{ .struct_get = .{ .ty = fty, .field = 0 } }, .comment = "the resume index" },
            .{ .instr = .{ .local_tee = sm_state } },
            .{ .instr = zero },
            .{ .instr = opOf(.i32, "ne") },
            .{ .instr = .{ .local_set = sm_seek } },
        });
        // 144 B-142 — closed by its consumer (`left` is -1, `$__gen_close`):
        // the defers pending at the point it rests on run, and it ends. A
        // body with no `defer` has nothing to run and is never entered so.
        if (self.gen_close_arms.items.len > 0) {
            try self.gen_closable.append(self.reg_arena.allocator(), kind);
            var cc: Capture = .{};
            self.open(&cc);
            for (self.gen_close_arms.items) |arm| {
                try self.emit(.{ .local_get = sm_state });
                try self.emit(try self.constInt(arm.k));
                try self.emit(opOf(.i32, "eq"));
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = arm.seq } } });
            }
            try self.emit(zero);
            try self.emitC(.@"return", "closed");
            const closing = self.seal(&cc, .terminated);
            try lines.appendSlice(ar, &.{
                .{ .instr = .{ .local_get = gen_handle } },
                .{ .instr = .{ .struct_get = .{ .ty = gi, .field = gen_fld.left } } },
                .{ .instr = try self.constInt(-1) },
                .{ .instr = opOf(.i32, "eq") },
                .{ .instr = .{ .@"if" = .{ .then = .{ .seq = closing } } }, .comment = "closed by its consumer" },
            });
            self.gen_close_arms = .empty;
        }
        const replaced = try self.withFrameSaves(f.body, saves.items);
        try lines.appendSlice(ar, replaced.lines);
        try self.item(.{ .func = try self.builder().func(.{
            .name = body_name,
            .params = &.{wat.Builder.param(gen_handle, gen_vt)},
            .result = .i32,
            .locals = try self.builder().localLines(body_locals.items),
            .body = .{ .lines = lines.items, .stack = replaced.stack },
        }) });
    }

    /// `iter loop { … }` (and the `iter while` / `iter for` it stands for) in
    /// a GC module: a lifted lambda whose body is the loop, unprefixed, as a
    /// generator machine; its closure is made here and called, answering the
    /// handle.
    fn lowerGenLoopValue(self: *Emitter, lp: anytype) anyerror!void {
        const yitem = (try self.genLoopItem(lp.body)) orelse return self.gcFail("an iter loop whose yitem type is not known");
        const ra = self.reg_arena.allocator();
        var inner = lp;
        inner.generator = null;
        inner.prefixedKeyword = null;
        const body = try ra.alloc(ast.Stmt, 1);
        body[0] = .{ .expr = .{ .loop = inner } };
        const idx = self.lambdas.items.len;
        const slot = try std.fmt.allocPrint(ra, "__gloop{d}", .{idx});
        try self.declareLocal(slot, .{ .ref = .closure });
        self.expected_fn = null;
        try self.lowerLambdaValue(&.{}, body, lp.loc);
        self.lambdas.items[idx].generator = true;
        self.lambdas.items[idx].gen_item = yitem;
        self.lambdas.items[idx].ret_seen = null;
        try self.emit(.{ .local_set = slot });
        try self.emitC(.{ .local_get = slot }, "the loop's environment");
        try self.gcEmitIndirect(slot, 0);
        try self.emit(.{ .ref_cast = self.gcTy(.gen) });
    }

    /// A local the function binds to a generator: what it yields, and — an
    /// `iter` loop's handle, or an iterator derived from a local holding one
    /// — the loop whose captures a step here syncs.
    fn noteGenLocal(self: *Emitter, name: []const u8, value: ast.Expr, lambda_idx: u32) !void {
        _ = self.gen_items.remove(name);
        _ = self.gen_locals.remove(name);
        if (!self.isGenExpr(value)) return;
        if (try self.genItemOf(value)) |it| try self.gen_items.put(self.alloc, name, it);
        if (value == .loop and self.lambdas.items.len > lambda_idx) {
            try self.gen_locals.put(self.alloc, name, .{ .lambda = lambda_idx, .handle = name });
            return;
        }
        if (self.genSourceLocal(value)) |gl| try self.gen_locals.put(self.alloc, name, gl);
    }

    const GenLocal = struct { lambda: u32, handle: []const u8 };

    /// The `iter` loop a generator expression steps, through a derived
    /// iterator's receivers to a local holding its handle.
    fn genSourceLocal(self: *Emitter, e: ast.Expr) ?GenLocal {
        var cur = e;
        while (true) {
            if (cur == .collection and cur.collection.kind == .grouped) {
                cur = cur.collection.kind.grouped.*;
                continue;
            }
            if (self.genMethodOf(cur) != null) {
                cur = cur.call.kind.call.receiver.?.*;
                continue;
            }
            break;
        }
        const n = plainIdentName(cur) orelse return null;
        return self.gen_locals.get(self.resolveName(n));
    }

    /// Around a step of the generator `e` in the function that made it: the
    /// locals its body captured copied into its environment (`into_env`), or
    /// the ones the body assigns back out of it (`out_of_env`).
    fn genSyncCaptures(self: *Emitter, e: ast.Expr, dir: GenSync) anyerror!void {
        const gl = self.genSourceLocal(e) orelse return;
        try self.genSyncLocal(gl, dir);
    }

    const GenSync = enum { into_env, out_of_env };

    fn genSyncLocal(self: *Emitter, gl: GenLocal, dir: GenSync) anyerror!void {
        const l = self.lambdas.items[gl.lambda];
        const ety = self.gcTyIndex(.{ .env = l.idx });
        for (l.captures, 0..) |cp, i| {
            if (dir == .out_of_env and !cp.threaded) continue;
            if (!self.locals.contains(cp.name)) continue;
            const f: wat.FieldRef = .{ .ty = ety, .field = @intCast(2 + i) };
            try self.emit(.{ .local_get = gl.handle });
            try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.gen), .field = gen_fld.aux } });
            try self.emit(.{ .ref_cast = ValType.def(ety) });
            switch (dir) {
                .into_env => {
                    try self.emit(.{ .local_get = cp.name });
                    try self.emitCf(.{ .struct_set = f }, "sync {s} into the generator", .{cp.name});
                },
                .out_of_env => {
                    try self.emitCf(.{ .struct_get = f }, "sync {s} from the generator", .{cp.name});
                    try self.emit(.{ .local_set = cp.name });
                },
            }
        }
    }

    /// A call that hands a generator local of this function on (`line(g)`):
    /// the callee may step it, so the loop's captures are synced around the
    /// call — in before, out after. Answers whether it lowered `e`.
    fn lowerGenSyncedCall(self: *Emitter, e: ast.Expr, cc: anytype) anyerror!bool {
        if (self.mode != .gc or self.gen_call_synced or self.gen_locals.count() == 0) return false;
        if (self.genMethodOf(e) != null) return false;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        const ra = self.reg_arena.allocator();
        for (cc.args) |a| try self.collectIdents(a.value.*, &names);
        if (cc.receiver) |r| try self.collectIdents(r.*, &names);
        var used: std.ArrayListUnmanaged(GenLocal) = .empty;
        outer: for (names.items) |n| {
            const gl = self.gen_locals.get(self.resolveName(n)) orelse continue;
            for (used.items) |u| if (std.mem.eql(u8, u.handle, gl.handle)) continue :outer;
            try used.append(ra, gl);
        }
        if (used.items.len == 0) return false;
        for (used.items) |gl| try self.genSyncLocal(gl, .into_env);
        self.gen_call_synced = true;
        {
            defer self.gen_call_synced = false;
            try self.lowerExpr(e);
        }
        for (used.items) |gl| try self.genSyncLocal(gl, .out_of_env);
        return true;
    }

    /// One step of the handle in `base`: `$__gen_next` between the syncs of
    /// the generator `e`'s captures; leaves `1` (an item in `value`) or `0`.
    fn emitGenStep(self: *Emitter, base: []const u8, e: ast.Expr) anyerror!void {
        try self.genSyncCaptures(e, .into_env);
        try self.emit(.{ .local_get = base });
        try self.emitC(.{ .call = "__gen_next" }, "the next yitem");
        try self.genSyncCaptures(e, .out_of_env);
    }

    /// `for (g) { x -> … }` over a generator in a GC module: one step per
    /// iteration, the item unboxed into the binder. Re-entering a machine
    /// inside an iteration, the step is not taken again (the binder is the
    /// frame's).
    fn lowerGenFor(self: *Emitter, lp: anytype) anyerror!void {
        self.gen_used = true;
        const ra = self.reg_arena.allocator();
        const n = self.loop_seq;
        self.loop_seq += 1;
        const base = try std.fmt.allocPrint(ra, "__gfor{d}", .{n});
        try self.declareLocal(base, .{ .ref = .gen });

        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        const start_lo = if (self.machine) |m| m.next else 0;
        var start: Capture = .{};
        self.open(&start);
        try self.lowerCoerced(lp.iter.*, .{ .ref = .gen });
        try self.emit(.{ .local_set = base });
        const yitem = (try self.genItemOf(lp.iter.*)) orelse {
            _ = self.seal(&start, .none);
            return self.gcFail("a loop over a generator whose yitem type is not known");
        };
        const elem0 = if (lp.params.len > 0) lp.params[0] else "__it";
        const er: Repr = if (yitem.repr == .bool) .i32 else yitem.repr;
        const elem = try self.bindTargetAs(elem0, er);
        try self.declareLocal(elem, er);
        if (er.isStr()) try self.str_locals.put(elem, {});
        if (yitem.bool_) try self.bool_locals.put(elem, {});
        if (yitem.tr) |t| try self.noteTypedBinder(elem, t);
        if (er == .ref and er.ref == .record) try self.local_types.put(elem, er.ref.record);
        self.installShadow(elem0, elem);
        try self.guardStart(&start, start_lo);

        var loop_c: Capture = .{};
        self.open(&loop_c);
        {
            var step_c: Capture = .{};
            self.open(&step_c);
            try self.emitGenStep(base, lp.iter.*);
            try self.emit(opOf(.i32, "eqz"));
            try self.emit(.{ .br_if = break_label });
            try self.emit(.{ .local_get = base });
            try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.gen), .field = gen_fld.value } });
            try self.gcUnbox(er);
            try self.emit(.{ .local_set = elem });
            const step = self.seal(&step_c, .none);
            if (self.machine != null) {
                try self.emit(.{ .local_get = sm_seek });
                try self.emit(opOf(.i32, "eqz"));
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = step } } });
            } else for (step.lines) |l| try self.cur.?.append(self.arena(), l);
        }
        try self.emitIterationBody(lp.body, lp.label);
        try self.emit(.{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);
        try self.emitLoopBlock(loop_seq, lp.label);
        try self.emitGenClose(base);
        try self.emit(zero);
    }

    /// `g.take(n)`, `g.drop(n)`, `g.map(f)`, `g.filter(f)` over a generator:
    /// a derived handle over `g` (`$__gen_resume`'s fixed kinds); `toArray`
    /// steps `g` to its end into an array.
    fn lowerGenMethod(self: *Emitter, e: ast.Expr) anyerror!bool {
        const m = self.genMethodOf(e) orelse return false;
        const cc = e.call.kind.call;
        const recv = cc.receiver.?.*;
        self.gen_used = true;
        const gi = self.gcTyIndex(.gen);
        const gen_r: Repr = .{ .ref = .gen };
        if (m == .next) {
            // `g.next()` by hand: one step, `Yield(item)` or `Done` — the
            // item stays in its box, a generic payload's erased slot.
            if (self.enums.get("YieldStep") == null) return self.gcFail("a next() with no YieldStep declared");
            const base = try self.gcTemp(gen_r);
            try self.lowerCoerced(recv, gen_r);
            try self.emit(.{ .local_set = base });
            try self.emitGenStep(base, recv);
            const er: Repr = .{ .ref = .{ .enum_ = "YieldStep" } };
            var y: Capture = .{};
            self.open(&y);
            try self.emit(.{ .local_get = base });
            try self.emit(.{ .struct_get = .{ .ty = gi, .field = gen_fld.value } });
            try self.emit(.{ .struct_new = self.gcTyIndex(.{ .variant = .{ .en = "YieldStep", .name = "Yield" } }) });
            const yes = self.seal(&y, .{ .value = self.vtOf(er) });
            var d: Capture = .{};
            self.open(&d);
            try self.emit(.{ .struct_new = self.gcTyIndex(.{ .variant = .{ .en = "YieldStep", .name = "Done" } }) });
            const no = self.seal(&d, .{ .value = self.vtOf(er) });
            try self.emit(.{ .@"if" = .{ .result = self.vtOf(er), .then = .{ .seq = yes }, .@"else" = .{ .seq = no } } });
            return true;
        }
        switch (m) {
            .for_each, .some, .every, .reduce => {
                try self.lowerGenWalk(e, m);
                return true;
            },
            else => {},
        }
        if (m == .to_array) {
            const yitem = (try self.genItemOf(recv)) orelse return self.gcFail("a toArray over a generator whose yitem type is not known");
            const er: Repr = if (yitem.repr == .bool) .i32 else yitem.repr;
            const cls = gcElemClassOf(er);
            const ti = self.gcTyIndex(.{ .arr = cls });
            const base = try self.gcTemp(gen_r);
            const acc = try self.gcTemp(.{ .ref = .{ .arr = cls } });
            try self.lowerCoerced(recv, gen_r);
            try self.emit(.{ .local_set = base });
            try self.emit(zero);
            try self.emit(.{ .array_new_default = ti });
            try self.emit(.{ .local_set = acc });
            var loop_c: Capture = .{};
            self.open(&loop_c);
            try self.emitGenStep(base, recv);
            try self.emit(opOf(.i32, "eqz"));
            try self.emit(.{ .br_if = break_label });
            try self.emit(.{ .local_get = acc });
            try self.emit(.{ .local_get = base });
            try self.emit(.{ .struct_get = .{ .ty = gi, .field = gen_fld.value } });
            if (cls != .any) try self.gcUnbox(er);
            try self.emit(.{ .call = try self.gcArrPush(cls) });
            try self.emit(.{ .local_set = acc });
            try self.emit(.{ .br = continue_label });
            const loop_seq = self.seal(&loop_c, .terminated);
            try self.emitLoopBlockPlain(loop_seq);
            try self.emit(.{ .local_get = acc });
            return true;
        }
        const kind: GenKind = switch (m) {
            .take => .take,
            .drop => .drop,
            .map => .map,
            .filter => .filter,
            else => unreachable,
        };
        try self.emit(zero);
        try self.emitC(try self.constInt(@intFromEnum(kind)), @tagName(kind));
        try self.emit(.{ .ref_null = .structref });
        try self.emit(.{ .ref_null = .anyref });
        try self.lowerCoerced(recv, gen_r);
        switch (kind) {
            .take, .drop => {
                try self.emit(.{ .ref_null = .anyref });
                try self.lowerCoerced(cc.args[0].value.*, .i32);
            },
            .map, .filter => {
                const src = (try self.genItemOf(recv)) orelse return self.gcFail("a map or filter over a generator whose yitem type is not known");
                const lam = genMethodLambda(cc) orelse return self.gcFail("a map or filter over a generator of no lambda written at the call");
                if (lam.params.len != 1) return self.gcFail("a map or filter over a generator of a lambda of no one parameter");
                const idx = self.lambdas.items.len;
                try self.lowerLambdaValue(lam.params, lam.body, self.call_loc);
                const l = &self.lambdas.items[idx];
                const pr: Repr = if (src.repr == .bool) .i32 else src.repr;
                if (l.param_seen.len > 0) l.param_seen[0] = pr;
                if (l.param_known.len > 0) l.param_known[0] = true;
                if (l.param_str.len > 0 and pr.isStr()) l.param_str[0] = true;
                if (kind == .map) {
                    const out = (try self.lambdaAnswerOver(lam.params[0], src, lam.body)) orelse return self.gcFail("a map over a generator whose answer is not known");
                    l.ret_seen = if (out.repr == .bool) .i32 else out.repr;
                    self.gen_map_used = true;
                } else {
                    l.ret_seen = .i32;
                    self.gen_filter_used = true;
                }
                self.uses_table = true;
                try self.emit(zero);
            },
        }
        try self.emitC(.{ .struct_new = gi }, "a derived iterator");
        return true;
    }

    const GenWalkArgs = struct { lam: ?GenLambda, init: ?ast.Expr };

    /// A walk's lambda (its argument or trailing block) and `reduce`'s
    /// initial value (`g.reduce({ acc, x -> … }, init)`).
    fn genWalkArgs(cc: anytype) GenWalkArgs {
        if (cc.trailing.len == 1) return .{
            .lam = .{ .params = cc.trailing[0].params, .body = cc.trailing[0].body },
            .init = if (cc.args.len == 1) cc.args[0].value.* else null,
        };
        if (cc.args.len == 0) return .{ .lam = null, .init = null };
        const v = cc.args[0].value.*;
        const lam: ?GenLambda = if (v == .function and v.function.kind.syntax == .lambda) .{ .params = v.function.kind.params, .body = v.function.kind.body } else null;
        return .{ .lam = lam, .init = if (cc.args.len == 2) cc.args[1].value.* else null };
    }

    /// 144 B-142 — `g.forEach(f)`, `g.some(f)`, `g.every(f)`,
    /// `g.reduce(f, init)` over a generator: `$__gen_next` per item, the
    /// closure called on it; `some` stops at the first `true`, `every` at the
    /// first `false`, so the body runs no step past the item that answered.
    fn lowerGenWalk(self: *Emitter, e: ast.Expr, m: GenMethod) anyerror!void {
        const cc = e.call.kind.call;
        const recv = cc.receiver.?.*;
        const gi = self.gcTyIndex(.gen);
        const gen_r: Repr = .{ .ref = .gen };
        const src = (try self.genItemOf(recv)) orelse return self.gcFail("a walk over a generator whose yitem type is not known");
        const wa = genWalkArgs(cc);
        const lam = wa.lam orelse return self.gcFail("a walk over a generator of no lambda written at the call");
        const argc: usize = if (m == .reduce) 2 else 1;
        if (lam.params.len != argc) return self.gcFail("a walk over a generator of a lambda of another arity");
        if (m == .reduce and wa.init == null) return self.gcFail("a reduce over a generator with no initial value");
        const acc_r: Repr = if (m == .reduce) self.wasmTypeOf(wa.init.?) else .i32;
        const acc_vr: Repr = if (acc_r == .bool) .i32 else acc_r;
        const pr: Repr = if (src.repr == .bool) .i32 else src.repr;
        self.gen_used = true;

        const base = try self.gcTemp(gen_r);
        const clo = try self.gcTemp(.{ .ref = .closure });
        const acc = try self.gcTemp(acc_vr);
        try self.lowerCoerced(recv, gen_r);
        try self.emit(.{ .local_set = base });
        if (m == .reduce) {
            try self.lowerCoerced(wa.init.?, acc_vr);
        } else try self.emit(if (m == .every) one else zero);
        try self.emit(.{ .local_set = acc });

        const idx = self.lambdas.items.len;
        try self.lowerLambdaValue(lam.params, lam.body, self.call_loc);
        {
            const l = &self.lambdas.items[idx];
            const item_at: usize = argc - 1;
            if (m == .reduce) {
                if (l.param_seen.len > 0) l.param_seen[0] = acc_vr;
                if (l.param_known.len > 0) l.param_known[0] = true;
                if (l.param_str.len > 0 and acc_vr.isStr()) l.param_str[0] = true;
            }
            if (l.param_seen.len > item_at) l.param_seen[item_at] = pr;
            if (l.param_known.len > item_at) l.param_known[item_at] = true;
            if (l.param_str.len > item_at and pr.isStr()) l.param_str[item_at] = true;
            l.ret_seen = acc_vr;
        }
        self.uses_table = true;
        try self.emit(.{ .local_set = clo });

        var loop_c: Capture = .{};
        self.open(&loop_c);
        try self.emitGenStep(base, recv);
        try self.emit(opOf(.i32, "eqz"));
        try self.emit(.{ .br_if = break_label });
        try self.emit(.{ .local_get = clo });
        if (m == .reduce) {
            try self.emit(.{ .local_get = acc });
            try self.gcBox(acc_vr);
        }
        try self.emit(.{ .local_get = base });
        try self.emit(.{ .struct_get = .{ .ty = gi, .field = gen_fld.value } });
        try self.gcEmitIndirect(clo, argc);
        try self.gcUnbox(acc_vr);
        switch (m) {
            .reduce => try self.emit(.{ .local_set = acc }),
            .for_each => try self.emit(.drop),
            .some, .every => {
                if (m == .every) try self.emit(opOf(.i32, "eqz"));
                var hit: Capture = .{};
                self.open(&hit);
                try self.emit(if (m == .some) one else zero);
                try self.emit(.{ .local_set = acc });
                try self.emitC(.{ .br = break_label }, "answered: no further step");
                const hit_seq = self.seal(&hit, .terminated);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = hit_seq } } });
            },
            else => unreachable,
        }
        try self.emit(.{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);
        try self.emitLoopBlockPlain(loop_seq);
        try self.emitGenClose(base);
        try self.emit(.{ .local_get = acc });
    }

    /// `$__gen_next(g) -> i32` — one step of a generator: `0` once its
    /// sequence ended (and from then on), else `1` with the item in `value`.
    fn genNextFunc(self: *Emitter) !wat.Func {
        const gi = self.gcTyIndex(.gen);
        var c: Capture = .{};
        self.open(&c);
        try self.emit(.{ .local_get = "g" });
        try self.emit(.{ .struct_get = .{ .ty = gi, .field = gen_fld.state } });
        {
            var d: Capture = .{};
            self.open(&d);
            try self.emit(zero);
            try self.emit(.@"return");
            const done = self.seal(&d, .terminated);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = done } } });
        }
        try self.emit(.{ .local_get = "g" });
        try self.emit(.{ .call = "__gen_resume" });
        try self.emit(.{ .local_tee = "r" });
        try self.emit(opOf(.i32, "eqz"));
        {
            var e: Capture = .{};
            self.open(&e);
            try self.emit(.{ .local_get = "g" });
            try self.emit(one);
            try self.emitC(.{ .struct_set = .{ .ty = gi, .field = gen_fld.state } }, "ended");
            try self.emit(.{ .local_get = "g" });
            try self.emit(.{ .ref_null = .structref });
            try self.emitC(.{ .struct_set = .{ .ty = gi, .field = gen_fld.frame } }, "its frame dropped");
            const ended = self.seal(&e, .none);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = ended } } });
        }
        try self.emit(.{ .local_get = "r" });
        const body = self.seal(&c, .{ .value = .i32 });
        return self.builder().func(.{
            .name = "__gen_next",
            .params = &.{wat.Builder.param("g", ValType.def(gi))},
            .result = .i32,
            .locals = try self.builder().localLines(&.{.{ .name = "r", .ty = .i32 }}),
            .body = body,
        });
    }

    /// 144 B-142 — `$__gen_close(g)`: a consumer leaves the generator before
    /// its end (a `break` out of its `for`, `some` / `every` answered). A
    /// derived iterator closes its source; a body still live is entered once
    /// more with `left` at -1, which runs the defers pending where it rests
    /// (`emitGenMachine`); the handle is ended either way.
    fn genCloseFunc(self: *Emitter) !wat.Func {
        const gi = self.gcTyIndex(.gen);
        var c: Capture = .{};
        self.open(&c);
        try self.emit(.{ .local_get = "g" });
        try self.emit(.ref_is_null);
        {
            var d: Capture = .{};
            self.open(&d);
            try self.emit(.@"return");
            const none = self.seal(&d, .terminated);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = none } } });
        }
        try self.genGet(gen_fld.kind);
        try self.emit(try self.constInt(gen_body_base));
        try self.emit(opOf(.i32, "lt_u"));
        {
            var d: Capture = .{};
            self.open(&d);
            try self.genGet(gen_fld.src);
            try self.emitC(.{ .call = "__gen_close" }, "its source");
            const derived = self.seal(&d, .none);
            var b: Capture = .{};
            self.open(&b);
            for (self.gen_closable.items) |k| {
                try self.genGet(gen_fld.state);
                try self.emit(opOf(.i32, "eqz"));
                try self.genGet(gen_fld.kind);
                try self.emit(try self.constInt(k));
                try self.emit(opOf(.i32, "eq"));
                try self.emit(opOf(.i32, "and"));
                var live: Capture = .{};
                self.open(&live);
                try self.emit(.{ .local_get = "g" });
                try self.emit(try self.constInt(-1));
                try self.emitC(.{ .struct_set = .{ .ty = gi, .field = gen_fld.left } }, "closing");
                try self.emit(.{ .local_get = "g" });
                try self.emit(.{ .call = "__gen_resume" });
                try self.emit(.drop);
                const live_seq = self.seal(&live, .none);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = live_seq } } });
            }
            const body = self.seal(&b, .none);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = derived }, .@"else" = .{ .seq = body } } });
        }
        try self.emit(.{ .local_get = "g" });
        try self.emit(one);
        try self.emitC(.{ .struct_set = .{ .ty = gi, .field = gen_fld.state } }, "ended");
        try self.emit(.{ .local_get = "g" });
        try self.emit(.{ .ref_null = .structref });
        try self.emitC(.{ .struct_set = .{ .ty = gi, .field = gen_fld.frame } }, "its frame dropped");
        const body = self.seal(&c, .none);
        return self.builder().func(.{
            .name = "__gen_close",
            .params = &.{wat.Builder.param("g", ValType.def(gi))},
            .result = null,
            .body = body,
        });
    }

    /// `local.get <base>; call $__gen_close` — the consumer in `base` is done
    /// with its generator, whether it ran to the end or left before.
    fn emitGenClose(self: *Emitter, base: []const u8) !void {
        self.gen_close_used = true;
        try self.emit(.{ .local_get = base });
        try self.emitC(.{ .call = "__gen_close" }, "the consumer is done with it");
    }

    /// `g.<field>`.
    fn genGet(self: *Emitter, field: u32) !void {
        try self.emit(.{ .local_get = "g" });
        try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.gen), .field = field } });
    }

    /// `if (!$__gen_next(g.src)) return 0`.
    fn genStepSrcOrEnd(self: *Emitter) !void {
        try self.genGet(gen_fld.src);
        try self.emit(.{ .call = "__gen_next" });
        try self.emit(opOf(.i32, "eqz"));
        var d: Capture = .{};
        self.open(&d);
        try self.emit(zero);
        try self.emit(.@"return");
        const done = self.seal(&d, .terminated);
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = done } } });
    }

    /// `g.value = <what the stack's code leaves>; return 1`.
    fn genAnswer(self: *Emitter, value: Seq) !void {
        try self.emit(.{ .local_get = "g" });
        for (value.lines) |l| try self.cur.?.append(self.arena(), l);
        try self.emit(.{ .struct_set = .{ .ty = self.gcTyIndex(.gen), .field = gen_fld.value } });
        try self.emit(one);
        try self.emit(.@"return");
    }

    /// The source's item, or the closure in `aux` called on it.
    fn genSrcValue(self: *Emitter, call_aux: bool) !Seq {
        var c: Capture = .{};
        self.open(&c);
        if (call_aux) {
            try self.genGet(gen_fld.aux);
            try self.emit(.{ .ref_cast = self.gcTy(.closure) });
            try self.emit(.{ .local_tee = "f" });
        }
        try self.genGet(gen_fld.src);
        try self.emit(.{ .struct_get = .{ .ty = self.gcTyIndex(.gen), .field = gen_fld.value } });
        if (call_aux) try self.gcEmitIndirect("f", 1);
        return self.seal(&c, .{ .value = .anyref });
    }

    /// `if (k == kind) { <the case> }` — the case sealed from `c`.
    fn genCase(self: *Emitter, c: *Capture, kind: u32) !void {
        const seq = self.seal(c, .terminated);
        try self.emit(.{ .local_get = "k" });
        try self.emit(try self.constInt(kind));
        try self.emit(opOf(.i32, "eq"));
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = seq } } });
    }

    /// `$__gen_resume(g) -> i32` — the module's dispatch by `kind`: the
    /// derived iterators, then each generator body (`gen_kinds`).
    fn genResumeFunc(self: *Emitter) !wat.Func {
        const gi = self.gcTyIndex(.gen);
        var c: Capture = .{};
        self.open(&c);
        try self.genGet(gen_fld.kind);
        try self.emit(.{ .local_set = "k" });
        // take: the source's next item while the count lasts.
        {
            var k: Capture = .{};
            self.open(&k);
            try self.genGet(gen_fld.left);
            try self.emit(zero);
            try self.emit(opOf(.i32, "le_s"));
            var d: Capture = .{};
            self.open(&d);
            try self.emit(zero);
            try self.emit(.@"return");
            const done = self.seal(&d, .terminated);
            try self.emit(.{ .@"if" = .{ .then = .{ .seq = done } } });
            try self.emit(.{ .local_get = "g" });
            try self.genGet(gen_fld.left);
            try self.emit(one);
            try self.emit(opOf(.i32, "sub"));
            try self.emit(.{ .struct_set = .{ .ty = gi, .field = gen_fld.left } });
            try self.genStepSrcOrEnd();
            try self.genAnswer(try self.genSrcValue(false));
            try self.genCase(&k, @intFromEnum(GenKind.take));
        }
        // drop: the source's first `left` items skipped, then each one.
        {
            var k: Capture = .{};
            self.open(&k);
            var lc: Capture = .{};
            self.open(&lc);
            try self.genGet(gen_fld.left);
            try self.emit(zero);
            try self.emit(opOf(.i32, "le_s"));
            try self.emit(.{ .br_if = break_label });
            try self.emit(.{ .local_get = "g" });
            try self.genGet(gen_fld.left);
            try self.emit(one);
            try self.emit(opOf(.i32, "sub"));
            try self.emit(.{ .struct_set = .{ .ty = gi, .field = gen_fld.left } });
            try self.genStepSrcOrEnd();
            try self.emit(.{ .br = continue_label });
            const lseq = self.seal(&lc, .terminated);
            try self.emitLoopBlockPlain(lseq);
            try self.genStepSrcOrEnd();
            try self.genAnswer(try self.genSrcValue(false));
            try self.genCase(&k, @intFromEnum(GenKind.drop));
        }
        if (self.gen_map_used) {
            var k: Capture = .{};
            self.open(&k);
            try self.genStepSrcOrEnd();
            try self.genAnswer(try self.genSrcValue(true));
            try self.genCase(&k, @intFromEnum(GenKind.map));
        }
        if (self.gen_filter_used) {
            var k: Capture = .{};
            self.open(&k);
            var lc: Capture = .{};
            self.open(&lc);
            try self.genStepSrcOrEnd();
            const test_seq = try self.genSrcValue(true);
            for (test_seq.lines) |l| try self.cur.?.append(self.arena(), l);
            try self.gcUnbox(.i32);
            {
                var y: Capture = .{};
                self.open(&y);
                try self.genAnswer(try self.genSrcValue(false));
                const yes = self.seal(&y, .terminated);
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = yes } } });
            }
            try self.emit(.{ .br = continue_label });
            const lseq = self.seal(&lc, .terminated);
            try self.emitLoopBlockPlain(lseq);
            try self.emit(.@"unreachable");
            try self.genCase(&k, @intFromEnum(GenKind.filter));
        }
        for (self.gen_kinds.items, 0..) |bname, i| {
            var k: Capture = .{};
            self.open(&k);
            try self.emit(.{ .local_get = "g" });
            try self.emit(.{ .call = bname });
            try self.emit(.@"return");
            try self.genCase(&k, gen_body_base + @as(u32, @intCast(i)));
        }
        try self.emit(.@"unreachable");
        const body = self.seal(&c, .terminated);
        return self.builder().func(.{
            .name = "__gen_resume",
            .params = &.{wat.Builder.param("g", ValType.def(gi))},
            .result = .i32,
            .locals = if (self.gen_map_used or self.gen_filter_used)
                try self.builder().localLines(&.{ .{ .name = "k", .ty = .i32 }, .{ .name = "f", .ty = self.gcTy(.closure) } })
            else
                try self.builder().localLines(&.{.{ .name = "k", .ty = .i32 }}),
            .body = body,
        });
    }

    /// `x` names an `[len][e0][e1]…` blob: an array literal, or a name bound to
    /// one. Deliberately narrow — walking the layout of something else would
    /// read its first word as an element count and trap.
    fn isArrayExpr(self: *Emitter, e: ast.Expr) bool {
        // Decision 105 (144 B-128) — a generator is a handle in a GC module.
        if (self.isGenExpr(e)) return false;
        if (self.genericResultOf(e)) |a| return self.isArrayExpr(a);
        return switch (e) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| self.arr_locals.contains(self.resolveName(n)) or self.arr_globals.contains(self.resolveName(n)),
                // A record field (or tuple element) declared as an array, an
                // `Array<T>` or an eager `@Iterator<T>` / `@Stream<T>` holds
                // the `[len][e0]…` blob its initialiser built — a `stream loop`
                // stored in `Ticker(s: …)` included. `for await (t.s)` fell to
                // the unknown-iterable no-op and yielded nothing. An optional
                // field (`?T[]`) is not an array until it is unwrapped.
                .identAccess => self.elemTypeRefOf(e) != null or self.isChildrenTyped(e),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.isArrayExpr(inner.*),
                .arrayLit => true,
                else => false,
            },
            // only the annotated loop has a value, and it is an array
            .loop => |lp| lp.generator != null,
            // `try items(n)` over a `-> @Result<i32[], E>`: the payload is the
            // array. Unrecognised, `for (try items(n))` was the unknown-iterable
            // no-op and a `val xs = try items(n)` printed its address.
            .jump => if (self.tryPayloadTypeRef(e)) |t| arrayElemOfTypeRef(t) != null else false,
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    if (self.primKindAt(cc, c.loc)) |k| break :blk self.primRes(k, cc) == .arr;
                    // A slice of an array is an array; `xs[i]` is an element,
                    // which is itself an array when `xs` holds arrays.
                    if (self.indexArgs(cc)) |ix| break :blk if (ix.is_slice)
                        self.isArrayExpr(ix.recv)
                    else if ((self.indexElemShape(cc) catch null)) |s| s[0] == '[' else false;
                    if (cc.is_builtin) break :blk false;
                    if (self.resolvedCallSym(cc, c.loc)) |sym| break :blk self.fn_arr_elem.contains(sym);
                    // A function VALUE answering an array — `f(5)` over a
                    // local read from a generic record's `fn(…) -> i32[]`
                    // field: it printed the array's address.
                    if (self.valueCallTypeRef(cc)) |t| if (arrayElemOfTypeRef(t) != null) break :blk true;
                    break :blk self.fn_arr_elem.contains(cc.callee);
                },
                else => false,
            },
            else => false,
        };
    }

    /// `for (xs) { item -> … }` over the `[len][e0][e1]…` layout: a counted
    /// walk binding each element to the loop parameter. A statement (decision
    /// 105): it leaves 0, or the generator's array when `result` names one.
    fn lowerCollectionLoop(self: *Emitter, lp: anytype, result: ?[]const u8) anyerror!void {
        if (self.mode == .gc) return self.gcCollectionLoop(lp, result);
        const ra = self.reg_arena.allocator();
        const n = self.loop_seq;
        self.loop_seq += 1;
        const base = try std.fmt.allocPrint(ra, "__iter{d}", .{n});
        const cur = try std.fmt.allocPrint(ra, "__idx{d}", .{n});
        const len = try std.fmt.allocPrint(ra, "__len{d}", .{n});
        try self.declareLocal(base, .i32);
        try self.declareLocal(cur, .i32);
        try self.declareLocal(len, .i32);

        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        const elem0 = if (lp.params.len > 0) lp.params[0] else "__it";
        const elem_kind = self.elemKindOf(lp.iter.*);
        // A float element is its slot's cell: loading the slot as an i32 read
        // the float as an integer (`[2.0, 4.0, 9.0]` averaged to `1082480000`).
        const elem_ty: Repr = if (elem_kind == .f64) .f64 else .i32;
        const elem = try self.bindTargetAs(elem0, elem_ty);
        try self.declareLocal(elem, elem_ty);
        if (elem_kind == .str) try self.str_locals.put(elem, {});
        if (try self.elemIsBool(lp.iter.*)) try self.bool_locals.put(elem, {});
        if (self.elemTypeRefOf(lp.iter.*)) |et| try self.noteTypedBinder(elem, et);
        // An element that is itself a tuple or an array prints — and is read
        // — by its shape: `for ([#(1.1, 2)]) { t -> t.0 }` read the float's
        // cell as an integer word (`288`).
        try self.noteElemShape(elem, lp.iter.*);
        // `for (es) { e -> … }` binds one ELEMENT: when the elements are
        // records, `e.key` needs the record type or it reads a slot by the
        // unique-field guess and prints the field's ADDRESS (`284` for
        // `"abc"`, exit 0).
        if (self.elemRecordOf(lp.iter.*)) |r| try self.local_types.put(elem, r);

        // The loop's start; a state machine re-entering the loop keeps the
        // counters its frame restored (decision 392, `guardStart`).
        const start_lo = if (self.machine) |m| m.next else 0;
        var start: Capture = .{};
        self.open(&start);
        try self.lowerCoerced(lp.iter.*, .i32);
        try self.emit(.{ .local_set = base });
        self.installShadow(elem0, elem);
        try self.emit(.{ .local_get = base });
        try self.emitC(.{ .load = .{} }, "element count");
        try self.emit(.{ .local_set = len });
        try self.emit(zero);
        try self.emit(.{ .local_set = cur });
        try self.guardStart(&start, start_lo);

        var loop_c: Capture = .{};
        self.open(&loop_c);
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, .{ .local_get = len });
        try self.emitAt(8, opOf(.i32, "ge_s"));
        try self.emitAt(8, .{ .br_if = break_label });
        try self.emitAt(8, .{ .local_get = base });
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, try self.constInt(4));
        try self.emitAt(8, opOf(.i32, "mul"));
        try self.emitAt(8, opOf(.i32, "add"));
        try self.emitAt(8, .{ .load = .{ .offset = 4 } });
        if (elem_kind == .f64) try self.emitAt(8, .{ .load = .{ .ty = .f64 } });
        try self.emitAt(8, .{ .local_set = elem });
        try self.emitIterationBody(lp.body, lp.label);
        try self.emitAt(8, .{ .local_get = cur });
        try self.emitAt(8, one);
        try self.emitAt(8, opOf(.i32, "add"));
        try self.emitAt(8, .{ .local_set = cur });
        try self.emitAt(8, .{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);

        try self.emitLoopBlock(loop_seq, lp.label);
        if (result) |r| try self.emit(.{ .local_get = r }) else try self.emit(zero);
    }

    /// One iteration's statements. A body that `continue`s is wrapped in
    /// `(block $__next …)` so the jump lands on the step; `loop_depth` lets
    /// `break`/`continue` branch at all.
    fn emitIterationBody(self: *Emitter, body: []const ast.Stmt, label: ?[]const u8) anyerror!void {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        self.loop_depth += 1;
        defer self.loop_depth -= 1;
        // Decision 539 — a `break` or a `continue` leaves the iteration with
        // the defers it pushed run; the end of the body runs them too.
        const saved_floor = self.defer_loop_floor;
        self.defer_loop_floor = self.defer_stack.items.len;
        defer self.defer_loop_floor = saved_floor;
        try self.loop_stack.append(self.arena(), .{ .label = label, .floor = self.defer_stack.items.len });
        defer _ = self.loop_stack.pop();
        // A labelled loop's iteration sits in `(block $__lnext_<label> ...)`, so
        // a `continue :label` from an inner loop reaches its step.
        var wrap: Capture = .{};
        if (label != null) self.open(&wrap);
        try self.emitIterationInner(body);
        if (label) |l| {
            const seq = self.seal(&wrap, .none);
            try self.emitAt(8, .{ .block = .{ .kind = .block, .label = try self.loopLabel("__lnext_", l), .body = seq } });
        }
    }

    fn emitIterationInner(self: *Emitter, body: []const ast.Stmt) anyerror!void {
        const mark = self.defer_stack.items.len;
        if (!bodyContinues(body)) {
            const tail = try self.emitStmtsFrom(body, 0, false, null, true, null);
            try self.closeDefers(mark, tail);
            return;
        }
        var c: Capture = .{};
        self.open(&c);
        const tail = try self.emitStmtsFrom(body, 0, false, null, true, null);
        try self.closeDefers(mark, tail);
        const seq = self.seal(&c, .none);
        try self.emitAt(8, .{ .block = .{ .kind = .block, .label = next_label, .body = seq } });
    }

    const LoopFrame = struct { label: ?[]const u8, floor: usize };

    fn loopLabel(self: *Emitter, prefix: []const u8, label: []const u8) ![]const u8 {
        return std.fmt.allocPrint(self.reg_arena.allocator(), "{s}{s}", .{ prefix, label });
    }

    /// `break` / `continue`, bare or labelled: a bare one (or a label no
    /// enclosing loop carries) leaves the innermost loop; `:label` branches to
    /// the named loop's own blocks, out of every loop between, the defers of
    /// every iteration crossed run first.
    fn emitLoopJump(self: *Emitter, label: ?[]const u8, is_break: bool) anyerror!void {
        if (label) |l| {
            var i = self.loop_stack.items.len;
            while (i > 0) {
                i -= 1;
                const fr = self.loop_stack.items[i];
                if (fr.label) |fl| if (std.mem.eql(u8, fl, l)) {
                    try self.runDefers(fr.floor);
                    try self.emit(.{ .br = try self.loopLabel(if (is_break) "__lbrk_" else "__lnext_", l) });
                    return;
                };
            }
        }
        try self.runDefers(self.defer_loop_floor);
        try self.emit(.{ .br = if (is_break) break_label else next_label });
    }

    fn bodyContinues(body: []const ast.Stmt) bool {
        for (body) |st| if (exprContinues(st.expr)) return true;
        return false;
    }

    fn exprContinues(e: ast.Expr) bool {
        return switch (e) {
            .jump => |j| j.kind == .@"continue",
            .branch => |b| switch (b.kind) {
                .if_ => |i| bodyContinues(i.then_) or (if (i.else_) |els| bodyContinues(els) else false),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| exprContinues(inner.*),
                .case => |c| blk: {
                    // Decision 541 (2) — a block is a scope, never a closure: a
                    // `continue` in a block or in a `case` arm reaches the loop.
                    if (c.isBlock) break :blk bodyContinues(c.arms[0].body.function.kind.body);
                    for (c.arms) |arm| {
                        if (arm.body == .function) {
                            if (bodyContinues(arm.body.function.kind.body)) break :blk true;
                        } else if (exprContinues(arm.body)) break :blk true;
                    }
                    break :blk false;
                },
                else => false,
            },
            else => false,
        };
    }

    // ── self-recursion in tail position (00 · 05-wasm step 9) ────────────────
    //
    // wasm has no tail calls without the tail-call proposal, and wasmtime's
    // default does not enable it: `fn count(n, acc) { … return count(n - 1,
    // acc + 1); }` answered `count(10000, 0)` and trapped `call stack
    // exhausted` at `count(100000, 0)`, where the other three backends answer.
    // A call to the function being emitted, in `return` position and with one
    // argument per parameter, is not a call: every argument is evaluated onto
    // the stack, the parameters are re-bound from it in reverse, and `br
    // $__tail` restarts the body, which `emitFn` has wrapped in `(loop $__tail
    // (result …) …)` — one frame for any depth. Only the `return f(…)` spelling
    // is a tail call here; an implicit tail (`if (…) { acc } else { count(…) }`)
    // still lowers to `call`.

    const tail_label = "__tail";

    const TailSelf = struct {
        name: []const u8,
        /// The parameter symbols, their wasm types and their declared types,
        /// in declaration order — what a tail call re-binds.
        syms: []const []const u8,
        types: []const Repr,
        typerefs: []const ?ast.TypeRef,
    };

    /// Arm `tail_self` for `f` when its body returns a call to itself.
    fn noteSelfTailCalls(self: *Emitter, f: ast.FnDecl) !void {
        for (f.params) |p| if (std.mem.eql(u8, p.name, "self") or p.destruct != null) return;
        if (!bodyHasSelfTailCall(f.body, f.name, f.params.len)) return;
        const ra = self.reg_arena.allocator();
        const syms = try ra.alloc([]const u8, f.params.len);
        const types = try ra.alloc(Repr, f.params.len);
        const typerefs = try ra.alloc(?ast.TypeRef, f.params.len);
        for (f.params, 0..) |p, i| {
            syms[i] = try self.paramSymbol(p, i);
            types[i] = self.reprOf(p.typeRef);
            typerefs[i] = p.typeRef;
        }
        self.tail_self = .{ .name = f.name, .syms = syms, .types = types, .typerefs = typerefs };
    }

    /// `return f(a, …)` inside `fn f`: the argument list is `f`'s own.
    fn isSelfTailCall(val: ast.Expr, name: []const u8, arity: usize) bool {
        return switch (val) {
            .call => |c| switch (c.kind) {
                .call => |cc| cc.receiver == null and !cc.is_builtin and cc.trailing.len == 0 and
                    cc.args.len == arity and std.mem.eql(u8, cc.callee, name),
                else => false,
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| isSelfTailCall(inner.*, name, arity),
                else => false,
            },
            else => false,
        };
    }

    /// A `return f(…)` reachable from `body` without crossing a lambda — the
    /// arms of an `if` and the body of a loop are looked into, a closure is a
    /// function of its own.
    fn bodyHasSelfTailCall(body: []const ast.Stmt, name: []const u8, arity: usize) bool {
        for (body) |st| switch (st.expr) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| if (r) |v| if (isSelfTailCall(v.*, name, arity)) return true,
                else => {},
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| {
                    if (bodyHasSelfTailCall(i.then_, name, arity)) return true;
                    if (i.else_) |els| if (bodyHasSelfTailCall(els, name, arity)) return true;
                },
                else => {},
            },
            .loop => |lp| if (bodyHasSelfTailCall(lp.body, name, arity)) return true,
            else => {},
        };
        return false;
    }

    /// Lower `return f(args)` as the re-binding and the branch when `f` is the
    /// function being emitted; false leaves the `return` to its ordinary path.
    fn lowerSelfTailCall(self: *Emitter, val: ast.Expr) anyerror!bool {
        const ts = self.tail_self orelse return false;
        // Decision 539 — a pending `defer` runs after the call, so it is one.
        if (self.defer_stack.items.len > 0) return false;
        if (!isSelfTailCall(val, ts.name, ts.syms.len)) return false;
        const call_expr = switch (val) {
            .collection => |col| switch (col.kind) {
                .grouped => |inner| inner.*,
                else => val,
            },
            else => val,
        };
        const cc = switch (call_expr) {
            .call => |c| switch (c.kind) {
                .call => |cc| cc,
                else => unreachable,
            },
            else => unreachable,
        };
        // Every argument is evaluated before any parameter is re-bound, so
        // `count(n - 1, acc + n)` reads the old `n` in both.
        for (cc.args, 0..) |arg, i| {
            if (self.boxesInto(ts.typerefs[i], arg.value.*))
                try self.lowerBoxedInto(ts.typerefs[i], arg.value.*)
            else
                try self.lowerCoerced(arg.value.*, ts.types[i]);
        }
        var i = cc.args.len;
        while (i > 0) {
            i -= 1;
            try self.emit(.{ .local_set = ts.syms[i] });
        }
        try self.emitC(.{ .br = tail_label }, "tail call");
        self.tail_self_used = true;
        return true;
    }

    /// `(loop $__tail (result …) <body>)` — the loop head a tail call branches to.
    fn wrapTailLoop(self: *Emitter, body: Seq) !Seq {
        var c: Capture = .{};
        self.open(&c);
        try self.emit(.{ .block = .{
            .kind = .loop,
            .label = tail_label,
            .result = if (self.fn_has_result) self.vtOf(self.cur_result) else null,
            .body = body,
        } });
        return self.seal(&c, body.stack);
    }

    /// `(block $__break (loop $__continue …))` around a lowered loop body, and
    /// the labels both jumps use.
    const break_label = "__break";
    const continue_label = "__continue";
    /// The block around one iteration's body; `continue` branches out of it
    /// to the step.
    const next_label = "__next";

    fn emitLoopBlock(self: *Emitter, body: Seq, label: ?[]const u8) !void {
        var outer_c: Capture = .{};
        if (label != null) self.open(&outer_c);
        try self.emitLoopBlockPlain(body);
        if (label) |l| {
            const seq = self.seal(&outer_c, .none);
            try self.emit(.{ .block = .{ .kind = .block, .label = try self.loopLabel("__lbrk_", l), .body = seq } });
        }
    }

    fn emitLoopBlockPlain(self: *Emitter, body: Seq) !void {
        var block_c: Capture = .{};
        self.open(&block_c);
        try self.emitAt(6, .{ .block = .{
            .kind = .loop,
            .label = continue_label,
            .body = body,
        } });
        const block_seq = self.seal(&block_c, .none);
        try self.emit(.{ .block = .{
            .kind = .block,
            .label = break_label,
            .body = block_seq,
        } });
    }

    /// `while (condition) { … }` / `loop { … }` (decision 105): test the
    /// condition at the top of every iteration, leave when it is false.
    fn lowerConditionLoop(self: *Emitter, lp: anytype, result: ?[]const u8) anyerror!void {
        var loop_c: Capture = .{};
        self.open(&loop_c);
        // A state machine re-entering the loop is inside an iteration: the
        // condition held (decision 392). One holding an `await` runs.
        const cond_lo = if (self.machine) |m| m.next else 0;
        var cond_c: Capture = .{};
        self.open(&cond_c);
        try self.lowerCoerced(lp.iter.*, .i32);
        const cond = self.seal(&cond_c, .{ .value = .i32 });
        if (self.machine == null or self.awaitRange(cond_lo) != null) {
            for (cond.lines) |l| try self.cur.?.append(self.arena(), l);
        } else {
            var in_c: Capture = .{};
            self.open(&in_c);
            try self.emitC(one, "re-entering: inside an iteration");
            const inside = self.seal(&in_c, .{ .value = .i32 });
            try self.emit(.{ .local_get = sm_seek });
            try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = inside }, .@"else" = .{ .seq = cond } } });
        }
        try self.emitAt(8, opOf(.i32, "eqz"));
        try self.emitAt(8, .{ .br_if = break_label });
        try self.emitIterationBody(lp.body, lp.label);
        try self.emitAt(8, .{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);

        try self.emitLoopBlock(loop_seq, lp.label);
        if (result) |res| try self.emit(.{ .local_get = res }) else try self.emit(zero);
    }

    fn lowerRangeLoop(self: *Emitter, params: []const []const u8, body: []const ast.Stmt, r: anytype, result: ?[]const u8, label: ?[]const u8) anyerror!void {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        const param0 = if (params.len > 0) params[0] else "__i";
        const param = try self.bindTarget(param0);
        try self.declareLocal(param, .i32);

        const start_lo = if (self.machine) |m| m.next else 0;
        var start: Capture = .{};
        self.open(&start);
        try self.lowerCoerced(r.start.*, .i32);
        try self.emit(.{ .local_set = param });
        try self.guardStart(&start, start_lo);
        self.installShadow(param0, param);

        var loop_c: Capture = .{};
        self.open(&loop_c);
        if (r.end) |end| {
            // `a..b` stops at `b`; `a...b` (decision 105) runs it too.
            try self.emitAt(8, .{ .local_get = param });
            try self.lowerExpr(end.*);
            try self.emitAt(8, opOf(.i32, if (r.inclusive) "gt_s" else "ge_s"));
            try self.emitAt(8, .{ .br_if = break_label });
        }

        try self.emitIterationBody(body, label);

        try self.emitAt(8, .{ .local_get = param });
        try self.emitAt(8, one);
        try self.emitAt(8, opOf(.i32, "add"));
        try self.emitAt(8, .{ .local_set = param });
        try self.emitAt(8, .{ .br = continue_label });
        const loop_seq = self.seal(&loop_c, .terminated);

        try self.emitLoopBlock(loop_seq, label);
        if (result) |res| try self.emit(.{ .local_get = res }) else try self.emit(zero);
    }

    // ── numeric types ─────────────────────────────────────────────────────────
    //
    // Codegen is untyped, so the wasm value type of an expression is recovered
    // here: from the literal spelling, the declared type of a local/param, or
    // the callee's registered result. Every operand site then *coerces* to the
    // type the context wants. Without this a `f64` parameter fed an `f32.const`,
    // or an `i32` local assigned a float, fails validation and the whole module
    // is rejected.

    /// Best-effort wasm value type of `e`. In a GC module an expression the
    /// base answer takes for a word may be a reference (`gcReprOfExpr`).
    fn wasmTypeOf(self: *Emitter, e: ast.Expr) Repr {
        // Front 164 s2 P4 — a task is a `$task` in a GC module, whatever the
        // shape of what it settles with.
        if (self.mode == .gc and self.isTaskExpr(e)) return .{ .ref = .task };
        // Decision 105 (144 B-128) — a generator is a `$gen` handle; its
        // `toArray` the array of its items.
        if (self.mode == .gc) {
            if (self.genMethodOf(e)) |m| {
                if (m == .next) return .{ .ref = .{ .enum_ = "YieldStep" } };
                switch (m) {
                    .some, .every => return .bool,
                    .for_each => return .i32,
                    .reduce => return self.wasmTypeOf(genWalkArgs(e.call.kind.call).init.?),
                    else => {},
                }
                if (m != .to_array) return .{ .ref = .gen };
                const yitem = (self.genItemOf(e.call.kind.call.receiver.?.*) catch null) orelse {
                    self.gcGap("a toArray over a generator whose item type is not known");
                    return .i32;
                };
                return .{ .ref = .{ .arr = gcElemClassOf(yitem.repr) } };
            }
            if (e == .loop and self.isGenExpr(e)) return .{ .ref = .gen };
        }
        // What an awaited task settles with (`gcAwaitedRead`).
        if (self.mode == .gc and e == .jump and e.jump.kind == .await_ and runCallOf(e.jump.kind.await_.*) == null) {
            const op = innerClosureBlock(e.jump.kind.await_.*) orelse e.jump.kind.await_.*;
            if (self.isTaskExpr(op)) {
                const g = self.gcAwaitedRead(op) catch {
                    self.gcGap("an awaited task of no known type");
                    return .i32;
                };
                return g.repr;
            }
        }
        // Decision 150 — a `case` / `if` the checker typed a union answers
        // the `unknown` its arms are boxed into.
        if (self.mode == .gc and self.unionValueOf(e) != null) return .{ .ref = .unknown };
        const base = self.wasmTypeOfBase(e);
        if (self.mode == .gc and base == .i32) if (self.gcReprOfExpr(e)) |r| return r;
        return base;
    }

    fn wasmTypeOfBase(self: *Emitter, e: ast.Expr) Repr {
        // A string is a GC reference in a GC module (front 164 s2); in linear
        // memory it is the word its address is, which every other answer
        // below already gives it.
        if (self.mode == .gc and self.isStringExpr(e)) return Repr.string;
        if (optOperatorParts(e)) |op| if (op.bang) if (self.optInfoOf(op.cond.*)) |oi| if (oi.cell != .none) return oi.cell.ty();
        return switch (e) {
            .literal => |lit| switch (lit.kind) {
                .numberLit => |n| if (isNumericLiteral(n)) numLitType(n) else .i32,
                else => .i32,
            },
            .identifier => |id| switch (id.kind) {
                .ident => |n| blk: {
                    // A narrowed `?f64` is the `f64` its cell holds.
                    if (self.narrowed_opts.get(self.resolveName(n))) |o| {
                        if (self.mode == .gc) {
                            if (self.gcOptPayload(o)) |pr| break :blk pr;
                        } else if (o.cell != .none) break :blk o.cell.ty();
                    }
                    break :blk self.locals.get(self.resolveName(n)) orelse self.global_types.get(self.resolveName(n)) orelse .i32;
                },
                // A named record's float field reads as the `f64` its box holds.
                .identAccess => |ia| blk: {
                    if (ia.optional) break :blk .i32;
                    // A float / 64-bit tuple element reads as the value its
                    // cell holds.
                    if (tupleIndex(ia.member) != null) {
                        const el = (self.tupleElemShapeOf(e) catch null) orelse break :blk .i32;
                        break :blk shapeCell(el).ty();
                    }
                    const rty = self.recordTypeOfExpr(ia.receiver.*) orelse break :blk .i32;
                    if (self.fieldOffsetIn(rty, ia.member) == null) break :blk .i32;
                    break :blk self.fieldCellIn(rty, ia.member).ty();
                },
                else => .i32,
            },
            .unaryOp => |un| switch (un.op) {
                .neg => if (negatedMinimum(un.expr.*)) |m| m.ty else self.wasmTypeOf(un.expr.*),
                .not => .i32,
            },
            .binaryOp => |bin| switch (bin.op) {
                .eq, .ne, .lt, .gt, .lte, .gte, .@"and", .@"or" => .i32,
                // A `+` with a string operand is a concatenation — a string
                // address — whatever the other operand holds: a template is
                // `"" + hole`, and a lone float hole made it an `f64` (B-31).
                .add => if (self.isStringExpr(e)) .i32 else self.unifyNum(self.wasmTypeOf(bin.lhs.*), self.wasmTypeOf(bin.rhs.*)),
                else => self.unifyNum(self.wasmTypeOf(bin.lhs.*), self.wasmTypeOf(bin.rhs.*)),
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| self.wasmTypeOf(inner.*),
                // `emitCaseArms` emits `(if (result {cur_result}))` and coerces
                // every arm to it, so that — not `i32` — is what a `case` leaves
                // on the stack. Saying `i32` made `return case …` in an `f64` fn
                // append a second, bogus `f64.convert_i32_s`.
                .case => self.cur_result,
                else => .i32,
            },
            .branch => |b| switch (b.kind) {
                .if_ => |i| if (ifIsStatementForm(i)) .i32 else self.ifValueType(i),
                .tryCatch => |tc| blk: {
                    const cell = self.resultOkCell(tc.expr.*);
                    break :blk if (cell != .none) cell.ty() else self.cur_result;
                },
            },
            .call => |c| switch (c.kind) {
                .call => |cc| blk: {
                    // `xs[i]` over a float array reads the `f64` its slot's cell holds
                    if (self.indexArgs(cc)) |ix|
                        break :blk if (!ix.is_slice and self.isArrayExpr(ix.recv) and
                            self.elemKindOf(ix.recv) == .f64) .f64 else .i32;
                    if (cc.is_builtin) {
                        // `o.unwrapOr(d)` over a `?f64` answers its `f64`.
                        if (std.mem.eql(u8, cc.callee, "__bp_option_unwrapOr") and cc.args.len > 0) if (self.optInfoOf(cc.args[0].value.*)) |oi| if (oi.cell != .none) break :blk oi.cell.ty();
                        // `r.unwrapOr(d)` over a `@Result<f64, E>` answers its `f64`.
                        if (std.mem.eql(u8, cc.callee, "__bp_result_unwrapOr") and cc.args.len > 0) break :blk self.resultOkCell(cc.args[0].value.*).ty();
                        break :blk .i32;
                    }
                    if (self.primKindAt(cc, c.loc)) |k| {
                        // `xs.fold(init, f)` answers what its accumulator holds.
                        if (k == .array and std.mem.eql(u8, cc.callee, "fold") and cc.args.len > 0) break :blk self.wasmTypeOf(cc.args[0].value.*);
                        const res = self.primRes(k, cc);
                        break :blk if (res == .f64) .f64 else if (res == .i64) .i64 else .i32;
                    }
                    // `recv?.m()` over a record's or an enum's method is the
                    // `?R` carrier `lowerOptionalTypedMethod` leaves.
                    if (self.optionalTypedMethod(cc, c.loc) != null) break :blk .i32;
                    if (self.recordMethodSym(cc, c.loc)) |sym| {
                        if (self.fn_sigs.get(sym)) |sig| break :blk sig.result orelse .i32;
                    }
                    // A call through a function value answering a float or a
                    // 64-bit value: what its cell holds (`valueCallCells`).
                    if (cc.calleeExpr != null or (cc.receiver == null and self.locals.contains(self.resolveName(cc.callee)))) {
                        if (self.valueCallCells(cc)) |fc| if (fc.ret != .none) break :blk fc.ret.ty();
                    }
                    if (self.calleeSymbol(cc, c.loc)) |sym| {
                        if (self.fn_sigs.get(sym)) |sig| break :blk sig.result orelse .i32;
                    }
                    break :blk .i32;
                },
                else => .i32,
            },
            .useHook => |uh| self.wasmTypeOf(uh.kind.inner.*),
            // Decision 392 — what the task settles with.
            .jump => |j| switch (j.kind) {
                .await_ => |a| if (self.isTaskExpr(a.*)) self.awaitedType(a.*) else self.wasmTypeOf(a.*),
                // `try r` over a `@Result<f64, E>` answers the `f64` its cell holds.
                .try_ => |v| if (v) |inner| self.resultOkCell(inner.*).ty() else .i32,
                else => .i32,
            },
            else => .i32,
        };
    }

    /// The type two numeric operands meet in: the wider / floatier of the two.
    fn unifyNum(self: *Emitter, a: Repr, b: Repr) Repr {
        if (self.sameVal(a, b)) return a;
        if (a.isFloat() or b.isFloat()) return .f64;
        if (a.isI64() or b.isI64()) return .i64;
        return .i32;
    }

    /// Whether turning a `from` value into a `to` one may change the number:
    /// a float into an integer, an `i64` into an `i32`.
    fn lossyConversion(from: Repr, to: Repr) bool {
        if (from.isFloat() and !to.isFloat()) return true;
        return from.isI64() and to.isWord();
    }

    /// Emit the conversion opcode that turns a value of type `from` into `to`.
    fn emitConvert(self: *Emitter, from: Repr, to: Repr) anyerror!void {
        if (self.sameVal(from, to)) return;
        // A GC reference converts to nothing but itself: the lowering took a
        // value for another shape, which it has no GC form for yet.
        // A reference into an `unknown` slot is an upcast to `anyref`.
        if (self.mode == .gc and from.isRef() and to == .ref and to.ref == .unknown) return;
        // An `unknown` read as the type a test proved it (`if (x is Frame) { val f: Frame = x }`)
        // is a downcast: a cast that traps where the test was wrong.
        if (self.mode == .gc and from == .ref and from.ref == .unknown and to == .ref) switch (to.ref) {
            .record, .str, .bytes, .arr, .tuple, .result, .closure => {
                try self.emit(.{ .ref_cast = self.vtOf(to) });
                return;
            },
            .enum_ => return,
            else => {},
        };
        // A scalar into an `unknown` slot (a type parameter's, a generic
        // field's) goes in its box; read out of one where its type is known,
        // it is unboxed (front 164 s2 P2b).
        if (self.mode == .gc and !from.isRef() and to == .ref and to.ref == .unknown) return self.gcBox(from);
        if (self.mode == .gc and from == .ref and from.ref == .unknown and !to.isRef()) return self.gcUnbox(to);
        if (self.mode == .gc and (from.isRef() or to.isRef())) {
            if (gc_debug) {
                std.debug.print("GCCONV {s} -> {s}\n", .{ from.name(), to.name() });
                if (std.c.getenv("GCTRACE") != null) std.debug.dumpCurrentStackTrace(.{});
            }
            return self.gcFail("convert ref");
        }
        // A float or an `i64` asked for as a narrower word: `lowerCoerced`
        // refuses it at the expression; a conversion with none (a body's
        // tail, a function value's answer) is refused at its statement.
        if (lossyConversion(from, to))
            return self.refuse(self.stmt_loc, "the wasm backend would narrow an `{s}` value to an `{s}` slot it does not fit", .{ from.name(), to.name() });
        const opcode: ?[]const u8 = switch (to.num()) {
            .f64 => if (from.isI64()) "f64.convert_i64_s" else "f64.convert_i32_s",
            .i64 => if (from.isFloat()) "i64.trunc_f64_s" else "i64.extend_i32_s",
            .i32 => if (from.isFloat()) "i32.trunc_f64_s" else "i32.wrap_i64",
            else => null,
        };
        if (opcode) |o| try self.emit(.{ .convert = o });
    }

    /// Lower `e` and convert the result to `want`.
    fn lowerCoerced(self: *Emitter, e: ast.Expr, want: Repr) anyerror!void {
        const prev_want = self.gc_want;
        self.gc_want = want;
        defer self.gc_want = prev_want;
        // `null` into a slot a GC module holds as a reference: a null reference.
        if (self.mode == .gc and want.isRef() and isNullLit(e)) return self.emit(self.zeroOf(want));
        // `@panic(…)` / `@todo()` stand wherever a value of any type is wanted:
        // the call ends in `unreachable`, so nothing converts or follows it.
        if (self.mode == .gc and isNoReturnCall(e)) return self.lowerExpr(e);
        // A `return` / `throw` / `break` / `continue` leaves: nothing follows it.
        if (self.mode == .gc and e == .jump) switch (e.jump.kind) {
            .@"return", .throw_, .@"break", .@"continue" => return self.lowerValue(e),
            else => {},
        };
        const from = self.wasmTypeOf(e);
        // A float or an `i64` asked for as a narrower word would be truncated
        // or wrapped (`i32.trunc_f64_s`, `i32.wrap_i64`) — a different number
        // at exit 0. The language converts by a call it names (`toInt`), never
        // by flowing a value into a slot; where this backend has no wider slot
        // for the value, it refuses.
        if (lossyConversion(from, want))
            return self.refuse(e.getLoc(), "the wasm backend would narrow this `{s}` value to an `{s}` slot it does not fit", .{ from.name(), want.name() });
        try self.lowerValue(e);
        try self.emitConvert(from, want);
    }

    /// The print shape both sides of an `==` share when both are tuples of the
    /// same shape — the one case this backend can compare element by element
    /// without a run-time walk, because the shape is static (`(is)` for
    /// `#(1, "a")`). `null` when either side has no shape, when they differ, or
    /// when the shape holds an array (`[X` has no closing code, and an array's
    /// length is only known at run time).
    fn tupleEqShape(self: *Emitter, lhs: ast.Expr, rhs: ast.Expr) anyerror!?[]const u8 {
        const ls = try self.printShapeOf(lhs) orelse return null;
        const rs = try self.printShapeOf(rhs) orelse return null;
        if (ls.len == 0 or ls[0] != '(') return null;
        if (!std.mem.eql(u8, ls, rs)) return null;
        if (std.mem.indexOfScalar(u8, ls, '[') != null) return null;
        return ls;
    }

    /// Leave `1`/`0` for "the tuples at `a` and `b` are equal", by the shape
    /// starting at `shape[start]` (a `(`). Answers the index past its `)`.
    /// Each element is compared by its own code: `i`/`b` as an `i32`, `f` as
    /// the `f64` the slot's cell holds, `s` through `$__str_eq` — a string
    /// element is a pointer, so comparing the words would compare addresses —
    /// and `(` by recursing through the pointer the slot holds.
    fn emitTupleEq(self: *Emitter, a: []const u8, b: []const u8, shape: []const u8, start: usize) anyerror!usize {
        var i = start + 1;
        var slot: u32 = 0;
        var first = true;
        while (i < shape.len and shape[i] != ')') {
            const off: u32 = slot * 4;
            switch (shape[i]) {
                '(' => {
                    const na = try self.declRes();
                    const nb = try self.declRes();
                    try self.emit(.{ .local_get = a });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(.{ .local_set = na });
                    try self.emit(.{ .local_get = b });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(.{ .local_set = nb });
                    i = try self.emitTupleEq(na, nb, shape, i);
                },
                'f' => {
                    try self.emit(.{ .local_get = a });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emitFromFloatSlot();
                    try self.emit(.{ .local_get = b });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emitFromFloatSlot();
                    try self.emit(.{ .call = self.floatEqSym() });
                    i += 1;
                },
                's' => {
                    try self.emit(.{ .local_get = a });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(.{ .local_get = b });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(self.builder().helper(.str_eq));
                    i += 1;
                },
                // Decision 332 — a `bigint` element: the values its blocks hold.
                'n' => {
                    try self.emit(.{ .local_get = a });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(.{ .local_get = b });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emitStdCall("bigint.compare");
                    try self.emit(opOf(.i32, "eqz"));
                    i += 1;
                },
                // A 64-bit element: the values its two cells hold.
                'l', 'u' => {
                    try self.emit(.{ .local_get = a });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emitFromCell(.i64);
                    try self.emit(.{ .local_get = b });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emitFromCell(.i64);
                    try self.emit(opOf(.i64, "eq"));
                    i += 1;
                },
                else => {
                    try self.emit(.{ .local_get = a });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(.{ .local_get = b });
                    try self.emit(.{ .load = .{ .offset = @intCast(off) } });
                    try self.emit(opOf(.i32, "eq"));
                    i += 1;
                },
            }
            if (!first) try self.emit(opOf(.i32, "and"));
            first = false;
            slot += 1;
        }
        if (first) try self.emitC(one, "an empty tuple equals an empty tuple");
        return if (i < shape.len) i + 1 else i;
    }

    // ── structural equality (decision 210) ───────────────────────────────────

    /// A primitive whose `==` keeps the instruction it always had: a scalar,
    /// a bool, a string (`$__str_eq`), an all-unit enum (its ordinal), and an
    /// optional of one (`lowerBinOp`'s own optional and null rows).
    fn eqIsPrim(self: *Emitter, t: ast.TypeRef) bool {
        return switch (t) {
            .named => |n| primKindOfName(n) != null or isScalarName(n) or isFloatTypeName(n) or
                std.mem.eql(u8, n, "bool") or std.mem.eql(u8, n, "string") or std.mem.eql(u8, n, "unknown") or
                self.isAllUnitEnum(n),
            .optional => |inner| self.eqIsPrim(inner.*),
            else => false,
        };
    }

    fn eqResolve(self: *Emitter, t: ast.TypeRef) ast.TypeRef {
        if (t.isSelf()) if (self.self_type) |st| return .{ .named = st };
        return t;
    }

    fn eqArrayElem(t: ast.TypeRef) ?ast.TypeRef {
        return switch (t) {
            .array => |inner| inner.*,
            .generic => |g| if (g.args.len == 1 and std.mem.eql(u8, g.name, "Array")) g.args[0] else null,
            else => null,
        };
    }

    /// The record or payload enum `t` names in this program.
    fn eqNominal(self: *Emitter, t: ast.TypeRef) ?[]const u8 {
        const n = switch (t) {
            .named => |n| n,
            .generic => |g| if (g.is_builtin) return null else g.name,
            else => return null,
        };
        if (self.records.contains(n)) return n;
        if (self.enums.get(n)) |vs| if (enumHasPayload(vs)) return n;
        return null;
    }

    /// A composite this backend generates an equality for.
    fn eqComposite(self: *Emitter, t0: ast.TypeRef) bool {
        const t = self.eqResolve(t0);
        if (self.eqIsPrim(t)) return false;
        if (eqArrayElem(t)) |_| return true;
        return switch (t) {
            .tuple_, .labeledTuple => true,
            .optional => |inner| self.eqComposite(inner.*),
            else => self.eqNominal(t) != null,
        };
    }

    /// The type a print shape spells (`i`, `f`, `b`, `s`, `[X`, `(XY…)`), or
    /// null for a shape that names no one type (`T`, an enum's names).
    fn eqTypeOfShape(self: *Emitter, sh: []const u8) anyerror!?ast.TypeRef {
        if (sh.len == 0) return null;
        const ar = self.arena();
        switch (sh[0]) {
            'i' => return .{ .named = "i32" },
            'f' => return .{ .named = "f64" },
            'b' => return .{ .named = "bool" },
            's' => return .{ .named = "string" },
            'l' => return .{ .named = "i64" },
            'u' => return .{ .named = "u64" },
            'n' => return .{ .named = "bigint" },
            '[' => {
                const inner = (try self.eqTypeOfShape(sh[1..])) orelse return null;
                const p = try ar.create(ast.TypeRef);
                p.* = inner;
                return .{ .array = p };
            },
            '(' => {
                var elems: std.ArrayListUnmanaged(ast.TypeRef) = .empty;
                var i: usize = 1;
                while (i < sh.len and sh[i] != ')') {
                    const n = shapeSpan(sh[i..]);
                    if (n == 0) return null;
                    try elems.append(ar, (try self.eqTypeOfShape(sh[i .. i + n])) orelse return null);
                    i += n;
                }
                return .{ .tuple_ = elems.items };
            },
            else => return null,
        }
    }

    /// The payload enum `e` is a value of: a variant constructor, a unit
    /// variant read off its enum, a call declared to answer one.
    fn eqEnumOf(self: *Emitter, e: ast.Expr) ?[]const u8 {
        switch (e) {
            .call => |c| switch (c.kind) {
                .call => |cc| {
                    if (self.callKind(cc) == .enum_ctor) {
                        if (receiverName(cc)) |rcv| if (self.enums.contains(rcv)) return rcv;
                        return self.enumOfVariant(cc.callee);
                    }
                    return self.enumReturnedBy(cc);
                },
                else => {},
            },
            .identifier => |id| switch (id.kind) {
                .identAccess => |ia| if (ia.receiver.* == .identifier and ia.receiver.identifier.kind == .ident) {
                    const en = ia.receiver.identifier.kind.ident;
                    if (self.enums.get(en)) |vs| for (vs) |v| {
                        if (std.mem.eql(u8, v.name, ia.member)) return en;
                    };
                },
                else => {},
            },
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.eqEnumOf(inner.*),
                else => {},
            },
            else => {},
        }
        return null;
    }

    /// The static type of `e` for `==`, read the way the rest of this backend
    /// reads it (`recordTypeOfExpr`, `typeRefOf`, the print shape). A
    /// primitive is answered too, because a tuple's or an array's element
    /// type is built from it. Null when nothing here says.
    fn eqTypeOf(self: *Emitter, e: ast.Expr) anyerror!?ast.TypeRef {
        if (self.genericResultOf(e)) |a| return self.eqTypeOf(a);
        const ar = self.arena();
        // A GC module's generic record or enum keeps the type arguments the
        // program wrote (`Pair<i32, string>`), which its slots are compared at.
        if (self.mode == .gc) if (self.typeRefOf(e)) |t0| if (t0 == .generic and !t0.generic.is_builtin and
            (self.record_generics.contains(t0.generic.name) or self.enum_generics.contains(t0.generic.name))) return t0;
        if (e == .identifier and e.identifier.kind == .ident) {
            if (self.eq_local_types.get(self.resolveName(e.identifier.kind.ident))) |t| return t;
        }
        if (self.recordTypeOfExpr(e)) |r| return .{ .named = r };
        if (self.eqEnumOf(e)) |en| return .{ .named = en };
        if (self.unitEnumOf(e)) |en| return .{ .named = en };
        if (self.typeRefOf(e)) |t0| {
            const t = self.eqResolve(t0);
            if (t.unionMembers() == null and (self.eqComposite(t) or self.eqIsPrim(t))) return t;
        }
        switch (e) {
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.eqTypeOf(inner.*),
                .tupleLit => |tl| {
                    const elems = try ar.alloc(ast.TypeRef, tl.elems.len);
                    for (tl.elems, elems) |el, *out| out.* = (try self.eqTypeOf(el)) orelse return null;
                    return .{ .tuple_ = elems };
                },
                .arrayLit => |al| if (al.elems.len > 0 and al.spread == null and al.spreadExpr == null) {
                    const p = try ar.create(ast.TypeRef);
                    p.* = (try self.eqTypeOf(al.elems[0])) orelse return null;
                    return .{ .array = p };
                },
                else => {},
            },
            else => {},
        }
        if (try self.printShapeOf(e)) |sh| if (try self.eqTypeOfShape(sh)) |t| return t;
        if (self.isArrayExpr(e)) {
            const p = try ar.create(ast.TypeRef);
            if (self.elemRecordOf(e)) |r| {
                p.* = .{ .named = r };
            } else p.* = .{ .named = switch (self.elemKindOf(e)) {
                .i32 => "i32",
                .f64 => "f64",
                .str => "string",
            } };
            return .{ .array = p };
        }
        if (self.isStringExpr(e)) return .{ .named = "string" };
        if (self.isBoolExpr(e)) return .{ .named = "bool" };
        if (self.wasmTypeOf(e).isFloat()) return .{ .named = "f64" };
        return switch (e) {
            .literal => |lit| switch (lit.kind) {
                .numberLit => .{ .named = "i32" },
                else => null,
            },
            .binaryOp => .{ .named = "i32" },
            .unaryOp => .{ .named = "i32" },
            else => null,
        };
    }

    /// The suffix of a per-type equality's symbol — prefix notation with each
    /// constructor's arity, so two types never share one: `Person`,
    /// `Array_Person`, `Tuple2_i32_string`, `Opt_Team`.
    fn eqMangle(self: *Emitter, t0: ast.TypeRef, out: *std.ArrayListUnmanaged(u8)) anyerror!void {
        const ar = self.reg_arena.allocator();
        const t = self.eqResolve(t0);
        if (eqArrayElem(t)) |elem| {
            try out.appendSlice(ar, "Array_");
            return self.eqMangle(elem, out);
        }
        switch (t) {
            .named => |n| try out.appendSlice(ar, n),
            .generic => |g| {
                try out.appendSlice(ar, g.name);
                for (g.args) |a| {
                    try out.append(ar, '_');
                    try self.eqMangle(a, out);
                }
            },
            .optional => |inner| {
                try out.appendSlice(ar, "Opt_");
                try self.eqMangle(inner.*, out);
            },
            .tuple_, .labeledTuple => {
                const elems = t.tupleElems().?;
                try out.print(ar, "Tuple{d}", .{elems.len});
                for (elems) |el| {
                    try out.append(ar, '_');
                    try self.eqMangle(el, out);
                }
            },
            else => try out.appendSlice(ar, "Any"),
        }
    }

    fn eqKey(self: *Emitter, t: ast.TypeRef) ![]const u8 {
        var out: std.ArrayListUnmanaged(u8) = .empty;
        try self.eqMangle(t, &out);
        return out.items;
    }

    /// `$__eq_<T>`, requested for emission once the module is lowered.
    fn eqFnFor(self: *Emitter, t0: ast.TypeRef) ![]const u8 {
        const t = self.eqResolve(t0);
        const sym = try std.fmt.allocPrint(self.reg_arena.allocator(), "__eq_{s}", .{try self.eqKey(t)});
        if (!self.eq_requests.contains(sym)) try self.eq_requests.put(self.reg_arena.allocator(), sym, t);
        return sym;
    }

    /// Decision 210 — `==` / `!=` over two composites of one static type
    /// calls that type's `$__eq_<T>`; two different nominal types are never
    /// equal (both operands still run). False when neither side is a
    /// composite this backend generates an equality for: the caller's rows
    /// below answer it as before.
    fn lowerStructuralEq(self: *Emitter, negate: bool, lhs: ast.Expr, rhs: ast.Expr) anyerror!bool {
        const lt = try self.eqTypeOf(lhs);
        const rt = try self.eqTypeOf(rhs);
        const l_comp = if (lt) |t| self.eqComposite(t) else false;
        const r_comp = if (rt) |t| self.eqComposite(t) else false;
        if (!l_comp and !r_comp) return false;
        // A primitive against a composite: two types, never equal.
        const t: ast.TypeRef = blk: {
            if (l_comp and r_comp) {
                if (std.mem.eql(u8, try self.eqKey(lt.?), try self.eqKey(rt.?))) break :blk lt.?;
                // A tuple literal against a tuple of the same arity: the
                // checker typed the literal by the other operand, so its
                // integers take the other side's widths (`#(5, true)` against
                // a `#(u64, bool)`). Compared by their own types the two were
                // never equal — `false` at exit 0.
                if (try self.lowerTupleEqAgainst(negate, lhs, lt.?, rhs, rt.?)) return true;
            } else if ((l_comp and rt == null) or (r_comp and lt == null)) {
                // The other side's type is not recovered here; the checker
                // accepted the comparison, so it is the recovered side's.
                break :blk if (l_comp) lt.? else rt.?;
            }
            try self.lowerCoerced(lhs, self.wasmTypeOf(lhs));
            try self.emit(.drop);
            try self.lowerCoerced(rhs, self.wasmTypeOf(rhs));
            try self.emit(.drop);
            try self.emitC(if (negate) one else zero, "two different types are never equal (decision 210)");
            return true;
        };
        const sym = try self.eqFnFor(t);
        const want: Repr = if (self.mode == .gc) self.reprOf(t) else .i32;
        try self.lowerCoerced(lhs, want);
        try self.lowerCoerced(rhs, want);
        try self.emit(.{ .call = sym });
        if (negate) try self.emit(opOf(.i32, "eqz"));
        return true;
    }

    /// `#(…) == t` / `t == #(…)` where `t`'s tuple type has the literal's
    /// arity: the literal is built with `t`'s element types and both sides
    /// compared by `t`'s `$__eq_<T>`. False when neither side is such a pair.
    fn lowerTupleEqAgainst(self: *Emitter, negate: bool, lhs: ast.Expr, lt: ast.TypeRef, rhs: ast.Expr, rt: ast.TypeRef) anyerror!bool {
        const lit_left = tupleLitElems(lhs) != null;
        const lit = tupleLitElems(if (lit_left) lhs else rhs) orelse return false;
        const t = if (lit_left) rt else lt;
        const elems = t.tupleElems() orelse return false;
        if (elems.len != lit.len or tupleLitElems(if (lit_left) rhs else lhs) != null) return false;
        const sym = try self.eqFnFor(t);
        if (lit_left) {
            try self.lowerTupleLitAs(.{ .elems = lit }, elems);
            try self.lowerCoerced(rhs, .i32);
        } else {
            try self.lowerCoerced(lhs, .i32);
            try self.lowerTupleLitAs(.{ .elems = lit }, elems);
        }
        try self.emit(.{ .call = sym });
        if (negate) try self.emit(opOf(.i32, "eqz"));
        return true;
    }

    /// The elements of a tuple literal, through parentheses.
    fn tupleLitElems(e: ast.Expr) ?[]ast.Expr {
        return switch (e) {
            .collection => |col| switch (col.kind) {
                .tupleLit => |tl| tl.elems,
                .grouped => |inner| tupleLitElems(inner.*),
                else => null,
            },
            else => null,
        };
    }

    /// Where a compared value is read from: `base` (+ `4 + idx * 4` for an
    /// array element) at `off`.
    const EqAddr = struct { base: []const u8, off: u32 = 0, idx: ?[]const u8 = null };

    /// How the address of a compared value reaches a float or an `i64`: a
    /// record `field` holds the address of either's cell; a tuple element, a
    /// variant payload and an array element are a `word` slot holding a
    /// float's cell (an `i64` there is only ever an `i32` word; a tuple's
    /// slot holds its cell and is compared as a `field`); an optional's box
    /// IS the `cell`.
    const EqSlot = enum { field, word, cell };

    fn eqPushAddr(self: *Emitter, a: EqAddr) !void {
        try self.emit(.{ .local_get = a.base });
        if (a.idx) |i| {
            try self.emit(try self.constInt(4));
            try self.emit(opOf(.i32, "add"));
            try self.emit(.{ .local_get = i });
            try self.emit(try self.constInt(4));
            try self.emit(opOf(.i32, "mul"));
            try self.emit(opOf(.i32, "add"));
        }
    }

    /// Leave `1` / `0` for "the values at `a` and `b`, of type `t`, are
    /// equal" — a primitive by its own instruction, a composite by its
    /// `$__eq_<T>`.
    fn emitValueEq(self: *Emitter, t0: ast.TypeRef, slot: EqSlot, a: EqAddr, b: EqAddr) anyerror!void {
        const t = self.eqResolve(t0);
        const n: []const u8 = switch (t) {
            .named => |x| x,
            else => "",
        };
        if (std.mem.eql(u8, n, "string")) {
            try self.eqPushAddr(a);
            try self.emit(.{ .load = .{ .offset = a.off } });
            try self.eqPushAddr(b);
            try self.emit(.{ .load = .{ .offset = b.off } });
            try self.emit(self.builder().helper(.str_eq));
            return;
        }
        // Decision 332 — a `bigint` slot is its block's address: equal when
        // the values are (std-wasm's `bigint.compare`), never by the addresses.
        if (std.mem.eql(u8, n, "bigint")) {
            try self.eqPushAddr(a);
            try self.emit(.{ .load = .{ .offset = a.off } });
            try self.eqPushAddr(b);
            try self.emit(.{ .load = .{ .offset = b.off } });
            try self.emitStdCall("bigint.compare");
            try self.emit(opOf(.i32, "eqz"));
            return;
        }
        if (fieldCellOf(n) == .i64 and slot != .word) {
            for ([_]EqAddr{ a, b }) |x| {
                try self.eqPushAddr(x);
                if (slot == .field) {
                    try self.emit(.{ .load = .{ .offset = x.off } });
                    try self.emit(.{ .load = .{ .ty = .i64 } });
                } else try self.emit(.{ .load = .{ .ty = .i64, .offset = x.off } });
            }
            try self.emit(opOf(.i64, "eq"));
            return;
        }
        if (isFloatTypeName(n)) {
            // The composite compare of a float is the bare float `==` —
            // decision 214's total order (`$__f64_eq`).
            for ([_]EqAddr{ a, b }) |x| {
                try self.eqPushAddr(x);
                switch (slot) {
                    .field, .word => {
                        try self.emit(.{ .load = .{ .offset = x.off } });
                        try self.emitFromFloatSlot();
                    },
                    .cell => try self.emit(.{ .load = .{ .ty = .f64, .offset = x.off } }),
                }
            }
            try self.emit(.{ .call = self.floatEqSym() });
            return;
        }
        if (self.eqComposite(t)) {
            const sym = try self.eqFnFor(t);
            try self.eqPushAddr(a);
            try self.emit(.{ .load = .{ .offset = a.off } });
            try self.eqPushAddr(b);
            try self.emit(.{ .load = .{ .offset = b.off } });
            try self.emit(.{ .call = sym });
            return;
        }
        if (t == .optional) {
            // A boxed scalar: equal when both are absent, or both present
            // with equal payload words.
            const sym = try self.eqFnFor(t);
            try self.eqPushAddr(a);
            try self.emit(.{ .load = .{ .offset = a.off } });
            try self.eqPushAddr(b);
            try self.emit(.{ .load = .{ .offset = b.off } });
            try self.emit(.{ .call = sym });
            return;
        }
        // An integer, a bool, an all-unit enum's ordinal — and a field this
        // backend has no type for (a type parameter's), compared as the word.
        try self.eqPushAddr(a);
        try self.emit(.{ .load = .{ .offset = a.off } });
        try self.eqPushAddr(b);
        try self.emit(.{ .load = .{ .offset = b.off } });
        try self.emit(opOf(.i32, "eq"));
    }

    /// Front 164 s2 P2 — with two values of type `t0` on the stack (the left
    /// one below), leaves `1` when they are equal: a string by content, a
    /// float by decision 214's order, an integer, a bool and an all-unit
    /// enum's ordinal by the word, a composite by its `$__eq_<T>`.
    fn gcEqValues(self: *Emitter, t0: ast.TypeRef) anyerror!void {
        const t = self.eqResolve(t0);
        const n: []const u8 = switch (t) {
            .named => |x| x,
            else => "",
        };
        if (std.mem.eql(u8, n, "string")) return self.emit(self.builder().helper(.str_eq));
        if (std.mem.eql(u8, n, "bigint") or std.mem.eql(u8, n, "unknown")) return self.gcFail("an equality over bigint or unknown");
        if (fieldCellOf(n) == .i64) return self.emit(opOf(.i64, "eq"));
        if (isFloatTypeName(n)) return self.emit(.{ .call = self.floatEqSym() });
        if (self.eqComposite(t)) return self.emit(.{ .call = try self.eqFnFor(t) });
        if (t == .optional) return self.emit(.{ .call = try self.eqFnFor(t) });
        return self.emit(opOf(.i32, "eq"));
    }

    /// Front 164 s2 P2 — `$__eq_<T>(a, b)` in a GC module: a record by its
    /// fields in order, a payload enum by its variant and then its payload;
    /// `0` at the first difference.
    fn gcEqFunc(self: *Emitter, sym: []const u8, t: ast.TypeRef) anyerror!wat.Func {
        if (eqArrayElem(t)) |elem| return self.gcEqElems(sym, t, elem, null);
        switch (t) {
            .tuple_, .labeledTuple => return self.gcEqElems(sym, t, null, t.tupleElems().?),
            .optional => |inner| return self.gcEqOptional(sym, t, inner.*),
            else => {},
        }
        const name = self.eqNominal(t) orelse return self.gcFail("an equality over a type with no struct");
        const vt = self.vtOf(self.reprOf(t));
        var c: Capture = .{};
        self.open(&c);
        if (self.records.get(name)) |fields| {
            const trefs = self.record_field_typerefs.get(name) orelse &.{};
            const gps = self.record_generics.get(name) orelse &.{};
            const written = gps.len == 0 or (t == .generic and t.generic.args.len == gps.len);
            const ti = self.gcTyIndex(.{ .record = name });
            for (fields, 0..) |_, i| {
                const ft: ast.TypeRef = if (i < trefs.len) self.eqFieldType(t, gps, trefs[i]) else return self.gcFail("a field with no type");
                const erased: ?Repr = if (gps.len > 0 and mentionsGeneric(trefs[i], gps)) self.gcErasedRepr(gps, trefs[i]) else null;
                if (erased != null and !written) {
                    try self.gcEqErasedSlot(ti, @intCast(i), erased.?, null);
                    continue;
                }
                if (erased != null and trefs[i] != .named) return self.gcFail("a generic record's composite field");
                for ([_][]const u8{ "a", "b" }) |x| {
                    try self.emit(.{ .local_get = x });
                    try self.emit(.{ .struct_get = .{ .ty = ti, .field = @intCast(i) } });
                    if (erased) |e| try self.emitConvert(e, self.reprOf(ft));
                }
                try self.gcEqValues(ft);
                try self.emit(opOf(.i32, "eqz"));
                try self.eqReturnIf(zero);
            }
            try self.emit(one);
        } else {
            const variants = self.enums.get(name) orelse return self.gcFail("an equality over a type with no struct");
            const egps = self.enum_generics.get(name) orelse &.{};
            const written = egps.len == 0 or (t == .generic and t.generic.args.len == egps.len);
            for (variants) |v| {
                const ti = self.gcTyIndex(.{ .variant = .{ .en = name, .name = v.name } });
                const vv = ValType.def(ti);
                var arm: Capture = .{};
                self.open(&arm);
                try self.emit(.{ .local_get = "b" });
                try self.emit(.{ .ref_test = vv });
                try self.emit(opOf(.i32, "eqz"));
                try self.eqReturnIf(zero);
                for (v.fields, 0..) |f, i| {
                    const ft: ast.TypeRef = self.eqFieldType(t, egps, f.typeRef);
                    const erased: ?Repr = if (egps.len > 0 and mentionsGeneric(f.typeRef, egps)) self.gcErasedRepr(egps, f.typeRef) else null;
                    if (erased != null and !written) {
                        try self.gcEqErasedSlot(ti, @intCast(i), erased.?, vv);
                        continue;
                    }
                    if (erased != null and f.typeRef != .named) return self.gcFail("a generic enum's composite payload");
                    for ([_][]const u8{ "a", "b" }) |x| {
                        try self.emit(.{ .local_get = x });
                        try self.emit(.{ .ref_cast = vv });
                        try self.emit(.{ .struct_get = .{ .ty = ti, .field = @intCast(i) } });
                        if (erased) |e| try self.emitConvert(e, self.reprOf(ft));
                    }
                    try self.gcEqValues(ft);
                    try self.emit(opOf(.i32, "eqz"));
                    try self.eqReturnIf(zero);
                }
                try self.emit(one);
                try self.emit(.@"return");
                const arm_seq = self.seal(&arm, .terminated);
                try self.emit(.{ .local_get = "a" });
                try self.emit(.{ .ref_test = vv });
                try self.emit(.{ .@"if" = .{ .then = .{ .seq = arm_seq } } });
            }
            try self.emit(zero);
        }
        const body = self.seal(&c, .{ .value = .i32 });
        return try self.builder().func(.{
            .name = sym,
            .params = &.{ wat.Builder.param("a", vt), wat.Builder.param("b", vt) },
            .result = .i32,
            .body = body,
        });
    }

    /// Decision 569 — one erased slot (field `field` of struct type `ti`, a
    /// type parameter's) of a generic record or variant compared with its
    /// type arguments unwritten: the two references by `$__unk_eq`, `return 0`
    /// when they differ. `cast` is the variant's type its `anyref` operands
    /// are cast to first.
    fn gcEqErasedSlot(self: *Emitter, ti: u16, field: u32, erased: Repr, cast: ?ValType) anyerror!void {
        if (!erased.isRef()) return self.gcFail("a scalar erased slot");
        for ([_][]const u8{ "a", "b" }) |x| {
            try self.emit(.{ .local_get = x });
            if (cast) |vt| try self.emit(.{ .ref_cast = vt });
            try self.emit(.{ .struct_get = .{ .ty = ti, .field = field } });
        }
        try self.emit(.{ .call = try self.gcUnkEq() });
        try self.emit(opOf(.i32, "eqz"));
        try self.eqReturnIf(zero);
    }

    /// `$__eq_<T>` over `?inner`: two absences are equal, one is not, two
    /// payloads by their own type.
    fn gcEqOptional(self: *Emitter, sym: []const u8, t: ast.TypeRef, inner: ast.TypeRef) anyerror!wat.Func {
        const pr = self.reprOf(inner);
        const cr = gcOptRepr(pr);
        const vt = self.vtOf(self.reprOf(t));
        var c: Capture = .{};
        self.open(&c);
        try self.emit(.{ .local_get = "a" });
        try self.emit(.ref_is_null);
        try self.emit(.{ .local_get = "b" });
        try self.emit(.ref_is_null);
        try self.emit(opOf(.i32, "and"));
        try self.eqReturnIf(one);
        try self.emit(.{ .local_get = "a" });
        try self.emit(.ref_is_null);
        try self.emit(.{ .local_get = "b" });
        try self.emit(.ref_is_null);
        try self.emit(opOf(.i32, "or"));
        try self.eqReturnIf(zero);
        for ([_][]const u8{ "a", "b" }) |x| {
            try self.emit(.{ .local_get = x });
            if (!pr.isRef()) try self.gcUnbox(pr);
        }
        _ = cr;
        try self.gcEqValues(inner);
        const body = self.seal(&c, .{ .value = .i32 });
        return try self.builder().func(.{
            .name = sym,
            .params = &.{ wat.Builder.param("a", vt), wat.Builder.param("b", vt) },
            .result = .i32,
            .body = body,
        });
    }

    /// Front 164 s2 P2 — `$__eq_<T>` over an array (`elem` its element type)
    /// or a tuple (`parts` its element types): the same length, then each
    /// element by its own type.
    fn gcEqElems(self: *Emitter, sym: []const u8, t: ast.TypeRef, elem: ?ast.TypeRef, parts: ?[]const ast.TypeRef) anyerror!wat.Func {
        const r = self.reprOf(t);
        const vt = self.vtOf(r);
        const cls: Repr.Elem = if (r.isArrRef()) r.ref.arr else .any;
        const ti = self.gcTyIndex(.{ .arr = cls });
        var c: Capture = .{};
        self.open(&c);
        var locals: []const wat.Local = &.{};
        if (elem) |et| {
            const er = self.reprOf(et);
            try self.emit(.{ .local_get = "a" });
            try self.emit(.array_len);
            try self.emit(.{ .local_get = "b" });
            try self.emit(.array_len);
            try self.emit(opOf(.i32, "ne"));
            try self.eqReturnIf(zero);
            try self.emit(.{ .local_get = "a" });
            try self.emit(.array_len);
            try self.emit(.{ .local_set = "n" });
            var body: Capture = .{};
            self.open(&body);
            try self.emit(.{ .local_get = "i" });
            try self.emit(.{ .local_get = "n" });
            try self.emit(opOf(.i32, "ge_u"));
            try self.emit(.{ .br_if = "brk" });
            for ([_][]const u8{ "a", "b" }) |x| {
                try self.emit(.{ .local_get = x });
                try self.emit(.{ .local_get = "i" });
                try self.emit(.{ .array_get = .{ .ty = ti } });
                if (cls == .any) try self.gcUnbox(er);
            }
            try self.gcEqValues(et);
            try self.emit(opOf(.i32, "eqz"));
            try self.eqReturnIf(zero);
            try self.emit(.{ .local_get = "i" });
            try self.emit(one);
            try self.emit(opOf(.i32, "add"));
            try self.emit(.{ .local_set = "i" });
            try self.emit(.{ .br = "cont" });
            const loop_seq = self.seal(&body, .terminated);
            try self.gcLoop(loop_seq);
            locals = try self.arena().dupe(wat.Local, &.{ .{ .name = "n", .ty = .i32 }, .{ .name = "i", .ty = .i32 } });
        } else for (parts.?, 0..) |pt, i| {
            const pr = self.reprOf(pt);
            for ([_][]const u8{ "a", "b" }) |x| {
                try self.emit(.{ .local_get = x });
                try self.emit(try self.constInt(i));
                try self.emit(.{ .array_get = .{ .ty = ti } });
                try self.gcUnbox(pr);
            }
            try self.gcEqValues(pt);
            try self.emit(opOf(.i32, "eqz"));
            try self.eqReturnIf(zero);
        }
        try self.emit(one);
        const body = self.seal(&c, .{ .value = .i32 });
        return try self.builder().func(.{
            .name = sym,
            .params = &.{ wat.Builder.param("a", vt), wat.Builder.param("b", vt) },
            .result = .i32,
            .locals = if (locals.len == 0) &.{} else try self.gcLocals(locals),
            .body = body,
        });
    }

    /// Decision 214 — the float `==` this module calls, marked for emission
    /// (`floatEqFunc`).
    fn floatEqSym(self: *Emitter) []const u8 {
        self.float_eq_used = true;
        return "__f64_eq";
    }

    /// `$__f64_eq(a, b)`: `==` over floats as a total order (decision 214,
    /// Java's `Double.compare` and Kotlin's data class) — both NaN (any
    /// payload: NaN is canonicalised by `x != x`), or the same bit pattern, so
    /// `0.0` and `-0.0` differ. Every float this backend holds is an `f64`.
    fn floatEqFunc(self: *Emitter) !wat.Func {
        var c: Capture = .{};
        self.open(&c);
        for ([_][]const u8{ "a", "b" }) |x| {
            try self.emit(.{ .local_get = x });
            try self.emit(.{ .local_get = x });
            try self.emit(opOf(.f64, "ne"));
        }
        try self.emitC(opOf(.i32, "and"), "both NaN");
        for ([_][]const u8{ "a", "b" }) |x| {
            try self.emit(.{ .local_get = x });
            try self.emit(.{ .convert = "i64.reinterpret_f64" });
        }
        try self.emitC(opOf(.i64, "eq"), "the same bits");
        try self.emit(opOf(.i32, "or"));
        const body = self.seal(&c, .{ .value = .i32 });
        return try self.builder().func(.{
            .name = "__f64_eq",
            .params = &.{ wat.Builder.param("a", .f64), wat.Builder.param("b", .f64) },
            .result = .i32,
            .body = body,
        });
    }

    /// `(if (then i32.const <v> return))` over the condition on the stack.
    fn eqReturnIf(self: *Emitter, v: Instr) !void {
        var hit: Capture = .{};
        self.open(&hit);
        try self.emit(v);
        try self.emit(.@"return");
        const s = self.seal(&hit, .terminated);
        try self.emit(.{ .@"if" = .{ .then = .{ .seq = s, .layout = .inline_ } } });
    }

    /// One field test: the comparison, and `return 0` at the first difference.
    fn eqFieldStep(self: *Emitter, t: ast.TypeRef, slot: EqSlot, off: u32) !void {
        try self.emitValueEq(t, slot, .{ .base = "a", .off = off }, .{ .base = "b", .off = off });
        try self.emit(opOf(.i32, "eqz"));
        try self.eqReturnIf(zero);
    }

    /// A record field's declared type, its owner's type parameters written
    /// with the arguments `t` spells (`Pair<string>`), or a parameter itself
    /// when `t` spells none.
    fn eqFieldType(self: *Emitter, owner: ast.TypeRef, gps: []const ast.GenericParam, ft: ast.TypeRef) ast.TypeRef {
        _ = self;
        const args = switch (owner) {
            .generic => |g| g.args,
            else => return ft,
        };
        if (ft != .named) return ft;
        for (gps, 0..) |gp, i| if (std.mem.eql(u8, gp.name, ft.named) and i < args.len) return args[i];
        return ft;
    }

    /// `$__eq_<T>(a, b)`: `a == b` as pointers answers `1` at once; then the
    /// type's parts in order, `0` at the first difference, `1` past the last.
    fn eqFunc(self: *Emitter, sym: []const u8, t: ast.TypeRef) !wat.Func {
        // A field written `Self` is the type being compared.
        const prev_self = self.self_type;
        if (self.eqNominal(t)) |nm| self.self_type = nm;
        defer self.self_type = prev_self;
        if (self.mode == .gc) return self.gcEqFunc(sym, t);
        var c: Capture = .{};
        self.open(&c);
        var locals: []const wat.Local = &.{};
        try self.emit(.{ .local_get = "a" });
        try self.emit(.{ .local_get = "b" });
        try self.emit(opOf(.i32, "eq"));
        try self.eqReturnIf(one);
        if (eqArrayElem(t)) |elem| {
            // The same length, then each element by its own type.
            try self.emit(.{ .local_get = "a" });
            try self.emit(.{ .load = .{} });
            try self.emit(.{ .local_get = "b" });
            try self.emit(.{ .load = .{} });
            try self.emit(opOf(.i32, "ne"));
            try self.eqReturnIf(zero);
            try self.emit(.{ .local_get = "a" });
            try self.emit(.{ .load = .{} });
            try self.emit(.{ .local_set = "n" });
            var body: Capture = .{};
            self.open(&body);
            try self.emit(.{ .local_get = "i" });
            try self.emit(.{ .local_get = "n" });
            try self.emit(opOf(.i32, "ge_u"));
            try self.emit(.{ .br_if = "brk" });
            try self.emitValueEq(elem, .word, .{ .base = "a", .idx = "i" }, .{ .base = "b", .idx = "i" });
            try self.emit(opOf(.i32, "eqz"));
            try self.eqReturnIf(zero);
            try self.emit(.{ .local_get = "i" });
            try self.emit(one);
            try self.emit(opOf(.i32, "add"));
            try self.emit(.{ .local_set = "i" });
            try self.emit(.{ .br = "cont" });
            const loop_seq = self.seal(&body, .none);
            var outer: Capture = .{};
            self.open(&outer);
            try self.emit(.{ .block = .{ .kind = .loop, .label = "cont", .body = loop_seq } });
            const outer_seq = self.seal(&outer, .none);
            try self.emit(.{ .block = .{ .kind = .block, .label = "brk", .body = outer_seq } });
            try self.emit(one);
            locals = try self.arena().dupe(wat.Local, &.{ .{ .name = "n", .ty = .i32 }, .{ .name = "i", .ty = .i32 } });
        } else switch (t) {
            .optional => |inner| {
                // Absent on either side: equal only when both are (`a == b`
                // above answered two absences).
                try self.emit(.{ .local_get = "a" });
                try self.emit(opOf(.i32, "eqz"));
                try self.emit(.{ .local_get = "b" });
                try self.emit(opOf(.i32, "eqz"));
                try self.emit(opOf(.i32, "or"));
                try self.eqReturnIf(zero);
                if (self.eqComposite(inner.*) or isNamedTypeRef(inner.*, "string")) {
                    // A pointer payload: the optional is the payload.
                    try self.emitValueEqDirect(inner.*);
                } else {
                    // A box: the payload at its address.
                    try self.eqFieldStep(inner.*, .cell, 0);
                    try self.emit(one);
                }
            },
            .tuple_, .labeledTuple => {
                // A tuple's slot holds a 64-bit element's cell, as a record
                // field does (`lowerTupleLit`).
                for (t.tupleElems().?, 0..) |el, i| try self.eqFieldStep(el, .field, @intCast(i * 4));
                try self.emit(one);
            },
            else => {
                const name = self.eqNominal(t).?;
                if (self.records.get(name)) |fields| {
                    const trefs = self.record_field_typerefs.get(name) orelse &.{};
                    const gps = self.record_generics.get(name) orelse &.{};
                    for (fields, 0..) |_, i| {
                        const ft: ast.TypeRef = if (i < trefs.len) self.eqFieldType(t, gps, trefs[i]) else .{ .named = "i32" };
                        try self.eqFieldStep(ft, .field, @intCast(i * 4));
                    }
                    try self.emit(one);
                } else {
                    // A payload enum: slot 0 is the ordinal; the variant's
                    // payload follows it, one 4-byte slot per field.
                    try self.emit(.{ .local_get = "a" });
                    try self.emit(.{ .load = .{} });
                    try self.emit(.{ .local_get = "b" });
                    try self.emit(.{ .load = .{} });
                    try self.emit(opOf(.i32, "ne"));
                    try self.eqReturnIf(zero);
                    for (self.enums.get(name).?, 0..) |v, k| {
                        if (v.fields.len == 0) continue;
                        var arm: Capture = .{};
                        self.open(&arm);
                        for (v.fields, 0..) |f, i| try self.eqFieldStep(f.typeRef, .word, @intCast((i + 1) * 4));
                        const arm_seq = self.seal(&arm, .none);
                        try self.emit(.{ .local_get = "a" });
                        try self.emit(.{ .load = .{} });
                        try self.emit(try self.constInt(k));
                        try self.emit(opOf(.i32, "eq"));
                        try self.emitC(.{ .@"if" = .{ .then = .{ .seq = arm_seq } } }, v.name);
                    }
                    try self.emit(one);
                }
            },
        }
        const body = self.seal(&c, .{ .value = .i32 });
        return try self.builder().func(.{
            .name = sym,
            .params = &.{ wat.Builder.param("a", .i32), wat.Builder.param("b", .i32) },
            .result = .i32,
            .locals = if (locals.len == 0) &.{} else try self.arena().dupe([]const wat.Local, &.{locals}),
            .body = body,
        });
    }

    /// The tail of an optional's equality over a pointer payload: `a` and `b`
    /// ARE the payloads, so the payload type's own compare answers.
    fn emitValueEqDirect(self: *Emitter, inner: ast.TypeRef) !void {
        try self.emit(.{ .local_get = "a" });
        try self.emit(.{ .local_get = "b" });
        if (isNamedTypeRef(inner, "string")) {
            try self.emit(self.builder().helper(.str_eq));
        } else try self.emit(.{ .call = try self.eqFnFor(inner) });
    }

    fn lowerBinOp(self: *Emitter, op: anytype, lhs: ast.Expr, rhs: ast.Expr, loc: ast.Loc) anyerror!void {
        const Op = @TypeOf(op);
        // Decision 346 — `==` / `!=` over `Bytes` (inference records it at
        // the operator) compares the bytes, as a string's do.
        if ((op == Op.eq or op == Op.ne) and !(isNullLit(lhs) or isNullLit(rhs))) if (self.instance_lowerings.get(loc)) |il| if (il == .prim and il.prim == .bytes)
            return self.lowerStrEq(lhs, rhs, op == Op.ne);
        // `x == null` compares the carrier with 0, whatever `x` holds — a
        // string `==` would read the length word at address 0.
        if ((op == Op.eq or op == Op.ne) and (isNullLit(lhs) or isNullLit(rhs))) {
            if (self.mode == .gc) {
                // The side that is no `null` is a reference (an optional): it is
                // null, or it is not.
                const side = if (isNullLit(lhs)) rhs else lhs;
                const r = self.wasmTypeOf(side);
                if (!r.isRef()) return self.gcFail("a null compared with a value that is no reference");
                try self.lowerCoerced(side, r);
                try self.emit(.ref_is_null);
                if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
                return;
            }
            try self.lowerCoerced(lhs, .i32);
            try self.lowerCoerced(rhs, .i32);
            try self.emit(opOf(.i32, if (op == Op.eq) "eq" else "ne"));
            return;
        }
        // Decision 8 §2.3: `==` with an `unknown` operand compares by what
        // the values hold — numbers by value (`2.0 == 2`), strings by content.
        if ((op == Op.eq or op == Op.ne) and (self.isUnknownExpr(lhs) or self.isUnknownExpr(rhs))) {
            try self.lowerAsUnknown(lhs);
            try self.lowerAsUnknown(rhs);
            if (self.mode == .gc) try self.emit(.{ .call = try self.gcUnkEq() }) else try self.emit(self.builder().helper(.unknown_eq));
            if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
            return;
        }
        // Front 164 s2 P2b — two values of a type parameter in a GC module's
        // generic body: `anyref`s, compared as `unknown`s are (a number by
        // value, a string by content, anything else by identity — what the
        // one body compared as words).
        if (self.mode == .gc and (op == Op.eq or op == Op.ne)) {
            const lr = self.wasmTypeOf(lhs);
            const rr = self.wasmTypeOf(rhs);
            if (lr == .ref and lr.ref == .unknown and rr == .ref and rr.ref == .unknown) {
                try self.lowerCoerced(lhs, lr);
                try self.lowerCoerced(rhs, rr);
                try self.emit(.{ .call = try self.gcUnkEq() });
                if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
                return;
            }
        }
        // Decision 332 — a `?bigint` is its block's address or `0`: two of
        // them (or one and a `bigint`) are equal when both are absent or both
        // hold equal values (std-wasm's `bigint.equalOptional`), never by the addresses.
        if ((op == Op.eq or op == Op.ne) and (self.isOptBigintExpr(lhs) or self.isOptBigintExpr(rhs))) {
            try self.lowerValue(lhs);
            try self.lowerValue(rhs);
            try self.emitStdCall("bigint.equalOptional");
            if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
            return;
        }
        // A boxed optional against a value: equal only when present and its
        // payload is equal (`null == 0` is false, as on the other targets).
        const lopt = self.optInfoOf(lhs);
        const ropt = self.optInfoOf(rhs);
        if ((op == Op.eq or op == Op.ne) and ((lopt != null and lopt.?.boxed) != (ropt != null and ropt.?.boxed))) {
            const opt_side = if (lopt != null and lopt.?.boxed) lhs else rhs;
            const val_side = if (lopt != null and lopt.?.boxed) rhs else lhs;
            const tmp = try std.fmt.allocPrint(self.arena(), "__opt{d}", .{self.loop_seq});
            self.loop_seq += 1;
            try self.declareLocal(tmp, .i32);
            try self.lowerCoerced(opt_side, .i32);
            try self.emit(.{ .local_tee = tmp });
            var then_c: Capture = .{};
            self.open(&then_c);
            try self.emit(.{ .local_get = tmp });
            const oi = (if (lopt != null and lopt.?.boxed) lopt else ropt).?;
            try self.emitUnboxPayload(oi, "optional payload");
            if (oi.cell == .f64) {
                // decision 214's total order, as for two floats
                try self.lowerCoerced(val_side, .f64);
                try self.emit(.{ .call = self.floatEqSym() });
            } else if (oi.cell == .i64) {
                try self.lowerCoerced(val_side, .i64);
                try self.emit(opOf(.i64, "eq"));
            } else {
                try self.lowerCoerced(val_side, .i32);
                try self.emit(opOf(.i32, "eq"));
            }
            const then_seq = self.seal(&then_c, .{ .value = .i32 });
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emitC(zero, "none equals no value");
            const else_seq = self.seal(&else_c, .{ .value = .i32 });
            try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = then_seq }, .@"else" = .{ .seq = else_seq } } });
            if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
            return;
        }
        // Decision 332 — two `bigint`s (the checker allows no other pair):
        // their blocks through the group's helpers, never the ALU over the
        // two addresses.
        if ((self.isBigintAt(loc) or self.isBigintExpr(lhs) or self.isBigintExpr(rhs)) and
            !(self.isStringExpr(lhs) or self.isStringExpr(rhs)))
            return self.lowerBigintBinOp(op, lhs, rhs);
        // String operands: concatenation and comparison run through
        // linear-memory helpers rather than the numeric ALU. This used to fire
        // only for literal==literal, so `s == "yes"` compared *pointers* and
        // `a + b` added them.
        if (self.isStringExpr(lhs) or self.isStringExpr(rhs)) switch (op) {
            Op.add => return self.lowerStrConcat(lhs, rhs),
            Op.eq => return self.lowerStrEq(lhs, rhs, false),
            Op.ne => return self.lowerStrEq(lhs, rhs, true),
            else => {},
        };
        // Decision 210 — a composite compares by value through its type's
        // generated `$__eq_<T>` (`lowerStructuralEq`).
        if (op == Op.eq or op == Op.ne) if (try self.lowerStructuralEq(op == Op.ne, lhs, rhs)) return;
        // Decision 8 §6 T6 — a tuple is positional at run time and `==`
        // compares its **elements**; T5 — labels take no part. Both sides are
        // pointers into the bump heap, so `i32.eq` on them answered `false` for
        // `#(1, "a") == #(1, "a")`.
        if (op == Op.eq or op == Op.ne) {
            if (try self.tupleEqShape(lhs, rhs)) |shape| {
                const a = try self.declRes();
                const b = try self.declRes();
                try self.lowerCoerced(lhs, .i32);
                try self.emit(.{ .local_set = a });
                try self.lowerCoerced(rhs, .i32);
                try self.emit(.{ .local_set = b });
                _ = try self.emitTupleEq(a, b, shape, 0);
                if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
                return;
            }
        }
        // A boxed optional — `xs[i]`, which answers `?T` — is the address of
        // its box: added to as a number it answered `269` for `[1, 2][0] + 1`
        // at exit 0. An absent one has no number either (erlang raises,
        // commonJS reads `null` as `0`), so the operation is refused.
        if (op != Op.eq and op != Op.ne and op != Op.@"and" and op != Op.@"or") for ([_]ast.Expr{ lhs, rhs }) |side| {
            if (self.optInfoOf(side)) |oi| if (oi.boxed)
                return self.refuse(side.getLoc(), "the wasm backend has no `{s}` over an optional value (`xs[i]` answers `?T`): unwrap it first", .{@tagName(op)});
        };
        // Under WasmGC the right operand can trap (a null `ref` read), so
        // `&&` / `||` short-circuit: the right side runs only where the left
        // one did not already decide.
        if (self.mode == .gc and (op == Op.@"and" or op == Op.@"or")) {
            try self.lowerCoerced(lhs, .i32);
            var rhs_cap: Capture = .{};
            self.open(&rhs_cap);
            try self.lowerCoerced(rhs, .i32);
            const rhs_seq = self.seal(&rhs_cap, .{ .value = .i32 });
            var short: Capture = .{};
            self.open(&short);
            try self.emit(constOf(.i32, if (op == Op.@"and") "0" else "1"));
            const short_seq = self.seal(&short, .{ .value = .i32 });
            if (op == Op.@"and")
                try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = rhs_seq }, .@"else" = .{ .seq = short_seq } } })
            else
                try self.emit(.{ .@"if" = .{ .result = .i32, .then = .{ .seq = short_seq }, .@"else" = .{ .seq = rhs_seq } } });
            return;
        }
        const t0 = self.unifyNum(self.wasmTypeOf(lhs), self.wasmTypeOf(rhs));
        // Every float is compared as the `f64` the language gives it.
        const t = t0;
        try self.lowerCoerced(lhs, t);
        try self.lowerCoerced(rhs, t);
        const is_float = t.isFloat();
        // Decision 214 — `==` over floats is a total order: NaN equals NaN
        // and `0.0` differs from `-0.0`. `<`, `>`, `<=`, `>=` stay IEEE.
        if (is_float and (op == Op.eq or op == Op.ne)) {
            try self.emit(.{ .call = self.floatEqSym() });
            if (op == Op.ne) try self.emit(opOf(.i32, "eqz"));
            return;
        }
        // Decision 319 — a `u64` / `usize` holds `0 … 2^64 − 1` in its `i64`
        // carrier, so its division, remainder and order read the bits
        // unsigned: signed, `10^19 > 3` answered `false` at exit 0.
        const unsigned = t.isI64() and (self.isU64At(loc) or self.isU64Expr(lhs) or self.isU64Expr(rhs));
        const opname: ?[]const u8 = switch (op) {
            Op.add => "add",
            Op.sub => "sub",
            Op.mul => "mul",
            Op.div => if (is_float) "div" else if (unsigned) "div_u" else "div_s",
            Op.mod => if (is_float) null else if (unsigned) "rem_u" else "rem_s",
            Op.lt => if (is_float) "lt" else if (unsigned) "lt_u" else "lt_s",
            Op.gt => if (is_float) "gt" else if (unsigned) "gt_u" else "gt_s",
            Op.lte => if (is_float) "le" else if (unsigned) "le_u" else "le_s",
            Op.gte => if (is_float) "ge" else if (unsigned) "ge_u" else "ge_s",
            Op.eq => "eq",
            Op.ne => "ne",
            // wasm has no short-circuit form; `and`/`or` are bitwise on the
            // 0/1 carrier, which is the same answer for booleans.
            Op.@"and" => if (is_float) null else "and",
            Op.@"or" => if (is_float) null else "or",
        };
        if (opname) |on| {
            try self.emitArith(t, on, loc);
        } else {
            // No opcode for this pair (float `%`, float `&&`). It used to drop
            // the right operand and answer the left one at exit 0.
            return self.refuse(lhs.getLoc(), "the wasm backend has no `{s}` for `{s}` operands", .{ @tagName(op), t.name() });
        }
    }

    fn lowerNeg(self: *Emitter, inner: ast.Expr, loc: ast.Loc) anyerror!void {
        // Decision 332 — a `bigint` negates into a fresh block.
        if (self.isBigintAt(loc) or self.isBigintExpr(inner)) {
            try self.lowerValue(inner);
            return self.emitStdCall("bigint.negate");
        }
        // Decision 319 — a type's minimum written as itself: `0 - 2^63` traps
        // the checked `sub` and `2^31` alone reads as an `i64`, so the
        // negated literal is the constant.
        if (negatedMinimum(inner)) |m| return self.emit(constOf(m.ty, m.text));
        const t = self.wasmTypeOf(inner);
        if (t.isFloat()) {
            try self.lowerValue(inner);
            try self.emit(opOf(t, "neg"));
        } else {
            try self.emit(constOf(t, "0"));
            try self.lowerCoerced(inner, t);
            try self.emitArith(t, "sub", loc);
        }
    }

    /// `<t>.<op>` over the two operands on the stack — an integer `add`,
    /// `sub` or `mul` checked (`$__i32_add_chk`, …), which aborts where the
    /// result does not fit `t`: wrapped, `2147483647 + 1` answered
    /// `-2147483648` at exit 0 where commonJS and erlang answer `2147483648`.
    /// The type inference recorded at `loc` (decision 264) then checks its
    /// own range when it is narrower than `t` (`emitRangeCheck`). An integer
    /// `div` or `rem` has its divisor checked against zero (`$__i32_nz`).
    /// Each check takes its site — the message the abort writes (decision 527
    /// (3)), pushed after the operands — so the abort says where it happened
    /// and is raised, not trapped, under `attempt`.
    fn emitArith(self: *Emitter, t: Repr, on: []const u8, loc: ast.Loc) anyerror!void {
        const wide = t.isI64();
        // A `u64` / `usize` result is checked unsigned against the carrier's
        // whole 64 bits (decision 319), which is its range: no range check
        // follows.
        if (wide and self.isU64At(loc)) {
            const h: ?wat.Helper = if (std.mem.eql(u8, on, "add"))
                .u64_add_chk
            else if (std.mem.eql(u8, on, "sub"))
                .u64_sub_chk
            else if (std.mem.eql(u8, on, "mul"))
                .u64_mul_chk
            else
                null;
            if (h) |helper| {
                try self.emitCheckSite("overflow", on, wide, loc);
                return self.emit(self.builder().helper(helper));
            }
        }
        if (wide or t.isWord()) {
            const h: ?wat.Helper = if (std.mem.eql(u8, on, "add"))
                (if (wide) .i64_add_chk else .i32_add_chk)
            else if (std.mem.eql(u8, on, "sub"))
                (if (wide) .i64_sub_chk else .i32_sub_chk)
            else if (std.mem.eql(u8, on, "mul"))
                (if (wide) .i64_mul_chk else .i32_mul_chk)
            else
                null;
            if (h) |helper| {
                try self.emitCheckSite("overflow", on, wide, loc);
                try self.emit(self.builder().helper(helper));
                return self.emitRangeCheck(wide, loc, on);
            }
            // The divisor is the operand on top: checked and answered back.
            const divides = std.mem.startsWith(u8, on, "div_") or std.mem.startsWith(u8, on, "rem_");
            if (divides) if (self.instance_lowerings.get(loc)) |il| if (il == .division and il.division.range() != null) {
                try self.emitCheckSite("division by zero", on, wide, loc);
                if (std.mem.eql(u8, on, "div_s")) {
                    try self.emitCheckSite("overflow", on, wide, loc);
                    return self.emit(self.builder().helper(if (wide) .i64_divs else .i32_divs));
                }
                try self.emit(self.builder().helper(if (wide) .i64_nz else .i32_nz));
            };
        }
        try self.emit(opOf(t, on));
    }

    /// Decision 527 (3) — the site of a checked operation, on the stack: the
    /// message its abort writes, `integer <overflow | division by zero>: <op>
    /// on <type> at <file>:<line>:<col>`, as every other target writes it. The
    /// type is the one inference recorded at `loc`, else the carrier's.
    fn emitCheckSite(self: *Emitter, what: []const u8, on: []const u8, wide: bool, loc: ast.Loc) anyerror!void {
        const sym: []const u8 = if (std.mem.eql(u8, on, "add"))
            "+"
        else if (std.mem.eql(u8, on, "sub"))
            "-"
        else if (std.mem.eql(u8, on, "mul"))
            "*"
        else if (std.mem.startsWith(u8, on, "div_"))
            "/"
        else
            "%";
        const ty: []const u8 = if (self.instance_lowerings.get(loc)) |il|
            (if (il == .division) @tagName(il.division) else if (wide) "i64" else "i32")
        else if (wide) "i64" else "i32";
        const file = if (self.src_path.len > 0) self.src_path else try std.fmt.allocPrint(self.arena(), "{s}.bp", .{if (self.module_name.len > 0) self.module_name else "main"});
        try self.emitStrLit(try std.fmt.allocPrint(self.arena(), "integer {s}: {s} on {s} at {s}:{d}:{d}", .{ what, sym, ty, file, loc.line, loc.col }));
    }

    /// Whether inference typed the arithmetic operator at `loc` `u64` or
    /// `usize` — the two types whose `i64` carrier holds unsigned bits.
    fn isU64At(self: *Emitter, loc: ast.Loc) bool {
        const il = self.instance_lowerings.get(loc) orelse return false;
        if (il != .division) return false;
        return il.division == .u64 or il.division == .usize;
    }

    /// Whether `e` names a `?T` local a null test narrowed to its payload.
    fn isNarrowedName(self: *Emitter, e: ast.Expr) bool {
        const n = plainIdentName(e) orelse return false;
        return self.narrowed_opts.contains(self.resolveName(n));
    }

    /// Whether `e` is a `u64` / `usize` value: its declared type, or the
    /// type inference recorded at its operator.
    fn isU64Expr(self: *Emitter, e: ast.Expr) bool {
        switch (e) {
            .binaryOp => |bin| return self.isU64At(bin.loc),
            .collection => |col| switch (col.kind) {
                .grouped => |inner| return self.isU64Expr(inner.*),
                else => {},
            },
            else => {},
        }
        // `t.0` of a `u64` element of a tuple no type is written for.
        if (self.tupleElemShapeOf(e) catch null) |el| if (el.len == 1 and el[0] == 'u') return true;
        const tr0 = self.typeRefOf(e) orelse return false;
        // A `?u64` a null test narrowed is the `u64` its cell holds:
        // `if (o != null) { o.toString() }` wrote `-1`.
        const tr = if (tr0 == .optional and self.isNarrowedName(e)) tr0.optional.* else tr0;
        if (tr != .named) return false;
        return std.mem.eql(u8, tr.named, "u64") or std.mem.eql(u8, tr.named, "usize");
    }

    /// Decision 264 — the checked result of the integer operator at `loc`,
    /// on the stack in its carrier (`i64` when `wide`, else `i32`), checked
    /// against the range of the type inference recorded there when that
    /// range is narrower than the carrier's: `i8`, `u8`, `i16`, `u16` in an
    /// `i32`; `u32`, `u64`, `usize` in an `i64`. `127 + 1` on `i8` answered
    /// `128` and `0 - 1` on `u32` answered `-1`, both at exit 0. A `u64`
    /// lives in an `i64` here, so its range ends at the carrier's. An
    /// operator whose type was never resolved (a generic `T`) is left as the
    /// carrier's check left it.
    fn emitRangeCheck(self: *Emitter, wide: bool, loc: ast.Loc, on: []const u8) anyerror!void {
        const il = self.instance_lowerings.get(loc) orelse return;
        if (il != .division) return;
        const r = il.division.range() orelse return;
        const c_lo: i128 = if (wide) std.math.minInt(i64) else std.math.minInt(i32);
        const c_hi: i128 = if (wide) std.math.maxInt(i64) else std.math.maxInt(i32);
        const lo = @max(r.lo, c_lo);
        const hi = @min(r.hi, c_hi);
        if (lo == c_lo and hi == c_hi) return;
        const ty: Repr = if (wide) .i64 else .i32;
        try self.emit(constOf(ty, try std.fmt.allocPrint(self.arena(), "{d}", .{lo})));
        try self.emit(constOf(ty, try std.fmt.allocPrint(self.arena(), "{d}", .{hi})));
        try self.emitCheckSite("overflow", on, wide, loc);
        try self.emit(self.builder().helper(if (wide) .i64_range_chk else .i32_range_chk));
    }

    /// The plain NAMES a null test narrows — when it HOLDS (`present`), which
    /// is the then-branch of `x != null`, and when it fails, which is the else
    /// branch of `x == null`. `&&` narrows both of its halves on the holding
    /// side and `||` both of them on the failing side; only a bare name is
    /// narrowable, which is the same limit the checker draws
    /// (`o.inner != null` rebinds nothing).
    fn collectNullTestNames(self: *Emitter, cond: ast.Expr, present: bool, out: *std.ArrayListUnmanaged([]const u8)) anyerror!void {
        switch (cond) {
            .collection => |col| switch (col.kind) {
                .grouped => |inner| try self.collectNullTestNames(inner.*, present, out),
                else => {},
            },
            .binaryOp => |bin| switch (bin.op) {
                .ne, .eq => {
                    if ((bin.op == .ne) != present) return;
                    const name = if (isNullLit(bin.rhs.*))
                        plainIdentName(bin.lhs.*)
                    else if (isNullLit(bin.lhs.*))
                        plainIdentName(bin.rhs.*)
                    else
                        null;
                    if (name) |n| try out.append(self.arena(), n);
                },
                .@"and" => if (present) {
                    try self.collectNullTestNames(bin.lhs.*, true, out);
                    try self.collectNullTestNames(bin.rhs.*, true, out);
                },
                .@"or" => if (!present) {
                    try self.collectNullTestNames(bin.lhs.*, false, out);
                    try self.collectNullTestNames(bin.rhs.*, false, out);
                },
                else => {},
            },
            else => {},
        }
    }

    /// One name a branch narrowed, and which shape notes were added for it —
    /// so `dropNarrowing` restores exactly what was there, and a narrowing does
    /// not outlive its branch.
    const Narrowing = struct {
        name: []const u8,
        added_str: bool = false,
        added_bool: bool = false,
        added_rec: bool = false,
    };

    /// Mark every narrowable name of `names` as its payload for the branch
    /// about to be emitted, and answer what was marked so `dropNarrowing` can
    /// put it back. A `?string`, a `?bool` and a `?Record` also take the shape
    /// their payload has, because inside the branch every reader asks about a
    /// plain value and no longer about an optional.
    const UnknownNarrowing = struct { name: []const u8, previous: ?[]const u8, alias: ?[]const u8 = null };

    /// `if (x is i32) { … x … }` over an `unknown` `x`: inside the branch `x`
    /// IS the payload the test proved — the checker types it so (§4.1) — so
    /// the branch reads an unboxed copy (an alias `resolveName` answers),
    /// converted when the box holds the other numeric kind (`3.0` read as
    /// `3`). Written at the top of the branch the test opens.
    fn narrowUnknown(self: *Emitter, cond: ast.Expr) anyerror!?UnknownNarrowing {
        const cc = switch (cond) {
            .call => |c| switch (c.kind) {
                .call => |cc| cc,
                else => return null,
            },
            else => return null,
        };
        if (!cc.is_builtin or !std.mem.eql(u8, cc.callee, ast.is_builtin_name) or cc.args.len != 1) return null;
        if (cc.isType) |ft| if (ft == .function) return self.narrowUnknownFn(cc.args[0].value.*, ft);
        const pt = primTestOf(cc.isType orelse return null) orelse return null;
        const n0 = plainIdentName(cc.args[0].value.*) orelse return null;
        if (!self.isUnknownExpr(cc.args[0].value.*)) return null;
        const n = self.resolveName(n0);
        const alias = try std.fmt.allocPrint(self.arena(), "{s}__is{d}", .{ n0, self.alias_seq });
        self.alias_seq += 1;
        try self.declareLocal(alias, self.unkPayloadRepr(pt));
        try self.emit(.{ .local_get = n });
        try self.emitUnkPayload(pt);
        try self.emit(.{ .local_set = alias });
        if (pt == .string) try self.str_locals.put(alias, {});
        if (pt == .bool_) try self.bool_locals.put(alias, {});
        const previous = self.aliases.get(n0);
        try self.aliases.put(n0, alias);
        return .{ .name = n0, .previous = previous };
    }

    /// Decision 254 — `if (f is fn(…) -> T) { … f(…) … }` over an `unknown`
    /// `f`: inside the branch `f` is the closure cell the box holds, typed by
    /// the tested function type so a call through it answers `T`.
    fn narrowUnknownFn(self: *Emitter, subject: ast.Expr, ft: ast.TypeRef) anyerror!?UnknownNarrowing {
        const n0 = plainIdentName(subject) orelse return null;
        if (!self.isUnknownExpr(subject)) return null;
        const n = self.resolveName(n0);
        const alias = try std.fmt.allocPrint(self.arena(), "{s}__is{d}", .{ n0, self.alias_seq });
        self.alias_seq += 1;
        try self.declareLocal(alias, .i32);
        try self.emit(.{ .local_get = n });
        try self.emitC(.{ .load = .{} }, "unknown: the proven function value");
        try self.emit(.{ .local_set = alias });
        try self.local_typerefs.put(alias, ft);
        const previous = self.aliases.get(n0);
        try self.aliases.put(n0, alias);
        return .{ .name = n0, .previous = previous, .alias = alias };
    }

    fn dropUnknownNarrowing(self: *Emitter, un: ?UnknownNarrowing) void {
        const u = un orelse return;
        if (u.alias) |a| _ = self.local_typerefs.remove(a);
        if (u.previous) |p| {
            self.aliases.put(u.name, p) catch {};
        } else _ = self.aliases.remove(u.name);
    }

    fn applyNarrowing(self: *Emitter, names: []const []const u8) anyerror![]const Narrowing {
        var marked: std.ArrayListUnmanaged(Narrowing) = .empty;
        for (names) |n0| {
            const n = self.resolveName(n0);
            if (self.narrowed_opts.contains(n)) continue;
            const oi = self.opt_locals.get(n) orelse continue;
            try self.narrowed_opts.put(n, oi);
            var m: Narrowing = .{ .name = n };
            if (oi.str and !self.str_locals.contains(n)) {
                try self.str_locals.put(n, {});
                m.added_str = true;
            }
            if (oi.bool_ and !self.bool_locals.contains(n)) {
                try self.bool_locals.put(n, {});
                m.added_bool = true;
            }
            if (oi.rec) |r| if (!self.local_types.contains(n)) {
                try self.local_types.put(n, r);
                m.added_rec = true;
            };
            try marked.append(self.arena(), m);
        }
        return marked.items;
    }

    fn dropNarrowing(self: *Emitter, marked: []const Narrowing) void {
        for (marked) |m| {
            _ = self.narrowed_opts.remove(m.name);
            if (m.added_str) _ = self.str_locals.remove(m.name);
            if (m.added_bool) _ = self.bool_locals.remove(m.name);
            if (m.added_rec) _ = self.local_types.remove(m.name);
        }
    }

    const BinderFlags = struct { name: []const u8, str: bool, bool_: bool, rec: ?[]const u8 };

    fn restoreBinderFlags(self: *Emitter, bp: BinderFlags) !void {
        if (bp.str) try self.str_locals.put(bp.name, {}) else _ = self.str_locals.remove(bp.name);
        if (bp.bool_) try self.bool_locals.put(bp.name, {}) else _ = self.bool_locals.remove(bp.name);
        if (bp.rec) |r| try self.local_types.put(bp.name, r) else _ = self.local_types.remove(bp.name);
    }

    fn lowerIfExpr(self: *Emitter, i: anytype) !void {
        // F2 (Optionals tail) — distinguish statement-form `if` (both
        // branches end in void calls / valueless returns) from value-form
        // `if` (the expression yields an i32). Statement-form must NOT
        // carry `(result i32)`; otherwise wasmtime --validate rejects the
        // module because the void-tailed branches don't push a value.
        const then_void = branchIsVoid(i.then_);
        const else_void = if (i.else_) |els| branchIsVoid(els) else false;
        const as_stmt = then_void and else_void;

        // Decision 330 — `recv?.[i]`, `f?.(args)` and `x!` reach every backend
        // as an `if` over the optional with a `__bp_opt_<line>_<col>` binder
        // (`infer.inferOptionalOperator`). Lowered as it stands such an `if`
        // printed addresses: what it answers — a boxed payload, a scalar, a
        // string — is read off the link first.
        // `x!` answers the payload the binder holds, and `xs?.[k]` (or a call
        // answering an optional) the link's own optional — absence is the `0`
        // both arms agree on. A link answering a plain value (`f?.(41)` over
        // a `?fn(i32) -> i32`) is boxed as a `?T` of its type is
        // (`optLinkBoxInfo`); one whose type is not known here is refused.
        var link_box: ?OptInfo = null;
        if (i.binding) |name| if (std.mem.startsWith(u8, name, "__bp_opt_")) {
            const supported = if (i.then_.len == 1) blk: {
                const tail = i.then_[0].expr;
                if (tail == .identifier and tail.identifier.kind == .ident and std.mem.eql(u8, tail.identifier.kind.ident, name)) break :blk true;
                if (self.optInfoOf(tail) != null) break :blk true;
                link_box = self.optLinkBoxInfo(i.cond.*, tail);
                break :blk link_box != null;
            } else false;
            if (!supported) return self.refuse(i.cond.getLoc(), "the wasm backend does not lower this `?.` link: the type of what it answers is not known here (decision 330)", .{});
        };

        // `if (opt) { v -> … }`: the condition is the optional (0 = none), and
        // the arm binds `v` to its payload.
        const bind_tmp: ?[]const u8 = if (i.binding != null) blk: {
            const t = try std.fmt.allocPrint(self.arena(), "__opt{d}", .{self.loop_seq});
            self.loop_seq += 1;
            // A GC module holds the optional as the reference it is.
            try self.declareLocal(t, if (self.mode == .gc) self.wasmTypeOf(i.cond.*) else .i32);
            break :blk t;
        } else null;
        // In a state machine the condition is read back on re-entry
        // (decision 392, `lowerCondition`).
        try self.lowerCondition(i.cond.*, bind_tmp);
        // The value's own type: an arm answering a float makes the whole `if`
        // one (`ifValueType`). It was the enclosing function's result type
        // whatever the arms answered, so `val m = if (d < 0.0) { 0.0 - d }
        // else { d }` in a function answering nothing was `(if (result i32)`
        // around two `f64`s — invalid code, the module refused.
        const ty: Repr = if (as_stmt) self.cur_result else if (link_box != null) .i32 else self.ifValueType(i);
        const own_ty = !self.sameVal(ty, self.cur_result);
        const result: ?ValType = if (as_stmt) null else self.vtOf(ty);

        var then_c: Capture = .{};
        self.open(&then_c);
        // The binder is the then-arm's name only. What its payload made it (a
        // string, a bool, a record) is put back as it was when the arm ends:
        // every `a ?? b` binds the same `__bp_nullish`, and a string payload
        // left behind made the next `??` over an `i32` print as a string — a
        // trap on the integer read as a pointer.
        const binder_prev: ?BinderFlags = if (i.binding) |name| .{
            .name = name,
            .str = self.str_locals.contains(name),
            .bool_ = self.bool_locals.contains(name),
            .rec = self.local_types.get(name),
        } else null;
        // A binder of another width than a local of its name already has —
        // every `a ?? b` binds `__bp_nullish`, so `x ?? 0.0` after `n ?? 0` —
        // is a local of its own, which the arm's reads resolve to until it ends.
        var binder_alias: ?struct { name: []const u8, prev: ?[]const u8 } = null;
        if (i.binding) |bname| {
            const oi = self.optInfoOf(i.cond.*);
            const cell: Cell = if (oi) |o| o.cell else .none;
            // The binder's repr: what the payload is (a GC module), or what its cell holds.
            const bty: Repr = if (self.mode == .gc) blk: {
                const o = oi orelse return self.gcFail("a binding over a condition that is no optional");
                break :blk self.gcOptPayload(o) orelse return self.gcFail("an optional of no known payload");
            } else cell.ty();
            var name = bname;
            if (self.locals.get(bname)) |existing| if (!self.sameVal(existing, bty)) {
                name = try std.fmt.allocPrint(self.arena(), "{s}__{d}", .{ bname, self.alias_seq });
                self.alias_seq += 1;
                binder_alias = .{ .name = bname, .prev = self.aliases.get(bname) };
                try self.aliases.put(bname, name);
            };
            try self.declareLocal(name, bty);
            if (!self.sameVal(self.locals.get(name).?, bty))
                return self.refuse(i.cond.getLoc(), "the wasm backend binds `{s}` to values of two widths in one function", .{name});
            try self.emit(.{ .local_get = bind_tmp.? });
            if (oi) |o| {
                if (o.boxed) try self.emitUnboxPayload(o, "optional payload");
                if (o.str) try self.str_locals.put(name, {});
                if (o.bool_) try self.bool_locals.put(name, {});
                if (o.inner) |tr| try self.local_typerefs.put(name, tr);
                // A record payload types the binder, so `h.rest` reads the
                // declared slot rather than guessing one by the field's name
                // (`modules/field/cases/field_name_collision` answered `0` / `0`).
                const rec: ?[]const u8 = o.rec orelse if (o.inner) |tr| switch (tr) {
                    .named => |n| self.resolveRecordName(n),
                    .generic => |g| self.resolveRecordName(g.name),
                    else => null,
                } else null;
                if (rec) |r| try self.local_types.put(name, r);
            }
            try self.emit(.{ .local_set = name });
        }
        var then_names: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectNullTestNames(i.cond.*, true, &then_names);
        const then_marked = try self.applyNarrowing(then_names.items);
        const unknown_narrowed = try self.narrowUnknown(i.cond.*);
        const then_tail: Tail = if (link_box) |bx| blk: {
            const tail = i.then_[0].expr;
            if (bx.cell != .none) {
                try self.lowerCellWord(tail, bx.cell);
            } else {
                try self.lowerCoerced(tail, .i32);
                if (bx.boxed) try self.emit(self.builder().helper(.box_i32));
            }
            break :blk .value;
        } else if (own_ty) try self.emitBranchValue(i.then_, ty) else try self.emitBody(i.then_, !as_stmt);
        self.dropUnknownNarrowing(unknown_narrowed);
        self.dropNarrowing(then_marked);
        if (binder_prev) |bp| try self.restoreBinderFlags(bp);
        if (binder_alias) |ba| {
            if (ba.prev) |p| try self.aliases.put(ba.name, p) else _ = self.aliases.remove(ba.name);
        }
        const then_seq = self.seal(&then_c, self.stackOf(then_tail, ty));

        var else_seq: ?Seq = null;
        if (i.else_) |els| {
            var else_c: Capture = .{};
            self.open(&else_c);
            var else_names: std.ArrayListUnmanaged([]const u8) = .empty;
            try self.collectNullTestNames(i.cond.*, false, &else_names);
            const else_marked = try self.applyNarrowing(else_names.items);
            const else_tail = if (own_ty) try self.emitBranchValue(els, ty) else try self.emitBody(els, !as_stmt);
            self.dropNarrowing(else_marked);
            else_seq = self.seal(&else_c, self.stackOf(else_tail, ty));
        } else if (!as_stmt) {
            // A value-form `if` must fill its `(result …)` on both paths.
            var else_c: Capture = .{};
            self.open(&else_c);
            try self.emitAt(8, self.zeroOf(ty));
            else_seq = self.seal(&else_c, .{ .value = self.vtOf(ty) });
        }

        try self.emit(.{ .@"if" = .{
            .result = result,
            .then = .{ .seq = then_seq },
            .@"else" = if (else_seq) |s| .{ .seq = s } else null,
        } });
    }

    /// The type a value-form `if` answers: a float when an arm that yields a
    /// value yields one, else the enclosing result type every other value
    /// `if` has always taken (its arms are coerced to it by their context).
    fn ifValueType(self: *Emitter, i: anytype) Repr {
        var t: ?Repr = null;
        // The first arm's integer type, when no arm answers a float: an `if`
        // over two `i32`s (a bool, a digit) inside a function answering `f64`
        // was `(if (result f64)` around two `i32`s — invalid code.
        var int: ?Repr = null;
        for ([_]?[]const ast.Stmt{ i.then_, i.else_ }, 0..) |maybe, arm| {
            const body = maybe orelse continue;
            if (body.len == 0) continue;
            const last = body[ast.lastRealIndex(body)].expr;
            if (self.exprTail(last) != .value) continue;
            // The then-arm answering the binder (`a ?? b`'s `__bp_nullish`)
            // answers the payload's width, which a local of the binder's name
            // an earlier `if` declared at another width does not tell.
            const binder_read = arm == 0 and if (i.binding) |bn| if (plainIdentName(last)) |ln| std.mem.eql(u8, ln, bn) else false else false;
            const lt = if (binder_read)
                (if (self.optInfoOf(i.cond.*)) |oi| (if (self.mode == .gc) (self.gcOptPayload(oi) orelse self.wasmTypeOf(last)) else oi.cell.ty()) else self.wasmTypeOf(last))
            else
                self.wasmTypeOf(last);
            if (lt.isFloat()) {
                t = if (t) |have| self.unifyNum(have, lt) else lt;
            } else if (int == null) int = lt;
        }
        if (t) |have| return have;
        return int orelse self.cur_result;
    }

    /// One arm of an `if` whose value type is its own (`ifValueType`): the
    /// arm's tail converted to `ty`, a zero of `ty` where it yields nothing.
    fn emitBranchValue(self: *Emitter, body: []const ast.Stmt, ty: Repr) anyerror!Tail {
        const scope_mark = self.scopeMark();
        defer self.scopeRestore(scope_mark);
        if (body.len == 0) {
            try self.emit(self.zeroOf(ty));
            return .value;
        }
        if (hasDefer(body)) {
            // A `defer` of the branch: the value is converted inside the
            // panic region, the defers run after it.
            var site: BranchLast = .{ .ty = ty };
            const mark = self.defer_stack.items.len;
            const tail = try self.emitStmtsFrom(body, 0, true, ty, true, .{ .ctx = &site, .run = BranchLast.run });
            try self.closeDefers(mark, tail);
            return tail;
        }
        for (body[0..ast.lastRealIndex(body)]) |stmt| _ = try self.emitStmt(stmt, false);
        return self.branchLastStmt(body[ast.lastRealIndex(body)], ty);
    }

    const BranchLast = struct {
        ty: Repr,
        fn run(ctx: *anyopaque, em: *Emitter, stmt: ast.Stmt) anyerror!Tail {
            const self: *BranchLast = @ptrCast(@alignCast(ctx));
            return em.branchLastStmt(stmt, self.ty);
        }
    };

    /// The last statement of a branch answering `ty`.
    fn branchLastStmt(self: *Emitter, last: ast.Stmt, ty: Repr) anyerror!Tail {
        const from = self.wasmTypeOf(last.expr);
        const tail = try self.emitStmtRaw(last);
        switch (tail) {
            .none => {
                try self.emit(self.zeroOf(ty));
                return .value;
            },
            .value => {
                try self.emitConvert(from, ty);
                return .value;
            },
            .terminated => return .terminated,
        }
    }

    /// True when an if-branch body ends in a void expression (a void
    /// builtin call like `@print`/`@panic`/`@todo`, or a valueless
    /// `return`). Drives the statement-form `(if ...)` emission above.
    fn branchIsVoid(body: []const ast.Stmt) bool {
        if (body.len == 0) return true;
        const last = body[ast.lastRealIndex(body)].expr;
        return switch (last) {
            .jump => |j| switch (j.kind) {
                .@"return" => |r| r == null,
                .throw_, .@"continue" => true,
                else => false,
            },
            .call => |c| switch (c.kind) {
                .call => |cc| isVoidBuiltinCall(cc),
                else => false,
            },
            .binding => true,
            else => false,
        };
    }
};

// ── small helpers ────────────────────────────────────────────────────────────

/// A number token's wasm type. A float literal is an `f64` — the type the
/// language gives it (`1e3`, `2.5`), and the only one that holds `5e-324` or
/// `1.7976931348623157e308`; it was an `f32.const`, where the first is `0`. A
/// radix integer (`0xFE`) is an `i32` whatever letters its digits use.
/// The operand of a unary `-` that is an integer literal of magnitude `2^31`
/// or `2^63`: the minimum of `i32` / `i64` written as itself (decision 319),
/// as the constant it is. Null for any other operand.
fn negatedMinimum(e: ast.Expr) ?struct { ty: Repr, text: []const u8 } {
    if (e != .literal or e.literal.kind != .numberLit) return null;
    const n = e.literal.kind.numberLit;
    if (n.len == 0 or n[0] == '-' or n[0] == '+') return null;
    const v: i128 = if (radixOf(n)) |r| radixValue(n, r) orelse return null else blk: {
        var acc: i128 = 0;
        for (n) |c| switch (c) {
            '0'...'9' => acc = std.math.add(i128, std.math.mul(i128, acc, 10) catch return null, c - '0') catch return null,
            '_' => {},
            else => return null,
        };
        break :blk acc;
    };
    if (v == -@as(i128, std.math.minInt(i32))) return .{ .ty = .i32, .text = "-2147483648" };
    if (v == -@as(i128, std.math.minInt(i64))) return .{ .ty = .i64, .text = "-9223372036854775808" };
    return null;
}

fn numLitType(n: []const u8) Repr {
    // Decision 332 — a `bigint` literal is the address of its block.
    if (lexerMod.isBigintText(n)) return .i32;
    if (radixOf(n)) |r| {
        const v = radixValue(n, r) orelse return .i32;
        return if (v > std.math.maxInt(i32) or v < std.math.minInt(i32)) .i64 else .i32;
    }
    for (n) |c| if (c == '.' or c == 'e' or c == 'E') return .f64;
    // An integer past the `i32` range is an `i64`: as `i32.const` the text
    // `4294967295` wrapped to `-1`.
    var v: u128 = 0;
    for (n) |c| if (c >= '0' and c <= '9') {
        v = (std.math.mul(u128, v, 10) catch return .i64) + (c - '0');
    };
    return if (v > std.math.maxInt(i32)) .i64 else .i32;
}

/// The base of a radix integer token — `0x` / `0b` / `0o`, after an optional
/// sign — or null for a decimal one.
fn radixOf(n: []const u8) ?u8 {
    const body = if (n.len > 0 and (n[0] == '-' or n[0] == '+')) n[1..] else n;
    if (body.len < 3 or body[0] != '0') return null;
    return switch (body[1]) {
        'x', 'X' => 16,
        'b', 'B' => 2,
        'o', 'O' => 8,
        else => null,
    };
}

/// A radix token's value (`_` separators allowed), or null when its digits
/// are not the base's.
/// Whether the integer literal `n` (digits, `_` separators, an optional
/// `0x` / `0b` / `0o` prefix) is past `i64`'s top — which only a `u64` holds.
fn isPastI64Literal(n: []const u8) bool {
    if (n.len == 0 or n[0] == '-') return false;
    var buf: [160]u8 = undefined;
    var len: usize = 0;
    for (n) |c| if (c != '_') {
        if (len == buf.len) return false;
        buf[len] = c;
        len += 1;
    };
    const v = std.fmt.parseInt(u128, buf[0..len], 0) catch return false;
    return v > std.math.maxInt(i64);
}

/// The value of a radix integer token, up to `u64`'s top (decision 319:
/// `0xFFFF_FFFF_FFFF_FFFFul` is a `u64`, and folded to a `256` placeholder
/// when its value overflowed an `i64` here).
fn radixValue(n: []const u8, base: u8) ?i128 {
    const neg = n[0] == '-';
    const body = if (n[0] == '-' or n[0] == '+') n[1..] else n;
    var v: i128 = 0;
    var any = false;
    for (body[2..]) |c| {
        if (c == '_') continue;
        const d = std.fmt.charToDigit(c, base) catch return null;
        v = v * base + d;
        if (v > std.math.maxInt(u64)) return null;
        any = true;
    }
    if (!any) return null;
    return if (neg) -v else v;
}

/// The `const` of a numeral token: its `numLitType`, and its text as wat
/// writes it — a radix integer in decimal (wat has no `0b` / `0o`), which it
/// had been interned as a string for, so `0xFF` printed the address `256`.
fn numLitConst(arena: std.mem.Allocator, n: []const u8) !Instr {
    return constOf(numLitType(n), try numeralText(arena, n));
}

fn numeralText(arena: std.mem.Allocator, n: []const u8) ![]const u8 {
    const r = radixOf(n) orelse return n;
    return std.fmt.allocPrint(arena, "{d}", .{radixValue(n, r).?});
}

fn exprNumType(e: ast.Expr) Repr {
    return switch (e) {
        .literal => |lit| switch (lit.kind) {
            .numberLit => |n| numLitType(n),
            else => .i32,
        },
        .unaryOp => |un| switch (un.op) {
            .neg => if (negatedMinimum(un.expr.*)) |m| m.ty else exprNumType(un.expr.*),
            else => .i32,
        },
        .binaryOp => |bin| exprNumType(bin.lhs.*),
        .collection => |col| switch (col.kind) {
            .grouped => |inner| exprNumType(inner.*),
            else => .i32,
        },
        else => .i32,
    };
}

/// `Result.Ok` / `Result.Err` / `Result.Error` — how the transform writes an
/// `Ok(…)` / `Error(…)` pattern over a `@Result` subject
/// (`Env.resultPatternLocs`). Always the `@Result` variant, even where a user
/// enum declares one of those names.
fn isResultPath(name: []const u8) bool {
    if (!std.mem.startsWith(u8, name, "Result.")) return false;
    const bare = name["Result.".len..];
    return std.mem.eql(u8, bare, "Ok") or std.mem.eql(u8, bare, "Err") or std.mem.eql(u8, bare, "Error");
}
